local P = LoreForeverPacks.Begin("LoreForever_Lang_ruRU")
P.entries["quest:496"] = {n="Эликсир Страдания",s="В Мельнице Таррен аптекарь Лидон исполняет мрачное поручение Королевского фармацевтического общества — создавать смертоносные смеси против живых. Для своих жутких опытов он нанимает путников собирать животные реагенты в окрестных предгорьях.",h="В Мельнице Таррен аптекарь Лидон исполняет мрачное поручение Королевского фармацевтического общества —...",kw={"apothecary lydon","creeper ichor","elixir of suffering","gray bear tongue","hillsbrad foothills","royal apothecary society","tarren mill","аптекарь лидон","ихор ползуна","эликсир страдания","язык серого медведя","предгорья хилсбрада","королевское фармацевтическое общество","мельница таррен"},ang={["faction:Horde"]="Хотя другие союзники из Орды могут опасаться холодной жестокости биологических опытов, защита рубежа Мельницы Таррен от Южнобережья требует доверять алхимической войне Отрекшихся.",["race:Undead"]="Для агентов Отрекшихся помощь Лидону продвигает главную цель Королевского фармацевтического общества: создать разрушительное оружие, чтобы обеспечить выживание их народа среди живых людей."},sec={{t="Ядовитое предприятие",b="Мельница Таррен — военный оплот Отрекшихся в Предгорьях Хилсбрада, но также действующая исследовательская станция Королевского фармацевтического общества. Аптекарь Лидон, живущий среди живописной зелени, ненавидит нетронутую сельскую местность и мечтает увидеть людские поселения отравленными и покоренными. Для своего опытного «Эликсира Страдания» ему нужны местные биологические вещества, известные силой и ядовитостью."},{t="Сбор реагентов",b="Создание алхимических чум требует точных ингредиентов. Лидон посылает охотников в дикие земли вокруг Мельницы Таррен собрать языки местных серых медведей и редкий ихор мшистых ползунов. После очистки нечестивой алхимией эти органические жидкости становятся основой смертоносной смеси, призванной истребить живых захватчиков по всему Хилсбраду."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — член Королевского фармацевтического общества, находящийся в Мельнице Таррен. Верный алхимической традиции Отрекшихся, он ненавидит чистый, живой пейзаж Хилсбрада и посвящает время созданию сильных ядов для истребления людей.",al={"apothecary lydon","who gives elixir of suffering","lydon tarren mill","аптекарь лидон","кто дает эликсир страдания","лидон мельница таррен"}},{q="Зачем Лидону медвежьи языки и ихор ползунов?",a="Лидон исследует ядовитые убийственные вещества, чтобы сварить из них смертоносные смеси. Биологические свойства языков серых медведей и едкие выделения мшистых ползунов дают нестабильную алхимическую основу для его нового Эликсира Страдания.",al={"why bear tongues","what is creeper ichor for","elixir ingredients lore","зачем медвежьи языки","для чего ихор ползунов","ингредиенты эликсира"}},{q="Куда ведет это задание дальше?",a="Когда основные реагенты доставлены, Лидон смешивает их в пробный отвар. Затем он требует испытать смесь, чтобы измерить ее смертоносность на живых существах.",al={"next quest elixir of suffering","what happens after elixir of suffering","следующее задание эликсир страдания","что после эликсира страдания"}},{q="Какова цель Королевского фармацевтического общества в Хилсбраде?",a="Общество действует по приказу леди Сильваны Ветрокрылой, чтобы создать алхимическую чуму, способную истребить и людей, и Плеть. Мельница Таррен — удобный пограничный форпост для сбора биологического материала и испытаний образцов на местных силах Альянса.",al={"why are apothecaries in hillsbrad","forsaken poison goals","hillsbrad plague","зачем аптекари в хилсбраде","цели ядов отрекшихся","чума хилсбрада"}},{q="Где найти нужных существ?",a="Серые медведи бродят по центральным полям и лесам Предгорий Хилсбрада, а мшистые ползуны таятся в зарослях и лесистых местах у Мельницы Таррен.",al={"where are gray bears","where are moss creepers","bear and spider locations","где серые медведи","где мшистые ползуны","где медведи и пауки"}},{q="Почему Лидон в таком дурном настроении?",a="Как и многих алхимиков Отрекшихся, Лидона отвращают жизненная сила, чистый воздух и цветущая природа. Радость он находит лишь в смерти, тлении и удачной перегонке смертельных ядов.",al={"why is lydon unhappy","lydon clean air","почему лидон недоволен","лидон чистый воздух"}}},fp="19,250,18.459.0,18.369.0,24.265.0,51.247.0,32.175.1,62.274.0,43.174.0,32.179.0"}
P.entries["quest:4966"] = {n="Защитить Канати Серое Облако",s="«Защитить Канати Серое Облако» — задание Орды на Заставе Белого Плеса в Тысяче Игл. Искателей приключений предупредили, что кентавры-убийцы охотятся на тауренов Канати Серое Облако, и им предстоит встать рядом с ним и отразить нападение отряда убийц из племени Галак.",h="«Защитить Канати Серое Облако» — задание Орды на Заставе Белого Плеса в Тысяче Игл.",kw={"assassination plot","assassins","centaur","galak","kanati greycloud","thousand needles","whitereach post","заговор убийц","убийцы","кентавры","галак","канати серое облако","тысяча игл","застава белого плеса"},ang={["faction:Horde"]="Застава Белого Плеса служит важным наблюдательным пунктом в Тысяче Игл, и сохранить жизнь таким часовым, как Канати, жизненно важно для обеспечения операций Орды по всему каньону.",["race:Tauren"]="Кровная вражда между тауренами и кентаврами глубока, поэтому защита соплеменника от подлого убийства — вопрос выживания и чести."},sec={{t="Раскрытая засада",b="Находясь среди высоких песчаниковых шпилей Заставы Белого Плеса, таурен Канати Серое Облако узнает из перехваченных приказов кентавров о заговоре с целью убить именно его. Кентавры племени Галак, неустанно враждующие с кочевыми тауренами и их союзниками из Орды, не довольствуются набегами на пути снабжения: они стремятся уничтожить тех, кто селится в их каньонах."},{t="Оборона Заставы Белого Плеса",b="Поняв, что нападение неизбежно и что силы врага могут превосходить его первоначальные оценки, Канати просит путников на заставе сражаться рядом с ним. Когда убийцы Галак наносят удар, Канати стоит насмерть, полагаясь на клинки и заклинания союзников, чтобы сорвать засаду до того, как кентавры получат свою добычу."}},faq={{q="Кто такой Канати Серое Облако?",a="Канати Серое Облако — таурен, устроивший охотничий лагерь на Заставе Белого Плеса в Тысяче Игл, неподалеку от каньонов, которые местные кентавры считают своими.",al={"who is kanati","kanati greycloud lore","who is the quest giver","кто такой канати","канати серое облако предыстория","кто выдает задание"}},{q="Почему кентавры пытаются его убить?",a="Местные кентавры племени Галак считают тауренов и лагеря Орды врагами, вторгшимися на территорию их каньонов. Убив Канати, кентавры намерены избавить каньон от его охотничьего лагеря и от всех, кто мог бы последовать за ним.",al={"why do centaur attack kanati","centaur assassination reason","assassination plot why","почему кентавры нападают на канати","причина покушения кентавров","зачем заговор убийц"}},{q="Где происходит эта оборона?",a="Засада происходит прямо на Заставе Белого Плеса — небольшом форпосте Орды на каньонных тропах Тысячи Игл.",al={"where is this quest","protect kanati location","where does the ambush happen","где это задание","защитить канати местоположение","где происходит засада"}},{q="Какой клан кентавров нападает на Канати Серое Облако?",a="Убийцы принадлежат к племени Галак — самому значительному клану кентавров, населяющему каньоны и ущелья Тысячи Игл.",al={"what tribe attacks","who are the assassins","which centaur","какое племя нападает","кто такие убийцы","какие кентавры"}},{q="Что происходит после поражения убийц?",a="После гибели убийц Галак жизнь Канати спасена, а Застава Белого Плеса остается в безопасности. Канати благодарит защитников за то, что они встали рядом с ним во время внезапного нападения, и на этом цепочка обороны успешно завершается.",al={"what happens next","quest follow up","after protecting kanati","что дальше","продолжение задания","после защиты канати"}},{q="Сражается ли Канати Серое Облако в бою?",a="Да. Канати не трусит и не бежит: он сам вступает в схватку рядом с теми, кто откликнулся на его просьбу, и отбивает убийц, пришедших положить конец его дозору.",al={"does kanati help","kanati fighting","is kanati passive","помогает ли канати","канати сражается","канати пассивен"}}},fp="24,233,18.405.0,25.318.0,24.163.0,46.224.0,35.137.0,44.123.0,46.219.1,42.158.0"}
P.entries["quest:498"] = {n="Спасение",s="«Спасение» — раннее задание Орды, которое выдает Круск в Мельнице Таррен: героям предстоит проникнуть в Крепость Дарнхольд и освободить плененных орков-разведчиков. Лично отобранные Траллом разведчики попали в засаду, когда искали реликвию из прошлого Вождя, и оказались в плену у безжалостных людей-преступников из Синдиката.",h="«Спасение» — раннее задание Орды, которое выдает Круск в Мельнице Таррен: героям предстоит проникнуть в...",kw={"drull","durnholde keep","gol'dir","hillsbrad","krusk","syndicate","tarren mill","tog'thar","друлл","крепость дарнхольд","гол'дир","хилсбрад","круск","синдикат","мельница таррен","тог'тар"},ang={["class:Warrior"]="Освобождение товарищей по переднему краю из плена укрепляет воинское братство перед лицом бесчестных людей-бандитов.",["faction:Horde"]="Это задание знаменует раннюю попытку Орды противостоять расширению Синдиката на спорных холмах Лордерона.",["race:Orc"]="Вид орков-воинов в кандалах в Крепости Дарнхольд напоминает о болезненной истории лагерей, поэтому задание по их освобождению становится глубоко личным."},sec={{t="Неудачная разведка",b="Вождь Тралл отправил отборный отряд орков-воинов в Предгорья Хилсбрада с приказом тихо разузнать о растущей угрозе Синдиката и найти предмет, тесно связанный с историей Крепости Дарнхольд. Под началом Гол'дира разведчики приблизились к руинам крепости. Однако Синдикат подавил их числом, устроив засаду. Воин Круск сумел вырваться и, хромая, добрался через реку до Мельницы Таррен, а его товарищи Друлл, Тог'тар и Гол'дир были взяты живыми и закованы в цепи."},{t="Цепи в руинах",b="Дарнхольд хранит горькие воспоминания для орков: когда-то там располагалась штаб-квартира лагерей для интернированных Эдельаса Черноскала, где пленных орков доводили до апатии и обращали в рабов-гладиаторов. Вновь увидеть своих воинов закованными в железо за потрескавшимися каменными стенами Дарнхольда — невыносимое оскорбление для Орды. Чтобы освободить Друлла и Тог'тара, спасителям придется сразиться с тюремщиками Синдиката, у которых хранятся ключи от оков, а затем выяснить, что стало с их командиром-разведчиком Гол'диром."}},faq={{q="Зачем орков вообще отправили в Крепость Дарнхольд?",a="Вождь Тралл направил Гол'дира и его отряд разведчиков разузнать о бандитах Синдиката и добыть предмет из прошлого Дарнхольда, имеющий для Вождя огромное личное значение.",al={"why were they there","why durnholde","krusk mission","зачем они там были","почему дарнхольд","задание круска"}},{q="Кого нужно спасти из плена?",a="Друлл и Тог'тар — орки-разведчики, посланные Ордой под командованием Гол'дира. Бандиты Синдиката одолели их и заковали в кандалы с ядрами в руинах.",al={"who is drull","who is togthar","who are the hostages","кто такой друлл","кто такой тог'тар","кто заложники"}},{q="Где предводитель отряда, Гол'дир?",a="Когда Друлл и Тог'тар освобождены, Круск узнает, что их командира Гол'дира отделили от основной группы, и Синдикат перевез его в другое, неизвестное место.",al={"where is goldir","find goldir","what happened to goldir","где гол'дир","найти гол'дира","что случилось с гол'диром"}},{q="Кто держит разведчиков в плену?",a="Их удерживает Синдикат — аристократическая преступная сеть, действующая из руин Лордерона и Альтерака; пленных охраняют непосредственно тюремщики Синдиката в Дарнхольде.",al={"who captured them","who are the jailors","who runs durnholde","кто взял их в плен","кто такие тюремщики","кто управляет дарнхольдом"}},{q="К чему ведет эта цепочка заданий?",a="Освобождение разведчиков ведет прямо к заданию выследить Синдикат и проникнуть к нему, чтобы спасти Гол'дира, и в итоге раскрыть замыслы лорда Алидена Перенольда и найти памятную вещь Тареты Фокстон.",al={"what comes next","after the rescue","rescue chain","что дальше","после спасения","цепочка спасения"}},{q="Почему Крепость Дарнхольд имеет особое значение для Орды?",a="Дарнхольд — крепость, где Эдельас Черноскал вырастил Тралла как гладиатора и управлял системой лагерей для интернированных Альянса после Второй войны, пока Тралл не поднял восстание и не разрушил крепость.",al={"history of durnholde","why horde cares about durnholde","история дарнхольда","почему орда дорожит дарнхольдом"}}},fp="10,308,26.534.0,19.512.1,58.191.0,35.181.0,37.182.1,34.173.0,33.205.1,58.215.0"}
P.entries["quest:499"] = {n="Эликсир Страдания",s="В Мельнице Таррен аптекарь Лидон варит ядовитое зелье, которое должно послужить зловещему делу Королевского фармацевтического общества. Чтобы убедиться в его смертоносности, он приказывает немедленно испытать его на живом существе — его несчастном спутнике рядом.",h="В Мельнице Таррен аптекарь Лидон варит ядовитое зелье, которое должно послужить зловещему делу Королевского...",kw={"apothecary lydon","elixir of suffering","hillsbrad foothills","poison","royal apothecary society","tarren mill","toad","umpi","аптекарь лидон","эликсир страдания","предгорья хилсбрада","яд","королевское фармацевтическое общество","мельница таррен","жаба","ампи"},ang={["class:Druid"]="Друиду может показаться глубоко тревожным небрежное, бессердечное отравление безобидного земноводного во имя войны Отрекшихся.",["faction:Horde"]="Союзники, посещающие Мельницу Таррен, видят собственными глазами жуткие алхимические методы, которые применяет Королевское фармацевтическое общество.",["race:Undead"]="Для Отрекшихся испытание смертельных ядов — важнейшее дело в исполнении указа леди Сильваны об истреблении и Плети, и живых."},sec={{t="Ядовитое испытание",b="Аптекарь Лидон неустанно трудится в Мельнице Таррен над химическим оружием, способным исполнить великие замыслы Темной Госпожи: мором, который уничтожит и живых людей Альянса, и нежить Плети. Когда нужные реагенты собраны и настоялись, Лидон смешивает мерзкое варево в то, что называет Эликсиром Страдания, и жаждет увидеть его силу, прежде чем применять его шире."},{t="Судьба Ампи",b="Вместо того чтобы искать вражеского пленника или сбежавшего зверя, Лидон обращается к существу рядом с собой. Он велит искателю приключений дать свежесваренный яд своему помощнику Ампи — безобидной жабе, тихо сидящей у его ног. Одной дозы эликсира оказывается достаточно: земноводное гибнет на месте, и аптекарь убеждается, что его смертоносная формула действует именно так, как задумано."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — алхимик, представляющий Королевское фармацевтическое общество, живущий в поселении Отрекшихся Мельница Таррен в Предгорьях Хилсбрада. Он проводит дни за усовершенствованием ядов и алхимических смесей, призванных истребить врагов Отрекшихся.",al={"lydon","who is lydon","apothecary lydon tarren mill","лидон","кто такой лидон","аптекарь лидон мельница таррен"}},{q="Кто такой Ампи?",a="Ампи — обычная жаба, сидящая прямо возле рабочего стола аптекаря Лидона в Мельнице Таррен; Лидон в шутку назвал ее своим помощником.",al={"what is umpi","umpi the toad","who is the assistant","что такое ампи","ампи жаба","кто помощник"}},{q="Для чего нужен Эликсир Страдания?",a="Эликсир Страдания — экспериментальное химическое оружие, созданное для проверки ядовитых формул, призванных истребить и живых людей, и нежить Плети по воле леди Сильваны Ветрокрылой.",al={"what does the elixir do","why make elixir of suffering","что делает эликсир","зачем делать эликсир страдания"}},{q="Что происходит, если дать зелье Ампи?",a="Lydon asks you to give Umpi a taste to see whether the newly mixed elixir achieves its intended effect. The result is revealed during the test.",al={"does umpi die","what happens to the toad","умирает ли ампи","что случится с жабой"}},{q="Где проходит это испытание?",a="Испытание проходит в городке Отрекшихся Мельница Таррен на севере Предгорий Хилсбрада, прямо у варочной станции Лидона.",al={"where is lydon located","where do i find umpi","где находится лидон","где найти ампи"}},{q="Почему Королевское фармацевтическое общество испытывает яды на мелких животных?",a="Аптекари Отрекшихся обычно используют мелких существ и вредителей для предварительных испытаний, чтобы проверить скорость и смертоносность своих составов, прежде чем перейти к полевым испытаниям на более крупных целях или живых пленниках.",al={"why test on toads","apothecary society animal testing","зачем испытывать на жабах","опыты общества на животных"}}},fp="19,223,12.439.0,16.424.1,24.265.0,12.135.0,47.191.0,46.143.1,32.131.0,68.217.0"}
P.entries["quest:5"] = {n="Урчащий живот Трясунчика",s="Оказавшись один и в ужасе среди руин Вороньего Холма, параноидальный бродяга Трясунчик отчаянно жаждет настоящей еды после долгого питания сорняками и насекомыми. Он умоляет проходящих мимо искателей приключений отправиться на восток в Темнолесье и убедить Шеф-повара Груаля приготовить горячую порцию его знаменитых Темных пирожков с крабами.",h="Оказавшись один и в ужасе среди руин Вороньего Холма, параноидальный бродяга Трясунчик отчаянно жаждет...",kw={"chef grual","crab cakes","darkshire","growling gut","jitters","raven hill","scarlet raven tavern","шеф-повар груаль","пирожки с крабами","темнолесье","урчащий живот","трясунчик","вороний холм","таверна алый ворон"},ang={["faction:Alliance"]="Помощь Трясунчику связывает путников с хрупкими, борющимися поселениями и выжившими, цепляющимися за жизнь в темных уголках Сумеречного леса.",["profession:Cooking"]="Знаменитые Темные пирожки с крабами Шеф-повара Груаля показывают, как мастера кулинарии на границе обходятся местными экзотическими ингредиентами, когда обычные поставки не доходят до Сумеречного леса."},sec={{t="Голод в Вороньем Холме",b="Вороний Холм стал логовом голодной нежити и затаившихся зверей, и чудаковатый отшельник Трясунчик уже несколько недель прячется там в ловушке. Пробираясь под вечным мраком через ветхие лачуги, он выживал лишь на личинках из земли и диких сорняках. Лишенные цивилизованного уюта, его нервы и желудок на пределе."},{t="Мольба о пирожках с крабами",b="В отчаянии, мечтая хоть о чем-то, напоминающем о безопасности, Трясунчик грезит о пряных пирожках из таверны «Алый ворон» в Темнолесье. Он посылает путников по опасной дороге разыскать Шеф-повара Груаля, надеясь, что Груаль согласится испечь порцию Темных пирожков с крабами, чтобы утихомирить свой яростно урчащий живот."}},faq={{q="Кто такой Трясунчик?",a="Трясунчик — напуганный, параноидальный человек, прячущийся в разрушенном поселке Вороний Холм на западе Сумеречного леса. Он до ужаса боится нашествия нежити и постоянно живет в страхе голодной смерти и расправы.",al={"jitters","who is jitters","where is jitters","трясунчик","кто такой трясунчик","где трясунчик"}},{q="Где найти Шеф-повара Груаля?",a="Шеф-повар Груаль работает на кухне таверны «Алый ворон» в Темнолесье, на восточной стороне Сумеречного леса.",al={"chef grual location","find grual","scarlet raven chef","шеф-повар груаль местоположение","найти груаля","повар алого ворона"}},{q="Почему Трясунчик ест личинок?",a="Отрезанный от цивилизации полчищами бродячей нежити и хищных воргенов, Трясунчик несколько недель сидит в ловушке в разрушенном городке Вороний Холм и не имеет другой еды, кроме насекомых и растений, которые удается собрать.",al={"jitters eating bugs","why eats grubs","raven hill food","трясунчик ест жуков","почему ест личинок","еда вороний холм"}},{q="Какого блюда хочет Трясунчик?",a="Трясунчик мечтает о Темных пирожках с крабами — местном фирменном блюде, которое готовит Шеф-повар Груаль в таверне «Алый ворон».",al={"jitters food","crab cakes quest","what does jitters want to eat","еда трясунчика","задание пирожки с крабами","что хочет съесть трясунчик"}},{q="Что происходит после разговора с Шеф-поваром Груалем?",a="Шеф-повар Груаль готов приготовить еду для Трясунчика, но у него нет свежих ингредиентов, и он поручает искателю приключений собрать липкие паучьи лапки для Темных пирожков с крабами.",al={"after jitters growling gut","next quest jitters gut","chef grual task","после урчащий живот трясунчика","следующее задание трясунчика","поручение шеф-повара груаля"}},{q="Могут ли игроки Орды выполнить это задание?",a="Нет. И Трясунчик, и город Темнолесье относятся к Альянсу, поэтому это поручение доступно только искателям приключений Альянса.",al={"is jitters alliance only","horde jitters growling gut","только ли для альянса трясунчик","орда урчащий живот трясунчика"}}},fp="21,286,22.345.0,21.293.0,15.206.0,28.129.0,28.230.0,28.105.0,44.172.1,38.121.0"}
P.entries["quest:501"] = {n="Эликсир боли",s="По поручению аптекаря Лидона из Мельницы Таррен герои Орды должны добыть кровь горных львов, чтобы сварить новое смертоносное зелье. Задание показывает мрачную преданность Королевского фармацевтического общества совершенствованию Новой чумы и его презрение к природной жизненной силе Предгорий Хилсбрада.",h="По поручению аптекаря Лидона из Мельницы Таррен герои Орды должны добыть кровь горных львов, чтобы сварить...",kw={"apothecary lydon","elixir of pain","hillsbrad foothills","mountain lion blood","new plague","royal apothecary society","tarren mill","аптекарь лидон","эликсир боли","предгорья хилсбрада","кровь горного льва","новая чума","королевское фармацевтическое общество","мельница таррен"},ang={["faction:Horde"]="Союзникам Отрекшихся приходится мириться с мрачными методами алхимиков Мельницы Таррен и помогать в добыче диких зверей, чтобы укрепить оплоты Орды против соседних людских угроз.",["race:Undead"]="Для путников из числа Отрекшихся сбор реагентов для аптекаря Лидона напрямую служит воле Темной Госпожи и Королевского фармацевтического общества, утверждающих свои права в Лордероне."},sec={{t="Горький взгляд в Мельнице Таррен",b="Находясь в Мельнице Таррен, аптекарь Лидон не находит радости в окружающем пейзаже. Глядя из окна на цветущие луга и свежий горный воздух Хилсбрада, он считает неугасающую жизнь этого края оскорблением. Как и многие в Королевском фармацевтическом обществе, он предан леди Сильване Ветрокрылой и совершенствованию Новой чумы — созданной искусственно напасти, призванной принести смерть живым и возмездие их врагам."},{t="Ингредиенты для страданий",b="Для своей новейшей ядовитой смеси Лидон обращается к местной фауне, бродящей по предгорьям и склонам в сторону Альтеракских гор. Он полагает, что кровь горных львов обладает особыми свойствами, необходимыми для создания Эликсира боли, и посылает слуг в глушь за десятью пузырьками. Она послужит основой для продолжающихся химических испытаний Общества на спорном южном фронте."}},faq={{q="Кто выдает задание «Эликсир боли»?",a="Задание выдает аптекарь Лидон, алхимик из числа Отрекшихся, находящийся в поселении Мельница Таррен в Предгорьях Хилсбрада.",al={"quest giver elixir of pain","who starts elixir of pain","apothecary lydon quest","кто выдает эликсир боли","кто начинает эликсир боли","задание аптекаря лидона","эликсир боли задание"}},{q="Зачем аптекарю Лидону кровь горных львов?",a="Алхимические исследования Лидона показывают, что кровь горных львов — необходимый реагент для нового смертоносного зелья, эликсира, который должен продвинуть чумные опыты Королевского фармацевтического общества против живых врагов.",al={"why mountain lion blood","lion blood purpose","what is the blood for","зачем кровь горных львов","для чего кровь льва","зачем нужна кровь"}},{q="Где можно найти горных львов?",a="Горные львы бродят по открытым полям и холмам Предгорий Хилсбрада, а также по высоким обрывам, ведущим в Альтеракские горы.",al={"where are mountain lions","mountain lion locations hillsbrad","lion blood farming","где горные львы","горные львы хилсбрад","фарм крови льва"}},{q="Что такое Новая чума, о которой говорит Лидон?",a="Новая чума — биологическое оружие, которое по приказу леди Сильваны Ветрокрылой тщательно разрабатывает Королевское фармацевтическое общество Отрекшихся. Оно предназначено для уничтожения как Плети, так и живых.",al={"what is the new plague","royal apothecary society plague","forsaken plague","что такое новая чума","королевское фармацевтическое общество чума","чума отрекшихся"}},{q="Что будет после выполнения этого задания?",a="Сдача десяти пузырьков крови горных львов ведет прямо к следующему заданию, в котором аптекарь Лидон начинает испытывать свой новый эликсир.",al={"elixir of pain next quest","follow up elixir of pain","what follows elixir of pain","эликсир боли следующее задание","продолжение эликсира боли","что после эликсира боли"}},{q="Почему Лидон презирает пейзажи Хилсбрада?",a="Будучи нежитью на службе Темной Госпожи, Лидон ненавидит цветущую растительность, свежий воздух и неугасимую жизнь этого края и мечтает увидеть, как живой мир задохнется под ядовитыми творениями его Общества.",al={"why does lydon hate hillsbrad","why is lydon brooding","lydon window quote","почему лидон ненавидит хилсбрад","почему лидон мрачен","цитата лидона об окне"}}},fp="14,314,31.477.0,22.426.0,35.138.0,51.232.0,38.160.0,38.222.0,44.159.0,43.207.0"}
P.entries["quest:502"] = {n="Эликсир боли",s="По поручению аптекаря Лидона из Мельницы Таррен агенты Орды должны испытать новое биологическое зелье — Эликсир боли. Аптекарь из Отрекшихся выбирает в качестве ничего не подозревающего подопытного Стэнли, собаку фермера Рэя в Хилсбрадских полях.",h="По поручению аптекаря Лидона из Мельницы Таррен агенты Орды должны испытать новое биологическое зелье —...",kw={"apothecary lydon","elixir of pain","farmer ray","hillsbrad fields","royal apothecary society","stanley","tarren mill","аптекарь лидон","эликсир боли","фермер рэй","хилсбрадские поля","королевское фармацевтическое общество","стэнли","мельница таррен"},ang={["class:Hunter"]="Зрелище того, как кроткий домашний питомец жестоко превращается в дикого мутировавшего хищника, показывает неестественное извращение природы зверей алхимией Отрекшихся.",["faction:Horde"]="Союзников Отрекшихся напрямую вовлекают в их мрачные химические испытания против соседних человеческих ферм Хилсбрада.",["race:Undead"]="Этот опыт показывает безжалостные методы Королевского фармацевтического общества, которое ищет биологическое оружие ради выживания Отрекшихся, не считаясь с побочным ущербом."},sec={{t="Наука аптекарей",b="Работая в Мельнице Таррен, аптекарь Лидон проводит опыты от имени Королевского фармацевтического общества и леди Сильваны Ветрокрылой. Из свежей крови местных животных Лидон готовит нестабильную смесь, которую называет Эликсиром боли. Общество не довольствуется теорией алхимии: ему нужны полевые данные, чтобы наблюдать физиологическое действие экспериментальных ядов и мутагенов."},{t="Испытание на Стэнли",b="Чтобы испытать снадобье, не тревожа людей-защитников Хилсбрада, Лидон велит своим агентам отправиться на северную ферму в Хилсбрадских полях. Там живет Стэнли, с виду безобидная собака фермера Рэя. Агент подходит к ничего не подозревающему псу, налив зелье в ладонь, и дает дозу под видом обычного лакомства."},{t="Жестокая мутация",b="Истинная природа Эликсира боли проявляется сразу после приема. Это не просто смертельный яд, а ужасный мутаген: он вызывает мгновенную агонию и яростно превращает тело Стэнли в свирепого разъяренного волка. Зверь бросается на все вокруг, доказывая силу алхимической формулы Лидона."}},faq={{q="Для чего нужен Эликсир боли?",a="Аптекарь Лидон сварил Эликсир боли в рамках постоянных попыток Королевского фармацевтического общества создать биологическое оружие и сильные мутагены для леди Сильваны и Отрекшихся.",al={"elixir of pain goal","why make elixir of pain","lydon elixir purpose","цель эликсира боли","зачем делать эликсир боли","назначение эликсира лидона"}},{q="Кто такой Стэнли?",a="Стэнли — собака фермера Рэя, живущая возле большого фермерского дома на северной окраине Хилсбрадских полей.",al={"who is stanley","farmer ray dog","stanley the dog","кто такой стэнли","собака фермера рэя","пес стэнли"}},{q="Что произойдет, если дать Стэнли эликсир?",a="После приема эликсира Стэнли жестоко мутирует в свирепого бешеного волка, который тут же становится враждебным и нападает.",al={"stanley transformation","what does elixir do to dog","stanley wolf","превращение стэнли","что эликсир делает с собакой","стэнли волк"}},{q="Где находится Стэнли?",a="Стэнли бродит возле большого дома на северной ферме в Хилсбрадских полях, к юго-западу от Мельницы Таррен.",al={"find stanley","stanley location","where is farmer ray dog","найти стэнли","где стэнли","где собака фермера рэя"}},{q="Кто выдает задание на испытание эликсира?",a="Задание предлагает аптекарь Лидон, находящийся в поселении Отрекшихся Мельница Таррен в Предгорьях Хилсбрада, после того как вы соберете необходимые реагенты.",al={"elixir of pain questgiver","who gives elixir of pain","apothecary lydon quest","кто выдает эликсир боли","персонаж эликсир боли","задание аптекаря лидона"}},{q="Почему зелье испытывают на собаке фермера, а не на людях?",a="Испытание на домашнем животном в Хилсбрадских полях позволяет провести тихий и доступный опыт, не привлекая сразу внимания городского ополчения и вооруженной стражи Хилсбрада к сути алхимических испытаний.",al={"why test on dog","why stanley","why poison dog","почему на собаке","почему стэнли","зачем травить собаку"}}},fp="14,290,18.431.0,18.364.0,16.365.1,42.187.0,15.123.0,46.128.1,25.115.0,39.155.0,56.193.0"}
P.entries["quest:5041"] = {n="Снабжение Перекрестка",s="«Снабжение Перекрестка» — задание Орды от Торка: вернуть важные припасы, захваченные во время набегов свинобразов Иглогривых. Отбивая украденные ящики в колючих лагерях, герои помогают поддерживать Перекресток среди постоянных региональных конфликтов.",h="«Снабжение Перекрестка» — задание Орды от Торка: вернуть важные припасы, захваченные во время набегов...",kw={"barrens","caravan","crates","crossroads","quilboar","razormane","supplies","thork","степи","караван","ящики","перекресток","свинобразы","иглогривые","припасы","торк"},ang={["faction:Horde"]="Удержание Перекрестка необходимо для связи столиц Орды в Дуротаре и Мулгоре; возвращая захваченные грузы, вы помогаете приграничной заставе не остаться без припасов.",["race:Orc"]="Защита этих важных путей снабжения от свинобразов-воров — священный долг по охране растущих поселений новой Орды."},sec={{t="Спасательная нить в осаде",b="Перекресток — главный узел путешествий, торговли и обороны Орды в Степях. Для работы такого центра нужен постоянный поток грузов из Дуротара и Мулгора. Когда караван с припасами попадает в засаду, застава сразу испытывает нехватку провизии, инструментов и оружия, необходимых для жизни в суровой глуши."},{t="Свинобразы-воры",b="Налет совершили свинобразы Иглогривых, местные свиноподобные существа, оспаривающие господство Орды в центральном Калимдоре. Вместо того чтобы уничтожить похищенное, свинобразы утащили тяжелые ящики в свои укрепленные лагеря из колючих кустов, чтобы припрятать их. Торк поручает надежным воинам проникнуть вглубь земель Иглогривых и вернуть то, что по праву принадлежит Орде."}},faq={{q="Кто выдает это задание?",a="Это задание выдает Торк, офицер Орды, руководящий обороной и делами Перекрестка.",al={"quest giver","thork quest","who starts supplies for the crossroads","персонаж, выдающий задание","задание торка","кто начинает снабжение перекрестка"}},{q="Почему припасы вообще были украдены?",a="Караван с припасами, шедший к Перекрестку, попал в засаду агрессивных свинобразов Иглогривых, которые утащили ящики в свои ближние лагеря.",al={"caravan raid","why stolen","what happened to the supplies","налет на караван","почему украдены","что случилось с припасами"}},{q="Где найти украденные ящики?",a="Украденные ящики с припасами для Перекрестка разбросаны по земле в лагерях свинобразов Иглогривых к востоку и северо-востоку от Перекрестка.",al={"crate locations","where are supplies","find crates","где ящики","где припасы","найти ящики"}},{q="Почему Торку так важно вернуть эти припасы?",a="Перекресток — изолированный и оживленный узел, окруженный враждебными угрозами. Потерянные караваны угрожают повседневной работе и безопасности заставы, оставляя и солдат, и путников без необходимого.",al={"why care","crossroads importance","importance of supplies","почему это важно","важность перекрестка","важность припасов"}},{q="Какое задание предшествует этому?",a="Это задание следует за заданием «Прекратить набеги», в котором герои сначала наносят удар по силам Иглогривых, чтобы ослабить их натиск на торговые пути Орды.",al={"prerequisite","prev quest","disrupt the attacks","предыдущее задание","что до этого","прекратить набеги"}},{q="Кто такие Иглогривые?",a="Иглогривые — свирепое, ревниво охраняющее свои земли племя свинобразов, коренных жителей Степей. Они яростно нападают на караваны и оспаривают присутствие Орды на своих исконных землях.",al={"razormane quilboar","who are quilboar","razormane","иглогривые свинобразы","кто такие свинобразы","иглогривые"}}},fp="27,269,22.350.0,17.399.0,21.99.0,48.142.0,37.156.0,55.211.0,29.152.0,22.178.0"}
P.entries["quest:5043"] = {n="Ловкость Агамаггана",s="Ловкость Агамаггана — повторяемый ритуал с кровавыми осколками, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо. Принося кристаллические Кровавые осколки, добытые из земли Степей, путники получают благословение безошибочной быстроты и меткости древнего божества-вепря свинобразов.",h="Ловкость Агамаггана — повторяемый ритуал с кровавыми осколками, который предлагает плененный свинобраз...",kw={"agamaggan","agility","barrens","blood shards","mangletooth","quilboar","taurajo","агамагган","ловкость","степи","кровавые осколки","кривозуб","свинобраз","таурахо"},ang={["class:Hunter"]="Ловкость Агамаггана сосредоточена на безошибочной меткости и быстром выслеживании — достоинствах, глубоко ценимых стрелками, пересекающими открытые просторы Калимдора.",["class:Rogue"]="Кривозуб особенно насмехается над быстротой разбойников, не являющихся свинобразами, поэтому этот ритуал становится тихим торжеством, когда священная скорость зверя обращается против племен зарослей.",["faction:Horde"]="Силы Орды в Лагере Таурахо терпят присутствие Кривозуба и сделки с Кровавыми осколками лишь потому, что остаточная сила бога-вепря помогает их нелегкой кампании в Степях.",["race:Tauren"]="Таурены уважают силу Древних, погибших в Войне Древних, хотя сделка с запертым в клетке свинобразом в Таурахо — неловкий компромисс."},sec={{t="Сила Кровавых осколков",b="По всем Степям из почвы торчат странные багровые минералы, известные как Кровавые осколки, особенно рядом со стоянками свинобразов и огромными зарослями терний. Предания свинобразов гласят, что эти кристаллы образовались из пролитой крови Агамаггана, Великого Вепря-Древнего, погибшего в борьбе с Пылающим Легионом в Войне Древних. Даже запертый в деревянной клетке в Лагере Таурахо, старый свинобраз Кривозуб умеет направлять эту дремлющую божественную силу для всякого, кто принесет камни."},{t="Благословение вепрей-разведчиков",b="Охотники и разведчики свинобразов гордятся беспощадной меткостью и ослепительной быстротой в зарослях. За четыре Кровавых осколка Кривозуб призывает скрытую энергию павшего полубога, наделяя просителя хищными инстинктами и гибкой грацией лучших следопытов своего народа. Хотя к чужакам он относится с презрительным ворчанием, Кривозуб чтит уговор, вплетая силу Агамаггана во временный покров ловкости."}},faq={{q="Кто предлагает Ловкость Агамаггана?",a="Задание выдает Кривозуб, геомант-свинобраз, которого держат в плену в клетке в Лагере Таурахо на юге Степей. Несмотря на заточение Ордой, он охотно торгуется с искателями приключений, приносящими ему Кровавые осколки.",al={"who gives quest","quest giver","where is mangletooth","кто дает задание","персонаж, выдающий задания","где кривозуб"}},{q="Что такое Кровавые осколки?",a="Кровавые осколки — кристаллические камни, встречающиеся по всем Степям; их добывают в основном из убитых свинобразов и минеральных выходов близ терновых зарослей. Предания свинобразов гласят, что они образовались тысячелетия назад, когда кровь Великого Вепря-Древнего Агамаггана обагрила землю.",al={"blood shards lore","what is a blood shard","red crystals in barrens","предания о кровавых осколках","что такое кровавый осколок","красные кристаллы в степях"}},{q="Почему плененный свинобраз помогает членам Орды?",a="Верность Кривозуба принадлежит его богу Агамаггану и собственному выживанию. Хотя он презрительно фыркает на всех, кто не свинобраз, он охотно обменивает божественные благословения Агамаггана на Кровавые осколки, что позволяет ему обращаться со священной сущностью своего божества даже из клетки врага.",al={"why help us","mangletooth motives","why does mangletooth talk","почему помогает нам","мотивы кривозуба","почему кривозуб разговаривает"}},{q="Можно ли получить это благословение больше одного раза?",a="Да. Этот ритуал полностью повторяем. Пока вы приносите Кривозубу четыре новых Кровавых осколка, он вновь призывает благословение Великого Вепря.",al={"is this repeatable","can i redo this","repeatable buff","повторяется ли","можно ли повторить","повторяемый бафф"}},{q="Кто такой Агамагган?",a="Агамагган был исполинским вепрем-Древним, ходившим по Калимдору в древнюю мифическую эпоху. Во время Войны Древних десять тысяч лет назад он сражался с демонами Пылающего Легиона и пал. Его кровь питала Степи, породив их непроходимые иглошипы и племя свинобразов.",al={"who is agamaggan","boar god","great boar","кто такой агамагган","бог-вепрь","великий вепрь"}},{q="Какие еще благословения дает Кривозуб?",a="Помимо ловкости, Кривозуб предлагает обряды, чтящие другие стороны Агамаггана. В обмен на Кровавые осколки он может даровать благословения, усиливающие грубую физическую силу, мудрость разума, быстроту бега и кожу, толстую как иглошкура.",al={"other blood shard quests","other buffs","mangletooth rewards","другие задания кровавые осколки","другие бафы","награды кривозуба"}}},fp="19,288,25.518.0,27.440.0,31.224.0,22.268.0,48.269.0,45.152.0,18.305.0,46.237.0"}
P.entries["quest:5044"] = {n="Мудрость Агамаггана",s="Мудрость Агамаггана — повторяемое задание Орды, которое предлагает плененный свинобраз Кривозуб в Лагере Таурахо. Принося Кровавые осколки, собранные по Степям, заклинатели могут приобщиться к ритуальной магии древнего бога-вепря Агамаггана.",h="Мудрость Агамаггана — повторяемое задание Орды, которое предлагает плененный свинобраз Кривозуб в Лагере...",kw={"barrens","blood shards","boar god","camp taurajo","geomancer","mangletooth","quilboar","wisdom of agamaggan","степи","кровавые осколки","бог-вепрь","лагерь таурахо","геомант","кривозуб","свинобраз","мудрость агамаггана"},ang={["class:Mage"]="Маги, увлеченные магическим усилением, оценят первобытную геомантическую силу, которая через сущность Агамаггана направляется в чистый интеллект.",["class:Priest"]="Жрецы, изучающие местные верования, найдут прямую связь между божественной кровью Агамаггана и ритуалами укрепления разума интересной гранью первобытного божественного культа.",["class:Shaman"]="Геомантия свинобразов отражает стихийные призвания шаманизма, поэтому ритуалы осколков бога-вепря знакомы шаманам, но при этом по-своему дики.",["faction:Horde"]="Содержание Кривозуба Ордой в Лагере Таурахо дает воинам и мистикам удобную возможность использовать местную магию Степей против окрестных племен свинобразов."},sec={{t="Кровавые осколки и древняя сила",b="Свинобраз Кривозуб, находящийся в плену у Орды в Лагере Таурахо, обменивает магические тайны своего народа на багровые кристаллы, известные как осколки крови. Согласно верованиям свинобразов, эти осколки образовались из пролитой крови Агамаггана — громадного полубога-вепря, погибшего в Войне Древних. Кривозуб утверждает, что геоманты и шаманы его племен используют эти осколки, чтобы направлять божественную силу в свои обряды."},{t="Благословение разума",b="Если другие дары вызывают из осколков физическую стойкость или быстроту, то ритуал Мудрости направлен строго на интеллект и тайные способности. За четыре Кровавых осколка Кривозуб призывает дух бога-вепря в пользу игрока, желая ему хитрости в схватках, и прощается зловещим напоминанием о смертности."}},faq={{q="Кто такой Агамагган?",a="Агамагган — древний вепрь-полубог, сражавшийся с Пылающим Легионом в Войне Древних десять тысяч лет назад. Он пал в Степях, где его кровь впиталась в почву, породив гигантские терновые лозы и кристаллические Кровавые осколки.",al={"agamaggan lore","who is the boar god","boar ancient","предания об агамаггане","кто такой бог-вепрь","вепрь-древний"}},{q="Почему Кривозуб готов помогать Орде?",a="Кривозуб — плененный свинобраз, которого держат в клетке в Лагере Таурахо. Несмотря на жгучую ненависть его племени к Орде, жажда Кровавых осколков и желание выжить перевешивают его верность, и он дарует священные племенные благословения в обмен на осколки.",al={"why help mangletooth","mangletooth motive","captive quilboar","почему помогать кривозубу","мотив кривозуба","пленный свинобраз"}},{q="Что такое Кровавые осколки?",a="Кровавые осколки — красные минеральные образования, встречающиеся по всем землям свинобразов в Степях. Легенды свинобразов утверждают, что эти кристаллы образовались прямо из капель крови, пролитой полубогом Агамаггана при его гибели.",al={"blood shard lore","what are blood shards","red shards barrens","предания о кровавых осколках","что такое кровавые осколки","красные осколки степи"}},{q="Можно ли повторить этот ритуал больше одного раза?",a="Да. Когда Кривозуб поверит вам после первого показа Кровавых осколков, он будет принимать по четыре Кровавых осколка каждый раз, когда вы захотите обновить благословение.",al={"is wisdom of agamaggan repeatable","repeatable blood shards","turn in again","повторяется ли мудрость агамаггана","повторяемое задание кровавые осколки","сдать снова"}},{q="Поклоняются ли шаманы свинобразов другим божествам?",a="Свинобразы чтят Агамаггана превыше всех остальных, считая себя его прямыми потомками. Их шаманы и геоманты черпают магию природы и власть над землей непосредственно из его мифического наследия и останков.",al={"quilboar religion","geomancer gods","quilboar worship","религия свинобразов","боги геомантов","поклонение свинобразов"}},{q="Где, по словам Кривозуба, может состояться следующая встреча?",a="По завершении ритуала Кривозуб говорит вам рассказать о своей хитрости при следующей встрече, в этой смертной жизни или в следующей, признавая нескончаемое кровопролитие в Степях.",al={"mangletooth next life","mangletooth dialogue","кривозуб следующая жизнь","диалог кривозуба"}}},fp="19,249,30.435.0,20.355.0,17.245.0,45.254.0,22.222.0,40.178.0,41.216.0,57.208.0"}
P.entries["quest:5045"] = {n="Высокий дух",s="Высокий дух — ритуальное благословение, которое предлагает плененный геомант из племени Иглогривых Кривозуб в Лагере Таурахо. В обмен на кровавые осколки, отобранные у его соперников Дыбогривов, Кривозуб направляет древнюю силу Агамаггана, чтобы укрепить силу воли и духовную стойкость героя.",h="Высокий дух — ритуальное благословение, которое предлагает плененный геомант из племени Иглогривых Кривозуб в...",kw={"agamaggan","barrens","blood shards","bristleback","camp taurajo","mangletooth","razormane","rising spirit","агамагган","степи","кровавые осколки","дыбогрив","лагерь таурахо","кривозуб","иглогривые","высокий дух"},ang={["class:Priest"]="Жрецы увидят в единении свинобразов с Агамагганом первобытное выражение веры и духа, не уступающее организованным молитвам восточных церквей.",["class:Shaman"]="Шаманы понимают, как глубоко древние родословные и земные минералы могут связать духов земли со смертным воином.",["faction:Horde"]="Для странников Орды в Степях глубокая племенная ненависть Кривозуба к Дыбогривам превращает назойливого пленника в ценное тактическое преимущество."},sec={{t="Сила воли Иглогривых",b="Старейшина Иглогривых Кривозуб, запертый в клетке в Лагере Таурахо, глубоко сведущ в геомантии свинобразов и магии предков. Пока другие племена хвалятся грубой боевой яростью, Кривозуб гордится духовной преданностью своего народа создателю, Великому Вепрю Агамаггану. Он учит, что несломленный дух поддерживает воина, когда одной силы в бою не хватает, и ведет героев вперед, даже когда поражение кажется неизбежным."},{t="Сила кровавых осколков",b="Чтобы призвать это духовное возвышение, Кривозуб требует кровавые осколки — кристаллизованные фрагменты, пропитанные древней кровью Агамаггана, которая впиталась в красную землю десять тысяч лет назад. Принося ему осколки, собранные по всем Степям, особенно у его врагов Дыбогривов, вы даете ему необходимый духовный проводник, чтобы он сплел благословение высокого духа, укрепляющее вашу волю."}},faq={{q="Кто такой Кривозуб?",a="Кривозуб — старейшина свинобразов из племени Иглогривых, содержащийся в деревянной клетке в Лагере Таурахо. Хотя он пленник Орды, он готов делиться священными геомантическими ритуалами в обмен на кровавые осколки, используя путников для ударов по враждебному племени Дыбогривов.",al={"mangletooth lore","who is the caged boar","taurajo prisoner","кривозуб предания","кто такой кабан в клетке","пленник таурахо"}},{q="Что такое кровавые осколки?",a="Blood shards are red mineral crystals formed from the spilled blood of the Ancient Demigod Agamaggan, who died in the Barrens during the War of the Ancients. They hold potent residual magic that quillboar shamans and geomancers harness for boons and rituals.",al={"what are blood shards","blood shard lore","agamaggan blood","что такое кровавые осколки","предания о кровавых осколках","кровь агамаггана"}},{q="Почему Кривозуб помогает искателям приключений из Орды?",a="Кривозуб питает жгучую ненависть к враждебным свинобразам Дыбогривам. Обменивая благословения на кровавые осколки, он побуждает сильных искателей приключений истреблять Дыбогривов по всем Степям, продолжая вражду своего племени даже в клетке.",al={"why does mangletooth help","why is quillboar helping horde","почему кривозуб помогает","почему свинобраз помогает орде"}},{q="Что дает благословение «Высокий дух»?",a="Высокий дух — мощное благословение предков от Кривозуба, которое усиливает дух и внутреннюю решимость воина, черпая из неиссякаемой жизненной силы Агамаггана, чтобы сохранять надежду в изнурительных сражениях.",al={"rising spirit buff","what is rising spirit","высокий дух бафф","что такое высокий дух"}},{q="Кто такой Агамагган?",a="Агамагган — колоссальный Древний-вепрь, сражавшийся с Пылающим Легионом десять тысяч лет назад во время Войны Древних. Свинобразы почитают его как создателя и верят, что колючие заросли и красные кровавые осколки Степей проросли прямо из его павшего тела.",al={"agamaggan","the great boar","агамагган","великий вепрь"}},{q="Этот ритуал — разовый обмен?",a="Нет. Пока вы приносите Кривозубу четыре кровавых осколка, плененный старейшина готов проводить ритуал снова и снова, обновляя благословение перед тем, как вы отправитесь обратно в пустоши.",al={"repeat rising spirit","is rising spirit repeatable","повторить высокий дух","можно ли повторять высокий дух"}}},fp="13,287,26.448.0,25.406.0,19.267.0,22.258.0,44.251.0,40.214.0,17.277.0,32.184.0"}
P.entries["quest:5046"] = {n="Иглошкура",s="Иглошкура — повторяемый ритуал, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо. Принося ему кровавые осколки, наполненные жизненной сущностью древнего бога-вепря Агамаггана, воины и странники могут получить мощное благословение закаленной кожи и стойкости перед боем.",h="Иглошкура — повторяемый ритуал, который предлагает плененный свинобраз Кривозуб в Лагере Таурахо.",kw={"agamaggan","barrens","blood shards","camp taurajo","mangletooth","quilboar","razorhide","агамагган","степи","кровавые осколки","лагерь таурахо","кривозуб","свинобраз","иглошкура"},ang={["class:Warrior"]="Бойцам передовой, входящим в опасные колючие заросли юга Степей, очень полезны магическая броня и закаленная шкура, смягчающие мощные удары.",["faction:Horde"]="Лагерь Таурахо служит оплотом Орды против постоянного натиска свинобразов, обращая почтение пленного Кривозуба к Агамаггану на пользу путникам.",["race:Tauren"]="Охотники Лагеря Таурахо присматривают за клеткой Кривозуба: хотя обряды свинобразов затрагивают священную землю Матери-Земли, их дикие служители редко делятся тайнами бесплатно."},sec={{t="Благословения бога-вепря",b="Свинобразы ведут свой род и силу прямо от Агамаггана, Великого Вепря, погибшего в битве с Пылающим Легионом тысячи лет назад. Его кровь впиталась в почву Степей и окаменела в кристаллические кровавые осколки, которые до сих пор гудят древней силой. Хотя свинобразы остаются заклятыми врагами Орды, Кривозуб, запертый в клетке в Лагере Таурахо, готов обменять их священные знания на эти драгоценные фрагменты."},{t="Закалка шкуры",b="От природы свинобразы обладают толстой шкурой и защитными иглами, но племенные воины призывают благословение Агамаггана «Иглошкура», чтобы еще лучше защититься от вражеских клинков и когтей. Направляя силу четырех кровавых осколков, Кривозуб воспроизводит этот племенной обряд для чужаков, магически усиливая защиту искателя приключений, чтобы его кости оставались целы, а кожа выдерживала ранения в глуши."}},faq={{q="Кто предлагает ритуал «Иглошкура»?",a="Задание выдает Кривозуб, заключенный свинобраз, которого держат в деревянной клетке в Лагере Таурахо на юге Степей. Когда вы докажете, что знакомы с кровавыми осколками, он предложит разные благословения в обмен на новые.",al={"who gives razorhide","mangletooth quest","who starts razorhide","кто дает иглошкура","задание кривозуба","кто начинает иглошкура"}},{q="Что такое кровавые осколки?",a="Кровавые осколки — кристаллические образования, встречающиеся по всем Степям. По верованиям свинобразов, они образовались из пролитой крови Древнего Вепря Агамаггана во время Войны Древних и хранят огромный запас первобытной магии.",al={"what are blood shards","blood shard lore","blood of agamaggan","что такое кровавые осколки","предания о кровавых осколках","кровь агамаггана"}},{q="Почему пленный свинобраз помогает путникам из Орды?",a="Кривозуб — пленник таурен в Лагере Таурахо. Сохраняя грубый нрав и верность своему богу, он жаждет кровавых осколков и готов учить чужаков обрядам свинобразов, чтобы их получить.",al={"why does mangletooth help","why is mangletooth in taurajo","friendly quilboar","почему кривозуб помогает","почему кривозуб в таурахо","дружелюбный свинобраз"}},{q="Какую защиту олицетворяет «Иглошкура»?",a="Иглошкура олицетворяет племенные обереги, которые свинобразы призывают перед боем. Она утолщает кожу и укрепляет кости, дополняя природную защиту сверхъестественной выносливостью Агамаггана.",al={"what does razorhide do","razorhide lore","protective blessing","что делает иглошкура","предания об иглошкуре","защитное благословение"}},{q="Можно ли получить «Иглошкуру» больше одного раза?",a="Да. Как и все дары Кривозуба, Иглошкура — повторяемый обмен. Всякий раз, когда вы приносите ему четыре кровавых осколка, он призовет благословение для вас.",al={"is razorhide repeatable","repeat razorhide","how many times can i do razorhide","иглошкура повторяется","повторить иглошкуру","сколько раз можно получить иглошкуру"}},{q="Где можно найти кровавые осколки?",a="Кровавые осколки обычно добывают у геомантов, охотников и воинов в разных лагерях свинобразов, зарослях и скалах по всем Степям.",al={"blood shard locations","where to get blood shards","farm blood shards","где найти кровавые осколки","где достать кровавые осколки","фарм кровавых осколков"}}},fp="9,299,25.464.0,18.398.0,32.224.0,22.246.0,54.209.0,49.204.0,41.162.0,32.156.0"}
P.entries["quest:5061"] = {n="Водный облик",s="Водный облик — завершающий обряд посвящения для друидов Альянса, которые учатся настраивать свой дух на глубокие воды. Собрав разделенные половины Подвески Морского Льва в Калимдоре и Восточных королевствах и скрепив их на Лунной поляне, посвящаемые возвращаются в Дарнасс, чтобы открыть новый облик.",h="Водный облик — завершающий обряд посвящения для друидов Альянса, которые учатся настраивать свой дух на...",kw={"aquatic form","cenarion enclave","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","pendant of the sea lion","sea lion","водный облик","анклав кенария","дарнасс","дендрит блеск звезд","матренгил медвежья лапа","лунная поляна","подвеска морского льва","морской лев"},ang={["class:Druid"]="Это задание — важная веха в вашем единении с природой: вы сможете быстро передвигаться под водой и неограниченно долго дышать под ее поверхностью.",["faction:Alliance"]="Завершение друидических испытаний дает Альянсу разведчиков, способных легко пересекать озера, реки и морские берега.",["race:NightElf"]="Для посвящаемых ночных эльфов возвращение из вневременных лесов Лунной поляны к юной кроне Тельдрассила подтверждает их долг защищать дикую природу Азерота в эпоху меняющегося равновесия."},sec={{t="Священная связь с глубинами",b="Для посвящаемого Круга Кенария превращение — не просто колдовство, а акт духовного единения с дикими силами Азерота. Доказав стойкость в темных прибрежных глубинах и пройдя испытания на Лунной поляне, молодые друиды-ночные эльфы получают собранную Подвеску Морского Льва от Дендрита Блеска Звезд. Доставив этот священный знак в Тельдрассил, посвящаемый доказывает, что чтит законы природы, управляющие воздухом, водой и дыханием."},{t="Возвращение в Дарнасс",b="В ветвях Анклава Кенария возвращения соискателя ждет старший наставник друидов Матренгил Медвежья Лапа. Испытания на побережьях Темных берегов и Западного Края требуют великой выносливости и внутренней гармонии. Предъявив собранную подвеску, посвящаемый показывает Матренгилу Медвежьей Лапе, что его разум и тело готовы сбросить смертный облик и принять быстрый, дышащий облик морского льва."}},faq={{q="Для чего нужно это задание?",a="Это задание — последний шаг в обучении друида Альянса Водному облику. Предъявив восстановленную Подвеску Морского Льва Матренгилу Медвежьей Лапе в Дарнассе, друид получает право на обучение водному облику.",al={"why do this quest","aquatic form purpose","what does this quest give","зачем делать это задание","цель водного облика","что дает это задание"}},{q="Кто отправляет вас обратно в Дарнасс?",a="Дендрит Блеск Звезд, старейшина Круга Кенария, обитающий в священном убежище Лунной поляны, отправляет вас обратно в Тельдрассил после того, как вы успешно завершите Испытание Морского Льва.",al={"who gives this quest","quest giver","dendrite starblaze","кто дает это задание","персонаж, выдающий задания","дендрит блеск звезд"}},{q="Кто завершает ваше обучение в Дарнассе?",a="Матренгил Медвежья Лапа, наставник друидов в Анклаве Кенария в Дарнассе, принимает вашу подвеску и обучает вас водному облику.",al={"quest hand in","who turns in aquatic form","mathrengyl bearwalker","сдача задания","кто принимает водный облик","матренгил медвежья лапа"}},{q="Что такое Подвеска Морского Льва?",a="Подвеска Морского Льва — священный талисман, созданный из двух подвесок испытаний, найденных в морских глубинах у берегов Темных берегов и Западного Края. Она служит осязаемым доказательством того, что друид овладел выносливостью и терпением, которых требуют морские существа.",al={"what is the pendant","pendant of the sea lion lore","что такое подвеска","предание о подвеске морского льва"}},{q="Выполняют ли друиды Орды именно это задание?",a="Нет. Друиды-таурены тоже проходят испытания на Лунной поляне, чтобы получить водный облик, но их путь ведет обратно к Тюраку Руническому Тотему на плато Громового Утеса, а не в Дарнасс.",al={"can tauren do this","is this quest alliance only","horde version","могут ли таурены выполнить это","задание только для Альянса","версия для Орды"}},{q="Где в Дарнассе находится Матренгил Медвежья Лапа?",a="Матренгил Медвежья Лапа живет в Анклаве Кенария, пышном убежище в северо-западном квартале Дарнасса, в ветвях Тельдрассила.",al={"where is mathrengyl","darnassus druid trainer location","где матренгил","наставник друидов дарнасса где"}}},fp="12,331,29.497.0,19.420.0,34.246.0,32.182.0,41.162.0,36.269.0,36.193.0,44.152.0"}
P.entries["quest:5062"] = {n="Священное пламя",s="Священное пламя — обряд посвящения Орды, связывающий изрезанные каньоны Тысячи Игл с высотами Громового Утеса. Чтобы призвать и изгнать мстительного ветряного змея Арикару, охотники должны собрать редкую Огненную агаву у Кипящего озера, чтобы Магата Зловещий Тотем превратила ее в ритуальный порошок.",h="Священное пламя — обряд посвящения Орды, связывающий изрезанные каньоны Тысячи Игл с высотами Громового Утеса.",kw={"arikara","boiling pool","darkcloud pinnacle","elder rise","incendia agave","magatha grimtotem","motega firemane","sacred fire","thousand needles","арикара","кипящее озеро","пик темного облака","вершина старейшин","огненная агава","магата зловещий тотем","мотега огненная грива","священное пламя","тысяча игл"},ang={["class:Shaman"]="Задание показывает практическое применение магии шаманов: стихийная сила может быть влита в природные растения, такие как Огненная агава.",["faction:Horde"]="Выполнение испытаний для старейшин укрепляет связи Орды на засушливых равнинах Калимдора.",["profession:Herbalism"]="У травников есть явное преимущество в поисках колючих кустов Огненной агавы под водой Кипящего озера.",["race:Tauren"]="Для охотников-тауренов почитание духов через ритуальную охоту и умение ориентироваться в политике старейшин на Вершине Старейшин — основа обряда взросления."},sec={{t="Разжечь дух",b="Чудовищного ветряного змея Арикару нельзя просто выследить на дне каньона — ее нужно призвать. Мотега Огненная Грива велит охотникам приготовить священное пламя жизни, древний ритуальный огонь, служащий маяком для духа-зверя. Для него нужно больше, чем обычный хворост, — редкая Огненная агава, растущая только у обжигающих вод Тысячи Игл."},{t="Кипящее озеро",b="Огненная агава растет у Кипящего озера — геотермального водоема у подножия Пика Темного Облака. Чтобы собрать колючее растение, придется пройти через обжигающую воду и нестабильных паровых элементалей, дрейфующих в тумане. Многие кусты растут под водой, и охотнику, посланному за ними, потребуется стойкость."},{t="Благословение старейшины",b="Одна сырая агава не разожжет ритуальную жаровню. Собранные растения нужно отнести высоко над равнинами на Вершину Старейшин в Громовом Утесе. Там старейшина-шаманка Магата Зловещий Тотем применяет свое мастерство, чтобы растереть и зачаровать листья в сильный ритуальный порошок, внешне желая увидеть, как мстительному зверю бросят вызов."}},faq={{q="Что такое священное пламя жизни?",a="Это ритуальный огонь, которым призывают мстительного змея-духа Арикару. Пока это священное пламя не зажжено, зверь остается скрытым и недосягаемым.",al={"sacred fire","what does the fire do","why light the sacred fire","священное пламя","что делает огонь","зачем зажигать священное пламя"}},{q="Где растет Огненная агава?",a="Огненную агаву можно найти в Кипящем озере и рядом с ним в Тысяче Игл, у подножия Пика Темного Облака. Многие колючие растения растут под горячей водой озера.",al={"where to find agave","incendia agave location","boiling pool agave","где найти агаву","где растет огненная агава","агава кипящее озеро"}},{q="Почему Магата Зловещий Тотем должна зачаровать агаву?",a="Сырому растению не хватает магической силы, чтобы зажечь священное пламя. Как могущественная шаманка, Магата вплетает в листья энергию стихий и превращает их в порошок, способный пробудить дремлющее пламя.",al={"why magatha","who enchants the agave","what does magatha do","почему магата","кто зачаровывает агаву","что делает магата"}},{q="Кто такая Арикара?",a="Арикара — грозный ветряной змей, рожденный нести возмездие тем, кто совершает ужасные преступления. Мотега Огненная Грива считает ее присутствие неминуемой опасностью, с которой должны справиться быстрые охотники.",al={"what is arikara","arikara lore","wind serpent boss","кто такая арикара","предание об арикаре","босс ветряной змей"}},{q="Кто выдает задание «Священное пламя»?",a="Мотега Огненная Грива дает задание в Тысяче Игл после того, как вы поможете ему с первыми поручениями, связанными с угрозой местных змеев.",al={"quest giver sacred fire","where to start sacred fire","кто выдает священное пламя","где начать священное пламя"}},{q="Почему Магата улыбается, услышав об Арикаре?",a="Магата находит удовольствие или удовлетворение в упоминании существа, рожденного лишь для наказания мерзких деяний, что намекает на ее мрачный взгляд на месть и племенную политику.",al={"magatha smiling","magatha reaction","why does magatha smile","магата улыбается","реакция магаты","почему магата улыбается"}}},fp="11,304,19.399.0,16.346.0,20.319.1,32.149.0,31.180.0,45.211.0,15.201.0,32.132.0,49.170.0"}
P.entries["quest:5064"] = {n="Наблюдение за Зловещим Тотемом",s="Дозорный утесов Долгорог поручает защитникам Орды проникнуть на Пик Темного Облака и выяснить, что замышляет неуловимый клан Зловещего Тотема. Трех неизвестных гонцов видели на плато, а охраняемые письма разбросаны по их горной деревне. Найдя эти тайные записки, можно раскрыть зреющий замысел, угрожающий поселениям тауренов Тысячи Игл.",h="Дозорный утесов Долгорог поручает защитникам Орды проникнуть на Пик Темного Облака и выяснить, что замышляет...",kw={"cliffwatcher longhorn","darkcloud pinnacle","freewind post","grimtotem","secret notes","spying","tauren","thousand needles","дозорный утесов долгорог","пик темного облака","застава вольного ветра","зловещий тотем","тайные записки","шпионаж","таурены","тысяча игл"},ang={["class:Rogue"]="Добыть три сундука на подвесных мостах и в густо патрулируемых постройках Пика Темного Облака — идеальная тайная операция, где скрытность важнее открытого боя.",["faction:Horde"]="Застава Вольного Ветра — важная линия жизни Орды на юге Калимдора. Любые подрывные замыслы Зловещего Тотема на Пике Темного Облака угрожают хрупким линиям снабжения между Степями и Танарисом.",["race:Tauren"]="Предательство клана Зловещего Тотема больно бьет по тауренам, чье общество ценит гармонию и честь рода. Открытие того, что сородичи тайно встречаются с неизвестными заговорщиками, угрожает всему, что построил Кэрн Кровавое Копыто."},sec={{t="Глаза на ветру",b="Застава Вольного Ветра стоит на высоких шпилях, но ее защитники вынуждены постоянно оглядываться на враждебных сородичей. Клан Зловещего Тотема давно враждебно и обиженно относится к Орде и держится за изолированные твердыни на Пике Темного Облака. Дозорный утесов Долгорог заметил перемену в их поведении, когда в течение нескольких недель прибыли три таинственных агента и тайно совещались с вождями клана. Долгорог подозревает, что эти посланники принесли приказы о выступлении или союзы, направленные против присутствия Громового Утеса в каньоне."},{t="Проникновение на Пик Темного Облака",b="Пик Темного Облака — укрепленная сеть отвесных плато, соединенных веревочными мостами. Чтобы проникнуть в деревню, придется пройти через плотные патрули враждебных воинов и шаманов Зловещего Тотема. Разведчики Долгорога подтвердили, что таинственные письма заперты в отдельных сундуках в центральных жилищах и на внешних утесах поселения. Чтобы добыть три тайные записки, нужно красться или пробиваться через все поселение и выкрасть личную переписку клана из-под бдительных глаз."},{t="Мрачные предзнаменования",b="Три добытые записки, возвращенные Дозорному утесов Долгорогу, подтверждают худшие опасения Заставы Вольного Ветра. Переписка показывает, что Зловещий Тотем не просто бряцает оружием, а активно взаимодействует с внешними агентами для скорого выступления. Хотя весь масштаб их замыслов остается скрытым, Долгорог тут же начинает разрабатывать планы защиты застав каньона от внезапного предательства."}},faq={{q="Кто посылает агентов на встречу со Зловещим Тотемом?",a="Дозорный утесов Долгорог знает лишь, что в последние недели на Пике Темного Облака видели трех агентов неизвестного происхождения. Личность их покровителей строго хранится в тайне в охраняемых записках.",al={"who visited grimtotem","grimtotem secret agents","who sent the notes","кто посещал зловещий тотем","тайные агенты зловещего тотема","кто прислал записки"}},{q="Где находится Пик Темного Облака?",a="Пик Темного Облака расположен в западной части Тысячи Игл, к юго-востоку от Великого Подъемника. Отмеченная синим тотемом тропа ведет по утесам плато в деревню, где деревянные мосты соединяют несколько высоких пиков.",al={"where is darkcloud pinnacle","how to get to darkcloud pinnacle","darkcloud pinnacle entrance","где пик темного облака","как попасть на пик темного облака","вход на пик темного облака"}},{q="Почему Зловещий Тотем враждебен к другим тауренам?",a="Зловещий Тотем считает тауренов выше всех прочих рас и яростно отвергает союз Кэрна Кровавого Копыта с Ордой. Хотя некоторые из Зловещего Тотема живут в Громовом Утесе в хрупком мире, кланы вроде обитающего на Пике Темного Облака открыто враждебны и Орде, и Альянсу.",al={"why do grimtotem hate horde","grimtotem vs thunder bluff","are grimtotem evil","почему зловещий тотем ненавидит орду","зловещий тотем и громовой утес","зловещий тотем злые"}},{q="Кто выдает задание «Наблюдение за Зловещим Тотемом»?",a="Дозорный утесов Долгорог дает задание на Заставе Вольного Ветра в Тысяче Игл, но лишь после того, как вы докажете свою надежность, выполнив прежние поручения заставы.",al={"who starts grimtotem spying","grimtotem spying quest giver","кто начинает наблюдение за зловещим тотемом","наблюдение за зловещим тотемом кто выдает"}},{q="Какие предварительные задания нужны перед этим?",a="Вы должны выполнить задания «Письмо на Заставу Вольного Ветра» и «Умиротворение кентавров», прежде чем Дозорный утесов Долгорог доверит вам шпионскую миссию против Зловещего Тотема.",al={"prereqs for grimtotem spying","how to unlock grimtotem spying","grimtotem spying chain","предыдущие задания наблюдения","как открыть наблюдение за зловещим тотемом","цепочка наблюдения за зловещим тотемом"}},{q="Что происходит, когда вы сдаете три тайные записки?",a="Прочитав их, Дозорный утесов Долгорог потрясен и называет новости мрачными. Он признает, что Застава Вольного Ветра должна срочно подготовить оборону против любого замысла, который готовит Зловещий Тотем.",al={"grimtotem spying completion","what do the notes say","завершение наблюдения за зловещим тотемом","что сказано в записках"}}},fp="16,381,16.574.0,34.512.0,13.410.1,49.216.0,36.216.0,46.303.0,37.166.0,54.181.0,53.213.1"}
P.entries["quest:5088"] = {n="Арикара",s="«Арикара» — завершение зловещего поручения, которое дает Магата Зловещий Тотем в Громовом Утесе. Убежденная, что древний ветряной змей преследует верховного вождя Кэрна Кровавого Копыта, старейшая шаманка посылает приключенцев Орды призвать и убить чудовище на погребальных шпилях Тысячи Игл.",h="«Арикара» — завершение зловещего поручения, которое дает Магата Зловещий Тотем в Громовом Утесе.",kw={"arikara","cairne bloodhoof","darkcloud pinnacle","incendia powder","magatha grimtotem","motega firemane","thousand needles","whitereach post","wind serpent","арикара","кэрн кровавое копыто","пик темного облака","порошок огненной агавы","магата зловещий тотем","мотега огненная грива","тысяча игл","застава белого плеса","ветряной змей"},ang={["class:Shaman"]="Шаманы-приключенцы заметят напряжение между стихийным ритуалом и политической интригой, а также нежелание Мотеги оспаривать непревзойденный духовный авторитет Магаты.",["faction:Horde"]="Воины Орды, поклявшиеся защищать Кэрна Кровавого Копыта, охотно выдвигаются в Тысячу Игл, чтобы устранить любую угрозу почтенному верховному вождю.",["race:Tauren"]="Для тауренов это задание затрагивает противоречие между древними обрядами предков и политическими переменами при Кэрне Кровавом Копыте, в которых посредничает вечно расчетливый клан Зловещего Тотема."},sec={{t="Зверь в дыму",b="Получив очищенный порошок огненной агавы, Магата Зловещий Тотем зачаровывает реагент, чтобы он служил катализатором призыва. Она предупреждает, что древние традиции тауренов слишком быстро изменились под влиянием нового союза Орды и навлекли месть Арикары, свирепого духа ветряного змея. Магата направляет героев на юг, в продуваемый ветрами каньон Тысячи Игл, и велит бросить порошок на ритуальный костер среди возвышенных мест погребения на Пике Темного Облака."},{t="Сомнения на Заставе Белого Плеса",b="Upon slaying the serpent on the burial needle and claiming its skin, adventurers deliver the remains to Motega Firemane at Whitereach Post. Rather than relief, Motega expresses genuine bewilderment. He finds it unbelievable that a primal spirit like Arikara would harbor malice toward Cairne Bloodhoof. Yet, unwilling to openly question Magatha's status as the tribe's most powerful shaman, Motega sets aside his suspicions and rewards the champion for protecting the chieftain."}},faq={{q="Кто такая Арикара?",a="Арикара — могущественный ветряной змей, которого призывают на вершине Пика Темного Облака в Тысяче Игл. Магата Зловещий Тотем утверждает, что зверя подтолкнули к мести современные отступления от традиций тауренов.",al={"what is arikara","arikara lore","who is the serpent","кто такая арикара","арикара предание","кто такой змей"}},{q="Почему Магата Зловещий Тотем хочет смерти Арикары?",a="Магата утверждает, что Арикара охотится на Кэрна Кровавого Копыта, верховного вождя тауренов. Она посылает вас уничтожить змея с помощью зачарованного порошка огненной агавы, пока он не стал угрозой для правителя Громового Утеса.",al={"magatha motivation","why kill arikara","why summon arikara","мотивы магаты","зачем убивать арикару","зачем призывать арикару"}},{q="Где находится священное пламя, чтобы призвать ее?",a="Незажженное священное пламя жизни находится на вершине уединенного шпиля на Пике Темного Облака в Тысяче Игл — возвышенном плато, где местные таурены хоронят своих мертвых.",al={"arikara location","where to summon arikara","sacred fire of life location","где арикара","где призвать арикару","где священное пламя жизни"}},{q="Почему Мотега Огненная Грива сомневается в этой охоте?",a="Magatha fears Arikara may be stalking Cairne and asks you to bring proof of the hunt to Motega. Motega's response is revealed when you deliver the remains.",al={"motega reaction","why is motega confused","cairne arikara make sense","реакция мотеги","почему мотега смущен","кэрн и арикара смысл"}},{q="Действительно ли Кэрну грозит опасность от Арикары?",a="Magatha says she fears Arikara may be stalking Cairne. The quest asks you to act on her warning; it does not establish the danger independently.",al={"was cairne really hunted","did arikara want cairne","magatha lying","охотились ли на кэрна","хотела ли арикара кэрна","магата лжет"}},{q="Какое задание предшествует этому в цепочке?",a="Это задание идет сразу после «Священного пламени», в котором приключенцы собирают огненную агаву в Кипящем озере в Тысяче Игл, чтобы Магата Зловещий Тотем зачаровала ее в порошок.",al={"arikara prereq","quest before arikara","sacred fire quest","предыдущее задание арикара","задание перед арикарой","задание священное пламя"}}},fp="7,290,20.477.0,24.478.1,15.199.0,45.201.0,47.170.0,45.155.1,42.144.1,41.182.0"}
P.entries["quest:509"] = {n="Эликсир агонии",s="В Мельнице Таррен аптекарь Лидон нанимает приключенцев Орды собрать ядовитые грибы на захваченной ферме в Предгорьях Хилсбрада. Эти ядовитые цветки Грязного Рыла — важное сырье для мрачных химических опытов Королевского фармацевтического общества. Полученная смесь должна помочь долгосрочному замыслу леди Сильваны уничтожить и живых, и Плеть.",h="В Мельнице Таррен аптекарь Лидон нанимает приключенцев Орды собрать ядовитые грибы на захваченной ферме в...",kw={"apothecary lydon","elixir of agony","hillsbrad","mudsnout blossom","nethander stead","new plague","royal apothecary society","tarren mill","аптекарь лидон","эликсир агонии","хилсбрад","цветок грязного рыла","владение нетандера","новая чума","королевское фармацевтическое общество","мельница таррен"},ang={["faction:Horde"]="Посланникам Орды в Мельнице Таррен приходится сочетать помощь союзникам-Отрекшимся с тревожной реальностью их химических опытов.",["profession:Herbalism"]="Травники и собиратели распознают в цветке Грязного Рыла редкий, чрезвычайно ядовитый грибной образец, процветающий на необработанной почве, оскверненной обитанием гноллов.",["race:Undead"]="Для агентов Отрекшихся помощь Лидону напрямую способствует жизненно важной работе Королевского фармацевтического общества по защите Лордерона и от человечества, и от Короля-лича."},sec={{t="Чума в разработке",b="Пока Плеть опустошает север, а Альянс держится в таких городах, как Южнобережье, Отрекшиеся ищут собственное расчетливое решение: создание особой смертоносной чумы. Аптекарь Лидон трудится в часовенных лабораториях Мельницы Таррен по поручению Темной Госпожи. Хотя сам он циничен и считает алхимию скучным трудом, Лидон усердно собирает в окрестностях сильные органические яды, чтобы варить эликсиры, способные ускорить взаимное уничтожение врагов Сильваны."},{t="Поля Владения Нетандера",b="К югу от Мельницы Таррен и к востоку от реки лежит Владение Нетандера — заброшенная человеческая ферма, захваченная свирепыми гноллами Грязного Рыла. Среди грязи и запущенной земли разрастаются странные зловонные грибы — цветки Грязного Рыла. Эти крупные едкие грибы содержат концентрированные органические яды, которые высоко ценит Королевское фармацевтическое общество. Чтобы добыть их, нужно пробиваться сквозь стаи гноллов или тихо пробираться мимо их неказистых лагерей."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — алхимик Королевского фармацевтического общества, расквартированный в Мельнице Таррен в Предгорьях Хилсбрада. Действуя от имени леди Сильваны Ветрокрылой, он занимается очисткой смертоносных смесей и разработкой новой чумы, способной сразить и живых смертных, и Плеть.",al={"lydon","who is lydon","apothecary lydon lore","лидон","кто такой лидон","аптекарь лидон предание"}},{q="Для чего нужны цветки Грязного Рыла?",a="Цветки Грязного Рыла — ядовитые зловонные грибы, собираемые во Владении Нетандера. Аптекарь Лидон использует их сильные природные токсичные свойства как основу для варки Эликсира агонии, части более широких исследований Отрекшихся в области химического и биологического оружия.",al={"mudsnout blossoms","what are the mushrooms for","blossom use","цветок грязного рыла","для чего грибы","применение цветков"}},{q="Где находится Владение Нетандера?",a="Владение Нетандера — заросшая ферма к югу от Мельницы Таррен, к востоку от большой реки, протекающей мимо Южнобережья. Ферму заняли агрессивные гноллы Грязного Рыла, которые охраняют поля, где растут грибы.",al={"nethander stead location","where is nethander stead","where are the gnolls","где владение нетандера","владение нетандера расположение","где гноллы"}},{q="Почему Отрекшиеся хотят создать новую чуму?",a="Леди Сильвана и Отрекшиеся ищут оружие, достаточно мощное, чтобы уничтожить и неумолимую Плеть, и враждебные живые расы Альянса. Создавая собственную чуму, Королевское фармацевтическое общество стремится обеспечить суверенитет и выживание Отрекшихся в Лордероне.",al={"why make a plague","forsaken plague reason","sylvanas plague","зачем делать чуму","причина чумы отрекшихся","чума сильваны"}},{q="Почему Лидон жалуется, что должен варить эти эликсиры?",a="Лидон несколько утомлен и мрачен: он замечает, что люди и Плеть и без посторонней помощи стремятся перебить друг друга. Однако поскольку леди Сильвана хочет ускорить их взаимное уничтожение, он выполняет приказы и продолжает варить смертоносные зелья.",al={"lydon attitude","why is lydon cynical","отношение лидона","почему лидон циничен"}},{q="Что происходит после сбора цветков?",a="Получив цветки Грязного Рыла, Лидон приступает к варке ядовитой смеси, и вскоре ему требуются дополнительные ингредиенты и испытания в полевых условиях, чтобы эликсир достиг максимальной смертоносности.",al={"next quest","what follows elixir of agony","следующее задание","что после эликсира агонии"}}},fp="15,377,22.526.0,29.448.0,24.280.0,36.270.0,33.226.0,48.283.0,59.277.0,43.197.0"}
P.entries["quest:513"] = {n="Эликсир агонии",s="Это поручение доставляет свежеразмятую Смесь Грязного Рыла аптекаря Лидона из Мельницы Таррен прямо в сердце Королевского фармацевтического общества в Подгороде. Мастеру аптекарю Фаранеллу нужна растительная масса, чтобы обработать ее коллоидом распада, продвигая разработку новой чумы Отрекшихся.",h="Это поручение доставляет свежеразмятую Смесь Грязного Рыла аптекаря Лидона из Мельницы Таррен прямо в сердце...",kw={"apothecarium","apothecary lydon","colloid of decay","elixir of agony","master apothecary faranell","mudsnout composite","new plague","undercity","апотекариум","аптекарь лидон","коллоид распада","эликсир агонии","мастер аптекарь фаранелл","смесь грязного рыла","новая чума","подгород"},ang={["faction:Horde"]="Орда полагается на территорию Отрекшихся для удержания севера Лордерона, и исследования Королевского фармацевтического общества — важная часть защиты этих уязвимых границ.",["race:Undead"]="Каждая партия сырого растительного материала, доставленная Фаранеллу, способствует конечному выживанию и суверенной обороне Отрекшихся и от живых, и от Плети."},sec={{t="Курьер в столицу",b="В постоянной работе Королевского фармацевтического общества региональные исследователи часто отправляют свои сырые находки в Подгород для особой очистки. Аптекарь Лидон размял местные цветки Грязного Рыла в смесь, но довести ее до смертоносной зрелости можно лишь с помощью передовых реагентов, которые хранятся только в лаборатории столицы."},{t="Спешка мастера",b="Мастер аптекарь Фаранелл работает под огромным давлением в Апотекариуме. Зажатая между постоянной тенью Плети на севере и агрессивным человеческим населением на юге, леди Сильвана Ветрокрылая потребовала могущественную новую чуму для защиты своего народа. Смесь Лидона дает Фаранеллу именно тот токсичный прорыв, которого ждет Темная Госпожа."}},faq={{q="Почему я должен доставить Смесь Грязного Рыла в Подгород?",a="У аптекаря Лидона в Мельнице Таррен нет особых реагентов, нужных для завершения этого этапа опыта. Мастер аптекарь Фаранелл хранит в Апотекариуме коллоид распада, которым нужно обработать Смесь Грязного Рыла, прежде чем она сможет перейти к следующей стадии.",al={"why go to undercity","mudsnout composite destination","why bring to faranell","зачем идти в подгород","куда нести смесь грязного рыла","зачем нести фаранеллу"}},{q="Кто такой Мастер аптекарь Фаранелл?",a="Мастер аптекарь Фаранелл возглавляет Королевское фармацевтическое общество из своей лаборатории в глубинах Подгорода. Он руководит всеми крупными химическими и алхимическими исследованиями Отрекшихся и подчиняется напрямую леди Сильване Ветрокрылой.",al={"who is faranell","master apothecary faranell lore","apothecarium leader","кто такой фаранелл","мастер аптекарь фаранелл предание","глава апотекариума"}},{q="Что за новая чума, о которой постоянно упоминают аптекари?",a="Новая чума — текущий проект Отрекшихся по приказу леди Сильваны. Она создается, чтобы уничтожить и живых, и нежить Плети, дав Отрекшимся абсолютное оружие против врагов.",al={"what is the new plague","forsaken plague project","why make a new plague","что такое новая чума","проект чумы отрекшихся","зачем делать новую чуму"}},{q="Где найти Мастера аптекаря Фаранелла?",a="Фаранелл обитает в Апотекариуме — юго-западном квартале Подгорода, целиком посвященном алхимии, изготовлению ядов и хирургическим опытам.",al={"where is faranell","faranell location","apothecarium location","где фаранелл","фаранелл расположение","где апотекариум"}},{q="Что пытается создать аптекарь Лидон?",a="Лидон готовит Эликсир агонии — крайне ядовитый токсин, сваренный из растений Хилсбрада и агентов распада, призванный доказать эффективность новых штаммов в полевых условиях.",al={"what is lydon making","elixir of agony purpose","lydon experiment","что делает лидон","назначение эликсира агонии","опыт лидона"}},{q="Почему Королевское фармацевтическое общество так торопится?",a="Отрекшиеся видят угрозы со всех сторон. Плеть Нордскола грозит захлестнуть их, а остатки человеческого сопротивления неустанно давят с юга, из-за чего срочно необходимо завершить разработку решающего биологического оружия.",al={"why rush","faranell busy","undercity threat","зачем спешка","фаранелл занят","угроза подгороду"}}},fp="15,304,24.340.0,20.392.0,62.260.0,34.225.0,56.214.0,44.160.0,42.179.0,46.242.0"}
P.entries["quest:5147"] = {n="Разыскивается: Арнак Зловещий Тотем",s="«Разыскивается: Арнак Зловещий Тотем» — награда за голову, объявленная Ордой на Заставе Вольного Ветра: требуется казнить жестокого изгнанника из племени Зловещего Тотема. Местные власти разыскивают Арнака за убийство и похищение человека на плато над каньоном.",h="«Разыскивается: Арнак Зловещий Тотем» — награда за голову, объявленная Ордой на Заставе Вольного Ветра...",kw={"arnak grimtotem","bounty","cliffwatcher longhorn","darkcloud pinnacle","freewind post","lakota windsong","outcast","thousand needles","арнак зловещий тотем","награда за голову","дозорный утесов долгорог","пик темного облака","застава вольного ветра","лакота песня ветра","изгой","тысяча игл"},ang={["faction:Horde"]="Застава Вольного Ветра — жизненно важная артерия Орды в Тысяче Игл, а уничтожение безжалостных отступников на Пике Темного Облака обеспечивает безопасность высот над дном каньона.",["race:Tauren"]="Для тауренов, верных Кэрну Кровавому Копыту, поиск Арнака — акт племенного правосудия: он должен ответить за убийство сородича и похищение Лакоты Песня Ветра, оскорбившие их традиции."},sec={{t="Жестокое преступление",b="Отношения между обычными тауренами Орды и замкнутым племенем Зловещего Тотема всегда были натянутыми, но Арнак зашел гораздо дальше политических трений. Объявленный изгоем, Арнак убил таурена и похитил его сестру, Лакоту Песня Ветра. В ответ на эти гнусные деяния Дозорный утесов Долгорог с Заставы Вольного Ветра объявил открытую награду за смерть таурена-изгоя."},{t="Пик Темного Облака",b="Арнак укрылся на высоких скалах Пика Темного Облака — обширной сети веревочных мостов и стоянок на плато, которые занимает клан Зловещего Тотема, неподалеку от входа в Курганы Иглошкурых. Вместе с Арнаком на этих продуваемых ветрами высотах заперта его пленница Лакота Песня Ветра. Она ждет спасения от любого, кто достаточно храбр, чтобы пробиться через мосты Зловещего Тотема."}},faq={{q="Кто такой Арнак Зловещий Тотем?",a="Арнак Зловещий Тотем — печально известный таурен-изгой, совершивший убийство и похитивший Лакоту Песня Ветра. Из-за его жестоких преступлений Застава Вольного Ветра назначила награду за его голову.",al={"who is arnak","arnak grimtotem lore","who is the wanted tauren","кто такой арнак","арнак зловещий тотем предыстория","кто разыскиваемый таурен"}},{q="Где найти Арнака Зловещего Тотема?",a="Он находится высоко на северных скалистых плато Пика Темного Облака в Тысяче Игл. Туда можно подняться по извилистой тропе к югу от Великого Подъемника и пересечь высокие деревянные мосты в сторону Курганов Иглошкурых.",al={"where is arnak","arnak grimtotem location","how to find arnak","где арнак","арнак зловещий тотем местонахождение","как найти арнака"}},{q="Кто такая Лакота Песня Ветра?",a="Лакота Песня Ветра — пленница-таурен, которую Арнак держит на Пике Темного Облака. Ее брата Арнак убил во время похищения, и она остается на плато, пока с Арнаком не разберутся.",al={"who is lakota","lakota windsong story","кто такая лакота","лакота песня ветра история"}},{q="Кто выплачивает награду?",a="Наградой ведает Дозорный утесов Долгорог на Заставе Вольного Ветра. Он награждает путников, которые приносят отрубленное копыто Арнака как доказательство того, что таурен-изгой предан правосудию.",al={"who turns in arnak","bounty turn in","cliffwatcher longhorn reward","кто принимает арнака","сдать награду","дозорный утесов долгорог награда"}},{q="Действует ли Арнак официально от имени племени Зловещего Тотема?",a="В объявлении Арнак прямо назван изгоем, что указывает: он действовал вне любых племенных законов. Тем не менее он укрылся в оплоте Зловещего Тотема — на Пике Темного Облака.",al={"is arnak with grimtotem","arnak tribe status","арнак со зловещим тотемом","статус арнака в племени"}},{q="Какое доказательство нужно для получения награды?",a="Охотникам нужно отрубить Копыто Арнака и вернуть его Дозорному утесов Долгорогу на Заставе Вольного Ветра, чтобы подтвердить его смерть и получить награду.",al={"what do i bring cliffwatcher longhorn","arnak proof","arnaks hoof","что принести дозорному утесов долгорогу","доказательство арнака","копыто арнака"}}},fp="24,219,16.400.0,18.352.0,23.168.0,35.217.0,23.192.0,29.172.0,52.190.0,43.128.0"}
P.entries["quest:515"] = {n="Эликсир агонии",s="Это поручение продолжает разработку новой чумы Королевского фармацевтического общества: курьер отправляется из Подгорода обратно в Мельницу Таррен. Мастер аптекарь Фаранелл усиливает Микстуру Грязного Рыла Лидона собственными составами гниения и требует прибрежные реагенты и алхимические зелья для запуска смертоносного варева.",h="Это поручение продолжает разработку новой чумы Королевского фармацевтического общества: курьер отправляется...",kw={"daggerspine","elixir of agony","faranell","lydon","mudsnout","tarren mill","torn fin","umpi","undercity","пронзающий гребень","эликсир агонии","фаранелл","лидон","грязное рыло","мельница таррен","рваный плавник","ампи","подгород"},ang={["faction:Horde"]="Мельница Таррен находится на грани постоянных пограничных стычек с Альянсом Южнобережья; ядовитые опыты Лидона призваны изменить баланс сил в регионе.",["race:Undead"]="Каждый очищенный реагент в этой цепочке заданий приближает Королевское фармацевтическое общество к исполнению желания леди Сильваны — создать абсолютное оружие против живых."},sec={{t="Коллоид гниения",b="Когда полевая работа аптекаря Лидона дала мощный состав из Цветков Грязного Рыла, собранных во Владении Нетандера, занятом гноллами, он отправил его прямо в Апотекариум в Подгороде. Мастер аптекарь Фаранелл, глава Королевского фармацевтического общества, сразу понял мрачный потенциал смеси. Обрадованный ее ядовитыми свойствами, Фаранелл добавил в нее свой особый коллоид гниения, а затем изложил, какие катализаторы нужны, чтобы превратить ее в полноценное оружие."},{t="Катализаторы с побережья",b="Для активации нестабильных заразных агентов нужны точные реагенты, которые Лидон должен собрать в Мельнице Таррен. Помимо восстанавливающего зелья из Крепкой крови тролля, питающего и стабилизирующего химическую реакцию, Фаранеллу требуются органические компоненты с южного берега Хилсбрада: чешуя змеевидных нага Пронзающего Гребня и глаза мурлоков Рваного Плавника."},{t="Жестокость в Мельнице Таррен",b="В Мельнице Таррен Лидон коротает часы ожидания в мрачных забавах: он регулярно травит, заражает и поднимает из мертвых свою несчастную подопытную нежить — Ампи. Доставка обогащенной смеси Фаранелла и прибрежных катализаторов приближает аптекаря к конечной цели — созданию нового штамма мучительной порчи, чтобы обрушить его на живые поселения Хилсбрада."}},faq={{q="Зачем для чумы нужен восстанавливающий эликсир из крови тролля?",a="В аптекарских смесях часто используют регенерирующие вещества, чтобы поддерживать, питать и быстро изменять агрессивные биологические агенты. Восстанавливающие свойства Крепкой крови тролля позволяют ядовитым культурам жить достаточно долго, чтобы вступить в реакцию с другими активными тканями.",al={"why troll blood","strong trolls blood purpose","trolls blood elixir plague","зачем кровь тролля","назначение крепкой крови тролля","эликсир из крови тролля чума"}},{q="Где найти чешую нага Пронзающего Гребня?",a="Чешую снимают с враждебных нага Пронзающего Гребня, обитающих на восточных пляжах Предгорий Хилсбрада, на берегу к востоку от города Альянса Южнобережье.",al={"daggerspine scales location","where are naga scales","where to get scales","где чешуя пронзающего гребня","где чешуя нага","где взять чешую"}},{q="Где добыть глаза мурлоков Рваного Плавника?",a="Глаза собирают у мурлоков Рваного Плавника, которые живут племенами на западном побережье Предгорий Хилсбрада, к западу от Южнобережья.",al={"torn fin eye location","where are torn fin murlocs","murloc eyes hillsbrad","глаза рваного плавника","где мурлоки рваного плавника","глаза мурлоков хилсбрад"}},{q="Кто такая Ампи?",a="Ампи — лягушка, которую аптекарь Лидон держит в Мельнице Таррен как своего «помощника». В свободные часы Лидон использует ее как расходного подопытного: раз за разом подвергает смертельным ядам и болезням, а потом снова воскрешает.",al={"who is umpi","umpi hillsbrad","lydon assistant umpi","кто такая ампи","ампи хилсбрад","помощница лидона ампи"}},{q="Почему Мастер аптекарь Фаранелл участвует в этом местном проекте?",a="Как глава Королевского фармацевтического общества, Фаранелл руководит всеми исследованиями новых биологических агентов и чум. Полевые аптекари вроде Лидона отправляют многообещающие находки прямо Фаранеллу в Подгород для доработки и одобрения.",al={"why faranell","master apothecary faranell role","royal apothecary society leader","почему фаранелл","роль мастера аптекаря фаранелла","глава королевского фармацевтического общества"}},{q="Что такое Микстура Грязного Рыла?",a="Это неочищенный ядовитый состав, который Лидон растер из Цветков Грязного Рыла — зловонных грибов, собранных во Владении Нетандера в Предгорьях Хилсбрада, кишащем гноллами. Заметив его необычайную заразность, Лидон отправил его в Подгород, где Фаранелл смешал его с коллоидами гниения, чтобы создать более смертоносную заразу.",al={"mudsnout mixture","gnoll poison","mudsnout composite","микстура грязного рыла","яд гноллов","состав грязного рыла"}}},fp="15,315,18.470.0,24.410.0,22.380.1,63.272.0,39.195.0,37.152.0,12.233.0,65.251.0,29.299.0"}
P.entries["quest:5151"] = {n="Механизм гипервместимости",s="После смертоносной засады кентавров на торговый караван в Тысяче Игл гоблин-изобретатель Визло Фингалет остался единственным выжившим. Отчаянно желая вернуть свое драгоценное изобретение, он нанимает авантюристов, чтобы те проникли в обломки, открыли железную клетку и сняли механизм с шеи свирепого хищника в клетке.",h="После смертоносной засады кентавров на торговый караван в Тысяче Игл гоблин-изобретатель Визло Фингалет...",kw={"centaur caravan","enraged panther","goblin engineering","hypercapacitor gizmo","panther cage key","thousand needles","whitereach post","wizlo bearingshiner","караван кентавров","разъяренная пантера","гоблинская инженерия","механизм гипервместимости","ключ от клетки пантеры","тысяча игл","застава белого плеса","визло фингалет"},ang={["class:Hunter"]="Разъяренная пантера в разбитом караване — необычайно грозный зверь, достаточно свирепый, чтобы напугать целый боевой отряд кентавров-мародеров.",["faction:Horde"]="Разведчики и путники Орды, действующие с Заставы Белого Плеса, непрерывно сражаются с хищными кланами кентавров, угрожающими торговым путям через центральный Калимдор.",["profession:Engineering"]="Лихорадочная погоня Визло за изобретением, назначение которого он толком не помнит, — пример хаотичной философии проб и ошибок, свойственной классической гоблинской инженерии."},sec={{t="Засада в Тысяче Игл",b="Караваны, идущие под высокими песчаными шпилями Тысячи Игл, проходят опасный путь. Враждебные кентавры рыщут по дну каньона, яростно охраняя свою территорию и нападая на всех путников, достаточно смелых, чтобы здесь пройти. Когда один такой торговый караван был разгромлен к северу от Заставы Белого Плеса, кентавры перебили путников и разграбили повозки, оставив лишь гоблина Визло Фингалета, который добрался до безопасного места, прихрамывая."},{t="Неожиданный страж",b="In the chaos of the raid, the centaur looted nearly every valuable scrap, but they gave one ruined wagon a wide berth. Bound inside a sturdy transport cage was a ferocious, enraged panther with Wizlo's prized hypercapacitor gizmo fastened directly around its neck. Daunted by the predator's snarling fury, the centaur abandoned the cage intact, forcing Wizlo to entrust its key to brave mercenaries capable of slaying the beast and reclaiming his gadget."},{t="Амбиции изобретателя",b="Как и подобает гоблину, страсть Визло к механическим чудесам часто опережает практическое понимание. Хотя он называет Механизм гипервместимости своим лучшим творением и рискует жизнями, чтобы вернуть его из лап верховного хищника, после возвращения он признает, что ему еще предстоит повозиться с ним, чтобы понять, что он на самом деле делает."}},faq={{q="Кто такой Визло Фингалет?",a="Визло Фингалет — гоблин-изобретатель и торговец, укрывшийся на Заставе Белого Плеса после того, как его караван был подвергнут засаде и уничтожен кентаврами на дне каньона Тысячи Игл.",al={"who is wizlo","wizlo bearingshiner lore","quest giver wizlo","кто такой визло","визло фингалет предыстория","визло персонаж, выдающий задания"}},{q="Почему механизм оказался на шее пантеры?",a="Во время перевозки или в хаосе засады кентавров устройство оказалось закрепленным на шее плененного зверя. Поскольку пантера была так страшна, нападавшие кентавры отказались прикасаться к клетке, невольно сделав хищника стражем устройства.",al={"why does the panther have the gizmo","panther necklace","collar gizmo","почему у пантеры механизм","ожерелье пантеры","механизм на шее"}},{q="Где находится разбитый караван?",a="Разбитый караван лежит к северу от Заставы Белого Плеса в Тысяче Игл, среди обломков повозок, окруженный враждебными лагерями кентавров.",al={"caravan location","where to find panther cage","cage location","где караван","где найти клетку с пантерой","где клетка"}},{q="Почему кентавры не разграбили клетку?",a="По словам Визло, разъяренная пантера настолько свирепа, что даже безжалостные кентавры-мародеры дрожали в ее присутствии и предпочли оставить зверя запертым в клетке, не рискуя ее открывать.",al={"why centaur left panther","centaur afraid of panther","why is cage untouched","почему кентавры оставили пантеру","кентавры боятся пантеры","почему клетка цела"}},{q="Что на самом деле делает Механизм гипервместимости?",a="Визло называет его своим лучшим механизмом, но, получив его обратно, признается, что ему еще нужно время, чтобы изучить его и повозиться с ним, чтобы понять, какую функцию он выполняет.",al={"what does gizmo do","hypercapacitor function","what is the gizmo","что делает механизм","функция гипервместимости","что за механизм"}},{q="Кому принадлежит Застава Белого Плеса?",a="Застава Белого Плеса — поселение тауренов, союзное Орде, расположенное среди плато каньона, чтобы следить за действиями кентавров и давать безопасный приют путникам Орды.",al={"whitereach post faction","is whitereach horde","фракция заставы белого плеса","застава белого плеса орда ли"}}},fp="20,320,21.433.0,20.454.0,19.336.1,27.185.0,43.260.0,37.143.0,37.198.0,47.187.1,29.165.0"}
P.entries["quest:516"] = {n="Погибель Берена",s="«Погибель Берена» — задание Орды, которое выдает жрец Тени Алистер из Гробницы. Агенты Отрекшихся узнали о тайном сборище Плети в уединенной пещере на юге холмов Серебряного бора и хотят уничтожить ее воинов до начала наступления.",h="«Погибель Берена» — задание Орды, которое выдает жрец Тени Алистер из Гробницы.",kw={"ambermill","beren's peril","berens peril","ravenclaw drudger","ravenclaw guardian","scourge","shadow priest allister","silverpine forest","the sepulcher","янтарная мельница","погибель берена","чернорабочий когтя ворона","страж когтя ворона","плеть","жрец тени алистер","серебряный бор","гробница"},ang={["class:Priest"]="Выполняя приказы жреца Тени Алистера, темные заклинатели помогают укреплять власть Гробницы, истребляя соперничающих ужасов из нежити.",["faction:Horde"]="Зачистка скрытых очагов Плети на границах Серебряного бора помогает укрепить положение северного Лордерона для всей Орды.",["race:Undead"]="Для Отрекшихся искоренение остатков Плети, таких как в Погибели Берена, — вопрос выживания, укрепляющий их суверенитет вопреки остаточной власти Короля-лича."},sec={{t="Упреждающий удар",b="Жрецу Тени Алистеру в Гробнице стало известно, что безмозглые слуги Короля-лича собираются в глубине южной части Серебряного бора. Если не вмешаться, эти силы Плети станут непосредственной угрозой для действий Отрекшихся по всему региону. Не дожидаясь нападения, Алистер велит разведчикам действовать первыми и уничтожить скопище в его укромном логове, пока оно не пришло в движение."},{t="Тайная пещера",b="Погибель Берена — малозаметная сеть пещер в холмах к югу от Янтарной мельницы, поселения под покровительством Даларана. Из-за коварной местности пещеру легко не заметить: к ней можно подойти, лишь обогнув южные склоны. В ее тенях обитают чернорабочие и стражи из Когтя Ворона — закрепившиеся остатки чумы, уничтожение которых помогает Отрекшимся удерживать шаткую власть над лесом."}},faq={{q="Что такое Погибель Берена?",a="Погибель Берена — уединенная пещера в гористых холмах южной части Серебряного бора, к югу от Янтарной мельницы. Она служит убежищем для остатков Плети — нежити Когтя Ворона.",al={"berens peril","where is berens peril","what is this cave","погибель берена","где погибель берена","что за пещера"}},{q="Кто выдает задание, связанное с Погибелью Берена?",a="Жрец Тени Алистер, находящийся в Гробнице в Серебряном бору, дает задание искателям приключений из Орды, узнав, что враждебная нежить готовит наступление из этой пещеры.",al={"who gives berens peril","quest giver berens peril","shadow priest allister quest","кто дает погибель берена","персонаж, выдающий задание погибель берена","задание жреца тени алистера"}},{q="Почему Отрекшиеся нападают там на нежить?",a="Нежить в Погибели Берена верна Королю-личу и входит в состав Плети. Отрекшиеся освободились от власти Короля-лича и активно борются за то, чтобы очистить свои земли от его оставшихся приспешников.",al={"why kill undead","why fight ravenclaw","arent forsaken undead","почему убивать нежить","почему сражаться с когтем ворона","разве отрекшиеся не нежить"}},{q="Как найти вход в пещеру?",a="Пещера скрыта в холмах к югу от Янтарной мельницы. Из-за крутых хребтов к входу нужно подходить с южной стороны холмов, а не напрямую с севера.",al={"how to get to berens peril","cave entrance location","where is the cave entrance","как добраться до погибели берена","где вход в пещеру","расположение входа в пещеру"}},{q="Какие враги обитают в Погибели Берена?",a="В пещере обитают рабы Плети, в частности чернорабочие Когтя Ворона и стражи Когтя Ворона, которые, по всей видимости, собираются для нападения на ближайшие поселения.",al={"berens peril mobs","what is inside berens peril","погибель берена мобы","что внутри погибели берена"}},{q="Какую роль играет Даларан в этом задании?",a="Даларан не играет прямой роли в самом задании, хотя находящуюся неподалеку Янтарную мельницу занимают человеческие маги из Даларана. Алистер упоминает их лишь как ориентир, чтобы разведчики нашли тайную пещеру.",al={"dalaran connection","ambermill connection","связь с даларан","связь с янтарной мельницей"}}},fp="13,289,19.433.0,15.428.0,22.200.0,41.184.0,48.209.0,41.183.0,35.168.0,44.196.0"}
P.entries["quest:517"] = {n="Эликсир агонии",s="Это задание — четвертая глава неустанной работы аптекаря Лидона над разрушительным ядом Отрекшихся в Мельнице Таррен. Когда смертоносный Эликсир агонии наконец сварен, Лидон отправляет героев Орды в Дун Гарок похитить бочонок дворфийского «Шиндигера» для доставки.",h="Это задание — четвертая глава неустанной работы аптекаря Лидона над разрушительным ядом Отрекшихся в Мельнице...",kw={"apothecary lydon","dun garok","dwarves","elixir of agony","hillsbrad","shindigger stout","tarren mill","umpi","аптекарь лидон","дун гарок","дворфы","эликсир агонии","хилсбрад","шиндигер","мельница таррен","ампи"},ang={["class:Rogue"]="Незаметно проскользнуть по людным столовым Дун Гарока — образец скрытного воровства прямо под носом у горных пехотинцев.",["faction:Horde"]="Подрыв присутствия Альянса в Дун Гароке помогает Мельнице Таррен удерживать шаткие позиции перед лицом неослабевающих угроз с юга.",["race:Dwarf"]="Превращение традиционного дворфийского эля в сосуд для химической бойни — глубокое оскорбление мастерства Стальгорна.",["race:Undead"]="Каждая партия, доведенная Лидоном до совершенства, приближает Отрекшихся к превращению смерти в оружие против живых врагов, подступающих к Лордерону."},sec={{t="Горькое варево",b="В сырых закоулках Мельницы Таррен аптекарь Лидон неустанно трудится на благо Королевского фармацевтического общества и леди Сильваны. Собрав смертоносные ингредиенты по всему Хилсбраду, он закончил свое новое зелье. Лидон не намерен тратить столь сильный состав на лягушек или бродячих собак: ему нужна настоящая проверка на живых противниках."},{t="Проникновение в Дун Гарок",b="Для своего опыта Лидону нужно неприметное средство доставки. К югу от Хилсбрада дворфы Стальгорна укрепили оплот Дун Гарок. Лидон велит агентам Орды проникнуть в подземные казармы и столовые, проскользнуть мимо дворфийских ружей и топоров и стащить ценный бочонок «Шиндигера»."},{t="Рецепт катастрофы",b="Лидон собирается подмешать свой смертоносный яд прямо в любимый напиток дворфов. После того как эликсир попадет в украденный бочонок, его можно будет подсунуть ничего не подозревающей цели под видом праздничного угощения, превратив любимый дворфийский стаут в орудие ужасной агонии."}},faq={{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — алхимик из числа Отрекшихся, находящийся в Мельнице Таррен. Представляя Королевское фармацевтическое общество, он проводит опыты по созданию смертоносных чум и эликсиров для Королевы банши, леди Сильваны.",al={"lydon","who gives this quest","apothecary lydon lore","лидон","кто дает это задание","аптекарь лидон предыстория"}},{q="Зачем Лидону бочонок «Шиндигера»?",a="Лидон хочет испытать готовый Эликсир агонии на живых целях. Подмешав яд в бочонок популярного дворфийского эля, он получает скрытый и действенный способ отравить своих жертв.",al={"why dwarven beer","why shindigger stout","purpose of the keg","почему дворфийское пиво","почему шиндигер","зачем бочонок"}},{q="Где находится Дун Гарок?",a="Дун Гарок — сильно укрепленный дворфийский редут на юго-востоке Предгорий Хилсбрада; его занимают горные пехотинцы и ружейники Стальгорна, охраняющие свои северные интересы.",al={"where is dun garok","dun garok location","where do i find the keg","где дун гарок","расположение дун гарока","где найти бочонок"}},{q="Кто такой Ампи?",a="Ампи — помощник аптекаря Лидона в Мельнице Таррен. Лидон шутливо замечает, что когда в лаборатории открывают банки с формальдегидом, Ампи заметно нервничает.",al={"umpi","who is umpi","lydon assistant","ампи","кто такой ампи","помощник лидона"}},{q="Какова конечная цель Эликсира агонии?",a="Эликсир агонии — экспериментальный яд, созданный Королевским фармацевтическим обществом для истребления живых; он служит кампании Отрекшихся по защите Лордерона от опорных пунктов людей и дворфов.",al={"what does elixir of agony do","plague purpose","forsaken poison goal","что делает эликсир агонии","цель чумы","цель яда отрекшихся"}},{q="Что будет после получения бочонка?",a="Когда бочонок окажется у вас, Лидон подмешает в «Шиндигер» ядовитый эликсир и поручит вам доставить отравленный эль ничего не подозревающей подопытной цели.",al={"next quest","what after dun garok","elixir part 5","следующее задание","что после дун гарока","эликсир часть 5"}}},fp="15,277,13.380.0,22.329.0,21.278.1,24.209.0,46.194.0,27.175.0,12.159.0,49.199.0,41.158.1"}
P.entries["quest:52"] = {n="Защита границы",s="«Защита границы» — задание Альянса, которое выдает Стражник Томас у восточного моста в Элвиннском лесу. Из-за ослабления военного присутствия Штормграда у границы дикие хищники осмелели и донимают путников и рабочих Лесопилки Восточной долины. Стражнику Томасу нужны умелые герои, чтобы проредить волков и медведей, угрожающих восточной границе.",h="«Защита границы» — задание Альянса, которое выдает Стражник Томас у восточного моста в Элвиннском лесу.",kw={"eastvale logging camp","elwynn forest","gray forest wolf","guard thomas","protect the frontier","prowler","young forest bear","лесопилка восточной долины","элвиннский лес","серый лесной волк","стражник томас","защита границы","подкрадывающийся хищник","молодой лесной медведь"},ang={["class:Hunter"]="Волки и медведи, рыщущие на востоке Элвиннского леса, — первое испытание навыков выслеживания и меткости на свирепой местной дичи.",["faction:Alliance"]="Обеспечение безопасности восточных дорог помогает сохранить поставки древесины из Восточной долины, поддерживая восстановление и оборону по всем землям Альянса."},sec={{t="Ослабевшая оборона",b="Хотя в Златоземье и Долине Североземья заметен гарнизон Штормграда, дальний восточный край Элвиннского леса защищен куда хуже. Стражник Томас стоит на посту у моста через реку и остается одним из немногих часовых между обжитыми землями и опасной глушью. Из-за нехватки ресурсов по всему королевству одинокие стражники полагаются на добровольцев, чтобы сохранить важные торговые пути."},{t="Угроза хищников",b="Лесопилка Восточной долины важна для поставок древесины в Штормград, но рубка деревьев у опушки приводит дровосеков к прямому столкновению с местной живностью. Подкрадывающиеся хищники, серые лесные волки и молодые лесные медведи становятся все агрессивнее и бродят возле дорог и лесных складов. Сокращение их числа временно облегчает положение рабочих, хотя Стражник Томас подозревает, что невидимая угроза в глубине леса гонит зверей к поселениям."}},faq={{q="Кто выдает задание «Защита границы»?",a="Задание дает Стражник Томас. Он стоит у восточного моста на главной дороге через Элвиннский лес и охраняет границу между глубиной леса и Восточной долиной.",al={"quest giver protect the frontier","who starts protect the frontier","guard thomas quest","кто выдает защиту границы","кто начинает защиту границы","задание стражника томаса"}},{q="Почему волки и медведи нападают на границу?",a="Агрессивные хищники часто выходят на дороги и рабочие участки возле Лесопилки Восточной долины. Хотя волки и медведи по природе территориальны, Стражник Томас отмечает, что нечто в глубине окрестной глуши, судя по всему, беспокоит их и гонит к людям.",al={"why are bears aggressive","why are wolves attacking eastvale","animal attacks elwynn","почему медведи агрессивны","почему волки нападают на восточную долину","нападения животных элвинн"}},{q="Где находится Лесопилка Восточной долины?",a="Лесопилка Восточной долины находится на востоке Элвиннского леса, чуть восточнее моста Стражника Томаса. Она поставляет необходимый лес для Штормграда и приграничных поселений.",al={"eastvale location","where is logging camp elwynn","eastvale camp","расположение восточной долины","где лесопилка элвинн","лагерь восточной долины"}},{q="Почему Стражник Томас охраняет мост в одиночку?",a="Регулярная армия и городская стража Штормграда крайне малочисленны на просторах королевства. На сторожевых постах у рек и дальних перекрестков часто стоят один-два стражника, поэтому для борьбы с крупными угрозами со стороны зверей приходится рассчитывать на странствующих героев.",al={"why is guard thomas alone","guard thomas post","stormwind guards eastvale","почему стражник томас один","пост стражника томаса","стража штормграда восточная долина"}},{q="Каких животных нужно истребить в этом задании?",a="Вам нужно убить восемь волков (подкрадывающихся хищников или серых лесных волков) и пять молодых лесных медведей, бродящих по лесам восточной части Элвиннского леса.",al={"protect the frontier targets","wolves and bears to kill","what mobs for protect the frontier","цели защиты границы","волки и медведи для убийства","какие мобы для защиты границы"}},{q="Что происходит после истребления зверей?",a="Доклад Стражнику Томасу приносит его благодарность и делает путь для лесозаготовительных караванов безопаснее. Однако он опасается, что темное влияние, растревожившее зверей, может принести лесу новые беды.",al={"protect the frontier follow up","turn in protect the frontier","продолжение защиты границы","сдать защиту границы"}}},fp="20,389,18.434.0,20.498.0,41.186.0,48.288.0,35.155.0,46.294.0,45.152.0,41.219.0"}
P.entries["quest:5261"] = {n="Иган Меховщик",s="Это короткое вводное задание направляет новоприбывших рекрутов в Долине Североземья к Игану Меховщику, местному скорняку, работающему у Аббатства Североземья. Поскольку у границ долины хищников становится все больше, Игану нужны умелые искатели приключений, чтобы охотиться на лесных волков и добывать шкуры.",h="Это короткое вводное задание направляет новоприбывших рекрутов в Долине Североземья к Игану Меховщику...",kw={"deputy willem","eagan peltskinner","northshire abbey","northshire valley","timber wolves","wolves across the border","заместитель судьи виллем","иган меховщик","аббатство североземья","долина североземья","лесные волки","волки за границей"},ang={["faction:Alliance"]="Каждое небольшое дело в Североземье помогает защитить родные земли Штормграда, пока основная армия королевства занята в других местах.",["race:Human"]="Для юных людей, покидающих Аббатство Североземья, помощь местным ремесленникам вроде Игана — первый урок защиты родины."},sec={{t="Разговор со скорняком",b="Долина Североземья может казаться пасторальной, но ее тихие сады и поля окружены диким лесом, кишащим лесными волками. Заместитель судьи Виллем часто направляет рекрутов за стены аббатства к Игану Меховщику, который работает неподалеку на землях аббатства. Иган рад занять новичков делом: проредить агрессивные стаи и добыть ценные шкуры для своего ремесла."},{t="Беда на границе",b="Растущее число волков вокруг Североземья — не просто досада: оно угрожает работникам, послушникам и обозам, идущим в долину и из нее. Направляя юных защитников к Игану, штормградские маршалы решают сразу две задачи: ближайшие тропы остаются безопасными, а немногочисленных оставшихся стражей гарнизона, и без того встревоженных обстановкой в Элвиннском лесу, не приходится отвлекать."}},faq={{q="Кто посылает вас поговорить с Иганом Меховщиком?",a="Заместитель судьи Виллем, стоящий у входа в Аббатство Североземья, направляет перспективных рекрутов к Игану, после того как знакомит их с проблемами безопасности долины.",al={"who gives this quest","who starts eagan peltskinner quest","кто выдает это задание","кто дает задание игана меховщика"}},{q="Где находится Иган Меховщик?",a="Иган Меховщик стоит у внешних стен Аббатства Североземья, с левой стороны главного здания, среди своих сушильных рам и снаряжения.",al={"where is eagan","eagan peltskinner location","find eagan","где иган","иган меховщик местонахождение","найти игана"}},{q="С чем нужно помочь Игану Меховщику?",a="Иган ищет искателя приключений, готового охотиться на агрессивных лесных волков, рыщущих в окрестных лесах, и принести их шкуры, что помогает очистить окрестности Североземья.",al={"what does eagan want","why hunt wolves","eagan purpose","что нужно игану","зачем охотиться на волков","цель игана"}},{q="Можно ли пропустить это задание и поговорить с Иганом напрямую?",a="Да. Иган предлагает свое охотничье задание любому, кто к нему подойдет. Это направляющее задание лишь дает формальную рекомендацию от Заместителя судьи Виллема.",al={"can i skip eagan quest","wolves across the border directly","можно ли пропустить задание игана","волки за границей напрямую"}},{q="Почему в Долине Североземья так много волков?",a="Долина Североземья граничит с густыми нетронутыми лесами, где свободно бродят лесные волки. Поскольку местные стражи рассеяны и заняты другими угрозами по всему королевству, популяция диких хищников росла без помех.",al={"why wolves in northshire","wolf problem elwynn","почему волки в североземье","проблема волков элвинн"}},{q="Какое задание следует после разговора с Иганом Меховщиком?",a="Разговор с Иганом сразу ведет к его просьбе охотиться на лесных волков за границей земель аббатства и собирать их прочные шкуры.",al={"next quest after eagan","what does eagan offer next","следующее задание после игана","что предлагает иган дальше"}}},fp="17,299,23.367.0,24.376.0,46.176.0,35.153.0,43.185.0,51.164.0,50.219.0,50.146.0"}
P.entries["quest:527"] = {n="Битва за Хилсбрад",s="Битва за Хилсбрад — первый удар кампании Отрекшихся по уничтожению человеческого поселения Хилсбрад. Это задание, выданное Верховным палачом Дарталией по приказу Вариматраса, направлено против крестьян и построек северных Хилсбрадских полей, чтобы лишить город продовольствия.",h="Битва за Хилсбрад — первый удар кампании Отрекшихся по уничтожению человеческого поселения Хилсбрад.",kw={"battle of hillsbrad","darthalia","farmer getz","farmer ray","hillsbrad fields","new plague","tarren mill","varimathras","битва за хилсбрад","дарталия","фермер гетц","фермер рэй","хилсбрадские поля","новая чума","мельница таррен","вариматрас"},ang={["faction:Alliance"]="Расправа над северными поселенцами показывает ужасающую реальность, с которой сталкиваются оставшиеся людские анклавы в Лордероне.",["faction:Horde"]="Пока Тралл проповедует честь, северная кампания, ведущаяся из Мельницы Таррен, раскрывает бескомпромиссную жестокость войны Сильваны против Альянса.",["race:Undead"]="Для Отрекшихся возвращение Лордерона означает истребление каждого уцелевшего очага живых, считающих их родину украденной землей."},sec={{t="Голод для сопротивления",b="Мельница Таррен — южный оплот империи Отрекшихся, обращенный к укрепившемуся населению людей, цепляющемуся за Предгорья Хилсбрада. Верховный палач Дарталия действует по строгим указаниям Вариматраса из Подгорода. Ее стратегия — полное истощение: прежде чем идти прямо на хорошо защищенный город Хилсбрад, она приказывает методично разрушить его земледелие. Удар по северным полям лишает человеческое ополчение важных припасов и сеет хаос среди усадеб."},{t="Сдерживающий бой",b="Более широкая кампания против людей в Хилсбраде служит мрачной тактической цели. Пока армии Отрекшихся сковывают и обескровливают местных защитников, Королевское фармацевтическое общество неустанно трудится над новой чумой, способной уничтожить и живых, и Плеть. Верховный палач Дарталия считает эти ранние стычки и гибель местных землевладельцев, таких как Фермер Рэй и Фермер Гетц, необходимыми шагами для подавления человеческой заразы, пока это конечное оружие не будет готово."}},faq={{q="Почему Отрекшиеся нападают на простых крестьян?",a="Крестьяне и работники ферм на Хилсбрадских полях — логистическая основа города Хилсбрад. Выкашивая их рабочую силу и убивая видных землевладельцев, таких как Фермер Рэй и Фермер Гетц, Отрекшиеся отрезают человеческий гарнизон от продовольствия и ослабляют его оборону перед прямым штурмом.",al={"why kill farmers","hillsbrad farm targets","why attack farms","зачем убивать крестьян","цели на фермах хилсбрада","зачем нападать на фермы"}},{q="Кто приказывает совершить это нападение?",a="Задание выдает Верховный палач Дарталия, военачальница Отрекшихся в Мельнице Таррен. Она подчиняется непосредственно повелителю ужаса Вариматрасу и леди Сильване Ветрокрылой.",al={"who gives quest","darthalia orders","who is darthalia","кто выдает задание","приказы дарталии","кто такая дарталия"}},{q="Какую роль в этой кампании играет Королевское фармацевтическое общество?",a="Дарталия отмечает, что обычная война против людей нужна, чтобы подавить живое население и выиграть время, пока аптекари Отрекшихся создают новую чуму, призванную полностью уничтожить их врагов.",al={"why the new plague","apothecaries hillsbrad","forsaken plague plan","зачем новая чума","аптекари хилсбрад","план чумы отрекшихся"}},{q="Где находятся Фермер Рэй и Фермер Гетц?",a="Оба землевладельца присматривают за северной частью Хилсбрадских полей. Фермера Рэя обычно можно найти у большого фермерского дома или в саду к востоку от него, а Фермер Гетц бывает в амбаре, во втором доме или на окружающих вспаханных участках.",al={"find farmer ray","find farmer getz","ray and getz location","найти фермера рэя","найти фермера гетца","где рэй и гетц"}},{q="Что происходит после завершения этого налета?",a="Возвращение к Дарталии с победой продвигает штурм к южным полям и самому городу Хилсбрад, а также открывает побочные операции, например сбор мрачных трофеев в задании «Сувениры смерти».",al={"battle of hillsbrad follow up","what comes next","chain progression","продолжение битвы за хилсбрад","что дальше","цепочка заданий"}},{q="Почему Дарталия угрожает своим солдатам?",a="Верховный палач Дарталия требует абсолютной дисциплины и беспощадности. Любое колебание или легкомыслие в отношении войны с Альянсом она считает изменой, наказуемой немедленной казнью на месте.",al={"darthalia dialogue","darthalia beheading threat","диалог дарталии","угроза обезглавливания дарталии"}}},fp="19,302,23.523.0,17.505.0,46.318.0,23.197.0,61.208.0,45.258.0,40.201.0,41.198.0"}
P.entries["quest:528"] = {n="Битва за Хилсбрад",s="Битва за Хилсбрад — военное задание Отрекшихся, которым руководит верховный палач Дарталия из Мельницы Таррен. После первых ударов по северным человеческим фермам оперативники Орды отправляются на юг, чтобы перебить бегущих хилсбрадских крестьян, искавших убежища в садах.",h="Битва за Хилсбрад — военное задание Отрекшихся, которым руководит верховный палач Дарталия из Мельницы Таррен.",kw={"battle of hillsbrad","dark lady","darthalia","deathstalkers","forsaken","hillsbrad fields","hillsbrad peasants","tarren mill","битва за хилсбрад","темная госпожа","дарталия","стражи смерти","отрекшиеся","хилсбрадские поля","хилсбрадские крестьяне","мельница таррен"},ang={["faction:Alliance"]="Убийство безоружных беженцев в южных садах подчеркивает беспощадную тотальную войну, которую Отрекшиеся ведут против последних живых подданных Лордерона.",["faction:Horde"]="Мельница Таррен — важный оплот Орды в предгорьях. Разгром Хилсбрада обеспечивает безопасность коммуникаций и снабжения Орды от вторжений Альянса.",["race:Undead"]="Для Отрекшихся эта чистка — практичная и бескомпромиссная мера: уничтожение живых работников лишает Альянс пропитания и закрепляет власть Темной Госпожи над южным Лордероном."},sec={{t="Сеять ужас на полях",b="Кампания против присутствия людей в Предгорьях Хилсбрада идет с холодным расчетом. После удара сил Орды по северным фермам по поселению прокатывается паника. Вместо того чтобы взяться за оружие, многие работники бегут на юг, в сады и на пастбища Хилсбрадских полей, надеясь спрятаться от наступающей нежити. Верховный палач Дарталия видит в их страхе не повод для милосердия, а стратегическую возможность окончательно сломить остатки рабочей силы и боевой дух Хилсбрада."},{t="Наступление Темной Госпожи",b="По прямому приказу из Мельницы Таррен чемпионы Орды выслеживают этих изгнанных с мест работников на полях. Лишенные защиты крестьяне методично уничтожаются, чтобы перекрыть Хилсбраду поставки продовольствия и сломить волю мирных жителей. Для Дарталии и Отрекшихся каждый убитый человек сильнее сжимает хватку смерти вокруг уцелевшего городка и гарантирует, что Лордерон останется в руках Отрекшихся."}},faq={{q="Почему Отрекшиеся нападают на простых крестьян?",a="Нападения на крестьян уничтожают земледельческую основу, которая кормит поселение Хилсбрад. Убивая работников, прячущихся в южных садах, верховный палач Дарталия добивается, чтобы город все глубже погружался в панику и голод, и это намного облегчает окончательное завоевание.",al={"why kill peasants","why target farmers","darthalia peasant plan","зачем убивать крестьян","зачем нападать на фермеров","план дарталии против крестьян"}},{q="Кто отдает приказ об этом нападении?",a="Верховный палач Дарталия, командир Отрекшихся, расквартированный в Мельнице Таррен, руководит всеми военными действиями против местных человеческих поселений от имени леди Сильваны Ветрокрылой.",al={"who gives battle of hillsbrad 2","quest giver battle of hillsbrad","darthalia orders","кто дает задание битва за хилсбрад","персонаж, выдающий задание битва за хилсбрад","приказы дарталии"}},{q="Откуда бежали эти крестьяне?",a="Они бежали с северных ферм Хилсбрада после прежних ударов Орды. Охваченные паникой и беззащитные, они укрылись среди деревьев и на пастбищах южных Хилсбрадских полей.",al={"where are peasants coming from","northern farms hillsbrad","откуда пришли крестьяне","северные фермы хилсбрада"}},{q="Где можно найти беглых крестьян?",a="Крестьяне разбросаны по южным садам и пастбищам Хилсбрадских полей, чуть южнее главной дороги, проходящей через предгорья.",al={"hillsbrad peasant location","where are hillsbrad peasants","где крестьяне хилсбрада","расположение крестьян хилсбрада","где найти крестьян"}},{q="Что происходит после убийства крестьян?",a="Когда южные поля очищены от работников, верховный палач Дарталия переносит кампанию на кузнеца Верринтана и кузницу, вооружающую защитников Хилсбрада, приближая бой к центру города.",al={"what is next after peasants","battle of hillsbrad next step","что дальше после крестьян","следующий шаг битвы за хилсбрад"}},{q="Почему Орда сражается здесь так беспощадно?",a="Человеческий город Хилсбрад — один из последних оставшихся оплотов Альянса в Лордероне. Отрекшиеся считают этот край своей законной территорией и стремятся изгнать или уничтожить любые анклавы Альянса, угрожающие их южной границе.",al={"why horde attacking hillsbrad","forsaken vs hillsbrad war","почему орда нападает на хилсбрад","отрекшиеся против хилсбрада","война за хилсбрад"}}},fp="19,271,27.478.0,23.422.0,47.266.0,24.186.0,35.185.0,40.148.0,38.220.1,45.259.0"}
P.entries["quest:529"] = {n="Битва за Хилсбрад",s="Эта операция — важнейший этап кампании Отрекшихся по завоеванию Предгорий Хилсбрада. Верховный палач Дарталия приказывает уничтожить местную кузницу на Хилсбрадских полях, чтобы лишить упрямых людей поставок оружия.",h="Эта операция — важнейший этап кампании Отрекшихся по завоеванию Предгорий Хилсбрада.",kw={"apprentice blacksmith","battle of hillsbrad","darthalia","hillsbrad fields","shipment of iron","tarren mill","verringtan","подмастерье кузнеца","битва за хилсбрад","дарталия","хилсбрадские поля","партия железа","мельница таррен","верринтан"},ang={["faction:Alliance"]="Убийство Верринтана и кража железа поселения лишают дальние фермы Южнобережья единственного средства самообороны.",["profession:Blacksmithing"]="Кузница Верринтана была бьющимся сердцем местного сопротивления и доказала, что наковальня может быть для захватчиков не менее опасна, чем полк пехоты.",["race:Undead"]="Для Отрекшихся уничтожение человеческой кузницы — прагматичный шаг к защите южных границ Лордерона и накоплению металла для их собственных военных усилий, которые идут нелегко."},sec={{t="Сломать наковальню",b="Наступление Отрекшихся через Предгорья Хилсбрада столкнулось с более упорным сопротивлением, чем ожидал верховный палач Дарталия. Сельские жители не желали разбегаться или уступать Стражам смерти и солдатам, посланным из Мельницы Таррен. Расследование показало, что местные крестьяне сражаются не просто вилами и косами: их вооружают для войны прямо на полях."},{t="Разорвать линию снабжения",b="На юго-западной окраине Хилсбрадских полей кузнец Верринтан и его подмастерья неустанно трудились у горна, превращая сырую руду в клинки и доспехи для ополчения. Отправив оперативника, чтобы убить Верринтана, перебить его подмастерьев и захватить запасенную партию железа, Дарталия намеревалась ослабить оборону поселения и направить его металл на будущий штурм Южнобережья."}},faq={{q="Почему верховный палач Дарталия выбрала целью именно кузнеца?",a="Городские жители и фермеры оказывают Отрекшимся неожиданное военное сопротивление. Дарталия выяснила, что кузнец Верринтан и его подмастерья куют оружие для ополчения, превращая обычных крестьян в вооруженную угрозу.",al={"why kill verringtan","blacksmith objective","verringtan quest","зачем убивать верринтана","цель кузнец","задание верринтан"}},{q="Где находится кузница?",a="Кузница стоит на юго-западной стороне Хилсбрадских полей, вокруг нее работают подмастерья, ходят стражи и местные патрули.",al={"verringtan location","where is the blacksmith","hillsbrad smithy","где верринтан","где кузнец","кузница хилсбрада"}},{q="Для чего нужна партия железа?",a="Дарталия конфискует железо для военной машины Отрекшихся. Она намерена использовать захваченное сырье, чтобы ковать оружие и припасы для планируемого штурма портового города Альянса — Южнобережья.",al={"what happens to the iron","iron shipment lore","что будет с железом","партия железа предания"}},{q="Как это вписывается в общую кампанию Битвы за Хилсбрад?",a="Это третий этап систематических усилий Дарталии по уничтожению присутствия людей в предгорьях: от истребления сельских работников и фермеров она переходит к лишению их руководства, снабжения и производственных мощностей.",al={"battle of hillsbrad chain","darthalia campaign","цепочка битва за хилсбрад","кампания дарталии"}},{q="Входят ли жители Хилсбрадских полей в военные силы Альянса?",a="Хотя жители полей культурно близки к Южнобережью и Альянсу, это в основном местные фермеры, работники и горожане, наспех создавшие ополчение, чтобы защитить свои дома от Отрекшихся.",al={"are hillsbrad farmers alliance","hillsbrad militia","фермеры хилсбрада альянс","ополчение хилсбрада"}},{q="Кто отдает приказ об этом ударе?",a="Верховный палач Дарталия, командующий офицер, руководящий операциями Отрекшихся из крепости Мельница Таррен.",al={"quest giver","who is darthalia","персонаж, выдающий задание","кто такая дарталия"}}},fp="19,249,18.390.0,24.422.0,68.262.0,28.129.0,38.214.0,64.233.0,65.211.0,23.123.0"}
P.entries["quest:532"] = {n="Битва за Хилсбрад",s="Этот важный этап кампании Отрекшихся против владений вокруг Южнобережья направлен против гражданского руководства города Хилсбрад. Под началом Верховного палача Дарталии из Мельницы Таррен силы Орды наносят удар по судье Бернсайду, его совету и административным записям, чтобы полностью сокрушить человеческую власть в предгорьях.",h="Этот важный этап кампании Отрекшихся против владений вокруг Южнобережья направлен против гражданского...",kw={"battle of hillsbrad","darthalia","hillsbrad councilmen","hillsbrad proclamation","hillsbrad town registry","magistrate burnside","tarren mill","town hall","битва за хилсбрад","дарталия","хилсбрадские советники","хилсбрадская прокламация","городской реестр хилсбрада","судья бернсайд","мельница таррен","ратуша"},ang={["faction:Alliance"]="Убийство судьи Бернсайда и сожжение городского устава ознаменовали катастрофическое падение последнего законного местного правительства Хилсбрада.",["faction:Horde"]="Удар по ратуше подрывает способность Альянса координировать местное ополчение и надежно укрепляет южную границу Мельницы Таррен от контратак людей.",["race:Undead"]="Для Отрекшихся уничтожение человеческой власти в Хилсбраде — одновременно стратегическое расширение и безжалостное возмездие живым, оспаривающим границы Лордерона."},sec={{t="Обезглавливание городского совета",b="Даже понеся тяжелые потери на полях и в патрулях, человеческие защитники Хилсбрада цепляются за остатки гражданской власти. Верховный палач Дарталия понимает, что простые крестьяне и ополченцы сплачиваются вокруг своих городских лидеров. Чтобы город рухнул окончательно, агентов Отрекшихся посылают прямо в Ратушу — казнить судью Бернсайда и пятерых его советников и тем самым разорвать цепь командования."},{t="Уничтожение городских записей",b="Помимо убийств, Дарталия стремится полностью разрушить Хилсбрад в психологическом и административном смысле. Агенты должны сжечь Хилсбрадскую прокламацию — почитаемый политический документ, символ устава и гордости поселения. Вместе с ее уничтожением изымается городской реестр: уцелевшие сторонники Альянса лишаются официальных записей и списков жителей, а разведка Подгорода получает подробные сведения о местном населении."}},faq={{q="Кто отдает приказ об этом ударе?",a="Верховный палач Дарталия, командир Отрекшихся в Мельнице Таррен, организует нападение в рамках своей более широкой кампании по уничтожению поселений Альянса в предгорьях.",al={"who gives this quest","quest giver battle of hillsbrad","darthalia hillsbrad","кто дает это задание","персонаж, выдающий задания битва за хилсбрад","дарталия хилсбрад"}},{q="Кто такой судья Бернсайд?",a="Судья Бернсайд — судья и политический лидер человеческого города Хилсбрад. Находясь в ратуше вместе со своими советниками, он использует тайную магию, чтобы защитить остатки власти в поселении.",al={"magistrate burnside","who is burnside","hillsbrad leader","судья бернсайд","кто такой бернсайд","лидер хилсбрада"}},{q="Что такое Хилсбрадская прокламация?",a="Хилсбрадская прокламация — почитаемый политический устав, на видном месте хранящийся в Ратуше. Он воплощает законы и дух жителей города, поэтому его уничтожение становится сокрушительным ударом по гражданскому духу.",al={"what is the proclamation","hillsbrad proclamation lore","destroy proclamation","что такое прокламация","хилсбрадская прокламация предания","уничтожить прокламацию"}},{q="Зачем Дарталии городской реестр?",a="В городском реестре содержится полная перепись и гражданская документация населения Хилсбрада. Его похищение лишает уцелевших людей административной памяти, а Отрекшиеся получают важные сведения о том, кто остался в округе.",al={"why steal registry","hillsbrad town registry","what does registry do","зачем красть реестр","городской реестр хилсбрада","для чего нужен реестр"}},{q="Где происходит это сражение?",a="Цели находятся в большом здании Ратуши и вокруг него, в человеческом поселении Хилсбрад, расположенном в южных предгорьях между Мельницей Таррен и Южнобережьем.",al={"where is magistrate burnside","hillsbrad town hall location","where are councilmen","где судья бернсайд","ратуша хилсбрада где","где советники"}},{q="Какую роль играют советники?",a="Хилсбрадские советники — управляющий орган, помогающий судье Бернсайду. Это умелые заклинатели, защищающие как внутренние помещения Ратуши, так и прилегающую территорию.",al={"hillsbrad councilmen","who are councilmen","хилсбрадские советники","кто такие советники"}}},fp="19,335,29.444.0,24.472.0,23.179.0,27.221.0,35.223.0,42.237.0,33.182.0,33.185.0"}
P.entries["quest:5321"] = {n="Спящий пробудился",s="Керлониан Вечный Сумрак, недавно пробудившийся Друид-медведь, изо всех сил старается не уснуть на пути к Заставе Мейстры в Ясеневом лесу. Путешественникам, которым доверен его Рог Пробуждения, предстоит сопровождать вялого друида вдоль лесной границы: будить его, когда он погружается в дрему, и защищать от диких фурболгов и зловещих культистов.",h="Керлониан Вечный Сумрак, недавно пробудившийся Друид-медведь, изо всех сил старается не уснуть на пути к...",kw={"ashenvale","dark strand","darkshore","druid of the claw","evershade","horn of awakening","kerlonian","liladris","maestra's post","twilight vale","ясеневый лес","темная нить","темные берега","друид-медведь","вечный сумрак","рог пробуждения","керлониан","лиладрис","застава мейстры","сумеречная долина"},ang={["class:Druid"]="Друиды узнают тяжелую цену глубокого единения с Изумрудным Сном: долгая спячка часто оставляет бодрствующий разум медленно приходящим в полное сознание.",["faction:Alliance"]="Безопасный проход путников между Темными берегами и севером Ясеневого леса помогает поддерживать важные линии связи между Аубердином и дальними сторожевыми постами.",["race:NightElf"]="Для ночных эльфов Керлониан — привычное свидетельство недавнего потрясения их культуры: он олицетворяет тысячи друидов, откликнувшихся на зов рога во время Третьей войны и теперь привыкающих к дневному свету."},sec={{t="Дремлющий разум",b="Тысячелетиями Друиды-медведи спали в курганах, общаясь с духами природы через Изумрудный Сон. Хотя Третья война потребовала их пробуждения, стряхнуть многовековую спячку удается не каждому. Керлониан Вечный Сумрак отправился на юг из Темных берегов в Ясеневый лес на встречу с Лиладрис Лунная Река, но усталость одолела его вскоре после начала пути. Он беспомощно склонен внезапно засыпать посреди глуши, поэтому полагается на латунный Рог Пробуждения и проходящих мимо союзников, чтобы продолжать идти."},{t="Опасности на дороге",b="Путь из Темных берегов в Ясеневый лес далек от спокойного. Пока Керлониан бредет на юг, его уязвимое состояние привлекает агрессию окрестной глуши. В Сумеречной долине дорогу выслеживают оскверненные фурболги Чернолесья, а южнее, в Ясеневом лесу, в засадах таятся члены зловещего культа Темной Нити. Сопровождение сонного друида требует бдительности: Керлониан просто ляжет спать там, где стоит, если его не разбудить рогом."},{t="Прибытие на заставу",b="Пережив засады и добравшись до Заставы Мейстры, Керлониан тут же уходит искать другую удобную лужайку, чтобы продолжить прерванный сон. Его знакомая, Лиладрис Лунная Река, почти не удивлена его привычной рассеянности и встречает его с нежной досадой. Трудности Керлониана отражают остаточную растерянность, свойственную многим друидам, для которых мир яви режет глаз после вневременного покоя Сна."}},faq={{q="Почему Керлониан все время засыпает?",a="Керлониан Вечный Сумрак — Друид-медведь, лишь недавно очнувшийся от многовековой спячки в Изумрудном Сне. Возвращение в мир яви оставляет многих друидов растерянными и глубоко вялыми, поэтому без постоянных внешних раздражителей ему почти невозможно не заснуть.",al={"why is kerlonian sleeping","why is he so sleepy","druid falling asleep","почему керлониан спит","почему он такой сонный","друид засыпает"}},{q="Как разбудить Керлониана, когда он засыпает?",a="Нужно использовать Рог Пробуждения, который берется из сундука рядом с Керлонианом в начале пути. Когда он падает в дрему на тропе, звук рога приводит его в чувство, и он может продолжить путь.",al={"how to wake kerlonian","kerlonian horn","horn of awakening use","как разбудить керлониана","рог керлониана","использование рога пробуждения"}},{q="Кто ждет Керлониана на Заставе Мейстры?",a="Он направляется на встречу с Лиладрис Лунная Река, эльфийкой с Заставы Мейстры на севере Ясеневого леса. Она знает о его хронической сонливости и просто рада видеть, что он добрался целым.",al={"who is liladris","who is kerlonian meeting","кто такая лиладрис","с кем встречается керлониан"}},{q="Какие враги нападают по пути?",a="Дорога ведет мимо Сумеречной долины, где враждебные фурболги Чернолесья устраивают засады на отряд. Дальше на юг, в Ясеневом лесу, из тени бьют землекопы, адепты и культисты тайной Темной Нити.",al={"ambushes during escort","what attacks kerlonian","twilight vale ambush","засады при сопровождении","кто нападает на керлониана","засада в сумеречной долине"}},{q="Откуда взялось название «Спящий пробудился»?",a="Это легендарное приветствие, которое произносят Друиды-медведи, когда их призывают на службу во время Третьей войны, и оно подчеркивает природу Керлониана как пробудившегося оборотня.",al={"sleeper has awakened quote","druid voiceline","цитата спящий пробудился","реплика друида"}},{q="Что будет с рогом, если слишком долго медлить?",a="Рог Пробуждения действует ограниченное время, после чего исчезает из вашего инвентаря. Если сопровождение затягивается или его приходится начинать заново после неудачи, замену нужно взять из сундука у места отдыха Керлониана.",al={"horn expired","horn of awakening disappeared","рог исчез","рог пробуждения пропал"}}},fp="24,348,17.541.0,20.484.0,22.454.1,39.294.0,42.241.0,47.194.0,34.212.0,58.168.0,46.232.0"}
P.entries["quest:536"] = {n="На побережье",s="«На побережье» — задание Альянса, которое выдает лейтенант Фаррен Оринель в Южнобережье. Крайне недовольный переводом из Штормграда на границу, лейтенант стражи предпочитает пить эль, а не патрулировать, и нанимает искателей приключений, чтобы вычистить мурлоков Рваного Плавника, наступающих на Западное побережье.",h="«На побережье» — задание Альянса, которое выдает лейтенант Фаррен Оринель в Южнобережье.",kw={"down the coast","farren orinelle","hillsbrad","murloc","redpath","southshore","torn fin","western strand","на побережье","фаррен оринель","хилсбрад","мурлок","редпат","южнобережье","рваный плавник","западное побережье"},ang={["faction:Alliance"]="Южнобережье — главный прибрежный бастион Альянса на севере, поэтому даже мелкая халатность гарнизона угрожает выживанию города.",["race:Human"]="Леность Оринеля болезненно обнажает контраст между защищенным сердцем Штормграда и суровым выживанием северных поселений."},sec={{t="Неохотное назначение",b="Лейтенант Фаррен Оринель был переведен из городской стражи Штормграда с его вымощенными камнем улицами в далекий соленый порт Южнобережья. Считая город унылым, а рыбный запах гавани невыносимым, Оринель проводит дни за выпивкой в местной таверне вместо патрулирования передовой. Когда маршал Маркус Редпат приказывает ему защитить Южнобережье от окрестных опасностей, Оринель решает передоверить свои обязанности проходящим мимо наемникам."},{t="Угроза Рваного Плавника",b="Само задание связано с Западным побережьем — береговой линией к западу от Южнобережья. Хотя Оринель насмехается над угрозой «переросшей рыбы», племя мурлоков Рваного Плавника представляет настоящую опасность для прибрежных путешествий и местного судоходства. Они собираются в плотных лагерях у прибоя, и их охотники приливов и мистические оракулы легко устраивают засады на всех, кто уходит далеко от городских стен, так что зачистка берега — кровавое дело."}},faq={{q="Почему Фаррен Оринель не разбирается с мурлоками сам?",a="Фаррен считает Южнобережье нежеланной ссылкой после прежней жизни в городской страже Штормграда. Обиженный назначением и испытывая отвращение к прибрежному городку, он предпочитает сидеть в таверне с элем, а не идти в прибой сражаться с мурлоками, и потому платит искателям приключений за свою работу.",al={"why is farren drinking","farren orinelle personality","why hire adventurers","почему фаррен пьет","характер фаррена оринеля","почему нанимает искателей приключений"}},{q="Кто такой «старина Редпат», о котором говорит Оринель?",a="Он имеет в виду маршала Маркуса Редпата, маршала Южнобережья. Редпат отвечает за порядок и оборону осажденного поселения, в том числе отдает военные приказы, от которых лейтенант Оринель откровенно пытается увильнуть.",al={"who is redpath","magistrate redpath","orinelle commander","кто такой редпат","судья редпат","командир оринеля"}},{q="Где находятся мурлоки Рваного Плавника?",a="Мурлоки Рваного Плавника обитают на Западном побережье — прибрежных пляжах прямо к западу от Южнобережья в Предгорьях Хилсбрада.",al={"where are torn fin","murloc location hillsbrad","western strand location","где рваный плавник","мурлоки хилсбрад","где западное побережье"}},{q="Каких мурлоков нужно уничтожить?",a="Задание требует убить охотников приливов Рваного Плавника — бойцов передовой племени — и оракулов Рваного Плавника, использующих магию стихий и воды, чтобы усиливать сородичей.",al={"murloc targets","which murlocs kill","tidehunter oracle","цели мурлоки","каких мурлоков убивать","охотник приливов оракул"}},{q="Что происходит после зачистки пляжа для Оринеля?",a="После завершения зачистки Оринель понимает, что ему нужны вещественные доказательства, чтобы удовлетворить проверку маршала Редпата, и это запускает цепочку заданий по сбору физических доказательств гибели мурлоков.",al={"next quest after down the coast","down the coast chain","farrens proof next","следующее задание после на побережье","цепочка на побережье","доказательства фаррена дальше"}},{q="Мурлоки действительно опасны или это просто предлог?",a="Хотя Фаррен высмеивает этих существ как безобидную переросшую рыбу, Рваные Плавники многочисленны, агрессивны и расположены неприятно близко к докам Южнобережья, угрожая торговым путям и рыбакам.",al={"are murlocs dangerous hillsbrad","southshore murloc danger","опасны ли мурлоки хилсбрад","опасность мурлоков южнобережье"}}},fp="14,293,19.465.0,19.442.0,58.293.0,42.249.0,39.139.0,44.179.0,51.196.1,56.195.0"}
P.entries["quest:539"] = {n="Битва за Хилсбрад",s="Этот приказ Верховного палача Дарталии велит агентам Орды нанести удар в глубине Лазуритового рудника — важного железного рудника к югу от Хилсбрадских полей. Уничтожив штейгера Бондса и его рабочих, Отрекшиеся стремятся прервать поставки железа на оружейные склады Альянса и захватить туннели.",h="Этот приказ Верховного палача Дарталии велит агентам Орды нанести удар в глубине Лазуритового рудника —...",kw={"azurelode","bonds","darthalia","hillsbrad","iron","miners","southshore","tarren mill","undercity","лазуритовый рудник","бондс","дарталия","хилсбрад","железо","шахтеры","южнобережье","мельница таррен","подгород"},ang={["faction:Horde"]="Срыв главных поставок металла Альянса в Хилсбраде ослабляет давление на передовую у Мельницы Таррен и не дает людским войскам легко заменить снаряжение.",["profession:Mining"]="Лазуритовый рудник — одна из богатейших железных копей в предгорьях, поэтому он естественно становится яблоком раздора для всех, кто борется за ценные рудные жилы.",["race:Undead"]="Захват Лазуритового рудника обеспечивает Стражей смерти необходимым железом и обращает промышленность людей на вооружение армий Сильваны по всему Лордерону."},sec={{t="Прерывание поставок железа",b="Захватив во время прежних налетов Регистрационную книгу Хилсбрада, Верховный палач Дарталия определила, что Лазуритовый рудник — опора военной устойчивости людей в регионе. Рудник действует к югу от спорных полей и непрерывно добывает богатую железную руду для оружейников и арсеналов Альянса. Если оставить его нетронутым, силы Южнобережья смогут перевооружиться и усилить гарнизоны, а прежние победы Мельницы Таррен потеряют смысл."},{t="Решающее послание",b="Чтобы полностью остановить добычу, Дарталия бьет и по руководству, и по рабочим. Силам Орды приказано убить штейгера Бондса, человека, руководящего раскопками, и значительную часть его рабочих. Удар по темным шахтам посылает Южнобережью недвусмысленное сообщение: ни их линии снабжения, ни уединенные рабочие лагеря не недоступны для Отрекшихся."},{t="Добыча для Темной Госпожи",b="Помимо лишения Альянса военных материалов, этот штурм преследует для Подгорода и практическую цель. Захват рудника позволяет силам Сильваны Ветрокрылой присвоить богатые рудные жилы для своих литейных. Мельнице Таррен нужен постоянный запас металла для оружия и лат для войны по всему Лордерону, и бывшее достояние людей становится двигателем завоеваний Отрекшихся."}},faq={{q="Почему Лазуритовый рудник так важен для Отрекшихся?",a="Лазуритовый рудник поставляет высококачественную железную руду прямо на оружейные склады Альянса. Его захват лишает человеческие гарнизоны, например Южнобережья, материалов для ковки и отдает Подгороду богатый источник сырого металла для снаряжения сил Отрекшихся.",al={"why attack azurelode","azurelode mine purpose","why target the mine","зачем атаковать лазуритовый рудник","значение лазуритового рудника","почему рудник цель"}},{q="Кто такой штейгер Бондс?",a="Штейгер Бондс — человек, надзирающий за раскопками в Лазуритовом руднике. Он управляет шахтерами и может призвать стойких дворфов-защитников, когда его загонят в глубокие нижние залы.",al={"foreman bonds","who is bonds","who leads the mine","штейгер бондс","кто такой бондс","кто управляет рудником"}},{q="Где находится Лазуритовый рудник?",a="Лазуритовый рудник вырублен в холмах к югу от Хилсбрадских полей, к западу от Южнобережья, среди прибрежных утесов.",al={"where is azurelode mine","azurelode location","how to find the mine","где лазуритовый рудник","расположение лазуритового рудника","как найти рудник"}},{q="Как Дарталия узнала о работе рудника?",a="Дарталия узнала о ценности рудника для снабжения и о том, что он действует, изучив Регистрационную книгу Хилсбрада, которую оперативники Орды захватили во время прежних ударов по поселениям людей.",al={"how did darthalia know","town registry mine","hillsbrad intel","как дарталия узнала","регистрационная книга рудник","разведка хилсбрад"}},{q="Что произойдет после гибели штейгера Бондса?",a="Когда рудник выведен из строя, а его ресурсы переходят под контроль Отрекшихся, Верховный палач Дарталия усиливает наступление: Орда направляет внимание на уничтожение оставшейся инфраструктуры Хилсбрада и продвигается ближе к самому Южнобережью.",al={"what next battle of hillsbrad","after killing bonds","quest aftermath","что дальше битва за хилсбрад","после убийства бондса","последствия задания"}},{q="Защищает ли Альянс рудник?",a="Да. Помимо людей-шахтеров, работающих в штольнях, Альянс держит у входа вооруженную стражу, а штейгер Бондс держит наготове крепких дворфов-подкрепление в глубине туннелей.",al={"mine guards","alliance presence in azurelode","dwarves in mine","стража рудника","присутствие альянса в лазуритовом руднике","дворфы в руднике"}}},fp="19,299,24.454.0,18.389.0,24.402.1,51.235.0,21.187.0,36.121.0,55.191.0,42.247.1,34.187.0"}
P.entries["quest:541"] = {n="Битва за Хилсбрад",s="Этот важный этап кампании Отрекшихся в Хилсбраде направлен на дворфийскую крепость Дун Гарок. Верховный палач Дарталия посылает героев Орды разгромить дворфийский гарнизон, помогающий местным людям, и убить его командира, капитана Железная Гора.",h="Этот важный этап кампании Отрекшихся в Хилсбраде направлен на дворфийскую крепость Дун Гарок.",kw={"battle of hillsbrad","captain ironhill","dun garok","high executor darthalia","mountaineer","rifleman","tarren mill","thoradin's wall","битва за хилсбрад","капитан железная гора","дун гарок","верховный палач дарталия","горный стрелок","стрелок","мельница таррен","стена торадина"},ang={["faction:Horde"]="Удар по Дун Гароку отрезает важные военные подкрепления, которые Стальгорн послал на помощь осажденным людям Южнобережья.",["race:Dwarf"]="Дун Гарок воплощает стойкую верность Стальгорна своим союзникам-людям, которые выдерживают осаду Отрекшихся, удерживая северный рубеж.",["race:Undead"]="Для Отрекшихся уничтожение дворфийского гарнизона закрепляет юго-восток Лордерона и гарантирует, что никакой южный авангард Альянса не сможет легко пройти через Стену Торадина."},sec={{t="Проверка Альянса",b="Надавив на людей-фермеров и городское ополчение в предгорьях, Верховный палач Дарталия обращает ярость Мельницы Таррен против военного контингента Стальгорна. Дворфийские войска взялись за оружие в поддержку Южнобережья, укрепляя присутствие людей в Лордероне. Для Дарталии эта солидарность — препятствие, которое нужно сокрушить, доказав Альянсу, что помощь остаткам людей принесет лишь разорение."},{t="Падение Дун Гарока",b="Дун Гарок, прижатый к древним валам Стены Торадина на юго-востоке Хилсбрада, служит сильно укрепленным дворфийским бастионом. Чтобы взять форпост, нужно прорваться через ряды дисциплинированных горных пехотинцев, меткие стрелки и закаленных в боях жрецов. Штурм завершается смертью капитана Железная Гора, что ломает передовое тактическое командование Стальгорна в регионе и оставляет прочие людские анклавы в изоляции."}},faq={{q="Почему дворфы сражаются в Хилсбраде?",a="Дворфы Стальгорна прочно связаны с Альянсом и отправили на север, в Дун Гарок, вооруженные силы, чтобы помочь уцелевшим людям Южнобережья и Хилсбрада против экспансии Отрекшихся.",al={"why are there dwarves in hillsbrad","dwarves dun garok","why dwarves helping humans","почему дворфы в хилсбраде","дворфы дун гарок","почему дворфы помогают людям"}},{q="Где находится Дун Гарок?",a="Дун Гарок расположен в юго-восточном углу Предгорий Хилсбрада и встроен прямо в основание Стены Торадина.",al={"dun garok location","where is dun garok","find dun garok","расположение дун гарока","где дун гарок","найти дун гарок"}},{q="Кто такой капитан Железная Гора?",a="Капитан Железная Гора — дворфийский командир гарнизона Дун Гарока. Благодаря ему горные пехотинцы в регионе остаются организованными и боеспособными.",al={"captain ironhill","who is ironhill","dun garok leader","капитан железная гора","кто такой капитан железная гора","предводитель дун гарока"}},{q="Кто дает этот приказ?",a="Приказ разгромить дворфийский гарнизон отдает Верховный палач Дарталия, военный командир Отрекшихся, расквартированный в Мельнице Таррен.",al={"who gives quest","questgiver darthalia","darthalia hillsbrad","кто дает задание","дарталия выдает задание","дарталия хилсбрад"}},{q="Что будет, если силы Орды потерпят здесь неудачу?",a="Верховный палач Дарталия ясно дает понять, что провал недопустим, и предупреждает: всякого, кто не сможет сломить Дун Гарок, разжалуют и отправят рыть могилы обратно в Тирисфальские леса.",al={"what if fail","darthalia threat","consequences","что если провал","угроза дарталии","последствия"}},{q="Почему Дун Гарок так трудно штурмовать?",a="В отличие от сельского ополчения Хилсбрада, Дун Гарок защищают обученные дворфийские солдаты, стрелковые отряды и священники, которые сражаются плотным строем в укреплениях, расположенных под землей и на возвышении.",al={"dun garok elite","why is dun garok hard","dun garok defense","элита дун гарока","почему дун гарок трудно взять","оборона дун гарока"}}},fp="19,270,20.421.0,21.433.0,38.202.0,27.128.0,24.158.0,21.132.0,39.172.0,41.205.0"}
P.entries["quest:543"] = {n="Тиара Перенольда",s="Тиара Перенольда — поручение графа Ремингтона Риджвелла, аристократа из Штормграда. Он нанимает искателей приключений, чтобы они отправились на север, в опасные Руины Альтерака, и вернули утраченную королевскую реликвию. Корона некогда принадлежала павшей династии Альтерака, и, по слухам, ее хранит маг-огр.",h="Тиара Перенольда — поручение графа Ремингтона Риджвелла, аристократа из Штормграда.",kw={"alterac","crushridge","grel'borg","miser","perenolde","ridgewell","stormwind","tiara","альтерак","раздробленный хребет","грель'борг","скряга","перенольд","риджвелл","штормград","тиара"},ang={["faction:Alliance"]="Поход на север, в беззаконные Альтеракские горы, позволяет агентам Альянса уничтожить опасных огров Раздробленного Хребта и вернуть бесценные исторические артефакты для знати Штормграда.",["race:Dwarf"]="Созданная искусными ювелирами Стальгорна, тиара олицетворяет прославленное мастерство дворфийских ремесленников, чья тонкая работа пережила даже крах человеческого королевства.",["race:Human"]="Для людей Альянса тиара — неприятное напоминание о предательстве Альтерака во Второй войне, когда человеческая знать встала на сторону Орды против собственного народа."},sec={{t="Реликвия павшего королевства",b="Тиара Перенольда — изысканная реликвия павшего человеческого королевства Альтерак. Искусные дворфийские ювелиры Стальгорна изготовили этот богато украшенный венец и украсили его лучшими изумрудами для правящего рода Перенольдов. Однако во время Второй войны король Эйден Перенольд предал Великий Альянс, перейдя на сторону Орочьей Орды, что прямо привело к падению его королевства, его завоеванию и окончательному краху. В хаосе и после падения города Альтерак многие величайшие сокровища королевской династии исчезли в заснеженных обломках Альтеракских гор."},{t="Скряга в руинах",b="Тиара оказалась не в хранилище Альянса и не в королевской гробнице, а в жадных лапах Грель'борга Скряги. Грель'борг, маг-огр из племени огров Раздробленного Хребта, обитающих в руинах Альтерака, целыми днями роется в полуразрушенных камнях в поисках блестящих безделушек и брошенных богатств. Граф Ремингтон Риджвелл, страстный коллекционер исторических диковин из Штормграда, узнал, что тиара уцелела, и нанимает отважных наемников, чтобы они проникли вглубь земель огров, убили скрягу и вернули бесценную драгоценность в его личную галерею."}},faq={{q="Кто такие Перенольды?",a="Перенольды — королевский род, правивший северным человеческим королевством Альтерак. Во время Второй войны король Эйден Перенольд совершил государственную измену, сотрудничая с вторгшейся Орочьей Ордой, чтобы пощадить свое королевство. Его предательство раскрыл Альянс Лордерона, что привело к военной оккупации Альтерака, упразднению трона и последующему падению королевства в полное беззаконие и разорение.",al={"house of perenolde","who were the perenoldes","perenolde lore","род перенольдов","кто такие перенольды","предания о перенольдах"}},{q="Кто создал Тиару Перенольда?",a="Тиару выковали искусные ювелиры дворфийского города Стальгорн. Изготовленная из тонких металлов и украшенная блестящими изумрудами, она была символом знатности и богатства правящего дома Альтерака, пока королевство не пало.",al={"tiara origin","who crafted perenolde tiara","происхождение тиары","кто создал тиару перенольда"}},{q="У кого сейчас тиара?",a="Тиара попала в лапы Грель'борга Скряги, огра-мага-собирателя, бродящего по заснеженным Руинам Альтерака в северных холмах и жаждущего древних сокровищ, оставшихся от разрушенного человеческого города.",al={"grelborg","who has perenolde tiara","tiara location","грель'борг","у кого тиара перенольда","где тиара"}},{q="Зачем графу Ремингтону Риджвеллу тиара?",a="Граф Ремингтон Риджвелл — богатый дворянин и любитель древностей, живущий в Штормграде. Он ищет знаменитые артефакты и исторические диковины по всему Азероту, чтобы пополнить свою известную личную коллекцию, и нанимает умелых наемников, чтобы они добывали утраченные сокровища из опасных мест.",al={"remington ridgewell motive","why get the tiara","мотив ремингтона риджвелла","зачем получить тиару"}},{q="Где находятся Руины Альтерака?",a="Руины Альтерака лежат в холодных Альтеракских горах на севере Восточных королевств, к северу от Предгорий Хилсбрада и к северу от окрестностей Дарнхольда. Заброшенный город сейчас кишит враждебными ограми Раздробленного Хребта и разбойниками Синдиката.",al={"alterac ruins location","where is alterac","расположение руин альтерака","где альтерак"}},{q="Что происходит с тиарой после того, как вы ее вернете?",a="Получив грязную и потускневшую реликвию, граф Риджвелл поручает профессиональным реставраторам почистить и отполировать ее, а затем сразу выставляет как главный экспонат своей личной коллекции.",al={"tiara turn in","tiara fate","сдача тиары","судьба тиары"}}},fp="19,319,27.573.0,22.591.0,29.425.0,29.241.0,24.204.0,50.289.0,39.265.0,47.201.1"}
P.entries["quest:546"] = {n="Сувениры смерти",s="«Сувениры смерти» — задание, которое Страж смерти Самса в Мельнице Таррен дает воинам Орды, воюющим против человеческих поселений в Предгорьях Хилсбрада. Завидуя тем, кого отправили на передовую, Самса просит принести тридцать человеческих черепов, добытых в бою, для его мрачной коллекции.",h="«Сувениры смерти» — задание, которое Страж смерти Самса в Мельнице Таррен дает воинам Орды, воюющим против...",kw={"battle of hillsbrad","darthalia","deathguard samsa","forsaken","hillsbrad","hillsbrad human skull","souvenirs of death","tarren mill","битва за хилсбрад","дарталия","страж смерти самса","отрекшиеся","хилсбрад","человеческий череп хилсбрада","сувениры смерти","мельница таррен"},ang={["faction:Alliance"]="Систематический сбор отрубленных человеческих голов показывает, какая жестокая и смертельная угроза исходит от Отрекшихся для уцелевших жителей Хилсбрада.",["faction:Horde"]="Кампания против Хилсбрада — прямая попытка Орды сокрушить оставшиеся оплоты Альянса в Лордероне и обезопасить северные пути снабжения Мельницы Таррен.",["race:Undead"]="Страж смерти Самса отражает обыденную жестокость и глубокую враждебность, которую многие Отрекшиеся питают к живым людям, считающим их чудовищами."},sec={{t="Зависть стража",b="Пока Верховный палач Дарталия направляет всю военную мощь Отрекшихся против человеческих поселений Хилсбрада, Страж смерти Самса застрял на посту в Мельнице Таррен. Он питает горькую зависть к тем, кого послали грабить, жечь и разорять, и считает открытое убийство живых завидной привилегией, недоступной городским стражам."},{t="Жуткий трофей",b="Не имея возможности покинуть пост, Самса дает выход своей ненависти, собирая черепа жителей Хилсбрада, убитых в ходе кампании. Его просьба о тридцати черепах не связана ни с тайным ритуалом, ни с тактикой: это чисто личная прихоть — трофеи войны, в которой он мечтает сражаться сам."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Страж смерти Самса. Он стоит на посту в Мельнице Таррен — главном оплоте Отрекшихся на севере Предгорий Хилсбрада.",al={"quest giver","who gives souvenirs of death","samsa location","персонаж, выдающий задание","кто дает сувениры смерти","где самса"}},{q="Что нужно Стражу смерти Самсе?",a="Самса просит тридцать человеческих черепов Хилсбрада, которые достаются с убитых вами людей — бойцов и горожан — в Хилсбрадских полях и в городе Хилсбрад.",al={"quest goal","what items needed","skulls required","цель задания","какие предметы нужны","сколько черепов"}},{q="Зачем Самсе человеческие черепа?",a="Самса — страстный коллекционер жутких трофеев. Застряв в гарнизоне Мельницы Таррен, пока другие ведут тотальную войну, он собирает черепа, чтобы хоть так разделить радость убийства живых.",al={"why collect skulls","samsa motivation","what are skulls for","зачем собирать черепа","мотивы самсы","для чего черепа"}},{q="Когда становится доступно это задание?",a="Самса обращается к вам, только когда вы поступили на службу к Верховному палачу Дарталии и выполнили первое нападение в цепочке заданий «Битва за Хилсбрад».",al={"quest prerequisites","how to unlock","prereqs for souvenirs","требования задания","как открыть","предыдущие задания сувениры смерти"}},{q="Используются ли черепа для алхимии или магии Отрекшихся?",a="Нет. В отличие от поручений Королевского фармацевтического общества, которому нужны биологические реагенты для Новой чумы, просьба Самсы совершенно личная. Он считает отрубленные черепа красивыми и хранит их как сувениры войны.",al={"are skulls for apothecary","magic skulls","necromancy use","черепа для аптекаря","магические черепа","некромантия"}},{q="Какие люди дают черепа?",a="Черепа могут выпасть с любого фермера, крестьянина, ополченца и защитника из Хилсбрадских полей или города Хилсбрад, пока вы сражаетесь от имени Мельницы Таррен.",al={"where to farm skulls","which mobs drop skulls","hillsbrad humans","где добыть черепа","с кого падают черепа","люди хилсбрада"}}},fp="18,285,14.373.0,17.303.0,49.147.0,32.170.0,33.185.0,38.151.0,50.222.0,32.173.0"}
P.entries["quest:5482"] = {n="Погибельник",s="«Погибельник» — задание, которое выдает младший аптекарь Холланд в Брилле: собрать ядовитые растения, растущие возле северных братских могил Тирисфаля. Холланд, раздраженный неуклюжими попытками сбора, предпринятыми порождением Гордо, нанимает проходящих мимо искателей приключений.",h="«Погибельник» — задание, которое выдает младший аптекарь Холланд в Брилле: собрать ядовитые растения...",kw={"brill","doom weed","gordo","junior apothecary holland","mass grave","rot hide gnolls","royal apothecary society","tirisfal glades","брилл","погибельник","гордо","младший аптекарь холланд","братская могила","гноллы гнилошкуры","королевское фармацевтическое общество","тирисфальские леса"},ang={["faction:Horde"]="Тревожные алхимические опыты в Брилле показывают, насколько Отрекшиеся отличаются от своих шаманистских и кочевых союзников в Калимдоре.",["profession:Herbalism"]="Хотя обычные травы для сбора растут по всем лесам, искаженные разновидности вроде погибельника показывают неестественные изменения растительного мира, вызванные чумой Плети.",["race:Undead"]="Служба младшим членам Королевского фармацевтического общества — обычный обряд для недавно пробудившихся Отрекшихся, желающих доказать свою полезность владениям Сильваны."},sec={{t="Аптекарские амбиции",b="Младший аптекарь Холланд ведет исследования от имени Королевского фармацевтического общества в поселении Брилл. Для продолжения опытов ему нужно много погибельника — отвратительного растения, которое заражает оскверненную почву Тирисфальских лесов. Убедившись, что Гордо не способен отличить нужные реагенты, Холланд обращается к более сноровистым рукам, чтобы спасти урожай."},{t="Сбор у братской могилы",b="Погибельник процветает в местах, сильно оскверненных смертью и чумой, и густо разрастается вокруг братской могилы к северу от кладбища Брилла. Сбор опасен из-за агрессивных гноллов Гнилошкуров, которые бродят по оскверненным курганам, роются в останках и защищают заросшие рвы."}},faq={{q="Зачем младшему аптекарю Холланду нужен погибельник?",a="Младшему аптекарю Холланду нужен погибельник для алхимических работ на благо Королевского фармацевтического общества. Он утверждает, что это прямо помогает леди Сильване Ветрокрылой, но его алчное рвение говорит о том, что он не меньше заинтересован в собственной карьере в обществе.",al={"holland doom weed","why doom weed","doom weed purpose","холланд погибельник","зачем погибельник","для чего нужен погибельник"}},{q="Почему Гордо не собирает травы сам?",a="Гордо — это порождение нежити, которому поручено собирать травы вокруг Брилла, но у него не хватает ума, чтобы отличать нужные растения. Холланд жалуется, что неуклюжее создание принесло совсем не те сорняки, и аптекарю пришлось нанимать способных искателей приключений.",al={"why not gordo","gordo task fail","who is gordo","почему не гордо","гордо не справился","кто такой гордо"}},{q="Где растет погибельник?",a="Погибельник растет среди зараженных растений вокруг братской могилы, к северу от кладбища за пределами Брилла. Он распространяется по почве, сильно отравленной погребальными рвами и остатками чумы.",al={"doom weed location","where is doom weed","mass grave weeds","погибельник где найти","где растет погибельник","братская могила травы"}},{q="Какие опасности таятся возле зарослей погибельника?",a="Земли вокруг братской могилы заполонили гноллы Гнилошкуры. Эти дикие, зараженные болезнями падальщики агрессивно нападают на всех, кто подходит к месту захоронений, пока те собирают траву.",al={"doom weed monsters","mass grave enemies","gnolls near brill","погибельник монстры","враги братской могилы","гноллы возле брилла"}},{q="Чем растения Тирисфаля интересны Королевскому фармацевтическому обществу?",a="Королевское фармацевтическое общество постоянно изучает растения, яды и грибы, измененные порчей, по всем Тирисфальским лесам. Реагенты вроде погибельника собирают, чтобы очищать токсины, находить алхимические средства исцеления и создавать новое оружие для Отрекшихся против их врагов.",al={"apothecary interest","royal apothecary society tirisfal","forsaken herb gathering","интерес аптекарей","королевское фармацевтическое общество тирисфаль","сбор трав отрекшихся"}},{q="Кто такая «Леди», о которой говорит Холланд?",a="Леди — это леди Сильвана Ветрокрылая, Королева банши и правительница Отрекшихся. Аптекари Подгорода и Брилла часто упоминают ее имя, поскольку их алхимические труды официально выполняются по ее приказу.",al={"who is the lady","holland lady sylvanas","the lady undercity","кто такая леди","холланд леди сильвана","леди подгород"}}},fp="9,259,20.366.0,22.333.0,50.278.0,43.266.0,26.209.0,45.201.0,66.262.0,39.211.0"}
P.entries["quest:549"] = {n="РАЗЫСКИВАЮТСЯ: сторонники Синдиката",s="Этот указ, вывешенный на доске объявлений Мельницы Таррен от имени леди Сильваны, приговаривает к смерти всех членов Синдиката. Отрекшиеся стремятся уничтожить разбойников, собирающихся в руинах Крепости Дарнхольд, прежде чем они начнут угрожать операциям Орды в предгорьях.",h="Этот указ, вывешенный на доске объявлений Мельницы Таррен от имени леди Сильваны, приговаривает к смерти всех...",kw={"durnholde keep","high executor darthalia","hillsbrad foothills","syndicate","syndicate rogue","syndicate watchman","tarren mill","wanted","крепость дарнхольд","верховный палач дарталия","предгорья хилсбрада","синдикат","разбойник синдиката","страж синдиката","мельница таррен","разыскивается"},ang={["class:Rogue"]="Синдикат держит в Дарнхольде умелых карманников и убийц из засады, так что это задание становится прямым столкновением соперничающих мастеров скрытности.",["faction:Horde"]="Крепость Дарнхольд хранит мрачные воспоминания как крепость-лагерь, где некогда держали в плену орков; уничтожение разбойников, засевших в ее руинах, имеет для Орды символическое значение.",["race:Undead"]="Для Отрекшихся уничтожение живых остатков знати Альтерака — практическая необходимость, чтобы обеспечить безраздельный контроль над холмами Лордерона."},sec={{t="Постоянный приказ о казни",b="Внезапное появление Синдиката к юго-востоку от Мельницы Таррен не осталось незамеченным Отрекшимися. Вместо переговоров или обращения с ними как с простыми изгнанными дворянами леди Сильвана Ветрокрылая и ее командиры видят в Синдикате живую заразу. Указ требует немедленной смерти и уточняет, что все приведенные пленники будут казнены без суда."},{t="Руины Дарнхольда",b="Некогда печально известная крепость-лагерь для интернированных, Крепость Дарнхольд теперь лежит в руинах и беззаконии. Разбойники и стражи Синдиката пробрались в ее обрушенные стены и башни и используют древний оплот как оперативный центр. Для Верховного палача Дарталии избавление руин от вооруженных бандитов необходимо, чтобы защитить дорогу и юго-восточные подступы к Мельнице Таррен."}},faq={{q="Кто вывесил объявление о награде за сторонников Синдиката?",a="Награда объявлена по прямому приказу леди Сильваны Ветрокрылой и вывешена на доске объявлений в Мельнице Таррен. Доказательства казни принимает Верховный палач Дарталия, военный командир поселения.",al={"who posted wanted syndicate personnel","who wants syndicate dead","bounty poster","кто вывесил разыскиваются сторонники синдиката","кто хочет смерти синдиката","автор объявления"}},{q="Где находятся эти члены Синдиката?",a="Они собираются среди разрушенных камней Крепости Дарнхольд к юго-востоку от Мельницы Таррен за рекой, а также у разрушенной сторожевой башни к югу от главной крепости.",al={"where are syndicate rogues","durnholde syndicate location","where to find watchmen","разбойники синдиката где","синдикат дарнхольд местоположение","где найти стражей"}},{q="Почему Отрекшиеся хотят убить их, а не взять в плен?",a="Отрекшиеся считают Синдикат вероломными паразитами и вооруженной угрозой своей территории. Указ прямо приказывает немедленно казнить всех взятых под стражу членов, так что плен совершенно бессмыслен.",al={"why kill syndicate","why no prisoners","darthalia syndicate","зачем убивать синдикат","почему без пленных","дарталия синдикат"}},{q="Что делает Синдикат в Крепости Дарнхольд?",a="Синдикат, состоящий в основном из опозоренной знати Альтерака и наемников, использует заброшенные крепости, руины и башни по всему Лордерону как опорные пункты для набегов на поселения, ограбления путников и восстановления своей разрушенной опоры власти.",al={"why syndicate in durnholde","syndicate purpose hillsbrad","durnholde keep occupiers","зачем синдикат в дарнхольде","цель синдиката хилсбрад","захватчики крепости дарнхольд"}},{q="Что будет после уничтожения этих приспешников Синдиката?",a="Сокращение рядов разбойников и стражей побуждает Верховного палача Дарталию объявить высокоприоритетную награду за их местного предводителя — барона Вардуса.",al={"what quest is next","after wanted syndicate personnel","next bounty","какое задание дальше","после разыскиваются сторонники синдиката","следующая награда"}}},fp="27,273,26.365.0,22.379.0,46.225.0,42.187.0,55.236.0,46.236.0,54.168.1"}
P.entries["quest:55"] = {n="Морбент Скверн",s="Это задание — последний расчет с Морбентом Скверном, некромантом, обитающим на возвышенностях над Кладбищем Вороньего Холма. Вооруженные зачарованной реликвией «Проклятье Морбента», герои отправляются скорбящим Свеном Йоргеном, чтобы разрушить защиту чародея и положить конец его террору в западном Сумеречном лесу.",h="Это задание — последний расчет с Морбентом Скверном, некромантом, обитающим на возвышенностях над Кладбищем...",kw={"duskwood","morbent fel","morbent's bane","necromancer","raven hill","raven hill cemetery","sven yorgen","сумеречный лес","морбент скверн","проклятье морбента","некромант","вороний холм","кладбище вороньего холма","свен йорген"},ang={["class:Paladin"]="Сразить мерзкого некроманта и очистить Вороний Холм от его неестественных чар — истинное призвание рыцарей Света.",["class:Priest"]="Осквернение Кладбища Вороньего Холма требует духовного очищения, поэтому рассеивание колдовских чар Скверна становится священным долгом.",["faction:Alliance"]="Убийство Морбента Скверна устраняет одну из страшнейших угроз жителям Сумеречного леса, делает дорогу безопасной и воздает должное страданиям западных поселений вроде Вороньего Холма."},sec={{t="Насест над мертвыми",b="Морбент Скверн устроил логово в заброшенном доме на скалистом гребне к востоку от лагеря Свена, над раскинувшимся Кладбищем Вороньего Холма. Оттуда некромант направлял волны нежити, чтобы терроризировать окрестный лес и осквернять могилы Сумеречного леса. Защищенный мощной темной магией и окруженный преданными рабами из нежити, он оставался неуязвим для обычной стали."},{t="Месть Свена",b="Свен Йорген обезумел от горя, когда темные силы зверски убили его семью и вынудили его скрываться. Хотя Свен знает, что истинные виновники резни на его ферме — загадочные Темные всадники Каражана, мерзкое колдовство Морбента Скверна продлевает кошмар этого края. Убийство некроманта — единственная осязаемая крупица справедливости, оставшаяся Свену в этой проклятой земле."},{t="Проклятье Морбента",b="Прямое нападение на Морбента Скверна — самоубийство без сверхъестественной помощи: его защитные чары отражают обычные удары. Чтобы обойти эту защиту, Свен вручает искателям приключений Проклятье Морбента — зачарованный артефакт, созданный специально для разрушения магического щита некроманта. После его применения преграда рушится, и Скверн становится уязвим для смертного удара."}},faq={{q="Кто такой Морбент Скверн?",a="Морбент Скверн — могущественный некромант, управляющий нежитью, наводнившей окрестности Вороньего Холма. Он скрывается в доме на холме над Кладбищем Вороньего Холма и использует темное колдовство, чтобы защищаться и мучить живых в Сумеречном лесу.",al={"morbent fel lore","who is morbent fel","morbent fel background","морбент скверн предания","кто такой морбент скверн","морбент скверн история"}},{q="Почему для убийства Морбента нужно Проклятье Морбента?",a="Морбент Скверн окружает себя мощными чарами, делающими его почти неуязвимым для обычного урона. Проклятье Морбента — зачарованная реликвия, созданная специально для рассеивания этих защитных чар, чтобы сделать его уязвимым.",al={"morbents bane","why use morbents bane","how to beat morbent fel","проклятье морбента","зачем проклятье морбента","как победить морбента скверна"}},{q="Как Свен Йорген связан с Морбентом Скверном?",a="Свен потерял семью и ферму из-за темных сил, наводнивших Сумеречный лес. Хотя за резню ответственны загадочные Темные всадники, некромантическая хватка Морбента Скверна над округой олицетворяет гнойное зло западного Сумеречного леса, что делает его главной целью мести Свена.",al={"why does sven want morbent dead","sven yorgen morbent fel","sven revenge","почему свен хочет смерти морбента","свен йорген морбент скверн","месть свена"}},{q="Где можно найти Морбента Скверна?",a="Он обитает на верхнем этаже ветхого разрушенного дома на холме к востоку от лагеря Свена Йоргена, возвышающегося над западной частью Кладбища Вороньего Холма.",al={"morbent fel location","where is morbent fel","morbent house","морбент скверн местоположение","где морбент скверн","дом морбента"}},{q="Убил ли Морбент Скверн семью Свена?",a="Нет. Семью Свена убили загадочные Темные всадники, искавшие Косу Элуны. Однако некромантия Морбента Скверна отравила окрестности и осквернила могилы Сумеречного леса, поэтому его уничтожение необходимо для возвращения покоя.",al={"did morbent kill sven family","who slaughtered sven family","убил ли морбент семью свена","кто убил семью свена"}},{q="Что происходит после смерти Морбента Скверна?",a="Возвращение Проклятья Морбента Свену приносит скорбящему отшельнику небольшое утешение. Хотя неуловимые Темные всадники остаются на свободе, гибель Скверна разрушает некромантическую хватку над Вороньим Холмом и укрепляет репутацию искателя приключений по всему Сумеречному лесу.",al={"after morbent fel","quest conclusion","does sven get peace","после морбента скверна","завершение задания","обретет ли свен покой"}}},fp="11,289,24.408.0,16.390.1,14.367.0,19.237.0,44.233.0,48.301.0,31.166.0,35.250.1,40.258.1"}
P.entries["quest:550"] = {n="Битва за Хилсбрад",s="Это задание знаменует завершение кампании Отрекшихся против человеческого поселения Хилсбрад. Разгромив местные силы Альянса, вы по приказу Верховного палача Дарталии несете официальную рекомендацию Вариматрасу в Подгород.",h="Это задание знаменует завершение кампании Отрекшихся против человеческого поселения Хилсбрад.",kw={"battle of hillsbrad","darthalia","hillsbrad foothills","royal quarter","sealed commendation","tarren mill","undercity","varimathras","битва за хилсбрад","дарталия","предгорья хилсбрада","королевский квартал","запечатанное рекомендательное письмо","мельница таррен","подгород","вариматрас"},ang={["faction:Horde"]="Отбросив силы Альянса в Лордероне, вы обеспечиваете Орде важный плацдарм в Восточных королевствах.",["race:Undead"]="Донесение о вашей победе над живыми Хилсбрада приносит прямую похвалу из Королевского квартала и подтверждает ваше место в растущей империи Темной Госпожи."},sec={{t="Решающая кампания",b="Кампания в Предгорьях Хилсбрада — жестокая борьба за юг Лордерона. В ходе затяжной серии ударов, координируемых из Мельницы Таррен, бойцы Орды уничтожили фермеров, ополчение, кузнецов и городских правителей человеческого поселения. Когда присутствие Альянса было подорвано, а земли перешли под контроль Отрекшихся, Верховный палач Дарталия составляет официальную рекомендацию, чтобы о подвигах исполнителя узнало высшее командование."},{t="Аудиенция у повелителя ужаса",b="Запечатанное письмо Дарталии ведет прямо в Королевский квартал Подгорода, к Вариматрасу. Повелитель ужаса стоит рядом с леди Сильваной Ветрокрылой и руководит военными операциями по всему Лордерону. Хотя Плеть, наступающая с северных Чумных земель, остается главной смертельной угрозой для Темной Госпожи, защита южных границ от уцелевших человеческих поселений жизненно важна для молодого государства Отрекшихся."}},faq={{q="Что это за задание?",a="Это заключительная сдача задания в длинной цепочке Битвы за Хилсбрад. Выполнив поручения Верховного палача Дарталии в Мельнице Таррен, вы получаете от нее запечатанное рекомендательное письмо, которое нужно лично доставить Вариматрасу в Подгород.",al={"battle of hillsbrad finale","hillsbrad final quest","quest 550","финал битвы за хилсбрад","последнее задание хилсбрада","задание 550"}},{q="Где сдать Запечатанное рекомендательное письмо Дарталии?",a="Его нужно сдать Вариматрасу, который стоит рядом с леди Сильваной Ветрокрылой в Королевском квартале Подгорода.",al={"where is varimathras","turn in commendation","darthalia letter turn in","где вариматрас","сдать рекомендательное письмо","сдать письмо дарталии"}},{q="Почему Вариматрасу есть дело до Хилсбрада?",a="Как главный военный помощник Темной Госпожи, Вариматрас отвечает за стратегическую оборону и расширение владений. Хотя Плеть на севере — величайшая угроза для Подгорода, человеческие поселения на юге постоянно тревожат рубежи Отрекшихся. Устранение угрозы в Хилсбраде защищает их южную границу.",al={"why varimathras","varimathras role in hillsbrad","почему вариматрас","роль вариматраса в хилсбраде"}},{q="Кто такая Верховный палач Дарталия?",a="Верховный палач Дарталия — старший командир Отрекшихся в Мельнице Таррен в Предгорьях Хилсбрада, руководящая наступлением на соседнее человеческое поселение.",al={"darthalia","who gave the quest","дарталия","кто выдал задание"}},{q="Ведет ли это задание к другим поручениям в Хилсбраде?",a="Нет. Доставка рекомендации Вариматрасу — официальное завершение сюжета Битвы за Хилсбрад, награда за прорыв обороны города.",al={"next quest after battle of hillsbrad","what comes after quest 550","следующее задание после битвы за хилсбрад","что после задания 550"}},{q="Почему Отрекшиеся вообще напали на Хилсбрад?",a="Город Хилсбрад — один из последних организованных оплотов людей в Лордероне. Он союзен Альянсу, и его ополчение и близость представляют непосредственную военную угрозу Мельнице Таррен и южным подступам к Подгороду.",al={"why attack hillsbrad","hillsbrad lore","зачем нападать на хилсбрад","предания хилсбрада"}}},fp="19,252,19.464.0,27.452.0,19.247.0,51.112.0,42.304.0,31.181.0,54.159.0,61.236.0"}
P.entries["quest:5502"] = {n="Опекун Орды",ang={["faction:Horde"]="Для Орды сила — это не только боевое мастерство, но и общая воля защищать и возвышать слабых, которые однажды понесут знамя Вождя.",["race:Orc"]="Культура орков ценит отвагу и честь, а сострадание к ребенку-сироте вроде Грунта воплощает благородство, которое Тралл стремится привить новой Орде."},sec={{t="An Orphan's Farewell",b="After the adventures of Children's Week, Grunth thanks his guardian for showing him more than he ever dreamed he would see. Remembering his parents' advice to rise above hardship, he says he hopes to become a hero like the adventurer. His final request is to return home and tell the matron about their time together."},{t="Home to the Valley of Honor",b="Returning to the orphanage in the Valley of Honor, adventurers return their young charge back into the care of Orphan Matron Battlewail. Taking responsibility for the young is considered a profound duty in the new Horde, where war has left countless children without parents. Battlewail commends your compassion as the true measure of a hero of the Horde, and Grunth parts ways with a beloved pet to ensure you remember the bond forged during your travels."}},faq={{q="В чем смысл этого задания?",a="This quest concludes the Horde's Children's Week festivities. Return Grunth and the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor.",al={"warden of the horde summary","childrens week ending horde","опекун орды краткое содержание","конец детской недели орда"}},{q="Кто такой Грунт?",a="Grunth is an orcish youth residing at the Orgrimmar Orphanage in the Valley of Honor. During Children's Week, he is paired with a Horde champion who takes him across Kalimdor to see legendary figures and grand sights.",al={"who is the orc orphan","grunth lore","кто такой орк-сирота","грунт предания"}},{q="What do I bring back to the matron?",a="Bring the Orcish Orphan Whistle back to Orphan Matron Battlewail when Grunth is ready to return home.",al={"orphan whistle return","return grunth whistle"}},{q="Кто присматривает за сиротами в Оргриммаре?",a="Orphan Matron Battlewail manages the Orgrimmar Orphanage in the Valley of Honor, dedicating her life to sheltering and raising the Horde's war orphans.",al={"orphan matron horde","who runs the orphanage","попечительница сирот орда","кто управляет приютом"}},{q="Why does Grunth want to return home?",a="His Children's Week outings are finished, and he wants to tell the matron about the adventures and the kind guardian who took him along.",al={"grunth return home","children week farewell"}},{q="Почему Детская неделя важна для Орды?",a="Десятилетия безжалостных войн с демонами, людьми и кентаврами оставили бесчисленных детей Орды без семей. Детская неделя — время, когда воины отходят от поля боя и чтят будущие поколения Дуротара и не только.",al={"childrens week lore","why care for orphans horde","предания детской недели","зачем заботиться о сиротах орды"}}},fp="21,218,20.317.0,27.456.0,34.157.0,14.217.0,35.101.0,38.151.0,36.136.0,46.247.0"}
P.entries["quest:5541"] = {n="Боеприпасы для Громострела",s="Оружейнику Хегнару Громострелу не хватает пуль и пороха для стрелков, тренирующихся возле Старой Наковальни. Пропавший ящик боеприпасов бросили в заснеженной глуши у Серой берлоги, когда курьера обратили в бегство голодные вендиго.",h="Оружейнику Хегнару Громострелу не хватает пуль и пороха для стрелков, тренирующихся возле Старой Наковальни.",kw={"ammo","anvilmar","coldridge","grizzled den","hegnar","loslor rudge","rumbleshot","wendigo","боеприпасы","старая наковальня","холодный кряж","серая берлога","хегнар","лослор рудж","громострел","вендиго"},ang={["class:Hunter"]="Каждый стрелок Холодной Гряды хорошо знает лавку Хегнара; пока на ее полках свежие порох и пули, вы никогда не выйдете в дикие земли с пустым ружьем.",["profession:Engineering"]="Дворфийскому огнестрелу и минометам нужны тонкий порох и ровные пули, поэтому товар Громострела необходим местным механикам и стрелкам.",["race:Dwarf"]="Дворфийское мастерство зависит от непрерывных поставок между кузнями Старой Наковальни и передовыми оружейниками вроде Громострела."},sec={{t="Бегство курьера",b="Лослор Рудж из Поселка Сталежара обеспечивает бесперебойные поставки торговцам по всему Дун Мороге, но местные звери часто мешают. Его последняя партия тяжелых боеприпасов так и не дошла до придорожной мастерской Хегнара Громострела. Остановившись у системы пещер, известной как Серая берлога, перепуганный курьер столкнулся с местными вендиго и бежал, бросив тяжелый деревянный ящик в снегу."},{t="Порох и пули",b="Хегнар Громострел держит оружейную лавку прямо у главной дороги, ведущей от Старой Наковальни. На поляне у его кузни постоянно толпятся стрелки Стальгорна, горные пехотинцы и дворфийские минометные расчеты, желающие пристрелять оружие и потренироваться боевыми зарядами. Без постоянных ящиков пороха и свинца от поставщиков вроде Лослора обучение стрельбе быстро останавливается."}},faq={{q="Где потеряли ящик с боеприпасами?",a="Испуганный посыльный Лослора Руджа уронил груз, остановившись лагерем у Серой берлоги — пещеры, кишащей вендиго, в снежных холмах к юго-западу от Караноса.",al={"ammo location","where is rumbleshot ammo","crate location","где боеприпасы","где боеприпасы громострела","где ящик"}},{q="Кто такой Хегнар Громострел?",a="Хегнар Громострел — дворф-оружейник, держащий оружейную лавку у дороги возле Старой Наковальни. Он снабжает порохом, пулями и огнестрельным оружием горных пехотинцев, охотников и осадные расчеты, тренирующиеся поблизости.",al={"who is hegnar","rumbleshot","hegnar rumbleshot","кто такой хегнар","громострел","хегнар громострел"}},{q="Почему курьера прогнали?",a="Посыльный совершил ошибку, расположившись лагерем возле Серой берлоги — логова свирепых территориальных вендиго, бродящих по холмам к юго-западу от Караноса.",al={"why courier ran","wendigo attack","courier story","почему курьер убежал","нападение вендиго","история курьера"}},{q="Почему у Хегнара Громострела закончились боеприпасы?",a="Дворфийские стрелки и минометные расчеты постоянно расходуют порох и свинец на учебные стрельбы возле лавки Хегнара, поэтому его товар в большом спросе.",al={"why low on ammo","rumbleshot out of ammo","почему мало боеприпасов","у громострела нет боеприпасов"}},{q="Кто такой Лослор Рудж?",a="Лослор Рудж — дворф, поставщик инженерных товаров в Поселке Сталежара, чье предприятие отправляет боеприпасы Хегнару Громострелу.",al={"loslor rudge","who is loslor","лослор рудж","кто такой лослор"}},{q="Портятся ли найденные боеприпасы в снегу?",a="Дворфийские боеприпасы традиционно упаковывают в тяжелые деревянные ящики с защитой от непогоды, чтобы черный порох оставался сухим и годным даже в морозных метелях Дун Морога.",al={"ammo ruined by snow","wet powder","боеприпасы испорчены снегом","мокрый порох"}}},fp="19,236,18.424.0,15.410.0,30.174.0,25.197.0,31.148.0,43.156.0,20.122.0,44.165.0"}
P.entries["quest:5545"] = {n="Тридцать три несчастья",s="Бригадир Раелен из Лесопилки Восточной долины не успевает в срок поставить древесину. Местные медведи и волки прогнали ее работников от свежесрубленного леса, и ценные связки бревен брошены в северных лесах. Она рассчитывает на отважных искателей приключений, которые войдут в кишащий зверями лес и вернут бревна, пока контракт не потерян.",h="Бригадир Раелен из Лесопилки Восточной долины не успевает в срок поставить древесину.",kw={"bears","bundle of wood","deputy rainer","eastvale","elwynn forest","logging camp","supervisor raelen","timber","wolves","медведи","связка бревен","заместитель судьи рейнер","восточная долина","элвиннский лес","лесопилка","бригадир раелен","древесина","волки"},ang={["class:Hunter"]="Пробираться по рощам, кишащим хищниками, возвращая припасы и справляясь с опасными зверями, — это прямо отвечает главным инстинктам выживания следопыта.",["faction:Alliance"]="Добыча леса в Восточной долине обеспечивает восстановление Штормграда и содержание региональных застав без дорогостоящих перебоев в поставках."},sec={{t="Горящий срок",b="Лесопилка Восточной долины поставляет важный лес для восстановления и обороны Королевства Штормград. Вести лесозаготовки на краю дикой местности опасно, и Бригадир Раелен сейчас в затруднении. Ее бригада отстала от графика по важной поставке леса, а время уходит."},{t="Хищники в лесу",b="Дело не в нехватке поваленных деревьев, а в агрессивных местных зверях. Голодные волки и медведи к северу от лесопилки прогнали дровосеков, и те бросили аккуратно связанные пучки бревен, разбросанные по лесу. Хотя городские власти о звериной угрозе предупреждены, Раелен не может ждать, пока стража очистит местность, и вынуждена нанять странствующих героев, чтобы те быстро собрали древесину."}},faq={{q="Кто такая Бригадир Раелен?",a="Бригадир Раелен руководит повседневной работой Лесопилки Восточной долины в восточной части Элвиннского леса. Она надзирает за бригадами дровосеков и следит, чтобы поставки леса удовлетворяли нужды Штормграда и местных поселений.",al={"supervisor raelen","raelen","eastvale supervisor","бригадир раелен","раелен","бригадир восточной долины"}},{q="Почему древесина брошена в лесу?",a="Рабочие уже срубили, обрезали и связали бревна в пучки, когда дикие медведи и рыскающие волки выгнали их с поляны. Опасаясь за жизнь, они бежали в лагерь, не увезя груз.",al={"why wood left","abandoned lumber","forest wood","почему брошено дерево","брошенная древесина","лес в чаще"}},{q="Почему Раелен упоминает Заместителя судьи Рейнера?",a="Раелен говорит, что сообщила Заместителю судьи Рейнеру об агрессивных хищниках. Любопытно, что Заместитель судьи Рейнер находится далеко, на другом краю Элвиннского леса, в Гарнизоне у Западного ручья, — значит, либо сообщения передавали по официальным каналам стражи, либо местная власть распределена по провинции слишком тонко.",al={"deputy rainer raelen","why deputy rainer","rainer connection","заместитель судьи рейнер раелен","почему рейнер","связь с рейнером"}},{q="Где нужна древесина?",a="Лесопилка Восточной долины снабжает лесом все королевство: от восстановления городской инфраструктуры до укрепления частоколов и мостов. Срыв сроков вредит местной экономике и останавливает стройки по всему Элвинну.",al={"who needs the wood","lumber delivery","timber purpose","кому нужна древесина","поставка леса","назначение древесины"}},{q="Почему дровосеки не могут забрать древесину сами?",a="Дровосеки — обычные рабочие, оснащенные для рубки деревьев, а не для борьбы с дикими хищниками. После нападения агрессивных волков и медведей никто из них не готов рисковать жизнью, возвращаясь в чащу безоружным.",al={"why loggers scared","why not loggers","loggers wolves","почему дровосеки боятся","почему не дровосеки","дровосеки волки"}},{q="Где найти связки бревен?",a="Связки срубленного леса лежат на земле в лесистых местах сразу к северу от Лесопилки Восточной долины, где работали люди, пока местные звери их не прогнали.",al={"wood location","where are bundles","find bundles","где древесина","где связки","найти связки"}}},fp="19,381,18.366.0,23.444.0,25.223.0,39.217.0,38.302.0,27.225.0,50.248.0,39.188.0"}
P.entries["quest:555"] = {n="Нежный черепаховый суп",s="Шеф-повар Джессен из Южнобережья гордится тем, что готовит лучшие блюда к северу от Штормграда, но недавние беспорядки лишили его запасов свежего мяса черепах-щелкунов. Чтобы вернуть в меню таверны свой знаменитый нежный черепаховый суп, он просит путешественников, разбирающихся в кулинарии, отважиться на опасные северные воды близ Даларана и озера Лордамер.",h="Шеф-повар Джессен из Южнобережья гордится тем, что готовит лучшие блюда к северу от Штормграда, но недавние...",kw={"chef jessen","cooking","dalaran","hillsbrad","lordamere lake","snapjaw","soothing turtle bisque","southshore","turtle meat","шеф-повар джессен","кулинария","даларан","хилсбрад","озеро лордамер","щелкун","нежный черепаховый суп","южнобережье","мясо черепахи"},ang={["faction:Alliance"]="Возвращение уюта в Южнобережье помогает поддерживать боевой дух местных жителей, пока город в изоляции противостоит враждебным разбойникам Синдиката и экспансии Отрекшихся.",["profession:Cooking"]="Шеф-повар Джессен делится своим мастерством только с собратьями по кулинарии и в награду дает вам рецепт, чтобы вы приготовили собственную порцию нежного черепахового супа.",["race:Human"]="Для людей, приезжих из южных королевств, стряпня Джессена — редкий вкус дома и гостеприимства на истерзанном севере."},sec={{t="Северный деликатес",b="Южнобережье остается одним из последних уцелевших прибрежных городков Альянса в Лордероне и гордо хранит мирную жизнь среди растущих смут в регионе. Шеф-повар Джессен утверждает, что его кухня не уступает ни одной таверне к северу от Штормграда, а посетители якобы приходят даже из Темнолесья в Сумеречном лесу ради его фирменного блюда — нежного черепахового супа. Этот наваристый восстанавливающий суп целиком зависит от свежего мяса черепах-щелкунов, обитающих в реках и озерах северных гор."},{t="Опасность на Лордамере",b="В более спокойные годы Джессен сам добывал мясо черепах, отправляясь за магический купол Даларана к восточным берегам озера Лордамер. Однако растущая напряженность, враждебные звери, Синдикат и вторжения Отрекшихся сделали сбор припасов за пределами города смертельно опасным для обычных горожан. Чтобы его котел продолжал кипеть, а посетители оставались довольны, повар полагается на вооруженных искателей приключений, готовых добывать мясо щелкунов вдоль речных берегов и северных побережий."}},faq={{q="Кто дает задание на нежный черепаховый суп?",a="Это задание посетившим его поварам предлагает шеф-повар Джессен, мастер кулинарии из прибрежного города Альянса Южнобережья в Предгорьях Хилсбрада.",al={"who gives soothing turtle bisque","where do i start soothing turtle bisque","chef jessen quest","кто дает нежный черепаховый суп","где начать нежный черепаховый суп","задание шеф-повара Джессена"}},{q="Почему шефу-повару Джессену нужна посторонняя помощь в добыче черепашьего мяса?",a="Раньше Джессен сам охотился на черепах-щелкунов возле Даларана и озера Лордамер, но из-за политических беспорядков и хищных зверей в регионе стало слишком опасно, и ему пришлось нанимать искателей приключений.",al={"why cant jessen get meat","why does jessen need turtles","почему джессен не может достать мясо","зачем джессену черепахи"}},{q="Где в этом регионе водятся черепахи-щелкуны?",a="Черепахи-щелкуны обитают вдоль пресноводной реки между Предгорьями Хилсбрада и Альтеракскими горами, а также на берегах озера Лордамер к северу от Даларана.",al={"turtle meat location","where are snapjaws","where to farm turtle meat","где мясо черепахи","где щелкуны","где добыть мясо черепахи"}},{q="Нужно ли уметь готовить, чтобы взять это задание?",a="Да. Шеф-повар Джессен делится этим заданием и своими кулинарными секретами только с путешественниками, обученными профессии «Кулинария», хотя определенный уровень навыка для принятия не требуется.",al={"is cooking required","cooking profession required","can anyone take soothing turtle bisque","нужна ли кулинария","нужна ли профессия кулинария","кто может взять нежный черепаховый суп"}},{q="Чем знаменита кухня Южнобережья?",a="Шеф-повар Джессен хвастается, что в Южнобережье подают лучшие блюда к северу от Штормграда, а его прославленный черепаховый суп якобы привлекал гостей даже из Темнолесья.",al={"southshore food","why is jessen famous","darkshire travel for bisque","еда южнобережья","чем знаменит джессен","темнолесье суп"}},{q="О каких беспорядках сокрушается шеф-повар Джессен?",a="Хилсбрад и Альтерак охвачены открытым конфликтом между Отрекшимися с севера, разбойниками Синдиката, бродящими среди руин, и дикими хищниками, изгнанными падением Лордерона, из-за чего путешествовать мирным жителям опасно.",al={"hillsbrad unrest","why is it dangerous now","what unrest","беспорядки в хилсбраде","почему сейчас опасно","какие беспорядки"}}},fp="22,334,19.495.0,18.473.0,48.147.0,61.203.0,46.175.0,47.178.0,35.180.0,39.212.0"}
P.entries["quest:556"] = {n="Каменные талисманы",s="«Каменные талисманы» — задание Орды, которое выдает Хранитель Бел'варил в Мельнице Таррен: добыть у агентов Даларана в Альтеракских горах магические артефакты связывания. Отрекшиеся хотят изучить тайные методы, которыми маги Даларана порабощают могущественных элементалей и командуют ими. Сбор этих инертных талисманов — основа исследований Магуса по подчинению элементалей.",h="«Каменные талисманы» — задание Орды, которое выдает Хранитель Бел'варил в Мельнице Таррен: добыть у агентов...",kw={"alterac mountains","binding","dalaran","elementals","hillsbrad foothills","keeper bel'varil","magus voidglare","stone tokens","tarren mill","worn stone token","альтеракские горы","связывание","даларан","элементали","предгорья хилсбрада","хранитель бел'варил","магус войдглар","каменные талисманы","мельница таррен","потертый каменный талисман"},ang={["class:Mage"]="Чародеи Даларана славятся умением подчинять элементалей своей воле; изучение этих талисманов показывает, как человеческие маги привязывают духов иных планов к материальным фокусам.",["class:Shaman"]="Хотя шаманы чтят элементалей на основе взаимных уз, волшебники Даларана используют тайные талисманы, чтобы подчинять и порабощать их — это противоречит духовной гармонии.",["race:Undead"]="Для Отрекшихся Мельницы Таррен раскрытие тайн магии Даларана жизненно важно, чтобы защитить Лордерон от человеческих чародеев, затаившихся за фиолетовым куполом."},sec={{t="Тайное подчинение",b="Маги Даларана давно обладают грозным мастерством управления элементалями: с помощью особых проводников и зачарованных фокусов они подчиняют существ из иных измерений. Хотя сам город скрыт под огромным фиолетовым куполом, его агенты и оставшиеся силы патрулируют окрестности, используя элементалей как рабочую силу и оборонительные ударные отряды. Маг Войдглар, исследователь тайной магии, работающий на Отрекшихся в Мельнице Таррен, стремится изучить точную магию, с помощью которой Даларан принуждает этих существ к повиновению."},{t="Сбор инертных образцов",b="Вместо того чтобы сразу требовать мощные и нестабильные магические предметы, Хранитель Бел'варил поручает агентам добыть потертые и поблекшие талисманы. Собрав эти истощенные обереги у персонала Даларана на окраинах и возле ближайшего лагеря для интернированных, Войдглар сможет безопасно изучить остаточные чары, не рискуя неконтролируемой реакцией иных миров. Эти выветрившиеся талисманы дают базовые теоретические знания, необходимые до испытаний более мощных механизмов связывания."}},faq={{q="Для чего нужны каменные талисманы?",a="Волшебники Даларана создают и носят эти каменные талисманы как магические фокусы для управления элементалями и их подчинения, заставляя существ из иных измерений служить стражами, часовыми и работниками.",al={"stone token purpose","why do dalaran wizards have stone tokens","what do the tokens do","назначение каменных талисманов","зачем магам даларана каменные талисманы","что делают талисманы"}},{q="Почему Магусу Войдглару нужны именно потертые талисманы?",a="Потертые каменные талисманы сохраняют основу магической матрицы заклинаний связывания Даларана, но их тайная сила угасла. Поэтому Магусу Войдглару гораздо безопаснее разбирать и изучать их, не опасаясь яростного ответа элементалей или взрывной магической отдачи во время первых опытов.",al={"why worn stone tokens","why not active tokens","почему потертые каменные талисманы","почему не активные талисманы"}},{q="Кто такой Хранитель Бел'варил?",a="Хранитель Бел'варил — Отрекшийся, выдающий задания в Мельнице Таррен в Предгорьях Хилсбрада. Он руководит тактическими операциями против человеческих сил в регионе и помогает исследователям вроде Магуса Войдглара, добывая магические артефакты и враждебные реагенты на соседних землях.",al={"belvaril","who gives stone tokens quest","бельварил","кто дает задание каменные талисманы"}},{q="Где силы Даларана хранят эти талисманы?",a="Талисманы носят волшебники Даларана и их персонал, занимающие пограничные земли между западным Хилсбрадом и Альтеракскими горами, особенно возле купола Даларана и руин старого лагеря для интернированных орков.",al={"where to find stone tokens","dalaran forces location","где найти каменные талисманы","где силы даларана"}},{q="Что происходит после доставки талисманов?",a="Когда Бел'варил осмотрит инертные образцы, Магус Войдглар переходит от теоретического изучения к физическому удержанию и поручает добыть более тяжелые наручи Связывания прямо у самих элементалей.",al={"what comes after stone tokens","stone tokens follow up","что после каменных талисманов","продолжение каменных талисманов"}},{q="Почему Орда изучает магию Даларана?",a="Отрекшиеся считают уцелевших магов Даларана прямой территориальной и магической угрозой в Лордероне. Разгадав их тайные методы, заклинатели Отрекшихся смогут противостоять действиям Кирин-Тора, защищать свои границы и, возможно, обратить силы элементалей себе на пользу.",al={"why horde wants dalaran magic","forsaken dalaran interest","почему орда хочет магию даларана","интерес отрекшихся к даларану"}}},fp="12,374,18.557.0,24.482.1,35.194.0,55.302.0,24.283.0,50.235.0,46.231.1,42.296.0"}
P.entries["quest:559"] = {n="Доказательство Фаррена",s="«Доказательство Фаррена» — задание Альянса в Южнобережье, которое выдает лейтенант Фаррен Оринель. Чтобы подтвердить своему начальнику, маршалу Редпату, успехи прибрежного патруля, Фаррен отправляет новобранцев собирать отрубленные головы мурлоков на Западном побережье.",h="«Доказательство Фаррена» — задание Альянса в Южнобережье, которое выдает лейтенант Фаррен Оринель.",kw={"farren","heads","hillsbrad","murloc","orinelle","redpath","southshore","strand","фаррен","головы","хилсбрад","мурлок","оринель","редпат","южнобережье","побережье"},ang={["faction:Alliance"]="Чтобы удержать Южнобережье, нужно обезопасить его берега от местных хищников, чтобы застава могла заняться угрозами со стороны Синдиката и Орды.",["profession:Cooking"]="Для поваров, готовящих рыбные блюда в Южнобережье, брезгливое отвращение Фаррена к морепродуктам непонятно, хотя сражения на пляже нередко приносят запасы сырого улова."},sec={{t="Неохотная просьба",b="После первых зачисток побережья на участке «На побережье» Лейтенант Фаррен Оринель оказался под пристальным вниманием маршала Редпата и городского начальства. Заявить о зачистке местных мурлоков — одно, а предъявить неопровержимые доказательства скептичным начальникам — совсем другое. Не желая пачкать руки кровавой разделкой, Фаррен поручает бродячим искателям приключений вернуться на берег и собрать осязаемое доказательство убийства."},{t="Жуткие доказательства",b="Задание ведет бойцов на запад от Южнобережья, на Западное побережье, где прибрежные мурлоки гнездятся на мелководье. Лейтенанту нужно десять отрубленных голов мурлоков, чтобы успокоить офицеров городского гарнизона. Сам Фаррен ненавидит этих тварей и признает, что омерзительный вид и запах рыболюдов-амфибий напрочь отбили у него аппетит к главному продукту и основной еде Южнобережья."}},faq={{q="Кто такой лейтенант Фаррен Оринель?",a="Лейтенант Фаррен Оринель — городской офицер Альянса, служащий в Южнобережье. Хотя он рвется доложить начальству об успехе, насильственную и грязную часть охраны побережья он предпочитает перепоручать толковым искателям приключений.",al={"farren orinelle","who gives farren's proof","lieutenant farren","фаррен оринель","кто дает доказательство фаррена","лейтенант фаррен"}},{q="Зачем Фаррену отрубленные головы мурлоков?",a="Маршала Редпата и городских чиновников не удовлетворили простые устные доклады о том, что Западное побережье зачищено. Они потребовали вещественных доказательств гибели мурлоков, прежде чем официально признать успех патруля.",al={"why murloc heads","farren proof reason","why collect heads","зачем головы мурлоков","причина доказательства фаррена","зачем собирать головы"}},{q="Где находятся эти мурлоки?",a="Мурлоки обитают на Западном побережье — прибрежных пляжах, тянущихся прямо на запад от Южнобережья к границе Серебряного бора.",al={"murloc head location","where is western strand","murloc spots hillsbrad","где головы мурлоков","где западное побережье","места мурлоков хилсбрад"}},{q="Что происходит после сдачи «Доказательства Фаррена»?",a="Фаррен просит сообщить о гибели мурлоков маршалу Редпату. Приняв доказательства, Редпат переключает внимание на угрозы на Восточном побережье, а позже передает приказы Штормграда о новом назначении Фаррена.",al={"next quest after farren's proof","farren quest chain","farren's proof followup","следующее задание после доказательства фаррена","цепочка заданий фаррена","продолжение доказательства фаррена"}},{q="Почему Фаррену противны мурлоки?",a="Фаррен находит ходячих двуногих рыб по своей природе отвратительными. Возня с их холодными склизкими останками окончательно отбила у него желание есть рыбу, и повседневная жизнь в рыбацкой общине Южнобережья стала для него мучением.",al={"farren fish","why doesn't farren like fish","фаррен рыба","почему фаррен не любит рыбу"}},{q="Кто такой маршал Редпат?",a="Маршал Редпат — командующий офицер в силах обороны города Южнобережья, отвечающий за то, чтобы младшие офицеры вроде Фаррена Оринеля отчитывались за безопасность региона.",al={"captain redpath","who is redpath","капитан редпат","кто такой редпат"}}},fp="14,256,18.467.0,15.392.0,34.226.0,42.222.0,32.138.0,45.214.1,39.217.0,23.187.0"}
P.entries["quest:56"] = {n="Ночной Дозор",s="Это задание выдает командир Алтея Чернодрев в Темнолесье: искателей приключений просят сократить число нежити, поднимающейся на соседнем Безмятежном кладбище. Штормград вывел из Темнолесья официальный гарнизон, и местное ополчение полагается на странствующих наемников, чтобы сдерживать наступающие ужасы.",h="Это задание выдает командир Алтея Чернодрев в Темнолесье: искателей приключений просят сократить число...",kw={"althea ebonlocke","darkshire","duskwood","night watch","skeletal mage","skeletal warrior","stormwind","tranquil gardens","алтея чернодрев","темнолесье","сумеречный лес","ночной дозор","скелет-маг","скелет-воин","штормград","безмятежное кладбище"},ang={["class:Paladin"]="Безмятежное кладбище — оскорбление для Света: оскверненные могилы павших горожан требуют освященной стали и праведного суда.",["class:Priest"]="Упокоить этих измученных неспокойных скелетов — акт духовного милосердия в краю, задыхающемся под зловещими проклятиями.",["faction:Alliance"]="Для сторонников Альянса это поручение обнажает горькую правду о равнодушии Штормграда: жителям окраин приходится проливать кровь ради собственного выживания без помощи короны."},sec={{t="Брошенные короной",b="Сумеречный лес некогда находился под защитой Штормграда, но когда ресурсы короны истощились, а в столице воцарились политические раздоры, корона отозвала своих солдат. Темнолесье осталось почти беззащитным перед наступающими тенями. В ответ жители леса создали Ночной Дозор — доморощенное ополчение, которое сейчас возглавляет командир Алтея Чернодрев. Оно стоит между проклятым лесом и оставшимися жителями города."},{t="Очистка Безмятежного кладбища",b="К югу от Темнолесья лежит Безмятежное кладбище — некогда мирное место упокоения, а теперь оно кишит неупокоенными скелетами и восставшими заклинателями. Поскольку силы Ночного Дозора опасно растянуты по границам Сумеречного леса, командир Чернодрев направляет прибывающих искателей приключений уничтожать скелетов-воинов и скелетов-магов, пока мертвецы кладбища не вышли на дороги."}},faq={{q="Почему Ночному Дозору нужна помощь со стороны?",a="Штормград отозвал из Сумеречного леса свой официальный гарнизон, и Темнолесье осталось один на один со своими бедами. Ночной Дозор — всего лишь местное ополчение, у которого нет ни людей, ни припасов, чтобы без посторонней помощи отбиться от растущего числа нежити на всей территории.",al={"why need help","why darkshire weak","why no guards","зачем нужна помощь","почему темнолесье слабое","почему нет стражи"}},{q="Кто такая командир Алтея Чернодрев?",a="Алтея Чернодрев — родственница бургомистра Темнолесья, лорда Элло Чернодрева, и решительный командир Ночного Дозора. Она взяла на себя обязанность организовать оборону города и собрать всех способных бойцов, готовых противостоять темным угрозам Сумеречного леса.",al={"who is althea","commander ebonlocke","althea ebonlocke lore","кто такая алтея","командир чернодрев","алтея чернодрев предания"}},{q="Где находится Безмятежное кладбище?",a="Безмятежное кладбище лежит к югу от Темнолесья. Это действующее место захоронений, ставшее жертвой темной магии, пропитавшей Сумеречный лес: мертвецы восстают и нападают на путников возле границ города.",al={"tranquil gardens location","where is cemetery","where to find skeletons","где безмятежное кладбище","где кладбище","где найти скелетов"}},{q="Какие существа восстают на Безмятежном кладбище?",a="Кладбище заполонили в основном оживленные скелеты-воины и скелеты-маги. В отличие от обычных трупов, эти останки сохранили остатки воинского мастерства и тайной силы, поэтому они смертельно опасны для простых горожан.",al={"what undead are there","skeletons in duskwood","какая там нежить","скелеты в сумеречном лесу"}},{q="Пришлет ли Штормград подкрепление?",a="Нет. Штормград отозвал своих стражей с постов и полностью предоставил отдаленную окраину Сумеречного леса самой себе.",al={"stormwind help duskwood","will stormwind send troops","штормград помощь сумеречный лес","пришлет ли штормград войска"}},{q="Положит ли это задание конец угрозе на кладбище?",a="Нет, истребление скелетов на Безмятежном кладбище — лишь первый шаг. Ночной Дозор сталкивается с растущими угрозами в глубине леса, и для борьбы с усиливающейся порчей на этой земле потребуются новые вылазки.",al={"is this the only quest","night watch chain","это единственное задание","цепочка ночного дозора"}}},fp="15,294,22.441.0,29.371.0,43.267.0,34.254.0,39.225.0,50.218.0,40.138.0,52.211.0"}
P.entries["quest:560"] = {n="Доказательство Фаррена",s="«Доказательство Фаррена» — короткое задание на доставку в Южнобережье: искатель приключений несет жуткую добычу — головы мурлоков — от лейтенанта Фаррена Оринеля маршалу Редпату. Позволив другому проделать кровавую работу по охоте на побережье, брезгливый лейтенант поручает ему и сам доклад. Это промежуточный шаг на пути к признанию в городе на побережье Хилсбрада.",h="«Доказательство Фаррена» — короткое задание на доставку в Южнобережье: искатель приключений несет жуткую...",kw={"alliance","errand boy","farren orinelle","farren's proof","hillsbrad foothills","marshal redpath","murloc heads","southshore","альянс","мальчик на побегушках","фаррен оринель","доказательство фаррена","предгорья хилсбрада","маршал редпат","головы мурлоков","южнобережье"},ang={["faction:Alliance"]="Каждое мелкое поручение в Южнобережье помогает укреплять главный оплот Альянса в Лордероне против враждебных сил, наступающих с севера и с моря.",["race:Human"]="Для людей общение с Фарреном и Редпатом — откровенный взгляд на натянутую бюрократию и усталость гарнизона Хилсбрада на границе."},sec={{t="Брезгливый офицер",b="Лейтенант Фаррен Оринель должен патрулировать и охранять южное побережье Предгорий Хилсбрада, однако у него слабый желудок для жестокой действительности приграничной войны. Отправив искателя приключений истреблять мурлоков, заполонивших пляжи, он отказывается даже прикасаться к отрубленным головам, принесенным в качестве доказательства. Вместо того чтобы лично нести окровавленные трофеи в командование Южнобережья, Фаррен охотно сваливает это поручение обратно на принесшего."},{t="Доклад Редпату",b="В Южнобережье маршал Редпат руководит обороной города и боевой готовностью на фоне растущих угроз со стороны Мельницы Таррен и диких зверей. Мешок с головами мурлоков, полученный через посыльного, а не от самого лейтенанта, его вовсе не удивляет. Понимая, что искатель приключений стал посыльным Фаррена, Редпат достаточно практичен, чтобы принять помощь: Южнобережью нужен весь усердный труд, какой только можно найти, чтобы удержать свои границы."}},faq={{q="Почему лейтенант Фаррен не доставляет головы мурлоков сам?",a="У лейтенанта Фаррена просто нет желания возиться с окровавленным мешком отрубленных голов мурлоков. Уже наняв искателя приключений для сражений, он находит гораздо удобнее поручить ему и грязную доставку маршалу Редпату.",al={"why farren not go","farren proof why deliver","why errand boy","почему фаррен не идет сам","доказательство фаррена зачем доставлять","почему посыльный"}},{q="Кто такой маршал Редпат?",a="Маршал Редпат — старший военный командир Альянса в Южнобережье. Он руководит местной обороной, координирует городскую стражу и занимается различными региональными угрозами, нависшими над человеческим поселением в Предгорьях Хилсбрада.",al={"who is redpath","marshal redpath lore","southshore marshal","кто такой редпат","маршал редпат предания","маршал южнобережья"}},{q="Что дальше в цепочке заданий после этой доставки?",a="Доставка доказательства ведет к новым поручениям от маршала Редпата и лейтенанта Фаррена и завершается официальными донесениями о размещении войск и бумагами, отправляемыми в столицу, в Штормград.",al={"what comes next","farren's proof next quest","redpath next quest","что дальше","доказательство фаррена следующее задание","следующее задание редпата"}},{q="Почему мурлоки — приоритет для гарнизона Южнобережья?",a="Племена мурлоков плотно гнездятся на пляжах побережья Хилсбрада. Если их не сдерживать, они грабят прибрежные пути снабжения, донимают местных рыбаков и угрожают южным подступам к Южнобережью, пока город и так занят Отрекшимися на севере.",al={"why kill murlocs","murloc problem southshore","hillsbrad murlocs","зачем убивать мурлоков","проблема мурлоков южнобережье","мурлоки хилсбрада"}},{q="Что маршал Редпат думает о поведении лейтенанта Фаррена?",a="Маршал Редпат хорошо знает привычки Фаррена и сухо замечает, что посыльный стал «мальчиком на побегушках у Фаррена». Тем не менее Редпат рад любой помощи, ведь Южнобережью приходится туго и нужны любые способные руки.",al={"redpath opinion on farren","does redpath like farren","мнение редпата о фаррене","нравится ли редпату фаррен"}},{q="Где в Южнобережье находится маршал Редпат?",a="Маршала Редпата можно найти возле центра города и здания совета в Южнобережье: он следит за повседневной обороной поселения.",al={"find redpath","where is marshal redpath","redpath location","найти редпата","где маршал редпат","местонахождение редпата"}}},fp="14,384,19.481.0,17.495.0,63.239.0,23.229.0,54.204.0,53.260.0,63.230.0,47.147.0"}
P.entries["quest:561"] = {n="Доказательство Фаррена",s="«Доказательство Фаррена» — задание Альянса на доставку в портовом городе Южнобережье. От имени маршала Редпата искатель приключений доставляет приказ лейтенанту Фаррену Оринелю: сосредоточить военные силы на нагах, наступающих на Восточное побережье.",h="«Доказательство Фаррена» — задание Альянса на доставку в портовом городе Южнобережье.",kw={"eastern strand","farren orinelle","farren's proof","hillsbrad","marshal redpath","naga","promotion","southshore","восточное побережье","фаррен оринель","доказательство фаррена","хилсбрад","маршал редпат","наги","повышение","южнобережье"},ang={["class:Warrior"]="Знакомое разочарование для воинов под знаменем Альянса — мелкая зависть и офицерские интриги, где боевое мастерство нередко сталкивается с честолюбием командиров.",["faction:Alliance"]="Этот разговор позволяет заглянуть в бюрократическое и карьерное соперничество, кипящее в гарнизоне Южнобережья: даже в осажденных северных форпостах офицеры борются за престиж."},sec={{t="Смена приказов",b="Военное руководство Южнобережья отбивается от окрестных угроз, но маршал Редпат по-прежнему внимателен к опасностям с моря на южном побережье. Получив свежие сведения о вторжениях нагов на Восточное побережье, Редпат посылает через город гонца к лейтенанту Фаррену Оринелю с прямым приказом: оставить второстепенные дела, уничтожить земноводную угрозу и докладывать о ходе дел лично маршалу."},{t="Соперничество на побережье",b="Получив сообщение, лейтенант Оринель выдает тихую неприязнь, зреющую среди офицеров гарнизона Южнобережья. Вместо добросовестного подчинения Оринель подозревает, что Редпат пользуется недавно полученными общими сведениями, чтобы присвоить заслугу за усмирение побережья. Решив не дать начальнику получить повышение за счет пота его солдат, Оринель тут же начинает замышлять собственный путь снискать расположение короны."}},faq={{q="Какова цель этой доставки?",a="Маршал Редпат намерен перенаправить солдат лейтенанта Фаррена Оринеля против нагов, наводнивших Восточное побережье Хилсбрада, и требует, чтобы Оринель лично докладывал ему, как только будет достигнут заметный успех.",al={"what does redpath want","why send message to farren","farren proof 3 objective","чего хочет редпат","зачем послание фаррену","доказательство фаррена 3 цель"}},{q="Почему Фаррен Оринель с горечью воспринимает приказы Редпата?",a="Оринель считает, что Редпат действует на основе тех же самых разведданных, которые они только что получили оба. Он опасается, что маршал намерен присвоить заслугу за очистку побережья и получить повышение за тяжелый труд Оринеля.",al={"farren redpath rivalry","why is orinelle mad","orinelle promotion","соперничество фаррена и редпата","почему оринель зол","повышение оринеля"}},{q="Где находится Восточное побережье?",a="Восточное побережье тянется вдоль южной морской береговой линии Предгорий Хилсбрада к юго-востоку от Южнобережья, где наступающие наги устроили на песке мерзкие лагеря.",al={"eastern strand location","where are the naga","hillsbrad coast","восточное побережье где","где наги","побережье хилсбрада"}},{q="Что будет после доставки этого сообщения?",a="После этой встречи Оринель придумывает собственный план вместо того, чтобы безропотно подчиниться власти Редпата, и направляет посыльных искателей приключений вдоль побережья к верховному командованию в задании «Ха, Штормград!».",al={"next quest","what happens next","stormwind ho follow up","следующее задание","что дальше","ха, штормград продолжение"}},{q="Какие командиры участвуют в этом разговоре?",a="Маршал Редпат — главный командир гарнизона Южнобережья, а лейтенант Фаррен Оринель служит под его началом полевым лейтенантом, руководящим береговой обороной.",al={"who are farren and redpath","southshore officers","farren orinelle and redpath","кто такие фаррен и редпат","офицеры южнобережья","фаррен оринель и редпат"}},{q="Требуется ли в этом задании сражаться?",a="Нет. Этот шаг — чисто внутреннее поручение по передаче сообщения между офицерами Южнобережья, хотя оно напрямую связано с военным ответом на враждебных нагов на берегу.",al={"is there fighting","do i fight naga","farrens proof combat","есть ли бой","нужно ли сражаться с нагами","доказательство фаррена бой"}}},fp="14,268,18.467.0,20.452.1,37.209.0,60.210.0,36.198.0,46.211.1,46.174.0,40.187.0"}
P.entries["quest:562"] = {n="Ха, Штормград!",s="Лейтенант Фаррен Оринель отчаянно хочет вырваться из Южнобережья и вернуться на юг, в Штормград. Услышав, что верховное командование Альянса опасается растущей угрозы со стороны наг, он видит шанс для карьеры и нанимает искателя приключений, чтобы тот истребил змеелюдов: так он присвоит заслугу себе и добьется перевода.",h="Лейтенант Фаррен Оринель отчаянно хочет вырваться из Южнобережья и вернуться на юг, в Штормград.",kw={"daggerspine","farren orinelle","hillsbrad foothills","naga","reassignment","samuelson","southshore","stormwind ho","пронзающий гребень","фаррен оринель","предгорья хилсбрада","наги","перевод","самуэльсон","южнобережье","ха, штормград"},ang={["faction:Alliance"]="Командная структура Альянса в Хилсбраде растянута до предела, и простые городские стражники оказываются беспомощны перед такими чудовищными угрозами, как наги Пронзающего Гребня.",["race:Human"]="Для людей, служащих в Лордероне, Южнобережье — мрачное напоминание об утраченной северной славе, резко контрастирующее с отстроенным величием и безопасностью Штормграда на юге."},sec={{t="Билет из Южнобережья",b="Южнобережье находится на самом острие Лордерона, зажатое между силами Отрекшихся, бандитами Синдиката и неутомимыми морскими тварями. Для лейтенанта Фаррена Оринеля, обычного стражника, привыкшего к городским пьяницам и мелким дракам в Штормграде, такая служба просто невыносима. Когда от его бывшего наставника приходит весть, что верховное командование Альянса все сильнее тревожится из-за наг, наступающих на побережье, Фаррен видит прекрасную возможность покинуть север."},{t="Чужая слава на побережье",b="Несмотря на высокие амбиции, Фаррен открыто признает свою трусость: сразиться в открытом бою со свирепыми сиренами и береговыми охотниками Пронзающего Гребня ему не по храбрости и не по силам. Вместо того чтобы рисковать шкурой, он поручает искателю приключений прочесать пляжи к юго-востоку от Южнобережья, проредить ряды наг и совершить боевые подвиги, нужные ему для внушительного донесения майору Самуэльсону в Штормград."}},faq={{q="Почему Фаррен Оринель хочет убить наг?",a="Сами наги его не волнуют: он хочет уехать из Южнобережья. От наставника Фаррен узнал, что верховное командование Альянса обеспокоено угрозой наг, поэтому успешные операции против них — быстрый путь к повышению или переводу обратно в Штормград.",al={"why naga","farren motive","why kill naga in southshore","почему нааги","мотив фаррена","зачем убивать наг в южнобережье"}},{q="Может ли лейтенант Фаррен Оринель сразиться с нагами сам?",a="Нет. Фаррен открыто признает, что он всего лишь городской стражник, способный разнимать пьяные драки в тавернах или арестовывать буйных попрошаек. Свирепые наги Пронзающего Гребня внушают ему ужас, и ему приходится целиком полагаться на приезжих искателей приключений.",al={"why doesn't farren fight","is farren weak","farren combat","почему фаррен не сражается","слаб ли фаррен","бой фаррена"}},{q="Где находятся наги Пронзающего Гребня?",a="Береговые охотники и сирены Пронзающего Гребня устроили лагеря на побережье прямо к юго-востоку от поселения Южнобережье и бродят по берегам Великого моря в Предгорьях Хилсбрада.",al={"where are naga","daggerspine location","southshore naga beach","где наги","пронзающий гребень расположение","наги на пляже южнобережья"}},{q="Кто такой майор Самуэльсон?",a="Майор Самуэльсон — бывший наставник Фаррена Оринель в страже Штормграда. Фаррен готовит для него отчеты об истребленных нагах в надежде, что Самуэльсон задействует нужные связи и добьется для него перевода обратно на юг.",al={"major samuelson","samuelson stormwind","who gets the letter","майор самуэльсон","самуэльсон штормград","кому письмо"}},{q="Что происходит после выполнения этого задания?",a="Когда угроза наг будет ослаблена, а Фаррен присвоит вашу работу себе, он отправит вас на юг, в Крепость Штормграда, чтобы вы лично передали майору Самуэльсону его отчет и просьбу о переводе.",al={"what comes next","next quest after stormwind ho","reassignment quest","что дальше","следующее задание после ха штормград","задание о переводе"}},{q="Почему Фаррен так ненавидит Южнобережье?",a="Фаррен считает Южнобережье мрачным и опасным пограничным постом, далеким от цивилизованной безопасности Штормграда. Из-за соседей-нежити и прибрежных чудовищ он с горечью называет его «Покинутым Светом портом».",al={"why does farren hate southshore","light forsaken port","почему фаррен ненавидит южнобережье","покинутый светом порт"}}},fp="13,322,26.475.0,25.402.0,47.272.0,54.243.0,39.195.0,23.229.0,40.184.1,40.215.0"}
P.entries["quest:5621"] = {n="Облачение Луны",s="Облачение Луны — вводный обряд служения для юных жрецов-ночных эльфов в Доланааре. Задание дает наставница жрецов Лорна Утренний Свет: неофит должен позаботиться о раненой Часовой Шае, патрулирующей лес к югу от поселения. Выполнение этого долга означает официальное признание неофита в Сестринстве Элуны.",h="Облачение Луны — вводный обряд служения для юных жрецов-ночных эльфов в Доланааре.",kw={"dolanaar","garments of the moon","in favor of elune","laurna morninglight","sentinel shaya","sisterhood of elune","teldrassil","доланаар","облачение луны","во имя элуны","лорна утренний свет","часовая шая","сестринство элуны","тельдрассил"},ang={["class:Priest"]="Этот обряд показывает два столпа жречества: исцеление раненых союзников целительной молитвой и защиту их от будущей опасности божественными оберегами.",["race:NightElf"]="Для кальдораев Сестринство Элуны и Часовые тысячелетиями действуют рука об руку, защищая леса и народ от наступающей тьмы."},sec={{t="Священное призвание",b="В ветвях Тельдрассила Сестринство Элуны заботится как о духовной жизни кальдораев, так и о практической защите их границ. Когда часовая Шайя ранена во время патруля в опасной глуши к югу от Доланаара, жрица-наставница Лорна Утренний Свет не может покинуть свой пост, чтобы оказать помощь. Вместо этого она поручает недавно обученной послушнице доказать свою преданность: залечить раны Шайи и укрепить ее здоровье защитной магией."},{t="Облачения Сестринства",b="Жрецы, восстановившие силы Часовой Шаи, возвращаются в Доланаар, чтобы получить официальные одеяния. Эти облачения означают, что юный послушник перешел от простых занятий к практическому, спасающему жизни служению под покровом Луны. В обществе кальдораев поддержка Часовых — не просто военная задача, а акт единения с Элуной и важнейший долг ради безопасности Тельдрассила."}},faq={{q="Кто дает задание «Облачение Луны»?",a="Задание дает Лорна Утренний Свет, наставница жрецов, живущая в северном здании Доланаара в Тельдрассиле.",al={"who gives garments of the moon","where to start garments of the moon","garments of the moon questgiver","кто дает облачение луны","с чего начать облачение луны","кто выдает задание облачение луны"}},{q="Кому нужна помощь в этом задании?",a="Часовая Шая, ночная эльфийка-стражница, раненная во время патруля в глуши, ждет помощи к югу от Доланаара.",al={"who do i heal","injured sentinel location","where is sentinel shaya","кого лечить","где раненый часовой","где часовая шая"}},{q="Какая магия нужна, чтобы помочь Часовой Шае?",a="Вы должны исцеляющей магией закрыть раны Часовой Шаи и наложить защитные чары, укрепляющие ее выносливость, а затем вернуться в Доланаар.",al={"what spells to cast on shaya","how to complete garments of the moon","shaya objective","какие заклинания на шаю","как выполнить облачение луны","цель шаи"}},{q="Может ли любой класс взять это задание?",a="Нет. Задание «Облачение Луны» предлагают только жрецам-ночным эльфам как ранний этап их духовного обучения.",al={"is garments of the moon priest only","garments of the moon class requirement","can druids do garments of the moon","облачение луны только для жрецов","облачение луны требования к классу","могут ли друиды облачение луны"}},{q="Что символизирует награда — одеяние?",a="Одеяние, которое вручает Лорна Утренний Свет, служит знаком посвящения: вы преданно послужили Элуне и заслужили признанное место среди местного жречества.",al={"garments of the moon robe meaning","robe reward lore","significance of garments of the moon","смысл одеяния облачение луны","предания об одеянии","значение облачения луны"}},{q="Как связаны это задание и «Во имя Элуны»?",a="«Во имя Элуны» — вводный призыв посетить наставницу в Доланааре. Оно не обязательно для получения «Облачения Луны», но его нельзя выполнить после завершения «Облачения Луны».",al={"in favor of elune prerequisite","in favor of elune missed","order of dolanaar priest quests","во имя элуны предварительное условие","пропустил во имя элуны","порядок заданий жрецов доланаара"}}},fp="20,354,16.470.0,27.414.0,42.124.0,32.135.0,46.140.0,30.119.0,36.178.0,66.208.0"}
P.entries["quest:5622"] = {n="Во имя Элуны",s="«Во имя Элуны» — обряд посвящения для юных жрецов-ночных эльфов, готовых покинуть укромные ветви Тенистой долины. По указанию жрицы Шанды послушники отправляются по тропе в Доланаар, чтобы получить дальнейшие наставления и обучение у Лорны Утреннего Света.",h="«Во имя Элуны» — обряд посвящения для юных жрецов-ночных эльфов, готовых покинуть укромные ветви Тенистой...",kw={"dolanaar","garments of the moon","in favor of elune","laurna morninglight","priest","shadowglen","shanda","teldrassil","доланаар","облачение луны","во имя элуны","лорна утренний свет","жрец","тенистая долина","шанда","тельдрассил"},ang={["class:Priest"]="Это задание означает ваш переход от простых занятий послушника к полноценному служению и ведет вас к получению первых освященных жреческих одеяний.",["race:NightElf"]="Сестринство Элуны — духовное сердце и историческое руководство общества кальдораев, поэтому путь в Доланаар — глубоко традиционный рубеж для верующих."},sec={{t="Покидая долину",b="Для неофита, служащего Элуне в уединенном убежище Альдрассила, обучение начинается с простых молитв и защитных призываний под присмотром жрицы Шанды. Но замкнутая жизнь Тенистой долины не может подготовить жрицу или жреца к смуте, охватившей большой мир. Когда неофит проявляет стойкую веру и дисциплину, Шанда отправляет его по тенистой лесной тропе в Доланаар для продолжения обучения."},{t="Шаг к жречеству",b="Прибытие в Доланаар — важный рубеж на божественном пути ночного эльфа. Там ждет Лорна Утренний Свет, уважаемая жрица, которой поручено готовить учеников к испытаниям, стоящим перед Тельдрассилом. Помимо продвинутого обучения лунному колдовству, прибытие в Доланаар готовит послушника к получению первых официальных облачений, означающих его положение в Сестринстве Элуны."}},faq={{q="Кто отправляет меня в это путешествие?",a="Жрица Шанда, наставница жрецов-ночных эльфов, живущая в ветвях Альдрассила в Тенистой долине, дает вам это напутствие, когда ваше начальное обучение завершено.",al={"quest giver","who starts in favor of elune","where do i get this quest","персонаж, выдающий задания","кто начинает во имя элуны","где взять это задание"}},{q="Куда идти, чтобы найти Лорну Утренний Свет?",a="Лорна Утренний Свет живет в Доланааре, первом крупном поселении к югу от ворот Тенистой долины в Тельдрассиле. Она находится в северном здании деревни.",al={"laurna morninglight location","where is dolanaar","where is morninglight","где лорна утренний свет","где доланаар","где утренний свет"}},{q="Может ли любой класс взять это задание?",a="Нет. Это задание предназначено именно для юных жрецов-ночных эльфов, делающих первые шаги в Сестринстве и служении Элуне.",al={"is this priest only","who can do in favor of elune","druid quest?","только для жрецов","кто может выполнить во имя элуны","задание друида"}},{q="Что будет после разговора с Лорной Утренним Светом?",a="Лорна Утренний Свет поприветствует вас и предложит испытание «Облачение Луны», проверяющее вашу способность защищать и исцелять раненых защитников, после чего вам вручат первые официальные жреческие одеяния.",al={"what comes next","followup quest","garments of the moon quest","что дальше","следующее задание","задание облачение луны"}},{q="Обязательно ли это задание для продолжения обучения жрецов?",a="Это необязательное вводное задание. Если вы дойдете до Доланаара сами, Лорна Утренний Свет все равно предложит обучение и последующие задания без этого вступления.",al={"do i have to do in favor of elune","can i skip in favor of elune","optional breadcrumb","обязательно ли во имя элуны","можно ли пропустить во имя элуны","необязательное задание"}},{q="Почему получение облачений так важно для Сестринства?",a="Одеяния в культуре ночных эльфов — не просто ткань, а священные символы, обозначающие чье-то официальное положение, преданность и готовность направлять благословения Богини Луны на службу своему народу.",al={"why robes matter","significance of garments","station of elune priestess","почему важны одеяния","значение облачений","положение жрицы элуны"}}},fp="17,264,17.441.0,26.398.0,29.166.0,50.172.0,30.142.0,50.194.0,52.189.0,55.201.0"}
P.entries["quest:5623"] = {n="Во имя Света!",s="«Во имя Света» — ранний этап для жрецов-новичков, обучающихся в Долине Североземья. Задание дает жрица Анетта: оно направляет начинающего служителя из уединенного аббатства в Златоземье. Там его ждет жрица Жозетта, чтобы углубить его духовную дисциплину и повести дальше по пути веры в Свет.",h="«Во имя Света» — ранний этап для жрецов-новичков, обучающихся в Долине Североземья.",kw={"anetta","church","elwynn forest","goldshire","holy light","josetta","northshire","priest quest","анетта","церковь","элвиннский лес","златоземье","свет","жозетта","североземье","задание жреца"},ang={["class:Priest"]="Этот обряд соединяет ваше уединенное обучение в Североземье с деятельным пастырским служением среди жителей и гарнизонов Элвиннского леса.",["faction:Alliance"]="Церковь Священного Света — один из главных столпов Альянса, воспитывающий преданных целителей, способных поддерживать защитников на передовой.",["race:Human"]="Для людей Штормграда поиск наставлений у жречества в Златоземье — важный шаг в поддержании нравственного и духовного стержня королевства."},sec={{t="За пределы Североземья",b="Аббатство Североземья дает новичкам кров и начальное обучение, но жреческая подготовка в Церкви Священного Света требует практического служения в мире. Когда неофит показывает базовое владение молитвой и божественным исцелением, жрица Анетта отправляет его на юг по залитым солнцем дорогам в Златоземье. Это путешествие означает переход от затворника-ученика к деятельному служителю прихода среди повседневных забот жителей Элвинна."},{t="Наставничество в Златоземье",b="В таверне «Гордость Льва» в Златоземье жрица Жозетта заботится о духовных нуждах местных жителей и наставляет растущих послушников. Жозетта опирается на основы, заложенные в аббатстве, и проверяет умение неофита утешать, оберегать верных и исцелять раненых. Оказавшись под ее руководством, юный жрец знакомится с обязанностями служителей Церкви во всем королевстве."}},faq={{q="Кто дает это задание и кому докладывать?",a="Задание дает жрица Анетта в Аббатстве Североземья, отправляя вас по дороге к жрице Жозетте в Златоземье.",al={"who gives in favor of the light","quest turn in","where to turn in in favor of the light","кто дает во имя света","сдача задания","где сдать во имя света"}},{q="Почему жреца так рано отправляют из Североземья?",a="Североземье дает основы знаний о Свете, но юные служители должны быстро начать служить настоящим общинам. Златоземье — это готовая приходская среда, где послушник может помогать простым горожанам и городской страже под руководством Жозетты.",al={"why go to goldshire","why leave northshire abbey","зачем идти в златоземье","зачем покидать аббатство североземья"}},{q="Где найти жрицу Жозетту в Златоземье?",a="Жрица Жозетта живет в таверне «Гордость Льва» в Златоземье и служит местной наставницей жрецов.",al={"where is priestess josetta","find josetta","josetta location","где жрица жозетта","найти жозетту","жозетта расположение"}},{q="Что будет после встречи с жрицей Жозеттой?",a="Жрица Жозетта сразу проверяет ваше обучение следующим заданием «Облачение Света»: нужно позаботиться о раненом стражнике и получить церемониальные жреческие одеяния.",al={"next quest after in favor of the light","what follows in favor of the light","следующее задание после во имя света","что дальше во имя света"}},{q="Доступно ли это задание только жрецам?",a="Да. Это задание — формальное духовное обучение в Церкви Священного Света, и его предлагают только послушникам-жрецам.",al={"can any class do in favor of the light","is this priest only","любой класс во имя света","только ли для жрецов"}},{q="Какую роль играет Церковь Священного Света в Элвиннском лесу?",a="Церковь дает утешение, духовное руководство и телесное исцеление горожанам и защитникам, которым все чаще приходится сталкиваться с бандитизмом и вторжениями диких зверей по всему лесу.",al={"church of the holy light role","priests in elwynn","роль церкви священного света","жрецы в элвиннском лесу"}}},fp="21,329,26.447.0,21.407.0,45.123.0,51.268.0,50.104.0,45.199.0,36.131.0,59.170.0"}
P.entries["quest:5624"] = {n="Облачение Света",s="«Облачение Света» — начальное испытание для жрецов-новичков в Златоземье, которое выдает жрица Жозетта. Вместо отвлеченного испытания веры церковь посылает послушника на восток, к Озеру Хрустальному, исцелить и укрепить раненого стражника Робертса. Выполнив этот долг, ученик доказывает свое мастерство целителя и получает первое официальное облачение, признанное Церковью Священного Света.",h="«Облачение Света» — начальное испытание для жрецов-новичков в Златоземье, которое выдает жрица Жозетта.",kw={"crystal lake","elwynn forest","garments of the light","goldshire","guard roberts","lesser heal","power word fortitude","priest robe","priestess josetta","озеро хрустальное","элвиннский лес","облачение света","златоземье","стражник робертс","малое исцеление","слово силы: стойкость","одеяние жреца","жрица жозетта"},ang={["class:Priest"]="Этот обряд посвящения связывает теоретическое богословие в Североземье с практической службой, подтверждая, что высшее призвание жреца — сохранять жизнь соратникам на передовой прямым исцелением и укрепляющими оберегами.",["faction:Alliance"]="Поскольку армия Штормграда перегружена и отсутствует в местных деревнях, городская стража во многом полагается на помощь послушников церкви, чтобы устоять перед надвигающимися угрозами.",["race:Human"]="Люди глубоко почитают Церковь Священного Света; получение облачения от жрицы поселения становится важной гражданской и духовной вехой в жизни послушника."},sec={{t="Практическое испытание веры",b="По традициям Церкви Священного Света новичков редко возвышают только за знание доктрины. Жрица Жозетта, наставляющая послушников, прибывающих в Златоземье из Аббатства Североземья, проверяет практическое владение божественной силой, прежде чем даровать официальное признание церкви. Когда в город доходит весть, что стражник Робертс лежит раненый у озера к востоку от Златоземья, Жозетта превращает обычное несчастье в испытание и отправляет молодого жреца помочь ему."},{t="Опора королевства",b="Задание требует большего, чем просто закрыть раны: послушник должен исцелить раны стражника целительными молитвами и укрепить его выносливость благословением стойкости. В это тяжелое время, когда армия Штормграда растянута, а местные гарнизоны осаждают кобольды и бандиты, Жозетта подчеркивает, что долг жречества напрямую связан с выживанием воинов. Возвращая стражника Робертса в строй, послушник сразу приносит пользу поселению и показывает, что способен поддерживать защитников под огнем."},{t="Облачение ордена",b="Вернувшись в Таверну Гордость Льва после лечения солдата, молодой жрец получает свой первый официальный комплект одеяний. Эти одежды означают внешнее одобрение и братство жречества Штормграда. Хотя носить их для дальнейшего обучения не обязательно, одеяния служат видимым свидетельством того, что церковь признает владельца посвященным служителем Света."}},faq={{q="Где найти стражника Робертса?",a="Стражник Робертс находится к востоку от Златоземья, у берегов Озера Хрустального. Его можно найти отдыхающим у дороги и кромки воды: он оправляется от ран, полученных во время дозора.",al={"guard roberts location","where is guard roberts","find guard roberts","где стражник робертс","местонахождение стражника робертса","найти стражника робертса"}},{q="Какие заклинания нужны для выполнения этого задания?",a="Вы должны помочь стражнику Робертсу: применить к нему «Малое исцеление» (2-й уровень), чтобы восстановить здоровье, затем «Слово силы: Стойкость», чтобы укрепить его выносливость, и вернуться к жрице Жозетте.",al={"spells needed","what spells do i cast on roberts","how to heal guard roberts","нужные заклинания","какие заклинания применить на робертса","как исцелить стражника робертса"}},{q="Кто такая жрица Жозетта?",a="Жрица Жозетта — наставница жрецов от Церкви Священного Света, живущая в Таверне Гордость Льва в Златоземье. Она опекает молодых послушников, покинувших Аббатство Североземья, и обучает их практическому служению и божественной магии.",al={"josetta lore","priestess josetta goldshire","who gives garments of the light","жозетта предания","жрица жозетта златоземье","кто выдает облачение света"}},{q="Почему Церковь выдает одеяния за это задание?",a="Одеяния — внешний знак того, что Церковь Священного Света официально одобряет послушника и поддерживает его служение. Выполнив это практическое задание по исцелению, неофит доказывает, что обладает умением и дисциплиной, достойными церковного облачения.",al={"why garments of the light","priest robe reward lore","church robes meaning","почему облачение света","награда жреца одеяние предания","значение церковных одеяний"}},{q="Могут ли другие классы выполнить это задание?",a="Нет. Это задание входит во вводную цепочку заданий класса специально для жрецов Альянса, освоивших основные молитвы исцеления и защиты.",al={"is garments of the light priest only","can paladins do garments of the light","priest class quest","облачение света только для жрецов","могут ли паладины облачение света","задание класса жрец"}},{q="Что происходит после выполнения «Облачения Света»?",a="«Облачение Света» завершает начальную цепочку посвящения жрецов 4-го уровня в Златоземье. Прямого продолжения нет, но жрица Жозетта и другие наставники по всему королевству предложат продвинутое обучение и новые испытания по мере роста вашего опыта.",al={"next quest after garments of the light","garments of the light followup","следующее задание после облачения света","облачение света продолжение"}}},fp="21,390,25.489.0,20.527.0,22.402.0,31.190.0,48.185.0,25.224.0,49.260.0,38.157.0,52.271.0"}
P.entries["quest:5625"] = {n="Облачение Света",s="«Облачение Света» — начальный обряд посвящения для юных жрецов-дворфов в Дун Мороге. По указанию наставника жрецов Максана Анвола в Караносе посвящаемый должен помочь раненому горному пехотинцу неподалеку от города, чтобы заслужить облачение.",h="«Облачение Света» — начальный обряд посвящения для юных жрецов-дворфов в Дун Мороге.",kw={"dun morogh","fortitude","garments of the light","holy light","ironforge","kharanos","lesser heal","maxan anvol","mountaineer dolf","priest","дун морог","стойкость","облачение света","свет","стальгорн","каранос","малое исцеление","максан анвол","горный стрелок дольф","жрец"},ang={["class:Priest"]="Этот обряд знаменует ваш переход от неопытного новичка к признанному служителю Света, которому доверено сохранять жизнь соратникам на передовой.",["faction:Alliance"]="Свет — духовная опора Альянса, дающая утешение и исцеление на поле боя солдатам, удерживающим рубеж против троггов, зверей и худших врагов.",["race:Dwarf"]="Горные пехотинцы Стальгорна охраняют опасные перевалы Дун Морога; помощь раненым разведчикам вроде Дольфа укрепляет важную связь между верой дворфов и военной обороной."},sec={{t="Неотложное испытание",b="Традиционно послушники Света проходят официальные испытания, чтобы доказать, что достойны носить церковное облачение. Однако в Караносе наставник жрецов Максан Анвол ценит практический результат выше церемоний. Когда местные патрули едва справляются с троггами и дикими зверями, теоретические экзамены отходят на второй план, если защитники истекают кровью на снегу."},{t="Помощь горным пехотинцам",b="Чтобы заслужить одеяния, молодых жрецов отправляют к югу от города искать горного пехотинца Дольфа, раненного при исполнении долга. Исцелив раны Дольфа целительными молитвами и укрепив его телосложение «Словом силы: Стойкость», посвящаемый доказывает, что его преданность напрямую превращается в выживание защитников Стальгорна."},{t="Одеяния Церкви",b="После помощи горному пехотинцу Максан Анвол вручает послушнику официальное облачение. Помимо защиты от холода Дун Морога, эти одеяния служат знаком отличия и показывают раненым путникам и местной страже, что рядом находится служитель Света, готовый помочь."}},faq={{q="Какова цель этого задания?",a="Задание проверяет, как жрец-новичок применяет на практике свои первые заклинания. Вместо академического экзамена наставник Максан Анвол отправляет вас найти раненого горного пехотинца Дольфа к югу от Караноса, исцелить его раны и укрепить его выносливость «Словом силы: Стойкость».",al={"what do i do","garments of the light goal","что делать","цель облачения света"}},{q="Кто такой Максан Анвол?",a="Максан Анвол — наставник жрецов-дворфов в Караносе. Прагматичный и скромный, он обучает молодых жрецов, прибывающих из Холодной долины, и подчеркивает прямую, спасающую жизни пользу Света, а не строгую официальную литургию.",al={"who is maxan anvol","kharanos priest trainer","кто такой максан анвол","наставник жрецов каранос"}},{q="Кто такой горный стрелок Дольф?",a="Дольф — горный стрелок Стальгорна, расквартированный неподалеку от Караноса, получивший ранения в патруле. Он ждет к югу от поселения и служит практическим испытанием для посвящаемых, которых посылают исцелить его раны и даровать ему стойкость.",al={"dolf location","who is dolf","где дольф","кто такой дольф"}},{q="Почему жрец получает особое облачение за это задание?",a="Облачения и одеяния наглядно показывают преданность и положение служителя Света. И жители, и солдаты, увидев жреца в одеянии, сразу понимают, что перед ними тот, кто способен лечить смертельные раны и давать духовное наставление.",al={"why do priests wear robes","priest garments lore","почему жрецы носят одеяния","облачение жреца предания"}},{q="Почему дворфы поклоняются Свету?",a="Дворфы Стальгорна переняли философию Света за века тесного культурного обмена и союза с людьми Лордерона и Штормграда. Жрецы-дворфы сочетают традиционную горную суровость с искренним почитанием добродетелей Света — сострадания, стойкости и защиты.",al={"dwarf light lore","do dwarves believe in the light","дворфы свет предания","верят ли дворфы в свет"}},{q="Что происходит после этого испытания?",a="Максан Анвол призывает новоиспеченного послушника отправиться в путь, оттачивать боевые заклинания и заклинания поддержки и проверять свои пределы вместе с другими путниками. Более трудные испытания церкви ждут жреца по мере роста его опыта и силы.",al={"what comes after garments of the light","next priest trial","что после облачения света","следующее испытание жреца"}}},fp="21,246,15.353.0,23.345.0,19.304.0,34.274.0,19.237.0,24.223.0,58.268.0,38.304.0,41.237.0"}
P.entries["quest:5626"] = {n="Во имя Света",s="«Во имя Света» — обряд посвящения молодого жреца, выводящий его из уединенных учебных земель Холодной долины в широкие просторы Дун Морога. По указанию Бранстока Халдера послушники идут через горный туннель в Каранос, чтобы продолжить обучение у наставника жрецов Максана Анвола. Это знак того, что послушник готов принять настоящую ответственность и заслужить традиционное облачение своего призвания.",h="«Во имя Света» — обряд посвящения молодого жреца, выводящий его из уединенных учебных земель Холодной долины...",kw={"branstock khalder","coldridge valley","dun morogh","in favor of the light","kharanos","light","maxan anvol","priest","vestments","брансток халдер","холодная долина","дун морог","во имя света","каранос","свет","максан анвол","жрец","облачение"},ang={["class:Priest"]="Это задание — веха для юных жрецов: оно означает их официальный переход от базовой подготовки к активной службе и получение первого облачения.",["race:Dwarf"]="Жречество дворфов сочетает духовную преданность с практической стойкостью, отправляя послушников прямо из горнов Холодной долины в суровые морозные ветра Дун Морога."},sec={{t="Прощание со Старой Наковальней",b="В уединенной колыбели Холодной долины жрецы-дворфы начинают обучение под присмотром наставников вроде Бранстока Халдера. Когда новичок проявляет достаточное усердие и понимание магии Света, его начальное обучение подходит к концу. Вместо того чтобы держать способных учеников под защитой в Старой Наковальне, Халдер направляет их за горы, в Каранос, где служение и оборона пересекаются с повседневными трудностями жителей Дун Морога."},{t="Шаг к Караносу",b="Чтобы добраться до Караноса, нужно пройти через Туннель Холодной долины в продуваемые ветрами снега центрального Дун Морога. В поселении ждет Максан Анвол, старший жрец, которому поручено вести учеников дальше простейших молитв. Анвол твердо уверен, что преданность Свету требует в равной мере нравственного характера, физической выносливости и несгибаемой воли. Для послушников, доказавших свою решимость под его руководством, Анвол готовит первое официальное облачение."}},faq={{q="Кто посылает вас в это путешествие?",a="Брансток Халдер, наставник жрецов-дворфов в Старой Наковальне в Холодной долине, посылает вас в Каранос, когда вы проявили достаточные способности в обращении со Светом для продвинутого обучения.",al={"who gives quest","quest giver","branstock khalder","кто выдает задание","персонаж, выдающий задания","брансток халдер"}},{q="Кто такой Максан Анвол?",a="Максан Анвол — наставник жрецов в горной деревне Каранос. Он ведет развивающихся жрецов и учит их сочетать преданность с физической выносливостью и силой духа.",al={"maxan anvol lore","who is maxan anvol","kharanos priest trainer","максан анвол предания","кто такой максан анвол","наставник жрецов каранос"}},{q="Что происходит после встречи с Максаном Анволом?",a="Максан Анвол предлагает вам доказать свое достоинство в задании «Облачение Света»: помочь раненым местным жителям, после чего вы получите первые официальные одеяния жреца.",al={"next quest","what follows in favor of the light","garments of the light","следующее задание","что после во имя света","облачение света"}},{q="Почему жрецы должны так рано покидать Холодную долину?",a="Холодная долина дает лишь основы боя и колдовства. Более крупные поселения вроде Караноса сталкиваются с насущными логистическими и оборонными угрозами и дают молодым жрецам реальный опыт служения своему народу.",al={"why leave coldridge","leaving anvilmar","why go to kharanos","зачем покидать холодную долину","уход из старой наковальни","зачем идти в каранос"}},{q="Получают ли жрецы-люди это же задание?",a="Жрецы-люди в Элвиннском лесу выполняют равнозначный обряд посвящения под тем же названием: Жрица Анетта в Североземье направляет их к жрице Жозетте в Златоземье.",al={"human in favor of the light","northshire version","люди во имя света","версия североземья"}},{q="Чем здесь отличается взгляд дворфов на Свет?",a="Дворфы придают огромное значение физической силе, воле и практической выносливости наряду с благочестием. Как отмечает Максан Анвол, служение Свету на холодных горных вершинах требует силы тела не меньше, чем веры.",al={"dwarf light beliefs","dwarves and the light","верования дворфов о свете","дворфы и свет"}}},fp="21,430,17.478.0,22.495.0,30.192.0,19.195.0,40.178.0,49.222.0,41.181.0,51.211.0"}
P.entries["quest:5627"] = {n="Звезды Элуны",s="«Звезды Элуны» — важная веха в единении юной жрицы ночных эльфов с Богиней Луны. Когда послушницы доказывают преданность своему народу, их приглашают в Храм Луны в Дарнассе, чтобы обучить священным умениям, присущим только Сестринству Элуны.",h="«Звезды Элуны» — важная веха в единении юной жрицы ночных эльфов с Богиней Луны.",kw={"darnassus","priestess alathea","returning home","sisterhood of elune","stars of elune","starshards","temple of the moon","дарнасс","жрица алатея","возвращение домой","сестринство элуны","звезды элуны","звездные осколки","храм луны"},ang={["class:Priest"]="Этот обряд знаменует разделение между жрицами кальдораев и жрецами других рас, открывая звездные заклинания, дарованные только Богиней Луны.",["faction:Alliance"]="Хотя жрецы-люди и дворфы проповедуют преданность Свету, преданность ночных эльфов Элуне привносит в ряды Альянса древнюю особую небесную магию.",["race:NightElf"]="Для кальдораев служение Элуне неотделимо от гражданской и культурной жизни; ответ на зов Сестринства означает взросление на службе Тельдрассилу."},sec={{t="Обряд преданности",b="Жрицы ночных эльфов черпают священную силу не из общих философских принципов Света, как люди и дворфы, а непосредственно от своей богини, Элуны. Когда послушница проявляет стойкую преданность на службе своему народу, Сестринство в Дарнассе признает это служение. Призванную в Храм Луны жрицу сочтут достойной более глубокого единения и откроют ей знания о священных заклинаниях, передававшихся на протяжении тысячелетий поклонения."},{t="Дары Богини Луны",b="Откликнувшись на зов жрицы Алатеи, посвященная получает прямое обучение священным таинствам, присущим ее народу, например Звездным осколкам. Эти заклинания направляют сияющие небесные гнев и милость Белой Госпожи. Это обучение означает, что послушница вышла за рамки базовой подготовки и готова отправиться за пределы защитного полога Тельдрассила во имя Элуны."}},faq={{q="Для чего нужно это задание?",a="«Звезды Элуны» — это официальное признание посвященной Сестринством Элуны. После выполнения жрица Алатея обучает юную жрицу расовым заклинаниям ночных эльфов, например Звездным осколкам, что отмечает ее рост как избранного сосуда Богини Луны.",al={"stars of elune quest","what do i get","why do this quest","задание звезды элуны","что я получу","зачем выполнять задание"}},{q="Кто выдает задание «Звезды Элуны»?",a="Задание сдается жрице Алатее, рукоположенной предводительнице Сестринства Элуны, пребывающей в величественном Храме Луны в Дарнассе.",al={"who gives stars of elune","quest giver stars of elune","where is alathea","кто дает звезды элуны","персонаж, выдающий задание звезды элуны","где алатея"}},{q="Почему это задание доступно только ночным эльфам?",a="Обряды, которым обучают в этом задании, принадлежат именно Сестринству Элуны, древнему жречеству, управляющему верой ночных эльфов. В отличие от других жречеств Альянса, изучающих всеобщий Свет, жрицы кальдораев получают свою особую магию непосредственно через единение с Элуной.",al={"can humans do this","is this night elf only","who can do stars of elune","могут ли люди","только для ночных эльфов","кто может выполнить звезды элуны"}},{q="К чему ведет это задание в сюжетной линии жрецов?",a="Это задание следует сразу за «Возвращением домой», которое направляет начинающую жрицу, помогавшую по всему Тельдрассилу, обратно в столицу, чтобы продолжить обучение в Храме Луны.",al={"what comes before stars of elune","stars of elune prereq","returning home quest","что перед звездами элуны","звезды элуны предыдущее задание","задание возвращение домой"}},{q="Какую магию Элуна дарует своим жрецам?",a="Жрицы, преданные Элуне, плетут лунный свет, звездный свет и тень. Особые ритуалы, такие как Звездные осколки, позволяют служительницам-кальдораям обрушивать на врагов раскаленный небесный огонь, сочетая божественный суд со звездным гневом.",al={"elune spells","night elf priest magic","starshards lore","заклинания элуны","магия жрицы ночных эльфов","звездные осколки предания"}},{q="Где в Дарнассе это происходит?",a="Это происходит в Храме Луны, сияющем мраморном святилище, которое возвышается над южным кварталом Дарнасса и служит религиозным сердцем народа кальдораев.",al={"stars of elune location","where is priestess alathea","temple of the moon location","где звезды элуны","где жрица алатея","где храм луны"}}},fp="14,264,18.458.0,25.404.0,34.271.0,26.150.0,44.284.0,55.200.0,52.222.0,40.184.0"}
P.entries["quest:5628"] = {n="Возвращение домой",s="«Возвращение домой» — это призыв, адресованный юным жрицам ночных эльфов, забредшим так далеко, как людские земли Элвиннского леса. Жрица Жозетта в Златоземье передает срочное сообщение из Дарнасса, веля послушнице вернуться в Храм Луны для дальнейшего духовного обучения у жрицы Алатеи.",h="«Возвращение домой» — это призыв, адресованный юным жрицам ночных эльфов, забредшим так далеко, как людские...",kw={"darnassus","elune","goldshire","priestess alathea","priestess josetta","returning home","stars of elune","temple of the moon","дарнасс","элуна","златоземье","жрица алатея","жрица жозетта","возвращение домой","звезды элуны","храм луны"},ang={["class:Priest"]="У каждого ордена жрецов глубокие традиции; для послушниц-кальдораев истинное продвижение в лунных обрядах может одобрить только старшие жрицы Храма Луны.",["faction:Alliance"]="Взаимное гостеприимство Церкви Священного Света в Элвиннском лесу и Сестринства Элуны в Дарнассе показывает растущие узы сотрудничества между расами Альянса.",["race:NightElf"]="Далекое странствие за море, в земли молодых рас, — путь честолюбивый, но зов Тельдрассила и благословения Элуны всегда возвращают кальдораев в их священные обители."},sec={{t="Весть в Златоземье",b="Ночные эльфы — необычное зрелище в Элвиннском лесу, и юная послушница среди человеческих поселений сразу привлекает внимание. Когда такая жрица приходит в Златоземье, жрица Жозетта встречает ее с теплом и новостями. Сестра Элуны пересекла континенты в поисках молодой служительницы с неотложным приказом из Храма Луны: пора вернуться в Калимдор и продолжить свое призвание."},{t="Зов храма",b="В сердце Дарнасса стоит Храм Луны — средоточие веры и власти ночных эльфов. Жрица Алатея и верховная жрица Тиранда Шелест Ветра руководят обучением Сестринства, внимательно присматривая за ученицами, даже когда любопытство уводит их за море. Вернувшихся посвященных встречают с материнской заботой и сразу направляют к более глубокому изучению небесных таинств Богини Луны."}},faq={{q="Почему жрицу ночных эльфов призывают из людских земель?",a="Юные жрицы ночных эльфов, отправившиеся в Восточные королевства, по-прежнему связаны со своим священным орденом в Тельдрассиле. Жрица Алатея следит за их успехами и призывает обратно в Храм Луны, когда они готовы изучать высшие обряды Элуны.",al={"why am i called back","why returning home","priest quest goldshire","почему меня зовут обратно","зачем возвращение домой","задание жреца златоземье"}},{q="Кто такая жрица Жозетта?",a="Жрица Жозетта — человеческая наставница жрецов в таверне «Гордость Льва» в Златоземье. Она служит Свету, но уважает приезжих послушниц-кальдораев и выступает посредницей, когда посланницы из Дарнасса приходят искать своих заблудших сородичей.",al={"who gives returning home","goldshire priest trainer","priestess josetta","кто дает возвращение домой","наставник жрецов златоземья","жрица жозетта"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — старшая сестра Элуны, обучающая послушниц в Храме Луны в Дарнассе. Тесно работая с верховной жрицей Тирандой Шелест Ветра, она следит за ростом и духовной преданностью начинающих жриц ночных эльфов.",al={"who is alathea","temple priest trainer","priestess alathea","кто такая алатея","наставница храма","жрица алатея"}},{q="Что происходит после возвращения в Дарнасс?",a="Когда вы доложите о возвращении жрице Алатее в Храме Луны, она благополучно встретит вас дома и поручит следующее духовное задание — «Звезды Элуны», которое глубже раскрывает священную силу, дарованную богиней.",al={"what comes next","next quest after returning home","followup quest","что дальше","следующее задание после возвращения домой","продолжение задания"}},{q="Чем это отличается от обычного пути обучения?",a="Это альтернативное вводное задание, созданное для жриц ночных эльфов, которые выбрали развитие в людских землях, например в Элвиннском лесу, вместо Тельдрассила. Оно возвращает их к расовым наставникам в Дарнассе, чтобы открыть расовые умения жрецов.",al={"do all priests do this","is this quest mandatory","elwynn priest quest","все ли жрецы делают это","обязательное ли задание","задание жреца элвиннский лес"}},{q="Как посланница нашла послушницу так далеко, в Элвиннском лесу?",a="Жрица Сестринства проделала путь из Дарнасса в Восточные королевства и оставила сообщение наставникам Альянса, таким как жрица Жозетта в Златоземье, чтобы они высматривали странствующую послушницу и направляли ее домой.",al={"how did they know i was here","who tracked me to goldshire","как узнали что я здесь","кто выследил меня в златоземье"}}},fp="14,308,19.426.0,22.452.0,58.256.0,25.249.0,25.244.0,42.232.0,51.296.0,67.225.0"}
P.entries["quest:5629"] = {n="Возвращение домой",s="«Возвращение домой» — обряд посвящения для юных жриц ночных эльфов, служащих по всему Тельдрассилу. Проявив себя в глуши, послушниц призывают в величественный Храм Луны в Дарнассе, чтобы предстать перед жрицей Алатеей и верховной жрицей Тирандой Шелест Ветра.",h="«Возвращение домой» — обряд посвящения для юных жриц ночных эльфов, служащих по всему Тельдрассилу.",kw={"darnassus","dolanaar","elune","laurna morninglight","priestess alathea","returning home","sisterhood of elune","teldrassil","temple of the moon","tyrande","дарнасс","доланаар","элуна","лорна утренний свет","жрица алатея","возвращение домой","сестринство элуны","тельдрассил","храм луны","тиранда"},ang={["class:Priest"]="Этот призыв отражает переход жрицы от обычной лесной послушницы к официальной служительнице Сестринства Элуны, подчиняющейся непосредственно Дарнассу.",["race:NightElf"]="Для кальдораев ответ на зов в Храм Луны означает единение с культурными корнями и под бдительным взором верховной жрицы Тиранды Шелест Ветра."},sec={{t="Призыв из Дарнасса",b="Жрицы, проводящие первые дни за уходом за ранеными и очищением скверны вокруг Доланаара, быстро привлекают внимание Сестринства Элуны. Наставница Лорна Утренний Свет перехватывает многообещающих посвященных и объясняет, что жрица Алатея прислала весть с просьбой о встрече. Помощь местным поселениям важна, но каждая преданная должна укреплять единение с Матерью-Луной и откликаться на высший зов веры."},{t="В Храме Луны",b="Путь ведет за ветви Тельдрассила, в величественное сердце Дарнасса — Храм Луны. Возвышаясь над городом в мягком сиянии милости Элуны, святилище служит и главным местом поклонения, и духовной столицей кальдораев. Приглашение в эти залы означает, что в вас больше не видят просто неопытную ученицу, а видят посвященную, признанную непосредственно руководством жречества."},{t="Благосклонность Тиранды и Алатеи",b="Когда путники предстают перед жрицей Алатеей, приветствие теплое и материнское. Алатея разделяет бдительную гордость руководства и отмечает, что и она, и верховная жрица Тиранда Шелест Ветра радуются, когда посвященные отправляются в неведомый внешний мир и возвращаются невредимыми. Это возвращение знаменует начало более глубоких священных испытаний под непосредственным наставничеством Алатеи."}},faq={{q="Кто выдает задание «Возвращение домой»?",a="Лорна Утренний Свет, наставница жрецов в Доланааре в Тельдрассиле, выдает задание, когда юная жрица ночных эльфов достигает достаточной подготовки и опыта.",al={"who gives returning home","returning home quest giver","laurna morninglight quest","кто дает возвращение домой","персонаж, выдающий задание возвращение домой","задание лорна утренний свет"}},{q="Где находится жрица Алатея?",a="Жрица Алатея живет в Храме Луны в Дарнассе, расположенном ближе к центру столицы ночных эльфов в Тельдрассиле.",al={"where is alathea","priestess alathea location","temple of the moon priestess","где алатея","где найти жрицу алатею","жрица храма луны"}},{q="Почему жрица Алатея хочет меня видеть?",a="Старейшины и руководство Сестринства Элуны отметили вашу самоотверженную службу в глуши Тельдрассила. Алатея считает, что вы готовы к углубленному обучению и более серьезным духовным заданиям.",al={"why summoned to darnassus","why go to temple of the moon","почему вызвали в дарнасс","зачем идти в храм луны"}},{q="Может ли взять это задание любой класс?",a="Нет. «Возвращение домой» предназначено именно для жриц ночных эльфов как часть раннего развития класса и священного посвящения в высшие обязанности Сестринства.",al={"is returning home for all classes","can druids do returning home","priest only quest","возвращение домой для всех классов","могут ли друиды","задание только для жрецов"}},{q="Какое задание следует за «Возвращением домой»?",a="Когда вы доложите жрице Алатее и завершите это поручение, она доверит вам следующее задание — «Звезды Элуны».",al={"what comes after returning home","returning home followup","next quest","что после возвращения домой","продолжение возвращения домой","следующее задание"}},{q="Какое значение имеет Храм Луны для ночных эльфов?",a="Храм Луны — главный центр поклонения богине Элуне и правящая обитель, где верховная жрица Тиранда Шелест Ветра направляет и Сестринство, и народ кальдораев.",al={"temple of the moon lore","darnassus moon temple","предания храма луны","лунный храм дарнасса"}}},fp="14,291,24.448.0,29.439.0,32.370.0,36.170.0,35.143.0,42.204.0,30.165.0,34.127.0,61.204.0"}
P.entries["quest:563"] = {n="Новое назначение",s="«Новое назначение» — кульминация стараний лейтенанта Фаррена Оринеля вырваться со службы в Южнобережье. Составив преувеличенный отчет о своих подвигах против прибрежных наг, Фаррен отправляет искателя приключений в Крепость Штормграда, чтобы тот передал документы его бывшему наставнику, майору Самуэльсону.",h="«Новое назначение» — кульминация стараний лейтенанта Фаррена Оринеля вырваться со службы в Южнобережье.",kw={"daggerspine","farren orinelle","major samuelson","reassignment","redpath","southshore","stormwind keep","пронзающий гребень","фаррен оринель","майор самуэльсон","новое назначение","редпат","южнобережье","крепость штормграда"},ang={["faction:Alliance"]="Это поручение показывает повседневную бюрократическую политику военных Альянса, где дальние пограничные гарнизоны вроде Южнобережья нередко сталкиваются с комфортными устремлениями офицеров, желающих вернуться в Штормград.",["race:Human"]="Доставка отчета обнажает контраст между измученными людьми-беженцами и защитниками, удерживающими рубеж в Лордероне, и политическими маневрами в высоких залах Крепости Штормграда."},sec={{t="Билет из Южнобережья",b="Лейтенант Фаррен Оринель не скрывает презрения к своему месту службы в Предгорьях Хилсбрада. Затерянный в Южнобережье, вдали от удобств столицы и под строгим надзором маршала Редпата, Фаррен проводит дни в замыслах о переводе на юг. Присвоив себе заслугу в уничтожении соседних наг из племени Пронзающего Гребня, он надеется предстать незаменимым закаленным в боях офицером, достойным повышения."},{t="Связи в крепости",b="Чтобы добиться нового назначения, не вызвав подозрений маршала Редпата, Фаррен полностью обходит местную цепочку командования. Он полагается на личные связи с майором Самуэльсоном, старшим офицером Крепости Штормграда, когда-то наставлявшим его. Передав отшлифованный отчет прямо в руки Самуэльсона, Фаррен гарантирует, что его мнимые достижения попадут на стол человека, имеющего власть переводить личный состав гарнизонов."},{t="Бюрократия за работой",b="Получив досье в Крепости Штормграда, майор Самуэльсон выказывает сдержанное одобрение инициативы своего бывшего ученика в борьбе с угрозой наг. Однако военная бюрократия движется медленно. Вместо немедленного перевода Самуэльсон лишь обещает рассмотреть отчет на плановой проверке личного состава в следующем месяце, и судьба Фаррена в Южнобережье остается неопределенной."}},faq={{q="Почему Фаррен Оринель хочет нового назначения?",a="Лейтенант Фаррен Оринель ненавидит службу в Южнобережье: он считает этот отдаленный северный форпост скучным, опасным и недостойным себя. Он мечтает вернуться к относительной роскоши и безопасности Штормграда и хочет использовать свои отчеты о нагах для обоснования перевода.",al={"why leave southshore","farren motive","why does farren want to leave","почему уехать из южнобережья","мотив фаррена","почему фаррен хочет уехать"}},{q="Кто такой майор Самуэльсон?",a="Майор Самуэльсон — высокопоставленный офицер Крепости Штормграда, ведающий назначениями городской стражи. До нынешнего поста он был наставником лейтенанта Фаррена Оринеля в начале его карьеры в столице.",al={"who is samuelson","samuelson lore","кто такой самуэльсон","самуэльсон предания"}},{q="Почему Фаррен не может доставить отчет сам?",a="Фаррен несет действующую службу в Южнобережье и не может покинуть пост без разрешения. Кроме того, он пытается обойти непосредственного начальника, маршала Редпата, который, вероятно, воспрепятствовал бы корыстной просьбе о переводе.",al={"why do i have to deliver it","why not deliver himself","почему я должен доставить","почему не доставит сам"}},{q="Фаррен действительно сам победил нага?",a="Нет. Фаррен отправил искателей приключений убивать нага Пронзающего Гребня на Восточном побережье, а затем использовал их успех в докладе в поддержку своей просьбы о новом назначении.",al={"did farren kill naga","farren report truth","убил ли фаррен наг","правда об отчете фаррена"}},{q="Фаррена действительно переводят обратно в Штормград?",a="Не сразу. Майор Самуэльсон лишь обещает рассмотреть отчет на проверке личного состава в следующем месяце. Фаррен остается на службе в Южнобережье в обозримом будущем, пока колеса военной бюрократии королевства медленно крутятся.",al={"does farren get reassigned","does transfer work","переведут ли фаррена","работает ли перевод"}},{q="Где находится майор Самуэльсон?",a="Майор Самуэльсон находится в Крепости Штормграда — оплоте в сердце Штормграда, где располагаются верховное командование и регентский совет.",al={"samuelson location","where is major samuelson","где самуэльсон","где найти майора самуэльсона"}}},fp="12,312,26.432.0,16.435.0,19.386.1,45.274.0,23.217.0,44.226.0,44.157.0,55.245.1,33.140.0"}
P.entries["quest:5630"] = {n="Возвращение домой",s="«Возвращение домой» — вызов для странствующих жрецов-ночных эльфов, оказавшихся далеко от Калимдора в заснеженных скалах Дун Морога. По указанию дворфа, наставника жрецов Максана Анвола, новичку велено вернуться в Храм Луны в Дарнасе и доложить жрице Алатее.",h="«Возвращение домой» — вызов для странствующих жрецов-ночных эльфов, оказавшихся далеко от Калимдора в...",ang={["class:Priest"]="Этот обряд посвящения вновь связывает странствующих служителей с руководством Сестринства Элуны, помогая сохранить преданность Богине Луны даже вдали от дома.",["race:NightElf"]="Для кальдорая, терпящего ледяные ветра Дун Морога, этот вызов означает долгожданное возвращение в знакомые святилища и древние леса Тельдрассила."},sec={{t="Зов из-за моря",b="Ночные эльфы, решившие начать приключения рядом с союзниками-дворфами, сталкиваются с лютым холодом Дун Морога, совсем непохожим на безмятежные леса Тельдрассила. В Караносе дворф-учитель жрецов Максан Анвол отмечает стойкость эльфа, а затем передает срочное сообщение: жрица Элуны заходила, разыскивая их, с приказом из Дарнасса, требующим немедленного возвращения."},{t="Храм Луны",b="Путь ведет обратно к священным ветвям Тельдрассила, прямо к Храму Луны. Там жрица Алатея приветствует странника, принимая его вновь в лоно Сестринства Элуны. Радуясь, что еще один преданный служитель вернулся невредимым из чужих земель, Алатея быстро готовит жреца к следующим обрядам служения, начиная со «Звезд Элуны»."}},faq={{q="Кто посылает меня с этим заданием?",a="Максан Анвол, дворф-учитель жрецов из Караноса в Дун Мороге, передает вам сообщение. Он замечает, что недавно заходила другая жрица-ночная эльфийка, разыскивавшая вас.",al={"quest giver","who starts returning home","maxan anvol","персонаж, выдающий задания","кто начинает возвращение домой","максан анвол"}},{q="Куда нужно отправиться, чтобы выполнить его?",a="Вы должны вернуться в Дарнасс на острове Тельдрассил на севере Калимдора. Жрица Алатея ждет вас в Храме Луны.",al={"turn in location","where is priestess alathea","where do i go","место сдачи","где жрица алатея","куда идти"}},{q="Почему Храм Луны призывает меня обратно?",a="Жрица Алатея и верховная жрица Тиранда Шелест Ветра следят за развитием молодых послушников. Алатея хочет убедиться в вашей безопасности, услышать о ваших странствиях под покровом Элуны и начать следующий этап вашего духовного обучения через «Звезды Элуны».",al={"why returning home","priest summons reason","зачем возвращаться домой","причина вызова жреца"}},{q="Что происходит после разговора с жрицей Алатеей?",a="Когда вы доложите о возвращении, жрица Алатея предложит задание «Звезды Элуны», продолжая ваши начальные обряды как жреца кальдораев.",al={"next quest","what comes next","следующее задание","что дальше"}},{q="Почему ночной эльф оказался в Дун Мороге на 10 уровне?",a="Ночные эльфы-искатели приключений часто отправляются в Восточные королевства на корабле из Темных берегов в Гавань Менетилов, чтобы исследовать земли Альянса или странствовать бок о бок с дворфами и гномами.",al={"why dun morogh","night elf in ironforge","почему дун морог","ночной эльф в айронфорже"}},{q="Доступно ли это задание другим расам?",a="Нет, это задание предназначено именно для жрецов-ночных эльфов, обучающихся за границей в землях дворфов, и направляет их обратно в культурный и духовный дом в Дарнассе.",al={"can dwarves do returning home","who can take this quest","могут ли дворфы взять возвращение домой","кто может взять это задание"}}},fp="14,279,24.419.0,22.379.0,27.196.0,37.143.0,46.259.0,51.143.0,51.187.0,39.174.0"}
P.entries["quest:5631"] = {n="Возвращение домой",s="«Возвращение домой» — задание жрецов Альянса: многообещающих послушников-ночных эльфов, странствующих за границей, призывают обратно в Тельдрассил. Под руководством Брата Джошуа в землях людей юного жреца вызывает в Храм Луны в Дарнасе жрица Алатея для углубленного обучения тайнам Элуны.",h="«Возвращение домой» — задание жрецов Альянса: многообещающих послушников-ночных эльфов, странствующих за...",kw={"brother joshua","darnassus","priest","priestess alathea","returning home","stars of elune","teldrassil","temple of the moon","tyrande","брат джошуа","дарнасс","жрец","жрица алатея","возвращение домой","звезды элуны","тельдрассил","храм луны","тиранда"},ang={["class:Priest"]="Это задание связывает братство Церкви Священного Света и Сестринства Элуны, отмечая миг, когда юный послушник возвращается к своему народу, чтобы освоить особые обряды кальдораев.",["faction:Alliance"]="Слаженное сотрудничество Брата Джошуа в Восточных королевствах и жриц в Дарнассе отражает духовную дипломатию, сохраняющую единство Альянса.",["race:NightElf"]="Для жрецов-ночных эльфов, бывших среди людей или дворфов за морем, это паломничество становится священным возвращением домой в святилища Тельдрассила."},sec={{t="Зов из-за морей",b="Хотя жрецы-ночные эльфы порой бывают в человеческих землях вроде Штормграда, чтобы разделить духовное братство с Церковью Священного Света, их глубочайшие узы связаны с Сестринством Элуны. Когда Брат Джошуа сообщает послушнику, что его искал посланник ночных эльфов, это означает конец ранних странствий. Родной храм требует его присутствия для углубленного обучения под руководством ближнего круга верховной жрицы Тиранды Шелест Ветра."},{t="Храм Луны",b="Возвращение через моря в Дарнасс приводит странника прямо в святилище Храма Луны. Жрица Алатея тепло встречает вернувшегося послушника, радуясь его благополучному пути через неспокойный мир. Благополучное возвращение молодых учеников — радость и для Алатеи, и для Тиранды, но также и пролог к более трудным духовным испытаниям."}},faq={{q="Почему Брат Джошуа дает указания жрецу-ночному эльфу?",a="Брат Джошуа служит Церкви Священного Света в землях людей, где молодые жрецы Альянса часто учатся вместе. Сестра Элуны посетила его залы, чтобы передать весть, призывающую вас в Дарнасс, и Джошуа передает этот вызов.",al={"why brother joshua","brother joshua night elf","who sends me home","почему брат джошуа","брат джошуа ночной эльф","кто отправляет меня домой"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — старшая участница Сестринства Элуны в Храме Луны в Дарнассе. Тесно работая с верховной жрицей Тирандой Шелест Ветра, она руководит обучением и продвижением многообещающих жрецов-ночных эльфов.",al={"priestess alathea","alathea darnassus","who is alathea","жрица алатея","алатея дарнасс","кто такая алатея"}},{q="Что происходит после прибытия в Храм Луны?",a="Когда вы доложите жрице Алатее о благополучном прибытии, она приветствует вас дома и посвящает в следующий обряд, начиная задание «Звезды Элуны», чтобы углубить вашу связь с Богиней Луны.",al={"quest after returning home","what is next","stars of elune quest","задание после возвращения домой","что дальше","задание звезды элуны"}},{q="Может ли любая раса Альянса выполнить это задание?",a="Этот вызов предназначен для жрецов-ночных эльфов, ушедших далеко от Калимдора в начале обучения. Он гарантирует их возвращение в родной дом для изучения расовых традиций жречества под руководством Сестринства Элуны.",al={"is this night elf only","can humans do returning home","who can pick up returning home","только ли для ночных эльфов","могут ли люди взять возвращение домой","кто может взять возвращение домой"}},{q="Где находится Храм Луны?",a="Храм Луны стоит в южном районе Дарнасса на ветвях Тельдрассила. Он служит духовным сердцем культуры ночных эльфов и престолом власти верховной жрицы Тиранды Шелест Ветра.",al={"temple of the moon location","where is the temple","where is alathea","где храм луны","где находится храм","где алатея"}},{q="Почему Алатея упоминает Тиранду Шелест Ветра?",a="Тиранда Шелест Ветра — Верховная жрица Элуны и духовная предводительница ночных эльфов. Старшие жрицы вроде Алатеи действуют от ее имени, следя за тем, чтобы все послушники, представляющие их веру за границей, находились под наблюдением и обучались по стандартам Тиранды.",al={"why tyrande mentioned","tyrande whisperwind priestess","alathea and tyrande","почему упомянута тиранда","тиранда шелест ветра жрица","алатея и тиранда"}}},fp="14,314,21.478.0,22.380.0,64.272.0,25.248.0,51.209.0,36.234.0,40.219.0,45.266.0"}
P.entries["quest:5632"] = {n="Возвращение домой",s="«Возвращение домой» — призыв, который получают перспективные жрецы-ночные эльфы, служащие за пределами столицы. Жрица Алатея вызывает послушников в Храм Луны в Дарнассе, чтобы отметить их рост в Сестринстве Элуны и дать им дальнейшее наставление.",h="«Возвращение домой» — призыв, который получают перспективные жрецы-ночные эльфы, служащие за пределами...",kw={"darnassus","nara meideros","priest quest","priestess alathea","returning home","sisterhood of elune","stars of elune","temple of the moon","tyrande whisperwind","дарнасс","нара мейдерос","задание жрецов","жрица алатея","возвращение домой","сестринство элуны","звезды элуны","храм луны","тиранда шелест ветра"},ang={["class:Priest"]="Этот призыв — важная веха на вашем пути жреца: он награждает вашу раннюю службу прямым общением с Сестринством Элуны и дальнейшим обучением у него.",["faction:Alliance"]="Сестринство Элуны — духовное сердце ночных эльфов в Альянсе, оно готовит умелых целителей и божественных воителей к встрече с угрозами по всему Калимдору.",["race:NightElf"]="Для кальдораев благополучное возвращение в Храм Луны — глубокое возвращение домой, укрепляющее непреходящее культурное и духовное лидерство жрецов Элуны."},sec={{t="Посланница Сестринства",b="Пока молодые жрецы странствуют вдали, служа своему народу, их духовный рост не остается незамеченным. Когда послушник навещает Нару Мейдерос в Парке Штормграда, к нему прибывает посланница Сестринства Элуны со срочной вестью: руководство ордена требует его присутствия в Дарнассе. Это одновременно проверка и обряд признания, знаменующий переход от неопытного новичка к действующему служителю Матери Луны."},{t="Аудиенция в Храме Луны",b="Призыв направляет путника прямо к жрице Алатее в главное святилище Дарнасса — Храм Луны. Сестринство, во главе которого стоит верховная жрица Тиранда Шелест Ветра, пристально следит за своими разбросанными по миру членами. Благополучное возвращение на земли храма чтит общину и богиню и показывает, что милость Элуны направляла и хранила жреца в первых испытаниях в диких землях."}},faq={{q="Почему жрица призывает меня обратно в Дарнасс?",a="Жрица Алатея и Сестринство Элуны следят за духовным развитием своих учеников. Вас вызывают в Храм Луны из-за ваших быстрых успехов на пути ордена, что ведет прямо к более глубокому обучению и священному благословению.",al={"why returning home","reason for summons","why visit alathea","почему возвращение домой","причина вызова","зачем идти к алатее"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — высокопоставленная наставница Сестринства Элуны, находящаяся в Храме Луны. Работая непосредственно под началом верховной жрицы Тиранды Шелест Ветра, она обучает перспективных жрецов-ночных эльфов и посвящает их в священные обряды.",al={"who is alathea","alathea lore","priestess alathea identity","кто такая алатея","алатея предания","кто такая жрица алатея"}},{q="Куда ведет этот призыв дальше?",a="Доклад жрице Алатее сразу ведет к испытанию «Звезды Элуны» — древнему заданию жрецов, в котором вы учитесь направлять небесную силу богини на защиту своего народа.",al={"what quest is after returning home","next step in returning home","stars of elune lead in","какое задание после возвращения домой","следующий шаг возвращения домой","звезды элуны продолжение"}},{q="Кто посылает весть через Нару Мейдерос?",a="Посланница, отправленная непосредственно Сестринством Элуны, передала весть Наре Мейдерос. Орден поддерживает связь с жрицами, находящимися за границей, например с Нарой в Парке Штормграда, чтобы следить за своими послушниками.",al={"who sent nara","messenger of the sisterhood","кто послал нару","посланница сестринства"}},{q="Получают ли этот призыв другие расы или классы?",a="Нет. Это задание связано именно со жречеством ночных эльфов и Сестринством Элуны. Послушники других рас и вер обращаются за продвижением к собственным духовным наставникам и священным орденам.",al={"can non night elves do this","is this priest only","могут ли не ночные эльфы выполнить","только для жрецов"}},{q="Почему Алатея упоминает Тиранду Шелест Ветра?",a="Тиранда Шелест Ветра — верховная жрица Элуны и верховная предводительница как Сестринства, так и правительства ночных эльфов. Алатея работает непосредственно под ее началом в Храме Луны и следит за тем, чтобы воля и духовное наставление Тиранды доходили до каждого послушника.",al={"tyrande connection","tyrande alathea relation","связь с тирандой","тиранда и алатея"}}},fp="14,253,31.449.0,34.414.0,52.253.0,25.246.0,34.201.0,44.231.0,47.206.0,45.261.0"}
P.entries["quest:5633"] = {n="Возвращение домой",s="«Возвращение домой» — призыв для жрецов-ночных эльфов, находящихся в Стальгорне, вернуться в Храм Луны в Дарнассе. Посланница Сестринства разыскивала странствующих послушников и направляла их обратно к жрице Алатее для срочного обучения и духовных обязанностей.",h="«Возвращение домой» — призыв для жрецов-ночных эльфов, находящихся в Стальгорне, вернуться в Храм Луны в...",kw={"braenna flintcrag","darnassus","priest quest","priestess alathea","returning home","stars of elune","temple of the moon","браэнна кремнескал","дарнасс","задание жрецов","жрица алатея","возвращение домой","звезды элуны","храм луны"},ang={["class:Priest"]="Это задание возвращает вас из ранних странствий среди союзников Альянса к главному духовному дому жрецов-ночных эльфов — Храму Луны.",["faction:Alliance"]="Сотрудничество дворфов-священников Стальгорна и Сестринства Элуны в Дарнассе показывает, как фракции Альянса согласованно поддерживают странствующих искателей приключений.",["race:NightElf"]="Покинуть Калимдор ради Восточных королевств — редкое путешествие для молодого кальдорая, но наставление Элуны и жречества Тиранды достигает и Великого моря."},sec={{t="Вызов из Горного города",b="Даже странствуя далеко от Тельдрассила в шумных подземных залах Стальгорна, жрецы-ночные эльфы остаются связаны с Сестринством Элуны. Браэнна Кремнескал, наставница жрецов из дворфов в Мистическом квартале, передает сообщение, оставленное посетившей город жрицей ночных эльфов. Посланница искала молодых учеников вдали от дома и принесла весть, что наставники требуют их немедленного возвращения в столицу."},{t="Храм Луны",b="По прибытии в Храм Луны в Дарнассе вернувшиеся послушники докладывают прямо жрице Алатее. Встречая ученика под бдительным взором верховной жрицы Тиранды Шелест Ветра, Алатея выражает облегчение по поводу благополучного путешествия через моря. Срочный призыв становится порогом к более глубокой преданности и открывает путь к священным обязанностям, таким как «Звезды Элуны»."}},faq={{q="Кто выдает это задание?",a="Задание выдает Браэнна Кремнескал, наставница жрецов из дворфов, которую можно найти в Мистическом квартале Стальгорна.",al={"who gives returning home","quest giver returning home","braenna flintcrag location","кто дает возвращение домой","персонаж, выдающий задание возвращение домой","где браэнна кремнескал"}},{q="Кому нужно доложить в Дарнассе?",a="Вы должны поговорить с жрицей Алатеей, которая находится в Храме Луны в Дарнассе.",al={"where to turn in returning home","priestess alathea location","turn in returning home","где сдать возвращение домой","где жрица алатея","сдать задание возвращение домой"}},{q="Почему Сестринство призывает жрецов обратно?",a="Сестринство Элуны пристально следит за своими послушниками. Когда послушник доказывает свои способности вдали от дома, руководство в Дарнассе вызывает его для углубленного обучения и священных обрядов, таких как «Звезды Элуны».",al={"why returning home","why go back to darnassus","почему возвращение домой","зачем возвращаться в дарнасс"}},{q="Доступно ли это задание другим классам?",a="Нет, это задание предназначено именно для жрецов-ночных эльфов, которые в начале своих приключений добрались до Дун Мороге и Стальгорна.",al={"can warriors do returning home","priest only quest","могут ли воины выполнить возвращение домой","задание только для жрецов"}},{q="Что происходит после сдачи этого задания?",a="Жрица Алатея приветствует вас в Дарнассе и предлагает следующее задание «Звезды Элуны», которое глубже раскрывает учение богини.",al={"returning home next quest","followup to returning home","возвращение домой следующее задание","продолжение возвращения домой"}},{q="Откуда Браэнна знает, что нужно искать вас?",a="Жрица, посланная прямо из Храма Луны, прошла через Стальгорн в поисках послушников и оставила местным наставникам, таким как Браэнна, четкие указания отправлять всех странствующих ночных эльфов домой.",al={"why does braenna know me","ironforge priestess message","откуда браэнна знает меня","сообщение жрицы в стальгорне"}}},fp="14,273,31.415.0,22.389.0,22.104.0,32.94.0,43.227.0,41.135.0,41.145.0,38.207.0"}
P.entries["quest:5634"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — обряд посвящения для начинающих жрецов-людей в Штормграде. Его дает верховная жрица Лорена в Соборе Света, и он отмечает преданность послушника делу сохранения жизни в неспокойных землях Альянса. Пройдя это духовное обучение, жрецы получают экстренное благословение, чтобы исцелять собственные раны, когда все остальное бессильно.",h="«Молитва отчаяния» — обряд посвящения для начинающих жрецов-людей в Штормграде.",kw={"cathedral of light","cathedral square","desperate prayer","high priestess laurena","holy light","laurena","priest","stormwind","собор света","соборная площадь","молитва отчаяния","верховная жрица лорена","свет","лорена","жрец","штормград"},ang={["class:Priest"]="Этот обряд знаменует ваш переход от ученика-послушника к действующему служителю Света, способному выжить в смертельных испытаниях в полевых условиях.",["faction:Alliance"]="Сохранение целителей на передовой с помощью таких благословений, как «Молитва отчаяния», жизненно важно для поддержки солдат Альянса на опасных рубежах.",["race:Human"]="Жрецы-люди получают это учение непосредственно от иерархии Собора Света, что подтверждает роль Штормграда как главного центра веры людей."},sec={{t="Мольба во тьме",b="Жрецов, служащих в Соборе Света, учат направлять свою веру вовне, чтобы защищать соратников, врачевать смертельные раны и карать зло. Но даже самые преданные служители Света оказываются в одиночестве, в ловушке или на грани человеческой выносливости. «Молитва отчаяния» — это глубоко личное экстренное обращение, отчаянный крик о божественном вмешательстве, когда жизнь послушника висит на волоске."},{t="Благословение собора",b="Верховная жрица Лорена надзирает за многими служителями церкви на Соборной площади Штормграда и решает, когда послушник достоин более глубоких тайн учения. Проявив истинную преданность добродетелям Света по всему королевству, послушники-люди получают этот священный урок не просто как средство выживания, но и как торжественное подтверждение того, что их дальнейшая служба по-прежнему необходима королевству."}},faq={{q="Для чего нужна «Молитва отчаяния»?",a="«Молитва отчаяния» — экстренное воззвание к Свету, доступное жрецам-людям и жрецам-дворфам. Оно позволяет раненому жрецу мгновенно призвать божественную энергию, чтобы залечить собственные тяжелые раны, не тратя время на длинные заклинания.",al={"what does desperate prayer do","why desperate prayer","desperate prayer purpose","что делает молитва отчаяния","зачем нужна молитва отчаяния","назначение молитвы отчаяния"}},{q="Кто дает этот урок в Штормграде?",a="Верховная жрица Лорена, служащая в величественном Соборе Света на Соборной площади Штормграда, дает этот урок, когда послушник проявил достаточную преданность и опыт в большом мире.",al={"who teaches desperate prayer","where to get desperate prayer","high priestess laurena quest","кто учит молитве отчаяния","где получить молитву отчаяния","задание верховной жрицы лорены"}},{q="Почему жрецы получают именно это обучение?",a="Жрецы Света часто бросаются в опасность, чтобы помочь другим. «Молитва отчаяния» служит священной защитой: когда целители оказываются брошены или тяжело ранены, их вера может сохранить им жизнь.",al={"why do priests get desperate prayer","lore behind desperate prayer","почему жрецы получают молитву отчаяния","предание молитвы отчаяния"}},{q="Может ли любой искатель приключений выучить «Молитву отчаяния» здесь?",a="Нет. Это задание и урок строго предназначены для жрецов, чтущих учение Света и обучающихся под руководством Церкви Света.",al={"can anyone learn desperate prayer","is this quest priest only","может ли любой выучить молитву отчаяния","задание только для жрецов"}},{q="Где проходит этот обряд?",a="Он проходит в Соборе Света — возвышающемся духовном сердце Альянса, расположенном в северном районе Штормграда.",al={"desperate prayer location","where is laurena","где молитва отчаяния","где лорена"}},{q="Свойственна ли «Молитва отчаяния» только жрецам-людям?",a="В землях Альянса «Молитва отчаяния» доступна и людям, и дворфам среди духовенства, поскольку оба народа чтут Свет в рамках тесно связанных церковных традиций, сосредоточенных вокруг Штормграда и Стальгорна.",al={"do other races get desperate prayer","dwarf desperate prayer","получают ли другие расы молитву отчаяния","молитва отчаяния дворфы"}}},fp="16,372,18.426.0,24.414.0,40.245.0,36.209.0,46.233.0,47.159.0,32.139.0,44.210.0"}
P.entries["quest:5635"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — вводное задание для начинающих жрецов Альянса, служащих Церкви Священного Света. Проявив преданность и дисциплину в Элвиннском лесу, многообещающие служители вызываются в Собор Света Штормграда, чтобы продолжить священное обучение под руководством верховной жрицы Лорены.",h="«Молитва отчаяния» — вводное задание для начинающих жрецов Альянса, служащих Церкви Священного Света.",kw={"cathedral of light","desperate prayer","goldshire","high priestess laurena","holy light","priest","priestess josetta","stormwind","собор света","молитва отчаяния","златоземье","верховная жрица лорена","свет","жрец","жрица жозетта","штормград"},ang={["class:Priest"]="Это задание знаменует ваш официальный переход от послушника прихода в Златоземье к признанному ученику, которого доверяют старшему руководству Собора Света.",["faction:Alliance"]="Церковь Священного Света остается одной из сильнейших культурных и нравственных опор, объединяющих Альянс в эпоху нарастающих угроз.",["race:Human"]="Для людей, верных Свету, вход в величественный Собор Света — глубокое паломничество, подтверждающее ваш долг перед духовным сердцем королевства."},sec={{t="Вызов в столицу",b="Жрецы-новички, служащие в отдаленных поселениях Элвиннского леса, начинают свой путь под руководством местных наставников, таких как жрица Жозетта в Златоземье. Когда ученик проявляет себя в духе и делах, весть быстро доходит до старших жрецов в столице. Признанием становится прямой вызов в величественный Собор Света — духовное сердце Королевства Штормград, — означающий, что пора принять более глубокие и официальные обязанности в служении вере."},{t="Наставления Верховной жрицы",b="По прибытии в Собор служители представляются верховной жрице Лорене. Как одна из выдающихся руководительниц Церкви в городе, Лорена отвечает за духовные основы и практическую подготовку недавно возвышенных жрецов. Ее наставления готовят верующих к суровым испытаниям, стоящим перед Альянсом, и передают важнейшие знания о чудесах Света, включая жизненно важную мольбу о спасении, известную среди людей как «Молитва отчаяния»."}},faq={{q="Для чего нужно задание «Молитва отчаяния»?",a="Задание направляет многообещающих жрецов 10 уровня из Златоземья в Собор Света Штормграда, где начинающие служители встречаются с верховной жрицей Лореной для продолжения священного обучения.",al={"desperate prayer quest","what is desperate prayer quest","why do desperate prayer","задание молитва отчаяния","что за задание молитва отчаяния","зачем нужна молитва отчаяния"}},{q="Кто выдает задание «Молитва отчаяния»?",a="Жрица Жозетта, наставница жрецов в таверне «Гордость Льва» в Златоземье, передает вызов, когда вы докажете свою преданность.",al={"who starts desperate prayer","desperate prayer quest giver","кто начинает молитву отчаяния","персонаж, выдающий задание молитва отчаяния"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — одна из старших руководительниц Церкви Священного Света. Она живет в Соборе Света Штормграда, где обучает опытных служителей.",al={"who is laurena","high priestess laurena lore","кто такая лорена","верховная жрица лорена предания"}},{q="Где находится Собор Света?",a="Собор Света возвышается над Соборной площадью в северном квартале Штормграда и служит духовным центром для жрецов и паладинов королевства.",al={"where is cathedral of light","cathedral location stormwind","где собор света","расположение собора штормград"}},{q="Почему задание называется «Молитва отчаяния»?",a="Оно открывает жрецу углубленное обучение в Штормграде, где жрецы-люди традиционно изучают воззвание «Молитва отчаяния» — мольбу к Свету о немедленном спасении собственной жизни.",al={"why called desperate prayer","desperate prayer name meaning","почему называется молитва отчаяния","значение названия молитва отчаяния"}},{q="Получают ли это задание другие расы или классы?",a="Эта цепочка заданий предназначена для жрецов, покидающих Элвиннский лес, чтобы начать высшее обучение в столице — Штормграде.",al={"can dwarves do desperate prayer quest","is desperate prayer priest only","могут ли дворфы взять молитву отчаяния","только ли для жрецов молитва отчаяния"}}},fp="16,314,24.479.0,32.465.0,50.188.0,37.140.0,30.166.0,40.168.0,40.212.0,41.135.0"}
P.entries["quest:5636"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — задание жрецов Альянса, возвращающее странствующих служителей Света в Штормград. Его начинает жрица-ночная эльфийка Лорна Утренний Свет в Доланааре; оно призывает жрецов-людей, посетивших Тельдрассил, вернуться домой для важного духовного обучения у верховной жрицы Лорены.",h="«Молитва отчаяния» — задание жрецов Альянса, возвращающее странствующих служителей Света в Штормград.",kw={"cathedral of light","desperate prayer","dolanaar","high priestess laurena","laurna morninglight","priest quest","stormwind","teldrassil","собор света","молитва отчаяния","доланаар","верховная жрица лорена","лорна утренний свет","задание жреца","штормград","тельдрассил"},ang={["class:Priest"]="Это задание — важный обряд посвящения на 10 уровне: оно возвращает жрецов в лоно Собора Света, чтобы изучить особые расовые дары веры.",["faction:Alliance"]="Вызов показывает растущее сотрудничество внутри Альянса: жрицы ночных эльфов охотно согласуют действия с руководством церкви в Штормграде.",["race:NightElf"]="Хотя ночные эльфы почитают Богиню Луны Элуну, жрица Лорна Утренний Свет вежливо уважает чужеземных последователей Света, идущих под сенью Тельдрассила."},sec={{t="Весть из дома",b="Во время пребывания в древних ветвях Тельдрассила жрецы, верные Свету, могут привлечь внимание местного Сестринства Элуны. В Доланааре жрица Лорна Утренний Свет неожиданно становится посредницей: она сообщает, что другой жрец преодолел континенты, разыскивая вас. Понимая срочность вызова, Лорна советует вам без промедления вернуться на родину, желая добра вашей вере и даруя благословение Элуны."},{t="Вызов в Штормград",b="Путь лежит через Великое море к величественному Собору Света в сердце Штормграда. Там верховная жрица Лорена руководит духовным ростом верных Альянса. Служители, рано проявившие себя, вызываются к ней, чтобы постичь более глубокие таинства веры, в частности экстренное воззвание «Молитва отчаяния» — спасительный дар, доверяемый лишь преданным ученикам в их темный час."}},faq={{q="Кто выдает задание «Молитва отчаяния» в Тельдрассиле?",a="Задание выдает Лорна Утренний Свет, наставница жрецов из ночных эльфов в Доланааре, что в Тельдрассиле. Она передает срочное сообщение, оставленное жрецом из ваших родных земель.",al={"who gives desperate prayer","desperate prayer quest giver teldrassil","laurna morninglight quest","кто дает молитву отчаяния","персонаж, выдающий задание молитва отчаяния тельдрассил","задание лорны утреннего света"}},{q="Куда ведет это задание?",a="Задание направляет вас в Собор Света в Штормграде, где нужно лично поговорить с верховной жрицей Лореной.",al={"where do i go","turn in desperate prayer","where is laurena","куда идти","сдать молитву отчаяния","где лорена"}},{q="Почему ночная эльфийка отправляет жреца в Штормград?",a="Жрецы ночных эльфов почитают Элуну, но чужеземные жрецы, например люди или дворфы, прибывшие в Тельдрассил, по-прежнему следуют традициям Света. Лорна Утренний Свет уважает их веру и передает сообщения от религиозной иерархии их родины.",al={"why does a night elf send me to stormwind","night elf holy light","почему ночная эльфийка отправляет меня в штормград","ночные эльфы и свет"}},{q="Какова награда за выполнение этого задания?",a="Доклад верховной жрице Лорене открывает путь к углубленному духовному наставничеству и позволяет изучить «Молитву отчаяния» — мгновенную исцеляющую молитву, доступную только жрецам-людям и дворфам.",al={"desperate prayer reward","what spell do i get","награда молитва отчаяния","какое заклинание я получу"}},{q="Могут ли жрецы-ночные эльфы взять это задание?",a="Нет. Жрецы ночных эльфов поклоняются Элуне и изучают «Звездные осколки», а не «Молитву отчаяния». Этот вызов предназначен именно для жрецов-людей, исследующих Калимдор на низких уровнях.",al={"can night elves do desperate prayer","night elf priest desperate prayer","могут ли ночные эльфы взять молитву отчаяния","жрец ночной эльф молитва отчаяния"}},{q="Как вернуться в Штормград из Тельдрассила?",a="Нужно пройти через Дарнасс в Деревню Рут'теран, сесть на корабль до Аубердина на Темных берегах, затем на другом корабле пересечь море до Гавани Менетилов в Болотине и отправиться на юг через Лок Модан и Дун Морог, а затем через Подземный поезд в Штормград.",al={"how to get to stormwind from dolanaar","teldrassil to stormwind route","как добраться до штормграда из доланаара","путь из тельдрассила в штормград"}}},fp="16,300,19.476.0,24.457.0,52.185.0,27.129.0,51.279.0,45.188.0,47.204.0,52.254.0"}
P.entries["quest:5637"] = {n="Молитва отчаяния",s="«Молитва отчаяния» — задание-обряд посвящения, призывающее многообещающих жрецов-дворфов из Дун Морога в величественный Собор Света в Штормграде. Верховная жрица Лорена вызывает растущих служителей, чтобы они углубили свою преданность и освоили особые священные приемы. Оно знаменует переход жреца от местного обучения к более широкому служению Альянсу.",h="«Молитва отчаяния» — задание-обряд посвящения, призывающее многообещающих жрецов-дворфов из Дун Морога в...",kw={"cathedral of light","desperate prayer","dun morogh","kharanos","laurena","maxan anvol","priest","stormwind","собор света","молитва отчаяния","дун морог","каранос","лорена","максан анвол","жрец","штормград"},ang={["class:Priest"]="Это задание — веха вашего духовного пути, соединяющая обычное приходское служение с высшими священными приемами, которым учит непосредственно руководство Церкви.",["faction:Alliance"]="Духовное сотрудничество Стальгорна и Штормграда обеспечивает единство последователей Света вне расовых границ.",["race:Dwarf"]="Путешествие в Собор Штормграда укрепляет общий духовный завет между горным королевством Стальгорн и человеческим государством Штормград."},sec={{t="Вызов в Собор",b="Жрецы, начавшие службу среди снегов Дун Морога, со временем перерастают наставления местных учителей вроде Максана Анвола в Караносе. Когда послушник подает настоящие надежды, приходит официальный вызов от самой верховной жрицы Лорены. Такое прямое внимание руководства Собора Света означает, что молодой жрец готов к более глубоким тайнам и большей ответственности внутри веры."},{t="Узы между королевствами",b="Хотя в Стальгорне есть свои священные традиции в Мистическом квартале, Церковь Священного Света в Штормграде служит духовным центром и для людей, и для дворфов. Путь на юг через Подземный поезд связывает дворфийских служителей с более широкой церковной общиной и укрепляет духовное братство двух союзных королевств."}},faq={{q="Почему верховная жрица Лорена призывает жрецов-дворфов в Штормград?",a="Верховная жрица Лорена руководит высшим религиозным обучением в Соборе Света. Когда местные наставники, такие как Максан Анвол, видят, что служитель освоил основы, они направляют его к Лорене для обучения мощным приемам, например «Молитве отчаяния».",al={"why laurena call me","why go to stormwind priest","who is high priestess laurena","почему лорена зовет меня","зачем жрецу идти в штормград","кто такая верховная жрица лорена"}},{q="Что такое «Молитва отчаяния» в преданиях?",a="«Молитва отчаяния» — экстренное воззвание, которое используют клирики Света среди людей и дворфов. На грани смерти жрец издает инстинктивный, настойчивый крик веры, мгновенно затягивающий раны и возвращающий силы.",al={"desperate prayer lore","what is desperate prayer","how does desperate prayer work","предания молитва отчаяния","что такое молитва отчаяния","как работает молитва отчаяния"}},{q="Где происходит это задание?",a="Вызов начинается в Караносе в Дун Мороге, где Максан Анвол велит вам отправиться в Штормград. Он заканчивается в Соборе Света на Соборной площади Штормграда, где правит верховная жрица Лорена.",al={"quest location","where do i go","where is laurena","место задания","куда идти","где лорена"}},{q="Почему жрец-дворф учится у Верховной жрицы-человека?",a="Дворфы и люди разделяют веру в Свет, и этот союз окреп во время Второй войны. Хотя жрецы-дворфы часто служат в Мистическом квартале Стальгорна, Собор Света в Штормграде — один из главных центров веры, принимающий всех последователей Света из Альянса.",al={"why human trainer dwarf","dwarf church of light","ironforge vs stormwind light","почему наставник человек у дворфа","церковь света дворфы","стальгорн или штормград свет"}},{q="Как молодому путнику добраться до Штормграда из Дун Морога?",a="Самый быстрый и безопасный путь лежит через Город механиков в Стальгорне, где Подземный поезд ведет прямо под горами в Квартал Дворфов Штормграда.",al={"how to get to stormwind","travel to stormwind dwarf","deeprun tram","как добраться до штормграда","путь в штормград дворфу","подземный поезд"}},{q="Кто такой Максан Анвол?",a="Максан Анвол — дворф, учитель жрецов из Караноса в Дун Мороге. Он присматривает за начинающими клириками и учит их основам, пока они не станут достаточно дисциплинированными, чтобы учиться у высшего церковного руководства в Штормграде.",al={"maxan anvol lore","who gave quest","kharanos priest trainer","предания максан анвол","кто выдал задание","наставник жрецов каранос"}}},fp="16,353,26.418.0,21.360.0,67.277.0,37.245.0,33.220.0,60.290.0,60.190.0,19.226.0"}
P.entries["quest:5638"] = {n="Молитва отчаяния",s="Молитва отчаяния — задание-вызов для начинающих жрецов, посещающих Парк в Штормграде. По указанию жрицы-ночной эльфийки Нары Мейдерос новички-клерики отправляются через каналы в Собор Света, чтобы продолжить священное обучение у верховной жрицы Лорены. Это момент, когда посвященный переходит от обычной службы к более глубокому, особому единению со Светом.",h="Молитва отчаяния — задание-вызов для начинающих жрецов, посещающих Парк в Штормграде.",kw={"cathedral of light","desperate prayer","high priestess laurena","holy light","nara meideros","priest quest","stormwind","the park","собор света","молитва отчаяния","верховная жрица лорена","свет","нара мейдерос","задание жреца","штормград","парк"},ang={["class:Priest"]="Этот вызов знаменует официальное посвящение жреца в высшие духовные дисциплины и открывает путь к овладению спасительным призывом — «Молитвой отчаяния».",["faction:Alliance"]="Сотрудничество Нары Мейдерос в Парке и духовенства на Соборной площади подчеркивает тихую солидарность священных орденов Дарнасса и Штормграда.",["race:Human"]="Собор Света — главное святилище людского богослужения на юге Восточных королевств, поэтому наставничество Лорены становится культурной и духовной вехой."},sec={{t="Слово в Парке",b="В тихой роще Парка жрицы-ночные эльфийки, такие как Нара Мейдерос, поддерживают единение с Элуной среди шума Штормграда. Но узы веры между духовными наставниками Альянса преодолевают культурные границы. Когда посланник с Соборной площади ищет многообещающего ученика, Нара передает вызов с тихим ободрением и уверяет посвященного, что зов несет добрые вести, а не тревогу."},{t="Зов Собора",b="Пройдя по Соборной площади и ступив под высокие белокаменные арки Собора Света, посвященный является к верховной жрице Лорене. Будучи одной из старших духовных предводительниц Штормграда, Лорена ведет молодых служителей дальше простых начальных молитв. Она открывает им священное воззвание — Молитву отчаяния, личную мольбу о божественном вмешательстве, способную мгновенно исцелить тяжелые раны, когда служитель Света стоит на пороге смерти."}},faq={{q="Кто отправляет меня на это задание?",a="Жрица Нара Мейдерос, клерик-ночная эльфийка из Парка в Штормграде, передает весть о том, что руководство Собора ищет вас.",al={"quest giver","who gives desperate prayer","nara meideros","персонаж, выдающий задания","кто дает молитву отчаяния","нара мейдерос"}},{q="К кому нужно явиться в Штормграде?",a="Вам нужно поговорить с верховной жрицей Лореной, которая находится в Соборе Света на Соборной площади Штормграда.",al={"where to go","quest turn in","who is laurena","куда идти","сдача задания","кто такая лорена"}},{q="В чем значение Молитвы отчаяния?",a="Молитва отчаяния — важная дисциплина, которой обучают клериков Света среди людей и дворфов. Это мгновенное воззвание, призывающее божественную милость, которая мгновенно исцеляет произносящего в минуты крайней опасности.",al={"what does desperate prayer do","priest ability lore","desperate prayer spell","что делает молитва отчаяния","предания о способности жреца","заклинание молитва отчаяния"}},{q="Почему ночная эльфийка направляет жрецов в человеческий собор?",a="Хотя жрицы-ночные эльфийки поклоняются Элуне, а не Свету, которому служат люди и дворфы, духовные ордена Штормграда поддерживают тесные связи и взаимное уважение и передают друг другу вести, когда клерикам Альянса нужно обучение.",al={"why nara meideros","park to cathedral","night elf elune stormwind","почему нара мейдерос","из парка в собор","ночной эльф элуна штормград"}},{q="На каком этапе обучения приходит этот вызов?",a="Этот вызов приходит примерно на десятом уровне опыта и означает, что молодой жрец достаточно проявил себя в полевых условиях, чтобы осваивать более сложные божественные обряды.",al={"what level is this","when do i get desperate prayer","какой уровень","когда получить молитву отчаяния"}},{q="Где находится Собор Света?",a="Собор Света возвышается над Соборной площадью в северной части Штормграда, между Кварталом Дворфов и Парком.",al={"cathedral location","where is cathedral square","где собор","где соборная площадь"}}},fp="16,409,18.435.0,25.477.0,27.162.0,40.118.0,45.228.0,60.239.0,50.169.0,40.144.0"}
P.entries["quest:5639"] = {n="Молитва отчаяния",s="Молитва отчаяния — обряд посвящения для жрецов-дворфов, достигших зрелости в Стальгорне. По указанию верховного жреца Рохана аколиты отправляются через Подземный поезд в Штормград, чтобы продолжить обучение у верховной жрицы Лорены. Прибытие в величественный Собор Света знаменует переход посвященного к более глубоким тайнам исцеления и выживания.",h="Молитва отчаяния — обряд посвящения для жрецов-дворфов, достигших зрелости в Стальгорне.",kw={"cathedral of light","desperate prayer","ironforge","laurena","mystic ward","priest","rohan","stormwind","собор света","молитва отчаяния","стальгорн","лорена","мистический квартал","жрец","рохан","штормград"},ang={["class:Priest"]="Это паломничество знаменует ваш переход от местного обучения в Стальгорне к более широкой иерархии Церкви Священного Света.",["faction:Alliance"]="Совместное обучение священников отражает глубокий духовный союз и институциональное сотрудничество Стальгорна и Штормграда.",["race:Dwarf"]="Для молодых дворфов Каз Модана поездка в Штормград — это первое знакомство с культурой людей, величественной архитектурой и общей духовной преданностью."},sec={{t="Вызов в Штормград",b="В каменных сводах Мистического квартала Стальгорна верховный жрец Рохан наставляет дворфов-посвященных, преданных Свету. Когда аколит проявляет достаточную дисциплину и веру, Рохан направляет его на юго-запад, в человеческое королевство Штормград. Клерики людей и дворфов связаны тесными духовными узами, а высшее богословское обучение сосредоточено в величественных залах Штормграда."},{t="Собор Света",b="Прибыв по Подземному поезду, аколиты поднимаются на Соборную площадь. Там, в величественном Соборе Света, верховная жрица Лорена испытывает кандидатов от имени Церкви. Ее наставления посвящены отчаянным мольбам, к которым жрец прибегает в горниле битвы, когда телесные силы иссякают и смерть близка."}},faq={{q="Кто отправляет меня на это задание?",a="Это задание дает верховный жрец Рохан. Он возглавляет духовенство дворфов в Зале Тайн в Мистическом квартале Стальгорна.",al={"who gives quest","quest giver","rohan location","кто дает задание","персонаж, выдающий задания","где рохан"}},{q="Куда нужно отправиться, чтобы выполнить это задание?",a="Вам нужно отправиться в Собор Света в центре Соборной площади Штормграда. Верховная жрица Лорена ждет в главном святилище.",al={"where is laurena","where to turn in","stormwind turn in","где лорена","куда сдавать","сдача задания в штормграде"}},{q="Как лучше всего добраться из Стальгорна в Штормград?",a="Самый безопасный и быстрый путь — Подземный поезд, инженерное чудо, построенное гномами. Вход находится в восточной части Стальгорна и ведет прямо в Квартал Дворфов Штормграда.",al={"how to get to stormwind","travel to stormwind","tram location","как добраться до штормграда","путь в штормград","где поезд"}},{q="Почему жрецу-дворфу нужно учиться в человеческом городе?",a="Церковь Священного Света глубоко коренится в человеческой традиции, а главный центр обучения — Собор Света. Священники дворфов и людей действуют сообща, делясь учениями и традициями по всему Альянсу.",al={"why stormwind","dwarf human church","why laurena","почему штормград","церковь дворфов и людей","почему лорена"}},{q="Какую способность открывает это обучение?",a="Эта цепочка заданий приобщает вас к изучению Молитвы отчаяния — мгновенной молитвы самосохранения, которая быстро восстанавливает здоровье жреца в тяжелых ситуациях.",al={"quest reward","what spell do i get","desperate prayer ability","награда за задание","какое заклинание я получу","способность молитва отчаяния"}},{q="Есть ли в этом задании бои?",a="Нет. Это задание — чистое паломничество и поручение посланника: вам нужно безопасно добраться из Стальгорна в Штормград и представиться верховной жрице Лорене.",al={"is there fighting","quest combat","travel quest","есть ли бой","бой в задании","задание на путешествие"}}},fp="16,346,22.399.0,22.379.0,27.132.0,39.161.0,56.217.0,52.225.0,39.167.0,31.166.0"}
P.entries["quest:5640"] = {n="Молитва отчаяния",s="Молитва отчаяния — задание для юных жрецов-людей и дворфов, посещающих Дарнасс, которое направляет их обратно к собственным духовным традициям в Штормграде. Жрица Алатея понимает, что ночные эльфы черпают силу в Элуне, а последователям Света следует искать наставников своей веры. Завершив это путешествие, аколит возвращается к верховной жрице Лорене в Соборе Света.",h="Молитва отчаяния — задание для юных жрецов-людей и дворфов, посещающих Дарнасс, которое направляет их обратно...",kw={"alathea","cathedral of light","darnassus","desperate prayer","elune","holy light","laurena","stormwind","алатея","собор света","дарнасс","молитва отчаяния","элуна","свет","лорена","штормград"},ang={["class:Priest"]="Это задание показывает, что священная магия Альянса разделена между почитанием Элуны и преданностью Свету, и направляет юных аколитов обратно к их настоящим наставникам.",["race:Dwarf"]="Жрецы-дворфы, почитающие Свет, тесно связаны с собором Штормграда и осваивают высшие воззвания вместе со своими собратьями-людьми.",["race:Human"]="Жрецам-людям вдали от дома напоминают, что их истинный духовный дом и обучение ждут в Соборе Света в Штормграде.",["race:NightElf"]="Сестры Элуны из числа ночных эльфов с вежливым почтением признают силу чужих верований, но хранят строгую преданность одной лишь Матери Луне."},sec={{t="Два пути веры",b="Жрецы Альянса черпают силу из принципиально разных священных источников. В Дарнассе жречество Элуны служит богине луны, направляя ее мягкое сияние и небесный гнев. Когда аколиты-люди и дворфы приходят под ветви Тельдрассила, наставницы вроде жрицы Алатеи вежливо признают эту границу: она чтит Элуну и уважает Свет, но не может обучать другую расу глубоким молитвам, связанным с совсем иной верой."},{t="Возвращение в Собор",b="Чтобы овладеть способностями, рожденными абсолютной верой, например призывом божественного вмешательства в самый темный час, посвященным Света велят вернуться домой. Верховная жрица Лорена руководит обучением под высокими мраморными арками Собора Света Штормграда и готова провести вернувшихся жрецов к более глубоким обрядам их призвания."}},faq={{q="Почему жрица из Дарнасса отправляет меня в Штормград?",a="Жрица Алатея обучает путям богини луны Элуны. Поскольку люди и дворфы черпают веру и чудеса из Света, Алатея вежливо направляет их к наставникам их собственной традиции, например к верховной жрице Лорене в Штормграде.",al={"why go to stormwind","why alathea sends me away","darnassus to stormwind priest quest","почему в штормград","почему алатея отправляет меня","задание жреца из дарнасса в штормград"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — жрица-ночная эльфийка, служащая в Храме Луны в Дарнассе. Она наставляет будущих последователей Элуны и почтительно направляет приезжих жрецов, посещающих Мировое древо.",al={"alathea lore","who is alathea","предания об алатее","кто такая алатея"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — духовная предводительница людей, находящаяся в Соборе Света в Штормграде. Она наставляет многообещающих служителей Света, помогая им овладеть высшими молитвами и суровыми обязанностями.",al={"who is laurena","high priestess laurena stormwind","кто такая лорена","верховная жрица лорена штормград"}},{q="Что такое Молитва отчаяния в преданиях?",a="Молитва отчаяния — мгновенный призыв о божественной помощи, когда жрец близок к смерти или в смертельной опасности. Это отличительное воззвание, дарованное верным служителям Света, которым нужно немедленное исцеление.",al={"what is desperate prayer","desperate prayer ability lore","что такое молитва отчаяния","предания о способности молитва отчаяния"}},{q="Могут ли ночные эльфы обучать Свету?",a="Нет. Ночные эльфы почти исключительно почитают Элуну и направляют ее лунную силу. Они относятся ко Свету с дипломатическим уважением, но не проповедуют его и не обучают его особым молитвам, оставляя это жречеству людей и дворфов.",al={"do night elves know the light","elune vs holy light","знают ли ночные эльфы свет","элуна и свет"}},{q="Где найти верховную жрицу Лорену?",a="Верховная жрица Лорена живет на Соборной площади Штормграда и находится в Соборе Света среди собратьев-клириков и паладинов Серебряной Длани.",al={"laurena location","where is laurena","где лорена","где найти лорену"}}},fp="16,401,18.489.0,23.366.0,49.249.0,25.207.0,30.240.0,37.220.0,37.241.0,40.165.0"}
P.entries["quest:5643"] = {n="Страж Тьмы",s="Страж Тьмы — жреческое задание для троллей-жрецов племени Черного Копья, которые оказались далеко от дома в столице Отрекшихся, Подгороде. Эльталисте признает, что молодой тролль достаточно возмужал для священных обрядов своего племени, и отправляет его обратно в Оргриммар. В Аллее Духов его ждет наставник жрецов Ур'кьо, который введет его в важную ступень духовной защиты.",h="Страж Тьмы — жреческое задание для троллей-жрецов племени Черного Копья, которые оказались далеко от дома в...",kw={"aelthalyste","orgrimmar","rite of passage","shadowguard","troll priest","undercity","ur'kyo","valley of spirits","эльталисте","оргриммар","обряд перехода","страж тьмы","тролль-жрец","подгород","ур'кьо","аллея духов"},ang={["class:Priest"]="Этот обряд отмечает важную веху на пути жреца, отделяя общие основы магии Света и Тьмы от особых культурных традиций его народа.",["race:Troll"]="Для племени Черного Копья обучение жреческому делу неотделимо от общения с лоа и защиты племени — это наследие хранит Ур'кьо в Аллее Духов.",["race:Undead"]="Наставницы вроде Эльталисте признают особые традиции своих живых союзников и следят за тем, чтобы приезжие тролли получали обучение у собственных старейшин, а не учение Отрекшихся."},sec={{t="Призыв через континенты",b="Даже в мраке Подгорода узы веры и племенных традиций остаются крепкими. Наставница жрецов из числа Отрекшихся Эльталисте внимательно наблюдает за приезжими троллями-жрецами и замечает, когда посвященный достаточно окреп для испытаний своей культуры. Вместо того чтобы навязывать им мрачную философию Культа Забытой Тени, она направляет тролля обратно через Великое море, к древним обычаям его собственных старейшин."},{t="Аллея Духов",b="Прибыв в Дуротар, жрец отправляется в мистический уголок Оргриммара — Аллею Духов. Там Ур'кьо заботится о духовных нуждах и древних ритуалах племени Черного Копья. Он приветствует вернувшегося посвященного и готовит его к важному обряду перехода, который связывает узы жреца с лоа и практические заклинания, необходимые для защиты от вреда."}},faq={{q="Кто дает это задание?",a="Задание дает Эльталисте, наставница жрецов, живущая в Военном квартале Подгорода. Она замечает, когда тролль-жрец достиг зрелости, необходимой для духовных испытаний его племени.",al={"quest giver","where do i start","who gives shadowguard","кто выдает задание","где начать","кто дает страж тьмы"}},{q="Почему наставница из Подгорода отправляет меня в Оргриммар?",a="Жрецы Отрекшихся исповедуют Культ Забытой Тьмы, а тролли Черного Копья черпают духовную силу в лоа и племенных традициях. Эльталисте уважает это разделение и отправляет начинающих жрецов-троллей домой, чтобы они изучили свои особые расовые умения у собственного старейшины.",al={"why go to orgrimmar","undercity to orgrimmar","why ur'kyo","почему в оргриммар","из подгорода в оргриммар","почему ур'кьо"}},{q="Кто такой Ур'кьо?",a="Ур'кьо — известный наставник жрецов-троллей племени Черного Копья, живущий в Аллее Духов в Оргриммаре. Он является учителем и наставником в духовных обычаях и обрядах перехода троллей.",al={"ur'kyo lore","who is urkyo","priest trainer ur'kyo","ур'кьо предания","кто такой ур'кьо","наставник жрецов ур'кьо"}},{q="В чем значение умения «Страж Тьмы»?",a="Страж Тьмы — защитный оберег, свойственный только жрецам-троллям. Он призывает теневых духов и благословения лоа и проявляется в виде вращающихся теней, которые наносят ответный удар любому врагу, безрассудно напавшему на заклинателя.",al={"what is shadowguard","shadowguard spell lore","why is it important","что такое страж тьмы","предания о заклинании страж тьмы","почему это важно"}},{q="Получают ли это задание другие расы?",a="Этот призыв предназначен исключительно для троллей-жрецов племени Черного Копья, которые оказались в Подгороде примерно к двадцатому году жизненного опыта. У жрецов Отрекшихся есть собственные обряды и обучение в рамках Культа Забытой Тени.",al={"can undead do this","is this troll only","priest race quest","могут ли нежить","только для троллей","задание жрецов разных рас"}},{q="Где в Оргриммаре находится Ур'кьо?",a="Ур'кьо можно найти в Аллее Духов — южном районе Оргриммара, отведенном троллям Черного Копья и их мистическим практикам.",al={"where is ur'kyo","urkyo location","find ur'kyo","где ур'кьо","местонахождение ур'кьо","найти ур'кьо"}}},fp="11,383,27.423.0,21.376.0,22.200.0,51.276.0,14.192.0,52.211.0,34.241.0,37.145.0"}
P.entries["quest:5644"] = {n="Всепожирающая чума",s="«Всепожирающая чума» — задание-обряд посвящения для жрецов Отрекшихся, отправляющихся далеко от Лордерона. Наставник жрецов Отрекшихся Майлз Уэльш в Громовом Утесе направляет ученика обратно за моря, к Эльталисте в Подгороде, чтобы тот получил фирменное проявление магии Тьмы.",h="«Всепожирающая чума» — задание-обряд посвящения для жрецов Отрекшихся, отправляющихся далеко от Лордерона.",kw={"aelthalyste","devouring plague","forsaken","miles welsh","shadow priest","thunder bluff","undercity","war quarter","эльталисте","всепожирающая чума","отрекшиеся","майлз уэльш","жрец тьмы","громовой утес","подгород","военный квартал"},ang={["class:Priest"]="Это задание — важная веха в обучении жреца Отрекшихся: от базовых основ он переходит к грозным традициям Тьмы, свойственным нежити.",["faction:Horde"]="Задание показывает материально-технические и духовные связи, соединяющие далекие форпосты Орды в Мулгоре с темным сердцем Подгорода.",["race:Undead"]="В отличие от Света, которому они служили при жизни, жрецы Отрекшихся принимают суровые недуги и магию Тьмы, и Всепожирающая чума воплощает их особую культурную магию."},sec={{t="Призыв домой",b="Во время пребывания в Громовом Утесе жрецов Отрекшихся, овладевших божественными и теневыми дисциплинами, оценивает Майлз Уэльш, посланник Культа Забытой Тени среди тауренов. Признав, что аколит достаточно окреп, Майлз велит ему вернуться в Руины Лордерона, а не пытается сам передать эти высшие тайны в Калимдоре."},{t="Тайны Эльталисте",b="Под руинами города, в Военном квартале Подгорода, ждет Эльталисте — одна из ведущих наставниц жрецов Отрекшихся. Она следит за развитием аколитов, плетущих тени, и следит за тем, чтобы могучая, истощающая порча, известная как Всепожирающая чума, доверялась лишь тем, кто способен управлять ее оскверняющей силой и не поддаться ей."}},faq={{q="Кто отправляет вас на это задание?",a="Майлз Уэльш, наставник жрецов Отрекшихся из Прудов Видений под Вершиной Духов в Громовом Утесе, отправляет вас в это путешествие, когда ваши способности достаточно разовьются.",al={"who starts devouring plague quest","quest giver devouring plague","miles welsh role","кто дает задание всепожирающая чума","выдающий задание всепожирающая чума","роль майлза уэльша"}},{q="Где находится Эльталисте?",a="Эльталисте живет в Военном квартале Подгорода, среди тренировочных площадок и темных каналов, где собираются жрецы Отрекшихся.",al={"aelthalyste location","where is aelthalyste","devouring plague turn in","местонахождение эльталисте","где эльталисте","сдача задания всепожирающая чума"}},{q="Почему Майлз Уэльш не может сам обучить этому заклинанию?",a="Некоторые основополагающие тайны теневой веры Отрекшихся доверены лишь мастерам-наставникам вроде Эльталисте в сердце Подгорода. Уэльш чтит эту иерархию и отправляет достойных адептов домой на испытание.",al={"why travel to undercity","why see aelthalyste","undercity priest trainer","зачем ехать в подгород","зачем идти к эльталисте","наставник жрецов подгорода"}},{q="Что такое Всепожирающая чума с точки зрения преданий?",a="Это разрушительное проклятие, которое применяет Культ Забытой Тени: оно поражает жертву губительной магической заразой, поглощающей ее жизненные силы, чтобы исцелить заклинателя.",al={"what is devouring plague","lore of devouring plague","forsaken disease spell","что такое всепожирающая чума","предания о всепожирающей чуме","болезнь отрекшихся заклинание"}},{q="Доступно ли это задание другим расам?",a="Нет. Задание «Всепожирающая чума» связано исключительно с жречеством Отрекшихся и отражает особую философию и магические практики, рожденные выжившими нежитью Лордерона.",al={"can trolls do devouring plague quest","can orcs do devouring plague","is this quest undead only","могут ли тролли задание всепожирающая чума","могут ли орки","только для нежити"}},{q="Почему наставник Отрекшихся вообще находится в Громовом Утесе?",a="После принятия Отрекшихся в Орду столицы обменялись дипломатами и наставниками. Жрецы вроде Майлза Уэльша представляют духовные традиции Подгорода и помогают Отрекшимся, путешествующим по Калимдору.",al={"why are undead in thunder bluff","forsaken in thunder bluff lore","miles welsh thunder bluff","почему нежить в громовом утесе","отрекшиеся в громовом утесе предания","майлз уэльш громовой утес"}}},fp="16,291,14.384.0,26.361.0,28.184.0,29.139.0,46.211.0,49.177.0,39.171.0,62.235.0"}
P.entries["quest:5645"] = {n="Бесстрашие",s="«Бесстрашие» — вызов для жрецов-дворфов, возвращающий перспективных учеников в великие залы Стальгорна. Верховный жрец Рохан ждет в Мистическом квартале, чтобы проверить их дисциплину и передать учения, соответствующие их растущей стойкости.",h="«Бесстрашие» — вызов для жрецов-дворфов, возвращающий перспективных учеников в великие залы Стальгорна.",kw={"alathea","fear ward","hall of mysteries","ironforge","laurena","mystic ward","priest","rohan","алатея","защита от страха","зал тайн","стальгорн","лорена","мистический квартал","жрец","рохан"},ang={["class:Priest"]="Этот призыв отмечает ваше взросление в жречестве и дает право изучить особые священные приемы, отточенные стойким духовенством Стальгорна.",["faction:Alliance"]="Жречества Альянса поддерживают тесную связь между столицами, посылая аколитов через границы учиться у мастеров-духовников в Стальгорне.",["race:Dwarf"]="Возвращение к Рохану чтит особое сочетание непоколебимой веры, телесной стойкости и боевой доблести вашего народа на службе Свету."},sec={{t="Призыв в Стальгорн",b="Жрецов Альянса, служащих вдали от дома, местные наставники обычно направляют с докладом к высшему духовенству их ордена. Для учеников-дворфов этот путь ведет прямо к верховному жрецу Рохану в сердце Мистического квартала Стальгорна. Этот вызов отмечает перелом, когда простая духовная практика уступает место более глубокому, проверенному испытаниями применению священной магии."},{t="Испытания стойкости",b="Верховный жрец Рохан не просто обучает литургии: по традиции дворфов Свет — это щит и непреклонный оплот в телесной схватке. Явка на это испытание означает, что посвященный пережил крещение огнем в большом мире и обладает мужеством, нужным, чтобы одолеть сам страх на передовой."}},faq={{q="Какова цель этого задания?",a="Это официальный призыв от местных наставников жрецов к верховному жрецу Рохану в Стальгорне: он направляет опытных посвященных на углубленное обучение, чтобы они обрели особые духовные дары, которыми владеет жречество города.",al={"why do i have to go to rohan","what does a lack of fear do","priest quest level 20 ironforge","зачем идти к рохану","что дает бесстрашие","задание жреца 20 уровня стальгорн"}},{q="Кто такой верховный жрец Рохан?",a="Верховный жрец Рохан — старший предводитель жречества дворфов в Стальгорне. Он обучает учеников в Зале Тайн в Мистическом квартале, делая упор на стойкую преданность и боевую выносливость.",al={"who is rohan","high priest rohan lore","кто такой рохан","верховный жрец рохан предания"}},{q="Где найти верховного жреца Рохана?",a="Рохан находится в Зале Тайн, расположенном в Мистическом квартале в западной части Стальгорна.",al={"where is rohan","rohan location","how to find high priest rohan","где рохан","местонахождение рохана","как найти верховного жреца рохана"}},{q="Почему задание называется «Бесстрашие»?",a="Задание представляет подготовку жреца к получению Защиты от страха — особого защитного благословения, взращенного дворфами, преданными Свету, чтобы оберегать разум от паники и сверхъестественного ужаса.",al={"meaning of lack of fear","fear ward quest","смысл бесстрашия","задание защита от страха"}},{q="Кто отправляет жреца в Стальгорн?",a="Посвященных обычно направляют местные наставники, например верховная жрица Лорена в Штормграде или жрица Алатея в Дарнассе, которые велят ученикам почтить свое наследие или учиться под руководством Рохана.",al={"who starts a lack of fear","quest givers for lack of fear","кто дает бесстрашие","выдающие задание бесстрашие"}},{q="Есть ли в этом задании бой?",a="Нет. Для задания нужно отправиться в Стальгорн и поговорить с верховным жрецом Роханом, который обучает Защите от страха.",al={"do i have to fight","is there combat in a lack of fear","нужно ли сражаться","есть ли бой в бесстрашии"}}},fp="14,258,22.369.0,23.326.0,34.231.0,25.202.0,37.112.0,36.203.0,34.221.0,31.103.0"}
P.entries["quest:5646"] = {n="Всепожирающая чума",s="«Всепожирающая чума» — задание-посвящение для жрецов из числа Отрекшихся, отправившихся в Калимдор учиться у племени Черного Копья. Жрец-тролль, наставник Ур'кьо в Оргриммаре, направляет перспективных новичков из Отрекшихся обратно домой, в Подгород, где Эльталисте ждет, чтобы передать им более глубокие учения Культа Забытой Тени.",h="«Всепожирающая чума» — задание-посвящение для жрецов из числа Отрекшихся, отправившихся в Калимдор учиться у...",kw={"aelthalyste","devouring plague","forsaken priest","orgrimmar","shadow priest","undercity","ur'kyo","war quarter","эльталисте","всепожирающая чума","жрец отрекшихся","оргриммар","жрец тьмы","подгород","ур'кьо","военный квартал"},ang={["class:Priest"]="Жрецы Отрекшихся опираются на особые расовые учения о тени и распаде и учатся направлять свои телесные муки в разрушительные проклятия, такие как «Всепожирающая чума».",["faction:Horde"]="Совместные обязанности по обучению, которые делят Ур'кьо в Дуротаре и Эльталисте в Тирисфале, показывают практическое сотрудничество и взаимное уважение, связывающие далекие столицы Орды.",["race:Undead"]="Возвращение в Военный квартал Подгорода напоминает искателям приключений из Отрекшихся, что их истинная верность и духовные корни лежат под руинами Лордерона, как бы далеко ни уводили их обязанности перед Ордой."},sec={{t="Обмен верованиями",b="Орки и таурены мало склонны к жреческому служению, но тролли Черного Копья и Отрекшиеся связаны в Орде необычным богословским союзом. В Оргриммаре наставник жрецов, тролль Ур'кьо, ведет тех, кого влечет духовная сила. Однако он понимает, что новички из Отрекшихся должны в итоге овладеть зловещими искусствами, присущими их состоянию. В знак взаимного уважения между их народами Ур'кьо отправляет странствующих Отрекшихся обратно в Лордерон для завершения обучения."},{t="Военный квартал Подгорода",b="Под руинами Лордерона жрица Эльталисте заботится о пастве в Военном квартале Подгорода. Жрецы Отрекшихся идут одиноким, суровым путем, который определен Культом Забытой Тени: они смягчают болезненное прикосновение Света разрушительной порчей магии Тени. Когда новичок достигает достаточного мастерства, Эльталисте призывает его к себе, чтобы наделить недугом, известным их народу как «Всепожирающая чума»."}},faq={{q="Кто отправляет меня на это задание?",a="Ур'кьо, жрец-тролль и наставник, которого можно найти среди духов в Оргриммаре, предлагает это задание жрецам из числа Отрекшихся, достигшим двадцатого уровня силы.",al={"quest giver","who starts devouring plague","ur'kyo location","персонаж, выдающий задания","кто начинает всепожирающая чума","где находится ур'кьо"}},{q="Куда мне нужно отправиться?",a="Вы должны пересечь Великое море и добраться до Подгорода в Тирисфальских лесах. Найдите жрицу Эльталисте, которая руководит обучением жрецов Отрекшихся в Военном квартале.",al={"where do i turn this in","aelthalyste location","undercity priest trainer","где сдать задание","где находится эльталисте","учитель жрецов в подгороде"}},{q="Почему Ур'кьо отправляет Отрекшихся обратно в Лордерон?",a="Ур'кьо чтит договоренность с жрицей Эльталисте. Тролли-жрецы Тьмы понимают лоа и духов, но Отрекшиеся владеют темными искусствами, связанными именно с их нежитью природой, и им необходимо обучение непосредственно у их собственных предводителей.",al={"why go back to undercity","why does troll priest send me away","зачем возвращаться в подгород","почему жрец-тролль отсылает меня"}},{q="В чем значение «Всепожирающей чумы»?",a="«Всепожирающая чума» — мощный недуг, присущий только Отрекшимся, практикующим магию Тени. Он наносит целям разрушительную болезнь и одновременно перекачивает их жизненную силу прямо к заклинателю.",al={"what is devouring plague lore","forsaken priest plague","предания всепожирающая чума","чума жреца отрекшихся"}},{q="Могут ли другие расы Орды взять это задание?",a="Нет. Это задание предлагается исключительно жрецам из числа Отрекшихся и отражает их связь с особыми учениями Тени их родины.",al={"can trolls do this","is this quest undead only","могут ли тролли это сделать","задание только для нежити"}},{q="Как это вписывается в отношения жрецов Орды?",a="Орда опирается на взаимный обмен между знахарями и жрецами-колдунами Черного Копья в Калимдоре и жрецами Тьмы из числа Отрекшихся в Восточных королевствах: каждые направляют путников к наставникам, лучше всего подходящим их культуре.",al={"trolls and undead priests","horde priest lore","тролли и жрецы нежити","предания жрецов орды"}}},fp="16,324,20.493.0,28.433.0,27.158.0,22.168.0,48.239.0,49.194.0,40.136.0,46.220.0"}
P.entries["quest:5648"] = {n="Одеяния духовности",kw={"durotar","fortitude","garments of spirituality","grunt kor'ja","lesser heal","proudmoore","razor hill","tai'jin","дуротар","стойкость","одеяния духовности","грунт кор'джа","малое исцеление","праудмур","колючий холм","тай'джин"},ang={["class:Priest"]="Этот обряд посвящения — главное раннее испытание для жрецов Орды в Дуротаре: он подтверждает их навыки полевой помощи и приносит им первые облачения.",["faction:Horde"]="Выживание Грунта Кор'джи напрямую укрепляет оборону Колючего Холма от людей Кул Тираса, засевших поблизости.",["race:Troll"]="Наставничество Тай'джин соединяет древнюю духовность троллей с практическим долгом на поле боя и помогает юным троллям Черного Копья защищать союзников своей верой."},sec={{t="Испытание целителя",b="В засушливых зарослях к югу от Колючего Холма Орда ведет непрерывные стычки с остатками сил верховного адмирала Даэлина Праудмура. Вместо абстрактных обрядов наставница-троллиха Тай'джин проверяет выдержку будущих жрецов в настоящей боевой сортировке раненых. Новичкам поручено найти Грунта Кор'джу, воина, тяжело раненного при отражении нападения лазутчиков-людей, залечить ее раны и укрепить ее телосложение, пока она не погибла."},{t="Облачения верных",b="Возвращение Кор'джи боеспособности доказывает готовность юного жреца нести бремя духовной традиции Орды. В знак признательности за спасение защитницы передовой Тай'джин дарует «Одеяния духовности». Для союзников-орков и троллей Черного Копья эти одеяния означают, что их носитель — не просто ученик, изучающий заклинания, а надежная опора, способная сохранить жизнь воинам Орды в бою."}},faq={{q="Кто такая Грунт Кор'джа и почему ей нужно исцеление?",a="Грунт Кор'джа — воин Орды, несущий службу к югу от Колючего Холма. Она была ранена в стычке с уцелевшими солдатами экспедиции Кул Тираса адмирала Праудмура, которые все еще тревожат побережье Дуротара.",al={"grunt korja","who is korja","injured grunt south","грунт корджа","кто такая корджа","раненый грунт на юге"}},{q="Где найти Тай'джин?",a="Тай'джин находится в Колючем Холме в Дуротаре. Она служит духовной наставницей и учителем жрецов для молодых искателей приключений Орды, покидающих Долину Испытаний.",al={"taijin location","who gives garments of spirituality","priest trainer razor hill","где тай'джин","кто дает одеяния духовности","учитель жрецов колючий холм"}},{q="Какие способности нужны, чтобы исцелить Кор'джу?",a="Жрецы должны залечить раны Кор'джи с помощью «Малого исцеления» и укрепить ее выносливость благословением «Слова силы: Стойкость», а затем вернуться к Тай'джин.",al={"which spells to use","how to complete garments of spirituality","korja spells","какие заклинания использовать","как выполнить одеяния духовности","заклинания для кор'джи"}},{q="Почему солдаты Кул Тираса все еще сражаются в Дуротаре?",a="После вторжения и поражения верховного адмирала Праудмура остатки его флота рассеялись вдоль восточного побережья Дуротара. Они продолжают предпринимать отчаянные набеги и создавать опорные пункты, как крепость Тирагард.",al={"proudmoore troops durotar","why humans in razor hill","kul tiras remnants","войска праудмура в дуротаре","почему люди в колючем холме","остатки кул тираса"}},{q="В чем значение полученных одеяний?",a="Одеяния, которые вручает Тай'джин, знаменуют переход новичка в действующие целители Орды. Пройдя это практическое испытание, ученик получает право носить облачение своего призвания.",al={"garments reward lore","why give a robe","priest vestments razor hill","предания о награде одеяния","зачем дают одеяние","облачение жреца колючий холм"}},{q="Какое задание предшествует «Одеяниям духовности»?",a="Это испытание следует за заданием «В пользу духовности» — вводным заданием, которое предлагает Тай'джин, когда жрец получает достаточную начальную подготовку в Колючем Холме.",al={"prerequisite quest","before garments of spirituality","how to start garments","предыдущее задание","перед одеяниями духовности","как начать одеяния духовности"}}},fp="24,382,16.462.0,25.429.0,50.208.0,25.154.0,40.154.0,53.209.0,49.192.0,45.157.0"}
P.entries["quest:5649"] = {n="В пользу духовности",s="«В пользу духовности» — основополагающий обряд посвящения для юных жрецов Черного Копья, покидающих Долину Испытаний. Ощущая направление Кен'джая явиться к наставнице жрецов Тай'джин в Колючем Холме, новички делают первые настоящие шаги за пределы уединенного учебного логова к более широким испытаниям Дуротара. Путь показывает, как непросто Черному Копью сохранять равновесие между уважением к наследию троллей-предков и вхождением в недавно созданную Орду.",h="«В пользу духовности» — основополагающий обряд посвящения для юных жрецов Черного Копья, покидающих Долину...",kw={"darkspear","durotar","in favor of spirituality","ken'jai","priest","razor hill","tai'jin","valley of trials","черное копье","дуротар","в пользу духовности","кен'джай","жрец","колючий холм","тай'джин","долина испытаний"},ang={["class:Priest"]="Это задание знаменует ваш выход из каньона новичков, чтобы получить официальное обучение и облачение от Тай'джин в Колючем Холме.",["faction:Horde"]="Оно показывает, как разные культуры взаимодействуют в Дуротаре, соединяя дикие традиции Островов Эха с военным форпостом Колючий Холм.",["race:Troll"]="Это задание показывает напряжение, с которым Черное Копье сталкивается каждый день, балансируя между верностью Орде и сохранением древней племенной духовности."},sec={{t="Уход из Красного каньона",b="Освоив основные обряды под руководством Кен'джая в уединенной Долине Испытаний, аколиты Черного Копья готовы покинуть место обучения. Извилистые тропы в Дуротаре ведут прямо к поселению на перекрестке — Колючему Холму. Для юного жреца это путешествие — важная веха: от простых упражнений на выживание в пыли к духовной и культурной ответственности за племя."},{t="Старые веры и новые союзы",b="Кен'джай откровенен насчет положения Черного Копья в Орде Тралла. Хотя тролли высоко ценят верность орков и их уроки чести, не всякая традиция предков спокойно уживается под взглядами союзников. Духовные наставники Черного Копья учат своих учеников тихо хранить наследие, твердо держась своей самобытности и продолжая служить Орде. Тай'джин в Колючем Холме приобщает этих аколитов к этому более глубокому пониманию и направляет их к самостоятельности и силе общины."}},faq={{q="Кто дает задание «В пользу духовности»?",a="Задание дает Кен'джай, наставник жрецов из числа троллей, находящийся в Логове в Долине Испытаний.",al={"who starts in favor of spirituality","quest giver in favor of spirituality","kenjai priest quest","кто начинает в пользу духовности","кто выдает задание в пользу духовности","кен'джай задание жреца"}},{q="Где найти Тай'джин?",a="Тай'джин живет в казармах Колючего Холма, к востоку от центра поселения, вдоль главной дороги Дуротара.",al={"tai'jin location","where is tai jin","find tai'jin","где тай'джин","как найти тай'джин","тай'джин местонахождение"}},{q="Какие классы могут взять это задание?",a="Это задание предлагается исключительно жрецам-троллям, начинающим свой путь в Дуротаре.",al={"is this quest priest only","who can take in favor of spirituality","priest class quest razor hill","только ли для жрецов","кто может взять в пользу духовности","классовое задание жреца колючий холм"}},{q="Почему Кен'джай подчеркивает необходимость хранить некоторые традиции в тайне?",a="Кен'джай понимает, что орки — верные соратники, ценящие честь, но не всякий древний обряд или обычай троллей они встречают благосклонно. Он учит юных жрецов скромно чтить наследие предков, чтобы сохранять согласие в Орде.",al={"why secret troll traditions","orc troll friction religion","why practice in secret","почему тайные традиции троллей","трения орков и троллей религия","почему практиковать тайно"}},{q="Чему Тай'джин учит юного жреца по прибытии?",a="Тай'джин объясняет, что Черное Копье стало сильнее, приспособившись к жизни в Орде. Вместо того чтобы ждать и забирать силу у павших врагов, племя теперь готовится заранее и вступает в бой уже усиленным.",al={"taijin speech","what does tai jin say","darkspear adaptation","речь тай'джин","что говорит тай'джин","приспособление черного копья"}},{q="Какое задание следует сразу после «В пользу духовности»?",a="После сдачи этого задания Тай'джин предлагает «Одеяния духовности», которое отправляет аколита помочь раненому солдату Орды на местности.",al={"what comes after in favor of spirituality","in favor of spirituality follow up","next priest quest after taijin","что после в пользу духовности","продолжение в пользу духовности","следующее задание жреца после тай'джин"}}},fp="24,462,22.427.0,28.509.0,45.105.0,25.114.0,35.86.0,58.247.0,54.233.0,56.142.0"}
P.entries["quest:5650"] = {n="Одеяния Тьмы",s="«Одеяния Тьмы» — основополагающий обряд посвящения для начинающих священников Отрекшихся в Брилле. Темный священник Берил поручает неофитам исцелить и укрепить раненого Стража смерти, проверяя их владение магией поддержки, прежде чем они углубятся в Тень.",h="«Одеяния Тьмы» — основополагающий обряд посвящения для начинающих священников Отрекшихся в Брилле.",kw={"brill","dark cleric beryl","deathguard kel","fortitude","garments of darkness","lesser heal","priest","shadow","tirisfal glades","брилл","темный священник берил","страж смерти кел","стойкость","одеяния тьмы","малое исцеление","священник","тень","тирисфальские леса"},ang={["class:Priest"]="Этот обряд воплощает философию священничества Отрекшихся: баланс мрачной пользы Тени и незаменимого долга укреплять и исцелять союзников.",["race:Undead"]="Для Отрекшихся магия исцеления — практичное средство выживания, помогающее поддерживать бойцов передовой, таких как Страж смерти Кел, в схватках с гноллами и остатками Плети."},sec={{t="Равновесие Тьмы и Света",b="Хотя священничество Отрекшихся черпает известность и особую самобытность в тени и тьме, его старейшины признают неизменную практическую необходимость исцеления. Темный священник Берил учит, что понимание тьмы требует понимания света и восстанавливающих искусств. Священнику, ищущему лишь разрушения, советуют вместо этого изучать тайную магию: истинное призвание священничества — укреплять и беречь соратников не меньше, чем поражать врагов."},{t="Долг на кладбище",b="Чтобы доказать мастерство, неофита отправляют к северу от кладбища Брилла на помощь Стражу смерти Келу. Кел охраняет местность от рыскающих стай гноллов и получил ранения, удерживая рубеж. Врачуя его раны исцеляющими заклинаниями и укрепляя его выносливость защитными чарами, послушник доказывает, что способен поддерживать защитников Тирисфальских лесов, и получает облачение Берил и допуск к высшим таинствам священничества."}},faq={{q="Почему священники Отрекшихся используют магию исцеления, если их сила исходит из тьмы?",a="Темный священник Берил объясняет, что хотя священники Отрекшихся черпают исключительную силу в Тени, исцеление остается необходимым. Прежде чем овладеть тьмой, послушник должен постичь магию поддержки и восстановления, чтобы защитники Отрекшихся оставались на ногах на поле боя.",al={"why do undead heal","forsaken priest healing lore","shadow vs light undead","почему нежить лечит","исцеление священников отрекшихся","тень и свет нежить"}},{q="Кто такой Страж смерти Кел?",a="Страж смерти Кел — часовой Отрекшихся, расположившийся к северу от кладбища в Брилле. Он защищает местные поселения от агрессивных стай гноллов, бродящих по лесам, и нуждается в помощи, когда получает ранения при исполнении долга.",al={"deathguard kel lore","who is deathguard kel","wounded deathguard","страж смерти кел","кто такой страж смерти кел","раненый страж смерти"}},{q="Кто выдает это задание?",a="Темный священник Берил, наставник священников в Брилле, в Тирисфальских лесах, предлагает это задание после того, как вы выполните предварительное — «Во славу Тьмы».",al={"who starts garments of darkness","garments of darkness quest giver","кто начинает одеяния тьмы","одеяния тьмы кто выдает задание"}},{q="Какое облачение вручают по завершении испытания?",a="Берил вручает сшитую на заказ мантию как знак положения и достижения: она означает, что священник освоил основные обязанности и признан собратьями.",al={"what robe do you get","garments reward priest","какую мантию дают","одеяния награда священник"}},{q="С какими угрозами сражался Страж смерти Кел?",a="Кел был ранен в бою с местными гноллами, которые населяют дикие земли Тирисфальских лесов к северу от кладбища Брилла.",al={"what attacked kel","kel gnolls","кто напал на кела","кел гноллы"}},{q="На какие темные силы намекает темный священник Берил?",a="Берил намекает на приемы Тени, свойственные только священникам Отрекшихся, — особые проявления магии Тьмы и ментального недуга, неизвестные священникам других рас.",al={"forsaken priest unique spells","darker powers hint","уникальные заклинания священников отрекшихся","намек на темные силы"}}},fp="20,264,27.460.0,23.433.0,77.263.0,22.212.0,21.158.0,52.170.0,41.134.0,50.174.0"}
P.entries["quest:5651"] = {n="Во славу Тьмы",s="«Во славу Тьмы» знаменует переход священника Отрекшихся от начальных склепов Могильника к углубленному обучению в Брилле. По поручению темного священника Дьюстена юный ученик отправляется учиться у темного священника Берил, чтобы постичь тонкий баланс между Светом и Тенью.",h="«Во славу Тьмы» знаменует переход священника Отрекшихся от начальных склепов Могильника к углубленному...",kw={"beryl","brill","deathknell","duesten","light","priest","shadow","tirisfal","берил","брилл","могильник","дьюстен","свет","священник","тень","тирисфаль"},ang={["class:Priest"]="Это задание воплощает основную философию священничества Отрекшихся: владеть и Светом, и Тенью с холодной рассудительностью, а не с религиозным трепетом.",["race:Undead"]="Путь из Могильника в Брилл — обычная первая вылазка в более широкий мир Отрекшихся, показывающая неофитам, как их народ отстраивается среди руин Лордерона."},sec={{t="Путь, проложенный в гнили",b="Хотя священники других рас чтят Свет как незапятнанный источник нравственной добродетели, Отрекшиеся подходят к вере сквозь суровую призму собственной нежизни. Как учит темный священник Дьюстен, Отрекшиеся были выкованы в скверне и брошены, как падаль. Их выживание требует понимать и Свет, и Тень без сентиментальности. «Во славу Тьмы» направляет новых учеников из замкнутого кладбища Могильника навстречу более широкой действительности, ждущей их в Тирисфальских лесах."},{t="Обучение в Брилле",b="Дорога на северо-восток от Могильника приводит юного священника через деревянный крытый мост в разрушенную деревушку Брилл. Там, в верхних покоях местного трактира, темный священник Берил ждет, чтобы испытать решимость неофита. Берил ценит честолюбие и холодную практичность выше слепой преданности и требует, чтобы священник Отрекшихся применял божественную силу как оружие и инструмент, а не как моральную опору."}},faq={{q="Для чего нужно это задание?",a="Это обряд посвящения для священников Отрекшихся, покидающих Могильник. Темный священник Дьюстен посылает вас к темному священнику Берил в Брилл, чтобы продолжить обучение и получить следующее испытание.",al={"what does this quest do","why in favor of darkness","in favor of darkness purpose","что дает это задание","зачем во славу тьмы","во славу тьмы назначение"}},{q="Почему священники Отрекшихся используют Свет, если принимают тьму?",a="Клирики Отрекшихся признают, что мир держится на равновесии Света и Тени. Хотя Свет причиняет нестерпимую боль плоти нежити, а их истоки лежат в гнили и тьме, они изучают обе силы из практичности и необходимости.",al={"why do undead priests use light","forsaken priest lore","light and shadow undead","почему нежить использует свет","священники отрекшихся предания","свет и тень нежить"}},{q="Где найти темного священника Берил?",a="Темный священник Берил находится в городке Брилл, к северо-востоку от Могильника. Он живет на втором этаже таверны «Петля висельника» в восточной части поселения.",al={"where is dark cleric beryl","beryl location","find beryl","где темный священник берил","берил местонахождение","найти берил"}},{q="Что следует за этим заданием?",a="Разговор с темным священником Берил завершает это задание и открывает следующее — «Одеяния Тьмы», в котором он проверяет, как вы умеете лечить и поддерживать союзников с помощью новообретенных умений.",al={"what comes next","next quest after in favor of darkness","in favor of darkness followup","что дальше","следующее задание после во славу тьмы","во славу тьмы продолжение"}},{q="Кто такой темный священник Дьюстен?",a="Темный священник Дьюстен — наставник священников в Могильнике. Он помогает только что пробудившимся священникам Отрекшихся осознать свое мучительное существование и овладеть духовными силами.",al={"who gives this quest","duesten lore","dark cleric duesten","кто выдает это задание","дьюстен предания","темный священник дьюстен"}},{q="Почему Берил ставит честолюбие выше веры?",a="Священники Отрекшихся считают традиционную набожную веру недостаточной после того, как их покинули силы, которым они поклонялись при жизни. Темный священник Берил ждет, что ученики будут полагаться на личное честолюбие, настойчивость и практическую силу, чтобы выжить.",al={"beryl dialogue meaning","why ambition not faith","forsaken faith","смысл слов берил","почему честолюбие а не вера","вера отрекшихся"}}},fp="20,304,20.495.0,20.409.0,34.199.0,63.260.0,34.172.0,31.192.0,27.187.0,43.232.0"}
P.entries["quest:5654"] = {n="Обессиливающий сглаз",s="«Обессиливающий сглаз» — раннее задание-обряд для юных жрецов-троллей племени Черного Копья, уже проявивших себя в Колючем Холме. Тай'джин посылает неофита на север, в Оргриммар, к Ур'кьо, чтобы тот был принят в духовный круг племени и обучен темным искусствам лоа.",h="«Обессиливающий сглаз» — раннее задание-обряд для юных жрецов-троллей племени Черного Копья, уже проявивших...",kw={"darkspear","durotar","hex of weakness","loa","orgrimmar","sen'jin village","tai'jin","ur'kyo","valley of spirits","черное копье","дуротар","обессиливающий сглаз","лоа","оргриммар","деревня сен'джин","тай'джин","ур'кьо","аллея духов"},ang={["class:Priest"]="В отличие от догматов Света или Забытой Тени, жречество троллей опирается на глубокое единение с первобытными духами, сочетая племенные сглазы с привычными заклинаниями Тени и исцеления.",["faction:Horde"]="Путь из Колючего Холма в Аллею Духов отражает включение культуры троллей в укрепленные стены растущей столицы Тралла.",["race:Troll"]="Этот обряд отмечает ваш переход от новичка в Колючем Холме к признанному жрецу племени Черного Копья, изучающему древние проклятия, передаваемые из поколения в поколение."},sec={{t="Призыв в круг",b="Начинающий жрец-тролль в Дуротаре продолжает обучение в казармах Колючего Холма под присмотром Тай'джин. Когда послушник достаточно овладевает базовым равновесием духовного единения и магии Тени, начальное наставничество заканчивается. Тай'джин направляет многообещающего священника прочь от Колючего Холма на север, через каньоны красной земли, к столице Орды, где старейшие мастера руководят более широкими магическими традициями племени."},{t="Старые обычаи в Аллее Духов",b="В Оргриммаре племя Черного Копья хранит собственное культурное убежище в Аллее Духов, отделенное от лязгающих кузниц и воинских площадок орков. Здесь, среди высоких тотемов и тенистых хижин, старейшина-жрец Ур'кьо ждет новых посвященных. Войти в его круг — значит принять древние обычаи троллей джунглей: сочетать почтение к лоа предков с мощными проклятиями и сглазами, лишающими противника сил в бою."}},faq={{q="Для чего нужно это задание?",a="Задание отражает официальное продвижение неофита в жречестве племени Черного Копья. Тай'джин посылает развивающихся жрецов-троллей с побережья Дуротара к Ур'кьо в Оргриммар, торжественно принимая их во внутренний круг духовных мастеров племени.",al={"why do this quest","hex of weakness purpose","what does hex of weakness quest do","зачем это задание","обессиливающий сглаз назначение","что дает задание обессиливающий сглаз"}},{q="Кто такая Тай'джин?",a="Тай'джин — наставница жрецов-троллей в казармах Колючего Холма в Дуротаре. Она ведет юнейших заклинателей племени Черного Копья через ранние испытания, прежде чем отправить их в столицу.",al={"who is quest giver","tai'jin lore","taijin","кто выдает задание","тай'джин предания","тайджин"}},{q="Кто такой Ур'кьо?",a="Ур'кьо — старейший наставник жрецов-троллей, живущий в Аллее Духов в Оргриммаре. Он руководит продвинутым духовным обучением, передавая жрецам племени Черного Копья племенные сглазы и глубокие обряды предков.",al={"who is ur'kyo","urkyo priest trainer","ur-kyo","кто такой ур'кьо","ур'кьо наставник жрецов","уркьо"}},{q="Где находится Аллея Духов?",a="Аллея Духов — уединенный болотистый район в западной части Оргриммара. Это главный дом троллей племени Черного Копья в орочьем городе-крепости: здесь находятся их наставники, жилища и тотемы.",al={"valley of spirits location","where is ur'kyo","where to find ur'kyo","аллея духов расположение","где ур'кьо","где найти ур'кьо"}},{q="На какой магии сосредоточено это обучение?",a="Жрецы племени Черного Копья призывают «старые обычаи», черпая силу у лоа и в древних традициях троллей джунглей. Не полагаясь только на Свет, которому следуют люди или дворфы, жрецы-тролли сочетают исцеляющую магию духов с ослабляющими проклятиями, такими как «Обессиливающий сглаз».",al={"troll priest magic","what are the old ways","hex lore","магия жрецов троллей","что такое старые обычаи","предания о сглазе"}},{q="Могут ли выполнить это задание не тролли?",a="Нет. Это задание связано с культурными традициями и особыми заклинаниями троллей племени Черного Копья. Жрецов из числа нежити направляют к их собственным наставникам и теневым учениям в Тирисфале и Подгороде.",al={"can undead do this","is this troll only","может ли нежить выполнить","только для троллей"}}},fp="15,304,23.451.0,37.478.0,34.252.0,15.202.0,14.205.0,31.208.0,47.277.0,36.213.0"}
P.entries["quest:567"] = {n="Вооружены и очень опасны!",s="Это объявление о розыске, вывешенное в Мельнице Таррен, обрекает на казнь четырех видных людей Хилсбрада. Верховный палач Дарталия объявила их опасными врагами Отрекшихся из-за конкретных убийств и засад на обозы.",h="Это объявление о розыске, вывешенное в Мельнице Таррен, обрекает на казнь четырех видных людей Хилсбрада.",kw={"apothecary eli","citizen wilkes","clerk horrace whitesteed","dangerous","deathguard toma","deathstalker fry","farmer kalaba","high executor darthalia","hillsbrad","miner hackett","tarren mill","undercity","аптекарь эли","горожанин уилкс","клерк гораций белоконь","вооружены и очень опасны","страж смерти тома","страж смерти фрай","фермер калаба","верховный палач дарталия","хилсбрад","шахтер хакетт","мельница таррен","подгород"},ang={["class:Rogue"]="Выслеживание скрывшихся вожаков на вражеской земле напоминает скрытное ремесло Стража смерти Фрая, чью гибель мстит это поручение.",["faction:Horde"]="Чтобы удержать Предгорья Хилсбрада, нужно сломить самых яростных вожаков человеческого ополчения и обеспечить безопасность передвижений Орды по региону.",["race:Undead"]="Мстить за павших Стражей смерти, аптекарей и Стражей смерти — повод для мрачной гордости любого верного слуги Темной Госпожи."},sec={{t="Дело возмездия",b="Линия фронта в Предгорьях Хилсбрада жестока и лична. Для верховного палача Дарталии и гарнизона Отрекшихся в Мельнице Таррен обычные жители Хилсбрада стали смертоносными бойцами. В объявлении названы четверо, чье сопротивление стоило жизни Отрекшимся и ценных грузов из Подгорода."},{t="Цели Мельницы Таррен",b="В объявлении названы: клерк Гораций Белоконь — за убийство Стража смерти Томы, горожанин Уилкс — за убийство аптекаря Эли, шахтер Хакетт — за убийство Стража смерти Фрая и фермер Калаба — за срыв обозов с припасами из Подгорода. Каждая цель действует в своем очаге сопротивления Хилсбрада и остается неуловимой в хаосе большого конфликта."}},faq={{q="Кто вывесил объявление «Вооружены и очень опасны!»?",a="Верховный палач Дарталия, командующая силами Отрекшихся в Мельнице Таррен, назначила награду за голову четырех видных людей Хилсбрада.",al={"who posted dangerous","who gave dangerous quest","darthalia bounty","кто вывесил объявление","кто выдал задание вооружены и очень опасны","награда дарталии"}},{q="Почему разыскивают именно этих людей?",a="Каждый из них нанес удар по Отрекшимся: клерк Гораций Белоконь убил Стража смерти Тому, горожанин Уилкс убил аптекаря Эли, шахтер Хакетт сразил Стража смерти Фрая, а фермер Калаба подстерег важные припасы, посланные из Подгорода.",al={"why are they dangerous","what did they do","hillsbrad targets crime","почему они опасны","что они сделали","цели хилсбрада преступления"}},{q="Где находятся цели?",a="Все четверо укрылись в поселениях и рабочих местах людей в Предгорьях Хилсбрада, прячась среди горожан, на фермах и в шахтах.",al={"where to find targets","dangerous quest locations","hackett location","где найти цели","места задания вооружены и очень опасны","где хакетт"}},{q="Какова стратегическая цель этого поручения?",a="Помимо простой мести, устранение этих вожаков подрывает местное сопротивление людей и защищает патрули и линии снабжения Отрекшихся между Мельницей Таррен и Подгородом.",al={"why kill them","hillsbrad bounty goal","tarren mill strategy","зачем их убивать","цель награды хилсбрада","стратегия мельницы таррен"}},{q="Связано ли это с Битвой за Хилсбрад?",a="Да. Цели этого задания живут на тех самых фермах, в шахтах и центрах городов, которые силы Отрекшихся штурмуют во время наступления в рамках Битвы за Хилсбрад.",al={"battle of hillsbrad connection","darthalia battle","hillsbrad offensive","связь с битвой за хилсбрад","дарталия битва","наступление на хилсбрад"}},{q="Кому сдают задание после их гибели?",a="Доказательства их устранения передают прямо верховному палачу Дарталии в Мельнице Таррен.",al={"who completes dangerous","dangerous turn in","darthalia turn in","кто завершает вооружены и очень опасны","сдача задания","дарталия сдать"}}},fp="10,235,23.338.0,22.381.0,33.142.0,37.241.0,30.144.0,47.175.0,45.160.0,44.91.0"}
P.entries["quest:5672"] = {n="Благодать Элуны",s="Благодать Элуны — обряд признания, который предлагают преданным жрецам из числа ночных эльфов в Дарнассе. Когда жрецы доказывают свою веру и дисциплину в первых странствиях, их призывают к жрице Алатее, чтобы они получили более глубокие наставления в божественных тайнах Богини Луны.",h="Благодать Элуны — обряд признания, который предлагают преданным жрецам из числа ночных эльфов в Дарнассе.",kw={"alathea","darnassus","elune","elune's grace","priest quest","priestess alathea","sisterhood of elune","temple of the moon","алатея","дарнасс","элуна","благодать элуны","задание жреца","жрица алатея","сестринство элуны","храм луны"},ang={["class:Priest"]="Этот обряд знаменует разделение между верой кальдораев и учениями людского и дворфийского духовенства, основанными на Свете, и прочно связывает ремесло жреца с защитой Элуны.",["race:NightElf"]="Для кальдораев Благодать Элуны — непрерывная связь с древними традициями, сохраненными в Сестринстве Элуны."},sec={{t="Священное призвание",b="В Храме Луны в Дарнассе Сестринство Элуны ведет молодых послушниц и послушников от первых молитв к владению лунной магией. Ночные эльфы смотрят на Свет не так, как люди или дворфы: их вера неразрывно связана с Матерью Луной, Элуной. Когда начинающий жрец достигает важного рубежа в своей преданности, старшие наставники замечают это и признают ученика готовым принять большую божественную силу."},{t="Благословения Богини Луны",b="Жрица Алатея передает этот призыв от имени Сестринства. Она признает, что преданность послушника возвысила его над обычной паствой и открыла ему доступ к традициям, сохраненным на протяжении тысячелетий. Принятие обряда скрепляет связь жреца с Элуной и открывает особые защитные покровы и лунные воззвания, свойственные вере кальдораев."}},faq={{q="Для чего нужно это задание?",a="Задание отмечает духовный рубеж для жрецов из числа ночных эльфов. Оно призывает послушника обратно в Дарнасс, чтобы жрица Алатея признала его рост и посвятила в высшие расовые учения Сестринства Элуны.",al={"why do elunes grace","what does elunes grace do","purpose of quest","зачем благодать элуны","что делает благодать элуны","цель задания"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — уважаемая наставница Сестринства Элуны, живущая в Дарнассе. Она присматривает за растущими жрецами-кальдораями и помогает им углублять единение с Богиней Луны.",al={"alathea role","who gives quest","who is alathea","роль алатеи","кто выдает задание","кто такая алатея"}},{q="Почему этот дар доступен только ночным эльфам?",a="В отличие от жрецов-людей и дворфов, черпающих силу из Света, жрецы-ночные эльфы напрямую почитают Элуну. Воззвания сестринства, такие как Благодать Элуны, отражают лунную защиту и оборонительные чары, которые кальдораи развивали тысячи лет.",al={"why only night elves","racial ability lore","elune priest difference","почему только ночные эльфы","расовая способность предания","отличие жрецов элуны"}},{q="Где проходит эта церемония?",a="На призыв отвечают в Дарнассе, в Храме Луны, где собирается и обучает жречество города.",al={"where is alathea","quest location","darnassus temple","где алатея","место задания","храм дарнасса"}},{q="Получают ли другие жрецы Альянса подобное призвание?",a="Да. Каждая культура подходит к жречеству по-своему: люди и дворфы изучают принципы Света у своих наставников в Штормграде и Стальгорне и получают расовые умения, отличные от лунной магии ночных эльфов.",al={"do humans get this","dwarf priest equivalent","other races","получают ли люди","жрец дворф аналог","другие расы"}},{q="О каком состоянии преданности говорит Алатея?",a="Алатея говорит о духовной стойкости и зрелости, обретенных в испытаниях большого мира. Выживание, дисциплина и неизменная верность добродетелям Элуны доказывают, что послушник может безопасно направлять более могущественные лунные благословения.",al={"attained a state","alathea dialogue","what devotion","достиг состояния","диалог алатеи","какая преданность"}}},fp="13,277,16.450.0,29.361.0,34.238.0,25.192.0,41.267.0,36.125.0,52.248.0,47.231.0"}
P.entries["quest:5674"] = {n="Благодать Элуны",s="Благодать Элуны — обряд посвящения для растущих жрецов из числа ночных эльфов, знак их готовности владеть божественными дарами, присущими их народу. Из отдаленных поселений вроде Доланаара кандидатов направляют в священный Храм Луны в Дарнассе, где они предстают перед жрицей Алатеей и доказывают свою преданность.",h="Благодать Элуны — обряд посвящения для растущих жрецов из числа ночных эльфов, знак их готовности владеть...",kw={"darnassus","dolanaar","elune's grace","laurna morninglight","priestess alathea","sisterhood of elune","teldrassil","temple of the moon","дарнасс","доланаар","благодать элуны","лорна утренний свет","жрица алатея","сестринство элуны","тельдрассил","храм луны"},ang={["class:Priest"]="Этот обряд знаменует важный переход для жрецов-ночных эльфов: их сущность опирается на особую небесную магию Сестринства Элуны, а не на общие священные практики.",["race:NightElf"]="Паломничество в Храм Луны подтверждает центральную роль поклонения Элуне в обществе кальдораев и призывает далеких послушников домой, в сердце Дарнасса."},sec={{t="Священный рубеж",b="Путь жреца в Сестринстве Элуны не сводится к освоению обычных молитв исцеления и кары. По мере роста опыта послушники достигают порога, за которым их признают готовыми принять благословения, доступные только кальдораям. Местные наставницы, такие как Лорна Утренний Свет в Доланааре, не вправе передавать эти глубокие умения и отправляют многообещающих учеников обратно в культурное и духовное сердце ордена."},{t="Прием в храме",b="Задание направляет посвящаемых через Тельдрассил в величественный Храм Луны в Дарнассе. Там, под взором верховного жречества, жрица Алатея оценивает, действительно ли проситель готов принять защитный покров богини. Изучение Благодати Элуны символизирует истинную зрелость в жречестве и соединяет нераскрытый потенциал с официальным служением богине."}},faq={{q="Для чего нужно это задание?",a="Это задание отправляет обратно в Дарнасс жрецов-ночных эльфов, набравшихся достаточного практического опыта. Оно служит обрядом перехода: жрецов направляют к жрице Алатее в Храм Луны, чтобы испытать их и обучить защитному искусству, известному как Благодать Элуны.",al={"what does this quest do","elunes grace quest purpose","why visit alathea","что делает это задание","цель задания благодать элуны","зачем идти к алатее"}},{q="Кто такая жрица Алатея?",a="Жрица Алатея — высокопоставленная наставница жрецов, живущая в Храме Луны в Дарнассе. Она руководит официальным обучением и продвижением послушников-ночных эльфов и следит, чтобы у них была духовная сосредоточенность, необходимая для сложных расовых молитв.",al={"priestess alathea lore","who is alathea","alathea darnassus","предания о жрице алатее","кто такая алатея","алатея дарнасс"}},{q="Почему местные наставники не могут обучить этому умению?",a="Наставницы в отдаленных поселениях, как Лорна Утренний Свет, обучают новичков основам, но священные благословения, присущие только кальдораям, сестринство доверяет лишь при официальном посвящении. Чтобы пройти проверку и получить эти глубокие дары, послушники должны явиться в главное святилище ордена в Дарнассе.",al={"why not train in dolanaar","why go to darnassus","почему не учиться в доланааре","зачем идти в дарнасс","почему не в доланааре","почему в дарнасс"}},{q="Что на самом деле означает Благодать Элуны в вере кальдораев?",a="Благодать Элуны — прямая защитная опека Богини Луны. Сотканная молитвой, она ослабляет силу входящих ударов и отражает оберегающее присутствие Элуны над ее верными защитниками, когда рядом опасность.",al={"what is elunes grace","elunes grace lore","что такое благодать элуны","предания благодать элуны"}},{q="Могут ли жрецы других рас получить это благословение?",a="Нет. Искусство Благодати Элуны строго связано с древней верой и поклонением кальдораев. Ему обучают только жрецов-ночных эльфов, напрямую общающихся с Богиней Луны.",al={"can humans learn elunes grace","is elunes grace night elf only","могут ли люди выучить благодать элуны","только ли для ночных эльфов"}},{q="Где начинается и заканчивается этот путь?",a="Призыв передает наставница Лорна Утренний Свет в поселении Доланаар на Тельдрассиле, отправляя послушника на запад, в Храм Луны в Дарнассе.",al={"quest start and end","where to go","начало и конец задания","куда идти"}}},fp="13,317,18.457.0,22.402.0,34.257.0,25.261.0,43.317.0,61.239.0,49.197.0,38.172.0"}
P.entries["quest:5676"] = {n="Волшебное искажение",s="Волшебное искажение — обряд посвящения для жрецов Альянса в Штормграде, который проводит верховная жрица Лорена в Соборе Света. Достигнув более глубокого единения с верой, жрец обучается защитным покровам против враждебных владеющих тайной магией. Это практическая защита Церкви от необузданного колдовства и мятежных заклинателей.",h="Волшебное искажение — обряд посвящения для жрецов Альянса в Штормграде, который проводит верховная жрица...",kw={"anti-magic","arcane feedback","cathedral of light","high priestess laurena","holy light","human priest","laurena","priest","stormwind","антимагия","волшебное искажение","собор света","верховная жрица лорена","свет","жрец-человек","лорена","жрец","штормград"},ang={["class:Priest"]="Этот обряд расширяет тактический арсенал жреца и дает средства подавлять противников, использующих ману, когда божественная дипломатия бессильна.",["faction:Alliance"]="По мере роста напряженности с мятежными кабалами и темными практиками на Восточных королевствах Альянс полагается на своих жрецов в нейтрализации магических угроз.",["race:Human"]="Жрецы-люди в Штормграде проходят особую доктринальную подготовку Собора Света, сочетающую праведную преданность со строгой дисциплиной в борьбе с магией."},sec={{t="Щит против тайной магии",b="В залитых солнцем кельях Собора Света верховная жрица Лорена напоминает послушникам об извечной опасности — тайной магии. Свет приносит исцеление, тепло и божественный порядок, а необузданные магические силы переменчивы и нередко влекут порчу или катастрофу. Чтобы выстоять против чернокнижников, мятежных чародеев и магических тварей, преданных жрецов учат, что вера порой должна становиться действенным оберегом от окружающих заклинаний."},{t="Обратить поток вспять",b="Волшебное искажение учит разум и дух наказывать враждебных заклинателей за направление силы против верных. Эта дисциплина не просто отражает магические залпы, а возвращает тайную энергию к источнику, сжигая запасы маны заклинателя и причиняя мучения. Лорена передает это заклинание жрецам-людям, выходящим в большой мир, чтобы посланники Собора никогда не странствовали беззащитными перед колдовством."}},faq={{q="Для чего нужно задание «Волшебное искажение»?",a="Задание отражает растущее мастерство жреца-человека под руководством Церкви Священного Света. Верховная жрица Лорена обучает его особому защитному обряду, позволяющему противостоять враждебным заклинателям и отвечать им ударом.",al={"arcane feedback quest","what is arcane feedback","why do this quest","задание волшебное искажение","что такое волшебное искажение","зачем выполнять задание"}},{q="Кто дает это задание и где ее найти?",a="Задание дает верховная жрица Лорена. Она находится в Соборе Света — великом духовном центре Альянса на Соборной площади Штормграда.",al={"who gives arcane feedback","arcane feedback quest giver","where is laurena","кто дает волшебное искажение","выдающий задание волшебное искажение","где лорена"}},{q="Почему Церковь Священного Света считает тайную магию врагом?",a="Церковь учит полагаться на нравственную ясность, преданность и божественную благодать. Тайная магия, напротив, черпает из переменчивых, затягивающих сил, которые исторически привлекали вторжения демонов и приносили разруху по всему Азероту, поэтому жрецы-люди видят в неукрощенном колдовстве постоянную угрозу.",al={"why do priests hate arcane","church vs arcane","is arcane bad","почему жрецы ненавидят тайную магию","церковь против тайной магии","плоха ли тайная магия"}},{q="Как в общих чертах действует защита «Волшебное искажение»?",a="Заклинание создает вокруг жреца ответную ауру. Когда враждебное заклинание попадает в покров, входящая магия вызывает отдачу, которая истощает запасы маны нападающего и наносит ему физический шок.",al={"how does arcane feedback work","arcane feedback lore","как работает волшебное искажение","предания волшебное искажение"}},{q="Может ли любой жрец научиться этому у Лорены?",a="В Штормграде эта дисциплина рассчитана на жрецов-людей как часть их церковных традиций и отражает боевые учения, которые преподают в Соборе Света.",al={"can dwarves learn arcane feedback","who can get arcane feedback","priest racial spell","могут ли дворфы выучить волшебное искажение","кто может получить волшебное искажение","расовое заклинание жреца"}},{q="Какого уровня ожидают от послушника, проходящего это обучение?",a="Жрецов призывают освоить эту технику примерно на двадцатом круге опыта — в пору, когда послушники оставляют обычные церковные обязанности и отправляются в опасные пограничные земли.",al={"what level for arcane feedback","arcane feedback level requirement","какой уровень для волшебного искажения","требования к уровню волшебное искажение"}}},fp="15,357,27.450.0,23.448.0,49.239.0,49.175.0,68.296.0,52.222.0,39.202.0,63.185.0"}
P.entries["quest:5677"] = {n="Волшебное искажение",s="«Волшебное искажение» — задание жрецов, которое выдает верховный жрец Рохан в Стальгорне жрецам-людям, посетившим Каз Модан. Рохан направляет начинающего жреца домой, в Собор Света в Штормграде, чтобы тот получил наставления, подходящие именно традициям людей. Это важный этап развития, когда молодые ученики начинают осваивать расовые проявления своей веры.",h="«Волшебное искажение» — задание жрецов, которое выдает верховный жрец Рохан в Стальгорне жрецам-людям...",kw={"arcane feedback","cathedral of light","high priest rohan","high priestess laurena","ironforge","mystic ward","priest quest","stormwind","волшебное искажение","собор света","верховный жрец рохан","верховная жрица лорена","стальгорн","мистический квартал","задание жреца","штормград"},ang={["class:Priest"]="Это задание — важная веха: жрецы узнают, что разные расы направляют и выражают Свет через особые культурные традиции.",["race:Dwarf"]="Наставники-дворфы, такие как верховный жрец Рохан, чтят союз с людьми, но хранят особые обряды Каз Модана внутри собственного народа.",["race:Human"]="Жрецов-людей мягко отзывают из дворфийских святилищ обратно в Штормград, чтобы они укрепились в священных путях Собора Света."},sec={{t="Мягкое напоминание",b="Когда жрец-человек ищет высшего духовного наставничества в залах Мистического квартала, верховный жрец Рохан встречает его с почтением, но обозначает границу. Хотя жрецы-дворфы и жрецы-люди одинаково преданы Свету, каждая цивилизация развивает собственные обряды, дисциплины и защитные молитвы. Вместо того чтобы раскрывать тайны Стальгорна, Рохан отправляет людей-священников к культурным корням в Элвиннский лес, чтобы они освоили наследие своего народа."},{t="Возвращение в Собор",b="По возвращении в Штормград послушник докладывает верховной жрице Лорене в величественном Соборе Света. Лорена рада, что наставления Рохана достигли путника, и приветствует его как раз тогда, когда его зарождающиеся силы начинают раскрываться. Это возвращение открывает путь к более глубокому посвящению в духовные практики Королевства Штормград и готовит служителей к тому, чтобы использовать Свет против растущих угроз, окружающих государство."}},faq={{q="Почему верховный жрец Рохан отказывается обучать жрецов-людей?",a="Верховный жрец Рохан уважает жрецов-людей, но у дворфийского духовенства есть особые обряды и благословения, передаваемые по их культурной линии. Он считает, что жрецы-люди должны изучать особые, специальные приемы, которые хранят их собственные наставники в Штормграде.",al={"why send to stormwind","why rohan won't train","dwarf priest won't train me","почему отправляют в штормград","почему рохан не обучает","жрец-дворф не хочет обучать меня"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — видная духовная предводительница и наставница в Соборе Света в Штормграде. Она следит за ростом многообещающих жрецов-людей, направляя их промежуточное обучение и обряды.",al={"high priestess laurena","who is laurena","cathedral priest trainer","верховная жрица лорена","кто такая лорена","наставник жрецов в соборе"}},{q="Где найти верховного жреца Рохана?",a="Верховный жрец Рохан находится в Зале Тайн в Мистическом квартале, в великом горном городе дворфов Стальгорне.",al={"rohan location","where is high priest rohan","find rohan","где рохан","где верховный жрец рохан","найти рохана"}},{q="В чем смысл этого задания?",a="Это задание-указатель: оно направляет жрецов-людей среднего уровня из земель дворфов обратно в главный расовый центр обучения — Собор Света, где они смогут изучать духовные приемы, свойственные их расе.",al={"arcane feedback quest purpose","why do this quest","what does this quest do","цель задания волшебное искажение","зачем это задание","что дает это задание"}}},fp="15,380,20.477.0,23.446.0,57.267.0,30.223.0,37.131.0,34.219.0"}
P.entries["quest:5678"] = {n="Волшебное искажение",s="«Волшебное искажение» — задание жрецов Альянса, которое направляет жрецов-людей, обучающихся в Дарнассе, домой, в Штормград. Жрица Алатея из Храма Луны отправляет их в путь, что подчеркивает глубокий культурный разрыв в отношении к магии между ночными эльфами и Восточными королевствами. По возвращении в Собор Света верховная жрица Лорена готовит послушника к более глубокому богословскому обучению.",h="«Волшебное искажение» — задание жрецов Альянса, которое направляет жрецов-людей, обучающихся в Дарнассе...",kw={"arcane feedback","cathedral of light","darnassus","high priestess laurena","holy light","priest quest","priestess alathea","stormwind","волшебное искажение","собор света","дарнасс","верховная жрица лорена","свет","задание жреца","жрица алатея","штормград"},ang={["class:Priest"]="Это паломничество — важный порог на вашем духовном пути, напоминающий о резком философском разрыве между сестринством Элуны и догмами Света.",["race:Human"]="Возвращение в Штормград приводит вас домой, в сердце Церкви Священного Света, вдали от замкнутого и скептичного жречества кальдорай.",["race:NightElf"]="Откровенная настороженность жрицы Алатеи отражает извечный страх кальдорай, что вмешательство молодых смертных рас в тайную магию приведет к новой катастрофе."},sec={{t="Неохотный вызов",b="Жрица Алатея опекает приезжих жрецов в тихих залах Храма Луны в Дарнассе. Хотя она признает официальный союз между кальдорай и людьми Штормграда, она глубоко сомневается в магических и духовных практиках людей. Общество ночных эльфов считает тайную силу изначально нестабильной и опасной — таково наследие десяти тысячелетий скорби после Войны Древних. Даже божественные обряды людей, стирающие грань между сияющей верой и тайной механикой, заметно тревожат жречество ночных эльфов."},{t="Возвращение в Собор",b="Несмотря на колебания, Алатея чтит узы между расами Альянса и отпускает послушника откликнуться на зов Собора Света. Верховная жрица Лорена разослала гонцов за море, чтобы собрать растущих жрецов-людей для высшего обучения. Вернувшись в Штормград, послушник покидает залитые луной рощи Элуны ради величественных каменных святилищ и золотого сияния Света."}},faq={{q="Почему жрица Алатея хочет, чтобы я покинул Дарнасс?",a="Жрица Алатея выполняет вызов, присланный вашим начальством в Штормграде, но ей также не по себе от богословских практик людей. Она открыто признает свое глубокое недоверие к тайной магии, божественной или нет, и потому охотно отправляет послушников-людей в их собственные великие соборы.",al={"why alathea sends me away","why return to stormwind","alathea arcane feedback","почему алатея отсылает меня","зачем возвращаться в штормград","алатея волшебное искажение"}},{q="Почему ночные эльфы не доверяют жреческой магии людей?",a="Культура ночных эльфов во многом определена катастрофическим Расколом, вызванным безрассудным тайным колдовством десять тысяч лет назад. Поклонение кальдорай сосредоточено на Элуне, и их жрицы с глубоким подозрением относятся к любой традиции, граничащей с тайными манипуляциями или включающей их, даже если ее исповедуют союзники по Свету.",al={"why night elves hate arcane","night elf arcane distrust","elune vs holy light","почему ночные эльфы не любят тайную магию","недоверие ночных эльфов к тайной магии","элуна и свет"}},{q="Кто такая верховная жрица Лорена?",a="Верховная жрица Лорена — видная духовная предводительница Собора Света в Штормграде. Она следит за обучением и продвижением начинающих жрецов-людей, направляя их понимание Света по мере роста их силы.",al={"who is laurena","high priestess laurena stormwind","кто такая лорена","верховная жрица лорена штормград"}},{q="К чему ведет это задание?",a="Доклад верховной жрице Лорене означает переход к более высокому жреческому обучению людей в Штормграде и открывает дисциплину и благословения, свойственные людям, приверженным Свету.",al={"what comes after arcane feedback","arcane feedback reward lore","что после волшебного искажения","награда за волшебное искажение"}}},fp="15,405,19.552.0,23.430.0,54.311.0,49.344.0,30.240.0,31.200.0"}
P.entries["quest:5679"] = {n="Всепожирающая чума",s="«Всепожирающая чума» — обряд обучения для жрецов Отрекшихся, доказавших преданность магии Тьмы. Жрица Эльталисте в Подгороде дает это знание, знаменуя посвящение послушника в одно из самых страшных проклятий жречества нежити.",h="«Всепожирающая чума» — обряд обучения для жрецов Отрекшихся, доказавших преданность магии Тьмы.",kw={"aelthalyste","devouring plague","forsaken","lordaeron","priest","shadow","undercity","war quarter","эльталисте","всепожирающая чума","отрекшиеся","лордерон","жрец","тьма","подгород","военный квартал"},ang={["class:Priest"]="Этот обряд дает жрецам Отрекшихся одно из самых узнаваемых расовых заклинаний, напрямую связывая их выживание с порчей, которую они насылают на врагов.",["faction:Horde"]="Если другие союзники Орды полагаются на духов предков или равновесие стихий, то Отрекшиеся приносят в общий арсенал фракции беспощадные проклятия, подобные болезням.",["race:Undead"]="Чумное колдовство Тьмы отражает отход Отрекшихся от традиционного лордеронского богослужения после Третьей войны."},sec={{t="Проклятие Тьмы",b="В мрачных кельях Военного квартала жрица Эльталисте наставляет Отрекшихся в суровых искусствах Тьмы. Если живые жрецы других рас взывают за силой к Свету или духам предков, то Отрекшиеся выработали собственные духовные учения. Всепожирающая чума воплощает их философию: наносить врагам страдания, а похищенную жизненную силу вливать в собственные разлагающиеся тела."},{t="Испытание мастерства",b="Эльталисте не отдает знание о чуме легко. Это заклинание считается оружием сильной злобы, призванным переломить ход борьбы против Плети и Алого ордена. Передавая заклинание, Эльталисте велит ученикам оттачивать власть над ним неустанной практикой и предупреждает, что тех, кто стремится овладеть темными искусствами, ждут куда более суровые испытания."}},faq={{q="В чем смысл этого задания?",a="Задание служит формальным уроком для жрецов Отрекшихся, достигших опытного уровня. Поговорив с жрицей Эльталисте, жрец узнает, как накладывать Всепожирающую чуму — характерную порчу Тьмы, свойственную только нежити.",al={"why do devouring plague","what does devouring plague quest do","devouring plague purpose","зачем всепожирающая чума","что дает задание всепожирающая чума","цель всепожирающей чумы"}},{q="Кто такая жрица Эльталисте?",a="Жрица Эльталисте — наставница жрецов Отрекшихся в Военном квартале Подгорода. Она следит за развитием начинающих заклинателей Тьмы и добивается, чтобы они эффективно применяли свои разрушительные дары на благо Отрекшихся.",al={"who is aelthalyste","aelthalyste lore","aelthalyste undercity","кто такая эльталисте","эльталисте предания","эльталисте подгород"}},{q="Могут ли жрецы других рас изучить Всепожирающую чуму у Эльталисте?",a="Нет. Всепожирающая чума — тайное заклинание, доступное только жрецам Отрекшихся. Тролли, люди, ночные эльфы и дворфы общаются с иными духовными силами и вместо этого обладают собственными расовыми учениями.",al={"can trolls learn devouring plague","is devouring plague undead only","other races devouring plague","могут ли тролли выучить всепожирающую чуму","всепожирающая чума только для нежити","другие расы всепожирающая чума"}},{q="Где сдать это задание?",a="Жрицу Эльталисте можно найти в Военном квартале Подгорода среди наставников и жрецов Отрекшихся.",al={"aelthalyste location","where is devouring plague quest","undercity priest trainer location","где эльталисте","где задание всепожирающая чума","наставник жрецов подгород"}},{q="Почему жрецы Отрекшихся специализируются на чуме и магии Тьмы?",a="Из-за своего посмертного состояния жрецы Отрекшихся терпят сильную физическую боль, когда направляют Свет. Поэтому многие обращаются к учениям Тьмы, используя порчу, проклятия и похищенную жизненную силу, чтобы выживать и воевать.",al={"why forsaken shadow priests","lore behind undead priests","forsaken priest magic","почему жрецы отрекшихся тьма","предания о жрецах нежити","магия жрецов отрекшихся"}},{q="О каких испытаниях говорит Эльталисте?",a="Эльталисте предупреждает, что по мере роста силы жреца испытания, ожидающие его в Лордероне, будут суровее. Владение темной магией привлекает опасное внимание и смертельных врагов и требует полного мастерства над каждым проклятием в арсенале послушника.",al={"tests later meaning","future tests aelthalyste","what tests","какие испытания","будущие испытания эльталисте","что за испытания"}}},fp="16,281,21.464.0,17.391.0,34.237.0,29.233.0,67.210.0,30.140.0,62.242.0,39.236.0"}
P.entries["quest:57"] = {n="Ночной Дозор",s="По прямому поручению командира Алтеи Чернодрев искатели приключений отправляются в захваченные нежитью курганы Сумеречного леса, чтобы сократить число неупокоенных мертвецов. Эта продолжающаяся кампания направлена против скелетов-чудовищ, выбирающихся с Безмятежного кладбища и из Вороньего Холма. Отражение скелетной напасти необходимо, чтобы хрупкое убежище — Темнолесье — не пало окончательно во тьму.",h="По прямому поручению командира Алтеи Чернодрев искатели приключений отправляются в захваченные нежитью...",kw={"althea ebonlocke","darkshire","duskwood","night watch","raven hill","skeletal fiend","skeletal horror","tranquil gardens","алтея чернодрев","темнолесье","сумеречный лес","ночной дозор","вороний холм","скелет-чудовище","скелетный ужас","безмятежное кладбище"},ang={["class:Paladin"]="Для Серебряной Длани и рыцарей Света столкновение с оскверненными мертвецами на Безмятежном кладбище — священный долг: очистить поруганные места упокоения.",["class:Priest"]="Жрецы, ступающие по оскверненной земле Вороньего Холма, видят неприкрытое надругательство над погребальными обычаями и силой веры приносят тихий покой измученным душам.",["faction:Alliance"]="Темнолесье — хрупкая юго-восточная граница Альянса в южной части Восточных королевств. Помощь Ночному Дозору помогает городу оставаться пригодным плацдармом, а не окончательно пасть в руины.",["race:Human"]="Многие скелеты, встающие из земли Сумеречного леса, — предки живых жителей Штормграда и Темнолесья, поэтому для защитников-людей эта битва глубоко личная."},sec={{t="Мертвые не знают покоя",b="Трагическое превращение Сумеречного леса из зеленого края, некогда называвшегося Светлой рощей, в окутанные туманом сумерки сделало его кладбища неестественно беспокойными. Командир Алтея Чернодрев, возглавляющая добровольческое ополчение Темнолесья — Ночной Дозор, ведет бесконечную осаду. Без помощи Штормграда ее силы растянуты опасно тонко. Сообщения об оживших скелетах и ужасах, поднимающихся из земли, грозят захлестнуть восточные поселения, и ополчение вынуждено набирать любых крепких путников, готовых войти в мертвые земли."},{t="Оскверненная земля",b="Кампания ведет новобранцев к двум очагам некромантических волнений: Безмятежному кладбищу к югу от города и обширным заросшим просторам кладбища Вороньего Холма далеко на западе. Скелеты выбираются из забытых гробниц и неглубоких придорожных могил, оживленные темной магией, застрявшей в сумрачном лесу. Уничтожение этих тварей дает осажденным жителям Темнолесья жизненно важную передышку, хотя это нескончаемая борьба с укоренившимся злом."}},faq={{q="Почему Ночной Дозор полагается на путников, а не на стражу Штормграда?",a="Штормград почти бросил Сумеречный лес на произвол судьбы, оставив оборону региона командиру Алтее Чернодрев и ее местному добровольческому ополчению. Из-за внутренних политических раздоров и пропавшего короля столица не присылает подкреплений гарнизона, и Ночному Дозору приходится нанимать проходящих мимо искателей приключений.",al={"why no stormwind help","where is stormwind army","why darkshire alone","почему нет помощи штормграда","где армия штормграда","почему темнолесье одно"}},{q="Откуда берутся скелеты?",a="Скелеты-чудовища выбираются из освященной земли Безмятежного кладбища и обширного кладбища Вороньего Холма. Темные магические силы, пронизывающие лес, потревожили захоронения многовековой давности и подняли древние останки как безмозглых свирепых стражей.",al={"skeletons duskwood origin","why are there skeletons","undead source duskwood","скелеты сумеречный лес","откуда скелеты","источник нежити сумеречный лес"}},{q="Кто возглавляет Ночной Дозор?",a="Ночным Дозором командует командир Алтея Чернодрев. Она родственница правителя Темнолесья, лорда Элло Чернодрева, лично руководит обороной города и координирует действия против нежити и чудовищ Сумеречного леса.",al={"night watch leader","who is althea ebonlocke","commander ebonlocke","глава ночного дозора","кто такая алтея чернодрев","командир чернодрев"}},{q="Чем отличаются Безмятежное кладбище и Вороний Холм?",a="Безмятежное кладбище лежит сразу к югу от Темнолесья и представляет собой непосредственную локальную угрозу городу. Кладбище Вороньего Холма, расположенное через лес далеко на западе, — огромное место захоронений, ставшее средоточием нежити Сумеречного леса.",al={"tranquil gardens vs raven hill","which graveyard is better","graveyard locations duskwood","безмятежное кладбище или вороний холм","какое кладбище лучше","расположение кладбищ сумеречный лес"}},{q="Что будет после уничтожения этих скелетов?",a="Уничтожение скелетов-чудовищ — лишь один этап кампании Алтеи. Ночной Дозор постоянно следит за растущими угрозами в лесу — от вурдалаков и скелетов до более опасной нежити и зловещих некромантов, направляющих ее в глубине Сумеречного леса.",al={"what next night watch","night watch questline","after night watch 2","что дальше ночной дозор","цепочка заданий ночного дозора","после ночного дозора 2"}},{q="Почему Темнолесье постоянно в опасности?",a="Некогда мирная провинция Королевства Штормград под названием Светлая роща, Сумеречный лес был поглощен магическими сумерками и поражен темными проклятиями. Теперь леса наводнены одичавшими воргенами, прожорливыми пауками и неупокоенной нежитью, и Темнолесье осталось последним оплотом живых людей в этой местности.",al={"why duskwood dangerous","darkshire danger","what cursed duskwood","почему сумеречный лес опасен","опасность темнолесья","что прокляло сумеречный лес"}}},fp="15,389,20.537.0,12.482.0,73.312.0,36.275.0,26.240.0,63.272.0,43.279.0,36.302.0"}
P.entries["quest:5713"] = {n="Каждый выстрел – в цель",s="Неся срочное сообщение в Аубердин, Часовой Айнаша попала в засаду и была отравлена враждебным фурболгом по имени Марош Бесчестный и его отрядом следопытов. Обездвиженная при приготовлении противоядия, она рассчитывает на путников поблизости, которые отобьют нападающих, чтобы она выжила и выполнила свой долг.",h="Неся срочное сообщение в Аубердин, Часовой Айнаша попала в засаду и была отравлена враждебным фурболгом по...",kw={"ambush","antidote","aynasha","darkshore","furbolg","lor'danel","maestra's post","marosh","onaeya","sentinel","засада","противоядие","айнаша","темные берега","фурболг","лор'данель","застава мейстры","марош","ойнея","часовой"},ang={["class:Hunter"]="Айнаша показывает непоколебимую решимость стрелка: она продолжает посылать меткие выстрелы в заросли, даже поддаваясь сильному яду.",["faction:Alliance"]="Если держать лесные тропы свободными от агрессивных стай фурболгов, путь между Ясеневым лесом и оплотами Альянса на севере остается безопасным.",["race:NightElf"]="Защищая Айнашу, вы сохраняете и сестру Часовых, и важные сообщения, которые передаются между заставами Ясеневого леса и севера Темных берегов."},sec={{t="Засада на лесной дороге",b="Тропы северного Калимдора стали опасными: порча все глубже укореняется среди диких обитателей. Часовой Айнаша шла в Аубердин с важными донесениями, когда ее перехватили враждебные фурболги. Под началом Мароша Бесчестного нападавшие ударили быстро и ввели изнуряющий яд, из-за которого разведчица едва держалась на ногах и не могла продолжить путь пешком."},{t="Удержать рубеж",b="Хотя Айнаша умело обращается с природными снадобьями, приготовить и принять противоядие под сенью леса требует времени, которого у нее нет, пока за ней охота. Пока следопыты Мароша приближаются, Айнаше приходится полагаться на путников, охраняющих ее позицию. Несмотря на слабеющие силы, она поднимает лук и осыпает заросли огнем прикрытия, решив, что ни она, ни ее донесение не погибнут в глуши."},{t="Доложить на Заставу Мейстры",b="Когда нападение отбито, а Марош убит, противоядие возвращает Айнаше достаточно сил, чтобы завершить путь в Аубердин. Чтобы застава на юге, в Ясеневом лесу, узнала об агрессивных действиях фурболгов, угрожающих региональным путям снабжения, она просит своих защитников доложить напрямую Часовому Ойнее на Заставе Мейстры."}},faq={{q="Кто такая Часовой Айнаша?",a="Часовой Айнаша — разведчица из ночных эльфов, доставляющая важные сообщения через границы Темных берегов и Ясеневого леса. Искусная лучница, знаток выживания в лесу, она едва не погибла от неожиданной засады с ядом во время службы.",al={"sentinel aynasha","aynasha","who is aynasha","часовой айнаша","айнаша","кто такая айнаша"}},{q="Кто напал на Часового Айнашу?",a="Ее поджидала в засаде стая враждебных фурболгов во главе с Марошем Бесчестным. Во время первой стычки они отравили ее, надеясь одолеть обездвиженную разведчицу, пока она не оправилась.",al={"who attacked her","marosh the devious","marosh","who poisoned her","кто напал на нее","марош бесчестный","марош","кто ее отравил"}},{q="Куда направлялась Часовой Айнаша?",a="Айнаша шла в Аубердин, чтобы доставить важное донесение, но Марош и его следопыты задержали ее на дороге.",al={"where was aynasha going","aynasha destination","lor'danel","куда шла айнаша","цель айнаши","лор'данель"}},{q="Почему вы должны доложить Часовому Ойнее?",a="Поскольку Айнаше нужно немедленно спешить в Аубердин, чтобы передать сообщение, она просит вас отправиться на юг, на Заставу Мейстры в Ясеневом лесу, и сообщить Часовому Ойнее о враждебности фурболгов.",al={"sentinel onaeya","why maestra's post","onaeya","часовой ойнея","почему застава мейстры","ойнея"}},{q="Почему фурболги в этой местности враждебны?",a="На Темных берегах и в Ясеневом лесу многие племена фурболгов поддались демонической порче и безумию после Третьей войны, из-за чего без разбора нападают на Часовых и случайных путников.",al={"why are furbolgs attacking","furbolg hostility","corrupted furbolg","почему фурболги нападают","враждебность фурболгов","оскверненные фурболги"}},{q="Сражается ли Айнаша во время засады?",a="Да. Хотя яд едва позволяет ей стоять, она поддерживает своего защитника огнем из лука, пока готовит противоядие.",al={"does aynasha help","aynasha bow","does she fight","помогает ли айнаша","лук айнаши","сражается ли она"}}},fp="19,310,25.400.0,16.406.0,24.340.1,24.233.0,30.184.0,37.125.0,39.198.0,41.207.0,37.155.0"}
P.entries["quest:5722"] = {n="В поисках потерянного ранца",s="«В поисках потерянного ранца» — задание Орды, которое дает Рахауро на Вершине Старейшин в Громовом Утесе. По поручению Мудрой старухи Магаты Зловещего Тотема искателей приключений направляют под Оргриммар, в Огненную пропасть, найти останки Маура Зловещего Тотема, посланника, погибшего после того, как обнаружил нечто необычное среди троггов.",h="«В поисках потерянного ранца» — задание Орды, которое дает Рахауро на Вершине Старейшин в Громовом Утесе.",kw={"elder rise","magatha grimtotem","maur grimtotem","ragefire chasm","rahauro","searching for the lost satchel","thunder bluff","troggs","вершина старейшин","магата зловещий тотем","маур зловещий тотем","огненная пропасть","рахауро","в поисках потерянного ранца","громовой утес","трогги"},ang={["faction:Horde"]="Пока Тралл занят уничтожением темных культистов прямо под столицей Орды, грозовые шепоты из Мулгора говорят о том, что Зловещий Тотем преследует в той же пещере собственные тихие цели.",["race:Tauren"]="Намерения племени Зловещего Тотема часто резко расходятся с открытым руководством Кэрна Кровавого Копыта, поэтому скрытное любопытство Магаты к подземным существам под городом союзников заслуживает пристального внимания."},sec={{t="Задание Зловещего Тотема под Оргриммаром",b="Пока вождь Тралл и его советники заняты присутствием Совета Теней в Огненной пропасти, племя Зловещего Тотема преследует собственные тайные интересы. Магата Зловещий Тотем на Вершине Старейшин в Громовом Утесе узнает, что ее посланник Маур Зловещий Тотем спустился в подземную пещеру под Оргриммаром, чтобы изучить троггов и попытаться вступить с ними в переговоры. Маур не вернулся, но ходят слухи, что незадолго до гибели он сделал любопытную находку."},{t="Павший посланник",b="Действуя от имени Магаты, ее помощник Рахауро отправляет воинов прямо в пропасть. В глубине туннелей, залитых лавой, у лагерей троггов лежит изуродованное тело Маура, жестоко избитого грубыми дубинами и голыми кулаками. Твари совсем не тронули его вещи, оставив имущество тауренов и все секреты, которые он искал, агентам Магаты."}},faq={{q="Кто посылает искателей приключений на это задание?",a="Задание выдает Рахауро, помощник Магаты Зловещего Тотема на Вершине Старейшин в Громовом Утесе.",al={"quest giver","who starts searching for the lost satchel","where to get quest","персонаж, выдающий задания","кто начинает в поисках потерянного ранца","где взять задание"}},{q="Кто такой Маур Зловещий Тотем?",a="Маур был агентом племени Зловещего Тотема, посланным Магатой Зловещим Тотемом в Огненную пропасть, чтобы разведать обстановку и попытаться наладить связь с троггами. Его забили до смерти в глубине пещеры.",al={"maur grimtotem","who was maur","what happened to maur","маур зловещий тотем","кто такой маур","что случилось с мауром"}},{q="Почему Магату Зловещий Тотем заинтересовала Огненная пропасть?",a="Магату интересовали трогги, заполонившие туннели под Оргриммаром, и она послала Маура попытаться наладить с ними связь. Когда перед смертью Маур нашел среди них нечто необычное, она захотела, чтобы его находку доставили прямо ей.",al={"magatha troggs","why magatha cares about ragefire","why send maur","магата трогги","почему магату интересует огненная пропасть","зачем послали маура"}},{q="Где находится тело Маура Зловещего Тотема?",a="Тело Маура лежит в глубине Огненной пропасти под Оргриммаром, избитое, неподалеку от земель троггов вдоль подземных троп.",al={"find maur","maur grimtotem location","where is maurs body","найти маура","где маур зловещий тотем","где тело маура"}},{q="Обобрали ли трогги Маура после убийства?",a="Нет. Трогги мало заботятся о богатстве, инструментах и письменных бумагах, поэтому одежда и ранец Маура остались нетронутыми рядом с его изломанными останками.",al={"trogg loot","was maur robbed","добыча троггов","ограбили ли маура"}},{q="Что будет после того, как найдено тело Маура?",a="При осмотре тела Маура вы найдете его ранец, что открывает следующее задание «Возвращение потерянной сумки»: доставить его находки Магате Зловещий Тотем в Громовой Утес.",al={"follow up quest","next quest after lost satchel","what to do with satchel","следующее задание","какое задание после потерянного ранца","что делать с ранцем"}}},fp="30,335,37.466.0,19.397.1,36.106.0,22.189.0,55.237.0,41.132.0,43.138.0,40.170.1"}
P.entries["quest:5723"] = {n="Испытание силы врага",s="«Испытание силы врага» — задание Орды, которое выдает Рахауро на Вершине Старейшин в Громовом Утесе от имени Магаты Зловещего Тотема. После провального дипломатического шага под Оргриммаром, закончившегося гибелью посланников, таурены стремятся отомстить и истребляют троггов, заполонивших Огненную пропасть.",h="«Испытание силы врага» — задание Орды, которое выдает Рахауро на Вершине Старейшин в Громовом Утесе от имени...",kw={"elder rise","magatha grimtotem","orgrimmar","ragefire chasm","rahauro","testing an enemy's strength","thunder bluff","troggs","вершина старейшин","магата зловещий тотем","оргриммар","огненная пропасть","рахауро","испытание силы врага","громовой утес","трогги"},ang={["class:Shaman"]="У троггов есть собственные грубые духовные практики: они повелевают первобытными стихиями в лавовых туннелях, являя собой извращенное зеркало благородных шаманских традиций.",["faction:Horde"]="Это задание показывает солидарность между разными народами Орды: Громовой Утес тратит силы и воинов, чтобы защитить основания Оргриммара.",["race:Orc"]="Хотя задание дано руководством тауренов, оно напрямую защищает сердце орочьей столицы от троггов, прорывающих туннели под городом.",["race:Tauren"]="Кровь дипломатов-тауренов обагрила камни Огненной пропасти, и потому этот штурм становится актом прямого возмездия от имени Вершины Старейшин."},sec={{t="Дипломатия сталкивается с дикостью",b="Когда подземные трогги впервые выбрались из огненных расселин под орочьей столицей Оргриммаром, Мудрая старуха Магата Зловещий Тотем предложила мир. Она отправила в глубины посланников-тауренов для переговоров с этими существами. Ответ был жестоким и мгновенным: трогги без колебаний перебили делегатов. Сочтя расправу непростительным оскорблением тауренов и растущей угрозой для всей Орды, Магата решила ответить на дикость решительной силой."},{t="Угроза под Оргриммаром",b="Таурен Рахауро, действуя в Громовом Утесе как доверенное лицо Магаты, руководит военным ответом. Он направляет воинов проникнуть в Огненную пропасть, найти скопления троггов и уничтожить их передовых воинов и шаманов. Нанося удар в глубину их подземных владений, Орда стремится сократить число троггов прежде, чем их туннели позволят им свободно хлынуть на улицы Оргриммара наверху."}},faq={{q="Почему задание для подземелья Оргриммара выдают в Громовом Утесе?",a="Задание исходит от руководства тауренов. Магата Зловещий Тотем лично отправила дипломатов в Огненную пропасть на переговоры с троггами, и после гибели этих посланников ее помощник Рахауро взялся организовать воинов на Вершине Старейшин в Громовом Утесе, чтобы отомстить за них.",al={"why thunder bluff","quest start thunder bluff","rahauro location","почему громовой утес","начало задания громовой утес","где рахауро"}},{q="Кто такой Рахауро?",a="Рахауро — таурен, выдающий задания на Вершине Старейшин в Громовом Утесе. Он действует от имени Магаты Зловещего Тотема и руководит вылазками в Огненную пропасть, чтобы истреблять троггов и возвращать реликвии, потерянные во время прежних неудачных дипломатических миссий.",al={"who is rahauro","rahauro npc","rahauro elder rise","кто такой рахауро","рахауро нпс","рахауро вершина старейшин"}},{q="Почему Магата Зловещий Тотем пыталась заключить мир с троггами?",a="Магата задумывала это как жест доброй воли: она хотела наладить отношения с подземными существами, а не сразу проливать кровь. Однако трогги оказались неспособны или не пожелали вести мирную беседу и перебили ее посланников по прибытии.",al={"why peace with troggs","magatha trogg diplomacy","why negotiate with troggs","почему мир с троггами","дипломатия магаты с троггами","зачем вести переговоры с троггами"}},{q="Каких врагов нужно убить для этого задания?",a="Вам нужно войти в Огненную пропасть под Оргриммаром и убить как троггов Огненной пропасти, так и шаманов Огненной пропасти, чтобы сломить их передовые ряды и ослабить поддержку заклинателей.",al={"which mobs to kill","quest targets","ragefire troggs","каких мобов убить","цели задания","трогги огненной пропасти"}},{q="Можно ли выполнять это задание вместе с другими заданиями подземелья?",a="Да. Рахауро также выдает задание «В поисках потерянного ранца», которое отправляет искателей приключений в ту же пропасть на поиски останков неудачной дипломатической группы, поэтому выполнять оба задания одновременно удобно.",al={"other rfc quests","lost satchel quest","ragefire chasm quests","другие задания огненной пропасти","задание потерянный ранец","задания огненная пропасть"}},{q="Откуда приходят трогги?",a="Трогги выбрались из глубоких вулканических трещин под Дуротаром. Как отмечает Рахауро по завершении задания, Орда по-прежнему мало знает о происхождении этих диких пещерных жителей и о том, почему они решили прорыть ход наверх, в Оргриммар.",al={"trogg origin rfc","where do troggs come from","why are troggs under orgrimmar","происхождение троггов","откуда берутся трогги","почему трогги под оргриммаром"}}},fp="27,301,24.496.0,28.421.0,68.293.0,15.246.0,52.282.0,44.183.0,58.219.0,33.252.0"}
P.entries["quest:5724"] = {n="Возвращение потерянной сумки",s="Это поручение завершает поиски Маура Зловещего Тотема в глубинах Огненной пропасти под Оргриммаром. Найдя убитого таурена, крепко сжимающего свой ранец, искателям приключений предстоит доставить найденную сумку Рахауро на Вершину Старейшин в Громовом Утесе.",h="Это поручение завершает поиски Маура Зловещего Тотема в глубинах Огненной пропасти под Оргриммаром.",kw={"elder rise","grimtotem satchel","magatha","maur grimtotem","ragefire chasm","rahauro","returning the lost satchel","thunder bluff","вершина старейшин","сумка маура зловещего тотема","магата","маур зловещий тотем","огненная пропасть","рахауро","возвращение потерянной сумки","громовой утес"},ang={["faction:Horde"]="Трогги и культисты угрожают туннелям под Оргриммаром, а тайное присутствие агентов Зловещего Тотема под крепостью Тралла вызывает политические вопросы без ответов.",["race:Tauren"]="У клана Зловещего Тотема непростые отношения с народом Кэрна Кровавого Копыта, поэтому любая тайная операция последователей Магаты в Оргриммаре вызывает подозрения."},sec={{t="Мрачная находка",b="Под красными скалами и в огненных глубинах Огненной пропасти Маур Зловещий Тотем принял жестокую смерть от рук троггов. Даже мертвым он не разжал рук, обхвативших личную сумку, и охранял ее содержимое до последнего вздоха. Вынув сумку из окоченевших пальцев, вы получаете единственную зацепку о том, что привело члена клана Зловещего Тотема в вулканические пещеры под столицей Тралла."},{t="Интерес Магаты",b="Когда вы доставляете сумку Рахауро на Вершину Старейшин, становится ясно, что за поручением стояла сама Магата Зловещий Тотем. Рахауро с благодарностью принимает посылку, желая понять, почему напрасно погиб один из членов клана Магаты, и вручает награду, одобренную непосредственно Мудрой старухой. Что нес Маур и зачем Магата отправила его в кишащие троггами расселины Оргриммара, известно лишь руководству клана Зловещего Тотема."}},faq={{q="Где находится Маур Зловещий Тотем?",a="Тело Маура Зловещего Тотема лежит в глубине подземелья Огненная пропасть под Оргриммаром, в окружении враждебных троггов.",al={"maur grimtotem corpse","find maur grimtotem","where is maur","тело маура зловещего тотема","найти маура зловещего тотема","где маур"}},{q="Кому сдавать сумку?",a="Сумку Маура Зловещего Тотема нужно вернуть Рахауро, который стоит на Вершине Старейшин в Громовом Утесе.",al={"turn in lost satchel","where is rahauro","satchel turn in","сдать потерянную сумку","где рахауро","сдача сумки"}},{q="Почему Маур Зловещий Тотем оказался в Огненной пропасти?",a="Рахауро заявляет, что не знает, почему соплеменник Магаты должен был напрасно погибнуть, но Магата Зловещий Тотем лично приказала организовать поиски, что говорит о том, что Маур действовал по делам клана.",al={"why was maur in rfc","maur mission","what was maur doing","почему маур в огненной пропасти","миссия маура","что делал маур"}},{q="Что лежит в Сумке Маура Зловещего Тотема?",a="Точное содержимое посыльному не раскрывается. Маур ревностно охранял сумку до самой смерти, и ее передают Рахауро нераскрытой от имени Магаты.",al={"what was in the bag","satchel contents","что было в сумке","содержимое сумки"}},{q="Что убило Маура Зловещего Тотема?",a="Мауру устроили засаду и убили дикие трогги, населяющие туннели Огненной пропасти.",al={"how did maur die","who killed maur","как погиб маур","кто убил маура"}},{q="Кто стоит за этим заданием?",a="Хотя на Вершине Старейшин с вами имеет дело Рахауро, награда и указание исходят непосредственно от Мудрой старухи Магаты Зловещего Тотема.",al={"who sent rahauro","magatha connection","кто послал рахауро","связь магаты"}}},fp="26,255,16.403.0,18.455.1,32.116.0,32.101.0,41.179.0,37.169.0,27.92.0,24.123.0"}
P.entries["quest:5725"] = {n="Силы разрушения...",s="Это задание выдает повелитель ужаса Вариматрас в Подгороде и отправляет героев Орды в глубины Огненной пропасти под Оргриммаром. Леди Сильвана Ветрокрылая ищет два темных тома, которыми владеет демонический культ Пламенеющего Клинка, чтобы подпитать свою долгую войну против Плети и Короля-лича.",h="Это задание выдает повелитель ужаса Вариматрас в Подгороде и отправляет героев Орды в глубины Огненной...",kw={"incantations from the nether","lich king","ragefire chasm","searing blade","spells of shadow","sylvanas","undercity","varimathras","магическая формула пустоты","король-лич","огненная пропасть","пламенеющий клинок","заклинания тьмы","сильвана","подгород","вариматрас"},ang={["class:Warlock"]="Добыча книг «Заклинания Тьмы» и «Магическая формула Пустоты» — привычное дело для тех, кто вырывает опасные тайны Легиона у безрассудных культистов.",["faction:Horde"]="Разгром Пламенеющего Клинка помогает укрепить основания Оргриммара, даже если магическая добыча уплывает в хранилища Подгорода.",["race:Undead"]="Для воителей Отрекшихся путь через Великое море ради разграбления недр Оргриммара служит и союзу с Ордой, и главной цели Темной Госпожи — уничтожить Плеть."},sec={{t="Одолженный арсенал",b="Пока орки Тралла заняты истреблением культистов Пламенеющего Клинка, затаившихся прямо под их столицей, Отрекшиеся видят возможность в оккультных запасах культа. Вариматрас по приказу Сильваны Ветрокрылой посылает лазутчиков проникнуть в Огненную пропасть и завладеть двумя демоническими гримуарами: «Заклинания Тьмы» и «Магическая формула Пустоты». По мнению Темной Госпожи, дары демонов гораздо лучше служат дисциплинированной воле Отрекшихся, чем пропадают впустую у мелких культистов."},{t="Война за освобождение",b="Когда тома добыты, Вариматрас раскрывает их более широкое назначение. Темная магия в них должна усилить продолжающуюся кампанию Сильваны против Плети. Забирая каждую крупицу запретной силы, Отрекшиеся надеются разорвать хватку Короля-лича на Лордероне и полностью освободить оставшуюся нежить от его ментального рабства."}},faq={{q="Зачем Вариматрасу книги из-под Оргриммара?",a="Культисты Пламенеющего Клинка в Огненной пропасти владеют мощными демоническими томами. Леди Сильвана считает, что эти артефакты Пылающего Легиона пропадают зря у простых культистов, и хочет обратить их темные знания против Короля-лича.",al={"why varimathras ragefire","undercity ragefire quest reason","why steal books","зачем вариматрасу огненная пропасть","причина задания подгород огненная пропасть","зачем красть книги"}},{q="Какие книги вас посылают добыть?",a="Вам нужно забрать две книги заклинаний у культистов и чернокнижников Пламенеющего Клинка: «Заклинания Тьмы» и «Магическая формула Пустоты».",al={"what books","power to destroy books","ragefire book drops","какие книги","книги силы разрушения","книги огненная пропасть добыча"}},{q="Где в Подгороде находится Вариматрас?",a="Вариматрас стоит рядом с леди Сильваной Ветрокрылой в Королевском квартале Подгорода.",al={"varimathras location","where is varimathras","turn in location","где вариматрас","местонахождение вариматраса","где сдать задание"}},{q="Как это связано с общими целями Отрекшихся?",a="Сильвана собирает любые возможные средства для войны против Плети. Завладев запретными демоническими тайнами, Отрекшиеся получают больше магических рычагов, чтобы сокрушить власть Короля-лича над нежитью.",al={"forsaken motivation","why does sylvanas need spells","undercity lich king plot","мотивы отрекшихся","зачем сильване заклинания","подгород заговор короля-лича"}},{q="Знает ли Тралл, что Отрекшиеся забирают эти книги?",a="Пока руководство Орды в Оргриммаре занято очисткой своих улиц от предателей и демонов, особый приказ Вариматраса подается как тихое дело Темной Госпожи, а не как официальное совместное решение Орды.",al={"does thrall know","orgrimmar undercity secret books","shadow council books orc reaction","знает ли тралл","оргриммар подгород тайные книги","совет теней книги реакция орков"}},{q="Что представляет собой Пламенеющий Клинок?",a="Пламенеющий Клинок — тайная секта Совета Теней, действующая прямо в Огненной пропасти под Оргриммаром и практикующая темную демоническую магию под самым носом у Вождя.",al={"what is searing blade","searing blade ragefire","ragefire cultists","что такое пламенеющий клинок","пламенеющий клинок огненная пропасть","культисты огненной пропасти"}}},fp="23,288,18.494.0,22.344.0,58.238.0,35.126.0,47.89.0,53.203.0,53.239.0,26.182.0"}
P.entries["quest:5726"] = {n="Тайные враги",s="«Тайные враги» — первая часть расследования вождя Тралла о проникновении культистов в Дуротар. Зная, что сторонники демонов действуют прямо под носом у Орды, Тралл поручает многообещающему молодому герою добыть Лейтенантский знак отличия в Скале Черепа, чтобы начать тайную операцию.",h="«Тайные враги» — первая часть расследования вождя Тралла о проникновении культистов в Дуротар.",kw={"burning blade","durotar","hidden enemies","lieutenant's insignia","orgrimmar","skull rock","thrall","пылающий клинок","дуротар","тайные враги","лейтенантский знак отличия","оргриммар","скала черепа","тралл"},ang={["class:Warlock"]="Чернокнижникам Орды приходится действовать осторожно: практикуя магию Скверны под строгим надзором Тралла, они призваны искоренить культистов, чье безудержное служение демонам угрожает самому существованию Оргриммара.",["faction:Horde"]="Это задание — решающий миг, когда вождь Тралл лично доверяет герою защиту сердца новой Орды от демонического подрыва.",["race:Orc"]="Для орков, стремящихся преодолеть кровавый дурман и позор демонического проклятия, охота на Пылающий Клинок — личная борьба за то, чтобы демоническая скверна не отравила их народ во второй раз."},sec={{t="Гниль в Дуротаре",b="Пока молодая Орда пытается создать надежный дом в Дуротаре, вождь Тралл сталкивается с коварной угрозой, куда более смертоносной, чем набеги кентавров или вторжения свинобразов: изменой изнутри. Демонический культ, известный как Пылающий Клинок, укоренился прямо у ворот Оргриммара, питаясь остатками демонической порчи и жаждой темной силы. Тралл понимает, что, послав официальных стражей Кор'крона или известных командиров, он лишь заставит культистов спрятаться глубже. Ему нужен тот, кто не связан с громкими именами, — его осторожные глаза и уши."},{t="Проникновение в Скалу Черепа",b="К востоку от Оргриммара лежит Скала Черепа — суровая пещера, кишащая чернокнижниками, демонами Бездны и фанатичными культистами. Тралл отправляет героя прямо в это гнездо с особой целью: добыть Лейтенантский знак отличия у одного из предводителей Пылающего Клинка. Эта эмблема — не просто боевой трофей, а важный пропуск, дающий владельцу доступ к скрытой иерархии культа и позволяющий провести более глубокую операцию, чтобы выяснить, кто направляет действия культа из тени."}},faq={{q="Кто выдает задание «Тайные враги»?",a="Задание выдает сам вождь Тралл в Аллее Мудрости в Оргриммаре — после того как вы доложите Оргнилу Душегрызу.",al={"hidden enemies questgiver","who starts hidden enemies","where to start hidden enemies","тайные враги кто выдает","кто начинает тайные враги","где начать тайные враги"}},{q="Какова цель задания «Тайные враги»?",a="Тралл поручает вам отправиться в Скалу Черепа к востоку от Оргриммара, убить культистов Пылающего Клинка и принести Лейтенантский знак отличия.",al={"hidden enemies objective","what do i need for hidden enemies","тайные враги цель","что нужно для тайные враги"}},{q="Почему Тралл просто не отправит элитных стражей зачистить Скалу Черепа?",a="Тралл опасается, что открытое военное вмешательство позволит настоящим заговорщикам скрыться и глубже спрятать порчу. Неизвестный герой может тихо добыть пропуск и проникнуть в сеть, не насторожив высокопоставленных предателей, дергающих за ниточки.",al={"why thrall needs adventurers","why not send the army","почему тралл нанимает героев","почему не послать армию"}},{q="Что такое Скала Черепа?",a="Скала Черепа — уединенная система пещер на восточном побережье Дуротара, к северо-востоку от Оргриммара. Это тайная крепость и место призыва демонов для культа Пылающего Клинка.",al={"where is skull rock","what is skull rock cave","где скала черепа","что такое пещера скала черепа"}},{q="Для чего нужен Лейтенантский знак отличия?",a="Знак служит доказательством звания среди культистов. Тралл планирует с его помощью внедрить своего агента в ряды Пылающего Клинка, чтобы узнать, кто руководит их действиями.",al={"what is the insignia for","lieutenants insignia purpose","для чего знак отличия","лейтенантский знак отличия назначение"}},{q="Какие еще задания можно выполнить вместе с этим?",a="Герои, входящие в Скалу Черепа, часто выполняют задание «Скала Черепа», собирая ошейники культистов, и могут добыть Око Пылающей Тени у предводителя культа Газз'уза, чтобы начать задание «Пылающие тени».",al={"skull rock quests","quests in skull rock","задания скала черепа","задания в скале черепа"}}},fp="14,320,22.586.0,23.509.0,35.146.0,35.145.0,66.266.0,19.185.0,43.198.0,54.199.0"}
P.entries["quest:5727"] = {n="Тайные враги",s="После обнаружения деятельности культа в Скале Черепа вождь Тралл поручает вам проникнуть в Пылающий Клинок в самом Оргриммаре. Предъявив знак лейтенанта культа чернокнижнику Нииру Огненному Клинку, вы проверяете его верность и приоткрываете завесу над Советом Теней, действующим прямо под городом.",h="После обнаружения деятельности культа в Скале Черепа вождь Тралл поручает вам проникнуть в Пылающий Клинок в...",kw={"burning blade","cleft of shadow","insignia","neeru fireblade","orgrimmar","ragefire chasm","shadow council","thrall","пылающий клинок","расселина теней","знак отличия","нииру огненный клинок","оргриммар","огненная пропасть","совет теней","тралл"},ang={["class:Warlock"]="Нииру заявляет, что выступает за чернокнижников, ищущих законного положения в Орде, но его предательство грозит навлечь суровое осуждение на всех, кто практикует магию Скверны под властью Тралла.",["faction:Horde"]="Известие о том, что демонические культы открыто действуют под самим основанием Оргриммара, угрожает самому существованию молодой Орды.",["race:Orc"]="Для орков, стремящихся избавиться от наследия кровожадности и демонической порчи, возрождение Совета Теней под их столицей — жуткое эхо темного прошлого на Дреноре."},sec={{t="Хитрый план Вождя",b="Вместо прямого удара по зловещим силам в Расселине Теней Тралл выбирает хитрость, а не спешку. Он прекрасно знает, что Нииру Огненный Клинок притворяется верным, втайне служа культистам. Немедленный удар по Нииру лишь встревожит его хозяев и оборвет след, ведущий вглубь заговора. Поэтому Тралл передает знак, отобранный у культа в Дуротаре, и велит вам выдать себя за новичка, чтобы выяснить, что знает Нииру."},{t="Скрытый хозяин Расселины",b="В мрачных пещерах Расселины Теней, у входа в Огненную пропасть, Нииру Огненный Клинок быстро клюет на приманку. Приняв вас за недавно повышенного лейтенанта своего ордена, чернокнижник открыто насмехается над неведением Тралла. Он раскрывает, что Пылающий Клинок и ответвления вроде Пламенеющего Клинка — лишь ширмы, напрямую подчиняющиеся Совету Теней, который служит воле Пылающего Легиона. Он хвастается, что заставил Вождя бросить верных солдат против культистов в пропасти, используя армии самого Тралла, чтобы отсеять слабых."}},faq={{q="Почему Тралл оставляет Нииру в живых, если знает, что тот предатель?",a="Тралл позволяет Нииру жить, потому что разоблаченный предатель ценнее мертвого. Если казнить его сразу, Совет Теней просто заменит его кем-то, кого труднее обнаружить. Держа Нииру под присмотром, Тралл превращает чернокнижника в невольный источник сведений о передвижениях культа в Оргриммаре.",al={"why thrall trust neeru","why keep neeru alive","neeru traitor","почему тралл доверяет нииру","почему оставить нииру живым","нииру предатель"}},{q="Кто такой Нииру Огненный Клинок?",a="Нииру Огненный Клинок — орк-чернокнижник, живущий в Расселине Теней. Внешне он делает вид, что помогает Траллу превратить чернокнижников в верных слуг Орды. На деле он предводитель культа Пылающего Клинка и от имени Совета Теней плетет измену под городом.",al={"neeru backstory","who is neeru","нииру история","кто такой нииру"}},{q="Какова связь между Пылающим Клинком и Советом Теней?",a="Как раскрывает Нииру, Пылающий Клинок — не самостоятельная секта, а ветвь самого Совета Теней. Совет держит несколько дочерних культов, включая Пламенеющий Клинок в Огненной пропасти, чтобы разделять, обманывать и контролировать честолюбивых последователей под верховной властью Пылающего Легиона.",al={"burning blade shadow council connection","are burning blade shadow council","пылающий клинок совет теней связь","пылающий клинок и совет теней"}},{q="Кто возглавляет культистов в Огненной пропасти?",a="Культ Пламенеющего Клинка в пропасти под Оргриммаром возглавляют сатир Баззалан и орк-чернокнижник Жергош Призыватель Духов. Нииру использует героев Тралла для борьбы с ними, чтобы и проредить сторонников Орды, и испытать своих подчиненных.",al={"ragefire chasm leaders","searing blade leaders","предводители огненной пропасти","предводители пламенеющего клинка"}},{q="Как я получил Лейтенантский знак отличия?",a="Знак был добыт во время первого расследования Тралла о деятельности культа в Дуротаре, а именно у культистов Пылающего Клинка, действовавших из Скалы Черепа.",al={"where lieutenant insignia comes from","insignia source","откуда знак отличия","источник знака отличия"}}},fp="14,322,21.465.0,25.577.1,61.333.1,23.287.1,74.314.1,45.280.0,43.173.0"}
P.entries["quest:5728"] = {n="Тайные враги",s="«Тайные враги» — ключевое задание на проникновение, данное вождем Траллом, чтобы уничтожить коварный культ, процветающий под Оргриммаром. Обманув предателя Нииру Огненного Клинка и убедив его, что вы союзник, Тралл отправляет вас в раскаленные глубины Огненной пропасти, чтобы убить верховных командиров Пламенеющего Клинка.",h="«Тайные враги» — ключевое задание на проникновение, данное вождем Траллом, чтобы уничтожить коварный культ...",kw={"bazzalan","cleft of shadow","hidden enemies","jergosh the invoker","neeru fireblade","ragefire chasm","searing blade","shadow council","thrall","баззалан","расселина теней","тайные враги","жергош призыватель духов","нииру огненный клинок","огненная пропасть","пламенеющий клинок","совет теней","тралл"},ang={["class:Warlock"]="Хотя Тралл терпит чернокнижников, практикующих темные искусства для защиты Орды, Жергош и Пламенеющий Клинок переходят грань, становясь предательскими слугами демонических хозяев.",["faction:Horde"]="Демоническая порча в сердце Дуротара угрожает всему, что новая Орда боролась создать; очистка Огненной пропасти жизненно важна для сохранения ее нелегко доставшейся самостоятельности.",["race:Orc"]="Для орков, ищущих искупления за кровавый дурман, уничтожение остатков Совета Теней под Оргриммаром — вопрос глубокого культурного выживания и чести."},sec={{t="Рак под улицами",b="Оргриммар строился как убежище для свободного народа орков, но в его основании таются старые демонические оковы. Под шумными рынками лежит Расселина Теней, ведущая глубже, в подземные туннели Огненной пропасти. В этих вулканических глубинах набирают силу остатки Совета Теней — Пламенеющий Клинок, практикующий темные искусства и замышляющий изнутри, из собственной столицы, свергнуть молодую Орду."},{t="Игра в двойного агента",b="Прямой штурм без разведданных оставил бы сеть Совета Теней нетронутой. Тралл придумал тайный план, использовав вас, чтобы выманить сведения у Нииру Огненного Клинка, внешне покорного чернокнижника в Расселине Теней. Уверенный в вашей преданности их извращенному делу, Нииру невольно выдал имена подземных предводителей культа: порочного сатира Баззалана и чернокнижника Жергоша Призывателя Духов."},{t="Обезглавливание Пламенеющего Клинка",b="Тралл поручает вам спуститься в Огненную пропасть и убить Баззалана и Жергоша, повергнув культистов в хаос. Важно, чтобы убийства нельзя было приписать вам: Нииру не должен узнать, кто совершил расправу, ведь Тралл намерен держать чернокнижника под наблюдением. Гибель этих главарей потрясет культ и даст молодому городу Орды драгоценную передышку."}},faq={{q="Кто отдает приказ об убийстве в задании «Тайные враги»?",a="Вождь Тралл лично дает это поручение в Аллее Мудрости в Оргриммаре, доверяя вам щекотливую шпионскую работу ради безопасности городских низов.",al={"who gives hidden enemies","hidden enemies quest giver","thrall ragefire quest","кто выдает тайные враги","тайные враги персонаж, выдающий задание","тралл задание огненная пропасть"}},{q="Почему Тралл просто не казнит Нииру Огненного Клинка?",a="Тралл предпочитает держать Нииру в живых под наблюдением. Зная, кто предатель, разведчики Вождя могут следить за перепиской Совета Теней и предугадывать будущие заговоры, а не позволять скрытому преемнику занять его место.",al={"why not kill neeru","why keep neeru alive","neeru fireblade traitor","почему не убить нииру","почему оставить нииру живым","нииру огненный клинок предатель"}},{q="Где находятся Баззалан и Жергош Призыватель Духов?",a="Оба предводителя обитают в глубинах Огненной пропасти — подземелья, доступного через Расселину Теней в Оргриммаре. Жергош занимает вулканический уступ, откуда командует культистами, а сатир Баззалан скрывается в возвышенной пещере неподалеку.",al={"where is bazzalan","where is jergosh","ragefire chasm bosses","где баззалан","где жергош","боссы огненной пропасти"}},{q="Что представляет собой Пламенеющий Клинок?",a="Пламенеющий Клинок — местная секта, связанная с Пылающим Клинком и Советом Теней. Ее члены поклоняются демоническим силам и практикуют магию Скверны под Оргриммаром, надеясь в итоге свергнуть Тралла и вновь поработить Орду.",al={"what is searing blade","searing blade cult","burning blade orgrimmar","что такое пламенеющий клинок","культ пламенеющего клинка","пылающий клинок оргриммар"}},{q="Почему сатир вроде Баззалана действует под орочьим городом?",a="Сатиры — древние слуги Пылающего Легиона. Баззалан служит демоническим наставником и подстрекателем, направляя смертных культистов Пламенеющего Клинка исполнять волю Легиона прямо под ногами Тралла.",al={"why is there a satyr in orgrimmar","bazzalan lore","satyr in ragefire","почему сатир в оргриммаре","баззалан предания","сатир в огненной пропасти"}},{q="Как это задание вписывается в общее прохождение Огненной пропасти?",a="«Тайные враги» — кульминация цепочки заданий Тралла о проникновении. Оно сочетается с другими заданиями подземелья в Огненной пропасти и направляет игроков убить главных человекоподобных боссов подземелья одним согласованным ударом.",al={"is hidden enemies ragefire","rfc quest line","hidden enemies chain","тайные враги огненная пропасть","цепочка заданий огненной пропасти","цепочка тайные враги"}}},fp="14,323,28.426.0,24.430.1,30.409.2,37.166.0,48.242.1,51.232.0,26.228.0,57.211.0,60.230.0"}
P.entries["quest:5729"] = {n="Тайные враги",s="«Тайные враги» — важный этап расследования вождя Тралла о проникновении культистов в Оргриммар. Казнив предводителей Пылающего Клинка под городом, игрок получает задание еще глубже внедриться и стать доверенным лицом Нииру Огненного Клинка.",h="«Тайные враги» — важный этап расследования вождя Тралла о проникновении культистов в Оргриммар.",kw={"bazzalan","burning blade","cleft of shadow","hidden enemies","jergosh","neeru fireblade","orgrimmar","ragefire chasm","shadow council","thrall","баззалан","пылающий клинок","расселина теней","тайные враги","жергош","нииру огненный клинок","оргриммар","огненная пропасть","совет теней","тралл"},ang={["class:Rogue"]="Это задание — классический пример операции по внедрению: уничтожить сеть агента и сразу занять место его самого доверенного соратника.",["class:Warlock"]="Нииру Огненный Клинок открыто стоит среди учителей чернокнижников в Расселине Теней, показывая, как близко новая Орда Тралла соседствует с темной магией, не поддаваясь откровенной порче.",["faction:Horde"]="Задание подчеркивает прагматичную дипломатию и государственное мышление Тралла: он использует контрразведку, чтобы обезопасить Оргриммар изнутри, а не полагается лишь на грубую силу.",["race:Orc"]="Орки, стремящиеся избавиться от демонического наследия старой Орды, должны выкорчевать Пылающий Клинок из недр Оргриммара, чтобы защитить свою честь."},sec={{t="Ход Тралла",b="После убийства Баззалана и Жергоша Призывателя Духов в Огненной пропасти Тралл видит возможность. Вместо того чтобы разоблачить Нииру Огненного Клинка сразу, Вождь решает играть вдолгую. Нииру встревожен внезапной потерей своих подземных лейтенантов, и в местном культе образовалась пустота в руководстве. Тралл посылает вас обратно в сумрачные глубины Расселины Теней, чтобы вы предстали надежным союзником, способным заполнить эту пустоту."},{t="Обман чернокнижника",b="Когда к нему обращаются в Расселине Теней, Нииру Огненный Клинок явно в ярости из-за внезапной гибели своих сообщников. Не зная, что стоящий перед ним искатель приключений сам казнил их по приказу Тралла, Нииру проклинает «доброхотов», разоривших Огненную пропасть. Застигнутый врасплох быстрым ударом, Нииру начинает терять бдительность рядом с игроком, а Тралл получает возможность следить за влиянием Совета Теней прямо изнутри Оргриммара."}},faq={{q="Почему Тралл не казнит Нииру Огненного Клинка сразу?",a="Тралл предпочитает держать разоблаченного врага там, где можно за ним наблюдать. Пока Нииру считает, что его прикрытие цело, Тралл может следить за перепиской Пылающего Клинка и отследить его связи с Советом Теней, используя игрока как внедренного агента.",al={"why spare neeru","why does thrall let neeru live","neeru alive","зачем щадить нииру","почему тралл оставляет нииру в живых","нииру жив"}},{q="Кто такие Баззалан и Жергош?",a="Баззалан был сатиром, а Жергош Призыватель Духов — орком-чернокнижником. Действуя в глубине Огненной пропасти под Оргриммаром, они были полевыми командирами и заговорщиками культа Пылающего Клинка, пока Тралл не приказал их убить.",al={"bazzalan","jergosh","who died in ragefire","баззалан","жергош","кто погиб в огненной пропасти"}},{q="Знает ли Нииру, что вы убили его лейтенантов?",a="Нет. Нииру изливает ярость, считая, что неизвестные агенты Тралла застали их врасплох и перебили, и совершенно не подозревает, что искатель приключений, выражающий ему сочувствие и предлагающий помощь, и есть убийца.",al={"does neeru know","neeru knows who killed them","знает ли нииру","нииру знает, кто их убил"}},{q="Где находится Нииру Огненный Клинок?",a="Нииру Огненный Клинок обитает в Расселине Теней — подземной пещере в глубине Оргриммара, где собираются чернокнижники, разбойники и заклинатели тьмы, обособленно от остального города.",al={"neeru location","find neeru","where is neeru fireblade","где нииру","найти нииру","где нииру огненный клинок"}},{q="Что такое Пылающий Клинок?",a="Пылающий Клинок, изначально свирепый клан с Дренора, выродился в демонический культ, которым управлял Совет Теней. В Калимдоре его остатки стремятся подорвать новую Орду Тралла и вернуть рабство у демонов.",al={"burning blade","burning blade cult","пылающий клинок","культ пылающего клинка"}},{q="Что происходит после разговора с Нииру?",a="Заручившись доверием Нииру и выслушав его сетования о потерях в Огненной пропасти, вы возвращаетесь к Траллу в Крепость Громмаш, чтобы доложить об успехе и завершить цепочку внедрения.",al={"what next","quest continuation","что дальше","продолжение задания"}}},fp="14,264,15.468.0,23.473.1,60.270.0,30.229.0,46.190.0,33.189.0,26.217.0,37.189.1"}
P.entries["quest:5730"] = {n="Тайные враги",s="«Тайные враги» — завершение операции вождя Тралла по внедрению в шабаш Пылающего Клинка в Оргриммаре и его оценке. Вернувшись к Траллу после того, как заручились доверием Нииру Огненного Клинка, вы передаете важные сведения о растущем влиянии культа в Калимдоре.",h="«Тайные враги» — завершение операции вождя Тралла по внедрению в шабаш Пылающего Клинка в Оргриммаре и его...",kw={"ashenvale","barrens","burning blade","cleft of shadows","hidden enemies","neeru fireblade","ragefire chasm","searing blade","shadow council","thrall","ясеневый лес","степи","пылающий клинок","расселина теней","тайные враги","нииру огненный клинок","огненная пропасть","пламенеющий клинок","совет теней","тралл"},ang={["class:Rogue"]="Это задание отражает раннее шпионское ремесло Орды: глубокое прикрытие, контрразведка и терпение важнее немедленного столкновения.",["class:Warlock"]="Нииру Огненный Клинок олицетворяет опасную грань практики скверны и показывает, как легко темные искусства из разрешенного государством средства превращаются в откровенное подчинение Совету Теней.",["faction:Horde"]="Раскрытие измены в самих границах Оргриммара доказывает, что юная Орда должна защищаться от древней демонической порчи изнутри, сражаясь с внешними врагами."},sec={{t="Раскрытый культ",b="По просьбе вождя Тралла агент отнес Лейтенантский знак отличия, взятый у Скалы Черепа, Нииру Огненному Клинку — чернокнижнику, открыто живущему в Расселине Теней, а позже нанес удар по предводителям Пламенеющего Клинка в глубине Огненной пропасти. Играя роль готового на все новобранца и принося знаки павших культистов, агент завоевывает доверие Огненного Клинка, и тот невольно раскрывает более широкую сеть, стоящую за его действиями."},{t="Шепот Совета Теней",b="Думая, что обрел верного лейтенанта, Нииру Огненный Клинок признает, что потеря в Огненной пропасти — неудача для Пламенеющего Клинка, но заявляет, что великие замыслы Совета Теней остаются в силе. Он сообщает, что у его хозяев есть действующие агенты не только в Степях, но и глубже, в чащах Ясеневого леса. Эта весть застает Вождя врасплох: демонический заговор простирается далеко за пределы подземных туннелей столицы."},{t="Бдительность Вождя",b="Вместо немедленной казни Нииру Тралл выбирает осторожный путь. Пока Нииру не знает о своем разоблачении, Орда может следить за его перепиской и прослеживать щупальца культа в Дуротаре, Степях и Ясеневом лесу. Вождь готовит разведчиков и шпионов для проверки этих местных ответвлений, понимая, что искоренение демонической порчи требует точности, а не безрассудной спешки."}},faq={{q="В чем цель этого задания?",a="Вам нужно добраться из Расселины Теней в Аллею Мудрости в Оргриммаре и поговорить с вождем Траллом, рассказав, что Нииру Огненный Клинок поведал о планах Совета Теней.",al={"hidden enemies goal","what to do hidden enemies 5","thrall turn in","цель тайные враги","что делать тайные враги 5","сдать задание тралу"}},{q="Почему Нииру Огненный Клинок мне доверяет?",a="В ходе цепочки «Тайные враги» вы добыли Лейтенантский знак отличия у Пылающего Клинка на Скале Черепа и вручили его Нииру, выдав себя за честолюбивого неофита культа, и убедили его, что вы верный соратник.",al={"why neeru trusts me","tricking neeru","fireblade infiltration","почему нииру мне доверяет","обмануть нииру","внедрение к огненному клинку"}},{q="Почему Тралл не арестует и не казнит Нииру Огненного Клинка сразу?",a="Нииру гораздо полезнее живым и несведущим. Пока он думает, что его прикрытие цело, разведчики Тралла могут следить за его посланиями и отследить его контакты до более крупных ячеек Совета Теней по всему Калимдору.",al={"why is neeru alive","why not kill neeru","why thrall leaves neeru","почему нииру жив","почему не убить нииру","почему тралл оставляет нииру"}},{q="Что нового узнает Тралл из этого доклада?",a="Тралл узнает, что культ под Оргриммаром поддерживает Совет Теней и что его агенты активно замышляют операции и в Степях, и в чащах Ясеневого леса.",al={"what did thrall learn","shadow council ashenvale","neeru secret","что узнал тралл","совет теней ясеневый лес","тайна нииру"}},{q="Пылающий Клинок и Пламенеющий Клинок — это одно и то же?",a="Пламенеющий Клинок — местная секта, действующая в Огненной пропасти под Оргриммаром и являющаяся ответвлением более широкого культа Пылающего Клинка, которым управляет демонический Совет Теней.",al={"burning blade vs searing blade","ragefire chasm cults","cult differences","пылающий клинок и пламенеющий клинок","культы огненной пропасти","различия культов"}},{q="Продолжается ли эта цепочка заданий где-либо?",a="Тралл велит вам отдохнуть и обещает позвать позже, но прямого задания, которое сразу продолжало бы именно эту линию тайного внедрения, нет.",al={"hidden enemies followup","next quest after hidden enemies","where does thrall send you next","продолжение тайных врагов","следующее задание после тайных врагов","куда тралл отправит дальше"}}},fp="14,287,15.454.1,30.485.2,24.412.1,31.184.0,34.223.1,64.212.1,56.182.1,57.188.0,40.157.0"}
P.entries["quest:5761"] = {n="Убить тварь",s="Нииру Огненный Клинок, орк-чернокнижник из Расселины Теней в Оргриммаре, посылает бойцов Орды в глубь Огненной пропасти охотиться на Тарагамана Ненасытного. Заявляя, что действует по приказу вождя Тралла, Нииру требует сердце огромного стража Скверны как доказательство падения демонического культа.",h="Нииру Огненный Клинок, орк-чернокнижник из Расселины Теней в Оргриммаре, посылает бойцов Орды в глубь...",kw={"cleft of shadows","felguard","neeru fireblade","orgrimmar","ragefire chasm","searing blade","slaying the beast","taragaman","расселина теней","страж Скверны","нииру огненный клинок","оргриммар","огненная пропасть","пламенеющий клинок","убить тварь","тарагаман"},ang={["class:Warlock"]="Работая в Расселине Теней рядом с Нииру, чернокнижники воочию видят, как трудно балансировать на политическом канате тем, кто практикует магию Скверны под бдительным взором Тралла.",["faction:Horde"]="Очистка демонического присутствия, гноящегося прямо под столицей Орды, — вопрос немедленного выживания города для каждой расы Оргриммара.",["race:Orc"]="Для орков, стремящихся избавиться от наследия проклятия демонической крови, обнаружить стража Скверны и демонический культ прямо под троном Тралла — нестерпимый позор."},sec={{t="Угроза под городом",b="Под красной земляной поверхностью Оргриммара лежит Огненная пропасть — пылающая подземная расселина, кишащая троггами, зверями и тайными агентами Пламенеющего Клинка. В Расселине Теней наверху Нииру Огненный Клинок представляется верным слугой, которому Тралл поручил очистить это демоническое гнездо. Он указывает прямо на Тарагамана Ненасытного, огромного стража Скверны в сердце пещеры, называя демона вдохновителем подземного культа."},{t="Обман чернокнижника",b="Сердце Тарагамана, доставленное Нииру Огненному Клинку, приносит высокую похвалу и обещания, что Тралл будет удовлетворен. На деле Тарагаман — не настоящий вожак культа, а заменимый головорез. Направив героев Орды на демона, Нииру дает Траллу заметную победу, чтобы развеять подозрения, и оберегает от пристального внимания истинное руководство Пламенеющего Клинка и его глубинные операции под Оргриммаром."}},faq={{q="Кто такой Тарагаман Ненасытный?",a="Тарагаман Ненасытный — могучий страж Скверны, стоящий на скалистой площадке в сердце Огненной пропасти. Нииру Огненный Клинок называет его предводителем культистов Пламенеющего Клинка, гнездящихся под Оргриммаром.",al={"who is taragaman","what is taragaman","taragaman lore","кто такой тарагаман","что такое тарагаман","предания о тарагамане"}},{q="Кто выдает задание «Убить тварь»?",a="Нииру Огненный Клинок выдает это задание в своей палатке в Расселине Теней — пещерном квартале чернокнижников Оргриммара.",al={"quest giver slaying the beast","who gives this quest","neeru fireblade quest","кто выдает убить тварь","кто дает это задание","задание нииру огненного клинка"}},{q="Зачем Нииру нужно сердце Тарагамана?",a="Нииру утверждает, что сердце нужно, чтобы доказать вождю Траллу, что демоническая угроза под Оргриммаром уничтожена.",al={"why get the heart","taragaman heart purpose","why does neeru want the heart","зачем сердце","для чего сердце тарагамана","зачем нииру сердце"}},{q="Тарагаман действительно предводитель Пламенеющего Клинка?",a="Нииру Огненный Клинок называет его предводителем. Тарагаман — грозный страж Скверны, обитающий среди культистов Пламенеющего Клинка в сердце Огненной пропасти.",al={"is taragaman the real leader","who leads searing blade","taragaman leader","настоящий ли тарагаман лидер","кто возглавляет пламенеющий клинок","лидер тарагаман"}},{q="Где находится Тарагаман?",a="Тарагаман Ненасытный стоит на каменной площадке, окруженной лавой, в средней части Огненной пропасти, среди культистов Пламенеющего Клинка.",al={"taragaman location","where is the beast","where to find taragaman","где тарагаман","где тварь","где найти тарагамана"}},{q="Как это задание связано с «Тайными врагами»?",a="В цепочке «Тайные враги» Тралл расследует проникновение Совета Теней в Оргриммар и присматривает за Нииру Огненным Клинком. Нииру дает это задание, чтобы показать Траллу видимые успехи против Пламенеющего Клинка.",al={"connection to hidden enemies","hidden enemies questline","thrall and neeru","связь с тайными врагами","цепочка тайные враги","тралл и нииру"}}},fp="17,289,25.472.0,23.417.1,30.204.0,38.115.0,38.122.1,54.153.1,27.145.0,46.226.1"}
P.entries["quest:5762"] = {n="Хеминг Эрнестуэй",s="Это поручение отправляет путников через море — от соляных равнин Калимдора в парные джунгли Тернистой долины. Крейвел Углебрад, оборотистый торговец с Виражей на Миражах, просит искателей приключений доставить давно задержанную посылку со специальными припасами знаменитому охотнику на крупного зверя Хемингу Эрнестуэю.",h="Это поручение отправляет путников через море — от соляных равнин Калимдора в парные джунгли Тернистой долины.",kw={"ammunition","hemet nesingwary","kravel koalbeard","kravel's crate","mirage raceway","shimmering flats","stranglethorn vale","боеприпасы","хеминг эрнестуэй","крейвел углебрад","сундук крейвела","виражи на миражах","мерцающая равнина","тернистая долина"},ang={["class:Hunter"]="Доставка специальных боеприпасов Хемингу Эрнестуэю знакомит следопытов с самым известным сафари на крупного зверя в Азероте.",["race:Dwarf"]="Доставка особых боеприпасов между двумя плутоватыми знакомыми-дворфами показывает, как далеко разбредаются выходцы из Стальгорна в погоне за монетой и добычей."},sec={{t="Доставка через континенты",b="На слепящих просторах Мерцающей равнины торговля идет бойко, но грузы порой запаздывают. Крейвел Углебрад наконец получает задержавшийся ящик, предназначенный одному из его богатых покровителей — Хемингу Эрнестуэю. Хеминг покинул Тысячу Игл задолго до прибытия посылки и заранее заплатил за ее пересылку в свой охотничий лагерь в глуши Тернистой долины. Вместо того чтобы самому совершать тяжелый путь, Крейвел нанимает странствующих искателей приключений, готовых преодолеть океан."},{t="Боеприпасы для охоты",b="Разыскав экспедицию Эрнестуэя к северу от Лагеря Гром'гол, вы узнаете, что в тяжелом ящике лежат специальные крупнокалиберные боеприпасы, необходимые для охоты на опасных хищников, бродящих по джунглям. Хеминг сразу замечает на снаряжении посыльного характерную белую корку соляных равнин и радуется, что старая дружба с хитрецом Крейвелом принесла его сафари столь нужную огневую мощь."}},faq={{q="Где начинается и заканчивается эта доставка?",a="Доставка начинается у Крейвела Углебрада на Виражах на Миражах, на Мерцающей равнине на юге Тысячи Игл. Она завершается на другом краю света, в лагере экспедиции Хеминга Эрнестуэя на севере Тернистой долины, чуть севернее Гром'гола.",al={"quest start and end","where is hemet","where do i go","начало и конец задания","где хеминг","куда идти"}},{q="Что находится в Сундуке Крейвела?",a="В ящике лежат боеприпасы особого калибра для оружия охотников на крупного зверя. Хеминг Эрнестуэй заказал эти особые патроны, чтобы пробивать толстые шкуры самых свирепых зверей Тернистой долины.",al={"whats in the crate","crate contents","kravel package","что в ящике","содержимое ящика","посылка крейвела"}},{q="Почему Крейвел не доставил ящик сам?",a="Крейвел — предприимчивый торговец-дворф, занятый своими вложениями и затеями на Виражах на Миражах. Вместо того чтобы бросить свой пост и пересекать моря, он предпочитает нанять проходящих искателей приключений на деньги, которые Эрнестуэй заплатил заранее.",al={"why kravel hire someone","why does kravel need help","зачем крейвел нанимает","почему крейвелу нужна помощь"}},{q="Как Хеминг узнает, откуда прибыл посыльный?",a="Получив посылку, Хеминг сразу замечает по запаху и виду характерную соляную корку на одежде посыльного и отмечает, что она именно с Мерцающей равнины, а не обычная пустынная пыль.",al={"desert salt","hemet dialogue salt","пустынная соль","диалог хеминга о соли"}},{q="Какие отношения связывают Крейвела и Хеминга?",a="Хеминг — давний и выгодный клиент Крейвела. Крейвел уважает его тугой кошелек, а Хеминг с теплом считает Крейвела «старым прохвостом», который вечно что-то затевает.",al={"kravel and hemet history","do they know each other","история крейвела и хеминга","знакомы ли они"}},{q="Кто такой Хеминг Эрнестуэй?",a="Хеминг Эрнестуэй — знаменитый стрелок-дворф, писатель и охотник на крупного зверя, возглавляющий нескончаемое сафари в опасных глубинах Тернистой долины.",al={"who is hemet","nesingwary lore","кто такой хеминг","предания об эрнестуэе"}}},fp="16,316,27.507.0,23.417.0,39.265.0,30.179.0,44.241.0,48.209.0,51.178.0,24.157.0"}
P.entries["quest:579"] = {n="Библиотека Штормграда",s="В глубине Королевской библиотеки Крепости Штормграда главный библиотекарь Донал Товальд ведает собранием исторических трудов и описаний земель. По приказу юного короля Андуина Ринна выделены средства на переписывание этих трудов для горожан и ученых, приносящих официальные библиотечные свитки. Эта услуга позволяет искателям приключений изучить историю, фракции и легенды Азерота из первых рук.",h="В глубине Королевской библиотеки Крепости Штормграда главный библиотекарь Донал Товальд ведает собранием...",kw={"anduin wrynn","books","donyal tovald","library scrip","lore tomes","stormwind keep","stormwind library","transcription","андуин ринн","книги","донал товальд","библиотечный свиток","тома преданий","крепость штормграда","библиотека штормграда","переписывание"},ang={["class:Mage"]="Для приверженцев тайной магии Королевская библиотека — важный светский архив королевства: в нем хранятся немагические исторические сочинения, которые дополняют изучение тайных искусств в Квартале магов.",["faction:Alliance"]="Библиотека хранит общие триумфы и трагедии Альянса Лордерона и напоминает горожанам об исторических узах между людьми, дворфами, гномами и высшими эльфами.",["race:Human"]="Лишившись бесчисленных архивов при разорении старого Штормграда в Первой войне, ученые-люди высоко ценят сохранение и копирование всех хроник, переживших восстановление королевства."},sec={{t="Королевский указ о знаниях",b="Пока верховный лорд Болвар Фордрагон и леди Катрана Престор ведают обороной и придворной политикой в отсутствие короля Вариана, юный король Андуин направил королевские средства на образование. Понимая, что знание истории важно для будущего королевства, Андуин взял под покровительство переписывание древних рукописей и исторических дневников. Королевская библиотека в залах Крепости Штормграда служит не только хранилищем государственных тайн, но и собранием, где предания сохраняются в записях и копируются для тех, кто состоит на королевской службе."},{t="Обмен свитков",b="Переписывание хрупкого пергамента вручную требует много времени, чернил и королевского дозволения. Чтобы управлять этой раздачей, главный библиотекарь Донал Товальд принимает официальные библиотечные свитки, выдаваемые искателям приключений и ученым по землям Альянса. Взамен Товальд предоставляет верные копии исторических томов — от древней истории Восточных королевств до описаний дальних земель, — давая представление о конфликтах за стенами столицы."}},faq={{q="Для чего нужно задание Библиотеки Штормграда?",a="Это задание позволяет сдать Библиотечный свиток главному библиотекарю Доналу Товальду в обмен на читаемые книги преданий. Они рассказывают о прошлом различных сюжетов, людей и земель Альянса по всему Азероту.",al={"what does this quest do","stormwind library quest purpose","why do this quest","что дает это задание","зачем библиотека штормграда","зачем выполнять задание"}},{q="Кто такой Донал Товальд?",a="Донал Товальд — библиотекарь, заведующий Королевской библиотекой в Крепости Штормграда. Он ведает собранием письменных хроник королевства и исполняет распоряжение Андуина раздавать копии достойным ученым и искателям приключений.",al={"who is donyal tovald","librarian stormwind","who gives the books","кто такой донал товальд","библиотекарь штормграда","кто выдает книги"}},{q="Где получить Библиотечный свиток?",a="Библиотечные свитки выдают за особые задания на землях Альянса — у ученых, магистратов и чиновников, поощряющих исследования и интерес к миру.",al={"where do i get library scrip","how to get library scrip","library scrip source","где взять библиотечный свиток","как получить библиотечный свиток","источник библиотечного свитка"}},{q="Почему юный король Андуин финансирует библиотеку?",a="Король Андуин Ринн придает большое личное значение учению и образованию. Даже будучи ребенком, правящим под руководством регента Болвара Фордрагона, он выделил королевские средства, чтобы сделать копии исторических томов королевства доступными для всех.",al={"why does anduin care about books","anduin library funding","king anduin books","почему андуину важны книги","финансирование библиотеки андуином","король андуин книги"}},{q="Где в Штормграде находится библиотека?",a="Королевская библиотека находится в Крепости Штормграда — огромной цитадели, возвышающейся в восточной части города. Донала Товальда можно найти внутри, среди высоких полок и читальных столов.",al={"where is stormwind library","royal library location","where is donyal tovald located","где библиотека штормграда","расположение королевской библиотеки","где донал товальд"}},{q="Могу ли я читать полученные книги?",a="Да. Каждая книга из библиотеки — читаемый игровой предмет, раскрывающий колорит, сюжетный фон и контекст различных легенд и исторических событий мира Warcraft.",al={"are the books readable","can you open the books","do books do anything","можно ли читать книги","можно ли открыть книги","есть ли польза от книг"}}},fp="17,403,29.547.0,18.488.0,51.220.0,21.232.0,36.190.0,45.242.0,42.202.0,31.193.0"}
P.entries["quest:58"] = {n="Ночной Дозор",s="Это последнее поручение командира Алтеи Чернодрев направляет искателей приключений из Альянса в склепы восточной части Кладбища Вороньего Холма. Поскольку Ночной Дозор растянут в обороне Темнолесья, истребить кишащих разносчиков чумы в гробницы должны войти посторонние. Это завершение прямой военной кампании городской стражи против нашествия нежити.",h="Это последнее поручение командира Алтеи Чернодрев направляет искателей приключений из Альянса в склепы...",kw={"althea ebonlocke","darkshire","duskwood","ghouls","mausoleum","night watch","plague spreaders","raven hill","undead","алтея чернодрев","темнолесье","сумеречный лес","вурдалаки","мавзолей","ночной дозор","разносчики чумы","вороний холм","нежить"},ang={["class:Paladin"]="Охваченные чумой склепы Вороньего Холма — нечестивая насмешка над священными погребальными обрядами, поэтому очищение его крипт — важный долг для служителей Света.",["class:Priest"]="Мерзкая зараза, распространяемая вурдалаками в восточном мавзолее, бросает вызов святости Света и требует духовного и телесного очищения.",["faction:Alliance"]="Пока королевская корона в Штормграде игнорирует мольбы Сумеречного леса, герои Альянса должны сами вступиться, чтобы спасти верных жителей от нашествия нежити."},sec={{t="Отчаянный рубеж",b="Темнолесье почти полностью изолировано: Штормград его бросил, и оно полагается лишь на собственное ополчение — Ночной Дозор. Командир Алтея Чернодрев истратила скудные силы лишь на охрану перекрестка, периметра города и путей снабжения. Поскольку неупокоенные множатся по всему Сумеречному лесу, командиру остается лишь поручить странствующим героям вести борьбу прямо в сумрачные глубины Вороньего Холма."},{t="Очищение мавзолея",b="Восточный мавзолей на Кладбище Вороньего Холма — одно из самых опасных скоплений нежити в округе. В отличие от открытых курганов, этот каменный склеп кишит разносчиками чумы — вурдалаками, несущими губительные хвори, способные поразить живых. Уничтожение двадцати этих мерзостей дает измотанному Ночному Дозору драгоценную передышку и не позволит Темнолесью столкнуться с согласованным натиском нежити с запада."}},faq={{q="Почему Ночной Дозор посылает искателей приключений, а не своих людей?",a="Ночной Дозор растянут по всему Сумеречному лесу. Поскольку Штормград не присылает официальных войск, у командира Алтеи Чернодрев едва хватает стражи, чтобы держать периметр Темнолесья и следить за дорогами, и свободных ополченцев для зачистки глубоких укрепленных склепов вроде Вороньего Холма не остается.",al={"why help darkshire","why the night watch needs help","night watch low numbers","зачем помогать темнолесью","почему ночному дозору нужна помощь","нехватка людей в ночном дозоре"}},{q="Где находится восточный мавзолей?",a="Он расположен в восточной части Кладбища Вороньего Холма на северо-западе Сумеречного леса. Вход ведет под землю, в каменные склепы, где собираются разносчики чумы.",al={"where are plague spreaders","eastern mausoleum location","where is the mausoleum","где разносчики чумы","расположение восточного мавзолея","где мавзолей"}},{q="Чем опасны разносчики чумы?",a="Разносчики чумы — прожорливые вурдалаки, несущие губительное разложение. Если их не остановить, их мерзкая порча грозит выйти за пределы кладбища и осквернить уцелевших жителей Темнолесья.",al={"why kill plague spreaders","what are plague spreaders","зачем убивать разносчиков чумы","кто такие разносчики чумы"}},{q="Кто такая командир Алтея Чернодрев?",a="Алтея Чернодрев — командир и предводительница Ночного Дозора, а также родственница градоначальника Темнолесья, лорда Элло Чернодрева. Она руководит обороной Сумеречного леса из Темнолесья.",al={"who is althea","commander ebonlocke","who leads the night watch","кто такая алтея","командир чернодрев","кто возглавляет ночной дозор"}},{q="Положит ли выполнение этой цепочки конец угрозе нежити в Сумеречном лесу?",a="Нет. Хотя сокращение числа тварей в мавзолее ослабляет давление на Темнолесье, Вороний Холм по-прежнему кишит нежитью, а более темные силы по всему Сумеречному лесу продолжают пробуждать мертвых.",al={"is raven hill saved","is darkshire safe now","спасен ли вороний холм","безопасно ли теперь темнолесье"}},{q="Как это задание вписывается в цепочку Ночного Дозора?",a="Это третья и последняя глава военной серии командира Чернодрев «Ночной Дозор»: от открытых дорог к окраинам кладбища и, наконец, в глубь мавзолея.",al={"what chain is this","is this the last night watch quest","что это за цепочка","последнее ли это задание ночного дозора"}}},fp="15,358,20.458.0,21.438.0,68.281.0,39.175.0,42.187.0,34.190.0,61.180.0,49.193.0"}
P.entries["quest:5881"] = {n="Смена караула",s="«Смена караула» — курьерское задание Орды, которое поручают искателям приключений, отдыхающим в Приюте у Солнечного Камня. Землепряд Маггран отправляет вас на юг, к границе Степей, с приказом сменить измотанного часового у Великого Подъемника.",h="«Смена караула» — курьерское задание Орды, которое поручают искателям приключений, отдыхающим в Приюте у...",kw={"calling in the reserves","great lift","grish longrunner","maggran earthbinder","stonetalon mountains","sun rock retreat","the barrens","thousand needles","смена караула","великий подъемник","гриш выносливый гонец","землепряд маггран","когтистые горы","приют у солнечного камня","степи","тысяча игл"},ang={["faction:Horde"]="Это задание показывает, как командиры Орды управляют войсками на границе Калимдора, сменяя часовых, чтобы поддерживать боевой дух и надежность постов.",["race:Tauren"]="Помощь в смене часовых у Великого Подъемника поддерживает важный путь, который ведет с юга Калимдора к обширным землям Громового Утеса."},sec={{t="Долгожданная смена",b="Даже в эпоху относительного благополучия после Третьей войны содержание гарнизонов в центральном Калимдоре испытывает ресурсы Орды. В Приюте у Солнечного Камня в Когтистых горах Землепряд Маггран ведает снабжением и благополучием войск. Понимая, что даже опытные солдаты выбиваются из сил от бесконечных караулов, Маггран посылает на юг, к Великому Подъемнику, письмо о переводе: там далеко от дома несет стражу молодой часовой Гриш Выносливый Гонец."},{t="Наблюдение за Подъемником",b="Великий Подъемник — единственная инженерная артерия, соединяющая высокие плато южных Степей с продуваемыми ветрами каньонами Тысячи Игл. Передав письмо Гришу, вы избавляете его от одинокого и монотонного дежурства у механизмов подъемника: он наконец сможет вернуться к семье, а на его место встанут свежие силы."}},faq={{q="Кто дает это задание?",a="Землепряд Маггран дает задание в Приюте у Солнечного Камня, расположенном высоко в Когтистых горах.",al={"quest giver","where to get calling in the reserves","maggran earthbinder location","кто дает задание","где взять смена караула","где находится землепряд маггран"}},{q="Куда доставить письмо Магграна?",a="Вы должны отнести Письмо Магграна о вызове подкрепления на юг через Степи к Великому Подъемнику — огромному деревянному лифту на границе, с которого открывается вид на Тысячу Игл.",al={"grish longrunner location","where is grish","where is the great lift","где находится гриш выносливый гонец","где гриш","где великий подъемник"}},{q="Почему Гришу Выносливому Гонцу нужна смена?",a="Гриш долгое время нес службу в одиночку, охраняя механизмы подъемника. Некоторое время назад он подал официальную просьбу о смене, чтобы отправиться домой и навестить семью.",al={"grish backstory","why grish leaves","great lift sentry duty","история гриша","почему гриш уходит","служба часового у великого подъемника"}},{q="Нужно ли в этом задании сражаться?",a="Сражаться не нужно. Это чисто посыльное задание, которое направляет путников на юг, к Тысяче Игл.",al={"do i have to fight","peaceful quest","courier task","нужно ли драться","мирное задание","курьерское задание"}},{q="Репутация какой фракции повышается за выполнение?",a="Доставка письма Гришу повышает репутацию у Громового Утеса, что отражает присутствие тауренов и их управление этим путем.",al={"rep reward","what rep does this give","thunder bluff rep","награда репутацией","какая репутация","репутация громовой утес"}},{q="Куда ведет это задание дальше?",a="Доставка приводит вас прямо на вершину Великого Подъемника, откуда можно спуститься на лифтах в каньоны Тысячи Игл и исследовать другие аванпосты Орды.",al={"next quest","where to go after","thousand needles breadcrumb","следующее задание","куда идти дальше","тысяча игл"}}},fp="23,234,21.467.0,17.366.0,22.102.0,36.185.0,38.180.0,44.111.0,52.134.0,32.174.0"}
P.entries["quest:59"] = {n="Броня из кожи и ткани",s="«Броня из кожи и ткани» — поручение стражника Томаса у восточного моста в Элвиннском лесу. Впечатленный службой искателя приключений, Томас выдает официальный знак брони, который можно обменять у местной мастерицы Сары Тимберлейн. Задание отправляет новобранцев дальше на восток, на Лесопилку Восточной долины, за снаряжением для защиты королевства.",h="«Броня из кожи и ткани» — поручение стражника Томаса у восточного моста в Элвиннском лесу.",kw={"armor marker","cloth and leather armor","eastvale","elwynn forest","guard thomas","logging camp","sara timberlain","stormwind army","знак брони","броня из кожи и ткани","восточная долина","элвиннский лес","стражник томас","лесопилка","сара тимберлейн","армия штормграда"},ang={["faction:Alliance"]="Снаряжение защитников по местным договорам показывает, как сельские общины Элвинна поддерживают работу Альянса, несмотря на политический паралич в столице.",["profession:Tailoring"]="Заказ Сары Тимберлейн от армии показывает, что работа с тканью — важное, официально поддерживаемое военное ремесло королевства.",["race:Human"]="Служба стражнику Томасу и торговля с Сарой Тимберлейн отражают общие гражданские связи, на которых держатся небольшие хутора Элвиннского леса."},sec={{t="Знак стражника",b="Стражник Томас несет дозор у восточной переправы через реку в Элвиннском лесу, удерживая границу от враждебных мурлоков и бродячих гноллов. Ценя усилия умелых путников, помогающих его одинокому посту, он выдает официальный Знак брони Штормграда, а не отдает снаряжение из своих скудных полевых запасов. Этот знак служит военным требованием-ваучером и официально подтверждает заслуги его владельца перед короной."},{t="Ткач Восточной долины",b="К востоку за мостом лежит Лесопилка Восточной долины — главное лесозаготовительное предприятие Элвинна. Работая в поселении, Сара Тимберлейн имеет официальный заказ от Армии Штормграда на изготовление ткани и кожаного снаряжения. Поскольку центральные оружейные королевства перегружены и истощены, местные мастера вроде Сары жизненно важны для снаряжения войск и вспомогательных разведчиков на границе."}},faq={{q="Что такое Знак брони Штормграда?",a="Это официальный военный ордер на снабжение, который выдают офицеры вроде стражника Томаса. Вместо того чтобы хранить громоздкие комплекты брони на отдаленных постах, стражники носят знаки, позволяющие доверенным новобранцам получать подогнанную броню у гражданских мастеров, работающих по заказу.",al={"armor marker","stormwind voucher","what is the marker","знак брони","ордер штормграда","что за знак"}},{q="Кто такая Сара Тимберлейн?",a="Сара Тимберлейн — портниха и ремесленница, живущая на Лесопилке Восточной долины. Она заключила с Армией Штормграда договор на изготовление снаряжения из ткани и кожи для служащих королевства и допущенных вспомогательных бойцов.",al={"sara timberlain","eastvale tailor","who makes the armor","сара тимберлейн","портниха восточной долины","кто делает броню"}},{q="Где находится Лесопилка Восточной долины?",a="Лесопилка Восточной долины находится на дальнем востоке Элвиннского леса. От поста стражника Томаса у речного моста идите по дороге на восток, в лесистую долину, где дровосеки заготавливают древесину для королевства.",al={"eastvale location","where is eastvale","how to get to timberlain","где восточная долина","как добраться до восточной долины","как найти тимберлейн"}},{q="Почему стражник Томас отправляет искателей приключений в Восточную долину?",a="У Томаса на речной заставе нет запаса готового снаряжения. Поэтому он награждает за храбрость, отправляя новобранцев к Саре Тимберлейн: так путники идут в Восточную долину и получают надежную защиту для обороны Элвинна.",al={"why guard thomas marker","thomas purpose","why eastvale","зачем знак стражника томаса","роль томаса","зачем восточная долина"}},{q="Почему армия полагается на местных портных в снабжении?",a="Поскольку король Вариан Ринн пропал, а войска Штормграда рассеяны из-за действий Братства Справедливости и диких зверей, местные оборонительные посты сильно зависят от наемных региональных мастеров, поддерживающих снабжение.",al={"stormwind supply problems","why local artisan","army logistics","проблемы снабжения штормграда","зачем местные мастера","снабжение армии"}},{q="От кого защищается стражник Томас?",a="Стражник Томас следит за восточной границей Элвиннского леса и охраняет мост от набегов речных мурлоков, бродячих зверей и опасных диких земель у Красногорья.",al={"guard thomas enemies","threats at bridge","eastern elwynn threats","враги стражника томаса","угрозы у моста","угрозы восточного элвинна"}}},fp="23,360,15.429.0,22.402.0,33.259.0,23.223.0,35.202.0,51.242.0,54.211.0,38.202.0"}
P.entries["quest:590"] = {n="Выгодная сделка",s="«Выгодная сделка» — столкновение с Кальвином Монтеччи в Могильнике. Пообещав богатство и предложив работу только что очнувшимся Отрекшимся, хитрый разбойник раскрывает свои истинные намерения, когда у него требуют плату.",h="«Выгодная сделка» — столкновение с Кальвином Монтеччи в Могильнике.",kw={"a rogue's deal","brawl","calvin montague","deathknell","forsaken rogue","swindle","tirisfal glades","выгодная сделка","драка","кальвин монтеччи","могильник","отрекшийся разбойник","обман","тирисфальские леса"},ang={["class:Rogue"]="Столкновение с Кальвином Монтеччи сразу учит молодых разбойников профессиональной опасности: никому не доверяйте, следите за кошельком и не позволяйте другому проходимцу уйти с вашей долей.",["race:Undead"]="Пробуждение в Могильнике быстро доказывает, что смерть не лишает людей мелких пороков: Отрекшиеся карманники так же охотно обманывают своих, как живые бандиты."},sec={{t="Бесчестное обещание",b="Кальвин Монтеччи слоняется возле склепов Могильника и предлагает легкую на вид работу только что восставшим Отрекшимся. Заявляя, что за доставку письма можно хорошо заработать, Монтеччи посылает неопытных искателей приключений навстречу опасности. Но когда поручение выполнено, Монтеччи удобно забывает об обещанной плате и притворяется, что ни о какой договоренности или долге не знает."},{t="Цена обещания",b="Когда от него требуют сдержать слово, Монтеччи показывает свое истинное лицо. Вместо того чтобы расстаться с серебром, он достает оружие, рассчитывая легко расправиться с неопытным новичком. Вколотив в разбойника разум, вы вынуждаете его уступить. Крепко избитый, он выкладывает часть монет и свободно признается, что солгал о плате лишь потому, что думал, что ему это сойдет с рук."}},faq={{q="Почему Кальвин Монтеччи нападает, когда у него просят плату?",a="Кальвин Монтеччи — беспринципный разбойник, который и не собирался делиться деньгами. Когда ему напоминают о нарушенном обещании, он пытается навсегда заставить своего напарника замолчать, а не заплатить, полагая, что только что восставший Отрекшийся — легкая добыча.",al={"why calvin fight","calvin montague hostile","why rogue attacks","почему кальвин дерется","кальвин монтеччи враждебен","почему разбойник нападает"}},{q="Где происходит это столкновение?",a="Столкновение происходит прямо в Могильнике — разрушенной деревне на юго-западе Тирисфальских лесов, где впервые просыпаются только что восставшие Отрекшиеся.",al={"where is calvin montague","calvin montague location","where is rogue's deal","где кальвин монтеччи","местонахождение кальвина монтеччи","где выгодная сделка"}},{q="Платит ли Кальвин Монтеччи то, что обещал?",a="Нет. Побежденный в бою, Кальвин сдается и отдает немного монет, но признает, что это гораздо меньше обещанного, ведь с самого начала он солгал о сумме.",al={"calvin reward","does calvin pay","did he lie about coin","награда кальвина","платит ли кальвин","солгал ли о деньгах"}},{q="Как открывается это второе задание?",a="Выполнив первое поручение по доставке для Кальвина Монтеччи, вернитесь и снова поговорите с ним, потребовав обещанные деньги. Если обвинить его в обмане, бой начнется сразу.",al={"how to get part 2","unlock rogue deal fight","secret rogue quest","как получить вторую часть","открыть бой выгодная сделка","тайное задание разбойника"}},{q="Погибает ли Кальвин Монтеччи, когда его побеждают?",a="Нет. Монтеччи сдается до смертельного удара, рассыпается в похвалах вашему боевому мастерству и неохотно открывает кошель, чтобы спасти свою шкуру.",al={"did i kill calvin","is calvin dead","calvin surrender","убил ли я кальвина","мертв ли кальвин","кальвин сдается"}},{q="Какой урок эта встреча дает новым Отрекшимся?",a="Это ранний практический урок суровой жизни Отрекшихся: честь среди нежити редка, слова ничего не стоят, а уважение завоевывается только силой оружия.",al={"what is the point of rogue deal","lore behind rogue's deal","в чем смысл выгодной сделки","предания выгодной сделки"}}},fp="14,216,22.368.0,16.390.1,55.244.1,41.145.0,51.177.1,33.183.1,39.153.1,54.183.0"}
P.entries["quest:5921"] = {n="Лунная поляна",s="Лунная поляна — вводный обряд посвящения для юных друидов-ночных эльфов, которые учатся общаться со священными землями Калимдора. Под руководством Матренгила Медвежьей Лапы в Дарнассе новички изучают заклинание, позволяющее магически перенестись через весь мир на Лунную поляну, где их ждет Дендрит Блеск Звезд в Ночной Гавани. Это начало их духовного пути к овладению силой облика медведя.",h="Лунная поляна — вводный обряд посвящения для юных друидов-ночных эльфов, которые учатся общаться со...",kw={"bear","cenarion","dendrite","mathrengyl","moonglade","nighthaven","remulos","starblaze","teleport","медведь","кенарий","дендрит","матренгил","лунная поляна","ночная гавань","ремулос","блеск звезд","телепорт"},ang={["class:Druid"]="Это путешествие — ваше пробуждение к мировому наследию друидов, дающее вам вечную связь со спокойным сердцем Круга Кенария.",["faction:Alliance"]="Хотя Дарнасс отстаивает интересы Альянса, ступив на Лунную поляну, друиды-ночные эльфы вспоминают о более древнем и высоком призвании, которое выше мирских фракций.",["race:NightElf"]="Покидая ветви Тельдрассила ради древней Лунной поляны, юные кальдораи напрямую соединяются с землей предков, сохраненной со времен до Великого Раскола."},sec={{t="Священное убежище",b="Лунная поляна отличается от остального Азерота: это древнее святилище, посвященное учению Кенария. Под бдительной опекой Хранителя Ремулоса ее тихие рощи дарят покой и глубокое единение с природой. Для юного друида научиться переносить свой дух через земли на Лунную поляну с помощью заклинания телепортации — важнейший шаг: он дает постоянный доступ к средоточию друидической мудрости, как бы далеко ни находился смертный."},{t="Политика Круга",b="Хотя Лунная поляна открыта для всех, кто идет путем дикой природы, напряжение не обошло и ее. Растущий раскол разделяет верховного друида Фэндрала Оленьего Шлема в Дарнассе и Хранителя Ремулоса на Лунной поляне из-за вопроса опеки над природой и создания Тельдрассила. Несмотря на эти философские разногласия в Круге Кенария, юных послушников по-прежнему безоговорочно принимают в Ночной Гавани для священных занятий."},{t="Путь медведя",b="Прибытие в Ночную Гавань приводит новичка к Дендриту Блеску Звезд, старейшине, которому поручено наставлять птенцов на путях Когтя. Прежде чем посвященный сможет принять мантию медведя, он должен проникнуться его взглядом на мир: выносливостью, яростью и непреклонной защитой дикой природы. Блеск Звезд принимает каждого нового ученика с благоговением перед Отцом Кенарием, начиная испытания Великого Духа Медведя."}},faq={{q="Почему друиды учатся телепортироваться на Лунную поляну?",a="Телепортация на Лунную поляну напрямую связывает друида со средоточием его ордена. Поскольку обучение, общение с духами и высокий совет проходят в Ночной Гавани, мгновенный духовный путь гарантирует, что каждый последователь сможет вернуться, чтобы учиться и восполнять духовные силы.",al={"why teleport moonglade","teleport moonglade purpose","why go to moonglade","зачем телепорт на лунную поляну","цель телепорта на лунную поляну","зачем идти на лунную поляну"}},{q="Кто такой Дендрит Блеск Звезд?",a="Дендрит Блеск Звезд — старейшина-друид, который находится на верхнем этаже главного дома в Ночной Гавани. Он наставляет посвященных, прибывающих на Лунную поляну, и начинает их испытания по овладению взглядом животных — начиная с первобытного духа медведя.",al={"dendrite starblaze role","who is dendrite","dendrite starblaze","роль дендрита блеск звезд","кто такой дендрит","дендрит блеск звезд"}},{q="Какие разногласия существуют между Фэндралом Оленьим Шлемом и Хранителем Ремулосом?",a="Верховный друид Фэндрал Олений Шлем возглавил посадку Тельдрассила без благословения Аспектов драконов, избрав для ночных эльфов более агрессивную, националистическую позицию. Хранитель Ремулос и традиционалисты на Лунной поляне остаются верны древним нейтральным путям Кенария, что порождает идеологические трения внутри Круга Кенария.",al={"staghelm remulos tension","fandral vs remulos","circle division","олений шлем ремулос разногласия","фэндрал против ремулоса","раскол круга"}},{q="Могут ли друиды Орды тоже посещать Лунную поляну?",a="Да. Лунная поляна — нейтральное убежище под защитой Хранителя Ремулоса и Круга Кенария. Друиды-ночные эльфы и таурены равно приветствуются в Ночной Гавани, чтобы вместе изучать пути природы, отложив вражду фракций под миром Кенария.",al={"horde moonglade","are tauren allowed in moonglade","is moonglade neutral","орда лунная поляна","пускают ли тауренов на лунную поляну","нейтральна ли лунная поляна"}},{q="Что происходит после встречи с Дендритом Блеском Звезд?",a="Когда вы доложите Дендриту Блеску Звезд, он проведет вас к ритуальному испытанию Великого Духа Медведя. Это духовное противостояние проверяет вашу решимость и понимание, прежде чем вам позволят обуздать необузданную силу медведя.",al={"after moonglade quest","next step bear form","bear quest next","после задания лунной поляны","следующий шаг облик медведя","следующее задание медведя"}},{q="Где в Ночной Гавани находится Дендрит?",a="Дендрит Блеск Звезд находится в главном доме ночных эльфов у центра Ночной Гавани и несет стражу на балконе второго этажа, с которого виден поселок.",al={"find dendrite starblaze","dendrite starblaze location","where is dendrite","найти дендрита блеск звезд","где находится дендрит блеск звезд","где дендрит"}}},fp="9,404,15.446.0,22.424.0,20.412.0,45.299.0,26.243.0,64.338.0,41.247.0,47.229.0,40.160.0"}
P.entries["quest:5922"] = {n="Лунная поляна",s="Это задание знакомит юного друида-тауренов с Лунной поляной, священным убежищем друидизма Кенария. Под руководством Тюрака Рунического Тотема в Громовом Утесе посвященный учится пересекать бодрствующий мир, чтобы напрямую общаться с древними хранителями природы.",h="Это задание знакомит юного друида-тауренов с Лунной поляной, священным убежищем друидизма Кенария.",kw={"bear form","cenarius","dendrite starblaze","moonglade","nighthaven","remulos","teleport moonglade","turak runetotem","облик медведя","кенарий","дендрит блеск звезд","лунная поляна","ночная гавань","ремулос","телепорт на лунную поляну","тюрак рунический тотем"},ang={["class:Druid"]="Этот обряд посвящения соединяет традиционные племенные верования с более широкими заветами Круга Кенария и открывает путь к древним обликам перевоплощения.",["faction:Horde"]="Хотя напряжение сохраняется по всему Калимдору, друиды Орды находят в Лунной поляне одно из редких мест в мире, где они могут мирно встретиться со своими собратьями — ночными эльфами.",["race:Tauren"]="Для посвященных тауренов прибытие на Лунную поляну — глубокое пробуждение: доказательство того, что их древние узы с Матерью-Землей глубоко созвучны учению Кенария."},sec={{t="Священное убежище вне фракций",b="Лунная поляна стоит в стороне от бурной политики Калимдора. Под сенью первобытных ветвей, под присмотром Хранителя Ремулоса, сына Кенария, эта древняя долина — нейтральное убежище для всех, кто идет путем природы. Будь то ночной эльф или таурен, любой друид, входящий в Ночную Гавань, делает это как равный под вечной мантией Круга Кенария."},{t="Прыжок через Калимдор",b="Чтобы помочь вашему духовному и боевому развитию, Тюрак Рунический Тотем обучает вас особому заклинанию перемещения, связанному с самой долиной. Призвав мистическую связь между друидами и миром природы, вы за мгновение преодолеваете сотни лиг. Это убежище станет и местом учебы, и неизменным приютом на всем вашем пути."},{t="Пробуждение медведя",b="Прибыв в Ночную Гавань, вы встречаете Дендрита Блеска Звезд, старейшину-друида из ночных эльфов, ожидающего новых учеников. Под его руководством начинается первое настоящее испытание вашего призвания: поиск взгляда медведя. Чтобы принять пути Когтя, нужно доказать силу, смелость и равновесие перед Великим Духом Медведя."}},faq={{q="Почему таурены могут посещать убежище ночных эльфов, такое как Лунная поляна?",a="Лунная поляна — суверенная священная земля под защитой Круга Кенария, которой руководит Хранитель Ремулос. В ее пределах преданность природе и Кенарию полностью берет верх над конфликтом фракций Орды и Альянса, позволяя друидам-тауренам и ночным эльфам мирно учиться и жить бок о бок.",al={"why tauren in moonglade","horde allowed in moonglade","is moonglade neutral","почему таурены на лунной поляне","орда на лунной поляне","нейтральна ли лунная поляна"}},{q="Кто такой Дендрит Блеск Звезд?",a="Дендрит Блеск Звезд — старейшина-друид из ночных эльфов, живущий в поселении Ночная Гавань. Он наставляет вновь прибывших посвященных обеих рас, проводя их ранние испытания, пока они настраиваются на древние звериные аспекты.",al={"dendrite starblaze","who is dendrite","night elf quest giver","дендрит блеск звезд","кто такой дендрит","персонаж, выдающий задания у ночных эльфов"}},{q="Кто такой Хранитель Ремулос?",a="Хранитель Ремулос — могучий Хранитель Рощи и сын полубога Кенария. Он верховный страж Лунной поляны: охраняет священные курганы, где спят друиды в спячке, и следит за тем, чтобы святость долины оставалась неприкосновенной.",al={"keeper remulos","remulos moonglade","who protects moonglade","хранитель ремулос","ремулос лунная поляна","кто защищает лунную поляну"}},{q="Что происходит после прибытия на Лунную поляну?",a="Разговор с Дендритом Блеском Звезд начинает ваше испытание Великого Духа Медведя. Он отправляет вас в обитель духа на северо-западе Лунной поляны, чтобы постичь силу тела и силу сердца — первый шаг к тайнам облика медведя.",al={"what do i do next","bear questline","after moonglade quest","что делать дальше","цепочка заданий медведя","после задания лунной поляны"}},{q="Как работает телепортация на Лунную поляну с точки зрения предания?",a="Друиды сплетают природные энергии лей-линий и свою духовную связь с Кругом Кенария, чтобы мгновенно преодолеть расстояние между местом, где они стоят, и сердцем Лунной поляны. Это духовный якорь, позволяющий вернуться за наставлением и утешением, когда бы их ни призвали.",al={"moonglade teleport lore","teleport spell druid","предание телепорт лунная поляна","заклинание телепорта друида"}},{q="Где находится Тюрак Рунический Тотем?",a="Тюрак Рунический Тотем живет на Вершине Старейшин в Громовом Утесе: он наставляет молодых тауренов, внявших зову дикой природы, прежде чем отправить их дальше, на Лунную поляну.",al={"turak runetotem location","where is turak","где тюрак рунический тотем","где тюрак"}}},fp="9,253,29.367.0,24.339.0,18.320.1,54.310.0,26.218.0,22.251.0,38.257.0,44.275.0,33.155.0"}
P.entries["quest:5923"] = {n="Зов Природы",s="Зов Природы — момент, когда ученик-друид из ночных эльфов привлекает внимание старшего руководства Круга Кенария. Вызванный в Дарнасс к Матренгилу Медвежьей Лапе, юный посвященный вступает на священный путь к овладению первым звериным аспектом — медведем.",h="Зов Природы — момент, когда ученик-друид из ночных эльфов привлекает внимание старшего руководства Круга...",kw={"bear form","cenarion enclave","darnassus","denatharion","druid quest","fandral staghelm","heeding the call","kal","mathrengyl bearwalker","theridran","облик медведя","анклав кенария","дарнасс","денатарион","задание друида","фэндрал олений шлем","зов природы","кал","матренгил медвежья лапа","теридран"},ang={["class:Druid"]="Это задание — ваш официальный переход от простого новичка, плетущего заклинания корней и гнева, к настоящему оборотню, постигающему духов Калимдора.",["faction:Alliance"]="Возможность взять это задание у Теридрана в Штормграде показывает растущее согласие между кальдораями Тельдрассила и их восточными союзниками-людьми.",["race:NightElf"]="Следуя вызову, вы попадаете в Анклав Кенария в Дарнассе, чтя тысячелетние традиции кальдораев под бдительным взором круга Фэндрала Оленьего Шлема."},sec={{t="Вызов из Анклава",b="Начинающие друиды, оттачивающие мастерство по всему Тельдрассилу или учащиеся в далеких краях, например в Штормграде, со временем получают личный вызов. Наставники, такие как Кал в Доланааре, Денатарион в Дарнассе или Теридран за Великим морем, передают весть, что Матренгил Медвежья Лапа желает лично руководить их обучением. Как прямой помощник верховного друида Фэндрала Оленьего Шлема, Матренгил — один из самых уважаемых и сведущих наставников среди ночных эльфов, и его внимание — безошибочный знак того, что ученик готов к настоящим испытаниям."},{t="Путь медведя",b="Встреча с Матренгилом на верхнем уровне высокой резиденции Фэндрала Оленьего Шлема в Анклаве Кенария открывает дверь к более глубоким тайнам. Чтобы должным образом служить природе, друид должен научиться воплощать ее живых существ, а не просто наблюдать за ними. Матренгил встречает кандидатов вестью о том, что их первым великим делом станет обретение силы, выносливости и духа медведя — путь, который уведет их далеко за пределы Тельдрассила, на священные земли предков."}},faq={{q="Кто посылает меня на это задание?",a="Этот вызов можно получить у нескольких учителей-друидов, набрав достаточно опыта: у Кала в Доланааре, Денатариона в Дарнассе или Теридрана в квартале Парк в Штормграде.",al={"quest giver","who starts this","where do i get this quest","персонаж, выдающий задания","кто дает это задание","где взять это задание"}},{q="Кто такой Матренгил Медвежья Лапа?",a="Матренгил Медвежья Лапа — старший друид из ночных эльфов и прямой помощник верховного друида Фэндрала Оленьего Шлема. Он живет в Анклаве Кенария в Дарнассе и служит выдающимся наставником для посвященных, стремящихся овладеть звериными обликами.",al={"mathrengyl","who is mathrengyl","bearwalker","матренгил","кто такой матренгил","медвежья лапа"}},{q="Где найти Матренгила Медвежью Лапу в Дарнассе?",a="Он находится в Анклаве Кенария, в северо-западном квартале Дарнасса. Вы найдете его на втором этаже большого живого дерева, служащего обителью верховного друида Фэндрала Оленьего Шлема.",al={"mathrengyl location","where is mathrengyl","cenarion enclave location","где матренгил","где найти матренгила","расположение анклава кенария"}},{q="К какому обучению ведет это задание?",a="Доклад Матренгилу начинает священное испытание Облика медведя. Он направит вас через Калимдор в священное убежище Лунная поляна, чтобы постичь силу тела и сердца, необходимые для общения с Великим Духом Медведя.",al={"what comes next","what do i get","next quest","что дальше","что я получу","следующее задание"}},{q="Почему я могу получить это задание в Штормграде?",a="Посланники и друиды ночных эльфов, такие как Теридран, поддерживают убежище в Парке Штормграда, чтобы помогать союзникам по Альянсу. Если юный друид странствует за морем в Элвиннском лесу, Теридран может передать вызов домой, в Тельдрассил.",al={"stormwind quest","theridran","can i get this in stormwind","задание в штормграде","теридран","можно ли получить это в штормграде"}},{q="Почему облик медведя — первый преподаваемый звериный аспект?",a="Друиды считают, что природе нужны и защитники, и хранители. Медведь воплощает несокрушимую стойкость, физическую мощь и смелость защищать равновесие от вреда, что делает его основополагающим аспектом для выживания в опасных испытаниях дикой природы.",al={"why bear form","druid bear lore","почему облик медведя","предание друида медведя"}}},fp="16,278,26.560.0,20.479.0,27.197.0,29.235.0,52.204.0,38.222.0,38.246.0,52.241.0"}
P.entries["quest:5926"] = {n="Зов Природы",s="«Зов Природы» — вызов начинающего друида на Вершину Старейшин в Громовом Утесе для углубленного личного обучения. Призыв передают хозяйки таверн и сородичи в поселениях Орды, и он направляет будущих оборотней к Тюраку Руническому Тотему. Эта встреча начинает священные испытания, необходимые для овладения обликом и духом медведя.",h="«Зов Природы» — вызов начинающего друида на Вершину Старейшин в Громовом Утесе для углубленного личного...",kw={"bear form","bloodhoof village","cenarion circle","druid","elder rise","gennia runetotem","heeding the call","thunder bluff","turak runetotem","облик медведя","деревня кровавого копыта","круг кенария","друид","вершина старейшин","геннией рунический тотем","зов природы","громовой утес","тюрак рунический тотем"},ang={["class:Druid"]="Это задание — важный первый шаг на пути к овладению звериными обликами, начало священного пути к обретению духа и стойкости медведя.",["faction:Horde"]="Хозяйки таверн в землях и орков, и тауренов помогают будущим друидам услышать свое призвание, укрепляя важную связь Орды с дикой землей.",["race:Tauren"]="Для тауренов обучение у Тюрака на Вершине Старейшин подтверждает их глубокую древнюю связь с Кругом Кенария и дикими духами Калимдора."},sec={{t="Слово в таверне",b="Вести быстро расходятся по равнинам Мулгора и пыльным улицам Оргриммара. Услышите ли вы их от Хозяйки таверны Гришки среди орков, от Хозяйки таверны Палы в Громовом Утесе или от Геннии Рунический Тотем в Деревне Кровавого Копыта, смысл один: Тюрак Рунический Тотем заметил ваши первые успехи. Круг Кенария не призывает последователей без причины, и это приглашение означает, что ваши дни простого сбора трав и базового плетения заклинаний заслужили вам более глубокую связь с дикими духами природы."},{t="Круг на Вершине Старейшин",b="Тюрак Рунический Тотем — помощник верховного друида Хамуула Рунического Тотема. Он направляет молодых тауренов к их древнему долгу в большом шатре Круга Кенария на Вершине Старейшин. Принимая посвящаемых к более широкому пониманию наследия Кенария, Тюрак учит, что животные и растения — одновременно союзники и священный долг. Встреча с ним — первый порог обряда: выход за рамки простого наставничества к испытаниям тела и духа, необходимым для прямой связи с Великим Духом Медведя."}},faq={{q="Кто посылает меня поговорить с Тюраком Руническим Тотемом?",a="Призыв могут передать несколько человек: Генн  Рунический Тотем в Деревне Кровавого Копыта, Хозяйка таверны Пала в Громовом Утесе или Хозяйка таверны Гришка в Оргриммаре. Каждый получил весть, что Тюрак хочет лично руководить вашим обучением.",al={"who gives heeding the call","quest giver heeding the call","where do i start heeding the call","кто дает зов природы","персонаж, выдающий задание зов природы","где начать зов природы"}},{q="Где найти Тюрака Рунический Тотем?",a="Тюрак живет на Вершине Старейшин в Громовом Утесе. Его дом — в заметном шатре Круга Кенария, рядом с другими друидами-наставниками города.",al={"turak runetotem location","where is turak","how to find turak","тюрак рунический тотем местонахождение","где тюрак","как найти тюрака"}},{q="Почему этот призыв так важен для молодых друидов?",a="Этот призыв начинает ваши официальные испытания оборотня. Тюрак Рунический Тотем направляет вас на священную землю Лунной поляны, чтобы вы изучили путь медведя и обрели свой первый звериный облик.",al={"why do i need turak","what is this quest for","druid level 10 quest horde","зачем мне тюрак","для чего это задание","задание друида 10 уровня орда"}},{q="Кто такой Тюрак Рунический Тотем в иерархии Кенария?",a="Тюрак — уважаемый таурен-друид и доверенный помощник верховного друида Хамуула Рунического Тотема. Он известен терпением и мудростью в обучении молодых посвященных равновесию природы.",al={"who is turak runetotem","turak lore","кто такой тюрак рунический тотем","тюрак предания"}},{q="Могут ли другие классы взять это задание?",a="Нет. Это задание предлагают только друидам, достигшим десятого уровня опыта, как обряд посвящения в оборотни.",al={"is heeding the call druid only","can shaman do this quest","зов природы только для друидов","может ли шаман взять это задание"}},{q="Что будет после разговора с Тюраком?",a="Тюрак принимает вас на службу Кенария и посылает на Лунную поляну, священное убежище друидов, найти Дендрита Блеска Звезд и начать общение с Великим Духом Медведя.",al={"what comes after heeding the call","next quest after turak","что после зова природы","следующее задание после тюрака"}}},fp="16,326,17.516.0,24.497.0,43.242.0,33.149.0,50.184.0,49.181.0,36.151.0,36.176.1"}
P.entries["quest:5931"] = {n="Возвращение в Дарнасс",s="Это задание отмечает возвращение начинающего друида-ночного эльфа из священных рощ Лунной поляны в Дарнасс. Пообщавшись с Великим Духом Медведя, посвящаемый докладывает Матренгилу Медвежьей Лапе в Анклаве Кенария, чтобы начать практические испытания оборотня.",h="Это задание отмечает возвращение начинающего друида-ночного эльфа из священных рощ Лунной поляны в Дарнасс.",kw={"bear spirit","bearwalker","cenarion enclave","darnassus","dendrite","mathrengyl","moonglade","shapeshifting","starblaze","дух медведя","медвежья лапа","анклав кенария","дарнасс","дендрит","матренгил","лунная поляна","оборотень","блеск звезд"},ang={["class:Druid"]="Это путешествие — важный обряд для молодых друидов, отмечающий переход от теоретической духовной связи к физическому превращению.",["race:NightElf"]="Путь между древним убежищем Лунной поляны и недавно посаженным Мировым Древом Тельдрассила отражает баланс между тысячелетним наследием кальдораев и их нынешними обязанностями."},sec={{t="Путь между убежищами",b="После общения с Великим Духом Медведя в Лунной поляне молодой друид должен преодолеть разрыв между вечными убежищами природы и неспокойным миром. Дендрит Блеск Звезд отправляет посвящаемого из Ночной Гавани в Дарнасс, поручая следующий этап обучения местным наставникам, хранящим Тельдрассил."},{t="Путь Когтя",b="Матренгил Медвежья Лапа ждет в Анклаве Кенария, охраняя природу даже там, где равновесие нарушено. Благословение Великого Духа Медведя — лишь первый шаг; Матренгил готовит посвящаемого воплотить эту свирепую древнюю мудрость в физической форме через трудные испытания тела и духа."}},faq={{q="Почему мне нужно вернуться в Дарнасс?",a="Лунная поляна дает духовную связь с Великим Духом Медведя, но ваш непосредственный наставник Матренгил Медвежья Лапа живет в Анклаве Кенария в Дарнассе. Он руководит практическими испытаниями, необходимыми для овладения новой силой.",al={"why return to darnassus","why leave moonglade","where does dendrite send me","зачем вернуться в дарнасс","зачем покидать лунную поляну","куда отправляет дендрит"}},{q="Кто такой Матренгил Медвежья Лапа?",a="Матренгил Медвежья Лапа — опытный наставник друидов из ночных эльфов в Анклаве Кенария в Дарнассе. Он специализируется на обучении молодых посвященных Пути Когтя и овладении обликом медведя.",al={"who is mathrengyl","mathrengyl bearwalker lore","bearwalker","кто такой матренгил","матренгил медвежья лапа предания","медвежья лапа"}},{q="Как вернуться в Дарнасс с Лунной поляны?",a="Мастер гиппогрифов Сильва Фил'навет в юго-западной части Ночной Гавани отправляет посвящаемых прямыми рейсами через море в Дарнасс.",al={"how to leave nighthaven","moonglade flight back","silva fil'naveth","как покинуть ночную гавань","перелет с лунной поляны назад","сильва фил'навет"}},{q="Что будет после разговора с Матренгилом?",a="Матренгил даст вам первое настоящее испытание: встретить Лунного Когтя у Камня лунных сов к востоку от Аубердина на Темных берегах и доказать, что ваши тело и дух готовы к облику медведя.",al={"next quest after back to darnassus","what comes next","следующее задание после возвращения в дарнасс","что дальше"}},{q="Что такое Путь Когтя?",a="Путь Когтя — друидическая традиция, посвященная направлению свирепости, стойкости и силы медведя, воплощаемых через общение с древними изначальными духами.",al={"path of the claw","druid claw lore","путь когтя","предания друидов о когте"}},{q="Почему Дендрит говорит о нарушенном равновесии близ Дарнасса?",a="Тельдрассил молод и не получил благословения Аспектов драконов, поэтому его ветви уязвимы для странной порчи, безумия фурболгов и наступающей тьмы, с которыми активно борются друиды Анклава Кенария.",al={"balance faltered darnassus","teldrassil corrupted","нарушено равновесие дарнасс","тельдрассил осквернен"}}},fp="17,265,29.312.0,20.320.0,37.238.0,29.197.0,46.148.0,41.199.0,29.175.0,59.205.0"}
P.entries["quest:5932"] = {n="Возвращение в Громовой Утес",s="«Возвращение в Громовой Утес» — важный обряд для молодых друидов-тауренов, возвращающихся из священных рощ Лунной поляны. Пообщавшись с Великим Духом Медведя, посвящаемый по велению Дендрита Блеска Звезд возвращается на Вершину Старейшин, чтобы продолжить обучение у Тюрака Рунический Тотем.",h="«Возвращение в Громовой Утес» — важный обряд для молодых друидов-тауренов, возвращающихся из священных рощ...",kw={"back to thunder bluff","bear form","dendrite starblaze","elder rise","great bear spirit","moonglade","nighthaven","turak runetotem","возвращение в громовой утес","облик медведя","дендрит блеск звезд","вершина старейшин","великий дух медведя","лунная поляна","ночная гавань","тюрак рунический тотем"},ang={["class:Druid"]="Этот отрезок вашего пути связывает древнее уединенное убежище Лунной поляны с продуваемыми ветрами высотами Громового Утеса и отмечает ваш рост на Пути Когтя.",["faction:Horde"]="Знания, принесенные с Лунной поляны, гарантируют, что в рядах Орды на равнинах Калимдора будут могучие защитники-оборотни.",["race:Tauren"]="Возвращение на Вершину Старейшин приносит мудрость древних духов домой, на благо и защиту ваших племен по всему Мулгору."},sec={{t="Мост между народами",b="Лунная поляна стоит вне разделения на фракции в мире смертных и служит убежищем, где ночные эльфы и таурены, владеющие магией природы, собираются как Круг Кенария. После общения с Великим Духом Медведя наставник-ночной эльф Дендрит Блеск Звезд отправляет молодого таурена к его народу. Хотя ночные эльфы часто считают тауренов птенцами в формальных учениях Кенария, Блеск Звезд охотно признает глубокую мудрость и равновесие Тюрака Рунический Тотем."},{t="Возвращение на утесы",b="Поднявшись обратно на широкие высоты Вершины Старейшин в Громовом Утесе, новичок предстает перед Тюраком Руническим Тотемом преображенным. Общение с древними тотемными духами, такими как Великий Дух Медведя, глубоко укоренено в культуре тауренов, но вступление на Путь Когтя — серьезное обязательство. Когда духовная связь установлена, Тюрак готовит друида применить обретенные силу и выносливость на деле."}},faq={{q="Почему ночной эльф учил таурена на Лунной поляне?",a="Круг Кенария нейтрален и всецело предан сохранению природы. На Лунной поляне политическая вражда между Ордой и Альянсом полностью отложена, и старейшины-ночные эльфы, такие как Дендрит Блеск Звезд, могут наставлять молодых друидов-тауренов.",al={"dendrite starblaze horde","why night elf mentor","cenarion circle tauren","дендрит блеск звезд орда","почему наставник ночной эльф","круг кенария таурен"}},{q="Кто такой Тюрак Рунический Тотем?",a="Тюрак Рунический Тотем — уважаемый таурен-друид, один из помощников Верховного друида, живущий на Вершине Старейшин в Громовом Утесе. Он руководит обучением молодых тауренов, желающих пройти путь природы и когтя, и служит важным связующим звеном с Кругом Кенария.",al={"turak runetotem role","elder rise druid leader","роль тюрака рунический тотем","глава друидов вершины старейшин"}},{q="Что молодой друид делал перед этим заданием?",a="Перед возвращением в Мулгор посвящаемый отправился на Лунную поляну, чтобы найти древнего Великого Духа Медведя и пообщаться с ним, получив его благословение и узнав духовную суть облика медведя.",al={"what came before back to thunder bluff","great bear spirit quest","что было до возвращения в громовой утес","задание великий дух медведя"}},{q="Как молодые друиды возвращаются в Громовой Утес с Лунной поляны?",a="Бантен Ветер Равнин в юго-западной части Ночной Гавани — распорядитель полетов, который особо отправляет друидов-тауренов обратно в Громовой Утес после обрядов.",al={"how to get back from moonglade","moonglade flight back","как вернуться с лунной поляны","перелет с лунной поляны назад"}},{q="Что дальше в обучении друида?",a="По возвращении Тюрак Рунический Тотем дает посвящаемому задание «Тело и дух» и отправляет на физическое испытание к Камню лунных сов на границе Степей и Мулгора, чтобы доказать, что он может обратить силу духа в настоящий звериный облик.",al={"next druid quest","after back to thunder bluff","следующее задание друида","после возвращения в громовой утес"}},{q="Почему Дендрит Блеск Звезд называет тауренов юными на пути Кенария?",a="Хотя легенды тауренов говорят о древнем общении с Кенарием на заре мира, формальное друидическое учение Кенария создавали и поддерживали ночные эльфы более десяти тысяч лет. Таурены лишь недавно вновь начали структурное обучение в Круге Кенария.",al={"are tauren new druids","tauren druid history cenarius","новые ли таурены друиды","история друидов тауренов кенарий"}}},fp="21,276,20.491.0,20.427.0,51.262.0,23.261.0,52.198.0,64.183.0,40.244.0,72.261.0"}
P.entries["quest:6"] = {n="Награда за голову Гаррика Тихокрада",s="«Награда за голову Гаррика Тихокрада» — контракт Альянса на выдачу награды, который выдает заместитель судьи Виллем в Аббатстве Североземья. Он поручает молодым рекрутам выследить известного местного вора, который из уединенной лачуги возле виноградников донимает фермеров и торговцев Элвинна.",h="«Награда за голову Гаррика Тихокрада» — контракт Альянса на выдачу награды, который выдает заместитель судьи...",kw={"bounty","cutthroat","elwynn","garrick","northshire","padfoot","thieves","vineyard","willem","награда","головорез","элвинн","гаррик","североземье","тихокрад","воры","виноградник","виллем"},ang={["class:Rogue"]="Гаррик Тихокрад дает разбойникам первое представление о том, как действуют преступники в тени Элвинна: плохо спрятанные убежища быстро находят клинки.",["faction:Alliance"]="Расправа с Гарриком Тихокрадом — одна из первых прямых услуг, которые начинающий искатель приключений из Альянса оказывает ради восстановления порядка в Королевстве Штормград.",["race:Human"]="Для людей, выросших в королевстве, избавить Североземье от головорезов вроде Тихокрада — личное дело защиты священной земли своей родины и местных фермеров."},sec={{t="Бич долины",b="Долина Североземья когда-то считалась надежным убежищем для обучения рекрутов и ухода за священными виноградниками, но недавний крах законности и порядка по всему Элвинну оставил ее беззащитной. В долину пробрались шайки воров, и головорез по имени Гаррик Тихокрад быстро встал во главе их. Уже несколько недель Гаррик и его банда грабят грузы, нападают на торговцев на дорогах и угрожают местным фермерам."},{t="Правосудие заместителя судьи Виллема",b="Стражи Штормграда заняты охраной столицы и внешних границ, поэтому местным шерифам и их помощникам приходится полагаться на добровольцев, чтобы поддерживать мир в Североземье. Заместитель судьи Виллем объявляет публичную награду за голову Гаррика, чтобы раз и навсегда избавить долину от его банды. Расправа с Тихокрадом в его ветхой лачуге к востоку от реки — первый удар по беззаконию, расползающемуся по сердцу земель людей."}},faq={{q="Кто такой Гаррик Тихокрад?",a="Гаррик Тихокрад — разбойник и головорез, орудующий в Долине Североземья. Уже несколько недель он донимает местных фермеров и устраивает засады на торговцев, собрав вокруг себя небольшую шайку головорезов, чтобы закрепиться на территории возле виноградников.",al={"garrick padfoot","who is garrick","padfoot","гаррик тихокрад","кто такой гаррик","тихокрад"}},{q="Где найти Гаррика Тихокрада?",a="Он скрывается в небольшой деревянной лачуге к востоку от Аббатства Североземья, за мостом через реку, рядом с виноградниками. Его охраняют подручные головорезы.",al={"where is garrick padfoot","garrick location","garrick shack","где гаррик тихокрад","местонахождение гаррика","лачуга гаррика"}},{q="Кто выдает награду за голову Гаррика?",a="Награду объявляет заместитель судьи Виллем, находящийся у Аббатства Североземья. Городской стражи не хватает, чтобы охранять долину, поэтому Виллем нанимает странствующих рекрутов, чтобы они привели преступника к правосудию.",al={"who gives bounty on garrick padfoot","willem bounty","кто дает награду за гаррика тихокрада","награда виллема"}},{q="Почему Штормград не посылает против него обычных солдат?",a="Армия Штормграда перегружена. Король Вариан Ринн пропал, напряжение растет по всему Элвиннскому лесу и за его пределами, и столица не может выделить опытные гарнизоны для каждого мелкого бандита, поэтому местным помощникам шерифа приходится привлекать рекрутов.",al={"why don't guards kill garrick","where are stormwind guards","почему стражи не убьют гаррика","где стражи штормграда"}},{q="Действует ли Гаррик Тихокрад в одиночку?",a="Нет. Гаррик окружил себя небольшой бандой разбойников и бандитов, которые лагерем стоят вокруг его лачуги возле виноградников Североземья и охраняют его.",al={"is garrick solo","padfoot gang","гаррик один","банда тихокрада"}},{q="Какое доказательство требует заместитель судьи Виллем?",a="Заместитель судьи Виллем требует вещественное доказательство, прежде чем выплатить деньги: вы должны принести в Аббатство Североземья отрубленную голову Гаррика Тихокрада.",al={"proof of garrick death","garricks head","доказательство смерти гаррика","голова гаррика"}}},fp="25,260,22.420.0,23.419.0,23.227.0,35.152.0,33.181.0,63.236.0,33.147.0,38.157.0"}
P.entries["quest:60"] = {n="Свечи кобольдов",s="«Свечи кобольдов» — одно из первых поручений, которое дает Вильям Пест в таверне «Гордость Льва» в Златоземье. Пест, алхимик, приехавший из своей лавки в Штормграде, ищет густой воск больших свечей, которые носят кобольды, наводнившие местные рудники Элвиннского леса. Для искателей приключений это первое знакомство с подземными вредителями, посягающими на ценные золотые жилы королевства.",h="«Свечи кобольдов» — одно из первых поручений, которое дает Вильям Пест в таверне «Гордость Льва» в Златоземье.",kw={"apothecary","candle","elwynn","fargodeep","goldshire","jasperlode","kobold","wax","william pestle","аптекарь","свеча","элвинн","подземные глубины","златоземье","яшмовая шахта","кобольд","воск","вильям пест"},ang={["faction:Alliance"]="Поскольку королевская армия ослаблена внутренними политическими раздорами и пропажей войск короны, защита местной инфраструктуры ложится на добровольцев из числа гражданских и странствующих искателей приключений.",["profession:Mining"]="Зачистка кобольдов ради их свечей приводит старателей прямо к богатейшим медным и золотым жилам Элвинна, покинутым шахтерами-людьми.",["race:Human"]="Вернуть захваченные рудники Элвинна и поставлять товары штормградским мастерам — первые обязанности юных подданных королевства."},sec={{t="Поручения аптекаря",b="Вильям Пест вместе с братом держит аптеку Песта в Торговом квартале Штормграда. При изготовлении лекарств, мазей и снадобий сырья, такого как воск, всегда не хватает. Вместо того чтобы закупать готовые свечи у городских торговцев, Пест знает, что вредители, наводнившие Элвинн, носят на лбу удивительно большие куски сала и воска — бери даром, если искатель приключений готов их снять."},{t="Рудники Элвинна",b="Кобольды полностью заполонили и Рудник Подземных Глубин к югу от Златоземья, и Яшмовую шахту на северо-востоке. Эти сопящие подземные создания ценят свои свечи превыше всего: при мерцающем свете они ходят по темным штольням, добывая золото и блестящие безделушки. Похищая эти свечи, вы не только пополняете алхимические запасы Песта, но и теснее прижимаете вредителей, душащих драгоценные рудные участки королевства."}},faq={{q="Зачем Вильяму Песту свечи кобольдов?",a="Вильям Пест с братом держит аптеку в Торговом квартале Штормграда. Вытопленное сало и воск больших свечей они используют как составляющую для печатей, мазей и различных алхимических смесей.",al={"why pestle wants candles","what are candles used for","candle wax use","зачем песту свечи","для чего нужны свечи","применение свечного воска"}},{q="Где найти большие свечи?",a="Свечи носят кобольды-рабочие, вредители и копатели, обитающие в рудниках Элвиннского леса, главным образом в туннелях Рудника Подземных Глубин к югу от Златоземья и Яшмовой шахты на востоке.",al={"where are kobold candles","candle locations","how to get large candles","где свечи кобольдов","где искать свечи","как получить большие свечи"}},{q="Почему кобольды так одержимы свечами?",a="Кобольды живут в кромешно темных подземных туннелях и при копании полагаются на небольшое пламя, привязанное к голове. Они суеверно, почти исступленно боятся темноты и яростно защищают свои свечи от всех, кто пытается их забрать.",al={"why do kobolds have candles","you no take candle meaning","kobold candle lore","почему у кобольдов свечи","не бери свечу значение","предания о свечах кобольдов"}},{q="Кто такой Вильям Пест?",a="Вильям Пест — человек, торговец и алхимик из Штормграда. Когда он не работает в своей лавке в Торговом квартале города, он отправляется в Златоземье, чтобы закупать дешевые материалы у странствующих искателей приключений.",al={"who is william pestle","william pestle lore","goldshire pestle","кто такой вильям пест","вильям пест предания","пест златоземье"}},{q="Связано ли это задание с другими бедами Элвинна?",a="Да. Нашествие в Рудник Подземных Глубин и Яшмовую шахту — серьезная экономическая угроза для Златоземья и Штормграда. Шахтеры-люди изгнаны, и очистка туннелей — один из главных приоритетов маршала Дугхана.",al={"elwynn mine problems","why are kobolds in mines","goldshire kobold threat","проблемы рудников элвинна","почему кобольды в шахтах","угроза кобольдов златоземью"}},{q="Есть ли в Элвинне другие рудники, захваченные кобольдами?",a="Рудник Подземных Глубин и Яшмовая шахта — два главных места возле Златоземья, но активность кобольдов распространяется и на берега рек леса, и на восток, к границам Красногорья.",al={"other kobold mines","elwynn mines list","другие шахты кобольдов","список рудников элвинна"}}},fp="14,393,20.450.0,19.454.0,44.223.0,36.205.0,41.253.0,22.204.0,52.216.0,56.187.0"}
P.entries["quest:6001"] = {n="Тело и дух",s="«Тело и дух» — завершающее испытание в посвящении молодого друида-ночного эльфа на путь когтя. По поручению Матренгила Медвежьей Лапы в Дарнассе неофит должен отправиться в глушь Темных берегов, призвать лунного хранителя Лунного Когтя и доказать, что обладает и внутренней стойкостью, и боевой силой, прежде чем принять облик медведя.",h="«Тело и дух» — завершающее испытание в посвящении молодого друида-ночного эльфа на путь когтя.",kw={"auberdine","bear form","body and heart","cenarion moondust","druid of the claw","lunaclaw","mathrengyl bearwalker","moonkin stone","аубердин","облик медведя","тело и дух","лунная пыль кенария","друид когтя","лунный коготь","матренгил медвежья лапа","лунный камень"},ang={["class:Druid"]="Этот обряд — главный рубеж начального друидического обучения: он превращает новичка-заклинателя в оборотня-защитника, способного принять могучий облик медведя.",["race:NightElf"]="Для ночных эльфов общение с древними духами зверей и почитание священных камней на Темных берегах обновляет связи с обычаями Кенария, установленными тысячелетия назад."},sec={{t="Испытание Лунного Когтя",b="Night elf druid initiates are directed by Mathrengyl Bearwalker in Darnassus to venture east of the coastal settlement of Auberdine. There, tucked inside a natural cavern inhabited by wild moonkin, sits an ancient Moonkin Stone. By anointing this sacred monolith with Cenarion Moondust, the initiate rouses Lunaclaw, the ancient defender of the stone, who will challenge any claimant wishing to inherit the sacred strength of the claw."},{t="Сила тела и духа",b="Принять мантию медведя — значит гораздо больше, чем проявить грубую силу. Великий Дух Медведя передает основы учения о свирепости природы, а испытание против Лунного Когтя проверяет, обладает ли неофит стойкостью сердца, необходимой, чтобы обуздать и направить эту первобытную мощь. Победив хранителя в бою и прислушавшись к оставшейся мудрости духа, друид доказывает, что готов владеть обликом медведя, не теряя себя в зверином инстинкте."}},faq={{q="Кто такой Лунный Коготь?",a="Lunaclaw is a fierce moonkin spirit guardian dwelling in a cavern directly east of Auberdine in Darkshore. It defends the sacred Moonkin Stone and answers the call of initiates who sprinkle Cenarion Moondust upon the relic.",al={"what is lunaclaw","lunaclaw lore","moonkin boss auberdine"}},{q="Каково назначение этого испытания?",a="Этот обряд посвящения — последнее испытание для неофита-ночного эльфа, желающего вступить в ряды Друидов Когтя. Победа над Лунным Когтем показывает, что неофит обладает равновесием физической стойкости и душевной собранности, необходимым, чтобы принять дух и облик медведя.",al={"why do body and heart","what does this quest do","bear form quest lore","зачем тело и дух","что дает это задание","предания о задании облика медведя"}},{q="Кто выдает это задание?",a="Матренгил Медвежья Лапа, старший наставник друидов в Анклаве Кенария в Дарнассе, поручает неофитам это испытание после того, как они пообщаются с Великим Духом Медведя.",al={"quest giver body and heart","who gives bear form quest","кто выдает тело и дух","кто выдает задание облика медведя"}},{q="Что такое Лунная пыль Кенария?",a="Лунная пыль Кенария — освященный ритуальный порошок, который старейшины дают неофитам. Если рассыпать его на Лунный камень, его магические свойства пробуждают Лунного Когтя и начинают ритуальный бой.",al={"what is moondust","cenarion moondust lore","что такое лунная пыль","лунная пыль кенария предания"}},{q="Где проходит это испытание?",a="The trial takes place in a cavern east of Auberdine in Darkshore, where wild moonkin nest around an ancient carved Moonkin Stone.",al={"where is moonkin stone","moonkin cave auberdine"}},{q="Что происходит после победы над Лунным Когтем?",a="После победы над существом Дух Лунного Когтя возникает над своей телесной оболочкой, чтобы даровать благословение и признать двойную силу духа и тела друида, прежде чем тот вернется в Дарнасс.",al={"what happens after killing lunaclaw","spirit of lunaclaw","что будет после убийства лунного когтя","дух лунного когтя"}}},fp="14,353,21.435.0,26.461.1,16.223.0,34.287.0,21.178.0,26.189.0,33.129.0,40.202.1"}
P.entries["quest:6002"] = {n="Тело и дух",s="«Тело и дух» — заключительное испытание для молодых таурен-друидов, стремящихся овладеть формой медведя. Посланный Тюраком Руническим Тотемом из Громового Утеса, посвящаемый должен отправиться на границу Мулгора и Степей, чтобы призвать и победить Лунного Когтя у Камня лунного совуха.",h="«Тело и дух» — заключительное испытание для молодых таурен-друидов, стремящихся овладеть формой медведя.",kw={"barrens","bear form","body and heart","camp taurajo","cenarion lunardust","lunaclaw","moonkin stone","mulgore","thunder bluff","turak runetotem","степи","форма медведя","тело и дух","лагерь таурахо","лунная пыль кенария","лунный коготь","камень лунного совуха","мулгор","громовой утес","тюрак рунический тотем"},ang={["class:Druid"]="Этот обряд связывает учения кенарийцев-ночных эльфов с наследием таурен и позволяет молодым друидам наконец проявить свирепую стойкость формы медведя.",["faction:Horde"]="Таурены-друиды придают передовым отрядам Орды жизненно важную стойкость, опирая магическую силу фракции на глубокую защиту дикой природы.",["race:Tauren"]="Для шу'хало пробуждение медведя внутри — это и священное единение с духами природы, и практический способ защитить равнины Мулгора от наступающих угроз."},sec={{t="Путь Когтя",b="Чтобы по-настоящему пойти путем друида-медведя, посвящаемые таурены должны соединить духовную убежденность с физической стойкостью. После общения с Великим Духом Медведя на Лунной поляне подготовка друида проверяется на деле. Тюрак Рунический Тотем, старший наставник друидов на Вершине Старейшин в Громовом Утесе, вручает достойным соискателям Лунную пыль Кенария и поручает им отыскать священный камень близ сухой границы, где Мулгор встречается со Степями."},{t="Испытание Лунного Когтя",b="Камень лунного совуха, расположенный к западу от Лагеря Таурахо, отмечает редкое место Кенария на юге Калимдора. Лунные совухи не водятся на выжженных солнцем равнинах центрального Калимдора, поэтому присутствие зверя-стража Лунного Когтя особенно значимо. Рассыпав лунную пыль по древнему монументу, друид вызывает Лунного Когтя на бой. Победа над существом доказывает, что соискатель владеет и силой тела, и ясностью духа, и он получает благословение зверя и открывает внутреннюю суть медведя."}},faq={{q="В чем смысл этого испытания?",a="Это задание — последний шаг к получению формы медведя для друидов Орды. Пройдя испытание, вы доказываете, что готовы принять звание друида-медведя под руководством Тюрака Рунического Тотема.",al={"why do body and heart","what does body and heart do","what do i get from body and heart","зачем тело и дух","что дает тело и дух","что я получу за тело и дух"}},{q="Где находится Камень лунного совуха?",a="Камень лунного совуха находится в Степях, к западу от Лагеря Таурахо, у дороги к воротам Мулгора. К югу от дороги, за деревом возле одинокой палатки, лежит священный камень.",al={"moonkin stone location","where is moonkin stone","where to find moonkin stone","камень лунного совуха","где камень лунного совуха","как найти камень лунного совуха"}},{q="Кто такой Лунный Коготь?",a="Лунный Коготь — свирепый страж-лунный совух, связанный с Камнем лунного совуха. Призванный с помощью Лунной пыли Кенария, он проверяет, обладает ли друид той несгибаемой стойкостью и душевной уравновешенностью, что нужны для владения силой медведя.",al={"who is lunaclaw","what is lunaclaw","кто такой лунный коготь","что такое лунный коготь"}},{q="Что будет, если я проиграю бой Лунному Когтю?",a="Если вы потерпите поражение, ваша Лунная пыль Кенария будет потрачена. Вам придется вернуться к Тюраку Руническому Тотему на Вершине Старейшин в Громовом Утесе, получить новый мешочек пыли и только потом снова попытаться призвать зверя.",al={"failed lunaclaw","lost lunardust","died to lunaclaw","поражение от лунного когтя","потерял лунную пыль","убит лунным когтем"}},{q="Водятся ли лунные совухи в Степях?",a="Нет. Как отмечает Тюрак Рунический Тотем, лунные совухи не водятся ни в Степях, ни в Мулгоре. Это существо — неестественное зрелище в саванне, связанное именно с обрядами Кенария и древними местами небесной силы.",al={"moonkin in barrens","why are moonkin here","barrens moonkin","лунный совух в степях","почему здесь лунные совухи","степи лунный совух"}},{q="Кто выдает задание «Тело и дух»?",a="Задание выдает Тюрак Рунический Тотем, старший наставник друидов на Вершине Старейшин в Громовом Утесе, после возвращения посвящаемого с Лунной поляны.",al={"who starts body and heart","body and heart questgiver","кто начинает тело и дух","тело и дух кто выдает"}}},fp="14,256,19.461.0,21.507.0,34.205.0,35.199.0,16.218.0,51.201.0,34.205.0,35.155.0"}
P.entries["quest:6061"] = {n="Приручение зверя",s="«Приручение зверя» — основополагающий обряд для молодых таурен-охотников в Деревне Кровавого Копыта. Под руководством наставника Йо Колкой Гривы охотник отправляется в Мулгор, чтобы приручить взрослого степного бегуна и сделать первый шаг к духовной связи с созданиями Матери-Земли.",h="«Приручение зверя» — основополагающий обряд для молодых таурен-охотников в Деревне Кровавого Копыта.",kw={"bloodhoof village","earthmother","hunter quest","mulgore","plainstrider","taming","taming rod","yaw sharpmane","деревня кровавого копыта","мать-земля","задание охотника","мулгор","степной бегун","приручение","жезл приручения","йо колкая грива"},ang={["class:Hunter"]="Этот обряд знаменует переход от начинающего следопыта к настоящему повелителю зверей и учит вас общаться с животными под руководством Матери-Земли.",["race:Tauren"]="Приручение зверя — древняя традиция, занимающая центральное место в кочевом охотничьем наследии Мулгора; она укрепляет связь между охотником и природой."},sec={{t="Священная связь с дикой природой",b="Для таурен охота никогда не сводилась лишь к убийству зверей ради мяса и шкур. По древним традициям, победа над дикими животными Мулгора и единение с ними позволяют охотнику вбирать их духов и становиться ближе к Матери-Земле. Приручение зверя-спутника укрепляет эту связь, превращая возможного противника в партнера на всю жизнь, живущего в согласии с природным равновесием равнин."},{t="Первое испытание",b="Йо Колкая Грива начинает обучение посвящаемого не со свирепых хищников, а с быстрых и зорких степных бегунов, обитающих на лугах Мулгора. Вооружившись зачарованным жезлом приручения, охотник должен встретиться со взрослым степным бегуном, усмирить его дикие инстинкты и заслужить его доверие. Это первое испытание доказывает решимость охотника и готовит его к более трудным зверям."}},faq={{q="В чем смысл этого испытания?",a="Это задание — первая практическая проверка для начинающих таурен-охотников, желающих освоить искусство общения с животными. Усмиряя взрослого степного бегуна жезлом приручения, охотник узнает основы духовной и рабочей связи со зверями.",al={"why do i tame a plainstrider","purpose of quest","tauren pet quest purpose","зачем приручать степного бегуна","цель задания","цель задания питомца таурен"}},{q="Кто выдает это задание и где его найти?",a="Задание выдает Йо Колкая Грива, наставник охотников в Деревне Кровавого Копыта, в центральных равнинах Мулгора.",al={"who gives quest","quest giver location","yaw sharpmane location","кто выдает задание","где персонаж, выдающий задание","йо колкая грива где"}},{q="Останется ли взрослый степной бегун у меня навсегда?",a="Нет. Звери, приручаемые в первых трех испытаниях Йо Колкой Гривы, — лишь временные учебные партнеры. Когда вы пройдете всю цепочку обучения и освоите приручение зверей, вы сможете отправиться в мир и навсегда приручить любого подходящего спутника.",al={"is this pet permanent","do i keep the plainstrider","keep beast after quest","этот питомец навсегда","останется ли степной бегун","оставить зверя после задания"}},{q="Почему таурены считают приручение зверей духовным действием?",a="Традиция таурен учит, что общение с дикими существами и победа над ними позволяют охотникам вбирать их духов и становиться единым целым с природой. Приручение зверя отражает взаимное уважение и единство с созданиями Матери-Земли.",al={"tauren pet lore","earthmother taming lore","why tame beasts tauren","предания о питомцах таурен","приручение мать-земля","почему таурены приручают зверей"}},{q="Где можно найти взрослых степных бегунов?",a="Взрослые степные бегуны свободно бродят по холмистым саваннам и долинам вокруг Деревни Кровавого Копыта в Мулгоре.",al={"where are plainstriders","plainstrider location","find adult plainstrider","где степные бегуны","где найти степного бегуна","найти взрослого степного бегуна"}},{q="Что будет после этого задания?",a="Если вернуть жезл приручения Йо Колкой Гриве, начнется следующее испытание: вам предстоит приручить охотника из засады, затем свирепого налетчика, и только после этого вы изучите искусство постоянного приручения зверей.",al={"what is next","quest chain after this","next step taming","что дальше","цепочка заданий после этого","следующий шаг приручения"}}},fp="16,289,27.405.0,14.390.0,34.268.0,48.125.0,45.233.0,52.239.0,39.118.0,28.198.0"}
P.entries["quest:6062"] = {n="Приручение зверя",s="Это испытание — первый шаг юного охотника Орды в искусстве приручения зверей. Под руководством ветерана Тотара в Колючем Холме начинающие охотники с помощью зачарованного жезла приручения подчиняют злобного пестрого вепря и налаживают с ним связь.",h="Это испытание — первый шаг юного охотника Орды в искусстве приручения зверей.",kw={"dire mottled boar","durotar","hunter quest","pet taming","razor hill","taming rod","thotar","злобный пестрый вепрь","дуротар","задание охотника","приручение питомца","колючий холм","жезл приручения","тотар"},ang={["class:Hunter"]="Этот обряд смыкает пропасть между простым стрелком и настоящим повелителем зверей, открывая определяющую для охотника связь с животными-спутниками.",["race:Orc"]="Для орков управление зверем отражает силу воли и власть над суровой глушью их нового дома — Дуротара.",["race:Troll"]="Охотники Черного Копья используют это обучение, чтобы настроить свои души на суровую дикую природу Калимдора, продолжая древние традиции выслеживания."},sec={{t="Обряд посвящения охотника",b="Для охотников-орков и троллей Черного Копья, взрослеющих в Дуротаре, выжить в одиночку в глуши — лишь полдела. Истинный мастер дикой природы должен научиться проявлять власть над самой природой, превращая враждебных зверей в верных союзников. Наставник охотников Тотар вручает новичкам зачарованный жезл приручения и поручает им встретить свирепого дикого вепря, не прибегая к смертоносной стреле."},{t="Вепри Дуротара",b="Злобные пестрые вепри бродят по сухим зарослям вокруг Колючего Холма. Хотя они грубы и раздражительны, их выносливость и свирепость делают их идеальными объектами для первого приручения. Выдержать их натиск и терпеть их агрессию, направляя силу жезла, требует терпения и железной воли — добродетелей, необходимых любому следопыту Орды."}},faq={{q="В чем смысл этого испытания?",a="Это первая практическая проверка для юных охотников в Дуротаре: она учит направлять свою волю через жезл приручения, чтобы усмирить дикое существо, а не просто убить его.",al={"why do this quest","boar taming quest reason","taming the beast point","зачем это задание","причина задания с вепрем","смысл приручения зверя"}},{q="Кто выдает это задание?",a="Тотар, наставник охотников в Колючем Холме, дает это поручение, когда вы докажете свои базовые навыки выживания в Дуротаре.",al={"quest giver","who gives taming the beast","where to get boar quest","персонаж, выдающий задание","кто выдает приручение зверя","где взять задание с вепрем"}},{q="Где найти злобных пестрых вепрей?",a="Злобных пестрых вепрей можно встретить в сухих зарослях сразу за частоколом Колючего Холма в центральном Дуротаре.",al={"boar location","where is dire mottled boar","where to find boar","где вепрь","где злобный пестрый вепрь","где найти вепря"}},{q="Остается ли вепрь у вас навсегда после этого задания?",a="Нет. Вепрь, которого вы приручаете в этом первом упражнении, нужен лишь для практики. Он уходит, когда вы возвращаетесь к Тотару, ведь вам нужно продолжить обучение на других существах, прежде чем заводить постоянную связь.",al={"do i keep the boar","is the boar my permanent pet","keep dire mottled boar","остается ли вепрь","вепрь мой постоянный питомец","оставить злобного пестрого вепря"}},{q="Что будет после этого задания?",a="Когда вы вернетесь к Тотару, он проверит вашу власть над другими опасными хищниками Дуротара, включая прибрежных крабов и бронированных скорпидов.",al={"next quest","what after boar taming","taming chain next step","следующее задание","что после приручения вепря","следующий шаг цепочки приручения"}},{q="Зачем нужен жезл приручения, а не просто чутье?",a="Новичкам не хватает отточенной духовной и физической дисциплины, нужной для прямой связи со зверями. Зачарованный жезл служит средоточием, помогая новичкам проявлять власть над духом дикого зверя, пока они не овладеют этим искусством окончательно.",al={"why taming rod","what does the rod do","lore of taming rod","зачем жезл приручения","что делает жезл","предания о жезле приручения"}}},fp="16,222,26.396.0,20.350.0,34.185.0,21.138.0,39.121.0,50.195.0,27.150.0,46.246.0"}
P.entries["quest:6063"] = {n="Приручение зверя",s="Это задание — первое испытание на пути охотника-ночного эльфа к мастерству общения со зверями-спутниками. По поручению Дазалар в Доланааре начинающий охотник должен с помощью зачарованного жезла приручения подружиться с диким паутинным тихушником. Испытание проверяет умение уважать природу и общаться с ней, а не пытаться грубо ее подчинить.",h="Это задание — первое испытание на пути охотника-ночного эльфа к мастерству общения со зверями-спутниками.",kw={"dazalar","dolanaar","hunter pet","kaldorei","taming","taming rod","teldrassil","webwood lurker","дазалар","доланаар","питомец охотника","кальдораи","приручение","жезл приручения","тельдрассил","паутинный тихушник"},ang={["class:Hunter"]="Этот обряд знаменует переход охотника от одинокого лучника к настоящему союзнику дикой природы, связанному со зверями леса.",["race:NightElf"]="В духе философии кальдораев приручение питомцев подчеркивает единение с природой и почтение к ней, а не подчинение и господство."},sec={{t="Священная связь",b="Для кальдораев охота — это не только выслеживание добычи и выживание в глуши, но и священные отношения с природой. Наставники охотников, такие как Дазалар, учат, что природа неизмеримо больше любого смертного. Животные — не вьючные существа и не орудия, которые можно силой подчинить своей воле, а самостоятельные создания, требующие взаимного уважения. Чтобы доказать готовность к спутнику-зверю на всю жизнь, начинающие охотники должны показать власть над первобытными инстинктами местных животных древними приемами, а не грубой силой."},{t="Первое испытание",b="Испытания начинаются с гигантских паукообразных, населяющих ветви Тельдрассила. Дазалар вручает охотнику особый жезл приручения и велит найти паутинного тихушника. Углубившись в тенистые заросли, охотник должен встретиться с ядовитым пауком и установить с ним эмпатическую связь, выдерживая его атаки. Успешное создание этого временного мысленного моста доказывает, что охотник способен общаться даже с жуткими, проворными хищниками Мирового Древа."}},faq={{q="В чем смысл этого задания?",a="Это задание начинает цепочку обучения, необходимую охотникам-ночным эльфам для постоянного приручения зверей-спутников. Применяя жезл приручения к указанным местным зверям, охотники доказывают, что обладают выдержкой и умением общаться с дикими хищниками.",al={"why do this quest","pet quest purpose","what does taming the beast give","зачем это задание","цель задания питомца","что дает приручение зверя"}},{q="Кто выдает это задание?",a="Дазалар, наставник охотников в поселении Доланаар в Тельдрассиле, выдает это задание молодым охотникам-ночным эльфам, набравшим достаточно опыта.",al={"quest giver","where to get taming quest","who starts taming the beast","персонаж, выдающий задание","где взять задание на приручение","кто начинает приручение зверя"}},{q="Какое существо нужно приручить в этом испытании?",a="Вам нужно приручить паутинного тихушника — одного из ядовитых гигантских пауков, обитающих в диких зарослях и лесах за пределами Доланаара.",al={"which pet to tame","webwood lurker target","what beast do i tame","какого питомца приручать","цель паутинный тихушник","какого зверя приручать"}},{q="Останется ли паутинный тихушник у меня навсегда?",a="Нет. Паутинный тихушник, которого вы приручаете в этом задании, — временный спутник, нужный лишь для отработки основ обращения с питомцем. Когда вы вернетесь к Дазалар, связь разрывается, и вы готовитесь к следующему испытанию.",al={"do i keep the spider","is the webwood lurker permanent","keep pet","останется ли паук","паутинный тихушник навсегда","оставить питомца"}},{q="Почему ночные эльфы сначала испытывают охотников пауками?",a="Паутинные тихушники хищны и агрессивны, поэтому они — суровая проверка самообладания новичка. Покорив казалось бы неестественного паукообразного, охотник доказывает, что способен соединить свое сознание с разными, в том числе враждебными, проявлениями природы.",al={"why webwood lurker","why tame a spider","spider taming lore","почему паутинный тихушник","зачем приручать паука","предания о приручении пауков"}},{q="Что будет после возвращения к Дазалар?",a="Дазалар отправляет охотника проверить свою связь на других местных животных Тельдрассила — в частности, на ночной саблезуб-охотник и совиного крикуна, — прежде чем даровать способность к постоянному приручению.",al={"what next","after taming the beast","next trial","что дальше","после приручения зверя","следующее испытание"}}},fp="16,332,13.537.0,15.474.0,34.242.0,21.181.0,42.138.0,41.209.0,51.235.0,38.190.1"}
P.entries["quest:6064"] = {n="Приручение зверя",s="Приручение зверя — первое испытание на пути охотника-дворфа к освоению искусства обращения со зверями-спутниками в Дун Мороге. Под руководством Грифа Дикого Сердца в Караносе юные следопыты учатся усмирять свирепого крупного скального кабана и заводить с ним связь при помощи зачарованного хлыста приручения.",h="Приручение зверя — первое испытание на пути охотника-дворфа к освоению искусства обращения со...",kw={"beast","boar","crag boar","dun morogh","grif wildheart","hunter","kharanos","taming","taming rod","зверь","кабан","скальный кабан","дун морог","гриф дикое сердце","охотник","каранос","приручение","хлыст приручения"},ang={["class:Hunter"]="Это задание — решающий рубеж, на котором начинающий стрелок становится настоящим повелителем зверей; с него начинается череда испытаний, открывающих постоянных животных-спутников.",["race:Dwarf"]="Горцы Стальгорна чтут зверей, способных выдержать лютый холод Дун Морога; начало с выносливого скального кабана отражает уважение дворфов к стойкости и упорству."},sec={{t="Спутник охотника",b="До этого момента дворфы-горцы и следопыты полагаются лишь на огнестрельное оружие, ловушки и чутье дикой природы. Но истинная душа охотника — в пожизненном союзе с диким зверем. Гриф Дикое Сердце, стоящий возле таверны «Громоварка» в Караносе, следит за этим обрядом посвящения. Вместо того чтобы требовать от новичка навсегда подчинить первого встречного зверя, Гриф велит ему испытать свое терпение и решимость на нескольких местных видах Дун Морога."},{t="Скальный кабан",b="Первое испытание сводит следопыта с крупным скальным кабаном — одним из грубых толстошкурых животных, бродящих по заснеженным предгорьям Дун Морога. Покрытые щетинистой шерстью и жесткой плотью, эти звери упрямы и агрессивны, что делает их идеальной первой проверкой воли. Используя зачарованный хлыст приручения, выданный Грифом, охотник должен выдержать натиск кабана и укротить его ярость, пока тот не подчинится его воле."}},faq={{q="Кто дает это испытание?",a="Испытание дает Гриф Дикое Сердце, опытный наставник дворфов-охотников, стоящий возле таверны «Громоварка» в Караносе.",al={"quest giver","who starts taming the beast","grif wildheart location","персонаж, выдающий задания","кто начинает приручение зверя","где гриф дикое сердце"}},{q="Почему сначала нужно приручить крупного скального кабана?",a="Крупные скальные кабаны выносливы и упрямы, но их много на заснеженных хребтах Дун Морога. Усмирение такого крепкого толстокожего существа — основное упражнение в спокойном утверждении власти над агрессивным зверем.",al={"why crag boar","what beast do i tame","boar taming","почему скальный кабан","какого зверя приручать","приручение кабана"}},{q="Останется ли этот кабан со мной навсегда?",a="Нет. Это испытание — лишь тренировка. Связь, созданная с помощью хлыста приручения, временна: вы можете испытать, каково повелевать существом, а затем вернуть хлыст и попробовать другие виды.",al={"is this boar permanent","keep crag boar","can i keep the pet","кабан постоянный","оставить скального кабана","можно ли оставить питомца"}},{q="Где найти крупных скальных кабанов?",a="Крупные скальные кабаны бродят по открытым снежным полям и сосновым рощам вокруг Караноса и по заснеженным склонам Дун Морога.",al={"boar locations","where are large crag boars","large crag boar spawn","где кабаны","где крупные скальные кабаны","появление крупного скального кабана"}},{q="Что дальше после приручения скального кабана?",a="Возвращение к Грифу Дикому Сердцу завершает первый урок и ведет ко второму испытанию, где вам предстоит приручить снежного леопарда.",al={"next trial","what is after this quest","hunter chain next","следующее испытание","что после этого задания","продолжение цепочки охотника"}},{q="Как действует хлыст приручения?",a="Хлыст приручения — зачарованный инструмент, который наставники охотников выдают новичкам, чтобы помочь направить волю и усмирить дикие инстинкты без глубокой магической подготовки и многолетнего опыта общения со зверями.",al={"taming rod lore","what is the rod","how do i tame","предания о хлысте приручения","что такое хлыст","как приручить"}}},fp="16,251,20.493.0,13.427.0,22.127.0,38.231.0,35.190.0,34.124.0,38.144.0,29.209.0"}
P.entries["quest:6065"] = {n="Путь охотника",s="Путь охотника — важная веха для юных охотников-тауренов в Мулгоре, направляющая их к углубленному обучению обращению со зверями. Когда местные наставники убеждаются в их навыках стрельбы и выслеживания, новичков отправляют в Деревню Кровавого Копыта за советом к наставнику охотников Йо Колкая Грива. Это путешествие открывает духовные и практические испытания, необходимые для приручения диких зверей и союза с ними.",h="Путь охотника — важная веха для юных охотников-тауренов в Мулгоре, направляющая их к углубленному обучению...",kw={"beast","bloodhoof village","camp narache","hunter's path","mulgore","pet quest","taming","yaw sharpmane","зверь","деревня кровавого копыта","лагерь нараче","путь охотника","мулгор","задание на питомца","приручение","йо колкая грива"},ang={["class:Hunter"]="Это задание знаменует момент, когда лучник или стрелок становится настоящим повелителем зверей, делая первый шаг к обретению верного боевого спутника.",["faction:Horde"]="Охотники Орды сильно полагаются на свирепых зверей пограничья как на защитников первой линии и следопытов в суровых землях Калимдора.",["race:Tauren"]="Для шу'хало умение приручать диких зверей — духовное продолжение почитания природы и творения Матери-Земли."},sec={{t="Обряд посвящения",b="Для кочевых шу'хало охота священна, а не просто забава. Охотник должен понимать равновесие природы, чтить духов равнин и уважать животных, питающих племена. Когда юный охотник проявляет достаточное умение выживать в глуши и владеть луком или ружьем, старейшины понимают, что он готов выйти за пределы одиночного выслеживания. Наказ искать опытных наставников знаменует порог истинной зрелости в культуре тауренов."},{t="Дорога в Деревню Кровавого Копыта",b="Путь ведет послушников через широкие луга Мулгора в Деревню Кровавого Копыта — главное место сбора, раскинувшееся у Озера Каменного Быка. Там их ждет Йо Колкая Грива, опытный охотник, хорошо знающий нрав местной фауны. Разговор с ним — не простая формальность: он означает готовность охотника взяться за трудные испытания приручения и научиться общаться с хищниками, а не просто охотиться на них."}},faq={{q="Для чего нужен Путь охотника?",a="Это задание — официальное приглашение для начинающих охотников-тауренов приступить к испытаниям приручения зверей. Оно направляет охотника в Деревню Кровавого Копыта к Йо Колкая Грива, который руководит обрядами, необходимыми для союза со зверем-спутником.",al={"why get this quest","hunters path purpose","hunter pet quest start","зачем это задание","цель пути охотника","начало задания на питомца охотника"}},{q="Кто посылает вас с этим заданием?",a="Задание дают наставники охотников-тауренов, например в Лагере Нараче, когда начинающий охотник набрался достаточно опыта и овладел основами выживания и стрельбы.",al={"who gives the hunters path","hunter trainer quest","кто дает путь охотника","наставник охотников задание"}},{q="Кто такой Йо Колкая Грива?",a="Йо Колкая Грива — уважаемый наставник охотников-тауренов, живущий в Деревне Кровавого Копыта. Ему доверено обучать юных охотников опасному искусству приближения к диким зверям Мулгора, их успокоения и приручения.",al={"who is sharpmane","yaw sharpmane role","кто такой колкая грива","йо колкая грива роль"}},{q="Что происходит после выполнения этого задания?",a="Когда охотник докладывает Йо Колкая Грива, тот начинает цепочку испытаний «Приручение зверя». По ним охотнику нужно отправиться в глушь с хлыстом приручения и усмирить нескольких местных существ, прежде чем он получит право обучиться обращению с постоянным спутником.",al={"what comes next","next quest after hunters path","что дальше","следующее задание после пути охотника"}},{q="Почему охотники-таурены заводят союз со зверями, а не просто охотятся на них?",a="В традиции тауренов звери — родственные души Матери-Земли. Прирученное животное — не слуга, а спутник и партнер на охоте, воплощение взаимного уважения и общего выживания на равнинах.",al={"tauren pet lore","why tame pets tauren","предания о питомцах тауренов","зачем тауренам приручать питомцев"}},{q="Могут ли охотники других рас взять это задание?",a="Эта версия задания предназначена именно для охотников-тауренов, обучающихся в Мулгоре. Другие расы Орды, такие как орки и тролли, получают равнозначные наказы, подходящие их родным землям в Дуротаре.",al={"is this tauren only","can orcs do hunters path tauren","только для тауренов","могут ли орки взять путь охотника тауренов"}}},fp="17,421,17.483.0,29.455.0,41.243.0,28.201.0,21.207.0,41.250.0,68.203.0,52.228.0"}
P.entries["quest:6068"] = {n="Путь охотника",s="Путь охотника — обряд посвящения, направляющий юных охотников-орков и троллей в Колючий Холм. Под руководством мастера-охотника Тотара начинающие следопыты изучают важнейшую дисциплину подчинения диких хищников своей воле.",h="Путь охотника — обряд посвящения, направляющий юных охотников-орков и троллей в Колючий Холм.",kw={"durotar","hunter trainer","hunter's path","pet quest","razor hill","tame beast","thotar","дуротар","наставник охотников","путь охотника","задание на питомца","колючий холм","приручить зверя","тотар"},ang={["class:Hunter"]="Этот вызов знаменует важнейший порог вашего пути: переход от стрелка-одиночки к истинному повелителю зверей.",["faction:Horde"]="Орда полагается на разведчиков и следопытов, приручающих местных хищников и обращающих суровую экологию Дуротара себе на пользу.",["race:Orc"]="Для орков союз со свирепым спутником созвучен древним традициям, восходящим к наездникам на волках Дренора.",["race:Troll"]="Охотники племени Черного Копья считают умение приручать местных ящеров и кабанов необходимым, чтобы закрепиться в коварной глуши Дуротара."},sec={{t="Пробуждение охотника",b="До этого момента ученик-охотник в Дуротаре полагается лишь на свой лук и хитрость. Выслеживание добычи в каньонах красной глины и суровых зарослях учит терпению, но истинное мастерство в Орде требует союза с неприрученной фауной этих земель. Наставники по классу замечают, когда ученик стал достаточно способен для этого пути, и направляют его прямо в Колючий Холм."},{t="Мастер в Колючем Холме",b="В Колючем Холме ждет Тотар, опытный охотник, знаток диких преданий Дуротара. Тотар — наставник, обучающий новичков опасному обряду усмирения свирепых зверей без сокрушения их духа. Встреча с ним — первый шаг к странствиям по глуши с верным спутником рядом."}},faq={{q="Для чего нужен Путь охотника?",a="Это вводный вызов, отправляющий охотников-орков и троллей в Колючий Холм, чтобы они начали обучение приручению зверей.",al={"why do hunters path","hunter path quest purpose","what does this quest do","зачем путь охотника","цель задания путь охотника","что дает это задание"}},{q="Кто такой Тотар?",a="Тотар — опытный охотник из Колючего Холма, который руководит испытаниями, необходимыми юным следопытам Орды для союза с дикими зверями и управления ими.",al={"thotar who is he","who is thotar","thotar razor hill","тотар кто он","кто такой тотар","тотар колючий холм"}},{q="Почему юные охотники не могут сразу приручать питомцев?",a="Управление опасным хищником требует глубокой дисциплины, терпения и особых приемов приручения. Пока охотник не докажет базовые навыки выживания, попытка подчинить дикого зверя закончится тем, что его растерзают или убьют.",al={"why no pet at level 1","why must hunters wait for pets","when do hunters get pets","почему нет питомца на 1 уровне","почему охотникам надо ждать питомцев","когда охотники получают питомцев"}},{q="Какие расы проходят это испытание?",a="Эта версия пути предназначена для орков и троллей племени Черного Копья, взрослеющих в Дуротаре, а охотники-таурены проходят похожее испытание в Мулгоре.",al={"who gets this quest","is this for orcs and trolls only","what races do this","кто получает это задание","только ли для орков и троллей","какие расы"}},{q="Что происходит после доклада Тотару?",a="Тотар сразу поручает охотнику выследить и покорить различных местных хищников Дуротара, чтобы доказать свое умение приручать.",al={"what comes next","after hunters path","next quest after thotar","что дальше","после пути охотника","следующее задание после тотара"}},{q="Где проходит это обучение?",a="Испытание проходит возле Колючего Холма — главного поселения в центре Дуротара, между Долиной Испытаний и Оргриммаром.",al={"where is razor hill","thotar location","where to go","где колючий холм","где тотар","куда идти"}}},fp="17,222,20.376.0,24.320.0,41.131.0,14.145.0,46.220.0,42.159.0,39.141.0,36.131.0"}
P.entries["quest:6074"] = {n="Путь охотника",s="Путь охотника — обряд посвящения, предлагаемый начинающим охотникам-дворфам по всему Дун Мороге, когда они достигают базовых навыков выслеживания и стрельбы. Местные наставники направляют учеников к Грифу Дикому Сердцу в Каранос, чтобы начать обучение приручению диких зверей как постоянных спутников.",h="Путь охотника — обряд посвящения, предлагаемый начинающим охотникам-дворфам по всему Дун Мороге, когда они...",kw={"dun morogh","grif wildheart","hunter","kharanos","olmin burningbeard","pet quest","taming","tristane shadowstone","дун морог","гриф дикое сердце","охотник","каранос","олмин горящая борода","задание на питомца","приручение","тристан тень камня"},ang={["class:Hunter"]="Это задание знаменует переход от одинокого следопыта к истинному повелителю зверей, способному повелевать дикими хищниками.",["race:Dwarf"]="Дворфы-горцы издавна держали медведей и кабанов как надежных спутников-разведчиков на заснеженных вершинах Дун Морога."},sec={{t="Истинное призвание охотника",b="Пока охотник не овладеет искусством союза со зверем, он бродит по заснеженным утесам Дун Морога один, полагаясь лишь на топор, ружье или лук. Наставники вроде Олмина Горящая Борода и Тристана Тень Камня пристально следят за учениками, пока те не обретут выдержку, нужную, чтобы встретить дикого зверя и не убить его. Когда новичок показывает достаточную дисциплину, его отправляют по горным дорогам вниз, в Каранос."},{t="Доклад Грифу Дикому Сердцу",b="В Караносе Гриф Дикое Сердце руководит завершающими испытаниями дворфийской охоты. Приручение зверя считается гораздо более трудным делом, чем добыча его ради мяса или шкуры: оно требует терпения, физической выносливости и интуитивной связи с дикими хищниками гор. Дикое Сердце открывает путь к этим испытаниям, готовя охотника к изнурительной задаче — проверить силу воли на самых свирепых животных Дун Морога."}},faq={{q="Для чего нужно это задание?",a="Это официальный вызов, отправляющий взрослеющего охотника в Каранос, чтобы начать испытания приручения питомца под руководством Грифа Дикого Сердца.",al={"why do this quest","what is hunter's path","hunter pet quest start","зачем это задание","что такое путь охотника","начало задания на питомца охотника"}},{q="Кто посылает меня по этому пути?",a="Наставники охотников, включая Олмина Горящая Борода из Зала Оружия Стальгорна, Тристана Тень Камня и Эйнриса Светлое Копье, направляют своих учеников выполнить это задание.",al={"quest giver","who gives hunters path","where to pick up","персонаж, выдающий задания","кто дает путь охотника","где взять"}},{q="Где найти Грифа Дикого Сердца?",a="Гриф Дикое Сердце стоит возле таверны «Громоварка» в Караносе, в заснеженной долине Дун Морога.",al={"grif wildheart location","where is grif","kharanos hunter trainer","где гриф дикое сердце","где гриф","наставник охотников каранос"}},{q="Почему охотникам нужен наставник для приручения зверей?",a="Taming wild beasts requires specialized techniques and a taming rod to commune with predatory creatures without provoking a fight to the death. Grif Wildheart teaches these traditions.",al={"why need taming training","lore behind pet taming","why cant i tame yet","зачем учиться приручению","предания о приручении питомцев","почему я пока не могу приручить"}},{q="Что происходит после доклада Грифу Дикому Сердцу?",a="Grif Wildheart immediately tests your mettle by sending you into the wilderness with a taming rod to subdue several distinct beasts native to Dun Morogh.",al={"next quest","what follows hunters path","chain after this","следующее задание","что после пути охотника","цепочка после этого"}},{q="Может ли любой охотник взять это задание?",a="Этот вызов предназначен для охотников-дворфов, действующих в Дун Мороге, и направляет их к местному наставнику в Каранос.",al={"is this dwarf only","can night elves do this","race restriction","только для дворфов","могут ли ночные эльфы","ограничение по расе"}}},fp="17,296,23.404.0,27.430.0,34.124.0,26.164.0,32.114.0,45.184.0,47.153.0,40.129.0"}
P.entries["quest:6081"] = {n="Обучение зверя",s="Обучение зверя — завершающий обряд посвящения для юных охотников-орков и троллей в Дуротаре. После того как охотники докажут свое мастерство в обращении с дикими зверями равнин, их отправляют из Колючего Холма в Оргриммар учиться у опытного мастера-охотника Ормака Лютострела. Пройдя этот путь, новичок узнает, как ухаживать за своим спутником-животным, кормить его и совершенствовать его умения на всю жизнь.",h="Обучение зверя — завершающий обряд посвящения для юных охотников-орков и троллей в Дуротаре.",kw={"durotar","hunter pet","orgrimmar","ormak grimshot","razor hill","thotar","training the beast","valley of honor","дуротар","питомец охотника","оргриммар","ормак лютострел","колючий холм","тотар","обучение зверя","аллея чести"},ang={["class:Hunter"]="Это задание знаменует миг, когда ваш питомец становится постоянным надежным союзником, а не мимолетным призывом, и открывает важнейшие умения «Кормление питомца» и «Воскрешение питомца».",["faction:Horde"]="Орда полагается на своих разведчиков и зверей, оберегая хрупкие границы Дуротара и Степей от набегов кентавров, свинобразов и Альянса.",["race:Orc"]="Орки считают связь с охотничьим спутником делом воинской чести и долга — союзом, проверенным в боях на суровых рубежах Дуротара.",["race:Troll"]="Для троллей Черного Копья, строящих новый дом в Калимдоре, умение находить общий язык со свирепыми существами Дуротара жизненно важно для разведки и выживания на незнакомой земле."},sec={{t="Путь за пределы дикой природы",b="В засушливых каньонах Дуротара умение владеть луком и выживать в суровых условиях — лишь половина долга охотника. Укротив свирепых кабанов Дуротара, крабов-падальщиков и бронированных скорпидов-охотников, юные охотники готовы к настоящей ответственности — заботе о питомце. Тотар, живущий в Колючем Холме, отправляет их на север через ущелья красной глины прямо к укрепленным вратам Оргриммара."},{t="Аллея Чести",b="В шумной столице будущим следопытам нужно найти Аллею Чести — квартал, где духи воинов и опытные охотники оттачивают свое мастерство. Там живет Ормак Лютострел, один из самых почитаемых мастеров-охотников Орды. Ормак смотрит дальше юного возраста и определяет, хватит ли охотнику терпения не только повелевать зверем, но и поддерживать и беречь его в голод, в бою и в утрате."},{t="Связь с дикой природой",b="Зверь, покоренный силой воли, остается диким, пока между охотником и спутником не возникнет взаимопонимание. Ормак передает священные традиции, необходимые для поддержания этой связи: знание того, какая пища питает дух каждого существа, дисциплину, нужную для обучения смертоносным приемам, и духовную сосредоточенность, необходимую, чтобы вернуть к жизни павшего зверя, если он погибнет при исполнении долга."}},faq={{q="Кто дает задание «Обучение зверя»?",a="Тотар, наставник охотников у казармы в Колючем Холме, дает это задание после того, как вы успешно укротите всех трех испытуемых существ в Дуротаре.",al={"quest giver","who gives training the beast","where to start training the beast","персонаж, выдающий задания","кто дает обучение зверя","где начать обучение зверя"}},{q="Где найти Ормака Лютострела?",a="Ормак Лютострел живет в Аллее Чести, восточном районе столицы, Оргриммара, рядом с другими опытными наставниками охотников и воинов.",al={"ormak grimshot location","find ormak grimshot","where is ormak","где ормак лютострел","найти ормака лютострела","где ормак"}},{q="Каким умениям вас учит Ормак Лютострел?",a="Ормак учит вас тренировать спутника активным и пассивным умениям, кормить питомца, чтобы он оставался преданным и довольным, и воскрешать его, если он погибнет в бою.",al={"what do i learn","quest reward skills","hunter pet abilities","чему я научусь","умения за задание","умения питомца охотника"}},{q="Почему охотникам-оркам и троллям для этого нужно идти в Оргриммар?",a="Местные наставники вроде Тотара могут научить основам выживания в дикой природе, но высшее мастерство обращения со зверями хранят старейшие разведчики Орды и почитаемые следопыты вроде Ормака Лютострела в столице.",al={"why go to orgrimmar","why orgrimmar","valley of honor visit","зачем идти в оргриммар","почему оргриммар","визит в аллею чести"}},{q="Выполняют ли это задание другие расы Орды?",a="Нет. Этот обряд предназначен для охотников-орков и троллей, начинающих в Дуротаре. Охотники-таурены проходят похожий ритуал в Мулгоре под руководством собственных племенных наставников.",al={"can tauren do this","is this orc only","undead hunter","могут ли таурены","только для орков","охотник нежить"}},{q="Что будет, если охотник не пройдет это обучение?",a="Не закончив это обучение, охотник не сможет кормить, как следует обучать или воскрешать своего спутника, и любой пойманный зверь будет несчастным, слабым и в конце концов покинет его.",al={"do i need to do this","can i skip training the beast","обязательно ли это","можно ли пропустить обучение зверя"}}},fp="18,382,31.428.0,19.411.0,21.391.0,40.164.0,32.156.0,42.174.0,62.190.0,48.167.0,60.188.0"}
P.entries["quest:6082"] = {n="Приручение зверя",s="Это задание — последнее испытание в основных обрядах посвящения юного охотника Орды в Дуротаре. Под руководством опытного охотника Тотара в Колючем Холме начинающий следопыт должен встретиться с опасным бронированным скорпидом и приручить его. Победа над этим хищником доказывает мастерство в обращении с дикими зверями и дарует пожизненную способность приручать, призывать и отпускать настоящего спутника.",h="Это задание — последнее испытание в основных обрядах посвящения юного охотника Орды в Дуротаре.",kw={"armored scorpid","durotar","hunter trial","pet quest","razor hill","tame beast","taming rod","thotar","бронированный скорпид","дуротар","испытание охотника","задание питомца","колючий холм","приручение зверя","жезл приручения","тотар"},ang={["class:Hunter"]="Этот обряд — главная веха раннего пути охотника, дающая постоянный доступ к основным приемам приручения, призыва и управления животными-спутниками.",["faction:Horde"]="Юные орки и тролли Дуротара должны пережить встречу с самыми свирепыми хищниками бесплодной земли, чтобы заслужить место настоящих разведчиков и добытчиков Орды.",["race:Orc"]="Усмирение скорпидов Дуротара чтит орочью философию преодоления суровой местности несгибаемой волей и воинской дисциплиной.",["race:Troll"]="Охотники Черного Копья полагаются на острое чутье и глубокую связь с духами природы, чтобы усмирять ядовитых хищников, способных сразить других."},sec={{t="Последнее испытание",b="Прежде чем охотнику позволят странствовать по Калимдору с верным спутником-животным, он должен доказать, что способен совладать с самыми суровыми существами Дуротара. Наставник охотников Колючего Холма Тотар отправляет учеников укротить трех разных существ зачарованным жезлом приручения. Проверив себя на лютых кабанах и проворных прибрежных крабах, охотники должны встретиться с бронированным скорпидом — ядовитым, закованным в панцирь хищником, воплощающим стойкость и смертоносную скорость."},{t="Связь с дикой природой",b="Покорить бронированного скорпида — не просто убийство, а проявление сосредоточенности и превосходства под неослабевающим натиском. Тотар призывает охотников брать пример с быстрых и уверенных ударов зверя. Возвращение в Колючий Холм после успешного усмирения ядовитого паукообразного доказывает, что у охотника хватает спокойной воли сохранять контроль. После возврата жезла приручения Тотар передает врожденные приемы дикой природы, позволяя охотнику найти и связать с собой постоянного спутника по собственному выбору."}},faq={{q="Какое существо нужно приручить для этого испытания?",a="Вам нужно найти бронированного скорпида, бродящего по засушливым красным утесам Дуротара, и с помощью жезла приручения Тотара усмирить и подчинить его.",al={"what beast to tame","target beast","scorpid quest","какого зверя приручить","цель приручения","задание про скорпида"}},{q="Останется ли у меня бронированный скорпид после выполнения задания?",a="Нет. Бронированный скорпид, прирученный во время испытания, временный и исчезает, когда вы возвращаете жезл. Однако выполнение задания научит вас постоянной способности приручать любого дикого зверя по вашему желанию.",al={"keep scorpid","do i keep the pet","scorpid permanent","оставить скорпида","остается ли питомец","скорпид навсегда"}},{q="Кто начинает этот обряд посвящения?",a="Тотар, наставник охотников в Колючем Холме в центральном Дуротаре, руководит этим обрядом посвящения для юных охотников-орков и троллей.",al={"quest giver","who gives taming the beast","thotar location","персонаж, выдающий задания","кто дает приручение зверя","где тотар"}},{q="Почему Тотар хочет, чтобы охотники приручили именно бронированного скорпида?",a="Тотар считает бронированного скорпида идеальным примером для подражания из-за его уверенных быстрых ударов и природной стойкости. Покорив такого опасного хищника, охотник доказывает, что готов повелевать любым зверем дикой природы.",al={"why scorpid","purpose of scorpid","почему скорпид","зачем скорпид"}},{q="Какие умения вы получаете после выполнения этого задания?",a="Это испытание дарует основные умения опытного повелителя зверей: «Приручение животного», «Призыв питомца» и «Отпустить питомца».",al={"rewards","what spells do i get","taming skills unlocked","награды","какие заклинания я получу","открытые умения приручения"}},{q="Что идет после этого испытания?",a="Когда вы научитесь приручать и призывать собственного спутника, Тотар направит вас к обучению питомца и даст следующее задание «Обучение зверя», чтобы вы освоили кормление и управление своим союзником.",al={"next quest","what's next","after taming 3","следующее задание","что дальше","после приручения 3"}}},fp="16,359,15.484.0,21.523.0,47.128.0,63.215.0,35.136.0,69.220.0,52.122.0,28.207.0"}
P.entries["quest:6083"] = {n="Приручение зверя",s="Второе испытание в обряде мастерства юного охотника в Дуротаре под руководством наставника Тотара в Колючем Холме. Начинающих охотников-орков и троллей отправляют на побережье у Островов Эха, чтобы усмирить прибрежного краба, расширяя их связь за пределы наземных зверей до береговых существ.",h="Второе испытание в обряде мастерства юного охотника в Дуротаре под руководством наставника Тотара в Колючем...",kw={"durotar","echo isles","pet taming","razor hill","sen'jin village","surf crawler","taming rod","thotar","дуротар","острова эха","приручение питомцев","колючий холм","деревня сен'джин","прибрежный краб","жезл приручения","тотар"},ang={["class:Hunter"]="Это испытание прививает основы дисциплины, необходимой для управления защитными зверями, и показывает, как природная броня и упорство существа дополняют стрелка.",["race:Orc"]="Для орков, строящих постоянный дом в Дуротаре, усмирение стойкой фауны побережья укрепляет их власть над суровым краем.",["race:Troll"]="Тролли Черного Копья хорошо знают воды у Островов Эха и Деревни Сен'джин, поэтому для них это испытание — встреча с привычными обитателями их прибрежного убежища."},sec={{t="Связь с побережьем",b="Успешно покорив лютого пятнистого кабана, начинающий охотник получает от Тотара задание обратить внимание на море. В суровой природе Дуротара есть зазубренные берега и мелководные рифы, кишащие бронированными ракообразными. Встреча с прибрежным крабом требует терпения и стойкости: эти панцирные крабы не терпят вторжения в свои береговые владения."},{t="Продолжение воли",b="Тотар учит, что любой зверь, которого связывает охотник, должен стать продолжением его собственной силы. Усмиряя водное существо вроде прибрежного краба жезлом приручения, охотник учится приспосабливать свою властность к разным нравам и средам, доказывая готовность к постоянным спутникам."}},faq={{q="Где найти прибрежных крабов?",a="Прибрежные крабы снуют вдоль восточных берегов Дуротара, особенно на мелководье напротив Деревни Сен'джин, у вод, ведущих к Островам Эха.",al={"surf crawler location","where is surf crawler","crab location","где прибрежный краб","где найти прибрежного краба","где крабы"}},{q="Зачем приручать прибрежного краба?",a="Тотар поручает прибрежного краба, чтобы научить охотников повелевать разными зверями. Приручение бронированного водного существа расширяет власть охотника и доказывает, что он способен покорять животных из воды так же легко, как и с суши.",al={"why tame crab","surf crawler quest purpose","зачем приручать краба","цель задания с крабом"}},{q="Останется ли у меня прибрежный краб навсегда?",a="Нет. Звери, прирученные в этих первых испытаниях, — временные учебные объекты, усмиренные магией жезла приручения Тотара. Постоянное умение приручения вы изучите только после завершения всей цепочки испытаний.",al={"do i keep the crab","is surf crawler permanent","оставить краба","краб навсегда"}},{q="Кто дает это задание?",a="Тотар, наставник охотников в Колючем Холме, предлагает это испытание после того, как вы докажете умение приручить лютого пятнистого кабана.",al={"quest giver","who starts taming the beast 2","персонаж, выдающий задания","кто начинает приручение зверя 2"}},{q="Что идет после приручения прибрежного краба?",a="Когда вы вернете жезл Тотару, он предложит вам третье и последнее испытание: выследить и приручить бронированного скорпида, после чего научит вас постоянному повелеванию зверями.",al={"next quest","what's next in the chain","следующее задание","что дальше в цепочке"}},{q="Почему используется жезл приручения, а не природные умения?",a="Начинающие охотники еще не обрели врожденной духовной власти, необходимой для постоянной связи с дикими зверями. Жезл приручения служит проводником, позволяя новичкам безопасно учиться направлять свою волю, прежде чем освоить настоящий прием.",al={"why taming rod","what is taming rod","зачем жезл приручения","что такое жезл приручения"}}},fp="16,281,22.353.0,21.318.0,30.166.0,45.230.0,39.219.0,21.126.0,41.179.0,47.241.0"}
P.entries["quest:6084"] = {n="Приручение зверя",s="Это задание — второе испытание в посвящении дворфов-охотников, которое дает Гриф Дикое Сердце в Караносе. Научившись справляться с грубой стойкостью скального кабана, молодой охотник должен овладеть быстротой и смертоносной грацией местного снежного леопарда.",h="Это задание — второе испытание в посвящении дворфов-охотников, которое дает Гриф Дикое Сердце в Караносе.",kw={"dun morogh","grif wildheart","hunter quest","kharanos","snow leopard","taming rod","taming the beast","дун морог","гриф дикое сердце","задание охотника","каранос","снежный леопард","хлыст приручения","приручение зверя"},ang={["class:Hunter"]="Этот обряд учит начинающих охотников-дворфов различать питомцев с высокой стойкостью, как кабаны, и быстрых, агрессивных бойцов, как кошки.",["race:Dwarf"]="Горцы Каз Модана издавна делят со снежными леопардами замерзшие вершины Дун Морога, уважая и их скрытность, и смертоносное охотничье мастерство."},sec={{t="Урок мастерства",b="Пока скальные вепри учат горца выдерживать необузданную ярость и принимать удары, Гриф Дикое Сердце подчеркивает, что мастер-охотник должен понимать разные стили боя. Он направляет своих учеников на юго-восток, к разгуливающим по Дун Мороге снежным леопардам. Гриф сравнивает этих грациозных хищников с изящно сделанным ружьем: внешне они великолепны, но под безупречно белым мехом скрывается разрушительная мощь."},{t="Овладение хлыстом приручения",b="С помощью зачарованного хлыста приручения охотник должен встретиться с диким леопардом и обратить его охотничьи инстинкты в партнерство. Снежные леопарды проверяют ловкость, скорость и острые рефлексы, а не просто выносливость. Укрощение такого зверя показывает, что новичок способен ладить с хищниками, стремительно нападающими со снежных утесов, и делает еще один шаг к истинной власти над зверями дикой природы."}},faq={{q="Для чего нужно это задание?",a="Это второй этап обряда посвящения охотников у дворфов. Наставник охотников Гриф Дикое Сердце требует, чтобы ученики проверили свои навыки на разных диких зверях, прежде чем он передаст им знания о постоянной связи с животными-спутниками.",al={"why do this quest","snow leopard quest dwarf","taming the beast 2","зачем это задание","задание снежный леопард дворф","приручение зверя 2"}},{q="Где найти снежных леопардов?",a="Снежные леопарды бродят по скалистым утесам и снежным склонам к югу и востоку от Караноса в Дун Мороге.",al={"snow leopard location","where are snow leopards dun morogh","leopard location","где снежные леопарды","расположение снежного леопарда","где леопарды дун морог"}},{q="Почему Гриф Дикое Сердце хочет, чтобы я приручил леопарда?",a="Гриф считает, что охотник должен познать и грубую силу, и утонченное мастерство. Если кабан полагается на грубую стойкость, то снежный леопард учит охотника сражаться рядом с быстрым, ловким и смертоносным бойцом.",al={"why snow leopard","grif wildheart leopard reasoning","почему снежный леопард","гриф дикое сердце леопард"}},{q="Останется ли этот снежный леопард со мной навсегда?",a="Нет. Звери, прирученные во время этих первых испытаний, — временные партнеры по обучению, связанные магией хлыста приручения. Когда Гриф сочтет ваше обучение завершенным в конце цепочки заданий, вы получите постоянную способность приручать любого дикого зверя по своему выбору.",al={"can i keep the snow leopard","is the leopard permanent","оставить снежного леопарда","леопард навсегда"}},{q="Кто дает это испытание?",a="Гриф Дикое Сердце, учитель охотников-дворфов, стоящий возле таверны в Караносе, Дун Морог.",al={"who gives quest","quest giver","grif wildheart role","кто дает задание","персонаж, выдающий задания","гриф дикое сердце"}},{q="Что дальше в цепочке?",a="После того как вы докажете мастерство в обращении со снежным леопардом, Гриф отправит вас на третье и последнее испытание — приручить медведя-ледолапа, — прежде чем официально научит вас самостоятельно приручать и обучать диких зверей.",al={"next quest","what after snow leopard","следующее задание","что после снежного леопарда"}}},fp="16,259,19.416.0,24.396.0,34.251.0,34.110.0,50.228.0,47.254.0,23.91.0,29.204.1"}
P.entries["quest:6085"] = {n="Приручение зверя",s="Это задание — последнее испытание в начальном обучении охотника-дворфа у Грифа Дикого Сердца в Караносе. Используя зачарованный жезл, чтобы укротить и понять агрессивного медведя-ледолапа, охотник доказывает, что владеет собой перед лицом грубой силы. Выполнив это упражнение, он получает основные умения, нужные, чтобы приручать, призывать и отпускать постоянного дикого спутника.",h="Это задание — последнее испытание в начальном обучении охотника-дворфа у Грифа Дикого Сердца в Караносе.",kw={"dun morogh","grif wildheart","hunter quest","ice claw bear","kharanos","pet taming","taming rod","taming the beast","дун морог","гриф дикое сердце","задание охотника","ледяной медведь","каранос","приручение питомца","хлыст приручения","приручение зверя"},ang={["class:Hunter"]="Это обряд, превращающий одинокого стрелка в настоящего охотника, приручающего питомцев, и открывающий основные умения приручать и призывать зверей.",["race:Dwarf"]="Медведи издавна были символичными спутниками горцев-дворфов, патрулирующих Дун Морог, и славятся тем, что не уступают хозяевам в упрямой стойкости."},sec={{t="Сила дикой природы",b="По всему Дун Морогу горцы и разведчики издавна полагались на выносливых зверей, чтобы пережить ледяные утесы. Направив учеников практиковаться на быстрых и хитрых хищниках, мастер-охотник Гриф Дикое Сердце поручает начинающим охотникам поймать ледяного медведя. Эти огромные звери бродят по сугробам к востоку от Караноса и воплощают грубую физическую мощь и неутомимую выносливость — качества, которыми должен научиться управлять каждый охотник-дворф."},{t="Обретение спутника",b="Испытания с хлыстом приручения — строго учебные упражнения, показывающие охотникам, как дикие инстинкты отзываются на волю и спокойное намерение. Когда хлыст удерживает медведя в покорности, временная связь выполняет свою цель. Возвращение орудия Грифу завершает официальные испытания, и мастер делится постоянными тайнами повелевания зверями: как усмирить любое подходящее дикое существо и призывать его всю жизнь приключений."}},faq={{q="Какое животное нужно приручить для этого задания?",a="Вы должны найти ледяного медведя, который бродит по замерзшим предгорьям к востоку от Караноса в Дун Мороге. Выданный Хлыст приручения усмиряет зверя, чтобы вы могли испытать обращение с грубой силой.",al={"which bear","target animal","taming target","какой медведь","целевое животное","цель приручения"}},{q="Останется ли у меня медведь после сдачи задания?",a="Нет. Медведь, усмиренный Хлыстом приручения, — лишь временная проверка дисциплины и умения. Когда вы вернете хлыст Грифу Дикому Сердцу, зверь уйдет, а вы получите настоящие умения приручать любого дикого зверя по своему выбору.",al={"do i keep the bear","keep pet","is bear permanent","оставить медведя","оставить питомца","медведь навсегда"}},{q="Где находится Гриф Дикое Сердце?",a="Гриф Дикое Сердце находится у таверны «Громоварка» в Караносе, в Дун Мороге, где обучает начинающих охотников стрельбе и управлению зверями.",al={"grif location","where is grif","hunter trainer kharanos","где гриф","расположение грифа","наставник охотников каранос"}},{q="Какие умения я получу после этого испытания?",a="Завершение этого последнего испытания обучает основным заклинаниям охотника: Приручение зверя, Призыв питомца и Отпускание питомца. Это позволяет вам отправиться в мир и связать себя с постоянным спутником.",al={"quest rewards","hunter skills learned","tame beast reward","награда за задание","умения охотника","награда приручение зверя"}},{q="Что делать после выполнения этого задания?",a="Гриф отправит вас дальше с заданием «Обучение зверя», велев научиться правильно кормить, растить и обучать нового спутника, чтобы он оставался верным в бою.",al={"next quest","what comes next","training the beast","следующее задание","что дальше","обучение зверя"}},{q="Почему Гриф заставляет охотников испытывать разных зверей?",a="Три испытания знакомят начинающего охотника с разными стилями боя — ловкостью, хитростью и грубой силой. Знакомство с этими разными нравами помогает горцу выбрать лучшего спутника для своего стиля охоты.",al={"why three beasts","purpose of trials","three animals","почему три зверя","цель испытаний","три животных"}}},fp="16,364,24.446.0,19.439.0,45.200.0,55.227.0,32.168.0,52.198.0,50.177.0,57.223.0"}
P.entries["quest:6086"] = {n="Обучение зверя",s="«Обучение зверя» — завершающий обряд посвящения молодых охотников-дворфов в Дун Мороге. Овладев искусством усмирять и приручать диких хищников на снежных утесах, начинающие следопыты направляются в сердце Стальгорна, чтобы научиться содержать, воспитывать и растить спутника на всю жизнь.",h="«Обучение зверя» — завершающий обряд посвящения молодых охотников-дворфов в Дун Мороге.",kw={"belia thundergranite","dun morogh","dwarf hunter","grif wildheart","hall of arms","ironforge","pet training","training the beast","белия громовой гранит","дун морог","охотник дворф","гриф дикое сердце","зал оружия","стальгорн","обучение питомца","обучение зверя"},ang={["class:Hunter"]="Этот рубеж открывает определяющую основу охотничьего ремесла: умения правильно кормить, направлять и воскрешать постоянного спутника-зверя.",["faction:Alliance"]="Повелители зверей Стальгорна вносят большой вклад в разведывательные силы Альянса, полагаясь на верных диких спутников при патрулировании холодных горных перевалов.",["race:Dwarf"]="Дворфы видят в охоте непреходящую традицию горной глуши Каз Модана и относятся к медведям, кабанам и горным кошкам как к уважаемым партнерам в разведке и обороне."},sec={{t="Из дикой природы в кузницу",b="Проявив доблесть в схватках со свирепыми зверями Дун Морога — усмирив жезлом приручения крупных скальных вепрей, снежных леопардов и выносливых ледяных медведей, — начинающие охотники завершают испытание под бдительным взором Грифа Дикого Сердца возле Караноса. Но покорить дикое сердце животного — лишь половина связи. Гриф отправляет своих повзрослевших учеников по горному перевалу в Стальгорн, на поиски военного квартала, известного как Зал Оружия."},{t="Наставления Белии Громовой Гранит",b="В каменных сводах Зала Оружия Стальгорна стоит Белия Громовой Гранит — одна из самых почитаемых мастеров-дрессировщиков королевства дворфов. Белия передает основные знания, превращающие дикого, напуганного зверя в яростно преданного партнера. Ее уроки выходят далеко за рамки простых команд: она показывает молодым охотникам, как кормить питомцев, обучать их новым боевым навыкам и даже возвращать их духов из смерти, если они падут, защищая хозяина."},{t="Узы охотника-дворфа",b="Традиция дворфов подчеркивает, что повелевание зверями строится прежде всего на уважении, а не на подчинении. Белия напоминает каждому молодому охотнику, что спутник-зверь отражает заботу, которую получает. Если зверя хорошо кормить, уважать и правильно обучать, он будет безоглядно предан в борьбе с троггами, ледяными троллями и любой угрозой, посмевшей напасть на Каз Модан."}},faq={{q="Для чего нужно это задание?",a="Это задание — последний шаг в начальной подготовке охотника-дворфа. Оно дает основные знания для содержания постоянного боевого питомца: вы сможете кормить его, развивать его способности, призывать к себе и воскрешать, если он погибнет.",al={"why do this quest","training the beast purpose","hunter pet quest reward","зачем это задание","цель обучения зверя","награда задания питомец охотника"}},{q="Кто такая Белия Громовой Гранит?",a="Белия Громовой Гранит — почитаемая мастер-дрессировщик, находящаяся в Зале Оружия в Стальгорне. Она — старший наставник следопытов-дворфов и учит их дисциплине, кормлению и командам, нужным, чтобы превратить прирученных диких животных в союзников на всю жизнь.",al={"who is belia","belia thundergranite lore","hunter trainer ironforge","кто такая белия","белия громовой гранит предания","наставник охотников стальгорн"}},{q="Где найти Белию Громовой Гранит?",a="Белия Громовой Гранит находится в Стальгорне, в Зале Оружия — военном крыле города, где собираются и тренируются воины, охотники и паладины из числа дворфов и гномов.",al={"belia location","where is belia thundergranite","where is hall of arms ironforge","где белия","где белия громовой гранит","где зал оружия стальгорн"}},{q="Каких зверей приручают охотники-дворфы до этого обучения?",a="Во время испытаний, предшествующих этому заданию, Гриф Дикое Сердце проверяет молодых охотников: с помощью зачарованного хлыста они временно усмиряют по всему Дун Морогу крупного скального кабана, снежного леопарда и ледяного медведя.",al={"what beasts do you tame","dwarf pet trial beasts","prior quests beasts","каких зверей приручают","звери испытаний дворфа","звери прошлых заданий"}},{q="Почему охотники-дворфы должны кормить питомцев?",a="Предания дворфов о зверях гласят, что спутники-животные — партнеры, а не орудия. Если пренебрегать голодом зверя, его настроение ухудшается и желание сражаться угасает, а сытый зверь сохраняет яростную преданность и максимальную эффективность в бою.",al={"why feed pet","pet happiness lore","beast loyalty dwarf","зачем кормить питомца","счастье питомца","верность зверя дворф"}},{q="Кто дает это задание?",a="Это задание дает Гриф Дикое Сердце, опытный наставник охотников, стоящий у дороги к востоку от Караноса в Дун Мороге, — после успешного завершения вашего третьего испытания приручения.",al={"who starts training the beast","grif wildheart role","quest giver","кто начинает обучение зверя","гриф дикое сердце","персонаж, выдающий задания"}}},fp="18,311,26.447.0,32.466.0,25.360.0,34.249.0,28.258.0,37.166.0,67.211.0,41.254.0,21.184.0"}
P.entries["quest:6087"] = {n="Приручение зверя",s="Это испытание — второй этап посвящения охотника-тауренов в искусство приручения зверей. Под руководством учителя охотников Йо Колкой Гривы в Деревне Кровавого Копыта новичок должен овладеть искусством приручения быстрого и бесстрашного луговой охотницы — волчицы прерий.",h="Это испытание — второй этап посвящения охотника-тауренов в искусство приручения зверей.",kw={"bloodhoof village","hunter trial","mulgore","prairie stalker","taming rod","taming the beast","tauren hunter","yaw sharpmane","деревня кровавого копыта","испытание охотника","мулгор","луговой охотник","жезл приручения","приручение зверя","таурен-охотник","йо колкая грива"},ang={["class:Hunter"]="Этот обряд связывает основы выживания с наступательной слаженностью и учит вас сражаться плечом к плечу с быстрым спутником.",["race:Tauren"]="В отличие от культур, видящих в питомцах лишь рабочих животных, шу'хало считают приручение зверя созданием священного родства под бдительной милостью Матери-Земли."},sec={{t="Уроки охотника прерий",b="Успешно освоив защитную выносливость взрослого страуса, Йо Колкая Грива призывает молодого охотника заглянуть дальше простого выживания. Луговой охотник воплощает совсем иную философию охоты: неутомимую скорость, слаженность стаи и бесстрашный натиск. Чтобы приручить его, нужно приблизиться к хитрому хищнику, не сбавляя шага, подобно решительной натуре самого волка."},{t="Плечом к плечу",b="Для таурена охота вместе со зверем — это никогда не рабство и не грубое подчинение. Йо Колкая Грива подчеркивает, что охотник и хищник должны сражаться как единое целое, связанное взаимным уважением и общим ритмом. Подружившись с прерийным бродягой под открытым небом Мулгора, охотник учится дополнять атаки напарника и действовать с ним согласованно в пылу боя."}},faq={{q="Какое животное Йо Колкая Грива просит меня приручить в этом испытании?",a="Этот второй урок требует приручить лугового охотника — одного из быстрых волков, бродящих по холмистым равнинам Мулгора.",al={"what beast do i tame","which pet is next","tame prairie stalker","какого зверя приручить","какой питомец следующий","приручить лугового охотника"}},{q="Почему охотник-таурен учится приручать волков?",a="Йо Колкая Грива учит, что луговой охотник воплощает скорость и бесстрашие. Сближаясь с таким хищником, охотник перенимает именно эти качества и учится согласованно атаковать вместе с быстрым охотничьим напарником.",al={"why wolves","prairie stalker lore","why tame a wolf","почему волки","предания о луговом охотнике","зачем приручать волка"}},{q="Где обычно можно найти луговых охотников?",a="Луговые охотники бродят по травянистым равнинам центрального и северного Мулгора, часто выслеживая добычу в прериях вокруг Деревни Кровавого Копыта.",al={"prairie stalker location","where are prairie stalkers","find prairie stalker","где луговой охотник","где найти лугового охотника","найти лугового охотника"}},{q="Останется ли у меня луговой охотник после задания?",a="Нет. Жезл приручения создает лишь временную связь для обучения. Когда вы пройдете все испытания, вы получите постоянную способность приручать любого дикого спутника по своему выбору.",al={"can i keep the wolf","keep prairie stalker","is this my permanent pet","можно ли оставить волка","оставить лугового охотника","это мой постоянный питомец"}},{q="Кто такой Йо Колкая Грива?",a="Йо Колкая Грива — местный учитель охотников в Деревне Кровавого Копыта. Он ведет молодых тауренов через духовные и практические этапы, необходимые, чтобы овладеть дикими землями Мулгора.",al={"who is yaw","sharpmane lore","yaw bloodhoof","кто такой йо","колкая грива","йо кровавое копыто"}},{q="Что идет после приручения лугового охотника?",a="Когда Йо Колкая Грива убедится в вашем мастерстве над волком, он отправит вас на третье и последнее испытание цепочки, где вашу решимость проверит скрытный налетчик.",al={"next quest","what is after prairie stalker","third taming quest","следующее задание","что после лугового охотника","третье задание приручения"}}},fp="16,233,21.405.0,16.376.0,60.124.0,46.237.0,44.136.0,53.198.0,21.187.0,44.173.0"}
P.entries["quest:6088"] = {n="Приручение зверя",s="Это испытание — последний урок в обучении молодого охотника-таурена у Йо Колкой Гривы в Деревне Кровавого Копыта. Связав себя с диким налетчиком при помощи жезла приручения, охотник доказывает мастерство над созданиями воздуха и земли и обретает священное доверие Матери-Земли. Выполнение задания дарует постоянное знание, необходимое, чтобы приручить спутника на всю жизнь и повелевать им.",h="Это испытание — последний урок в обучении молодого охотника-таурена у Йо Колкой Гривы в Деревне Кровавого...",kw={"bloodhoof village","earthmother","hunter pet","mulgore","swoop","taming rod","taming the beast","yaw sharpmane","деревня кровавого копыта","мать-земля","питомец охотника","мулгор","налетчик","жезл приручения","приручение зверя","йо колкая грива"},ang={["class:Hunter"]="Это задание завершает основную цепочку обучения, открывающую постоянное приручение зверей, и знаменует переход от ученика к полностью самостоятельному стражу дикой природы.",["race:Tauren"]="Для шу'хало связь с диким зверем — акт духовного единения, благословленный Матерью-Землей, имеющий глубокое культурное значение на равнинах Мулгора."},sec={{t="Власть над небом",b="Уже покорив хищников, обитающих на земле, на холмистых равнинах Мулгора, Йо Колкая Грива обращает ваш взор к открытому небу. Налетчик — свирепая хищная птица с острым клювом, известная стремительными пикированиями и грозным нравом. Укрощение такого дикого воздушного охотника испытывает вашу реакцию и спокойствие: вам придется терпеть его когти, пока вы с помощью зачарованного жезла настраиваете свой дух на его инстинкты."},{t="Дар Матери-Земли",b="Для тауренов охота и дружба с животными — прежде всего духовные занятия, а не простое подчинение. Овладев созданиями земли и неба, вы показываете равновесие и уважение, необходимые, чтобы ходить по равнинам, не нарушая природы. Йо Колкая Грива признает вашу зрелость, забирает свой временный жезл приручения и передает вам прочные приемы призыва, отпускания и постоянного приручения спутника по вашему выбору."}},faq={{q="Почему в последнем испытании нужно приручить налетчика?",a="Йо Колкая Грива хочет проверить ваши силы против созданий, населяющих небо. Налетчики наносят острые и быстрые удары и внушают трепет, что доказывает: охотник справится и с воздушными хищниками, и с наземными зверями, прежде чем обретет настоящую самостоятельность.",al={"why tame swoop","purpose of swoop taming","why a swoop","зачем приручать налетчика","цель приручения налетчика","почему налетчик"}},{q="Останется ли у меня налетчик, которого я приручу во время этого задания?",a="Нет. Налетчик приручается временно с помощью жезла приручения Йо Колкой Гривы в рамках ритуального обучения. Выполнив задание, вы получите способность приручить любого дикого зверя, которого пожелаете оставить навсегда.",al={"do i keep the swoop","is the swoop my pet","can i keep this bird","останется ли налетчик","налетчик мой питомец","можно оставить эту птицу"}},{q="Кто выдает это задание и где его найти?",a="Йо Колкая Грива, учитель охотников в Деревне Кровавого Копыта в центральном Мулгоре, предлагает это задание как третий и последний шаг ваших первых испытаний приручения зверей.",al={"quest giver","who starts this","where is yaw sharpmane","персонаж, выдающий задание","кто начинает задание","где йо колкая грива"}},{q="Что произойдет после того, как я верну жезл приручения?",a="Йо Колкая Грива научит вас самостоятельно приручать, призывать и отпускать зверей. Он также направит вас в Громовой Утес, чтобы вы научились правильно обучать выбранного спутника и ухаживать за ним.",al={"what do i learn next","rewards for finishing","what is after this quest","чему я научусь дальше","награды за выполнение","что после этого задания"}},{q="Где в Мулгоре можно найти диких налетчиков?",a="Налетчики парят над открытыми лугами и краями плато по всему центральному Мулгору, часто кружа над равнинами у самой Деревни Кровавого Копыта.",al={"swoop locations","where are swoops","find a swoop","где налетчики","места налетчиков","найти налетчика"}},{q="Почему приручение питомца считается у тауренов обрядом посвящения?",a="Культура тауренов видит в зверях не орудия, а таких же детей Матери-Земли. Чтобы сблизиться со спутником, нужны терпение, взаимное уважение и духовное равновесие, а не одна лишь сила.",al={"tauren hunter lore","hunter spiritual path","earthmother connection","предания охотников-тауренов","духовный путь охотника","связь с матерью-землей"}}},fp="16,362,18.438.0,22.453.0,50.249.0,45.209.0,48.161.0,43.207.0,40.132.0,58.199.0"}
P.entries["quest:6089"] = {n="Обучение зверя",s="Обучение зверя — завершающий обряд посвящения молодых охотников-тауренов в Мулгоре. Доказав духовное терпение и решимость, необходимые, чтобы усмирять диких зверей равнин, охотники отправляются в Громовой Утес, чтобы освоить пожизненную дисциплину единения с постоянным животным-спутником, его кормления и управления им.",h="Обучение зверя — завершающий обряд посвящения молодых охотников-тауренов в Мулгоре.",kw={"beast training","holt thunderhorn","hunter rise","mulgore","tauren hunter","thunder bluff","training the beast","yaw sharpmane","обучение зверя","хольт громовой рог","вершина охотников","мулгор","таурен-охотник","громовой утес","йо колкая грива"},ang={["class:Hunter"]="Этот обряд знаменует переход от одиночной борьбы к бою рядом с верным спутником и завершает вашу основную подготовку как стража дикой природы.",["race:Tauren"]="Для шу'хало брать животного-спутника в бой — священный долг заботы и уважения к созданиям Матери-Земли."},sec={{t="Путь к Великому Утесу",b="Испытав свой дух против опасных хищников Мулгора — страусов, луговых охотников и налетчиков, — охотники-таурены признаются готовыми принять истинную мантию охотника. Йо Колкая Грива, наставник из Деревни Кровавого Копыта, поручает новичку отправиться на Вершину Охотников в Громовом Утесе. Там живет Хольт Громовой Рог, легендарная личность среди шу'хало, чья слава общения с дикой природой превзойдена лишь его почтением к Матери-Земле."},{t="Священная связь",b="Для тауренов зверь — не простое оружие и не раб, а напарник, дарованный через гармонию с миром природы. Хольт Громовой Рог передает важные знания, необходимые для поддержания этого союза. Охотник должен научиться не только направлять боевые инстинкты существа, но и питать его тело регулярным кормлением, залечивать раны и призывать его дух обратно, если оно падет, защищая своего спутника на равнинах."}},faq={{q="С кем мне говорить для этого задания?",a="Вам нужно поговорить с Хольтом Громовым Рогом, мастером-охотником на Вершине Охотников в Громовом Утесе. Йо Колкая Грива направит вас к нему, когда вы завершите первые испытания приручения диких зверей в Мулгоре.",al={"quest turn in","who is holt thunderhorn","where is holt","сдать задание","кто такой хольт громовой рог","где хольт"}},{q="Каким умениям учатся охотники-таурены после выполнения этого задания?",a="Хольт Громовой Рог учит вас обучать питомца новым умениям, кормить спутника, чтобы он оставался верным и довольным, и воскрешать питомца, если он погибнет в бою.",al={"what abilities do i get","quest reward skills","what does holt teach","какие умения я получу","умения за задание","чему учит хольт"}},{q="Какое место это задание занимает в цепочке охотника-тауренов?",a="Это последнее задание цепочки. Оно следует за заданиями «Путь охотника» и трехчастным испытанием «Приручение зверя», в котором охотник временно усмиряет взрослого страуса, лугового охотника и налетчика на равнинах.",al={"hunter quest chain","pet quest mulgore","training the beast chain","цепочка заданий охотника","задание питомца мулгор","цепочка обучение зверя"}},{q="Почему Хольт Громовой Рог пользуется таким высоким положением среди охотников-тауренов?",a="Хольт всю жизнь испытывал себя в схватках с самыми свирепыми зверями Азерота, повелевая несколькими могучими спутниками и сохраняя глубокую духовную связь с Матерью-Землей. Его мудрость делает его главным учителем молодых охотников-шу'хало в Громовом Утесе.",al={"holt thunderhorn lore","who is holt","хольт громовой рог предания","кто такой хольт"}},{q="Могут ли охотники приручить постоянного питомца до сдачи этого задания?",a="Способность приручать диких зверей у вас уже есть после предыдущего испытания, но пока вы не поговорите с Хольтом Громовым Рогом, вам не хватает знаний, чтобы кормить, воскрешать или обучать умениям выбранного спутника.",al={"can i tame a pet now","when do i get my pet","do i need training the beast","могу ли я приручить питомца сейчас","когда я получу питомца","нужно ли обучение зверя"}},{q="Почему уход за питомцем связан с Матерью-Землей в культуре тауренов?",a="Таурены видят во всех живых существах детей Матери-Земли. Охотник не подавляет зверя одной силой воли, а вступает в духовный союз, где охотник дает пищу и заботу в обмен на верность и защиту животного.",al={"tauren pet lore","earthmother beasts","питомцы тауренов","звери матери-земли"}}},fp="18,336,27.484.0,13.429.0,33.201.0,63.180.0,53.226.0,71.272.0,66.194.0,58.257.0"}
P.entries["quest:61"] = {n="Посылка в Штормград",s="Посылка в Штормград — задание Альянса на доставку, завершающее свечное дело Вильяма Песта в Элвиннском лесу. Собрав большие восковые свечи у местных кобольдов-вредителей, герои несут упакованную посылку по дороге в Торговый квартал Штормграда к брату Вильяма, Моргану Песту.",h="Посылка в Штормград — задание Альянса на доставку, завершающее свечное дело Вильяма Песта в Элвиннском лесу.",kw={"elwynn forest","goldshire","kobold candles","morgan pestle","pestle's apothecary","shipment to stormwind","trade district","william pestle","элвиннский лес","златоземье","кобольдовы свечи","морган пест","аптека песта","посылка в штормград","торговый квартал","вильям пест"},ang={["faction:Alliance"]="Доставка припасов по королевской дороге в Штормград — классический обряд посвящения для молодых защитников Альянса, переходящих от сельских стычек к шумной столице.",["profession:Herbalism"]="Семейное дело Пестов тесно связано с местными реагентами Элвиннского леса, и заход в их лавку в Штормграде — привычная обязанность как для собирателей, так и для зельеваров."},sec={{t="Семейное дело",b="Братья Пест ведут алхимическую торговлю между сельскими деревушками Элвиннского леса и оживленными улицами Штормграда. Вильям собирает травы, реагенты и сырье в Златоземье, а его брат Морган управляет аптекой Песта в Торговом квартале столицы. Поскольку Вильям не может легко покинуть свой пост в Таверне Гордость Льва, он полагается на путников, идущих к городским воротам, в роли курьеров."},{t="От кобольдова воска к столичным зельям",b="William's parcel contains large candles gathered from kobolds in Elwynn's mines. He and Morgan run an apothecary in Stormwind, and William says he collects the candles for their wax. Delivering the shipment brings those supplies to Morgan in the Trade District."}},faq={{q="Что внутри посылки Вильяма?",a="The shipment contains candles gathered from kobolds in Elwynn Forest. William collected them for their wax and packed them for Morgan at Pestle's Apothecary.",al={"shipment contents","what is in the package","what did william send","содержимое посылки","что в посылке","что отправил вильям"}},{q="Где найти Моргана Песта?",a="Морган Пест работает в аптеке Песта в Торговом квартале Штормграда, неподалеку от главных ворот.",al={"morgan pestle location","where is morgan","find morgan pestle","где морган пест","где морган","найти моргана песта"}},{q="Кем друг другу приходятся Вильям и Морган Пест?",a="Вильям и Морган Пест — братья, вместе ведущие алхимическое дело. Вильям добывает материалы в Элвиннском лесу, а Морган управляет их лавкой в Штормграде.",al={"pestle brothers","who is william pestle brother","братья пест","брат вильяма песта"}},{q="Почему Вильям не доставляет посылку сам?",a="Вильям занят торговлей и сбором алхимических ингредиентов в Златоземье. Он предпочитает нанимать проходящих героев, которые и так направляются на север, к воротам столицы.",al={"why doesn't william go to stormwind","why hire a courier","почему вильям не идет в штормград","зачем нанимать курьера"}},{q="Есть ли у кобольдовых свечей настоящее алхимическое применение?",a="William says he and his brother need the candles for their wax. The quest does not describe the specific use they make of it at the apothecary.",al={"why kobold candles","kobold wax alchemy","зачем кобольдовы свечи","кобольдов воск алхимия"}},{q="Что будет после доставки посылки?",a="Эта доставка завершает короткую цепочку, начавшуюся со сбора кобольдовых свечей в Элвиннском лесу. Морган просто платит вам за работу курьера и приглашает заходить в его лавку.",al={"what next after shipment to stormwind","follow up quest shipment to stormwind","что дальше после посылки в штормград","продолжение задания посылка в штормград"}}},fp="21,306,14.433.0,34.261.0,34.157.0,30.135.0,42.172.0,48.189.0,48.143.0,41.182.0"}
P.entries["quest:6101"] = {n="Приручение зверя",s="Это испытание — второй этап обучения приручению питомцев для охотника-ночного эльфа под руководством Дазалара в Доланааре. Охотникам предстоит усмирить ночную саблезубую охотницу с помощью зачарованного хлыста приручения, чтобы лучше понять переменчивое многообразие диких зверей. Оно укрепляет связь понимания между дикой природой Тельдрассила и следопытами-Часовыми, ходящими под его ветвями.",h="Это испытание — второй этап обучения приручению питомцев для охотника-ночного эльфа под руководством Дазалара...",kw={"beast taming","dazalar","dolanaar","hunter","nightsaber stalker","taming rod","teldrassil","приручение зверей","дазалар","доланаар","охотник","ночная саблезубая охотница","хлыст приручения","тельдрассил"},ang={["class:Hunter"]="Этот обряд — основа обучения охотника: он учит вас уважать разнообразные звериные нравы, прежде чем вам доверят спутника на всю жизнь.",["race:NightElf"]="Ночные саблезубы тесно связаны с историей и культурой кальдораев, поэтому приручение охотницы — традиционная веха для местных лесных разведчиков."},sec={{t="Изменчивая природа зверей",b="Ранние уроки посвящены пониманию основных инстинктов, но Дазалар подчеркивает: единственная постоянная в природе — ее непрерывная изменчивость. Каждый лесной вид обладает особым нравом, и охотник должен научиться соответственно приспосабливать свою волю. В тени крон Тельдрассила это означает схватку с существами хитрыми, скрытными и куда более хищными, чем простые пауки-ткачи."},{t="Усмирение ночной саблезубой",b="Ночные саблезубы почитаются кальдораями как священные хищники, свирепые стражи и скрытные спутники Часовых. Начинающему охотнику направить силу хлыста приручения на ночную саблезубую охотницу позволяют лишь твердые нервы и спокойная властность. Обратив хищную агрессию зверя в восприимчивую связь, охотник доказывает, что способен повелевать не только кроткими или мелкими лесными существами."}},faq={{q="Для чего нужно это задание?",a="Это промежуточное испытание в цепочке охотника-ночного эльфа, открывающей постоянное приручение зверей. Дазалар посылает вас приручить ночную саблезубую охотницу, чтобы вы заметили различия в нраве разных хищных существ.",al={"why do this quest","pet taming quest 2","nightsaber taming goal","зачем выполнять задание","задание приручения питомца 2","цель приручения ночной саблезубой"}},{q="Где можно найти ночных саблезубых охотниц?",a="Ночные саблезубые охотницы бродят по лесным тропам и в подлеске к югу от Доланаара в центральной части Тельдрассила.",al={"where are nightsaber stalkers","stalker location","where to find the cat","где ночные саблезубые охотницы","где найти охотницу","где найти кошку"}},{q="Останется ли ночная саблезубая охотница моим постоянным питомцем?",a="Нет. Зверь, приручаемый хлыстом, временный и служит лишь для практики. Когда вы завершите все три части испытания и вернете хлыст, вы изучите настоящее умение приручения и сможете выбрать постоянного спутника.",al={"do i keep the pet","can i keep the nightsaber","is this my pet forever","останется ли питомец","можно ли оставить саблезубую","питомец навсегда"}},{q="Кто выдает это задание?",a="Дазалар, наставник охотников в Доланааре, что в Тельдрассиле, дает это поручение после того, как вы пройдете первое испытание приручения.",al={"quest giver","who starts this","dazalar location","персонаж, выдающий задание","кто начинает задание","где дазалар"}},{q="Почему ночные эльфы так глубоко почитают ночных саблезубых?",a="Ночные саблезубы тысячелетиями жили рядом с кальдораями как спутники, разведчики и боевые скакуны Часовых и жриц Элуны. Приручить такого зверя считается гордым признаком мастерства кальдораев в лесном деле.",al={"night elf cats lore","why nightsabers matter","lore on nightsabers","предания о кошках ночных эльфов","почему важны саблезубы","предания о ночных саблезубых"}},{q="Что будет после выполнения этого задания?",a="Дазалар даст последнее задание на приручение, связанное с другим существом Тельдрассила, а затем обучит врожденному умению приручать, кормить и содержать постоянных зверей-спутников по всему Азероту.",al={"next quest","what is after nightsaber stalker","hunter trial next","следующее задание","что после ночной саблезубой охотницы","следующее испытание охотника"}}},fp="16,377,29.399.0,23.418.0,34.227.0,39.105.0,60.230.0,21.140.0,48.213.0,38.180.0"}
P.entries["quest:6102"] = {n="Приручение зверя",s="Это задание — последнее испытание базовой подготовки юного охотника-ночного эльфа. Под руководством Дазалара в Доланааре охотники должны приручить хищную сову, прежде чем получат возможность выбрать настоящего спутника на всю жизнь.",h="Это задание — последнее испытание базовой подготовки юного охотника-ночного эльфа.",kw={"beast","dazalar","dolanaar","hunter pet","screecher","strigid screecher","taming","taming rod","teldrassil","зверь","дазалар","доланаар","питомец охотника","крикунья","совиная крикунья","приручение","хлыст приручения","тельдрассил"},ang={["class:Hunter"]="Этот обряд — порог, за которым охотник переходит от одиночной борьбы к союзу на всю жизнь с диким спутником.",["race:NightElf"]="Приручение местной живности Тельдрассила отражает путь кальдораев — жить в согласии с природой, а не подчинять ее силой."},sec={{t="Мастерство крон",b="Прежде чем завершить начальное обучение, охотники-ночные эльфы должны наладить согласие с существами из всех уголков экосистемы Тельдрассила. Уже доказав волю на зверях подлеска, охотник получает от Дазалара поручение одолеть дух небес — совиную крикунью. Эти зоркие хищные птицы гнездятся высоко в ветвях к западу от Доланаара, и чтобы усмирить их зачарованным хлыстом приручения, нужны терпение и твердые нервы."},{t="Узы охотника",b="Успех с совиной крикуньей завершает древние уроки единения охотников-кальдораев с природой. Вернув израсходованный хлыст Дазалару, ученик оставляет учебные упражнения и обретает полное искусство призыва, отпускания и постоянного приручения зверей по собственному выбору по всему Азероту."}},faq={{q="Где найти совиных крикуний?",a="Совиные крикуньи гнездятся в лесах к западу от Доланаара. Охотникам нужно искать этих хищных птиц среди крон и корней за пределами поселения, чтобы испытать свой хлыст.",al={"screecher location","where is strigid screecher","owl location","где крикунья","где совиная крикунья","где сова"}},{q="Кто такой Дазалар?",a="Дазалар — наставник охотников из ночных эльфов в Доланааре. Он наблюдает за юными кальдораями, достигшими базового уровня в стрельбе и выслеживании, и испытывает их на наземных и небесных зверях, прежде чем даровать умение связывать настоящего спутника-животное.",al={"dazalar role","who teaches pet taming dolanaar","hunter trainer dolanaar","роль дазалара","кто учит приручать питомцев в доланааре","наставник охотников доланаар"}},{q="Останется ли совиная крикунья моим питомцем?",a="Нет. Крикуньи, приручаемые в этом испытании, временны и подчинены лишь магии хлыста приручения. Когда вы сдадите задание, хлыст придется вернуть, а охотника научат приручать в дикой природе постоянного спутника по собственному выбору.",al={"keep owl","is screecher permanent","do i keep this pet","оставить сову","постоянная ли крикунья","останется ли питомец"}},{q="Что происходит после этого испытания?",a="Дазалар навсегда открывает вам умение приручать, призывать и отпускать зверей. Он также направляет вас на дальнейшее обучение в Дарнасс, где вы изучите важные искусства кормления и обучения спутника в бою.",al={"what comes next","after taming the beast","hunter pet quest finish","что дальше","после приручения зверя","конец цепочки питомца охотника"}},{q="Почему ночные эльфы приручают именно сов?",a="Хищные птицы вроде сов имеют глубокое культурное значение для кальдораев как бдительные ночные охотники и верные разведчики. Овладев существом небес, охотник доказывает, что понимает воздушных хищников наравне с наземными зверями.",al={"owl lore night elf","why owls","strigid screecher importance","предания о совах ночных эльфов","почему совы","значение совиной крикуньи"}},{q="Может ли охотник выбрать любое животное после этого задания?",a="Да. Когда Дазалар обучит постоянному приручению, охотник вправе искать любого приручаемого зверя на земле, в воде или в небе — в Тельдрассиле и за его пределами.",al={"what pets can i get","choosing first pet","any beast tameable","каких питомцев можно получить","выбор первого питомца","любой приручаемый зверь"}}},fp="16,234,21.463.0,15.320.0,35.165.0,15.244.0,49.250.0,41.205.0,42.245.0,47.160.0"}
P.entries["quest:6103"] = {n="Обучение зверя",s="Обучение зверя — завершающий обряд посвящения для начинающих охотников-ночных эльфов в Тельдрассиле. Доказав мастерство приручением диких зверей среди ветвей, охотники отправляются в Дарнасс, чтобы освоить у Иокасты более глубокие искусства ухода за питомцем и его дисциплины.",h="Обучение зверя — завершающий обряд посвящения для начинающих охотников-ночных эльфов в Тельдрассиле.",kw={"cenarion enclave","darnassus","dazalar","hunter pet","jocaste","teldrassil","training the beast","анклав кенария","дарнасс","дазалар","питомец охотника","иокаста","тельдрассил","обучение зверя"},ang={["class:Hunter"]="Этот обряд знаменует ваш путь от начинающего следопыта к истинному повелителю зверей и открывает умения обучать, кормить и воскрешать спутника.",["race:NightElf"]="Традиция дружбы кальдораев со зверями строится на уважении и сосуществовании, отражая учения, передаваемые через Дарнасс и Анклав Кенария."},sec={{t="Обряд посвящения охотника",b="Чтобы странствовать по Калимдору с верным спутником, охотник-ночной эльф должен овладеть не только хлыстом приручения. Усмирение дикого существа доказывает силу и волю, но необученный зверь остается непредсказуемой угрозой. Когда новичок проявляет способности в дикой местности вокруг Доланаара, Дазалар направляет его в Дарнасс завершить обучение."},{t="Наставления в Анклаве Кенария",b="В тихих рощах Анклава Кенария почитаемая охотница Иокаста передает основы искусства общения со спутником. Она учит юного охотника правильно кормить питомца, воскрешать его в случае беды и развивать его боевые инстинкты. Для ночных эльфов эти отношения основаны на глубоком благоговении перед природой, а не на простом господстве."}},faq={{q="Для чего нужно это задание?",a="Это задание завершает начальную цепочку питомца охотника у ночных эльфов. Оно направляет вас в Дарнасс, чтобы открыть основные умения, нужные для ухода за постоянным спутником-животным и его обучения.",al={"why do this quest","pet training quest night elf","what does training the beast do","зачем выполнять задание","задание обучения питомца ночной эльф","что дает обучение зверя"}},{q="Где найти Иокасту?",a="Иокаста находится в Дарнассе, в Анклаве Кенария, среди высоких деревьев и охотничьих домов в северо-западной части столицы.",al={"where is jocaste","jocaste location","find jocaste","где иокаста","местонахождение иокасты","найти иокасту"}},{q="Кто выдает это задание?",a="Дазалар, наставник охотников в Доланааре, предлагает это задание после того, как вы пройдете все три этапа испытаний приручения в Тельдрассиле.",al={"quest giver","who gives training the beast","dazalar location","персонаж, выдающий задание","кто дает обучение зверя","где дазалар"}},{q="Какие умения вы изучаете у Иокасты?",a="Беседа с Иокастой открывает основы повелевания зверями: кормление спутника, его оживление после гибели в бою и обучение новым способностям.",al={"what abilities do i get","jocaste rewards","hunter pet spells","какие умения я получу","награды иокасты","заклинания питомца охотника"}},{q="Почему культура ночных эльфов придает такое значение обучению питомцев?",a="Охотники-кальдораи видят в питомцах партнеров, а не покорные орудия. Правильное обучение и уход отражают главную философию этого народа — жить в равновесии с природой и благоговеть перед ней.",al={"night elf hunter lore","why train beasts night elf","предания об охотниках ночных эльфов","зачем ночным эльфам обучать зверей"}},{q="Доступно ли это задание другим расам?",a="Это путешествие в Дарнасс уникально для охотников-ночных эльфов. Охотники других рас проходят равноценные обряды обучения у собственных наставников.",al={"can dwarves do this","can horde do training the beast","могут ли дворфы","может ли орда выполнить обучение зверя"}}},fp="18,265,26.403.0,32.383.0,34.188.0,24.149.0,21.135.0,38.161.0,50.175.0,39.151.0"}
P.entries["quest:6121"] = {n="Новый урок",s="«Новый урок» — вводное задание, которое молодым друидам Альянса выдает Матренгил Медвежья Лапа в Дарнассе. Оно направляет посвященных в священное убежище Лунную поляну, где они встретятся с Дендритом Блеском Звезд и начнут обучение искусству очищения от яда и токсинов.",h="«Новый урок» — вводное задание, которое молодым друидам Альянса выдает Матренгил Медвежья Лапа в Дарнассе.",kw={"auberdine","cenarius","cure poison","dendrite starblaze","lessons anew","mathrengyl bearwalker","moonglade","nighthaven","power over poison","аубердин","кенарий","устранение яда","дендрит блеск звезд","новый урок","матренгил медвежья лапа","лунная поляна","ночная гавань","власть над ядом"},ang={["class:Druid"]="Этот обряд знаменует ваш переход от простых превращений и выживания к истинной опеке над дикой природой: вы учитесь снимать с нее смертельные поветрия и яды.",["faction:Alliance"]="Кризис, угрожающий Аубердину, показывает, насколько важна помощь друидов для защиты хрупких северных поселений Альянса на Темных берегах.",["race:NightElf"]="Это задание, выдаваемое в Анклаве Кенария в Дарнассе, напрямую связывает юных кальдораев с более глубокими древними обязанностями Лунной поляны и Темных берегов."},sec={{t="Дар Кенария",b="Друиды связаны священной связью с живым миром, унаследованной через учения и благословения полубога Кенария. Среди этих даров — способность очищать от мерзких ядов простым заклинанием. Однако такие могущественные дары не вручают посвященным легкомысленно. Чтобы по-настоящему ценить чудесную легкость своей магии, молодые друиды должны сначала постичь кропотливый будничный труд борьбы с ядами без прямого вмешательства природы."},{t="Вызов в Ночную Гавань",b="Матренгил Медвежья Лапа, наставник друидов в Анклаве Кенария в Дарнассе, велит своему ученику обойти местную практику и отправиться прямо на Лунную поляну. Там, в тихой деревне Ночная Гавань, Дендрит Блеск Звезд координирует более широкие усилия Круга Кенария и готов поручить новичку срочное практическое дело."},{t="Настоящий кризис",b="Прибыв в Ночную Гавань, посвященные узнают, что их испытание не будет ни устроенной проверкой, ни заранее написанным ритуалом. Поселение Аубердин на побережье Темных берегов столкнулось с сильной вспышкой отравлений животных, остановить которую местные бессильны. Дендрит Блеск Звезд поручает новичку расследовать происходящее и помочь Темным берегам, бросая его прямо в настоящий кризис, где на кону стоят жизни."}},faq={{q="Кто выдает задание «Новый урок»?",a="Задание выдает Матренгил Медвежья Лапа, наставник друидов из ночных эльфов в Анклаве Кенария в Дарнассе.",al={"who gives lessons anew","lessons anew quest giver","mathrengyl bearwalker quest","кто дает новый урок","кто выдает задание новый урок","задание матренгила медвежьей лапы"}},{q="Куда нужно отправиться для выполнения этого задания?",a="Вы должны отправиться в священные друидические земли Лунной поляны и доложить Дендриту Блеску Звезд, который находится в мирной деревне Ночная Гавань.",al={"where do i go","where is dendrite starblaze","lessons anew turn in","куда идти","где дендрит блеск звезд","сдача задания новый урок"}},{q="Почему друиды сначала должны учиться лечить яды как простые люди?",a="Наставники-друиды считают, что чудесный дар Кенария — исцелять от яда одним заклинанием — может породить самодовольство. Заставляя посвященных сначала изучать и разрешать отравления травами и обычными способами, они добиваются, чтобы друид по-настоящему уважал бремя и страдания, которые причиняет яд.",al={"why layman","why cure poison without magic","cenarius poison lesson","почему без магии","почему лечить яд без магии","урок кенария об яде"}},{q="Что за беда случилась в Аубердине?",a="Аубердин страдает от вспышки тяжелых отравлений животных на побережье Темных берегов. Местные ночные эльфы не смогли излечить недуг и отправили мольбу о помощи Кругу Кенария на Лунной поляне.",al={"auberdine poison problem","what is happening in auberdine","darkshore animal poisonings","проблема с ядом в аубердине","что происходит в аубердине","отравления животных на темных берегах"}},{q="Какое умение в итоге дает эта цепочка заданий?",a="Это задание открывает цепочку «Власть над ядом», которая учит друидов важному заклинанию «Устранение яда» и позволяет магически очищать союзников от токсинов.",al={"what reward do i get","cure poison quest","power over poison chain","какая награда","задание устранения яда","цепочка власть над ядом"}},{q="Доступно ли это задание друидам Орды?",a="Нет. «Новый урок» — именно версия задания для Альянса, начинающаяся в Дарнассе. Друиды-таурены получают параллельное задание в Громовом Утесе, которое тоже направляет их на Лунную поляну изучать искусство лечения от яда.",al={"horde lessons anew","can tauren do this","tauren lessons anew","новый урок орда","могут ли таурены","новый урок таурены"}}},fp="12,273,20.462.0,21.348.0,19.409.1,34.120.0,45.147.0,58.296.0,42.236.0,52.157.0,40.227.0"}
P.entries["quest:6122"] = {n="Основной источник",s="Задание «Основной источник» — важный обряд посвящения для молодых ночных эльфов-друидов, которые учатся понимать и исцелять природный мир. Посланные из Лунной поляны Дендритом Блеском Звезд, посвящаемые должны набрать оскверненной воды у Водопада Скалистого на Темных берегах, чтобы помочь натуралисту из Аубердина Аландариан Песне Ночи остановить распространяющуюся среди лесных оленей болезнь.",h="Задание «Основной источник» — важный обряд посвящения для молодых ночных эльфов-друидов, которые учатся...",kw={"alanndarian nightsong","auberdine","cenarion circle","cliffspring falls","cure poison","darkshore","dendrite starblaze","naga","power over poison","аландариан песня ночи","аубердин","круг кенария","водопад скалистый","устранение яда","темные берега","дендрит блеск звезд","наги","власть над ядом"},ang={["class:Druid"]="Это задание — часть основополагающего испытания друидов. Противостоя разложению природы у Водопада Скалистого и составляя лекарства, вы пробуждаете духовные и ботанические знания, нужные для излечения от ядов в дикой природе.",["race:NightElf"]="Для кальдораев Аубердина порча Водопада Скалистого — прямое осквернение их исконных лесов, требующее немедленного вмешательства ради защиты невинных существ этой земли."},sec={{t="Оскверненный жизненно важный водоток",b="Водопад Скалистый — основной источник пресной воды для северной части Темных берегов. Когда дикие животные, особенно местные олени, начали гибнуть от неестественного затяжного недуга, Круг Кенария обратил внимание на реку. Предполагая, что заражен сам водоносный слой, Дендрит Блеск Звезд в Лунной поляне поручает начинающим друидам важное дело: добраться до входа в пещеру под водопадом и взять чистый образец отравленной воды."},{t="Тени у водопада",b="Брать воду опасно. Свирепые наги обосновались в пещере у Реки Скалистой и гнездятся у самых истоков водопада. Их присутствие у подземного родника напрямую угрожает всем, кто расследует причину порчи. Несмотря на опасность, взять незагрязненный образец у входа в пещеру — единственный способ для Круга Кенария изучить то, что поражает дикую природу."},{t="Более глубокий недуг",b="Когда образец доставлен Аландариан Песня Ночи в Аубердин, мерзость воды подтверждает худшие опасения Круга. Но осмотр отравленной жидкости открывает тревожную истину: хотя оскверненный водопад действительно главный источник яда для берегов реки, больных оленей замечали далеко за пределами его русла. Вода служит важным реагентом для создания противоядия, однако Аландариан подозревает, что более глубокая и широкая порча расползается по всем грунтовым водам Темных берегов."}},faq={{q="Почему Водопад Скалистый так важен для Темных берегов?",a="Водопад Скалистый — главный природный источник питьевой воды для севера Темных берегов. Его потоки питают местные ручьи и реки, а также окружающие растения и животных, поэтому любая зараза у истоков быстро распространяется по всей округе.",al={"why cliffspring falls matters","cliffspring river importance","darkshore water source","почему важен водопад скалистый","значение реки скалистой","источник воды темных берегов"}},{q="Почему олени на Темных берегах болеют?",a="Местные олени пьют прямо из Водопада Скалистого и питаемых им ручьев. Опасная зараза отравила грунтовые воды у истока, и лесные звери страдают от тяжелой изнуряющей болезни.",al={"why are deer sick","darkshore sick deer","what poisoned the deer","почему больны олени","больные олени темных берегов","что отравило оленей"}},{q="Кто такой Дендрит Блеск Звезд?",a="Дендрит Блеск Звезд — старший наставник друидов, живущий в священном убежище Лунная поляна. Он направляет восходящих друидов, следит за бедствиями по всему Калимдору и координирует действия Круга Кенария при природных кризисах.",al={"dendrite starblaze lore","who gave me this quest","starblaze moonglade","дендрит блеск звезд предания","кто выдал это задание","блеск звезд лунная поляна"}},{q="Кто такая Аландариан Песня Ночи?",a="Аландариан Песня Ночи — ночной эльф, натуралистка, живущая в Аубердине. Встревоженная распространением порчи и страданиями животных на Темных берегах, она обратилась к Кругу Кенария в Лунной поляне за помощью опытных друидов, чтобы изучить недуг и создать лекарство.",al={"who is alanndarian nightsong","nightsong auberdine","кто такая аландариан песня ночи","песня ночи аубердин"}},{q="Почему у Водопада Скалистого наги?",a="Наги с побережья Темных берегов продвинулись вглубь суши и заняли систему пещер за Водопадом Скалистым. Их присутствие создает огромную опасность для всех, кто пытается добраться до истоков, чтобы исследовать воду.",al={"naga in cliffspring cave","why are naga here","cliffspring falls naga","наги в пещере скалистой","почему здесь наги","наги водопад скалистый"}},{q="Какому умению это задание учит друидов?",a="Это расследование — часть испытания «Власть над ядом». Определяя причину болезни животных и создавая противоядие вместе с Аландариан Песня Ночи, молодые друиды учатся важному магическому искусству излечения от ядов.",al={"what spell does this give","druid poison quest","cure poison chain","какое заклинание дает","задание друида на яд","цепочка устранения яда"}}},fp="20,354,26.501.0,20.422.0,15.507.1,51.280.0,42.223.0,26.234.0,29.262.0,34.233.0,47.220.0"}
P.entries["quest:6125"] = {n="Власть над ядом",s="«Власть над ядом» — завершение испытания юного друида, посвященного овладению искусством борьбы с ядами. Научившись вручную готовить травяное снадобье в Темных берегах, посвящаемый возвращается в Дарнасс, чтобы получить от Круга Кенария магическое благословение, позволяющее очищать от токсинов по своей воле.",h="«Власть над ядом» — завершение испытания юного друида, посвященного овладению искусством борьбы с ядами.",kw={"auberdine","cenarion enclave","cure poison","darnassus","dendrite starblaze","mathrengyl bearwalker","moonglade","power over poison","аубердин","анклав кенария","устранение яда","дарнасс","дендрит блеск звезд","матренгил медвежья лапа","лунная поляна","власть над ядом"},ang={["class:Druid"]="Этот обряд посвящения соединяет скромное травничество со священной целительной магией и отмечает момент, когда друид обретает прямую власть нейтрализовать яд милостью природы.",["race:NightElf"]="Это испытание, проходящее в Анклаве Кенария в Дарнассе, отражает почтение кальдораев к равновесию и их суровую заботу о древних лесах."},sec={{t="Смирение ученика",b="Прежде чем даровать друиду врожденную магическую способность выводить яды, Круг Кенария требует, чтобы посвящаемые поняли страдания простых людей. В Темных берегах Аландариан Песня Ночи поручает юным последователям самим собрать корень земли и лунный гриб и сварить обычную мазь для лечения пострадавших животных. Этот урок гарантирует, что, направляя силу природы на исцеление от яда, друид делает это с глубоким состраданием к тем, кому приходится бороться с отравой без духовной помощи."},{t="Возвращение в Анклав",b="Когда обычное лекарство доказало свою эффективность в Аубердине, Блеск Звезд отправляет друида обратно через море в Дарнасс. Среди ветвей Анклава Кенария его ожидает Матренгил Медвежья Лапа. Довольный выдержкой посвящаемого в трудных условиях, Матренгил официально передает ему искусство природного очищения, дающее постоянную власть над ядами. Но испытание приносит и тревожную весть: присутствие губительных ядов в глуши вокруг Аубердина указывает на неестественную порчу, нарушающую хрупкое равновесие этих земель."}},faq={{q="Каково назначение этого задания?",a="Это задание завершает испытание друидов по излечению от ядов. Успешно приготовив для Дендрита Блеска Звезд обычное лечебное снадобье в Лунной поляне и Темных берегах, ученик возвращается к Матренгилу Медвежьей Лапе в Дарнасс, чтобы изучить врожденное заклинание «Устранение яда».",al={"why do power over poison","power over poison objective","cure poison quest","зачем нужна власть над ядом","цель задания власть над ядом","задание устранение яда"}},{q="Кто такой Дендрит Блеск Звезд?",a="Дендрит Блеск Звезд — старейшина-друид, живущий в священной обители Ночная Гавань в Лунной поляне. Он наставляет посвящаемых в их духовных испытаниях, проверяя их терпение и преданность природе, прежде чем отправить обратно к их наставникам.",al={"dendrite starblaze role","who gives power over poison","дендрит блеск звезд роль","кто выдает власть над ядом"}},{q="Кто такой Матренгил Медвежья Лапа?",a="Матренгил Медвежья Лапа — мастер-наставник друидов, живущий в Анклаве Кенария в Дарнассе. Он следит за развитием ночных эльфов-друидов среди ветвей Тельдрассила, обучая их формам, искусству исцеления и суровым обязанностям Круга Кенария.",al={"mathrengyl bearwalker lore","bearwalker darnassus","матренгил медвежья лапа предания","медвежья лапа дарнасс"}},{q="Почему друиду сначала нужно было приготовить лекарство вручную?",a="Дендрит Блеск Звезд учит, что друид должен понять, какой урон наносит яд и какой труд требуется, чтобы лечить его без магии. Собирая простые ингредиенты и помогая больным своими руками, посвящаемый учится смирению и ценит дары природы, которые ему предстоит получить.",al={"why make herbal cure","lesson of power over poison","зачем делать травяное лекарство","урок власти над ядом"}},{q="Что беспокоит Матренгила в положении дел в Аубердине?",a="Матренгил отмечает, что внезапное появление смертельных токсинов в глуши Темных берегов вокруг Аубердина неестественно. Нарушения в жизни местных животных и растений угрожают экологическому равновесию, что говорит о действии порочной силы вдоль туманного побережья.",al={"auberdine poison lore","mathrengyl concern","яд в аубердине предания","беспокойство матренгила"}}},fp="17,269,22.487.0,21.526.0,34.268.0,26.243.0,29.255.0,56.291.0,58.255.0"}
P.entries["quest:6126"] = {n="Новый урок",s="«Новый урок» — обряд посвящения юных друидов-таурен, который начинает Тюрак Рунический Тотем на Вершине Старейшин в Громовом Утесе. Ученикам предписано отправиться в священную обитель Лунная поляна, чтобы начать осваивать искусство очищения от природных и неестественных ядов. Под руководством ночного эльфа Дендрита Блеска Звезд этот урок отказывается от учебных испытаний в пользу борьбы с настоящим кризисом отравлений.",h="«Новый урок» — обряд посвящения юных друидов-таурен, который начинает Тюрак Рунический Тотем на Вершине...",kw={"cenarion circle","crossroads","cure poison","dendrite starblaze","lessons anew","moonglade","nighthaven","turak runetotem","круг кенария","перекресток","устранение яда","дендрит блеск звезд","новый урок","лунная поляна","ночная гавань","тюрак рунический тотем"},ang={["class:Druid"]="Это задание отмечает ваш переход от основ звериных обликов и стычек к истинной заботе о дикой природе и начинает путь к овладению заклинанием «Устранение яда».",["faction:Horde"]="Пока воины Орды сражаются с ночными эльфами в Ясеневом лесу, друиды Орды находят безопасное убежище в Лунной поляне под священным покровительством Круга Кенария.",["race:Tauren"]="Для таурен это паломничество показывает, как глубоко дети Матери-Земли вновь прониклись учением Кенария наравне со своими собратьями ночными эльфами."},sec={{t="Дар Кенария",b="Друиды несут священный долг защищать дикую природу, и к нему относится чудесная способность, дарованная Кенарием, — выводить губительные яды простым заклинанием. Однако такая могучая магия не дается без подготовки. Тюрак Рунический Тотем настаивает, что прежде чем направлять божественные силы на легкое рассеивание порчи, друид должен понять, какой урон наносит яд, и научиться лечить его обычными, земными средствами."},{t="Призыв в Ночную Гавань",b="Вместо того чтобы вести обучение только на утесах Мулгора, многообещающих учеников отправляют на север по священным тропам в Лунную поляну. Там, в мирной деревне Ночная Гавань, древние наставники-ночные эльфы, такие как Дендрит Блеск Звезд, руководят обучением и эльфов, и таурен. Это совместное обучение показывает хрупкое перемирие в Круге Кенария, стоящем выше политических распрей между Ордой и Альянсом."},{t="Настоящий кризис в Степях",b="Если прежние посвященные отрабатывали обряды очищения в контролируемых условиях, то Блеску Звезд некогда заниматься искусственными упражнениями. Вблизи Перекрестка в засушливых Степях вспыхнула неконтролируемая волна отравлений животных. Отчаянная просьба о помощи с Перекрестка превращает учебный обряд посвящения в срочное полевое задание, требующее от молодых друидов лично столкнуться со страданиями диких зверей."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Тюрак Рунический Тотем, наставник друидов-таурен на Вершине Старейшин в Громовом Утесе. Он призывает посвящаемых, которые доказали свою раннюю преданность учению Кенария.",al={"who gives lessons anew","where to get lessons anew","lessons anew quest giver","кто выдает новый урок","где взять новый урок","новый урок задание"}},{q="Кто такой Дендрит Блеск Звезд?",a="Дендрит Блеск Звезд — старейшина-друид из ночных эльфов, живущий в Ночной Гавани в Лунной поляне. Несмотря на общую вражду между ночными эльфами и таурен, он наставляет юных друидов обеих рас в традициях Круга Кенария.",al={"who is dendrite","dendrite starblaze role","who is the night elf in moonglade","кто такой дендрит","дендрит блеск звезд роль","кто ночной эльф в лунной поляне"}},{q="Какой силе меня учит это задание?",a="Эта цепочка заданий начинает ваше обучение заклинанию «Устранение яда». Она учит друидов понимать физическую и магическую природу яда, позволяя им снимать вредные недуги с союзников и диких существ, находящихся на их попечении.",al={"what ability do i learn","what spell is this for","curing poison quest","какую способность я изучу","для какого заклинания это","задание излечение от яда"}},{q="Почему тауренам приходится учиться у ночного эльфа?",a="Круг Кенария — нейтральное братство, посвященное равновесию природы. Хотя ночные эльфы первыми оформили современное друидизм под руководством Кенария, они приняли таурен обратно в орден и делят с ними священные места вроде Лунной поляны, несмотря на войну фракций.",al={"why night elf trainer","tauren night elf druids","cenarion circle faction","почему наставник ночной эльф","таурены ночные эльфы друиды","круг кенария фракция"}},{q="Что происходит на Перекрестке?",a="Местных животных вокруг Перекрестка в Степях терзает яростная волна отравлений, с которой местные смотрители не справляются. Дендрит Блеск Звезд направляет ваше обучение прямо в поля, чтобы найти источник и приготовить лекарство.",al={"crossroads problem","what is poisoning the animals","crossroads sickness","проблема перекрестка","что травит животных","болезнь на перекрестке"}},{q="Как быстрее всего добраться до Лунной поляны для этого задания?",a="Как друид, вы владеете врожденным заклинанием «Телепортация: Лунная поляна», которое переносит вас прямо в убежище Ночной Гавани, избавляя от необходимости пешком идти по опасным спорным землям.",al={"how to get to moonglade","travel to nighthaven","teleport moonglade","как добраться до лунной поляны","путь в ночную гавань","телепортация лунная поляна"}}},fp="12,403,20.427.0,21.458.0,28.418.1,47.199.0,26.236.0,37.234.0,50.276.0,36.257.0,59.191.0"}
P.entries["quest:6127"] = {n="Основной источник",s="«Основной источник» — задание друидов Орды, которое выдает Дендрит Блеск Звезд на Лунной поляне. Оно отправляет начинающих друидов на Вершину Багрового Тумана на севере Степей, чтобы набрать пробу оскверненной воды из источника и доставить ее Тонге Руническому Тотему на Перекресток. Эта проба помогает понять природу яда, который распространяется среди местных животных.",h="«Основной источник» — задание друидов Орды, которое выдает Дендрит Блеск Звезд на Лунной поляне.",kw={"barrens","cenarion circle","crossroads","dendrite starblaze","dreadmist peak","power over poison","principal source","sickly gazelle","tonga runetotem","степи","круг кенария","перекресток","дендрит блеск звезд","вершина багрового тумана","власть над ядом","основной источник","больная газель","тонга рунический тотем"},ang={["class:Druid"]="Этот обряд посвящения — важный шаг на вашем пути защитника дикой природы: он доказывает, что вы способны проследить порчу до источника и выделить магические токсины, пока они не погубили всю экосистему.",["faction:Horde"]="Перекресток — логистическое сердце присутствия Орды в Калимдоре, поэтому беспрепятственное распространение демонической порчи прямо у ее порога представляет непосредственную угрозу торговле и выживанию.",["race:Tauren"]="Степи — родовые земли племен Калимдора; очищение воды помогает защитить от демонической скверны стада газелей, веками кормившие ваш народ."},sec={{t="Оскверненная гора",b="Вершина Багрового Тумана возвышается к северо-западу от Перекрестка, и ее высокие источники и водоемы влияют на погоду и влажность засушливых северных Степей. К несчастью, поклоняющиеся демонам сектанты из Пылающего Клинка обосновались на ее скалах. Дендрит Блеск Звезд понимает, что мерзкое колдовство на такой важной природной высоте может отравить всю окружающую долину."},{t="Мор на равнинах",b="По северной саванне видели больных газелей, бредущих к северу от главной дороги, идущей с востока на запад через Перекресток. Тонга Рунический Тотем, прося помощи от имени местных таурен, обратился к Кругу Кенария, чтобы выяснить, что травит стадо. Взойдя на вершину и добыв чистую пробу оскверненной воды, друиды дают Тонге важнейший катализатор для анализа недуга и приготовления противоядия."}},faq={{q="Где взять пробу воды для этого задания?",a="Воду нужно набрать из водоема на самой вершине Вершины Багрового Тумана, к северо-западу от Перекрестка в Степях. Вам нужно добраться до горного водоема, где собираются сектанты Пылающего Клинка, и воспользоваться пробоотборником, который выдал Дендрит Блеск Звезд.",al={"dreadmist peak pool location","where is the water pool","principal source water sample","где водоем вершины багрового тумана","где водоем с водой","проба воды основной источник"}},{q="Почему вода на Вершине Багрового Тумана так важна для Степей?",a="На открытых высотах Вершины Багрового Тумана находятся водоемы, напрямую влияющие на местную погоду и туман. Когда сектанты-демонопоклонники оскверняют эти воды, отравленный пар и стоки спускаются вниз и портят равнины, заражая животных по всем северным Степям.",al={"why dreadmist peak matters","barrens weather pool","dreadmist peak pools","почему важна вершина багрового тумана","погода степей водоем","водоемы вершины багрового тумана"}},{q="Who is Tonga Runetotem?",a="Тонга Рунический Тотем — друид-таурен на Перекрестке в Степях. Глубоко встревоженный неестественными недугами, распространяющимися среди местных газелей, он обратился к Кругу Кенария в Лунной поляне с просьбой помочь определить причину и очистить землю.",al={"who is tonga","tonga runetotem role","crossroads druid","кто такой тонга","тонга рунический тотем роль","друид перекрестка"}},{q="Кто портит воду на вершине?",a="Воду осквернил Пылающий Клинок — тайный культ чернокнижников-демонопоклонников и приверженцев скверны, занявших извилистые тропы и вершину Вершины Багрового Тумана.",al={"who tainted the pool","dreadmist cultists","burning blade dreadmist","кто осквернил водоем","сектанты багрового тумана","пылающий клинок багровый туман"}},{q="Какой способности учит эта цепочка заданий?",a="Это поручение — часть более крупного обряда «Власть над ядом» для юных друидов Орды, который завершается овладением духовными и травными знаниями, необходимыми для излечения от ядов в полевых условиях.",al={"power over poison reward","druid poison cure spell","cure poison quest barrens","награда власть над ядом","заклинание друида от яда","задание устранение яда степи"}},{q="Могут ли друиды Альянса выполнить это задание?",a="Нет. «Основной источник» — это именно версия испытания для Орды: игроки отправляются в Степи, чтобы помочь Тонге Руническому Тотему. Друиды Альянса проходят такой же путь на Темных берегах, чтобы получить умения очищения от яда.",al={"alliance equivalent","can night elves do principal source","alliance poison quest","аналог для альянса","могут ли ночные эльфы основной источник","задание альянса от яда"}}},fp="20,346,18.429.0,22.428.0,47.253.0,63.265.0,23.253.0,40.184.0,46.185.0,34.232.0"}
P.entries["quest:6128"] = {n="Создание лекарства",s="«Создание лекарства» — священный обряд посвящения для молодых таурен-друидов, расположенных на Перекрестке. По поручению Тонги Рунического Тотема друид собирает землекорень и прочные рога кодо, чтобы приготовить целебную мазь для отравленных газелей Степей.",h="«Создание лекарства» — священный обряд посвящения для молодых таурен-друидов, расположенных на Перекрестке.",kw={"barrens","crossroads","druid quest","earthroot","gathering the cure","gazelle","kodo horn","salve","tonga runetotem","степи","перекресток","задание друида","землекорень","создание лекарства","газель","рог кодо","мазь","тонга рунический тотем"},ang={["class:Druid"]="Это задание — часть важнейших испытаний, в которых друиды учатся выходить за пределы смертного травничества и направлять магию природы, чтобы изгонять яды напрямую.",["faction:Horde"]="Помощь Тонге защищает диких животных вокруг Перекрестка и обеспечивает устойчивую экосистему вокруг опорного пункта в сердце земель Орды.",["profession:Herbalism"]="Задание требует землекорня и напоминает о неизменной ценности сбора диких целебных корней на скалистых склонах саванны."},sec={{t="Рецепт для облегчения",b="Раздобыв образец воды с Вершины Багрового Тумана, Тонга Рунический Тотем нуждается в сырых реагентах, чтобы сварить действенное физическое противоядие. Природная вода служит основой мази, обычный землекорень придает ей основные лечебные свойства, а толченый рог кодо дает смеси восстанавливающую силу, способную изгнать яд из тела существа. Для молодого друида добыча этих ингредиентов означает полагаться на дары земли и охотиться на местных зверей."},{t="Уроки очищения",b="Алхимия и знание трав — традиционные способы противодействия определенным токсинам, но для каждого особого яда обычно требуется точное, подобранное средство. Тонга использует это трудоемкое приготовление, чтобы показать посвящаемым пределы физических лекарств. Истинное мастерство над природными ядами заключается не в том, чтобы носить с собой бесконечное множество сушеных трав и рогов, а в том, чтобы настроиться непосредственно на исцеляющие силы природы — глубокий урок, ведущий прямо к друидическому искусству «Излечение от яда»."}},faq={{q="Какие ингредиенты нужны Тонге Руническому Тотему?",a="Тонга просит пять пучков землекорня и пять целых рогов кодо. Землекорень дает целебные свойства трав, а рога обеспечивают силу, необходимую, чтобы противостоять токсинам, поражающим местных газелей.",al={"gathering the cure items","what reagents do i need","cure materials","ингредиенты для создания лекарства","какие реагенты мне нужны","материалы для лекарства"}},{q="Где найти рога кодо?",a="Кодо бродят по засушливым равнинам северных и центральных Степей и часто пасутся у дорог вокруг Перекрестка. Тонга подчеркивает, что для мази подойдут только целые, прочные рога этих зверей, а не хрупкие осколки.",al={"where are the kodos","kodo horn location","finding kodos in the barrens","где кодо","где взять рога кодо","поиск кодо в степях"}},{q="Нужно ли быть травником, чтобы добыть землекорень?",a="Нет, самому владеть профессией травознания не нужно. Травники собирают землекорень на утесах и скалистых выступах по всем Степям, а друиды, если не умеют собирать его сами, могут получить его у других путников или на торговых постах.",al={"do i need herbalism","gathering earthroot without herbalism","earthroot profession requirement","нужно ли травознание","сбор землекорня без травознания","землекорень требования профессии"}},{q="Зачем Тонга готовит физическую мазь?",a="Тонга готовит физическое противоядие, чтобы лечить отравленных газелей, страдающих по всем северным Степям. Кроме того, кропотливое изготовление обычных лекарств помогает ему показать огромное преимущество врожденных магических заклинаний очищения.",al={"why make an antidote","purpose of the salve","why not use magic","зачем делать противоядие","назначение мази","почему не использовать магию"}},{q="Кто такой Тонга Рунический Тотем?",a="Тонга Рунический Тотем — старший таурен-друид, находящийся на Перекрестке в Степях. Он исследует порчу, распространяющуюся по водам региона, и наставляет молодых друидов в постижении равновесия природы.",al={"who gives gathering the cure","tonga runetotem role","who is tonga","кто выдает создание лекарства","роль тонги рунический тотем","кто такой тонга"}},{q="Что происходит после сбора этих ингредиентов?",a="Когда Тонга варит целебную мазь из реагентов, он отправляет друида в саванну, чтобы тот нанес смесь прямо на больных газелей. Так лекарство проверяется до того, как друид узнает о более глубоком искусстве магического очищения.",al={"what follows gathering the cure","gathering the cure next quest","after gathering the cure","что после создания лекарства","создание лекарства следующее задание","после создания лекарства"}}},fp="18,244,19.464.0,20.467.0,46.224.0,34.236.0,49.256.0,40.267.0,23.217.0,45.223.1"}
P.entries["quest:6129"] = {n="Исцеление больных",s="«Исцеление больных» — важное испытание для молодых друидов Орды: им нужно вылечить больных животных в северных Степях. Нанося свежеприготовленную травяную мазь на хворающих газелей, посвящаемые показывают и практические навыки полевой медицины, и верность сохранению природного равновесия. Выполнив этот долг, они доказывают свою преданность Кругу Кенария в Лунной поляне.",h="«Исцеление больных» — важное испытание для молодых друидов Орды: им нужно вылечить больных животных в...",kw={"barrens","cenarion circle","crossroads","curative animal salve","cure poison","curing the sick","dendrite starblaze","moonglade","sickly gazelle","tonga runetotem","степи","круг кенария","перекресток","мазь исцеления животных","излечение от яда","исцеление больных","дендрит блеск звезд","лунная поляна","больная газель","тонга рунический тотем"},ang={["class:Druid"]="Этот обряд исцеления знаменует ваш переход от ученика травознания к деятельному хранителю природы и доказывает вашу готовность применять магию жизни против смертельных ядов.",["faction:Horde"]="Леча больных животных у Перекрестка, друиды-таурены помогают защищать важные охотничьи угодья и пути сообщения, на которых держится присутствие Орды в центральном Калимдоре.",["race:Tauren"]="Пока ваш народ возрождает древние связи с Кругом Кенария, исцеление Степей доказывает, что дети Матери-Земли — достойные хранители равновесия."},sec={{t="Мор среди стад",b="По северной саванне Степей пасущиеся газели начали гибнуть от неестественной болезни. Собрав землекорень и рога кодо для приготовления лекарства, Тонга Рунический Тотем на Перекрестке поручает молодому друиду провести лечение на местах. Посвящаемому нужно отправиться к северу от главного перекрестка, найти десять страдающих животных и немедленно облегчить их муки, пока гниль не укоренилась в экосистеме глубже."},{t="Благословение Круга",b="Когда мазь использована, путь друида ведет обратно в безмятежные ветви Лунной поляны. Там Дендрит Блеск Звезд отмечает сострадание и бдительность посвящаемого. Он говорит, что страдания газелей — лишь признак более глубокой, коварной порчи, подкрадывающейся к дикой природе Калимдора. Заботясь о самых скромных зверях, друиды-таурены показывают, что почитание Кенария выходит за границы племен, и получают более глубокие тайны очищения от яда и магии природы."}},faq={{q="Где найти больных газелей?",a="Больные газели бродят по засушливым равнинам северных Степей, главным образом к северу от главной торговой дороги с востока на запад, пересекающейся на Перекрестке.",al={"gazelle location","where are sick gazelles","barrens gazelles","где газели","где больные газели","газели в степях"}},{q="Кто выдает это задание?",a="Задание выдает Тонга Рунический Тотем, таурен-друид на Перекрестке в Степях. Он же снабжает вас предметом «Мазь исцеления животных» после того, как вы выполните его поручение по сбору реагентов.",al={"who gives curing the sick","quest giver","tonga runetotem location","кто выдает исцеление больных","персонаж, выдающий задания","где тонга рунический тотем"}},{q="Кому сообщить после лечения животных?",a="Вы сдаете задание Дендриту Блеску Звезд в друидическом святилище Лунной поляны, добираясь до священной рощи с помощью телепортации.",al={"where do i turn this in","quest turn in","dendrite starblaze location","где сдать это задание","сдача задания","где дендрит блеск звезд"}},{q="Почему Круг Кенария интересуется Степями?",a="Круг Кенария следит за гармонией земель. Болезнь, распространяющаяся среди диких газелей, отражает повсеместную порчу, ползущую по Калимдору и грозящую нарушить природный порядок, если ее не остановить.",al={"why druids care about barrens","cenarion circle barrens","почему друиды заботятся о степях","круг кенария степи"}},{q="Какую способность открывает эта цепочка заданий?",a="Это испытание — вторая половина друидического обряда посвящения, который в итоге дарует посвящаемому способность очищать от ядов и токсинов себя и союзников.",al={"cure poison quest reward","why do this quest druid","награда за задание излечение от яда","зачем выполнять задание друиду"}},{q="Могут ли не друиды вылечить этих газелей?",a="Нет. Эта линейка заданий доступна только друидам и служит особым классовым испытанием под непосредственным надзором Круга Кенария.",al={"is this druid only","who can do curing the sick","только ли для друидов","кто может выполнить исцеление больных"}}},fp="15,397,23.459.0,21.483.0,36.158.0,22.180.0,44.140.0,53.218.0,42.180.0,35.122.0"}
P.entries["quest:6130"] = {n="Власть над ядом",s="«Власть над ядом» — завершающий обряд в испытании молодого друида Орды, посвященном овладению целительной магией природы. Вылечив газелей у Перекрестка одними травяными смесями, посвящаемый возвращается к Тюраку Руническому Тотему на Вершине Старейшин в Громовом Утесе, чтобы получить истинный дар — «Излечение от яда».",h="«Власть над ядом» — завершающий обряд в испытании молодого друида Орды, посвященном овладению целительной...",kw={"barrens","crossroads","cure poison","dendrite starblaze","elder rise","moonglade","thunder bluff","turak runetotem","степи","перекресток","излечение от яда","дендрит блеск звезд","вершина старейшин","лунная поляна","громовой утес","тюрак рунический тотем"},ang={["class:Druid"]="Этот обряд посвящения связывает физическое травознание Калимдора с врожденной магией природы и дарует друидам постоянную способность очищать союзников от токсинов.",["faction:Horde"]="Испытания вокруг Перекрестка показывают растущую роль Орды в защите диких просторов центрального Калимдора от неестественной порчи.",["race:Tauren"]="Для таурен-посвящаемых выполнение этого задания доказывает преданность Кругу Кенария и сохраняет мудрость Матери-Земли живой на Вершине Старейшин."},sec={{t="Урок страдания",b="Прежде чем даровать начинающему друиду врожденную магическую силу очищения от ядов, Круг Кенария требует, чтобы он понял физическую суть недуга. Дендрит Блеск Звезд отправил новичка на Перекресток, где Тонга Рунический Тотем велел ему собрать земные реагенты для целебной мази, приготовленной вручную. Лишь леча отравленных степных газелей Степей без помощи духов, ученик видит, какую мучительную борьбу ведут обычные существа с природными и неестественными токсинами."},{t="Возвращение на Вершину Старейшин",b="Когда испытание завершено, Дендрит отправляет посвящаемого обратно к Тюраку Руническому Тотему, великому наставнику друидов на Вершине Старейшин в Громовом Утесе. Тюрак отмечает, что странные, губительные яды, появляющиеся у Перекрестка, угрожают природному равновесию равнин и вызывают серьезную тревогу. Похвалив самообладание посвящаемого, Тюрак навсегда передает ему духовное искусство излечения от ядов и поручает беречь живых существ Калимдора."}},faq={{q="Какова цель этого задания?",a="Это задание завершает друидическое испытание Орды, посвященное исцелению от ядов. Проявив дисциплину и приготовив простые средства для спасения страдающих газелей, посвящаемый возвращается к Тюраку Руническому Тотему, чтобы выучить заклинание «Излечение от яда» напрямую через единение с природой.",al={"why do power over poison","what does this quest do","druid poison quest purpose","зачем выполнять власть над ядом","что дает это задание","цель друидического задания об яде"}},{q="Где находится Тюрак Рунический Тотем?",a="Тюрак Рунический Тотем обитает на вершине Вершины Старейшин в Громовом Утесе. Его дом — в шатре и выдолбленных насестах, где друиды-таурены общаются с природой и учатся.",al={"turak runetotem location","where is turak","find turak runetotem","где тюрак рунический тотем","где тюрак","найти тюрака рунический тотем"}},{q="Кто отправляет друида обратно в Громовой Утес?",a="Дендрит Блеск Звезд, ночной эльф-друид из Круга Кенария, находящийся в священном убежище Лунной поляны, отправляет посвящаемого обратно к наставнику после того, как тот успешно исцелит диких животных у Перекрестка.",al={"who gives power over poison","quest giver","dendrite starblaze","кто выдает власть над ядом","персонаж, выдающий задания","дендрит блеск звезд"}},{q="Почему Круг Кенария сначала заставил друида лечить зверей вручную?",a="Дендрит Блеск Звезд подчеркивает, что друид должен понять, что значит излечивать яд тяжелым трудом и в пределах смертных сил, прежде чем владеть легкой духовной магией. Пережив участь больных существ, он учится сочувствию и уважению к природному равновесию.",al={"why cure sick manually","why use salves first","druid poison lesson","почему лечить вручную","почему сначала мази","урок друида об ядах"}},{q="Что тревожит Тюрака Рунический Тотем на Перекрестке?",a="Тюрак с глубокой тревогой отмечает, что неестественные агрессивные яды попадают к диким животным Степей около Перекрестка. Он считает такое загрязнение серьезным нарушением равновесия земли, требующим постоянной бдительности.",al={"turak crossroads concern","crossroads poison balance","тревога тюрака о перекрестке","яд и равновесие на перекрестке"}},{q="Доступно ли это задание друидам Альянса?",a="Друиды Альянса проходят параллельное испытание с тем же названием. Вместо того чтобы идти к Тюраку Руническому Тотему на Вершине Старейшин, ночные эльфы завершают урок, вернувшись к Матренгилу Медвежьей Лапе в Дарнассе.",al={"can night elves do this","alliance power over poison","могут ли ночные эльфы это выполнить","власть над ядом альянс"}}},fp="17,300,21.494.0,24.465.0,34.271.0,33.158.0,42.206.0,70.273.0,51.234.0,43.215.0"}
P.entries["quest:6181"] = {n="Срочное сообщение",s="Интенданту Льюису из Сторожевого холма срочно нужны поставки доспехов из Штормграда для снаряжения Народного ополчения. Поскольку Западный Край почти не получает официальной военной помощи, он отправляет вас к Тору, укротителю грифонов, чтобы доставить срочную заявку в столицу по воздуху.",h="Интенданту Льюису из Сторожевого холма срочно нужны поставки доспехов из Штормграда для снаряжения Народного...",kw={"armor","flight master","gryphon","old town","osric strang","peoples militia","quartermaster lewis","sentinel hill","stormwind","thor","доспехи","укротитель грифонов","грифон","старый город","озрик штранг","народное ополчение","интендант льюис","сторожевой холм","штормград","тор"},ang={["faction:Alliance"]="Это поручение показывает глубокий разрыв в снабжении между великой столицей Штормградом и ее бедствующими пограничными форпостами в Западном Крае.",["race:Human"]="Для людей королевства доставка записки Льюиса показывает тяжелое положение провинций Штормграда и знакомит с важными грифоньими маршрутами, связывающими родные земли."},sec={{t="Мольба сквозь небеса",b="Сторожевой холм стоит в изоляции перед растущим натиском разбойников Братства Справедливости и гноллов, лишенный прямой военной помощи из Штормграда. Интендант Льюис полагается на частные связи в столице, чтобы снабжать Народное ополчение оружием и доспехами. Снаряжения остается все меньше, и его единственная надежда — Озрик Штранг, оружейник из Старого города. Доставить ему срочную заявку нужно быстро, поэтому Льюис привлекает путников, чтобы они обратились к укротителю грифонов Западного Края — Тору."},{t="Сеть полетов",b="Грифоны обеспечивают Королевство Штормград бесценной сетью быстрого сообщения и курьерской связи. Тор, обосновавшийся на Сторожевом холме, управляет воздушной связью форпоста со столицей. Передав записку Льюиса Тору, вы открываете небесный путь между Западным Краем и королевским городом, что показывает, насколько важны наездники на грифонах для гарнизонов на границе, отрезанных от официальной помощи."}},faq={{q="Почему интенданту Льюису нужно отправить записку в Штормград?",a="Западный Край получает мало прямой военной помощи от правительства Штормграда, и у Народного ополчения остро не хватает доспехов. Льюису приходится обратиться к надежному торговцу в городе, Озрику Штрангу, чтобы получить новые припасы.",al={"why send note","lewis note purpose","why contact stormwind","зачем отправлять записку","цель записки льюиса","зачем связываться со штормградом"}},{q="Кто такой Озрик Штранг?",a="Озрик Штранг — оружейник, чья лавка «Ограниченный иммунитет» находится в Старом городе в Штормграде. Он служит надежным частным поставщиком Льюиса, когда официальные каналы не справляются.",al={"osric strang","who is osric","limited immunity owner","озрик штранг","кто такой озрик","владелец limited immunity"}},{q="Кто такой Тор?",a="Тор — укротитель грифонов, служащий на Сторожевом холме. Он заведует летающими скакунами, которые связывают Западный Край со Штормградом, обеспечивая быструю курьерскую доставку и перелеты.",al={"who is thor","westfall flight master","thor gryphon master","кто такой тор","укротитель грифонов западного края","тор укротитель грифонов"}},{q="Почему Штормград не присылает солдат и снаряжение в Западный Край напрямую?",a="Из-за исчезновения короля Вариана Ринна и нехватки ресурсов руководство Штормграда в основном забросило окраинные фермерские земли. Пограничным форпостам вроде Сторожевого холма приходится полагаться на ополчение из добровольцев и частные договоренности, чтобы выжить.",al={"why no stormwind help","why stormwind ignores westfall","where is the army","почему штормград не помогает","почему штормград игнорирует западный край","где армия"}},{q="Может ли это задание выполнить любой искатель приключений?",a="Это поручение доверяют именно искателям приключений-людям, проявившим себя в Западном Крае; оно служит знакомством с сетью полетов на грифонах в королевстве.",al={"who can take this quest","human only quest","can dwarves do this quest","кто может взять задание","задание только для людей","могут ли дворфы выполнить задание"}},{q="Куда ведет это курьерское задание дальше?",a="После того как вы передадите записку Тору, он организует перелет на грифоне прямо в Штормград, где вы продолжите путь к Дунгару Долгопиву в гнездовье столицы, а затем отыщете Озрика Штранга в Старом городе.",al={"next step","what happens after thor","where do i go next","следующий шаг","что будет после тора","куда идти дальше"}}},fp="15,269,23.481.0,18.370.0,62.223.0,20.175.0,12.161.0,67.235.0,39.172.0,42.197.0"}
P.entries["quest:62"] = {n="Рудник Подземных глубин",s="Маршал Дугхан из Златоземья поручает разведчикам проверить сообщения о том, что Рудник Подземных Глубин захвачен кобольдами. Падение рудника, расположенного к югу от города между фермами Стоунфилд и Маклюр, говорит о растущем нашествии вредителей по всему Элвиннскому лесу.",h="Маршал Дугхан из Златоземья поручает разведчикам проверить сообщения о том, что Рудник Подземных Глубин...",kw={"dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","maclure","stonefield","дугхан","элвиннский лес","подземные глубины","златоземье","яшмовая шахта","кобольд","маклюр","стоунфилд"},ang={["faction:Alliance"]="Захваченный рудник — еще один явный признак слабеющей власти Штормграда в Элвиннском лесу: местная стража с трудом защищает важные объекты.",["profession:Mining"]="Богатые медные жилы Рудника Подземных Глубин жизненно важны для начинающих кузнецов, но чтобы добывать их, придется прорубаться через кобольдов, охраняющих свои владения."},sec={{t="Беда к югу от Златоземья",b="Пока Долина Североземья справлялась со своими вредителями, в Златоземье дошли тревожные вести: кобольды захватили еще одно важное место. Рудник Подземных Глубин, расположенный между враждующими усадьбами Стоунфилд и Маклюр к югу от города, когда-то давал королевству камень и руду. Теперь в сырых туннелях раздаются пронзительный щебет и мерцают сальные свечи, и маршал Дугхан отправляет искателей приключений на разведку в глубины, чтобы подтвердить худшее."},{t="Стража в затруднении",b="Подтверждение нашествия лишь усугубляет заботы Стражи Штормграда. Регулярные войска растянуты в обороне от бандитов Братства Справедливости и набегов гноллов, и у стражи не хватает людей, чтобы полностью зачистить рудник. Мрачная реакция Дугхана на подтверждение показывает, что в сердце страны постепенно теряется контроль, и он тут же начинает беспокоиться о других рудниках, например об Яшмовой шахте на северо-востоке."}},faq={{q="Где находится Рудник Подземных Глубин?",a="Рудник Подземных Глубин находится почти строго к югу от Златоземья в Элвиннском лесу, прямо между усадьбами Стоунфилд и Маклюр.",al={"fargodeep location","where is fargodeep mine","fargodeep mine map","расположение рудника подземных глубин","где рудник подземных глубин","карта рудника подземных глубин"}},{q="Кто посылает вас на разведку Рудника Подземных Глубин?",a="Маршал Дугхан, командир Стражи Штормграда в Златоземье, дает задание разведать туннели.",al={"who gives fargodeep quest","marshal dughan quest","кто дает задание рудника подземных глубин","задание маршала дугхана"}},{q="Какие существа захватили рудник?",a="Рудник полностью захвачен кобольдами, которые обосновались там, зажгли свои свечи и вытеснили рабочих-людей.",al={"who is in fargodeep","what monsters in fargodeep","кто в руднике подземных глубин","какие монстры в руднике подземных глубин"}},{q="Почему маршалу Дугхану нужны искатели приключений, чтобы проверить рудник?",a="Стража Штормграда и без того с трудом справляется с местным бандитизмом, остатками орков и набегами гноллов, поэтому у Дугхана нет лишних солдат даже для проверки обычных донесений разведчиков.",al={"why send scouts","why doesn't the guard go","зачем посылать разведчиков","почему стража не идет сама"}},{q="Что происходит после разведки Рудника Подземных Глубин?",a="Когда вы сообщите маршалу Дугхану дурные вести, он решит, что проблема повсеместна, и отправит вас на северо-восток, чтобы проверить также Яшмовую шахту.",al={"next quest after fargodeep","what comes next","следующее задание после рудника подземных глубин","что дальше"}},{q="Почему нашествие в Руднике Подземных Глубин так важно?",a="Падение Рудника Подземных Глубин доказывает, что нашествие кобольдов в Североземье не было единичным случаем. Оно показывает, как быстро дикие угрозы подступают к обжитым фермерским землям у самых врат Штормграда.",al={"why does fargodeep matter","lore of fargodeep mine","почему важен рудник подземных глубин","предания рудника подземных глубин"}}},fp="18,257,26.450.0,16.435.0,36.127.0,42.132.0,40.117.0,59.193.0,47.150.1,53.200.0"}
P.entries["quest:6281"] = {n="Продолжение пути в Штормград",s="Это поручение знакомит искателей приключений в Западном Крае со скоростью и удобством сети грифонов Королевства Штормград. Получив срочную заявку из Сторожевого холма, путники летят прямо в Старый город, чтобы передать весть торговцу Озрику Штрангу.",h="Это поручение знакомит искателей приключений в Западном Крае со скоростью и удобством сети грифонов...",kw={"flight path","gryphon","lewis' note","limited immunity","old town","osric strang","sentinel hill","thor","маршрут полета","грифон","записка льюиса","старый город","озрик штранг","сторожевой холм","тор"},ang={["faction:Alliance"]="Сеть полетов, которую поддерживают укротители грифонов, связывает разбросанные форпосты Альянса, не давая дальним гарнизонам оторваться от столицы.",["race:Human"]="Возвращение в Старый город показывает, насколько далекими от политики великого Дома знати чувствуют себя простые горожане и изолированные жители границы."},sec={{t="Взлет",b="После того как интендант Льюис из Сторожевого холма составляет заявку, местный укротитель грифонов Тор предлагает самый быстрый путь из спорных равнин. За скромную плату путники садятся на обученных королевских грифонов и парят над пыльными фермерскими землями, над речной границей Элвиннского леса и над высокими белыми стенами самого Штормграда."},{t="Линии снабжения Старого города",b="Прибыв на торговые насесты столицы, курьер отправляется в Старый город, чтобы найти Озрика Штранга в его лавке «Ограниченный иммунитет». Озрик снабжает пограничье снаряжением и припасами, но его мрачный прием показывает растущий разрыв между осажденным Народным ополчением Западного Края и рассеянными правителями в Крепости Штормграда."}},faq={{q="В чем цель этого задания?",a="Задание служит практическим знакомством с маршрутами полетов на грифонах Альянса и учит искателей приключений быстро перемещаться между дальними форпостами и столицей.",al={"why do this quest","quest purpose","continue to stormwind objective","зачем это задание","цель задания","цель продолжения пути в штормград"}},{q="Где находится Озрик Штранг?",a="Озрик Штранг держит лавку «Ограниченный иммунитет» на извилистых улочках Старого города в Штормграде.",al={"where is osric strang","find osric strang","limited immunity location","где озрик штранг","найти озрика штранга","где limited immunity"}},{q="Почему Сторожевому холму нужны припасы из Штормграда?",a="Народное ополчение на Сторожевом холме с трудом противостоит Братству Справедливости и почти не получает официальной военной помощи из столицы, поэтому интенданту Льюису приходится покупать снаряжение напрямую у гражданских торговцев.",al={"why need supplies","westfall supply issue","sentinel hill gear","зачем нужны припасы","проблема снабжения западного края","снаряжение сторожевого холма"}},{q="Кто такой Тор?",a="Тор — укротитель грифонов Альянса на Сторожевом холме, управляющий маршрутами полетов, которые связывают Западный Край со Штормградом и другими дружественными узлами.",al={"who is thor","westfall gryphon master","thor westfall","кто такой тор","укротитель грифонов западного края","тор западный край"}},{q="Что написано в записке Льюиса?",a="Это срочная заявка интенданта Льюиса с перечнем снаряжения и провизии, остро необходимых для оснащения гарнизона Сторожевого холма.",al={"lewis note","what does the note say","contents of note","записка льюиса","что сказано в записке","содержание записки"}},{q="Что происходит после доставки записки?",a="Получив заявку, Озрик велит вам поговорить с укротителем грифонов Штормграда Дунгаром Долгопивом, чтобы организовать доставку заказанных припасов обратно в Западный Край.",al={"what next","follow up quest","after osric strang","что дальше","следующее задание","после озрика штранга"}}},fp="21,268,11.357.0,21.336.0,34.174.0,30.113.0,52.218.0,12.153.0,27.148.0,39.179.0"}
P.entries["quest:6282"] = {n="Угроза со стороны гарпий",s="«Угроза со стороны гарпий» — задание Орды, которое выдает Землепряд Маггран в Приюте у Солнечного Камня в Когтистых горах. Исполняя призвание тауренов как хранителей земли, герои отправляются на юг, в опустошенную Обугленную долину, чтобы истребить множащиеся ряды гарпий клана Кровавой Ярости.",h="«Угроза со стороны гарпий» — задание Орды, которое выдает Землепряд Маггран в Приюте у Солнечного Камня в...",kw={"ambushers","bloodfury","charred vale","coven","harpies threaten","maggran earthbinder","roguefeathers","slayers","stonetalon mountains","sun rock retreat","убийцы из засады","кровавая ярость","обугленная долина","клан","угроза со стороны гарпий","землепряд маггран","воровки","душегубки","когтистые горы","приют у солнечного камня"},ang={["class:Druid"]="Извращенное присутствие клана Кровавой Ярости оскверняет и без того хрупкую, опустошенную огнем экосистему Обугленной долины.",["class:Shaman"]="Выполняя волю Землепряда Магграна, шаманы откликаются на призыв и изгоняют агрессивных осквернителей, нарушающих природное равновесие стихий.",["faction:Horde"]="Очищение неба над Обугленной долиной укрепляет позиции Орды в Приюте у Солнечного Камня против опасных диких сил, обитающих в Когтистых горах.",["race:Tauren"]="Для персонажей-тауренов истребление наступающих гарпий Кровавой Ярости — почетный долг, исполнение древнего обета защищать дикие земли Калимдора."},sec={{t="Защитники земли",b="Таурены Приюта у Солнечного Камня исполняют глубокий долг — оберегать Когтистые горы, поддерживать природное равновесие и защищать мирных путников от опасностей края. Землепряд Маггран, старейшина и предводитель приюта, с растущей тревогой наблюдает за неудержимым ростом числа местных гарпий. Клан Кровавой Ярости расселился по выжженным пустошам Обугленной долины, донимает проходящих зверей и перекрывает пути сообщения. Если их хищные стаи не остановить, Приют у Солнечного Камня окажется полностью отрезан от мира."},{t="Очищение Обугленной долины",b="К югу от Приюта у Солнечного Камня лежит Обугленная долина — безжизненная пустошь из пепла, выжженной земли и тлеющих деревьев, оставшаяся после страшных пожаров. Здесь, высоко в обугленных остатках древних лесов, гарпии Кровавой Ярости устроили свое укрепление. Маггран поручает воинам Орды отправиться в эту враждебную кальдеру и истребить десятки гарпий-убийц из засады, душегубок и воровок. Поредевшая стая лишится власти над долиной, и путь к их предводительнице откроется."}},faq={{q="Кто выдает задание «Угроза со стороны гарпий»?",a="Задание выдает Землепряд Маггран, таурен, которого можно найти у центрального водоема в Приюте у Солнечного Камня в Когтистых горах.",al={"quest giver harpies threaten","where to pick up harpies threaten","maggran earthbinder quest","кто выдает задание угроза со стороны гарпий","где взять угрозу со стороны гарпий","задание землепряда магграна"}},{q="Где обитают гарпии клана Кровавой Ярости?",a="Гарпии Кровавой Ярости обитают по всей Обугленной долине — выжженной равнине прямо к югу от Приюта у Солнечного Камня. Горная тропа за приютом ведет прямо вниз, в долину.",al={"where are bloodfury harpies","bloodfury harpy location","charred vale harpies","где гарпии кровавой ярости","расположение гарпий кровавой ярости","гарпии обугленной долины"}},{q="Почему таурены хотят истребить гарпий?",a="Таурены считают себя хранителями природного равновесия Когтистых гор. Землепряд Маггран опасается, что гарпии Кровавой Ярости агрессивно расселяются по Калимдору, нападают на невинных и мешают живым существам свободно передвигаться по земле.",al={"why kill harpies","tauren harpy conflict","why maggran hates harpies","зачем убивать гарпий","конфликт тауренов и гарпий","почему маггран ненавидит гарпий"}},{q="Что будет после выполнения задания «Угроза со стороны гарпий»?",a="Выполнение задания «Угроза со стороны гарпий» открывает следующее задание — «Предводительница клана Кровавой Ярости», в котором Землепряд Маггран посылает вас уничтожить правящую верхушку клана Кровавой Ярости.",al={"next quest harpies threaten","harpies threaten follow up","what after harpies threaten","следующее задание угроза со стороны гарпий","продолжение угрозы со стороны гарпий","что после угрозы со стороны гарпий"}},{q="Это задание только для Орды?",a="Да. Задание доступно исключительно Орде и выдается в поселении Приют у Солнечного Камня.",al={"can alliance do harpies threaten","harpies threaten horde only","alliance harpies threaten","может ли альянс выполнить угрозу со стороны гарпий","угроза со стороны гарпий только для орды","альянс угроза со стороны гарпий"}},{q="Каких гарпий нужно убить?",a="Вы должны убить в Обугленной долине по семь гарпий Кровавой Ярости, убийц из засады Кровавой Ярости, душегубок Кровавой Ярости и воровок Кровавой Ярости.",al={"which harpies to kill","harpy types charred vale","harpies threaten objectives","каких гарпий убивать","виды гарпий обугленной долины","цели угрозы со стороны гарпий"}}},fp="16,288,22.518.0,25.538.0,37.139.0,40.183.0,42.251.0,45.175.0,25.91.0,36.149.0"}
P.entries["quest:6284"] = {n="Арахнофобия",s="«Арахнофобия» — задание Орды о награде за голову Бесселет, древнего исполинского хищника, обитающего на юге Когтистых гор. Объявление у дороги близ Утеса Ветрорезов направляет героев в Сиширский каньон за клыком паучьей матриарха для Землепряда Магграна в Приюте у Солнечного Камня. Конец ее владычеству сделает горные дороги безопаснее для путников в ночное время.",h="«Арахнофобия» — задание Орды о награде за голову Бесселет, древнего исполинского хищника, обитающего на юге...",kw={"arachnophobia","besseleth","bounty","maggran earthbinder","sishir canyon","spider","stonetalon mountains","sun rock retreat","webwinder path","арахнофобия","бессилет","награда за голову","землепряд маггран","сиширский каньон","паук","когтистые горы","приют у солнечного камня","паучий тракт"},ang={["class:Hunter"]="Выслеживание неуловимого исполинского паука в тенистых утесах Сиширского каньона — настоящее испытание для горного охотника.",["faction:Horde"]="Расправа с Бесселет делает безопаснее путь в Приют у Солнечного Камня и защищает жизненно важный оплот Орды в центральных утесах Когтистых гор.",["race:Tauren"]="Землепряд Маггран носит болезненный шрам от яда Бесселет, и потому охота становится делом чести — помочь собрату, сыну земли."},sec={{t="Предупреждение у дороги",b="Путники на главном тракте к югу от Утеса Ветрорезов заметят потрепанное объявление о розыске, предупреждающее об опасностях на западе. Сиширский каньон и Паучий тракт полностью захвачены восьминогими хищниками. В сердце этой паутинной угрозы обитает Бесселет — необычайно крупный паук оранжевого цвета, который повелевает своим выводком и устраивает засады на всякого, кто осмелится сойти с тропы после заката."},{t="Обида Землепряда",b="Награду за голову Бесселет назначил Землепряд Маггран, таурен из Приюта у Солнечного Камня. У Магграна с матриархом личные счеты: в прошлой встрече он едва не погиб, пораженный огромным двухфутовым клыком Бесселет. Хотя ему удалось отбиться и доковылять до безопасного места, незаживающая рана постоянно напоминает об опасности, таящейся в тенях каньона. Поручив герою добыть Клык Бесселет, Маггран надеется обезопасить перевалы, чтобы торговля и путешествия к Приюту у Солнечного Камня процветали без страха."}},faq={{q="Где начинается задание «Арахнофобия»?",a="Задание начинается при осмотре объявления о розыске, висящего вдоль западной стороны главной дороги в Когтистых горах, к югу от входа в Утес Ветрорезов.",al={"where to get arachnophobia","wanted poster besseleth location","how to start arachnophobia","где взять арахнофобию","объявление о розыске бессилет","как начать арахнофобию"}},{q="Где можно найти Бесселет?",a="Бесселет обитает в Сиширском каньоне, к западу от объявления у дороги. Она бродит среди своих пауков-детенышей по затянутой паутиной земле каньона.",al={"besseleth location","where is besseleth","find besseleth spider","где бессилет","расположение бессилет","найти паука бессилет"}},{q="Кто такой Землепряд Маггран?",a="Землепряд Маггран — таурен из Приюта у Солнечного Камня в Когтистых горах. Он лично пережил ядовитый укус Бесселет и назначил награду, чтобы избавить каньон от ее угрозы.",al={"who is maggran","maggran earthbinder role","who turned in arachnophobia","кто такой маггран","роль магграна","кто сдает арахнофобию"}},{q="Почему Бесселет так опасна для края?",a="Бесселет — исключительно крупный и безжалостный паук, охотящийся в Сиширском каньоне и на соседнем Паучьем тракте. Она и ее выводок нападают на путников под покровом ночи, угрожая всем, кто пытается добраться до Приюта у Солнечного Камня.",al={"why kill besseleth","what did besseleth do","зачем убивать бессилет","что сделала бессилет"}},{q="Какое доказательство нужно для получения награды?",a="Вы должны убить Бесселет и отсечь один из ее огромных двухфутовых клыков. Передача Клыка Бесселет Землепряду Магграну в Приюте у Солнечного Камня завершает задание.",al={"besseleth proof","besseleth quest item","what drops from besseleth","доказательство бессилет","предмет задания бессилет","что падает с бессилет"}},{q="Доступно ли это задание Альянсу?",a="Нет. Награду выплачивает Землепряд Маггран в Приюте у Солнечного Камня, лагере Орды, поэтому «Арахнофобия» доступна только Орде.",al={"can alliance do arachnophobia","alliance arachnophobia quest","может ли альянс выполнить арахнофобию","задание арахнофобия для альянса"}}},fp="13,392,20.398.0,27.556.0,41.169.0,29.162.0,27.200.0,45.237.0,43.162.0,40.153.0"}
P.entries["quest:63"] = {n="Зов Воды",s="Этот важный обряд посвящения направляет шаманов из Степей через Великое море к зараженным берегам Серебряного бора. Чтобы обрести общение с духами воды, посвящаемый должен сразиться с оскверненным элементалем и очистить древнее прибрежное святилище, оскверненное чумой Плети.",h="Этот важный обряд посвящения направляет шаманов из Степей через Великое море к зараженным берегам Серебряного...",kw={"brazier of everfount","brine","call of water","corrupt manifestation","islen waterseer","sepulcher","silverpine forest","water totem","жаровня вечного источника","брин","зов воды","оскверненное воплощение","ислен заклинатель воды","гробница","серебряный бор","тотем воды"},ang={["class:Shaman"]="Этот обряд показывает, что шаман — не просто призыватель бурь, но целитель израненных земель, которому поручено очищать духовную порчу.",["faction:Horde"]="Путешествие в Серебряный бор заставляет рожденных в Калимдоре орков и таурен воочию увидеть мрачные тяготы своих союзников Отрекшихся, живущих среди чумы."},sec={{t="Паломничество через море",b="Добыв капли чистой воды под руководством отшельницы Брин, шаман возвращается к Ислен Заклинательнице Воды на побережье Степей. Затем Ислен поручает новичку куда более опасное дело: доставить эту очищенную эссенцию через море на призрачный берег Серебряного бора, к западу от убежища Отрекшихся — Гробницы."},{t="Очищение Вечного источника",b="Избранное святилище — Жаровня Вечного источника, древний очаг стихий, воды которого исказились и стали враждебными под влиянием порчи от чумы Лордерона. Обитающие там духи воды онемели и одичали. Победив связанное здесь оскверненное воплощение и предложив пламени жаровни его наручи и чистейшую воду, шаман разрывает хватку порчи и призывает неоскверненного духа приливов."}},faq={{q="Почему шаману нужно отправляться так далеко, в Серебряный бор?",a="Ислен Заклинатель Воды требует от шаманов доказать власть над порчей, а не просто изучать покой. Прибрежное святилище к западу от Гробницы пало жертвой чумы Лордерона, и посвящаемый получает возможность исцелить святилище стихий и пробудить духов воды, которые не хотят говорить ни с кем другим.",al={"why go to silverpine","why travel across sea","why silverpine water quest","зачем идти в серебряный бор","зачем плыть через море","задание воды серебряный бор"}},{q="Что происходит, когда вы используете Жаровню Вечного источника?",a="Если положить наручи побежденного элементаля вместе с оставшимися каплями чистейшей воды в пламя, начинается обряд очищения, которому научила Ислен. Потрескивающее приношение очищает местный водоем и призывает чистое воплощение воды, готовое даровать свое благословение.",al={"brazier of everfount event","what does the brazier do","how to cleanse the pool","жаровня вечного источника событие","что делает жаровня","как очистить водоем"}},{q="Кто оскверняет святилище воды в Серебряном бору?",a="Воду исказила чума, окутавшая павшее королевство Лордерон. Порча, просачиваясь с холмов, осквернила местный родник и превратила его духов воды в диких, враждебных чудовищ.",al={"who corrupted the shrine","why is the manifestation corrupted","silverpine water corruption","кто осквернил святилище","почему воплощение оскверенно","порча воды серебряный бор"}},{q="Что вы получите после завершения этого испытания?",a="Очистив жаровню Вечного источника, вы сможете пообщаться с чистым духом воды. Если вы отнесете доказательство очищения Ислен Заклинательнице Воды в Степях, вы наконец получите свой Тотем воды и завершите долгое испытание «Зов Воды».",al={"call of water reward","water totem unlock","what do i get","награда зов воды","тотем воды открыть","что я получу"}},{q="Где именно находится святилище?",a="Святилище находится прямо на западном побережье Серебряного бора, за зараженным хребтом к западу от Гробницы.",al={"brazier of everfount location","where is the shrine","silverpine shrine coords","местоположение жаровни вечного источника","где святилище","координаты святилища серебряный бор"}},{q="Кто такая Ислен Заклинатель Воды?",a="Ислен Заклинатель Воды — отшельница-элементалист, живущая на Торговом побережье Степей, к югу от Кабестана. Она служит почитаемой духовной наставницей и ведет молодых шаманов Орды через трудные обряды, необходимые для единения со стихией воды.",al={"who is islen","islen waterseer background","barrens water trainer","кто такая ислен","ислен заклинатель воды история","наставник воды степи"}}},fp="13,295,27.345.0,23.441.1,66.303.0,51.264.0,49.240.0,48.237.0,36.123.0,23.246.0"}
P.entries["quest:6301"] = {n="Цикл возрождения",s="«Цикл возрождения» — задание Орды, которое дает Таммра Перекати-поле в Приюте у Солнечного Камня: собрать редкие семена Геи на берегах Мутного озера. Удрученная ущербом от промышленной алчности и непрекращающихся войн в Когтистых горах, Таммра хочет наделить эти стойкие зерна силой шаманов, чтобы возродить истерзанную почву гор. Это первый важный шаг в усилиях по исцелению израненной глуши.",h="«Цикл возрождения» — задание Орды, которое дает Таммра Перекати-поле в Приюте у Солнечного Камня: собрать...",kw={"charred vale","cycle of rebirth","earthmother","gaea seed","mirkfallon lake","new life","stonetalon mountains","sun rock retreat","tammra windfield","обугленная долина","цикл возрождения","мать-земля","семена геи","мутное озеро","новая жизнь","когтистые горы","приют у солнечного камня","таммра перекати-поле"},ang={["class:Druid"]="Друиды оценят схожий упор на природные циклы и выращивание семян: восстановление бесплодной земли прямо созвучно заботе Кенария.",["class:Shaman"]="Усилия Таммры отражают призвание шамана исцелять нарушенное равновесие природы и показывают, что духи и Мать-Земля способны восстановить то, что разрушает промышленная эксплуатация.",["race:Tauren"]="Для Шу'хало исцеление израненной почвы Когтистых гор — духовный долг перед Матерью-Землей, ответ на разорение, вызванное бездумными вырубками и войной фракций."},sec={{t="Израненная глушь",b="Вершины Когтистых гор несут глубокие раны от коммерческой эксплуатации и непрекращающихся местных конфликтов. Из-за агрессивных лесозаготовок и столкновений враждующих сторон целые участки леса были выжжены, вырублены или обращены в пепел. Для таурен Приюта у Солнечного Камня видеть, как стремительно гибнет природа, — тяжкая рана. Шаманы вроде Таммры Перекати-поле не просто бьются за удержание земель, а обращаются к древнему природному порядку, стремясь воплотить восстановительный цикл Матери-Земли."},{t="Семена Мутного озера",b="Чтобы вернуть жизнь бесплодной земле, нужна необычайная жизненная сила, и Таммра находит ее в редких семенах Геи у Мутного озера. К северу от Приюта у Солнечного Камня берега озера питают эти крепкие семенные коробочки у самой кромки воды. Хотя округа полна опасностей, эти семена обладают врожденной стойкостью, свойственной только Когтистым горам. Когда семена собраны, Таммра вливает в каждое зерно благословения шаманов-предков, пробуждая скрытую силу и ускоряя их рост для предстоящей работы."}},faq={{q="Зачем нужно собирать семена Геи?",a="Семена Геи обладают исключительной природной жизненной силой, которая делает их особенно подходящими для восстановления опустошенных земель. Таммра Перекати-поле собирает их, чтобы наделить благословениями Матери-Земли и силой шаманов, подготовив к быстрому прорастанию и возрождению участков Когтистых гор, разоренных промышленностью и войной.",al={"why gaea seeds","what are gaea seeds for","cycle of rebirth purpose","зачем семена геи","для чего семена геи","цель цикла возрождения"}},{q="Где находятся семена Геи?",a="Семена Геи лежат на берегу Мутного озера, прямо к северу от Приюта у Солнечного Камня в Когтистых горах. Они покоятся в земле у кромки воды по всему периметру озера.",al={"gaea seed location","where to find gaea seeds","mirkfallon lake seeds","где семена геи","где найти семена геи","семена мутное озеро"}},{q="Кто такая Таммра Перекати-поле?",a="Таммра Перекати-поле — шаманка-таурен, живущая в Приюте у Солнечного Камня. Глубоко скорбя о вырубке лесов и разрушениях, причиненных Когтистым горам войной и лесозаготовительными синдикатами, она посвятила себя исцелению земли с помощью благословений Матери-Земли.",al={"who is tammra","tammra windfield lore","кто такая таммра","таммра перекати-поле предание"}},{q="Что делает Таммра, когда семена возвращены?",a="Получив десять семян Геи, Таммра начинает священное песнопение, наполняя зерна энергией шаманов и ускоряя их природный потенциал роста, чтобы их можно было посадить в разоренных местах.",al={"what happens to seeds","turn in cycle of rebirth","что будет с семенами","сдать цикл возрождения"}},{q="Какое задание идет после «Цикла возрождения»?",a="«Цикл возрождения» напрямую ведет к заданию «Новая жизнь»: напитанные силой семена несут в Обугленную долину, чтобы начать возрождение растительной жизни.",al={"cycle of rebirth follow up","next quest after cycle of rebirth","what is after cycle of rebirth","продолжение цикла возрождения","следующее задание после цикла возрождения","что после цикла возрождения"}},{q="Почему земле Когтистых гор нужно исцеление?",a="Когтистые горы сильно пострадали от непрерывных войн и масштабных вырубок промышленных лесозаготовителей: остались выжженные пустоши и израненные долины, которым трудно возродиться самим.",al={"why is stonetalon ruined","what happened to stonetalon","почему разорены когтистые горы","что случилось с когтистыми горами"}}},fp="16,429,20.546.0,23.520.0,45.309.0,33.224.0,24.255.0,48.196.0,36.166.0,49.232.0"}
P.entries["quest:631"] = {n="Мост Тандола",s="После страшного взрыва на севере Болотины Раг Каменщик просит путников обыскать разрушенные мосты Моста Тандола в поисках пропавшего дворфа-разведчика. Клан Черного Железа яростно атаковал Дун Модр, прервав связь и оставив местных защитников без подкрепления. Найти Старину Растлока — первый шаг к тому, чтобы узнать истинный масштаб диверсии.",h="После страшного взрыва на севере Болотины Раг Каменщик просит путников обыскать разрушенные мосты Моста...",kw={"dark iron","dun modr","garmason","longbraid","rustlocke","span","thandol","wetlands","черное железо","дун модр","каменщик","длиннокос","растлок","мост","тандол","болотина"},ang={["faction:Alliance"]="Мост Тандола — единственный сухопутный путь снабжения, связывающий Штормград и Стальгорн с силами Альянса, удерживающими Арати и Хилсбрад.",["race:Dwarf"]="Разрушение Моста Тандола — оскорбление дворфийского каменного зодчества и прямой удар по Каз Модану от ненавистных сородичей из клана Черного Железа."},sec={{t="Гром над мостом",b="Недавно чудовищный взрыв разрушил Мост Тандола — огромный каменный мост, соединяющий Болотину с Нагорьем Арати. Солдаты Бронзобородов, стоявшие на границе, оказались в самом центре бедствия, когда дворфы Черного Железа внезапно напали на Дун Модр. Ряды защитников поредели, их укрепления осаждены, и выжившие под командованием Длиннокоса Мрачного вынуждены отчаянно обороняться от нападающих."},{t="Разведчик, посланный на восток",b="Надеясь сохранить переправу и выяснить, остался ли путь на север проходимым, Длиннокос отправил опытного разведчика Эбенезера Растлока осмотреть восточную часть моста. Прошли дни без единого донесения, но Дун Модр находится в осаде, и у Рага Каменщика и гарнизона нет солдат, чтобы отправить спасательный отряд в занятые врагом развалины."},{t="Мрачная находка",b="Выход на разрушенный мост показывает, какой ценой обернулось нападение дворфов Черного Железа. Старина Растлок не вернулся с разведданными — он погиб среди обломков восточного моста. Его тело и пергамент, зажатый в кулаке, подтверждают худшее: он попал в засаду дворфов Черного Железа, и они еще не закончили с важнейшей артерией между Каз Моданом и Лордероном."}},faq={{q="Что такое Мост Тандола?",a="Мост Тандола — громадное дворфийское сооружение, перекинутое через пропасть между северной Болотиной и Нагорьем Арати. Это главный сухопутный путь, соединяющий Каз Модан с северными землями Лордерона.",al={"thandol span","what is thandol bridge","wetlands bridge","мост тандола","что такое мост тандола","мост болотины"}},{q="Кто напал на Мост Тандола?",a="На мост и соседний форпост Дун Модр напал клан дворфов Черного Железа. Они взорвали заряды, разрушив мост, нарушили сообщение Альянса и застали защитников из Бронзобородов врасплох.",al={"who blew up the bridge","thandol span explosion","who attacked dun modr","кто взорвал мост","взрыв моста тандола","кто напал на дун модр"}},{q="Кто такой Старина Растлок?",a="Эбенезер Растлок был доверенным дворфом-разведчиком на службе Длиннокоса Мрачного. Его послали оценить состояние восточного моста после взрыва, но во время задания его одолели и убили силы Черного Железа.",al={"ebenezer rustlocke","who is rustlocke","missing scout","эбенезер растлок","кто такой растлок","пропавший разведчик"}},{q="Где находится Раг Каменщик?",a="Раг Каменщик находится возле осажденного поселения Дун Модр, к югу от Моста Тандола на севере Болотины. Он помогает координировать оборону, пока гарнизон отрезан от Стальгорна.",al={"rhag garmason location","where is rhag","quest giver dun modr","где раг каменщик","раг каменщик","персонаж, выдающий задания дун модр"}},{q="Почему Стальгорн не прислал помощь в Дун Модр?",a="Внезапность нападения, разрушение моста и осада Дун Модра оставили гарнизон в изоляции. Защитников слишком мало, чтобы посылать гонцов или отвлекать войска, поэтому они зависят от проходящих мимо искателей приключений, которые передадут весть.",al={"why no reinforcements","ironforge help wetlands","dun modr reinforcement","почему нет подкрепления","помощь стальгорна болотине","подкрепление дун модр"}},{q="Что происходит после того, как найдено тело Растлока?",a="При останках Растлока находится пергамент, из которого следует, что Кам Гневливый, организатор нападения, спрятал запас взрывчатки сразу за мостом. Начинается операция по уничтожению тайника, пока он не добрался до уцелевшего моста, а затем — поиск более широкой помощи через обращение к руководству Альянса.",al={"next quest after rustlocke","thandol span continuation","after the thandol span","следующее задание после растлока","продолжение моста тандола","после моста тандола"}}},fp="16,413,21.432.0,17.358.0,14.380.1,25.226.0,30.202.0,21.231.1,31.206.0,43.267.0,46.302.1"}
P.entries["quest:632"] = {n="Мост Тандола",s="Раг Каменщик поручает искателям приключений проверить Старину Эбенезера Растлока — разведчика, посланного осмотреть огромный каменный Мост Тандола, с которым потеряна связь. Осмотр под арками моста раскрывает обстоятельства его исчезновения и угрозы северным линиям снабжения.",h="Раг Каменщик поручает искателям приключений проверить Старину Эбенезера Растлока — разведчика, посланного...",kw={"arathi","dark iron","deepfury","ebenezer rustlocke","rhag garmason","thandol span","wetlands","арати","черное железо","гневливый","эбенезер растлок","раг каменщик","мост тандола","болотина"},ang={["faction:Alliance"]="Мост Тандола — артерия, связывающая Стальгорн и Штормград с северными оплотами Альянса, поэтому находка Растлока крайне важна для безопасности всего континента.",["race:Dwarf"]="Появление сил Черного Железа так далеко к северу от Тлеющего ущелья показывает, как глубоко проникла их коварная диверсия и что угроза нависла над сородичами из Стальгорна."},sec={{t="Последний бой разведчика",b="Командир Длиннокос послал Эбенезера Растлока следить за прочностью и безопасностью Моста Тандола. Когда связь с разведчиком прервалась, сразу заподозрили неладное. Осмотр ниш под арками показывает Растлока мертвым: он пал жертвой жестокой засады, устроенной из тени захватчиками из клана Черного Железа."},{t="Приказы Кама Темная Ярость",b="Рядом со сжатыми пальцами Растлока обнаружен набор письменных приказов с именем Гневливого. Это не случайный грабеж и не отдельная пограничная стычка: в пергаменте изложены продуманные действия Черного Железа, направленные на дестабилизацию переправы. Когда вы доставите эти доказательства Гармасону, гарнизон перейдет от обычных поисков к срочной обороне в условиях войны."}},faq={{q="Кем был Эбенезер Растлок?",a="Эбенезер, прозванный Стариной, Растлок был дворфом Альянса, посланным в разведку и для наблюдения за Мостом Тандола. Дворфы Черного Железа, засевшие под мостом, застали его врасплох и убили.",al={"who is rustlocke","ol rustlocke","ebenezer rustlocke","кто такой растлок","старина растлок","эбенезер растлок"}},{q="Кто убил Растлока?",a="Его подстерегли лазутчики Черного Железа, действовавшие под Мостом Тандола и выполнявшие распоряжения Кама Гневливого.",al={"who killed rustlocke","who ambushed rustlocke","rustlocke corpse","кто убил растлока","кто устроил засаду на растлока","тело растлока"}},{q="Что найдено на теле Растлока?",a="Рядом с его сжатым кулаком лежит пергамент с приказами Кама Темная Ярость, в которых описаны тайные замыслы Черного Железа против важнейшего северного моста.",al={"what was in his hand","deepfury's orders","parchment on rustlocke","что было в его руке","приказы кама темная ярость","пергамент растлока"}},{q="Кто такой Раг Каменщик?",a="Раг Каменщик — офицер Альянса, расположившийся на южной стороне Моста Тандола в Болотине и отвечающий за безопасность движения между землями дворфов и севером.",al={"rhag garmason","who is garmason","раг каменщик","кто такой каменщик"}},{q="Почему за Мост Тандола идет такая борьба?",a="Мост Тандола — единственный сухопутный мост, соединяющий земли дворфов Каз Модана и Болотину с Нагорьем Арати и Лордероном. Его защита жизненно важна для снабжения Альянса.",al={"why thandol span matters","thandol span importance","почему важен мост тандола","значение моста тандола"}},{q="Что происходит после передачи приказов Рагу Каменщику?",a="Осознав серьезность угрозы, Раг Каменщик посылает вас уничтожить тайник со взрывчаткой дворфов Черного Железа, спрятанный сразу за мостом в Нагорье Арати, чтобы сорвать их диверсию.",al={"what happens next","thandol span follow up","что будет дальше","продолжение моста тандола"}}},fp="16,322,21.358.0,17.380.1,27.191.1,21.123.1,34.141.1,21.184.0,45.196.0,54.184.1"}
P.entries["quest:6321"] = {s="Поставка оружия — снабженческое задание Стража смерти Подрига в Гробнице в Серебряном бору. Чтобы местный отряд Стражей смерти был вооружен против диких чудовищ и Плети, рыскающих по лесу, срочную заявку на оружие нужно передать через заведующего летучими мышами Кароса Раззока поставщикам оружия в Подгороде.",h="Поставка оружия — снабженческое задание Стража смерти Подрига в Гробнице в Серебряном бору.",kw={"bat handler","deathguard","gordon wendham","hadrec","karos razok","podrig","requisition","sepulcher","silverpine","undercity","заведующий летучими мышами","страж смерти","гордон уиндем","хадрик","карос раззок","подриг","заявка","гробница","серебряный бор","подгород"},ang={["faction:Horde"]="Создание и поддержка надежных воздушных сетей между гарнизонами и столицами — основа согласованной военной обороны в спорных регионах.",["race:Undead"]="Содержание таких застав, как Гробница, позволяет Отрекшимся проецировать силу за пределы Тирисфальских лесов и обеспечивать безопасность окрестных земель для Темной Госпожи."},sec={{t="Вооружение передовой",b="Страж смерти Подриг сообщает, что запасов в Гробнице относительно много, но постоянные потери в Серебряном бору расходуют снаряжение с пугающей скоростью. Из-за диких зверей, бродящих остатков Плети и других местных угроз боевое снаряжение изнашивается или теряется в стычках. По приказу Палача Хадрика Подриг составляет прямую заявку на имя Гордона Уиндема, торговца оружием из столицы. Стабильный поток запасных клинков и доспехов необходим, если Отрекшиеся хотят удержать свои хрупкие опорные пункты за пределами Тирисфальских лесов."},{t="Сеть полетов",b="Доставлять важные письма и военные припасы по окутанным туманом дорогам Серебряного бора пешком медленно и опасно из-за засад. Чтобы обойти эти опасности, Отрекшиеся используют прирученных вампирических летучих мышей. Передав заявку Подрига заведующему летучими мышами Каросу Раззоку, пехотинцы включаются в обширную воздушную сеть снабжения Подгорода, которая напрямую связывает дальние гарнизоны со столицей Сильваны."}},faq={{q="Для чего нужен приказ Подрига?",a="Страж смерти Подриг осмотрел оружейную Гробницы по поручению Палача Хадрика. Провизии и обычного снаряжения хватало, но требовалось оружие взамен сломанного или потерянного в стычках с Плетью и другими лесными угрозами.",al={"why podrig order","what is podrigs requisition","purpose of supplying the sepulcher","зачем приказ подрига","заявка подрига","поставка оружия цель"}},{q="Кто такой Гордон Уиндем?",a="Гордон Уиндем — торговец оружием из Подгорода. Подриг направляет заявку именно ему, чтобы удовлетворить потребность гарнизона в новом оружии.",al={"who is gordon wendham","gordon wendham undrcity","кто такой гордон уиндем","гордон уиндем подгород"}},{q="Кто такой Карос Раззок?",a="Карос Раззок — заведующий летучими мышами в Гробнице. Он отвечает за стаю жутких летучих мышей, на которых перевозят гонцов, разведчиков и припасы по всему Лордерону.",al={"karos razok role","who is the bat handler","карос раззок","кто заведует летучими мышами"}},{q="Почему используют летучих мышей, а не гонцов на дорогах?",a="Серебряный бор кишит враждебными зверями, бродячей Плетью и другими опасными силами. Гонцы на дорогах постоянно рискуют попасть в засаду, поэтому воздушные маршруты на летучих мышах — самая быстрая и безопасная связь с Подгородом.",al={"why fly to undercity","why use bats","зачем лететь в подгород","зачем летучие мыши"}},{q="Какие угрозы окружают Гробницу?",a="Гробницу окружают враждебные силы: оставшиеся нежить Плети, ворген, дикие звери и местные людские группировки, из-за чего необходима постоянная боевая готовность и регулярная замена снаряжения.",al={"sepulcher threats","why do deathguards need weapons","угрозы гробнице","зачем стражам смерти оружие"}},{q="Куда ведет это задание дальше?",a="Получив приказ, Карос Раззок организует прямой перелет в Подгород, где заявку можно передать лично Гордону Уиндему.",al={"what quest is next","next after supplying the sepulcher","какое задание дальше","после поставки оружия"}}},fp="23,328,21.597.0,18.443.0,38.243.0,22.159.0,19.163.0,38.216.0,37.207.0,31.167.0"}
P.entries["quest:6322"] = {n="Майкл Гарретт",s="Майкл Гарретт — простое задание курьера, связывающее торговлю в Подгороде с сетью перелетов Отрекшихся. Забрав припасы, упакованные Гордоном Уиндемом в Торговом квартале, вы должны доставить ящик погонщику летучих мышей Майклу Гарретту, чтобы организовать воздушную переправу к Гробнице. Задание показывает, как Отрекшиеся используют обученных летучих мышей-вампиров для связи столицы с аванпостами по всему Лордерону.",h="Майкл Гарретт — простое задание курьера, связывающее торговлю в Подгороде с сетью перелетов Отрекшихся.",kw={"bat master","flight master","gordon wendham","gordon's crate","michael garrett","sepulcher","silverpine","undercity","мастер летучих мышей","распорядитель полетов","гордон уиндем","ящик гордона","майкл гарретт","гробница","серебряный бор","подгород"},ang={["faction:Horde"]="Для путников, прибывших из Калимдора, сеть летучих мышей Отрекшихся — основной способ быстро перемещаться по северу Восточных королевств.",["race:Undead"]="Понимание воздушной линии снабжения, которой управляют погонщики вроде Майкла Гарретта, необходимо для сохранения влияния Сильваны за пределами Тирисфальских лесов."},sec={{t="Снабжение аванпостов",b="Молодому королевству, возникшему на руинах Лордерона, постоянно требуется снабжение. Аванпосты вроде Гробницы в Серебряном бору сильно зависят от товаров, боеприпасов и провизии, которые поступают из Подгорода. Гордон Уиндем упаковывает необходимые полевые припасы в один ящик в Торговом квартале города, но перевозка грузов по земле через зараженные леса медленна и уязвима для засад остатков Плети или диких зверей."},{t="Крылья Отрекшихся",b="Чтобы обойти опасности дорог, Отрекшиеся полагаются на пленных летучих мышей-вампиров, которых разводят и содержат опытные погонщики. Майкл Гарретт присматривает за этими крылатыми тварями со своего насеста в Торговом квартале Подгорода. Доставив ему груз, вы обеспечите отправку припасов на летучей мыши прямо над холмами в Серебряный бор, а новые курьеры узнают, как столица взаимодействует с отдаленными поселениями."}},faq={{q="Кто такой Майкл Гарретт?",a="Майкл Гарретт — погонщик летучих мышей Подгорода, он находится в Торговом квартале. Он управляет летучими мышами-вампирами сети перелетов и организует перевозку людей и грузов по воздуху между столицей Отрекшихся и союзными распорядителями полетов по всему Лордерону.",al={"michael garrett","undercity bat master","who is garrett","майкл гарретт","погонщик летучих мышей подгорода","кто такой гарретт"}},{q="Что в Ящике Гордона?",a="В ящике лежат жизненно важная провизия и полевые припасы, собранные Гордоном Уиндемом в Торговом квартале и предназначенные для сил Отрекшихся в Гробнице в Серебряном бору.",al={"gordon's crate","what supplies","sepulcher crate","ящик гордона","какие припасы","ящик для гробницы"}},{q="Почему используют летучих мышей, а не повозки или лошадей?",a="Сухопутные дороги, ведущие из Тирисфальских лесов в Серебряный бор, полны опасностей: бродячие твари Плети, враждебные люди и коварная местность. Воздушные маршруты на обученных гигантских летучих мышах намного быстрее и полностью обходят засады на земле.",al={"why bat flight","why use bats","flying supplies","почему летучие мыши","зачем летучие мыши","доставка по воздуху"}},{q="Куда идет груз после Майкла Гарретта?",a="Когда Майкл Гарретт получает Ящик Гордона, груз готовят к отправке на летучей мыши прямо к мастеру полетов в Гробнице в Серебряном бору, и логистическая цепочка замыкается.",al={"next step","after michael garrett","where do bats fly","следующий шаг","после майкла гарретта","куда летят летучие мыши"}},{q="Где найти Майкла Гарретта в Подгороде?",a="Он находится в юго-западной части Торгового квартала, там же, где приземляются летучие мыши, прилетающие из Гробницы.",al={"where is garrett","find bat handler","undercity flight master location","где гарретт","найти погонщика летучих мышей","где распорядитель полетов подгорода"}},{q="Нужно ли заранее побывать в Гробнице, чтобы выполнить это задание?",a="Чтобы полететь на летучей мыши вместе с грузом, нужно сначала поговорить с распорядителем полетов в Гробнице и открыть воздушный маршрут; иначе туда придется идти пешком.",al={"sepulcher flight path required","can i fly immediately","маршрут полета в гробницу","можно ли лететь сразу"}}},fp="15,424,22.451.0,21.410.0,23.236.0,26.199.0,40.281.0,49.188.0,48.122.0,60.197.0"}
P.entries["quest:6323"] = {n="Полет в Подгород",s="Полет в Подгород знакомит молодых искателей приключений из числа Отрекшихся с сетью воздушных перелетов Орды в Лордероне. Курьеры везут заявки на оружие из осажденного аванпоста Гробница и на ужасной летучей мыши прилетают прямо в Торговый квартал Подгорода, чтобы пополнить запасы местных защитников.",h="Полет в Подгород знакомит молодых искателей приключений из числа Отрекшихся с сетью воздушных перелетов Орды...",kw={"dread bat","flight master","gordon wendham","karos razok","podrig's order","ride to the undercity","sepulcher","trade quarter","ужасная летучая мышь","распорядитель полетов","гордон уиндем","карос раззок","заказ подрига","полет в подгород","гробница","торговый квартал"},ang={["faction:Horde"]="Распорядители полетов — важнейшая связующая ткань территориальной экспансии Орды: они превращают трудные переходы по глуши в быстрые тактические переброски.",["profession:Blacksmithing"]="Доставка заказов Гордону Уиндему показывает кузнецам логистический хребет Лордерона, где каждый кусок железа остается острым и готовым к войне.",["race:Undead"]="Перелет из Серебряного бора в столицу показывает размах и организованность сети Темной Госпожи, благодаря которой изолированные гарнизоны никогда не отрезаны от промышленности Подгорода."},sec={{t="Крылья над Серебряным бором",b="Для связи между столицей Отрекшихся и передовыми аванпостами нужен быстрый и надежный транспорт. Карос Раззок, погонщик летучих мышей в Гробнице в Серебряном бору, управляет обученными ужасными летучими мышами, которые переносят гонцов и грузы по зараженным землям. Дороги кишат враждебными тварями, воргенами Лунной Ярости и остатками Плети, поэтому полет — самый безопасный и быстрый способ доставить срочные военные запросы в столицу."},{t="Вооружение фронта",b="Приземлившись в шумном Торговом квартале Подгорода, курьер передает заявку Подрига на снаряжение прямо Гордону Уиндему. Как оружейник Подгорода, преданный делу Темной Госпожи, Уиндем следит за тем, чтобы аванпосты вроде Гробницы были обеспечены чистым, готовым к бою оружием. Поддержка этих оборонительных узлов жизненно важна для молодого государства Отрекшихся, укрепляющего границы против окружающих врагов."}},faq={{q="Зачем нужен этот полет в Подгород?",a="Задание заключается в доставке официальной заявки на оружие от Стража смерти Подрига из Гробницы прямо Гордону Уиндему, торговцу оружием из Торгового квартала Подгорода, и учит новых героев пользоваться сетью перелетов Отрекшихся.",al={"why ride to undercity","ride to the undercity objective","podrig's order use","зачем лететь в подгород","цель задания полет в подгород","зачем заявка подрига"}},{q="Кто такой Карос Раззок?",a="Карос Раззок — мастер полетов на летучих мышах в Гробнице в Серебряном бору. Он присматривает за насестом ужасных летучих мышей, на которых Отрекшиеся быстро перемещаются и поддерживают связь с Подгородом.",al={"karos razok role","who is the sepulcher bat master","карос раззок","кто мастер летучих мышей в гробнице"}},{q="Кто такой Гордон Уиндем?",a="Гордон Уиндем — оружейник из Отрекшихся в Торговом квартале Подгорода, рядом с площадкой погонщика летучих мышей. Он гордится тем, что содержит оружие чистым, наточенным и готовым для передовых сил леди Сильваны.",al={"gordon wendham","where is gordon wendham","гордон уиндем","где гордон уиндем"}},{q="Почему Отрекшиеся используют летучих мышей для перелетов?",a="Ужасные летучие мыши — местные ночные хищники, хорошо приспособленные к зараженному небу Лордерона. Они быстро проносят над наземными опасностями, такими как дикие воргены, враждебные гнилокожие и Плеть.",al={"why bats","forsaken flight mounts","почему летучие мыши","летающие скакуны отрекшихся"}},{q="Что происходит после доставки?",a="Получив заявку, Гордон Уиндем направляет курьеров к Майклу Гарретту, погонщику летучих мышей Подгорода, и открывает обратный маршрут к Гробнице.",al={"what comes next","follow up to ride to the undercity","что дальше","продолжение задания полет в подгород"}},{q="Где в Подгороде приземляется ужасная летучая мышь?",a="Ужасная летучая мышь приземляется на приподнятый насест в самом центре Торгового квартала Подгорода, откуда сразу можно дойти до ремесленников и торговцев припасами.",al={"undercity bat landing","where does bat land","посадка летучих мышей в подгороде","где приземляется летучая мышь"}}},fp="21,294,21.489.0,16.446.0,52.261.0,19.198.0,22.239.0,41.202.0,43.166.0,47.181.0"}
P.entries["quest:6324"] = {n="Обратно к Подригу",s="Обратно к Подригу — задание на снабжение, завершающее курьерский рейс между Серебряным бором и Подгородом. Доставив донесение в столицу, курьер получает ящик с оружием, который должен через сеть погонщиков летучих мышей Отрекшихся доставить Стражу смерти Подригу в Гробницу.",h="Обратно к Подригу — задание на снабжение, завершающее курьерский рейс между Серебряным бором и Подгородом.",kw={"bat master","gordons crate","karos razok","michael garrett","podrig","sepulcher","silverpine","undercity","мастер летучих мышей","ящик гордона","карос раззок","майкл гарретт","подриг","гробница","серебряный бор","подгород"},ang={["faction:Horde"]="Это задание показывает логистическую основу, связывающую Подгород с отдаленными аванпостами северного континента.",["race:Undead"]="Вооружение передовых гарнизонов необходимо для обороны Лордерона и защиты молодого королевства королевы Сильваны."},sec={{t="Линия снабжения Подгорода",b="Аванпосты по всему Лордерону сильно зависят от регулярных поставок из Подгорода. В Гробнице в Серебряном бору стражи смерти испытывают давление со стороны местных воргенов, остатков Даларана и отставших бойцов Плети. Снабжение отдаленных гарнизонов свежекованым оружием жизненно важно для удержания региона под контролем Отрекшихся."},{t="Крылья Отрекшихся",b="Мастер полетов Майкл Гарретт управляет главным насестом в Торговом квартале Подгорода, центром воздушных перелетов Отрекшихся. Хотя летучие мыши сами возвращаются в столицу, всадники сначала должны договориться с местными погонщиками вроде Кароса Раззока, прежде чем можно будет проложить маршруты к дальним аванпостам. Перелет с Ящиком Гордона по небу Лордерона учит курьеров, как Отрекшиеся связывают свои разбросанные крепости."}},faq={{q="Что в Ящике Гордона?",a="В ящике лежит свежее оружие, изготовленное в Подгороде, чтобы стражи смерти в Гробнице были как следует вооружены против окружающих угроз.",al={"gordons crate contents","what am i delivering to podrig","содержимое ящика гордона","что я доставляю подригу"}},{q="Кто такой Страж смерти Подриг?",a="Страж смерти Подриг — солдат Отрекшихся в Гробнице в Серебряном бору, ведающий снабжением и обороной местного гарнизона.",al={"podrig","who is podrig","подриг","кто такой подриг"}},{q="Кто такой Майкл Гарретт?",a="Майкл Гарретт — мастер полетов на летучих мышах у Отрекшихся в Торговом квартале Подгорода, отвечающий за согласование маршрутов по всему Лордерону.",al={"michael garrett","undercity bat master","майкл гарретт","мастер летучих мышей подгорода"}},{q="Почему перед полетом нужно поговорить с мастером летучих мышей?",a="Летучие мыши Отрекшихся сами знают дорогу к главному насесту в Подгороде, но для вылета в обратную сторону сначала нужно проложить маршрут с местным погонщиком, чтобы прибытие было безопасным.",al={"flight path rules","how do bat handlers work","правила перелетов","как работают погонщики летучих мышей"}},{q="Почему так важно снабжать Гробницу?",a="Гробница — главная передовая база Отрекшихся в Серебряном бору. Она поддерживает их военное присутствие против стай воргенов, угроз Лунной Ярости и сил Даларана в этой местности.",al={"why sepulcher matters","sepulcher importance","почему важна гробница","значение гробницы"}},{q="Кто такой Карос Раззок?",a="Карос Раззок — мастер полетов на летучих мышах в Гробнице в Серебряном бору, управляющий насестом, который связывает аванпост с Подгородом.",al={"karos razok","sepulcher bat master","карос раззок","мастер летучих мышей в гробнице"}}},fp="16,292,25.353.0,21.419.0,26.156.0,25.154.0,23.151.0,65.183.0,44.178.0,19.143.0"}
P.entries["quest:633"] = {n="Мост Тандола",s="Это важное задание Альянса поручает героям защитить единственный уцелевший мост через Мост Тандола. После убийства Эбенизера Растлока Раг Каменщик раскрывает заговор предателя Кама Гневливого, который хочет взорвать спрятанную взрывчатку и перерезать жизненно важную связь Стальгорна с севером.",h="Это важное задание Альянса поручает героям защитить единственный уцелевший мост через Мост Тандола.",kw={"arathi highlands","dark iron","ebon rustlocke","explosives","kam deepfury","magni bronzebeard","rhag garmason","thandol span","wetlands","нагорье арати","черное железо","эбенизер растлок","взрывчатка","кам гневливый","магни бронзобород","раг каменщик","мост тандола","болотина"},ang={["faction:Alliance"]="Удержание Моста необходимо для безопасности всего континента: если эта переправа падет, переброска армий и ресурсов Альянса в Арати и Лордерон станет намного опаснее.",["profession:Engineering"]="Инженеры оценят чудовищную разрушительную силу тайника Гневливого со взрывчаткой, созданного, чтобы разрушить колоссальную дворфийскую каменную кладку в стиле титанов.",["race:Dwarf"]="Для сынов Стальгорна защита Моста Тандола охраняет жизненную связь короля Магни с северными союзниками и наносит удар по предательским лазутчикам из клана Черного Железа."},sec={{t="Раскрытый заговор",b="Узнав о печальной судьбе Эбенизера Растлока в основании Моста Тандола, найденный документ проливает свет на более мрачные замыслы. Агитатор из клана Черного Железа Кам Гневливый, устроивший первое разрушение моста, не закончил дело. Уже обрушив одну из великих каменных переправ, его сеть диверсантов спрятала второй тайник с тяжелыми боеприпасами сразу за северной границей, в Нагорье Арати, готовый довершить начатое."},{t="Спасение жизненной артерии",b="Мост Тандола — главный сухопутный путь, соединяющий южные королевства Каз Модан и Штормград с охваченными войной землями севера. Чтобы защитить этот путь, Раг Каменщик приказывает немедленно нанести упреждающий удар по тайнику диверсантов в Арати, пока заговорщики Гневливого не пустили его в ход. Взрыв боеприпасов устраняет непосредственную угрозу и сохраняет Стальгорну доступ на север, хотя Каменщику отчаянно не хватает солдат для обороны прохода."}},faq={{q="Кто такой Кам Гневливый?",a="Кам Гневливый — дворф из клана Черного Железа, организатор диверсии на Мосту Тандола. Не удовлетворившись обрушением первой арки, он спрятал дополнительную взрывчатку за ущельем в Нагорье Арати, чтобы уничтожить оставшийся мост.",al={"kam deepfury","who bombed thandol span","thandol span mastermind","кам гневливый","кто взорвал мост тандола","организатор диверсии на мосту тандола"}},{q="Почему Мост Тандола так важен стратегически?",a="Мост — единственный сухопутный мост через огромное ущелье между Болотиной и Нагорьем Арати. Если его разрушить, Альянс потеряет главный сухопутный путь снабжения между Стальгорном, Штормградом и союзниками, удерживающими позиции на севере Лордерона.",al={"why is thandol span important","thandol span lore","почему важен мост тандола","предания моста тандола"}},{q="Что случилось с Эбенизером Растлоком?",a="Эбенизер Растлок был защитником Стальгорна, убитым в глубинах под мостом. Именно по его расследованию и бумагам, найденным после его гибели, Раг Каменщик обнаружил спрятанный тайник Гневливого со взрывчаткой.",al={"ebon rustlocke death","who was rustlocke","смерть эбенизера растлока","кто такой растлок"}},{q="Где спрятан тайник со взрывчаткой?",a="Взрывчатка спрятана в тайнике сразу за мостом, со стороны Нагорья Арати, достаточно близко, чтобы заговорщики Гневливого могли быстро доставить ее к уцелевшей части моста.",al={"explosives location","where are the explosives","cache location","где взрывчатка","расположение взрывчатки","где тайник"}},{q="Кто отдает приказ уничтожить взрывчатку?",a="Раг Каменщик, офицер-дворф на Мосту Тандола со стороны Болотины, отдает приказ найти и уничтожить тайник, чтобы почтить жертву Растлока и защитить оставшийся мост.",al={"who starts this quest","rhag garmason","кто дает это задание","раг каменщик"}},{q="Что происходит после уничтожения боеприпасов?",a="Хотя немедленная диверсия сорвана, Раг Каменщик понимает, что его гарнизон не сможет долго удерживать поврежденный мост без помощи. В ожидании резервов Стальгорна он отправляет просьбу о подкреплении капитану Ниалс из лагеря Альянса в Опорном пункте на Нагорье Арати.",al={"what next after thandol span","plea to the alliance quest","что дальше после моста тандола","задание просьба к альянсу"}}},fp="16,308,15.456.0,19.482.1,20.252.0,47.268.0,36.222.1,40.195.0,46.196.0,47.287.1"}
P.entries["quest:634"] = {n="Просьба о помощи",s="«Просьба о помощи» — отчаянная просьба о подкреплении от выживших дворфов-защитников Дун Модра, переданная через Мост Тандола в Арати. После того как гарнизон был вырезан лазутчиками клана Черного Железа, дворфы просят помощи у людей, расквартированных в Опорном пункте, но обнаруживают, что силы Альянса и так истощены до предела.",h="«Просьба о помощи» — отчаянная просьба о подкреплении от выживших дворфов-защитников Дун Модра, переданная...",kw={"arathi highlands","captain nials","dark iron","dun modr","longbraid","refuge pointe","rhag garmason","stromgarde","thandol span","нагорье арати","капитан ниалс","черное железо","дун модр","длиннокос","опорный пункт","раг каменщик","стромгард","мост тандола"},ang={["faction:Alliance"]="Этот обмен показывает, насколько раздроблен Альянс на севере Восточных королевств: местные гарнизоны ведут отдельные отчаянные бои без общих резервов.",["race:Dwarf"]="Для дворфов это поручение показывает мучительную изоляцию северных гарнизонов вроде Дун Модра: даже давние союзники-люди слишком осаждены, чтобы протянуть руку помощи."},sec={{t="Крик через пропасть",b="После разрушения Дун Модра и диверсии дворфов Черного Железа на Мосту Тандола уцелевшие дворфы удерживают шаткий рубеж на северном краю Болотины. Основные резервы Стальгорна еще не прибыли, и Раг Каменщик с командиром Длиннокосом смотрят на север, в сторону Нагорья Арати. Узнав о лагере Альянса в Опорном пункте, Раг отправляет посланника через разрушенный мост просить капитана Ниалс о срочной военной помощи."},{t="Бедствие Стромгарда",b="Прибыв в Опорный пункт, гонец видит мрачную действительность северного Альянса. Капитан Ниалс искренне сочувствует солдатам Длиннокоса, но не может выделить ни одного бойца. Сам Стромгард лежит в руинах, захваченный разбойниками Синдиката, ограми Тяжелого Кулака и троллями Сухокожих. Оставшиеся защитники Стромгарда целиком заняты возвращением своей древней столицы. Связанный честью и собственным отчаянным положением, Ниалс вынужден передать, что дворфам на мосту придется рассчитывать только на себя."}},faq={{q="Кто посылает просьбу о помощи в Опорный пункт?",a="Раг Каменщик, находящийся у разрушенного края Моста Тандола на границе Болотины, посылает просьбу от имени командира Длиннокоса и остатков обороны Дун Модра.",al={"who gives plea to the alliance","rhag garmason quest","who asks for help","кто дает просьбу о помощи","задание раг каменщик","кто просит о помощи"}},{q="Почему дворфам нужна помощь из Опорного пункта?",a="Дун Модр пал после внезапного и жестокого нападения лазутчиков клана Черного Железа, которые также устроили диверсию на Мосту Тандола. Пока выжившие ждут крупных резервов из Стальгорна, их слишком мало, чтобы самим отбить поселение и защитить переправу.",al={"why need alliance help","why ask refuge pointe","dun modr reinforcements","зачем нужна помощь альянса","почему просят опорный пункт","подкрепление дун модр"}},{q="Почему капитан Ниалс отказывается присылать солдат?",a="Капитан Ниалс не может выделить войска, потому что королевство Стромгард само лежит в руинах. Силы людей в Опорном пункте полностью заняты отчаянной кампанией по возвращению Стромгарда у Синдиката, огров и лесных троллей.",al={"why no help from nials","why refuge pointe refuses","captain nials answer","почему ниалс не помогает","почему опорный пункт отказывает","ответ капитана ниалса"}},{q="Где находится Опорный пункт?",a="Опорный пункт расположен недалеко от главной дороги в центре Нагорья Арати, к северу от переправы Моста Тандола между Болотиной и Арати.",al={"refuge pointe location","where is captain nials","how to find refuge pointe","опорный пункт расположение","где капитан ниалс","как найти опорный пункт"}},{q="Что случилось с Дун Модром?",a="Дун Модр был захвачен и разграблен кланом Черного Железа, который проник через горы, чтобы перерезать сухопутный путь между южными землями дворфов и северными владениями Альянса.",al={"dun modr lore","what happened dun modr","who attacked dun modr","предания дун модр","что случилось с дун модром","кто напал на дун модр"}},{q="Что происходит после того, как капитан Ниалс отклоняет просьбу?",a="Капитан Ниалс передает командиру Длиннокосу свои сожаления: подкрепления от людей не будет. Выжившим дворфам у моста придется полагаться на собственную смекалку, странствующих искателей приключений и далекие подкрепления из Стальгорна.",al={"what next plea to the alliance","next quest after plea","chain continuation","что дальше просьба о помощи","следующее задание после просьбы","продолжение цепочки"}}},fp="20,349,22.483.0,24.543.0,36.183.0,48.264.0,47.248.0,31.142.0,26.194.0,56.233.0"}
P.entries["quest:6341"] = {n="Изобилие Тельдрассила",s="«Изобилие Тельдрассила» — вводное поручение, которое выдает Несса Песня Теней в Деревне Рут'теран. Желая сравнить необычные размеры и обилие рыбы у острова с уловом на материке, она собирает кости и чешую, чтобы отправить их через пролив на Темные берега. Передав посылку местному мастеру гиппогрифов, вы делаете первый шаг к пересечению моря до Аубердина.",h="«Изобилие Тельдрассила» — вводное поручение, которое выдает Несса Песня Теней в Деревне Рут'теран.",kw={"auberdine","bounty of teldrassil","darkshore","hippogryph","laird","nessa shadowsong","rut'theran village","vesprystus","аубердин","изобилие тельдрассила","темные берега","гиппогриф","лайрд","несса песня теней","деревня рут'теран","весприст"},ang={["faction:Alliance"]="Путь между Рут'теран и Аубердином служит важной транспортной артерией, связывающей столицу ночных эльфов с остальным северным Калимдором.",["race:NightElf"]="Для путников-ночных эльфов это путешествие — традиционный спуск с безопасных высот Тельдрассила к сумрачным материковым берегам Темных берегов."},sec={{t="Исследование рыбака",b="Под огромными ветвями Мирового Древа защищенные воды вокруг Деревни Рут'теран кишат на удивление крупной и многочисленной морской живностью. Несса Песня Теней, наблюдая за поразительными уловами местных рыбаков, хочет выяснить, распространяется ли эта жизненная сила на древнее побережье материка или свойственна только водам, питаемым Тельдрассилом. Чтобы проверить свою теорию, она собирает чешую и кости для изучения Лайрдом, торговцем рыбой, живущим за водой, в Аубердине."},{t="Организация перелета",b="Чтобы перевозить грузы и путников через открытый пролив между островной ветвью и материковым Калимдором, нужны надежные крылья. Вместо того чтобы отправлять посылку на небольшой лодке, Несса направляет путников прямо к Веспристу, мастеру гиппогрифов деревни. Передав ему сборник образцов, путники договариваются о том, чтобы сесть на обученного зверя и доставить образцы прямо на причалы Темных берегов."}},faq={{q="Что пытается выяснить Несса?",a="Несса Песня Теней заметила, что рыба, выловленная в водах вокруг Деревни Рут'теран, необычайно крупная и многочисленная. Она хочет отправить образцы костей и чешуи через пролив, чтобы сравнить улов Тельдрассила с рыбой у материкового побережья Темных берегов.",al={"nessa goal","why compare fish","bounty of teldrassil purpose","цель нессы","зачем сравнивать рыбу","смысл изобилия тельдрассила"}},{q="Кто получает образцы рыбы в Аубердине?",a="Посылка адресована Лайрду, торговцу рыбой, живущему в прибрежной деревне Аубердин на материковом берегу Темных берегов.",al={"who gets nessa collection","laird darkshore","auberdine fish vendor","кто получает посылку нессы","лайрд темные берега","торговец рыбой аубердин"}},{q="Почему посылку нужно нести Веспристу, а не добираться до Аубердина самому?",a="Весприст — мастер гиппогрифов в Деревне Рут'теран. Передав ему посылку, вы организуете прямую воздушную доставку и получите место на гиппогрифе для перелета через море на Темные берега.",al={"why vesprystus","who is vesprystus","hippogryph master ruttheran","почему весприст","кто такой весприст","мастер гиппогрифов рут'теран"}},{q="Где находится Деревня Рут'теран относительно Тельдрассила?",a="Деревня Рут'теран расположена у южного основания Тельдрассила на уровне моря и соединена с Дарнассом изумрудным порталом. Это главная прибрежная гавань для кораблей и гиппогрифов, летящих к великому дереву и от него.",al={"rut'theran location","where is nessa shadowsong","how to reach ruttheran","расположение рут'теран","где несса песня теней","как добраться до рут'теран"}},{q="Что происходит после передачи посылки Веспристу?",a="Весприст принимает посылку и предлагает следующее задание — «Полет в Аубердин», которое отправит вас на гиппогрифе через пролив прямо на Темные берега.",al={"flight to auberdine next","after bounty of teldrassil","what does vesprystus do","полет в аубердин дальше","после изобилия тельдрассила","что делает весприст"}},{q="Это часть выхода ночных эльфов из начальной зоны?",a="Да. Эта цепочка знакомит молодых ночных эльфов-искателей приключений с маршрутами полета и выводит их из островной кроны вниз, к материковому Калимдору, чтобы продолжить путь на Темных берегах.",al={"leaving teldrassil","level 10 night elf quest","moving to darkshore","покинуть тельдрассил","задание ночных эльфов 10 уровня","переезд на темные берега"}}},fp="24,405,19.514.0,17.410.0,36.280.0,47.133.0,77.202.0,62.236.0,55.178.0,58.182.0"}
P.entries["quest:6342"] = {n="Полет в Аубердин",s="Это поручение знакомит покидающих Тельдрассил искателей приключений с воздушной транспортной сетью ночных эльфов. По заданию мастера гиппогрифов Весприста из Деревни Рут'теран путники летят через море, чтобы доставить Лайрду в Аубердин связку крупных морских образцов.",h="Это поручение знакомит покидающих Тельдрассил искателей приключений с воздушной транспортной сетью ночных...",kw={"auberdine","darkshore","flight path","flight to auberdine","hippogryph","laird","nessa shadowsong","rut'theran village","teldrassil","vesprystus","аубердин","темные берега","маршрут полета","полет в аубердин","гиппогриф","лайрд","несса песня теней","деревня рут'теран","тельдрассил","весприст"},ang={["faction:Alliance"]="Гиппогрифы служат основной воздушной сетью Альянса по всему северному Калимдору, напрямую связывая прибрежные форпосты со столицей.",["race:NightElf"]="Полет на гиппогрифе в Аубердин — знаковый обряд перехода для юных кальдораев, выходящих из Тельдрассила на древний материк."},sec={{t="На крыльях к Темным берегам",b="Для многих юных искателей приключений, покидающих ветви Тельдрассила, Деревня Рут'теран — порог между убежищем и большим миром. Хотя через пролив между островным приютом и материковым Калимдором ходит обычный паром, ночные эльфы не меньше полагаются на своих прирученных гиппогрифов. Получив от Нессы Песни Теней посылку с редкими частями рыб, путники садятся на одного из крылатых зверей и прокладывают свой первый маршрут полета к берегам Темных берегов."},{t="Любопытный улов",b="Эта доставка очень интересна рыбакам Темных берегов. Лайрд, ожидающий результатов Нессы на причалах Аубердина, осматривает улов и находит огромную чешую размером с кулак и челюстную кость почти вдвое больше, чем у материковых образцов. Воды острова у основания Мирового Древа, похоже, порождают измененную или необычно крупную жизнь — любопытный факт, намекающий на могучую, неспокойную природу самого Тельдрассила."}},faq={{q="Какова цель этого полета?",a="Путешествие служит практическим уроком по связыванию маршрутов полета между поселениями, а также доставляет Лайрду в Аубердин исследовательские образцы необычной рыбы, пойманной возле Деревни Рут'теран.",al={"why do i fly to auberdine","flight to auberdine quest goal","why fly","зачем лететь в аубердин","цель задания полет в аубердин","зачем лететь"}},{q="Кто посылает посылку и что в ней?",a="Посылку отправила рыбачка Несса Песня Теней. В ней образцы рыбы из вод вокруг Деревни Рут'теран, включая огромную чешую и непомерно большую челюстную кость.",al={"nessa's collection","what is in the package","who sent package","сборник нессы","что в посылке","кто отправил посылку"}},{q="Почему рыба из Тельдрассила такая крупная?",a="Лайрд отмечает, что челюстная кость почти вдвое больше обычной, а чешуя размером с кулак. Воды вокруг Мирового Древа Тельдрассила порождают странно увеличенную живность по сравнению с материковыми берегами Темных берегов.",al={"why are fish big","rut'theran fish size","huge scales","почему рыба большая","размер рыбы рут'теран","огромная чешуя"}},{q="Кто такой Весприст?",a="Весприст — мастер гиппогрифов в Деревне Рут'теран. Он ухаживает за ездовыми животными ночных эльфов и руководит воздушными перелетами через воду на материковый Калимдор.",al={"vesprystus lore","who is the hippogryph master","предания весприст","кто мастер гиппогрифов"}},{q="Кто такой Лайрд?",a="Лайрд — рыбак из ночных эльфов, живущий в Аубердине на побережье Темных берегов. Он изучает местную водную жизнь и сравнивает материковый улов с уловом возле Тельдрассила.",al={"laird lore","who is laird","laird darkshore","предания лайрд","кто такой лайрд","лайрд темные берега"}},{q="Можно ли добраться между Рут'теран и Аубердином без полета?",a="Да. Между причалами Деревни Рут'теран и пристанью Аубердина ходит обычный паром — альтернатива полету на гиппогрифе.",al={"boat to auberdine","ferry to darkshore","other way to auberdine","лодка в аубердин","паром на темные берега","другой путь в аубердин"}}},fp="19,272,24.467.0,15.428.0,35.198.0,44.182.0,42.226.0,18.169.0,13.174.0,63.147.0"}
P.entries["quest:6343"] = {n="Возвращение к Нессе",s="Это задание отправляет юных путников из Аубердина обратно в Деревню Рут'теран, чтобы передать Нессе Песне Теней результаты наблюдений Лайрда. Оно завершает вводное поручение, обучающее искателей приключений пользоваться транспортом между материком Калимдора и Тельдрассилом.",h="Это задание отправляет юных путников из Аубердина обратно в Деревню Рут'теран, чтобы передать Нессе Песне...",kw={"auberdine","caylais moonfeather","darkshore","laird","nessa shadowsong","return to nessa","rut'theran village","teldrassil","аубердин","кайлаис лунное перо","темные берега","лайрд","несса песня теней","возвращение к нессе","деревня рут'теран","тельдрассил"},ang={["faction:Alliance"]="Аубердин и Деревня Рут'теран образуют важные морские врата, связывающие поселения ночных эльфов на севере Калимдора с более широкими интересами Альянса в Азероте.",["race:NightElf"]="Для ночных эльфов, впервые покидающих ветви Тельдрассила, это поручение становится первым официальным заданием, связывающим новый островной приют с древним материком Темных берегов."},sec={{t="Посланник за морем",b="Передав Лайрду в Аубердине первые вопросы Нессы Песни Теней, путники получают поручение отнести его письменные наблюдения обратно через воду. Лайрд отмечает резкую разницу в улове рыбы у Темных берегов и у берегов Тельдрассила и подозревает, что само великое Мировое Древо изменяет местную морскую жизнь. Чтобы вернуться в Деревню Рут'теран, искатели приключений могут нанять полет у мастера гиппогрифов Кайлаис Лунное Перо или сесть на обычный паром, отходящий от пристани Аубердина."},{t="Удивительное изобилие",b="Получив ответ Лайрда в Деревне Рут'теран, Несса выражает восхищение заметным различием в морской жизни. Огромные размеры рыбы возле Мирового Древа сразу приносят пользу местным рыбакам, но причина этого остается открытым вопросом среди кальдораев. Несса решает поделиться выводами с односельчанами и пока довольствуется обильным уловом, внимательно следя за тем, какие силы могут быть тому причиной."}},faq={{q="Кто выдает и принимает это задание?",a="Задание выдает рыбак Лайрд в Аубердине на побережье Темных берегов. Сдать его нужно Нессе Песне Теней в Деревне Рут'теран, у подножия Тельдрассила.",al={"quest giver","where to turn in","who gives quest","кто выдает задание","где сдать","персонаж, выдающий задание"}},{q="Как быстрее всего вернуться в Деревню Рут'теран?",a="Вы можете быстро долететь на гиппогрифе, поговорив с Кайлаис Лунное Перо в Аубердине, или дойти до длинной пристани и сесть на обычный пассажирский паром до причалов Деревни Рут'теран.",al={"how to get back","travel to ruttheran","ferry or hippogryph","как вернуться","добраться до рут'теран","паром или гиппогриф"}},{q="Почему Лайрд изучает рыбу?",a="Лайрд замечает, что морской улов у Темных берегов резко отличается от улова у Тельдрассила. Он подозревает, что бурный рост и особые силы Мирового Древа напрямую изменяют окружающих животных.",al={"why study fish","fish difference","laird response lore","зачем изучать рыбу","разница рыбы","ответ лайрда"}},{q="Узнает ли Несса, почему рыба такая необычная?",a="Не сразу. Несса отмечает поразительную разницу и соглашается, что это требует дальнейшего изучения, но пока она довольствуется тем, что делится отчетом с местными жителями и наслаждается богатым уловом.",al={"why are fish big","teldrassil fish mystery","почему рыба большая","загадка рыбы тельдрассила"}},{q="Что предшествует этому заданию?",a="Это задание непосредственно следует за заданием «Полет в Аубердин», которое отправляет путников из Деревни Рут'теран на Темные берега с первоначальным письмом Нессы к Лайрду.",al={"prerequisite","previous quest","flight to auberdine","предыдущее задание","требование","полет в аубердин"}},{q="Для чего нужна эта цепочка заданий?",a="Помимо знакомства с загадочным влиянием Тельдрассила на местную природу, эта цепочка поручений служит обрядом посвящения, обучая юных ночных эльфов-искателей приключений добираться с родного острова на материк Калимдора на корабле и с помощью распорядителя полетов.",al={"why do this quest","travel quest","зачем выполнять задание","задание на путешествие"}}},fp="15,253,26.515.0,16.478.0,36.166.0,51.205.0,31.234.0,48.213.0,29.153.0,40.267.0"}
P.entries["quest:6344"] = {n="Несса Песня Теней",s="Несса Песня Теней — вводное задание на доставку, которое выдает Мидраннул в Дарнассе. Оно ведет начинающих искателей приключений с Мирового Древа в Деревню Рут'теран, к торговке рыбой Нессе Песне Теней. Это первый шаг, связывающий столицу в кронах с берегами и гаванями внизу.",h="Несса Песня Теней — вводное задание на доставку, которое выдает Мидраннул в Дарнассе.",kw={"auberdine","courier","darkshore","darnassus","mydrannul","nessa shadowsong","portal","rut'theran village","temple gardens","аубердин","курьер","темные берега","дарнасс","мидраннул","несса песня теней","портал","деревня рут'теран","храмовые сады"},ang={["faction:Alliance"]="Это поручение знакомит с важной сетью снабжения, связывающей изолированный остров Тельдрассил с остальными землями Альянса на Калимдоре.",["race:NightElf"]="Для ночных эльфов-искателей приключений это путешествие знаменует традиционный путь от безмятежных высот Дарнасса к оживленным прибрежным дорогам, связывающим их новый дом с древними берегами Темных берегов."},sec={{t="Поручение за пределами крон",b="В Дарнассе Мидраннул присматривает за путниками, ищущими работу и цель. Когда торговке рыбой Нессе Песне Теней нужно доставить посылку через море на Темные берега, Мидраннул направляет способных курьеров к побережью. Многие юные ночные эльфы проводят первые странствия среди ветвей Тельдрассила, и эта простая просьба побуждает их взглянуть на материк."},{t="Спуск к докам",b="Чтобы попасть в Деревню Рут'теран, нужно шагнуть в светящиеся корни западного портала города возле Храмовых садов. Врата спускаются сквозь Мировое Древо к его корням на уровне океана, где рыбацкие доки и насесты гиппогрифов связывают Тельдрассил с остальным Калимдором. Там Несса Песня Теней занимается своим делом, готовя грузы для портового поселения Аубердин."}},faq={{q="Кто выдает это задание?",a="Задание выдает Мидраннул, находящийся в Дарнассе, на Террасе Воинов.",al={"quest giver","where to get nessa shadowsong quest","mydrannul location","кто выдает задание","где взять задание несса песня теней","где мидраннул"}},{q="Как добраться до Деревни Рут'теран?",a="Идите на запад от Храмовых садов в Дарнассе. Войдите в большой светящийся портал в дереве, и вы мгновенно окажетесь в Деревне Рут'теран у подножия Тельдрассила.",al={"how to reach ruttheran","rut'theran portal","exit darnassus","как добраться до рут'теран","портал рут'теран","выход из дарнасса"}},{q="Кто такая Несса Песня Теней?",a="Несса Песня Теней — эльфийка, снабжающая рыбаков, которая работает на доках Деревни Рут'теран. Она ведает товарами и посылками, которые перевозят между Тельдрассилом и материком у Темных берегов.",al={"nessa shadowsong role","what does nessa do","nessa shadowsong npc","роль нессы песни теней","чем занимается несса","несса песня теней нпс"}},{q="Куда ведет эта цепочка заданий?",a="Разговор с Нессой сразу ведет к заданию «Изобилие Тельдрассила», которое знакомит искателей приключений с распорядителем полетов и дарит им первый полет через воду в Аубердин.",al={"what comes after nessa shadowsong","next quest in chain","teldrassil flight chain","что после нессы песни теней","следующее задание цепочки","цепочка полетов тельдрассила"}},{q="Родственна ли Несса Маив Песня Теней?",a="Хотя у них одна фамилия — Песня Теней, никакой личной связи между Нессой, скромной торговкой рыбой с доков, и легендарной стражницей Маив Песня Теней не известно.",al={"nessa maiev relation","shadowsong family","is nessa related to maiev","несса и маив","семья песни теней","родственница ли несса маив"}},{q="Чем это поручение важно для юных искателей приключений?",a="Оно служит главной путеводной нитью, обучая новых героев покидать крону Тельдрассила, находить доки внизу и пользоваться маршрутами полета на гиппогрифах, чтобы добраться до материка Калимдора.",al={"why do this quest","significance of quest","зачем выполнять задание","значение задания"}}},fp="16,310,26.391.0,23.390.0,22.85.0,35.171.0,24.179.0,33.183.0,37.175.0,51.198.0"}
P.entries["quest:6361"] = {n="Связка шкур",s="Связка шкур — вводное задание на доставку в Степях, которое выдает таурен Джахан Соколиное Крыло на Перекрестке. Он просит путников отвезти выделанные шкуры дичи через центральный Калимдор в Громовой Утес для кожевничества. Поручение знакомит новых курьеров Орды с насестом ветрокрылов на Перекрестке и принципами воздушных перевозок.",h="Связка шкур — вводное задание на доставку в Степях, которое выдает таурен Джахан Соколиное Крыло на...",kw={"ahanu","bundle of hides","crossroads","devrak","jahan hawkwing","leatherworking","the barrens","thunder bluff","wind rider","ахану","связка шкур","перекресток","деврак","джахан соколиное крыло","кожевничество","степи","громовой утес","ветрокрыл"},ang={["faction:Horde"]="Доставка показывает систему снабжения, связывающую базы Орды в Калимдоре, и опору на орков — укротителей зверей, таких как Деврак, которые преодолевают расстояния между союзными землями.",["race:Tauren"]="Для путешественников-таурен это поручение отражает давнее сотрудничество между странствующими охотниками в исконных Степях и ремесленниками, обосновавшимися на огромных плоскогорьях Громового Утеса."},sec={{t="Торговля через саванну",b="Перекресток — оживленный центр торговли и путешествий по Степям, соединяющий орков, троллей и тауренов на засушливых равнинах. Охотники постоянно добывают шкуры и мясо у бродящих по саванне зверей, но в местных аванпостах нет возможностей переработать все сырье на месте. Джахан Соколиное Крыло собирает шкуры с местных охот и надеется на проезжих путников, которые доставят их на запад, в Громовой Утес, где мастера-кожевники могут изготовить необходимое снаряжение для Орды."},{t="Навстречу небесам",b="Нести тяжелый груз пешком по неровным тропам Степей и в Мулгор — изнурительный путь, где грозят засады свинобразов и хищники. Чтобы ускорить торговлю, Джахан направляет курьеров прямо к Девраку, мастеру ветрокрылов на Перекрестке. Доверив груз Девраку и взлетев на обученной виверне, вы увидите жизненно важную сеть снабжения, связывающую разбросанные поселения Орды."}},faq={{q="Кто выдает задание «Связка шкур»?",a="Задание выдает Джахан Соколиное Крыло, таурен с Перекрестка в Степях. Он собрал шкуры местных животных и ищет надежного курьера, чтобы переправить их в Громовой Утес.",al={"quest giver","who starts a bundle of hides","where to get bundle of hides","кто выдает задание","кто начинает связку шкур","где взять связку шкур"}},{q="Кому отнести связку шкур?",a="You need to take the bundle directly to Devrak, the orc wind rider master stationed at the Crossroads perch. He handles aerial transit between the Crossroads and other major Horde hubs.",al={"turn in npc","where to take hides","who do i talk to","кому сдать","куда отнести шкуры","с кем говорить"}},{q="Что происходит после передачи шкур Девраку?",a="Деврак дает следующее поручение: сесть на ветрокрыла и доставить груз прямо Ахану, кожевнику, ожидающему на высоких утесах Громового Утеса.",al={"next quest","what after a bundle of hides","follow up quest","следующее задание","что после связки шкур","продолжение задания"}},{q="Почему эти шкуры отправляют в Громовой Утес?",a="Джахан Соколиное Крыло работает с коллегой по имени Ахану в Громовом Утесе, который превращает сырые шкуры степной дичи в готовые кожаные доспехи и изделия для тауренов и их союзников по Орде.",al={"why thunder bluff","ahanu hides","what are hides for","почему громовой утес","ахану шкуры","для чего шкуры"}},{q="Почему лучше лететь на ветрокрыле, а не идти пешком?",a="Путь пешком через просторы Степей и подъем на огромную гору Громового Утеса опасны и медленны. Ветрокрыл обеспечивает быстрый и безопасный перелет над враждебными зверями саванны и стаями свинобразов.",al={"why fly to thunder bluff","wind rider travel","зачем лететь в громовой утес","полет на ветрокрыле"}},{q="Нужен ли для этого опыт работы с распорядителями полетов?",a="Это задание задумано как раннее знакомство с системой полетов для искателей приключений Орды: оно знакомит вас с насестом Деврака, чтобы вы могли использовать ветрокрылов для дальних перелетов по региону.",al={"flight path requirement","do i need flight path","требование маршрута полета","нужен ли маршрут полета"}}},fp="17,347,24.480.0,19.410.0,38.193.0,42.185.0,46.168.0,48.184.0,40.212.0,49.202.0"}
P.entries["quest:6363"] = {n="Укротитель ветрокрылов Тал",s="«Укротитель ветрокрылов Тал» — простое курьерское задание, связывающее кожевников Мулгора с торговцами в Степях. Кожевник Ахану поручает доставить по воздуху из Громового Утеса сверток с готовыми шкурами. Доставка прямо к Талу, укротителю ветрокрылов на плато, знакомит юных путешественников Орды с сетью перелетов на ветрокрылах.",h="«Укротитель ветрокрылов Тал» — простое курьерское задание, связывающее кожевников Мулгора с торговцами в...",kw={"ahanu","crossroads","devrak","flight master","jahan","leather goods","tal","thunder bluff","wind rider","ахану","перекресток","деврак","укротитель ветрокрылов","джахан","кожаные изделия","тал","громовой утес","ветрокрыл"},ang={["faction:Horde"]="Надежные воздушные маршруты между Степями и Громовым Утесом позволяют быстро доставлять по центральному Калимдору подкрепления, товары и вести.",["race:Tauren"]="Ветрокрылы, гнездящиеся на утесах Громового Утеса, — жизненно важная связь, благодаря которой народ Кэрна Кровавого Копыта, живущий уединенно, остается частью союза Орды."},sec={{t="Снабжение Перекрестка",b="Торговля между Мулгором и засушливыми зарослями Степей жизненно важна для молодой Орды. Ахану, кожевник, торгующий на нижнем уступе Громового Утеса, изготавливает прочные кожаные изделия для торговой лавки Джахана Соколиного Крыла на Перекрестке. Путь по суше вниз с утесов и через золотистые равнины занимает часы, поэтому торговцы полагаются на крылатых курьеров, которые переправляют хрупкие или срочные посылки через скалистую преграду."},{t="Хозяин насеста на плато",b="На самом высоком центральном уступе Громового Утеса живет Тал, который присматривает за городской стаей ветрокрылов, также известных как виверны. Эти разумные кожистокрылые звери прекрасно приспособлены для полетов над непредсказуемыми тепловыми потоками и неприступными вершинами Калимдора. Тал координирует рейсы в такие форпосты, как Перекресток, благодаря чему гонцы и грузы быстро доставляются между столицей таурен и их союзниками-орками."}},faq={{q="Кто такой Тал?",a="Тал — укротитель ветрокрылов Громового Утеса, управляющий насестом ветрокрылов на центральном плато. Он занимается воздушными перевозками для путешественников и курьеров, отправляющихся в Степи и дальше.",al={"who is tal","tal thunder bluff","wind rider master tal","кто такой тал","тал громовой утес","укротитель ветрокрылов тал"}},{q="Кто такой Ахану?",a="Ахану — таурен-кожевник, живущий в Громовом Утесе. Он готовит большие партии кожаных изделий и связывает их в тюки для торговцев в поселениях по всему Калимдору, в том числе для Джахана Соколиного Крыла на Перекрестке.",al={"ahanu","who is ahanu","ahanu thunder bluff","ахану","кто такой ахану","ахану громовой утес"}},{q="Почему товары нужно доставить на Перекресток?",a="Перекресток — важнейший торговый и военный узел Степей. Товары, произведенные в тихом Мулгоре, такие как шкуры и кожаная одежда, отправляют туда для снабжения путешественников, охотников и патрулей Орды.",al={"why crossroads","leather goods crossroads","jahan leather","почему перекресток","кожаные изделия перекресток","кожа джахана"}},{q="Могу ли я долететь прямо до Перекрестка с этой посылкой?",a="Долететь до Перекрестка можно, только если вы уже побывали в поселении и наладили связь с Девраком, местным укротителем ветрокрылов. Если этот маршрут еще не открыт, придется идти пешком по суше.",al={"can i fly to crossroads","tal flight path","how to fly to crossroads","могу ли я долететь до перекрестка","маршрут полета тала","как долететь до перекрестка"}},{q="Что такое ветрокрылы?",a="Ветрокрылы, которых обычно называют вивернами, — разумные ядовитые крылатые хищники, обитающие в скалах Калимдора. Со времен Третьей войны они союзники Орды и служат ее основными воздушными скакунами.",al={"wyverns","what is a wind rider","tauren mounts","виверны","что такое ветрокрыл","скакуны тауренов"}},{q="Куда ведет это курьерское поручение дальше?",a="Когда вы доставите товары Талу, он велит вам взять скакуна и отвезти посылку Ахану через равнины Джахану Соколиному Крылу, который ждет на Перекрестке.",al={"next quest","what after tal","where do leather goods go","следующее задание","что после тала","куда везти кожаные изделия"}}},fp="25,339,27.439.0,26.421.0,11.198.0,13.208.0,46.235.0,54.220.0,21.204.0,41.159.0"}
P.entries["quest:6364"] = {n="Возвращение к Джахану",s="«Возвращение к Джахану» — заключительная часть знакомства с сетью перелетов Орды на ветрокрылах между Мулгором и Степями. Доставив шкуры кожевнику Ахану в Громовой Утес, путешественники летят на виверне обратно на Перекресток с готовыми кожаными изделиями для торговца Джахана Соколиного Крыла.",h="«Возвращение к Джахану» — заключительная часть знакомства с сетью перелетов Орды на ветрокрылах между...",kw={"ahanu","barrens","crossroads","devrak","jahan hawkwing","tal","thunder bluff","wind rider","ахану","степи","перекресток","деврак","джахан соколиное крыло","тал","громовой утес","ветрокрыл"},ang={["faction:Horde"]="Маршруты ветрокрылов между Мулгором, Дуротаром и Степями — жизненно важные артерии, скрепляющие земли Орды в центральном Калимдоре.",["race:Tauren"]="Торговые цепочки между кожевниками Мулгора и поселениями Степей показывают, как объединенные племена поддерживают расширение границ Орды."},sec={{t="Крылья над Калимдором",b="Для многих путешественников это поручение — первый полет на обученном ветрокрыле. Тал, укротитель ветрокрылов на центральном плато Громового Утеса, организует перелеты над равнинами центрального Калимдора. Если путешественник уже наладил связь с насестом в другом поселении, например в лагере Деврака на Перекрестке, эти крылатые звери без труда преодолевают расстояния, на которые иначе потребовался бы опасный переход по суше через Красные скалы и север Степей."},{t="Торговля Перекрестка",b="Курьерский рейс служит не только обучению полетам, но и экономике. Джахан Соколиное Крыло работает в шумном поселении Перекресток, где ежедневно собираются охотники, разведчики и наемники. Сырые шкуры, отправленные Ахану на высокие уступы Громового Утеса, превращают в прочные доспехи и снаряжение, а затем доставляют по воздуху обратно на пыльный перекресток Степей для снабжения растущих пограничных предприятий Орды."}},faq={{q="Кто такой Джахан Соколиное Крыло?",a="Джахан Соколиное Крыло — торговец-таурен на Перекрестке в Степях. Он покупает и продает кожаные изделия, полагаясь на мастеров Громового Утеса, которые превращают сырые шкуры зверей в ценное снаряжение для странствующих искателей приключений.",al={"jahan","jahan hawkwing lore","who is jahan","джахан","джахан соколиное крыло предания","кто такой джахан"}},{q="Почему мне нужно лететь обратно на Перекресток на ветрокрыле?",a="Путешествие показывает, как работает сеть перелетов. Укротители ветрокрылов, такие как Тал в Громовом Утесе, могут отправлять курьеров и пассажиров лишь в те поселения, которые они сами разведали или с которыми связаны, например в насест Деврака на Перекрестке.",al={"why fly back","wind rider return","how do flight paths work","почему лететь обратно","возвращение на ветрокрыле","как работают маршруты полета"}},{q="Кто такой Ахану?",a="Ахану — искусный кожевник и скорняк с высоких утесов Громового Утеса. Он берет сырые шкуры, присланные охотниками из Степей, делает из них готовые изделия и возвращает их на продажу.",al={"ahanu","ahanu thunder bluff","who crafted the goods","ахану","ахану громовой утес","кто сделал товары"}},{q="Кто такой Деврак?",a="Деврак — орк, укротитель ветрокрылов на Перекрестке. Он управляет насестом, который связывает Степи с крупными оплотами Орды, такими как Оргриммар и Громовой Утес.",al={"devrak","crossroads flight master","wind rider master devrak","деврак","укротитель ветрокрылов перекрестка","укротитель ветрокрылов деврак"}},{q="Можно ли воспользоваться ветрокрылом, не поговорив сначала с укротителем в пункте назначения?",a="Нет. Ветрокрылов можно отправить только в те поселения, где путешественник уже встречался с местным укротителем ветрокрылов и зарегистрировался у него, установив связь между насестами.",al={"flight path rules","unlock flight master","can I fly anywhere","правила полетов","открыть укротителя ветрокрылов","можно ли лететь куда угодно"}},{q="Что будет после возвращения кожаных изделий Джахану?",a="Доставка готовых товаров завершает курьерскую цепочку между Мулгором и Степями: путешественники осваивают воздушные перевозки и могут продолжать помогать гарнизону и торговцам Перекрестка.",al={"quest followup","what next","after return to jahan","продолжение задания","что дальше","после возвращения к джахану"}}},fp="15,313,19.511.0,26.408.0,22.219.0,58.249.0,13.212.0,14.179.0,74.176.0,56.211.0"}
P.entries["quest:6365"] = {n="Мясные продукты в Оргриммар",s="«Мясные продукты в Оргриммар» — короткое вводное задание на доставку, которое дает Заргх на Перекрестке. Он просит юных орков и троллей отнести пакет отборного мяса из Степей укротителю ветрокрылов поселения Девраку, знакомя их с перелетами обратно в столицу Орды.",h="«Мясные продукты в Оргриммар» — короткое вводное задание на доставку, которое дает Заргх на Перекрестке.",kw={"barrens","crossroads","devrak","flight master","gryshka","meat delivery","orgrimmar","wind rider","zargh","степи","перекресток","деврак","укротитель ветрокрылов","гришка","доставка мяса","оргриммар","ветрокрыл","заргх"},ang={["profession:Cooking"]="Доставка свежего мяса со Степей в таверну Гришки в Оргриммаре помогает поддерживать полными сытные котлы столицы для приезжих воинов.",["race:Orc"]="Для молодых орков, покидающих Дуротар ради охоты в Степях, доставка посылки Заргха — быстрый способ наладить воздушный маршрут прямо в столицу Вождя.",["race:Troll"]="Тролли Черного Копья, действующие с Перекрестка, используют это поручение, чтобы связать расширяющиеся дальние поселения с линиями снабжения Оргриммара."},sec={{t="Свежая дичь из Степей",b="Обширные равнины Степей изобилуют дичью: от жевр и долгоножек до кодо и громовых ящеров. Заргх приготовил несколько отборных кусков, которые нужно лично доставить Гришке, хлопотливой хозяйке таверны в Аллее Силы в Оргриммаре. Чтобы мясо осталось свежим и не пришлось долго идти в пыли через Реку Строптивую в Дуротар, Заргх отправляет гонцов прямо с Перекрестка к насесту ветрокрылов."},{t="Крылья над степью",b="Встреча с Девраком — первое официальное знакомство юного воина Орды с сетью перелетов на ветрокрылах. Сотрудничая с укротителями ветрокрылов, Орда напрямую соединяет отдаленные поселения, такие как Перекресток, со своей укрепленной столицей Оргриммар. Деврак готовит курьера и груз к быстрому полету над саванной."}},faq={{q="Кому Заргх отправляет это мясо?",a="Заргх отправляет куски мяса своей подруге Гришке, популярной хозяйке главной таверны в Аллее Силы в Оргриммаре.",al={"who gets the meat","who is the meat for","zargh meat recipient","кому мясо","для кого мясо","получатель мяса заргха"}},{q="Почему это задание могут взять только орки и тролли?",a="Это задание — культурное знакомство с полетами, связывающее орков и троллей Черного Копья с их общей столицей Оргриммар. Таурены направляются в Громовой Утес через задание «Связка шкур», а Отрекшиеся получают задание «Поставка оружия», которое связывает их с Серебряным бором.",al={"why cant tauren get this","undead meats quest","race restriction","почему тауренам нельзя","мясное задание отрекшихся","ограничение по расе"}},{q="Кто такой Деврак?",a="Деврак — орк, укротитель ветрокрылов на Перекрестке в Степях. Он присматривает за вивернами, которые переносят вести, припасы и путешественников по всему Калимдору.",al={"devrak crossroads","who is devrak","деврак перекресток","кто такой деврак"}},{q="Что будет после передачи мяса Девраку?",a="Деврак принимает груз и организует для вас полет на ветрокрыле, чтобы доставить мясо к Небесной башне Оргриммара и передать Гришке в ее таверне — в рамках следующего задания «Дорога до Оргриммара».",al={"next quest after meats to orgrimmar","what does devrak do","следующее задание после мясных продуктов в оргриммар","что делает деврак"}},{q="Где находится Заргх?",a="Заргх находится на Перекрестке — главном торговом центре Орды на главном пересечении дорог Степей.",al={"zargh location","where is zargh","где заргх","местонахождение заргха"}},{q="Зачем лететь на ветрокрыле, а не идти пешком?",a="Ветрокрылы быстро перевозят через суровые просторы Степей и через речной каньон в Дуротар, и хрупкий груз, например свежее мясо, попадает в Оргриммар раньше, чем испортится.",al={"why fly to orgrimmar","wind rider meat","зачем лететь в оргриммар","мясо на ветрокрыле"}}},fp="18,286,27.443.0,22.338.0,34.142.0,45.309.0,14.172.0,45.195.0,23.116.0,40.193.0"}
P.entries["quest:637"] = {n="Письмо Салли Балу",s="Это пропитанное водой письмо, найденное на утонувшем скелете под разрушенными арками Моста Тандола, содержит предсмертные слова дворфа-солдата по имени Салли Балу. Адресованное его жене Саре в Стальгорн, оно хранит последние мысли защитника, погибшего в ледяных водах реки во время битв за мост.",h="Это пропитанное водой письмо, найденное на утонувшем скелете под разрушенными арками Моста Тандола, содержит...",kw={"arathi","dwarf soldier","ironforge","sara balloo","skeleton","sully balloo","thandol span","waterlogged envelope","wetlands","арати","дворф-солдат","стальгорн","сара балу","скелет","салли балу","мост тандола","отсыревший конверт","болотина"},ang={["faction:Alliance"]="Письмо — трогательное напоминание о личной жертве простых солдат передовой, оберегающих хрупкие сухопутные связи между южными и северными землями Альянса.",["race:Dwarf"]="Для дворфов Стальгорна возвращение последних слов Салли — дань брату по оружию, отдавшему жизнь, защищая величественные каменные творения дворфов от северных угроз."},sec={{t="Голос со дна реки",b="Под массивными каменными опорами Моста Тандола — важнейшей сухопутной переправы, соединяющей Болотину с Нагорьем Арати, — лежит утонувший скелет павшего дворфа. В костлявой руке он все еще сжимает отсыревший конверт, который едва выдерживает прикосновения. Письмо, написанное с величайшей тщательностью посреди пожаров сражений, начинается нежными словами: «Моя дорогая Сара...» — голос солдата сохранился спустя долгое время после того, как его поглотили воды."},{t="Цена моста",b="У Моста Тандола шли жестокие бои между силами Альянса и его врагами — от диверсантов из клана Черного Железа до разбойничьих отрядов, оспаривавших пограничные земли. Салли Балу был одним из многих дворфов-солдат, посланных на север защищать этот важный путь. Когда он погиб под водой, его семья в горах не знала о его судьбе, пока водолаз наконец не достал его прощальное завещание."},{t="Вдова в Стальгорне",b="Возвращение найденного письма в Стальгорн приносит тихое горе вдове Салли, Саре Балу. Живя в шумных залах столицы дворфов, она оставалась между скорбью и робкой надеждой, не зная, пропал ли ее муж без вести или потерян навсегда. Увидев его слова, написанные его рукой, и узнав о месте его последнего упокоения под водой, она наконец вынуждена принять горькую правду о его смерти."}},faq={{q="Где найти письмо Салли Балу?",a="Письмо находится в руке затонувшего скелета, лежащего глубоко на дне реки прямо под массивными каменными опорами Моста Тандола, который соединяет Болотину и Нагорье Арати.",al={"letter location","where is sully balloo","thandol span skeleton","где письмо","где салли балу","скелет моста тандола"}},{q="Кто такой Салли Балу?",a="Салли Балу был дворфом-солдатом Альянса, павшим при обороне Моста Тандола. Оказавшись в ловушке под ледяной водой во время сражений у переправы, он успел написать последнее письмо жене Саре, прежде чем умереть.",al={"who is sully","sully balloo lore","who was sully balloo","кто такой салли","салли балу предания","кто был салли балу"}},{q="Кто такая Сара Балу?",a="Сара Балу — вдова Салли, живущая в великой столице дворфов Стальгорне. Она провела месяцы в ожидании вестей о судьбе мужа на северной границе.",al={"where is sara balloo","who is sara","sara balloo location","где сара балу","кто такая сара","местонахождение сары балу"}},{q="Что происходит после доставки письма?",a="Получив мучительное подтверждение смерти Салли, Сара Балу охвачена горем и просит увековечить его память. История продолжается в следующем задании в Стальгорне.",al={"what next","sully quest chain","after delivering letter","что дальше","цепочка заданий салли","после доставки письма"}},{q="Почему письмо сохранилось под водой?",a="Письмо было защищено конвертом, который крепко сжимали останки солдата. Хотя к моменту находки оно частично размокло и отсырело, несколько страниц, написанных аккуратным почерком, остаются вполне разборчивыми.",al={"why is letter readable","how did envelope survive","почему письмо читаемо","как уцелел конверт"}},{q="Какое реальное событие вдохновило это задание?",a="Задание — дань уважения майору Салливану Баллу из 2-го пехотного полка Род-Айленда времен Гражданской войны в США, написавшему знаменитое поэтичное прощальное письмо жене незадолго до гибели в первом сражении при Булл-Ран.",al={"sully balloo trivia","sullivan ballou","civil war reference","салли балу факты","салливан баллу","отсылка к гражданской войне"}}},fp="21,327,25.455.0,21.403.0,20.428.1,37.197.0,21.214.0,19.167.0,42.203.1,43.229.0,49.228.0"}
P.entries["quest:6381"] = {n="Новая жизнь",s="«Новая жизнь» — восстанавливающее задание Орды, которое выдает Таммра Перекати-поле в Приюте у Солнечного Камня. Собрав зачарованные семена, игрок отправляется на запад, в пепельные руины Обугленной долины, чтобы посадить их в плодородную землю. Этот ритуал призван положить начало восстановлению земли среди враждебных элементалей и гарпий.",h="«Новая жизнь» — восстанавливающее задание Орды, которое выдает Таммра Перекати-поле в Приюте у Солнечного...",kw={"bloodfury harpies","charred vale","cycle of rebirth","dirt mounds","fire elementals","gaea seeds","stonetalon mountains","sun rock retreat","tammra windfield","гарпии кровавой ярости","обугленная долина","цикл возрождения","земляные холмики","элементали огня","семена геи","когтистые горы","приют у солнечного камня","таммра перекати-поле"},ang={["class:Druid"]="Друиды близки к миссии Таммры и видят в возрождении Обугленной долины необходимое восстановление хрупкого равновесия природы.",["class:Shaman"]="Шаманы понимают, что встревоженные элементали огня, бродящие по долине, не обретут покоя, пока сама израненная земля не начнет исцеляться.",["profession:Herbalism"]="Травники ценят великую силу стойких семян, способных породить цветущую растительность из совершенно мертвой почвы.",["race:Tauren"]="Для тауренов посев зачарованных семян в израненную землю — акт духовного единения с Матерью-Землей, исполнение священного долга исцелять раненые земли."},sec={{t="Исцеление выжженной земли",b="Обугленная долина — печальное свидетельство недавнего разорения: она задыхается от сажи, яростных элементалей огня и гарпий-падальщиц. Таммра Перекати-поле не желает, чтобы край сдался разрухе. Полагаясь на древнюю стойкость Матери-Земли, она отправляет путников в самое сердце почерневшей долины на поиски земляных холмиков Геи — участков плодородной почвы, уцелевших в пожаре."},{t="Опора для будущего",b="Зачарованные семена Геи, посаженные в выжженную почву, выведены так, чтобы противостоять остаточной стихийной порче. Укореняясь, они начинают создавать важную экологическую опору, способную противостоять распаду и вернуть в долину растения. Таммра представляет себе долгий процесс исцеления: по мере того как живые корни медленно отвоевывают котловину, встревоженные духи огня успокоятся, гарпии лишатся своего унылого гнезда, а хищные лесозаготовки Торговой Компании в конце концов будут изгнаны."}},faq={{q="Для чего сажать семена Геи?",a="Зачарованные семена Геи предназначены, чтобы прорасти в израненной земле Обугленной долины. Они противостоят порче и создают первую опору для живых растений, закладывая основу для постепенного возрождения и исцеления леса.",al={"why plant seeds","new life purpose","what do gaea seeds do","зачем сажать семена","цель новой жизни","что делают семена геи"}},{q="Куда нужно идти, чтобы посадить семена?",a="Вы должны отправиться на запад от Приюта у Солнечного Камня в Обугленную долину. Семена сажают в небольшие земляные холмики Геи, разбросанные по почерневшей котловине.",al={"where is charred vale","where do i plant gaea seeds","seed locations","где обугленная долина","где сажать семена геи","места посадки семян"}},{q="Кто такая Таммра Перекати-поле?",a="Таммра Перекати-поле — таурен-натуралист, живущая в Приюте у Солнечного Камня в Когтистых горах. Она посвятила себя утешению раненых духов земли и восстановлению областей, опустошенных яростью стихий и жадностью промышленников.",al={"who gives new life","tammra quest giver","tammra windfield lore","кто выдает новую жизнь","таммра выдает задание","таммра перекати-поле предания"}},{q="Какие опасности встречаются в Обугленной долине при посадке?",a="В Обугленной долине обитают взбесившиеся элементали огня, потревоженные недавним разорением, а также агрессивные гарпии из племени Кровавой Ярости, гнездящиеся среди обгоревших деревьев.",al={"charred vale enemies","what attacks in charred vale","dangers in charred vale","враги обугленной долины","кто нападает в обугленной долине","опасности обугленной долины"}},{q="Какое задание предшествует «Новой жизни»?",a="«Новая жизнь» идет сразу после задания «Цикл возрождения», в котором вы помогаете Таммре собрать важные материалы для подготовки зачарованных семян Геи.",al={"new life prerequisite","cycle of rebirth quest","what leads to new life","предыдущее задание новой жизни","задание цикл возрождения","что ведет к новой жизни"}},{q="На что Таммра надеется в отношении Когтистых гор в долгосрочной перспективе?",a="Таммра надеется, что возрождающаяся земля со временем усмирит разъяренных элементалей огня, вытеснит хищных гарпий и переживет лесозаготовки Торговой Компании, вернув горам облик пышного и мирного леса.",al={"future of stonetalon","tammra goal","what happens to charred vale","будущее когтистых гор","цель таммры","что будет с обугленной долиной"}}},fp="8,321,26.399.0,25.486.0,47.240.0,41.153.0,24.235.0,50.166.0,33.152.0,58.228.0"}
P.entries["quest:6382"] = {n="Большая охота",s="«Большая охота» — поручение, направляющее опытных авантюристов Орды из засушливых Степей на север, в густые чащи Ясеневого леса. По поручению Джорна Заклинателя Небес из Лагеря Таурахо путников отправляют на Заставу Расщепленного Дерева помогать Сенани Громовое Сердце и испытать свое умение выслеживать в диком, спорном краю.",h="«Большая охота» — поручение, направляющее опытных авантюристов Орды из засушливых Степей на север, в густые...",kw={"ashenvale","ashenvale hunt","barrens","camp taurajo","jorn skyseer","senani thunderheart","splintertree post","ясеневый лес","большая охота","степи","лагерь таурахо","джорн заклинатель небес","сенани громовое сердце","застава расщепленного дерева"},ang={["class:Hunter"]="Переход с равнин Калимдора в Ясеневый лес — огромная перемена местности: под густым пологом можно выслеживать, изучать и приручать экзотических зверей.",["faction:Horde"]="Ясеневый лес — важнейший стратегический рубеж: закрепившись здесь, Орда получает необходимые запасы древесины и продовольствия для поселений Дуротара и Степей.",["race:Tauren"]="Джорн Заклинатель Небес и Сенани Громовое Сердце вместе направляют это путешествие, считая охоту не просто убийством, а духовным равновесием и способом почтить дикую природу."},sec={{t="Под древним пологом леса",b="Доказав свое охотничье мастерство на выжженных солнцем равнинах Степей, охотники и воины Орды направляются на совсем иное поле испытаний. Джорн Заклинатель Небес замечает, когда путник перерос местную дичь, и указывает ему путь на север, в Ясеневый лес. Для молодой Орды эти древние леса — и источник богатств, и важный политический и духовный рубеж, который она должна понять и занять."},{t="Застава Расщепленного Дерева",b="Петляющая дорога на север мимо Заставы Мор'шан приводит путников к Заставе Расщепленного Дерева — укрепленному лагерю Орды в глубине леса. Там охотница-таурен Сенани Громовое Сердце встречает опытных пришельцев, ищущих более серьезных испытаний на выживание. Чтобы преуспеть в Ясеневом лесу, Орде нужны умелые следопыты, способные противостоять не только свирепым местным хищникам, но и враждебным взглядам защитников леса."}},faq={{q="Кто отправляет меня на «Большую охоту»?",a="Джорн Заклинатель Небес, охотник-таурен из Лагеря Таурахо на юге Степей, дает это поручение, когда вы докажете свое умение в охоте на местных зверей.",al={"who gives the ashenvale hunt","quest giver ashenvale hunt","jorn skyseer quest","кто выдает большую охоту","персонаж большой охоты","задание джорна заклинателя небес"}},{q="Где находится Застава Расщепленного Дерева?",a="Застава Расщепленного Дерева находится в центральной восточной части Ясеневого леса. Если идти по главной дороге на север от Степей мимо Заставы Мор'шан и дальше через лес, укрепленный форпост будет стоять на северной стороне дороги.",al={"splintertree post location","where is senani thunderheart","find splintertree post","где застава расщепленного дерева","где сенани громовое сердце","найти заставу расщепленного дерева"}},{q="Кто такая Сенани Громовое Сердце?",a="Сенани Громовое Сердце — охотница-таурен, живущая на Заставе Расщепленного Дерева. Она координирует охоту по всему Ясеневому лесу и учит прибывающих авантюристов Орды выслеживать самых свирепых хищников и духов древнего леса.",al={"senani thunderheart","who is senani","huntress senani","сенани громовое сердце","кто такая сенани","охотница сенани"}},{q="Какие еще форпосты Орды есть поблизости в Ясеневом лесу?",a="Помимо Заставы Расщепленного Дерева, Орда держит Лесозаготовки Песни Войны на востоке и Форт Зорам'гар на дальнем западном побережье у Зорамского взморья.",al={"horde bases ashenvale","other camps ashenvale","базы орды в ясеневом лесу","другие лагеря ясеневого леса"}},{q="Почему Орду интересует охота в Ясеневом лесу?",a="Дикая природа дает мясо, шкуры и ресурсы, которых не хватает засушливым землям Дуротара и Степей. Встреча с опасными зверями леса также считается важным испытанием воли и духовной силы для воинов и охотников Орды.",al={"why hunt ashenvale","horde ashenvale motivation","зачем охота в ясеневом лесу","мотивы орды в ясеневом лесу"}},{q="Какие испытания ждут после этого путешествия?",a="Сенани Громовое Сердце поручает опытным охотникам выследить заметные лесные угрозы, отправляя их под полог леса охотиться на верховных хищников: огромного медведя Урсангуса, кошку Тенумбру и гиппогрифа Острого Когтя.",al={"next quest after ashenvale hunt","what does senani give you","следующее задание после большой охоты","что дает сенани"}}},fp="18,317,23.443.0,17.452.0,35.159.0,35.225.0,27.226.0,50.149.0,52.252.0,36.227.0"}
P.entries["quest:6383"] = {n="Большая охота",s="Большая охота — традиционный обряд, который проводит Сенани Громовое Сердце на Заставе Расщепленного Дерева. Охотникам Орды предстоит выследить и одолеть трех легендарных лесных хищников, обитающих в древнем лесу: медведя Урсангуса, ночную саблезубую кошку Тенумбру и свирепого гиппогрифа Острого Когтя. Обряд задуман не только как испытание оружием, но и как путь к постижению хитрости, уважения и самопознания.",h="Большая охота — традиционный обряд, который проводит Сенани Громовое Сердце на Заставе Расщепленного Дерева.",kw={"ashenvale hunt","raynewood retreat","senani thunderheart","shadumbra","sharptalon","splintertree post","talondeep path","ursangous","большая охота","приют в ночных лесах","сенани громовое сердце","тенумбра","острый коготь","застава расщепленного дерева","туннель когтя","урсангус"},ang={["class:Hunter"]="Охота служит классическим обрядом посвящения: следопыт должен прочесывать обширные участки леса, читать местность и сражаться со зверями, способными легко одолеть неосторожного разведчика.",["faction:Horde"]="В противовес разрушительным вырубкам леса Песнью Войны охота предлагает Орде путь воинской чести и духовного единения в спорном Ясеневом лесу.",["race:Tauren"]="Для охотников-таурен выслеживание Урсангуса, Тенумбры и Острого Когтя отражает традиционное почтение к творению Матери-Земли: уважение к свирепости природы сочетается с честью выслеживания."},sec={{t="Традиция таурен в древнем лесу",b="Пока Орда закрепляется в глубине Ясеневого леса, духовные учения Матери-Земли находят выражение в лице Сенани Громового Сердца. В отличие от агрессивной заготовки древесины орками, охота Сенани рассматривает затененные леса как священное место испытаний. Состязаясь в смекалке с главными хищниками леса, охотник должен соприкоснуться с первозданной глушью и обрести тихое смирение, которого требует выживание в Ясеневом лесу."},{t="Три великих зверя",b="Охота строится вокруг трех легенд-одиночек, бродящих среди ветвей. Возле Туннеля Когтя обитает Урсангус, огромный старый медведь, чья сила проверяет физическую стойкость. Дальше на восток, у границ Приюта в Ночных Лесах и неуловимых Смеющихся сестер, крадется Тенумбра, скрытная ночная саблезубая кошка, почитаемая за хитрость. Наконец, к югу от Заставы Расщепленного Дерева кружит Острый Коготь, злобный гиппогриф, чье владение лесным пологом завершает испытание."}},faq={{q="Кто начинает Большую охоту?",a="Охотой руководит Сенани Громовое Сердце, охотница-таурен, расположившаяся в Ясеневом лесу. Она бросает вызов путникам из Орды, желающим доказать свое умение выживать в дикой природе.",al={"quest giver ashenvale hunt","who gives the hunt","senani thunderheart quest","персонаж, выдающий задания большая охота","кто дает охоту","задание сенани громовое сердце"}},{q="Каких зверей нужно выследить?",a="Вы должны выследить и убить трех легендарных хищников: большого медведя Урсангуса, ночную саблезубую кошку Тенумбру и свирепого гиппогрифа Острого Когтя.",al={"what animals to kill","three beasts","ashenvale hunt targets","каких зверей убить","три зверя","цели большой охоты"}},{q="Где можно найти Урсангуса?",a="Урсангус бродит на небольшом участке чуть западнее Туннеля Когтя среди других диких медведей леса.",al={"ursangous location","where is the bear","find ursangous","где урсангус","где медведь","найти урсангуса"}},{q="Где крадется Тенумбра?",a="Тенумбра рыщет в районе к югу от Приюта в Ночных Лесах, охотясь у дороги, где обитают дриады, известные как Смеющиеся сестры.",al={"shadumbra location","where is shadumbra","nightsaber location","где тенумбра","где найти тенумбру","ночная саблезубая кошка"}},{q="Где можно выследить Острого Когтя?",a="Острый Коготь патрулирует обширную территорию к югу от Заставы Расщепленного Дерева, пролетая над деревьями и полянами.",al={"sharptalon location","where is sharptalon","hippogryph location","где острый коготь","найти острого когтя","где гиппогриф"}},{q="Зачем Сенани Громовое Сердце посылает охотников за этими зверями?",a="Сенани задумала охоту как почетное испытание, а не бессмысленную бойню. Испытывая мужество в схватке с опаснейшими обитателями леса, охотники должны постичь дикую природу и осознать собственную внутреннюю силу.",al={"why do the hunt","purpose of the hunt","hunt lore","зачем охота","смысл охоты","предания охоты"}}},fp="18,403,39.442.0,22.458.0,30.191.0,36.144.0,29.119.0,28.127.0,32.115.0,61.244.0"}
P.entries["quest:6384"] = {n="Дорога до Оргриммара",s="Это поручение знакомит искателей приключений из Орды с воздушными перелетами по Калимдору: нужно доехать на ветрокрыле с Перекрестка до Оргриммара. Получив свежие куски мяса от Заргха, путники приземляются у Небесной башни столицы и доставляют посылку прямо Хозяйке таверны Гришке.",h="Это поручение знакомит искателей приключений из Орды с воздушными перелетами по Калимдору: нужно доехать на...",kw={"barrens","crossroads","devrak","doras","gryshka","orgrimmar","skytower","wind rider","zargh","степи","перекресток","деврак","дорас","гришка","оргриммар","небесная башня","ветрокрыл","заргх"},ang={["faction:Horde"]="Перелет на ветрокрыле между Перекрестком и Оргриммаром — основа жизненной связи, соединяющей центральные Степи с оплотом власти вождя Тралла.",["profession:Cooking"]="Получив подарок Заргха, Гришка ясно дает понять свои кулинарные предпочтения: лучшую дичь Калимдора следует подавать с кровью, чтобы сохранить вкус."},sec={{t="Крылья над саванной",b="Пересекать засушливые просторы между Перекрестком и красными утесами Дуротара пешком изнурительно, но Орда держит надежную сеть обученных ветрокрылов, чтобы преодолевать это расстояние. Деврак, укротитель ветрокрылов на Перекрестке, ведает этими вивернами и отправляет посыльных и путников высоко над пыльными тропами каньона, доставляя важные донесения и товары прямо в столицу."},{t="Особая доставка для Гришки",b="Перелет — не просто прогулка: в нем есть личное участие. Заргх с Перекрестка приготовил сверток отборного сырого мяса для Хозяйки таверны Гришки в Аллее Силы в Оргриммаре. Когда ветрокрыл садится на центральную Небесную башню Оргриммара, до таверны Гришки рукой подать; там она охотно принимает подарок, с нежностью замечая, что Заргх определенно знает путь к сердцу дамы."}},faq={{q="Для чего нужен этот перелет?",a="The journey serves as a practical introduction to the Horde's wind rider travel network. You are paying Devrak for passage from the Crossroads to Orgrimmar to deliver Zargh's fresh cuts of meat to Innkeeper Gryshka.",al={"why fly to orgrimmar","flight to orgrimmar purpose","why meat to orgrimmar","зачем лететь в оргриммар","цель полета в оргриммар","зачем мясо в оргриммар"}},{q="Где ветрокрыл приземляется в Оргриммаре?",a="Ветрокрыл приземляется у Небесной башни Оргриммара, возвышающейся над Аллеей Силы. С площадки башни можно спуститься по пандусам к главной площади, ближайшим торговцам и таверне Гришки.",al={"where do i land in org","skytower location","orgrimmar flight landing","где приземлиться в оргриммаре","где небесная башня","посадка в оргриммаре"}},{q="Кто такая Гришка?",a="Хозяйка таверны Гришка управляет оживленной таверной в Аллее Силы в Оргриммаре. Она принимает усталых путников в столице и дружит с Заргхом, который регулярно снабжает ее отборным сырым мясом для кухни.",al={"innkeeper gryshka","who is gryshka","gryshka location","хозяйка таверны гришка","кто такая гришка","где гришка"}},{q="Кто такой Деврак?",a="Деврак — укротитель ветрокрылов на Перекрестке в Степях. Он ухаживает за вивернами и управляет воздушным сообщением, связывающим поселение в Степях с Дуротаром и другими поселениями Орды.",al={"devrak crossroads","who is devrak","crossroads wind rider master","деврак перекресток","кто такой деврак","укротитель ветрокрылов на перекрестке"}},{q="Почему Заргх посылает Гришке сырое мясо?",a="Заргх считает свежую дичь Степей ценным даром. Гришка очень рада подарку и замечает, что отборное мясо с кровью — верный путь к ее сердцу.",al={"zargh meats","why send meat to gryshka","zargh and gryshka","мясо заргха","зачем мясо гришке","заргх и гришка"}},{q="Что делать после доставки мяса?",a="После доставки в таверне Гришка отправляет путников обратно к Небесной башне, чтобы поговорить с Дорасом, укротителем ветрокрылов Оргриммара, и подготовиться к обратному пути.",al={"what next after ride to orgrimmar","next quest after gryshka","where to go after delivery","что дальше после дороги до оргриммара","следующее задание после гришки","куда идти после доставки"}}},fp="17,275,22.394.0,28.423.0,35.215.0,44.198.0,15.239.0,14.197.0,41.165.0,43.180.0"}
P.entries["quest:6385"] = {n="Укротитель ветрокрылов Дорас",s="Хозяйка таверны Гришка из Оргриммара написала благодарственное письмо Заргху на Перекрестке, и ей нужен курьер, чтобы доставить его в Степи. Чтобы договориться о перелете, она отправляет путников на башню города к Дорасу, главному укротителю ветрокрылов Орды.",h="Хозяйка таверны Гришка из Оргриммара написала благодарственное письмо Заргху на Перекрестке, и ей нужен...",kw={"barrens","crossroads","doras","flight master","gryshka","orgrimmar","wind rider","wyvern","zargh","степи","перекресток","дорас","укротитель ветрокрылов","гришка","оргриммар","ветрокрыл","виверна","заргх"},ang={["faction:Horde"]="Сеть ветрокрылов соединяет Оргриммар с ключевыми региональными гарнизонами и служит связующей жилой, позволяющей молодой Орде проецировать силу и перевозить припасы по глуши Калимдора.",["race:Orc"]="С момента прибытия на континент орки наладили прочную связь с местными вивернами Калимдора, полагаясь на их ловкость и силу как летающих скакунов и вьючных курьеров."},sec={{t="Ответ курьера",b="Получив свежую крупную партию мяса, доставленную с охотничьих угодий Степей, Хозяйка таверны Гришка пишет мяснику Заргху официальное благодарственное письмо. Не имея времени пройти сухопутный путь через Дуротар самой, она полагается на сеть воздушных курьеров между крупными поселениями Орды в Калимдоре, чтобы быстрее отправить весть через границу."},{t="Хозяин насеста",b="Дорас ведает насестом ветрокрылов Оргриммара на вершине башни в Аллее Силы. Его обученные виверны — основа военной связи и снабжения Орды: они преодолевают опасный путь между столицей и дальними заставами вроде Перекрестка за долю времени, нужного пешему или кодо-повозке."}},faq={{q="Кто такой Дорас?",a="Дорас — главный укротитель ветрокрылов в Оргриммаре. Он ведает стаей обученных виверн города и управляет воздушным сообщением с дальними центрами Орды по всему центральному Калимдору.",al={"doras","who is doras","orgrimmar flight master","дорас","кто такой дорас","укротитель ветрокрылов оргриммара"}},{q="Почему Хозяйка таверны Гришка отправляет это письмо?",a="Гришка отправляет Заргху, мяснику с Перекрестка, письменную благодарность за благополучно доставленные в ее таверну в Оргриммаре запасы мяса.",al={"why send letter","gryshka letter","what is the letter for","зачем письмо","письмо гришки","для чего письмо"}},{q="Где можно найти Дораса?",a="Дорас находится на вершине центральной башни над Аллеей Силы в Оргриммаре; подняться можно по деревянным пандусам внутри башни.",al={"where is doras","doras location","find doras","где дорас","местонахождение дораса","найти дораса"}},{q="Что произойдет после передачи письма Гришки Дорасу?",a="Когда вы поговорите с Дорасом, он подготовит ветрокрыла, чтобы доставить вас обратно в Степи, и вы сможете лично передать письмо Гришки Заргху на Перекрестке.",al={"what next","after doras","next quest","что дальше","после дораса","следующее задание"}},{q="Кто такой Заргх?",a="Заргх — орк-мясник с Перекрестка в Степях и друг Гришки, приславший ей в подарок отборные куски мяса из Степей.",al={"zargh","who is zargh","заргх","кто такой заргх"}},{q="Почему используют ветрокрылов, а не ходят пешком?",a="Сухопутный путь из Оргриммара через Дуротар и реку Строптивую в Степи медленный и полон опасностей. Прирученные ветрокрылы дают Орде быстрый и надежный способ отправлять разведчиков, приказы и курьеров между поселениями.",al={"why fly","wind rider purpose","flight path lore","зачем летать","зачем ветрокрылы","предания о перелетах"}}},fp="27,265,17.382.0,23.322.0,13.191.0,45.170.0,25.140.0,52.159.0,13.139.0,39.255.0"}
P.entries["quest:6386"] = {n="Возвращение на Перекресток",s="Это поручение завершает курьерскую доставку между Дуротаром и Степями: ответ Гришки возвращается к Заргху на Перекресток. Оно показывает, как ветрокрылы служат жизненно важной воздушной опорой, связывающей поселения Орды по всему Калимдору.",h="Это поручение завершает курьерскую доставку между Дуротаром и Степями: ответ Гришки возвращается к Заргху на...",kw={"barrens","crossroads","devrak","doras","gryshka","letter","orgrimmar","wind rider","wyvern","zargh","степи","перекресток","деврак","дорас","гришка","письмо","оргриммар","ветрокрыл","виверна","заргх"},ang={["faction:Horde"]="Насесты ветрокрылов Оргриммара и Перекрестка образуют экономический и логистический хребет, соединяющий столицу Орды с опасными равнинами Калимдора.",["race:Orc"]="Сытные куски свежей дичи остаются одним из лучших знаков привязанности и уважения, которые орк-охотник может преподнести будущей спутнице."},sec={{t="Возвращение на крыльях",b="Доставив Гришке в Оргриммар посылку отборного мяса, вы получаете ее письменный ответ для Заргха. Дорас, укротитель ветрокрылов, живущий на высоких утесах Оргриммара, предоставляет скакуна обратно в Степи. Поскольку вы уже связались с Девраком на Перекрестке, виверны Дораса знают маршрут, и изнурительный сухопутный переход через реку Строптивую превращается в быструю поездку по небу над пустошью."},{t="Союз, заключенный в Степях",b="Смелое кулинарное ухаживание Заргха удалось. Теплый ответ Гришки подтверждает: ничто так не впечатляет орка, как качественные припасы, и Заргх ликует и даже задумывается о грядущей свадьбе. Помимо романтического успеха, путешествие закрепляет доступ путника к главному транспортному узлу Степей."}},faq={{q="Почему возвращаться нужно на ветрокрыле?",a="Дорас использует эту доставку, чтобы показать сеть перелетов Орды. Раз вы уже побывали у Деврака на Перекрестке, виверны могут лететь напрямую между двумя насестами, экономя время и сохраняя линии снабжения в безопасности.",al={"why fly back","wind rider required","can i walk","зачем лететь обратно","обязателен ветрокрыл","можно пешком"}},{q="Кто такая Гришка?",a="Гришка — хозяйка таверны в Аллее Силы в Оргриммаре. Заргх прислал ей отборное мясо из Степей, надеясь завоевать ее расположение.",al={"gryshka lore","who is gryshka","orgrimmar meat lady","предания о гришке","кто такая гришка","хозяйка таверны оргриммара"}},{q="Чего добивался Заргх, посылая мясо в Оргриммар?",a="Заргх хотел поухаживать за Гришкой. В культуре орков подарок сытной качественной дичи из диких равнин Степей считается великим романтическим жестом.",al={"why did zargh send meat","zargh motivation","zargh letter","зачем заргх послал мясо","мотивы заргха","письмо заргха"}},{q="Где заканчивается это задание?",a="The quest completes at the Crossroads in the Barrens, where you hand Gryshka's Letter back to Zargh near the watchtower and stables.",al={"where to turn in","return location","who gets gryshka letter","где сдать","место возвращения","кому письмо гришки"}},{q="Кто такой Дорас?",a="Дорас — укротитель ветрокрылов на насесте над Аллеей Силы в Оргриммаре, ведающий воздушными скакунами, летающими по всему Калимдору.",al={"doras wind rider","doras location","orgrimmar flight master","дорас ветрокрыл","местонахождение дораса","укротитель ветрокрылов оргриммара"}},{q="Что происходит после этого задания?",a="Эта доставка завершает курьерскую цепочку «Мясные продукты в Оргриммар». Связав Оргриммар и Перекресток, вы полностью готовы исследовать Степи глубже.",al={"chain follow up","next quest after return","meats to orgrimmar continuation","продолжение цепочки","следующее задание после возвращения","мясные продукты в оргриммар продолжение"}}},fp="25,247,15.438.0,27.314.0,44.220.0,15.145.0,51.154.0,26.132.0,13.159.0,30.172.0"}
P.entries["quest:6387"] = {n="Награды ученикам",s="Инструктор по горному делу Брок Камнекоп награждает перспективных юных учеников в Телсамаре почетными кирками. Чтобы организовать доставку инструментов из Стальгорна, он направляет искателей приключений к местному распорядителю полетов на грифонах Торгруму Боррелсону.",h="Инструктор по горному делу Брок Камнекоп награждает перспективных юных учеников в Телсамаре почетными кирками.",kw={"brock stoneseeker","golnir bouldertoe","gryphon","honor students","ironforge","loch modan","mining","thelsamar","thorgrum borrelson","брок камнекоп","голнир твердопал","грифон","награды ученикам","стальгорн","лок модан","горное дело","телсамар","торгрум боррелсон"},ang={["faction:Alliance"]="Это поручение знакомит путников в Лок Модане с жизненно важной сетью распорядителей полетов и воздушных курьеров Альянса.",["profession:Mining"]="Поручение показывает уважение дворфов к горному делу как к дисциплинированному ремеслу, в котором мастерство обращения с камнем и жилами приносит ощутимое признание от наставников.",["race:Dwarf"]="Для дворфов-искателей приключений это задание отражает тесную связь между пограничными поселениями вроде Телсамара и глубокими горными залами столицы."},sec={{t="Заслуженная награда шахтера",b="В дворфийском городке Телсамар горное дело — больше чем ремесло: это основа повседневного выживания и повод для гордости дворфов. Брок Камнекоп наблюдает за десятками новобранцев, проходящих его обучение, и натаскивает их в знании горных пород и технике безопасности в туннелях. Тех учеников, кто выделился среди остальных, по традиции отмечают искусно сделанной почетной киркой. Поскольку местных запасов мало, за такими кирками приходится обращаться через весь Каз Модан в самое сердце Стальгорна."},{t="В небеса",b="Вместо долгого горного пути пешком обратно через Дун Морог Брок полагается на воздушную курьерскую сеть королевства. Торгрум Боррелсон заведует грифоньим насестом рядом с Телсамаром и обеспечивает быструю доставку в столицу. Передав Торгруму заказ Брока, вы начинаете курьерский рейс, который напрямую связывает обучение в отдаленном пограничье с большими кузнями дворфийской столицы."}},faq={{q="Кто такой Брок Камнекоп?",a="Брок Камнекоп — инструктор по горному делу, живущий в Телсамаре. Он обучает новичков основам раскопок и работы с камнем.",al={"brock stoneseeker","who is brock","mining trainer thelsamar","брок камнекоп","кто такой брок","учитель горного дела телсамар"}},{q="Почему Броку нужны кирки из Стальгорна?",a="Брок составляет список лучших учеников-шахтеров, заслуживших почетные кирки. Чтобы выдать эти награды, заказ нужно доставить Голниру Твердопалу, торговцу горными припасами в Стальгорне.",al={"why ironforge","why picks","brock's list","почему стальгорн","почему кирки","список брокка"}},{q="Какую роль в этом задании играет Торгрум Боррелсон?",a="Торгрум Боррелсон — распорядитель полетов на грифонах в Телсамаре. Брок велит курьерам принести ему список заказа, чтобы тот организовал быструю доставку по воздуху обратно в Стальгорн.",al={"thorgrum borrelson","who is thorgrum","gryphon master thelsamar","торгрум боррелсон","кто такой торгрум","распорядитель полетов телсамар"}},{q="Кто получает список в Стальгорне?",a="Список предназначен для Голнира Твердопала в Стальгорне, который готовит церемониальные кирки для отличившихся учеников Брока.",al={"who gets the list","golnir bouldertoe","ironforge contact","кто получает список","голнир твердопал","контакт в стальгорне"}},{q="Куда ведет это поручение дальше?",a="Когда вы поговорите с Торгрумом Боррелсоном, он устроит вам полет на грифоне прямо в Стальгорн, чтобы вы лично передали заказ Голниру Твердопалу.",al={"next step","what follows honor students","after brock's list","следующий шаг","что после наград ученикам","после списка брокка"}},{q="Где происходит это задание?",a="Задание начинается и заканчивается в поселении Телсамар, расположенном среди холмов Лок Модана.",al={"quest location","where is thelsamar","where to start honor students","место задания","где телсамар","где начать награды ученикам"}}},fp="14,251,13.512.0,19.394.0,25.138.0,41.212.0,52.168.0,35.136.0,33.146.0,32.112.0"}
P.entries["quest:6388"] = {n="Грит Турден",s="Это поручение знакомит искателей приключений с грифоньей сетью Стальгорна: нужно доставить связку церемониальных инструментов распорядителю полетов города. Получив от Голнира Твердопала почетные кирки, курьер должен передать их Гриту Турдену, чтобы их отправили обратно в Лок Модан.",h="Это поручение знакомит искателей приключений с грифоньей сетью Стальгорна: нужно доставить связку...",kw={"flight master","golnir bouldertoe","gryth thurden","honorary picks","ironforge","loch modan","thelsamar","thorgrum borrelson","распорядитель полетов","голнир твердопал","грит турден","почетные кирки","стальгорн","лок модан","телсамар","торгрум боррелсон"},ang={["faction:Alliance"]="Грифоньи насесты Стальгорна служат незаменимым транспортным узлом для посланников Альянса, перемещающихся между Дун Морогом, Лок Моданом и остальными королевствами.",["profession:Mining"]="Доставка напрямую помогает ученикам-шахтерам Брока Камнекопа в Лок Модане, отмечая их мастерство почетными кирками, выкованными в столице.",["race:Dwarf"]="Для дворфов опора на грифонов — предмет гордости предков и практическая необходимость, связывающая горные залы через коварные вершины."},sec={{t="Курьер для шахтеров",b="Добравшись из Лок Модана до Великой кузни, курьеры получают от Голнира Твердопала связку почетных кирок для учеников-шахтеров Брока Камнекопа. Чтобы не возвращаться пешком по горным перевалам, Голнир советует воспользоваться дворфийской сетью грифонов и отправляет посыльного через весь город к главному распорядителю Стальгорна."},{t="На крыльях в Телсамар",b="Грит Турден управляет грифоньими насестами в великом горном зале, соединяя Стальгорн с дворфийскими поселениями по всему Каз Модану. Турден соглашается организовать доставку к Торгруму Боррелсону в Телсамар при условии, что искатель приключений уже изучил маршрут и поговорил там с местным распорядителем. Это поручение учит начинающих героев, какую важную роль воздушные курьеры играют в единстве дворфийского королевства."}},faq={{q="Для чего нужны почетные кирки?",a="Почетные кирки — церемониальные инструменты, которые Голнир Твердопал изготовил в Стальгорне для учеников Брока Камнекопа, инструктора по горному делу в Телсамаре.",al={"honorary picks","why honorary picks","picks for brock","почетные кирки","зачем почетные кирки","кирки для брока"}},{q="Кто такой Грит Турден?",a="Грит Турден — главный распорядитель грифонов в Стальгорне. Он управляет маршрутами полетов, которые соединяют дворфийскую столицу с окрестными поселениями по всему Каз Модану и за его пределами.",al={"who is gryth thurden","ironforge gryphon master","gryth thurden lore","кто такой грит турден","распорядитель грифонов стальгорна","грит турден предания"}},{q="Где в Стальгорне находится Грит Турден?",a="Грита Турдена можно найти у летного насеста Великой кузни, рядом с главной центральной улицей и вратами Стальгорна.",al={"gryth thurden location","where to find gryth thurden","ironforge flight master","где грит турден","как найти грита турдена","распорядитель полетов стальгорн"}},{q="Почему сначала нужно поговорить с Торгрумом Боррелсоном?",a="Распорядители грифонов отправляют всадников только по известным маршрутам. Чтобы Грит Турден мог отправить всадника в Телсамар, путник должен сначала связаться с Торгрумом Боррелсоном, распорядителем в Лок Модане.",al={"thorgrum borrelson requirement","why need thelsamar flight path","cant fly to thelsamar","требование торгрум боррелсон","зачем маршрут в телсамар","не могу полететь в телсамар"}},{q="Что происходит после передачи кирок Гриту Турдену?",a="Осмотрев посылку, Грит готовит полет на грифоне, чтобы вы вернулись в Телсамар и передали инструменты прямо Броку Камнекопу.",al={"what next after gryth thurden","next quest after gryth thurden","что дальше после грита турдена","следующее задание после грита турдена"}},{q="Кто посылает вас к Гриту Турдену?",a="Голнир Твердопал, мастеровой, работающий у Великой кузни в Стальгорне, дает вам кирки и направляет вас к Гриту.",al={"who starts gryth thurden","who gives this quest","кто начинает грит турден","кто выдает это задание"}}},fp="13,303,24.384.0,24.418.0,32.164.0,21.185.0,44.120.0,50.216.0,53.149.0,31.126.0"}
P.entries["quest:6391"] = {n="Полет в Стальгорн",s="«Полет в Стальгорн» — вводное курьерское задание, которое отправляет новичков в первый полет на грифоне из Телсамара в Лок Модане в дворфийскую столицу. Получив от Брока Камнекопа список лучших учеников-шахтеров, путник несет донесение прямо Голниру Твердопалу в Великую кузню.",h="«Полет в Стальгорн» — вводное курьерское задание, которое отправляет новичков в первый полет на грифоне из...",kw={"brock's list","deep mountain mining guild","golnir bouldertoe","great forge","gryphon","kharanos","ride to ironforge","thorgrum borrelson","список брокка","гильдия горняков глубинных гор","голнир твердопал","великая кузня","грифон","каражан","полет в стальгорн","торгрум боррелсон"},ang={["faction:Alliance"]="Сеть полетов на грифонах — основа снабжения Альянса по всему Каз Модану, она плавно соединяет передовые гарнизоны с великой столицей.",["profession:Mining"]="Это задание подчеркивает традицию Гильдии горняков Глубинных гор отмечать и награждать гравировкой многообещающих шахтеров из каменоломен Лок Модана.",["race:Dwarf"]="Для юных дворфов Бронзобородов полет на грифоне в Великую кузню — гордый обряд перехода от глухих застав к сердцу королевства."},sec={{t="В небеса",b="Для многих юных горцев и путников полет из Телсамара в Стальгорн становится первым путешествием на грифоне. Под присмотром распорядителя грифонов Торгрума Боррелсона этот короткий перелет проводит путников над заснеженными хребтами Дун Морога прямо ко входу в горную крепость."},{t="Почести Гильдии глубинных гор",b="Поручение связано с Гильдией горняков Глубинных гор. Брок Камнекоп регулярно присылает вести о самых многообещающих учениках из Телсамара. В Великой кузне ждет Голнир Твердопал, который выбивает имена учеников на церемониальных почетных кирках в награду за труд в каменоломнях и шахтах Лок Модана."}},faq={{q="Где начинается и заканчивается этот полет?",a="Путь начинается у распорядителя полетов Торгрума Боррелсона в Телсамаре в Лок Модане и приводит вас прямо к летному насесту у Великой кузни в Стальгорне.",al={"flight path route","where do i fly","ride destination","маршрут полета","куда лететь","пункт назначения"}},{q="Что такое Список Брокка?",a="Список Брокка — перечень, составленный учителем горного дела Броком Камнекопом в Телсамаре. В нем записаны лучшие ученики, чтобы гильдия в Стальгорне могла наградить их за усердие.",al={"brocks list lore","who is brock","what is the paper","список брокка предания","кто такой брок","что за бумага"}},{q="Кто такой Голнир Твердопал?",a="Голнир Твердопал — представитель Гильдии горняков Глубинных гор, работающий в Великой кузне Стальгорна. Он получает списки от местных учителей и выбивает имена учеников на почетных кирках.",al={"golnir role","where is golnir","who is golnir bouldertoe","роль голнира","где голнир","кто такой голнир твердопал"}},{q="Что происходит после передачи списка?",a="Когда Голнир получает список, он направляет вас к Гриту Турдену, главному распорядителю грифонов Стальгорна, чтобы вы лучше узнали воздушную транспортную сеть королевства.",al={"next quest","what to do after","follow up","следующее задание","что делать дальше","продолжение"}},{q="Зачем лететь на грифоне, а не идти пешком?",a="Хотя горная дорога и туннели ведут прямо к вратам Стальгорна, задание служит практическим уроком путешествия на грифонах Альянса и показывает новичкам, как быстро можно перемещаться между поселениями.",al={"why fly","can i walk to ironforge","why gryphon","зачем лететь","можно ли дойти до стальгорна","зачем грифон"}},{q="Что такое почетная кирка?",a="Почетные кирки — церемониальные инструменты, которые изготавливает Гильдия горняков Глубинных гор, чтобы отметить выдающихся учеников, освоивших под руководством местных инструкторов основы раскопок и геологии.",al={"honorary picks","pick reward","mining pick ceremony","почетные кирки","награда кирка","церемония кирки шахтера"}}},fp="17,325,19.309.0,33.326.0,37.169.0,21.177.0,25.207.0,40.175.0,37.214.0,25.193.0"}
P.entries["quest:6392"] = {n="Возвращение к Броку",s="Доставив послание Брока Камнекопа в Стальгорн, вы получаете партию почетных кирок, чтобы отнести их обратно в Телсамар. Воспользовавшись дворфийской воздушной сетью, вы садитесь на грифона к Гриту Турдену и быстро возвращаетесь через горы.",h="Доставив послание Брока Камнекопа в Стальгорн, вы получаете партию почетных кирок, чтобы отнести их обратно в...",kw={"brock stoneseeker","flight master","gryphon","gryth thurden","honorary picks","ironforge","return to brock","thelsamar","брок камнекоп","распорядитель полетов","грифон","грит турден","почетные кирки","стальгорн","возвращение к броку","телсамар"},ang={["profession:Mining"]="Доставка этих почетных кирок дает необходимые инструменты новейшим шахтерам Лок Модана и поддерживает дворфийскую традицию раскопок и разведки недр.",["race:Dwarf"]="Маршрут между Стальгорном и Телсамаром показывает, какую важную роль грифоны Громового Молота и распорядители Стальгорна играют в единстве дворфийских твердынь."},sec={{t="В небеса",b="Великая горная крепость Стальгорн опирается на согласованную сеть грифоньих насестов, поддерживая связь и торговлю с дальними поселениями вроде Лок Модана. Грит Турден, распорядитель грифонов Стальгорна, управляет этим сообщением с центральной площадки полетов города. Поскольку путники должны сначала наладить связь с распорядителем гнезда, прежде чем лететь туда, Грит убеждается, что вы уже говорили с Торгрумом Боррелсоном в Телсамаре, и только потом седлает грифона для обратного пути."},{t="Кирки для учеников",b="Ваше путешествие служит не только знакомству с полетами на грифонах: Брок Камнекоп, уважаемый инструктор по горному делу в Телсамаре, нуждается в новом снаряжении для учеников. Когда почетные кирки благополучно окажутся в его руках, юные шахтеры долины смогут приступить к богатым медным и оловянным жилам в холмах вокруг озера Лок."}},faq={{q="Кто такой Брок Камнекоп?",a="Брок Камнекоп — дворф, учитель горного дела в Телсамаре в Лок Модане. Он учит начинающих шахтеров добывать руду и камень в окрестных холмах.",al={"brock stoneseeker","who is brock","brock in thelsamar","брок камнекоп","кто такой брок","брок в телсамаре"}},{q="Почему для завершения этого задания нужно лететь на грифоне?",a="Задание знакомит путников с системой полетов Альянса. Грит Турден объясняет, что грифоны могут доставить вас только к тем насестам, где вы уже бывали, например к насесту Торгрума Боррелсона в Телсамаре.",al={"why fly","flight path quest","gryphon ride","зачем лететь","задание на полет","полет на грифоне"}},{q="Для чего нужны почетные кирки?",a="Это новые кирки, которые Брок Камнекоп заказал в Стальгорне для своих учеников-новичков, чтобы они работали на богатых рудой утесах Лок Модана.",al={"honorary picks","what are the picks","почетные кирки","зачем кирки"}},{q="Кто такой Грит Турден?",a="Грит Турден — распорядитель грифонов Стальгорна, он находится у Великой кузни. Он управляет исходящими и входящими полетами столицы по всему Каз Модану и за его пределами.",al={"gryth thurden","ironforge flight master","грит турден","распорядитель полетов стальгорна"}},{q="Можно ли вернуться в Телсамар пешком, а не лететь?",a="Хотя урок призван научить вас пользоваться маршрутами полета, Броку Камнекопу важно лишь, чтобы вы благополучно доставили ему почетные кирки в Телсамар, как бы вы туда ни добрались.",al={"can i walk back","do i have to take gryphon","можно ли пешком","обязательно ли лететь на грифоне"}},{q="Где в Телсамаре находится Брок?",a="Брока Камнекопа можно найти на улице рядом с кузней и наковальней в Телсамаре, он готов помочь шахтерам, работающим в Лок Модане.",al={"where is brock","brock stoneseeker location","find brock","где брок","где брок камнекоп","найти брока"}}},fp="15,270,19.498.0,20.361.0,25.171.0,55.216.0,32.159.0,21.167.0,52.195.0,36.124.0"}
P.entries["quest:6395"] = {n="Последнее желание Марлы",s="«Последнее желание Марлы» — одно из первых заданий Отрекшихся, которое выдает Новобранец Элрет в Могильнике. Оно требует выследить порабощенные Плетью останки Самуэля Фиппса, чтобы похоронить его рядом с его убитой женой Марлой. Это задание отражает стремление молодого общества Отрекшихся чтить человеческие узы и отличаться от безмозглой Плети.",h="«Последнее желание Марлы» — одно из первых заданий Отрекшихся, которое выдает Новобранец Элрет в Могильнике.",kw={"deathknell","grave","marla fipps","marla's last wish","novice elreth","remains","samuel fipps","scourge","могильник","могила","марла фиппс","последнее желание марлы","новобранец элрет","останки","самуэль фиппс","плеть"},ang={["class:Priest"]="Настойчивость Новобранца Элрет в вопросе погребальных обрядов напрямую говорит о духовном долге Отрекшихся жрецов, которые борются с мыслями о смерти, горе и осквернении мертвых Лордерона.",["race:Undead"]="Для недавно восставших Отрекшихся исполнение желания Марлы — эмоциональная связь с прежней человеческой жизнью, доказательство того, что сострадание и честь не погибли с падением Лордерона."},sec={{t="Трагическое воссоединение",b="До того как Третья война опустошила Лордерон, Марла и Самуэль Фиппс жили вместе как муж и жена. Когда по их землям прокатилась чума, Самуэль поддался заразе и был воскрешен как безмозглый раб Плети. Марла избежала нежизни, но не смогла уйти от самого Самуэля, который жестоко убил ее в своем бездумном неистовстве. Несмотря на то что она погибла от рук мужа, в последние мгновения Марла не питала ненависти. Ее предсмертным желанием, которое помнит Новобранец Элрет, было вечно покоиться рядом с мужем на кладбище Могильника."},{t="Уважение к мертвым",b="Новобранец Элрет отправляет Отрекшихся авантюристов к северо-востоку от Могильника, чтобы найти Самуэля Фиппса, который все еще бродит среди разоренного лагеря. Положить конец мучениям Самуэля важно вдвойне: так долину очистят от подступающего прислужника Плети, а его останки можно будет перенести к месту упокоения Марлы. Как подчеркивает Элрет, почитание умерших и уважение к их последней воле — важнейшее нравственное отличие недавно освободившихся Отрекшихся от безмозглой злобы Плети."}},faq={{q="Кто такая Марла Фиппс?",a="Марла Фиппс была жительницей Лордерона, пережившей первую волну чумы нежити, но убитой собственным мужем Самуэлем после того, как он превратился в безмозглого вурдалака Плети. Ее предсмертным желанием было упокоиться рядом с ним.",al={"marla fipps lore","who is marla","marla background","марла фиппс предыстория","кто такая марла","история марлы"}},{q="Кто такой Самуэль Фиппс?",a="Самуэль Фиппс был мужем Марлы до чумы. Он поддался Плети, потерял рассудок под властью Короля-лича и убил свою жену. Он бродит по разоренному лагерю к северо-востоку от Могильника, пока его не упокоят Отрекшиеся авантюристы.",al={"samuel fipps lore","who is samuel fipps","where is samuel fipps","самуэль фиппс предыстория","кто такой самуэль фиппс","где самуэль фиппс"}},{q="Почему Новобранцу Элрет важно похоронить их вместе?",a="При жизни Новобранец Элрет был другом Марлы. Помимо личных чувств, Элрет считает, что уважение к воле умерших и достойное обращение с останками доказывают, что Отрекшиеся сохранили человечность и нравственность, и отличают их от безмозглой Плети.",al={"why help marla","novice elreth motive","why bury samuel","почему помочь марле","мотив новобранца элрета","зачем хоронить самуэля"}},{q="Восстала ли Марла Отрекшейся?",a="Нет. По словам Новобранца Элрет, Марла вообще избежала нежизни. Она умерла обычной смертью от рук мужа и была похоронена на кладбище Могильника.",al={"is marla undead","did marla become forsaken","marla fipps undead","марла нежить","стала ли марла отрекшейся","марла фиппс нежить"}},{q="Где находится могила Марлы?",a="Могила Марлы находится в первом ряду кладбища сразу за главной часовней Могильника.",al={"marla's grave location","where is marla buried","where do i bury samuel","могила марлы","где похоронена марла","где хоронить самуэля"}},{q="Где найти Самуэля Фиппса?",a="Самуэль Фиппс бродит вокруг разоренного лагеря у дороги, ведущей из Могильника на северо-восток.",al={"samuel fipps location","find samuel fipps","where is samuel","где самуэль фиппс","найти самуэля фиппса","где самуэль"}}},fp="17,339,16.550.0,19.517.0,20.225.0,20.235.0,56.265.0,27.162.0,31.96.0,32.97.0"}
P.entries["quest:64"] = {n="Забытая вещь",s="Фермер Хмуробров и его жена Верна бежали из дома, когда замаскированные разбойники захватили их тыквенное поле в Западном Крае. В спешке бегства Хмуробров оставил в шкафу в доме дорогую семейную реликвию. Возвращение карманных часов — редкая возможность спасти что-то личное из надвигающегося хаоса, охватившего край.",h="Фермер Хмуробров и его жена Верна бежали из дома, когда замаскированные разбойники захватили их тыквенное...",kw={"benny blaanco","defias","furlbrow","pocket watch","pumpkin patch","verna furlbrow","wardrobe","westfall","вит карлеон","братство справедливости","хмуробров","карманные часы","тыквенное поле","верна хмуробров","шкаф","западный край"},ang={["faction:Alliance"]="Бедственное положение Хмуробровых показывает серьезный упадок гражданского порядка в житнице королевства и вынуждает путников Альянса заниматься тем, чем пренебрегла корона.",["race:Human"]="Для людей Штормграда вид честных фермеров, изгнанных жестокими преступниками в дне пути от столицы, — отрезвляющее напоминание о внутренних бедах королевства."},sec={{t="Ночное выселение",b="Как и многие поселенцы Западного Края, Фермер Хмуробров и его жена Верна были изгнаны с земли грубой силой. Разбуженные внезапными криками и насилием на тыквенных полях, супруги успели лишь собрать немногое, что могли унести, и бежать с фермы. В панике Хмуробров был вынужден оставить карманные часы, подаренные ему отцом Верны в день свадьбы, в шкафу захваченного дома."},{t="Хулиганы на полях",b="Тыквенная ферма Хмуробровых теперь кишит головорезами Братства Справедливости, мародерами и ворами-оппортунистами вроде Вита Карлеона, которые роются в остатках брошенных домов. Для простых людей вернуться за личными ценностями — верная смерть. Достав часы из шкафа среди разграбленных комнат, авантюристы возвращают каплю достоинства семье, которая потеряла почти все остальное в нарастающей волне беззакония."}},faq={{q="Почему карманные часы так важны для Фермера Хмуроброва?",a="Карманные часы — свадебный подарок отца Верны. Для нищих беженцев, лишившихся средств к существованию, эти часы — одна из немногих оставшихся памятных связей с прежней жизнью и семейным наследием.",al={"why watch important","furlbrow watch significance","who gave furlbrow the watch","почему часы важны","значение часов хмуроброва","кто подарил часы хмуроброву"}},{q="Кто прогнал Хмуробровых с их фермы?",a="Разбойники и мародеры из Братства Справедливости захватили ферму ночью. Беззаконие, охватившее Западный Край, вынудило многие семьи фермеров покинуть поля и дома под угрозой насилия.",al={"who attacked the farm","who took furlbrow farm","what happened to the furlbrows","кто напал на ферму","кто захватил ферму хмуробровых","что случилось с хмуробровыми"}},{q="Где спрятаны часы?",a="Часы лежат в шкафу в спальне дома Хмуробровых, расположенного на тыквенных полях к западу от придорожного лагеря Хмуробровых на севере Западного Края. Сейчас дом занимают скваттеры и преступники из Братства Справедливости.",al={"where is the pocket watch","find watch","wardrobe location","где карманные часы","найти часы","где шкаф"}},{q="Кто такой Вит Карлеон?",a="Вит Карлеон — преступник, околачивающийся в доме Хмуробровых вместе со своими товарищами из Братства Справедливости: они грабят брошенное жилище и охраняют захваченную территорию от тех, кто хочет ее вернуть.",al={"benny blaanco lore","who is the guy in the house","вит карлеон предыстория","кто тот парень в доме"}},{q="Где сейчас живут Хмуробровы?",a="Покинув свою землю, Фермер Хмуробров и Верна оказались у дороги в Западном Крае: они ютятся возле своего фургона и пытаются выжить посреди упадка в крае.",al={"where are furlbrows","where is farmer furlbrow","где хмуробровы","где фермер хмуробров"}},{q="Присылает ли Штормград стражу, чтобы помочь вернуть такие фермы?",a="Официальное военное присутствие Штормграда в Западном Крае практически отсутствует из-за политического безразличия и отсутствия руководства в столице. Народному ополчению в Сторожевом холме не хватает людей, чтобы отвоевывать отдельные фермы, и поселенцы остаются совершенно беззащитными.",al={"stormwind help westfall","why no guards at farm","помощь штормграда западному краю","почему нет стражи на ферме"}}},fp="22,354,19.491.0,23.440.0,56.214.0,45.197.0,26.226.0,21.190.0,36.174.0,59.275.0"}
P.entries["quest:6401"] = {n="Кайя жива!",s="«Кайя жива!» — короткое задание Орды в Когтистых горах, завершающее спасение Кайи Плоского Копыта. Проводив юную тауренку мимо враждебных разбойников Племени Зловещего Тотема, вы относите радостную весть о ее спасении ее встревоженной тете, Таммре Перекати-поле, в Приют у Солнечного Камня.",h="«Кайя жива!» — короткое задание Орды в Когтистых горах, завершающее спасение Кайи Плоского Копыта.",kw={"flathoof","grimtotem","kaya","makaba","protect kaya","stonetalon","sun rock retreat","tammra","tauren","windfield","плоское копыто","зловещий тотем","кайя","макаба","защита кайи","когтистые горы","приют у солнечного камня","таммра","таурены","перекати-поле"},ang={["faction:Horde"]="Когтистые горы — спорная глушь, где силы Орды растянуты тонко; доставка вестей о выживших помогает поддерживать единство между разбросанными лагерями.",["race:Tauren"]="Угроза Зловещего Тотема — болезненный внутренний раскол для шу'хало, и потому спасение невинных родных, таких как Кайя, для них особенно лично."},sec={{t="Вздох облегчения",b="Когтистые горы полны опасностей, особенно на спорных тропах, где Племя Зловещего Тотема наносит удар без пощады. Когда их деревню постигло жестокое нападение, юную Кайю Плоское Копыто считали погибшей или плененной отступниками. Ее спасение стало редким мгновением триумфа и облегчения среди продолжающихся племенных конфликтов в ущельях."},{t="Путь в Приют у Солнечного Камня",b="Когда Кайя доставлена в безопасное место, Макаба Плоское Копыто поручает вам отнести весть прямо в Приют у Солнечного Камня. Там тетя Кайи, Таммра Перекати-поле, с тревогой ждет новостей с троп. Весть о спасении Кайи приносит утешение раздробленной семье и подчеркивает важную роль странствующих героев в поддержании связи между отдаленными аванпостами Орды."}},faq={{q="Кто такая Кайя Плоское Копыто?",a="Кайя Плоское Копыто — юная тауренка, разлученная с близкими и оказавшаяся в опасности после жестокого нападения отступников из Зловещего Тотема на ее поселение в Когтистых горах.",al={"who is kaya","kaya flathoof","kaya","кто такая кайя","кайя плоское копыто","кайя"}},{q="Кто такая Таммра Перекати-поле?",a="Таммра Перекати-поле — тетя Кайи, живущая в Приюте у Солнечного Камня в Когтистых горах. Она боялась, что ее племянница погибла при нападении Зловещего Тотема.",al={"tammra windfield","who is tammra","kaya aunt","таммра перекати-поле","кто такая таммра","тетя кайи"}},{q="Кто напал на деревню Кайи?",a="Деревню Кайи атаковал из засады агрессивный клан Зловещего Тотема — изоляционистская фракция тауренов, известная тем, что нападает как на соперничающие племена, так и на странников в горах.",al={"who attacked kaya","village attack","grimtotem attack","кто напал на кайю","нападение на деревню","нападение зловещего тотема"}},{q="Какое задание предшествует этому?",a="Это задание следует сразу за заданием «Защита Кайи» — сопровождением, в котором вы защищаете Кайю Плоское Копыто, пока она бежит от похитителей и возвращается в безопасное место.",al={"prerequisite","protect kaya","escort quest","предыдущее задание","защита кайи","задание сопровождения"}},{q="Где находится Приют у Солнечного Камня?",a="Приют у Солнечного Камня расположен высоко в центральной части Когтистых гор. Добраться до него можно по главной дороге на запад, а затем через узкое горное ущелье в укрытую котловину.",al={"sun rock retreat location","where is sun rock","find sun rock retreat","где приют у солнечного камня","где солнечный камень","найти приют у солнечного камня"}},{q="Почему Макаба Плоское Копыто посылает вас, а не идет сам?",a="Макаба остается в своем лагере у юго-восточного края Когтистых гор и полагается на крепкого посыльного, который быстро успокоит их семью в Приюте у Солнечного Камня.",al={"why makaba stays","why send me","почему макаба остается","почему посылают меня"}}},fp="12,293,18.381.0,25.362.0,21.161.0,24.149.0,28.181.0,29.143.0,34.175.0,59.155.0"}
P.entries["quest:6421"] = {n="Ущелье Камнепадов",s="Глубоко в Ущелье Камнепадов в Когтистых горах местные кобольды принялись лихорадочно добывать редкий подземный минерал — резонит. Чувствуя растущее напряжение в земле, таурен Мор'рогал посылает героев Орды исследовать пещеры ущелья и добыть образцы минерала, чтобы узнать, что скрыто под камнем.",h="Глубоко в Ущелье Камнепадов в Когтистых горах местные кобольды принялись лихорадочно добывать редкий...",kw={"boulderslide ravine","earthen","kobold","mor'rogal","resonite","resonite crystal","stonetalon","sun rock retreat","titan","ущелье камнепадов","земельник","кобольд","мор'рогал","резонит","кристалл резонита","когтистые горы","приют у солнечного камня","титан"},ang={["class:Shaman"]="Шаманы, прислушивающиеся к земле, чувствуют неестественный резонанс, дрожащий в камне, пока кобольды вскрывают реликвии первозданного стихийного мастерства Титанов.",["profession:Mining"]="Резонит, который добывают кобольды Камнепадов, — не обычная руда: его структура пропитана древними арканными остатками, оставленными подземными строителями давних времен.",["race:Tauren"]="Для тауренов, почитающих Мать-Землю, обнаружение древних творений Титанов под горами означает опасное нарушение природного равновесия Когтистых гор."},sec={{t="Напряжение в камне",b="Со своего поста в Приюте у Солнечного Камня таурен Мор'рогал с глубокой тревогой наблюдает за вершинами Когтистых гор. Сама земля словно потревожена: с юго-востока исходит неестественное волнение. Там, среди скал Ущелья Камнепадов, местные кобольды забросили обычный сбор добычи и яростно раскапывают редкий подземный минерал — резонит. Чтобы выяснить, почему эти суеверные паразиты копают с таким отчаянным неистовством, Мор'рогал нанимает разведчиков Орды: им нужно прорваться через защиту кобольдов, спуститься в самые глубины пещеры и принести необработанные образцы минерала."},{t="Пробуждение древних",b="Когда сырой резонит осмотрели, его истинная природа стала ясна: кристаллы гудят древней магией земельников. Кобольды, вслепую копавшие глубокий камень, пробили древний пласт мира и откопали земельника — одно из первозданных каменных существ, созданных Титанами для обустройства подземных основ Калимдора. То, что кобольды считают простым карьером, потревожило реликт первобытной истории, и тауренам приходится вмешаться, пока погребенное не вырвалось на свободу."}},faq={{q="Где находится Ущелье Камнепадов?",a="Ущелье Камнепадов врезается в горы к юго-востоку от Приюта у Солнечного Камня в Когтистых горах. Оно ведет в извилистую систему пещер, захваченную кобольдами Камнепадов.",al={"boulderslide ravine location","where is boulderslide ravine","how to find boulderslide ravine","где ущелье камнепадов","расположение ущелья камнепадов","как найти ущелье камнепадов"}},{q="Кто выдает задание «Ущелье Камнепадов»?",a="Задание выдает таурен Мор'рогал, которого можно найти в Приюте у Солнечного Камня — главном оплоте Орды в Когтистых горах.",al={"who starts boulderslide ravine","quest giver boulderslide ravine","mor'rogal quest","кто дает ущелье камнепадов","персонаж, выдающий задание ущелье камнепадов","задание мор'рогала"}},{q="Что такое кристаллы резонита?",a="Резонит — редкий минерал, встречающийся глубоко в пещерах Ущелья Камнепадов. В нем сохранились следы созданной Титанами магии земельников, что говорит о том, что кристаллы образовались рядом с подземными реликвиями земельников.",al={"what is resonite","resonite lore","resonite crystals","что такое резонит","предания о резоните","кристаллы резонита"}},{q="Почему кобольды так лихорадочно добывают резонит?",a="Кобольды наткнулись на резонит во время раскопок и в своей ненасытной погоне за блестящими рудами забрались глубоко под горы, пока не потревожили древнего земельника, погребенного в камне.",al={"why are kobolds mining","boulderslide kobolds goal","kobold plot stonetalon","зачем кобольды копают","цель кобольдов камнепадов","замысел кобольдов когтистые горы"}},{q="Кто такие земельники согласно преданиям тауренов?",a="Согласно древним преданиям, о которых вспоминает Мор'рогал, земельники — каменные существа, созданные Титанами давным-давно, чтобы высекать и формировать саму твердь мира.",al={"what are earthen","earthen titan connection","who are earthen","кто такие земельники","земельники и титаны","земельники"}},{q="Что происходит после выполнения этого задания?",a="Распознав магию земельников в кристаллах резонита, Мор'рогал готовит зачарованное средство и предлагает следующее задание «Пробуждение земельника», отправляя вас обратно в пещеру, чтобы сразиться с пробудившейся угрозой.",al={"next quest after boulderslide ravine","what follows boulderslide ravine","boulderslide ravine follow up","следующее задание после ущелья камнепадов","что после ущелья камнепадов","продолжение ущелья камнепадов"}}},fp="19,347,20.608.0,22.489.1,37.181.0,40.125.0,27.225.1,51.193.1,44.165.0,41.225.1"}
P.entries["quest:6441"] = {n="Рога сатира",s="«Рога сатира» — наемный контракт, который предлагает странствующий гоблин Пиксель на Заставе Расщепленного Дерева в Ясеневом лесу. Видя выгодную торговую возможность в портовом городе Кабестан, Пиксель нанимает способных героев Орды, чтобы истреблять местные общины сатиров и собирать их ценные рога.",h="«Рога сатира» — наемный контракт, который предлагает странствующий гоблин Пиксель на Заставе Расщепленного...",kw={"ashenvale","night run","pixel","ratchet","satyr horns","satyrnaar","splintertree post","xavian","ясеневый лес","ночная поляна","пиксель","кабестан","рога сатира","сатирнаар","застава расщепленного дерева","ксавиан"},ang={["class:Hunter"]="Выслеживание демонических гуманоидов среди оскверненных лесных руин вроде Сатирнаара и Ночной поляны подвергает опасному испытанию навыки следопыта.",["class:Warlock"]="Сатиры пропитаны могущественной магией скверны, поэтому их останки — ценные диковинки для тех, кто изучает демоническую силу.",["faction:Horde"]="Истребление сатиров в центральной части Ясеневого леса ослабляет опасные демонические общины, угрожающие хрупким линиям снабжения Заставы Расщепленного Дерева."},sec={{t="Выгодная возможность",b="Отдыхая на передовом лагере Орды — Заставе Расщепленного Дерева, оборотистый гоблин-путешественник по имени Пиксель заметил брешь на пограничном рынке. Рога демонических сатиров Ясеневого леса пользуются большим спросом в Кабестане, что в Степях. Не желая рисковать жизнью и здоровьем в прямой схватке с порченными тварями, Пиксель нанимает проходящих мимо героев, чтобы те собрали шестнадцать целых рогов до возвращения на юг."},{t="Логова оскверненных",b="Сатиры Ясеневого леса обитают в разбросанных руинах, оскверненных скверной, по всему древнему лесу — это остатки их предательства во время древнего Раскола. Чтобы выполнить заказ Пиксель, охотников направляют к известным оплотам сатиров, среди которых Ночная поляна, укрепленный лагерь Сатирнаар и сумрачные рощи Ксавиан. Добыча в любом из этих поселений дает ценные демонические трофеи, которые ищут на торговых причалах Кабестана."}},faq={{q="Кто такой Пиксель?",a="Пиксель — предприимчивый гоблин-путешественник, временно остановившийся на Заставе Расщепленного Дерева в Ясеневом лесу перед возвращением на юг, в нейтральный порт Кабестан.",al={"who is quest giver","pixel lore","goblin at splintertree","кто выдает задание","пиксель","гоблин на заставе расщепленного дерева"}},{q="Почему в Кабестане нужны рога сатиров?",a="Пиксель отмечает, что рога сатиров стоят дорого в Кабестане, где торговцы, алхимики и коллекционеры редкостей хорошо платят за сырые демонические реагенты и диковинные материалы, привезенные из северных лесов.",al={"why satyr horns","what are horns used for","ratchet satyr horns","зачем рога сатиров","для чего нужны рога","рога сатира кабестан"}},{q="Где в Ясеневом лесу можно найти рога сатиров?",a="Сатиры обитают в нескольких оскверненных местах Ясеневого леса. Известные поселения — Ночная поляна к северо-западу от Заставы Расщепленного Дерева, Сатирнаар недалеко от главной дороги к Азшаре и Ксавиан на северо-востоке Ясеневого леса.",al={"satyr locations","where to find satyrs","night run xavian satyrnaar","где сатиры","где найти сатиров","ночная поляна ксавиан сатирнаар"}},{q="Кто такие сатиры?",a="Сатиры — древние ночные эльфы, поддавшиеся демонической скверне Пылающего Легиона тысячи лет назад. Превратившись в рогатых тварей с копытами, они служат темным силам и активно оскверняют окружающий лес.",al={"what is a satyr","satyr lore","are satyrs demons","кто такие сатиры","предания о сатирах","сатиры демоны"}},{q="Почему этот контракт выдают на Заставе Расщепленного Дерева?",a="Застава Расщепленного Дерева — главная крепость Орды в центральной части Ясеневого леса. Пиксель использует ее как безопасную стоянку между торговыми путями и нанимает расположенных поблизости воинов Орды, которые и так ведут борьбу с опасностями леса.",al={"splintertree satyr quest","why horde only","задание сатиры застава расщепленного дерева","почему только орда"}},{q="Верен ли Пиксель Орде?",a="Нет. Пиксель — независимый гоблин-торговец, ищущий выгоду. Как и многие гоблины из Кабестана, Пиксель работает с каждым, кто может предоставить ценные товары, не заботясь о политике фракций.",al={"is pixel horde","pixel faction","пиксель из орды","фракция пикселя"}}},fp="11,283,23.425.0,23.430.0,13.161.0,34.200.0,44.204.0,16.231.0,50.226.0,44.206.0"}
P.entries["quest:6442"] = {n="Наги на Зорамском взморье",s="«Наги на Зорамском взморье» — задание Орды, в котором героям нужно истребить агрессивных змееподобных захватчиков на побережье северо-запада Ясеневого леса. Тролль Марукайя, находящаяся в Форте Зорам'гар, стремится удержать спорное побережье, прогнав нагов племени Гневохвостов от затонувших руин древнего Зорама.",h="«Наги на Зорамском взморье» — задание Орды, в котором героям нужно истребить агрессивных змееподобных...",kw={"ashenvale","marukai","naga","wrathtail","wrathtail heads","zoram strand","zoram'gar outpost","ясеневый лес","марукайя","наги","гневохвосты","головы гневохвостов","зорамское взморье","форт зорам'гар"},ang={["faction:Horde"]="Удержание Форта Зорам'гар крайне важно для расширения Орды в Ясеневом лесу, поэтому уничтожение нагов становится вопросом военного выживания.",["race:Orc"]="Прямолинейная стратегия Марукайи — жестко отбросить врага — созвучна прагматичной воинской культуре орков, удерживающих пограничные рубежи."},sec={{t="Шаткий оплот",b="Присутствие Орды на Зорамском взморье непрочно. Окруженный враждебными землями ночных эльфов и ожесточенными лесными стычками в Ясеневом лесу, форт служит жизненно важной связью с морем. Однако внезапное появление агрессивных нагов, выползающих на берег, грозит отрезать Орду от моря и сокрушить малочисленный гарнизон прежде, чем позиция будет полностью укреплена."},{t="Отголоски погибшего Зорама",b="Песчаные отмели взморья скрывают разрушенные остатки Зорама — древнего эльфийского города, поглощенного Великим Расколом тысячи лет назад. Марукайя и защитники форта почти не знают, почему змееподобное племя Гневохвостов выбралось из глубоких пучин именно сейчас, но их внезапный интерес к затонувшим руинам не сулит ничего хорошего всем, кто ходит по суше."},{t="Цена выживания",b="Марукайя смотрит на ситуацию с точки зрения простого выживания: когда обнажены мечи и трезубцы, доводы не имеют значения. Требуя двадцать отрубленных голов захватчиков из племени Гневохвостов, она намерена силой загнать змееподобных чудовищ обратно в пучину и защитить берег для Орды."}},faq={{q="Кто выдает задание «Наги на Зорамском взморье»?",a="Задание предлагает Марукайя, тролль из племени Черного Копья, находящаяся в форте Орды Зорам'гар на Зорамском взморье на северо-западе Ясеневого леса.",al={"quest giver","who starts this","marukai location","персонаж, выдающий задание","кто начинает задание","где марукайя"}},{q="Какова история Зорамского взморья?",a="Взморье — место упокоения древнего погибшего города Зорам. Разрушенный и погрузившийся в Великое море давным-давно, во время Раскола, он теперь лежит в руинах, частично под водой, вдоль побережья Ясеневого леса.",al={"what is zoram","history of zoram","sunken city","что такое зорам","история зорама","затонувший город"}},{q="Почему наги нападают на берег?",a="Гарнизон Орды не знает точного мотива появления племени Гневохвостов — лишь то, что существа хлынули из глубин океана, чтобы завладеть затонувшими руинами и прогнать всех обитателей суши.",al={"why are naga here","wrathtail motive","naga goal","почему здесь наги","мотив гневохвостов","цель нагов"}},{q="С какими противниками нужно сражаться в этом задании?",a="Вам нужно убивать нагов племени Гневохвостов, выползающих на пляжи и в прибой Зорамского взморья, и собрать для Марукайи двадцать их отрубленных голов.",al={"which naga","wrathtail heads","target enemies","какие наги","головы гневохвостов","цели задания"}},{q="Какое задание следует за «Наги на Зорамском взморье»?",a="Марукайя не дает после этого других поручений; она просто благодарит вас и просит прислать больше таких, как вы, чтобы удержать взморье.",al={"next quest","follow up","marukai next","следующее задание","продолжение","что дальше у марукайи"}},{q="Почему Орду заботит этот отдаленный пляж?",a="За Ясеневый лес идет яростная борьба между Ордой и ночными эльфами. Надежный морской плацдарм на Зорамском взморье дает Орде стратегический доступ и линии снабжения вдали от густых внутренних лесов.",al={"why is horde here","zoram'gar outpost purpose","почему здесь орда","зачем форт зорам'гар"}}},fp="24,312,21.388.0,22.371.0,21.317.0,45.144.0,44.218.0,37.204.0,48.166.0,44.124.0,48.217.0"}
P.entries["quest:6461"] = {n="Кровопийцы",s="«Кровопийцы» — охотничий контракт Орды, который выдает Ксен'Зилла в поселении племени Черного Копья Малака'джин. Местные тролли нашли обильную дичь на склонах Когтистых гор, но запах разделанного мяса привлек в их лагеря стаи хищных пауков из Глубокого мха.",h="«Кровопийцы» — охотничий контракт Орды, который выдает Ксен'Зилла в поселении племени Черного Копья...",kw={"blood feeders","cleft","deepmoss creeper","deepmoss venomspitter","malaka'jin","spiders","stonetalon","xen'zilla","кровопийцы","расселина","ползун глубокого мха","ядоплюй глубокого мха","малака'джин","пауки","когтистые горы","ксен'зилла"},ang={["class:Hunter"]="Выслеживать опасных хищников, которые охотятся лучше местных и тревожат дружественные поселения, — привычная работа для опытных следопытов, идущих по скалам.",["faction:Horde"]="Малака'джин обеспечивает Орде путь в Когтистые горы с севера Степей; защита деревни обезопасит весь южный проход.",["race:Troll"]="Охотники Малака'джина — сородичи, стремящиеся создать самодостаточные владения на суровом нагорье Калимдора и не поддаться дикой природе."},sec={{t="Незваные гости к ужину",b="Тролли, основавшие пограничный форпост Малака'джин на юго-востоке Когтистых гор, пришли сюда за хорошей охотой. Скалистые склоны оказались богатыми, но мясо и дичь, которые охотники приносили, вскоре привлекли ночных хищников. Пауки Глубокого мха — агрессивные паукообразные, обитающие в скалах и каньонах на севере, — под покровом темноты стали проникать в лагерь, пытаясь поживиться запасами или сделать добычей самих охотников."},{t="Очистка скал",b="Чтобы обезопасить лагерь и защитить припасы, Ксен'Зилла просит искателей приключений выследить хищников в горных проходах на севере. Больше всего ползунов и ядоплюев Глубокого мха в скалистых ущельях и паутине Расселины. Сокращение их числа отгоняет выводок от границ Малака'джина и позволяет деревне отдыхать, не опасаясь засады из тени."}},faq={{q="Кто выдает задание «Кровопийцы»?",a="Ксен'Зилла, тролль из племени Черного Копья, живущая в деревне Малака'джин на юго-востоке Когтистых гор, поручает это задание странствующим героям Орды.",al={"who gives blood feeders","blood feeders quest giver","xen'zilla quest","кто дает кровопийцы","кровопийцы персонаж, выдающий задание","задание ксен'зилла"}},{q="Почему пауки нападают на Малака'джин?",a="Тролли Малака'джина много охотятся на местную дичь. Запах свежей добычи и вяленого мяса по ночам привлекает пауков Глубокого мха из горных проходов: они крадут припасы и охотятся на жителей.",al={"why spiders attack","spider attacks malakajin","why are spiders invading","почему нападают пауки","нападения пауков малака'джин","почему пауки вторгаются"}},{q="Где обитают пауки Глубокого мха?",a="Ползуны и ядоплюи Глубокого мха бродят по центральным проходам и скалам к северу от Малака'джина, а особенно много их в ущелье, затянутом паутиной, — Расселине.",al={"where are deepmoss spiders","deepmoss creepers location","deepmoss venomspitter location","где пауки глубокого мха","ползуны глубокого мха местонахождение","ядоплюи глубокого мха местонахождение"}},{q="Что такое Малака'джин?",a="Малака'джин — лагерь троллей племени Черного Копья у южного входа в Когтистые горы, недалеко от границы со Степями. Он служит пограничной охотничьей базой и форпостом Орды.",al={"what is malaka'jin","malakajin lore","troll village stonetalon","что такое малака'джин","малака'джин предание","деревня троллей когтистые горы"}},{q="Связана ли с этими пауками более серьезная угроза?",a="Глубоко в Расселине, среди паутины, обитает огромная смертоносная паучья матриарх. Предупреждающий указатель у входа в каньон остерегает путников об опасности и призывает группы одолеть ее.",al={"big spider stonetalon","cleft elite spider","spider matriarch stonetalon","большой паук когтистые горы","элитный паук расселина","паучья матриарх когтистые горы"}},{q="Что происходит после истребления пауков?",a="Истребление ползунов и ядоплюев дает Малака'джину передышку: тролли-охотники могут сберечь запасы мяса и ходить по лагерю ночью, не опасаясь постоянных засад.",al={"blood feeders aftermath","does malakajin become safe","кровопийцы последствия","станет ли малака'джин безопасным"}}},fp="13,286,22.448.0,18.397.0,35.154.0,41.208.0,39.188.0,19.192.0,48.187.0,42.181.0"}
P.entries["quest:6462"] = {n="Оберег троллей",s="«Оберег троллей» — задание Орды, которое выдает тролль из племени Черного Копья Митсува в Форте Зорам'гар в Ясеневом лесу. После того как странствующий отряд троллей был убит в засаде фурболгами Колючего Меха, Митсува просит искателей приключений проникнуть в их логово и вернуть священные талисманы, украденные у мертвых.",h="«Оберег троллей» — задание Орды, которое выдает тролль из племени Черного Копья Митсува в Форте Зорам'гар в...",kw={"ashenvale","darkspear","furbolg","mitsuwa","thistlefur hold","thistlefur village","troll charm","zoram'gar outpost","ясеневый лес","черное копье","фурболг","митсува","крепость колючего меха","деревня колючего меха","оберег троллей","форт зорам'гар"},ang={["faction:Horde"]="Наступление на земли Колючего Меха — это ответный удар по лесным угрозам, устраивающим засады на снабжение Орды и путников в Ясеневом лесу.",["race:Troll"]="Возвращение оберегов — духовный долг троллей Черного Копья: священные предметы предков должны быть спасены из лап диких фурболгов."},sec={{t="Караван в засаде",b="Форт Зорам'гар — отдаленное западное убежище Орды на побережье Ясеневого леса, и путь по лесным тропам там полон опасностей. Отряд троллей Черного Копья, направлявшийся к форту, так и не прибыл: он пал жертвой жестокой засады воинственного племени фурболгов Колючего Меха. Митсува принимает гибель сородичей как будущую встречу в загробном мире, но осквернение и кража их священных оберегов — непереносимое оскорбление."},{t="Священные безделушки",b="В культуре троллей обереги и талисманы тесно связаны с самосознанием, духовной защитой и связью с ловой. Митсува считает тролля без оберега таким же пустым и никчемным, как орка без боевых шрамов. Фурболги Колючего Меха утащили похищенные предметы в Крепость Колючего Меха, глубоко в пещерах за Деревней Колючего Меха, и спрятали их в сундуках вдали от законных владельцев."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Митсува, тролль из племени Черного Копья, находящаяся в Форте Зорам'гар на Зорамском взморье, на северо-западном побережье Ясеневого леса.",al={"quest giver","where is mitsuwa","who starts troll charm","персонаж, выдающий задание","где митсува","кто дает оберег троллей"}},{q="Почему оберегы троллей так важны для Митсувы?",a="Для троллей священные обереги имеют глубокое духовное и культурное значение. Митсува сравнивает тролля без оберега с орком без боевых шрамов и считает обладание этими реликвиями враждебными фурболгами возмутительным осквернением памяти ее убитых сородичей.",al={"charm importance","why troll charms matter","significance of charms","важность оберегов","почему важны обереги троллей","значение оберегов"}},{q="Где находятся обереги троллей?",a="Обереги лежат в сундуках в Крепости Колючего Меха — глубоком пещерном комплексе на северной окраине Деревни Колючего Меха, к северу от поселения ночных эльфов Астранаар.",al={"charm location","where are chests","find charms","где обереги","где сундуки","найти обереги"}},{q="Кто украл обереги?",a="Фурболги Колючего Меха устроили засаду и убили сородичей Митсувы, когда те шли к Форту Зорам'гар, разграбили их вещи и утащили священные обереги в свои пещеры.",al={"who took charms","ambush culprits","кто забрал обереги","виновники засады"}},{q="Что случилось с троллями, которые изначально несли обереги?",a="Их убили на тропе фурболги Колючего Меха. Митсува скорбит о потере, но верит, что однажды воссоединится с ними в загробном мире, и первым делом стремится вернуть их священные реликвии.",al={"caravan fate","slain trolls","mitsuwa kin","судьба каравана","убитые тролли","сородичи митсувы"}},{q="Доступно ли это задание Альянсу?",a="Нет. Задание начинается в Форте Зорам'гар и доступно только игрокам Орды, помогающим племени Черного Копья.",al={"alliance troll charm","can alliance do it","альянс оберег троллей","может ли альянс выполнить"}}},fp="11,292,19.467.0,15.422.0,48.142.0,49.253.0,35.190.0,21.181.0,62.205.0,40.117.0"}
P.entries["quest:647"] = {n="Самогон Маккрила",s="«Самогон Маккрила» — срочное поручение от Туманника Маккрила, дворфа, застрявшего на разрушенной части Моста Тандола. Выпив слишком много собственного крепкого напитка и проспав свой дозор, Туманник поручает путнику из Альянса срочно доставить свежую партию в Хилсбрад, чтобы расплатиться с долгом перед Мастером-пивоваром Бочкопузом в Южнобережье.",h="«Самогон Маккрила» — срочное поручение от Туманника Маккрила, дворфа, застрявшего на разрушенной части Моста...",kw={"bilger","foggy","longbraid","mackreel","menethil","moonshine","southshore","бочкопуз","туманник","длиннокос","маккрил","менетил","самогон","южнобережье"},ang={["faction:Alliance"]="Этот быстрый переход по суше подчеркивает важную связь между Мостом Тандола и принадлежащим Альянсу Южнобережьем в Хилсбраде.",["race:Dwarf"]="Дворфы сразу поймут двойную беду: мучительное похмелье и неоплаченный пивной долг перед собратом."},sec={{t="Похмелье стражника",b="Служба в дозоре на разрушенном Мосту Тандола сырая, холодная и ужасно скучная. Туманник Маккрил спасается от промозглого холода собственным самогоном — настолько крепким, что последствия он сравнивает с целой бригадой осадных машин, катящихся по его черепу. К несчастью для Туманника, лишняя кружка заставила его отключиться на посту. Поскольку дворфами, защищающими Мост, командует Длиннокос Мрачный, Туманнику нельзя допускать новых нарушений дисциплины."},{t="Гонка со временем",b="Беды Туманника усугубляет давний долг Мастеру-пивовару Бочкопузу в Южнобережье. Туманник пообещал Бочкопузу партию своего напитка, чтобы свести счеты, но из-за похмелья и службы он оказался в нескольких минутах от просрочки. Путникам придется, полагаясь на грифонов и быстрые ноги, мчаться через Нагорье Арати в Южнобережье, чтобы доставить кувшин, пока Бочкопуз не решил, что Туманник снова сбежал, не расплатившись."}},faq={{q="Кто такой Туманник Маккрил?",a="Туманник Маккрил — дворф, которого можно найти на разрушенной части Моста Тандола со стороны Нагорья Арати. Он известен тем, что варит исключительно крепкий домашний самогон и во время службы слишком вольно пробует собственный продукт.",al={"foggy mackreel","who is foggy","quest giver mackreel","туманник маккрил","кто такой туманник","маккрил персонаж, выдающий задание"}},{q="Почему эта доставка так срочна?",a="Туманник сильно отстал от графика, напившись и отключившись на посту. У него жесткий срок, чтобы доставить самогон Мастеру-пивовару Бочкопузу и погасить просроченный долг, и на дорогу от Моста Тандола до Южнобережья остается всего около четверти часа.",al={"why is there a timer","why 15 minutes","mackreel moonshine timer","почему есть таймер","почему 15 минут","таймер самогон маккрила"}},{q="Кто такой Мастер-пивовар Бочкопуз?",a="Мастер-пивовар Бочкопуз — опытный дворф-пивовар, который трудится в прибрежном поселении Южнобережье в Предгорьях Хилсбрада. Он ценит крепкий алкоголь и имеет невыполненное деловое соглашение с Туманником Маккрилом.",al={"brewmeister bilger","who is bilger","bilger southshore","мастер-пивовар бочкопуз","кто такой бочкопуз","бочкопуз южнобережье"}},{q="Как успеть доставить самогон в Южнобережье?",a="От Моста до Южнобережья лодки нет. Самый быстрый путь — отправиться в Нагорье Арати и, если вы знаете этот маршрут полета, долететь на грифоне из Опорного пункта до Южнобережья, а затем найти Мастера-пивовара Бочкопуза в городе до истечения таймера.",al={"how to deliver moonshine","fastest way southshore mackreel","moonshine delivery route","как доставить самогон","быстрый путь южнобережье маккрил","маршрут доставки самогона"}},{q="Кто такой Длиннокос?",a="Длиннокос Мрачный — командир дворфов, стоящий лагерем у Дун Модра в Болотине и возглавляющий защитников Моста Тандола. Туманник смертельно боится, что Длиннокос узнает, как он напился до беспамятства, когда должен был стоять в дозоре.",al={"captain longbraid","longbraid menethil","капитан длиннокос","длиннокос менетил"}}},fp="20,347,18.478.0,24.441.0,22.235.0,31.267.0,26.229.0,53.246.0,17.248.0"}
P.entries["quest:6481"] = {n="Пробуждение земельника",s="Глубоко в Ущелье Камнепадов шаман Мор'рогал обнаруживает дремлющего земельника по имени Гоггерок, запечатанного в резонитовой бочке. Опасаясь необузданной разрушительной силы, которую древнее существо из камня может обрушить на Калимдор, он посылает героя разбить бочку и сразить Гоггерока, пока тот не восстановил полную силу.",h="Глубоко в Ущелье Камнепадов шаман Мор'рогал обнаруживает дремлющего земельника по имени Гоггерок...",kw={"boulderslide ravine","earthen","earthen arise","goggeroc","mor'rogal","resonite cask","shaman","stonetalon mountains","ущелье камнепадов","земельник","пробуждение земельника","гоггерок","мор'рогал","резонитовая бочка","шаман","когтистые горы"},ang={["class:Shaman"]="Мор'рогал направляет силу шаманов, чтобы управлять кристаллами резонита и нарушить стихийное равновесие, удерживающее земельника в бочке.",["faction:Horde"]="Уничтожив Гоггерока, герои Орды закрепляют свое присутствие в спорных скалах Когтистых гор и завоевывают неизменное уважение руководства Громового Утеса.",["race:Tauren"]="Когтистые горы — священные охотничьи угодья предков для племен Громового Утеса, и устранение древней разрушительной сущности в их глубинах защищает землю от разорения."},sec={{t="Сон в камне",b="Расследуя нашествие паразитов в Ущелье Камнепадов, разведчики обнаружили среди кобольдов странную реликвию — резонитовую бочку, излучающую нездешнюю силу. Мор'рогал, шаман-таурен из Когтистых гор, понял, чем она является на самом деле: тюрьмой и убежищем для Гоггерока, дремлющего земельника. Эти первозданные создания из камня обладают силой, превосходящей смертных воинов, поэтому свободный Гоггерок стал бы смертельной угрозой для региона."},{t="Кристалл резонита",b="Пробуждение земельника в полной силе стало бы катастрофой для Когтистых гор. Чтобы изменить расклад, Мор'рогал изменил состав принесенных ему кристаллов резонита, наполнив их магией шаманов. Получившийся колдовской кристалл должен разбить резонитовую бочку с такой силой, чтобы Гоггерок пробудился потрясенным и сильно ослабленным. Воинам Орды предстоит разбить сосуд и сразить растерянное создание, рожденное титанами, пока оно не стряхнуло вековое оцепенение."}},faq={{q="Кто такой Мор'рогал?",a="Мор'рогал — шаман-таурен из Когтистых гор. Он изучает происходящие в регионе возмущения и с помощью магии стихий оценивает странные древние артефакты и угрозы, которые откапывают местные паразиты.",al={"mor rogal","who is questgiver","orc shaman morrogal","мор'рогал","кто выдает задание","шаман орк мор'рогал"}},{q="Кто такие земельники?",a="Земельники — древние существа из живого камня, созданные Титанами на заре мира. Обладая глубокой связью с землей и колоссальной физической мощью, они тысячелетиями спали, погребенные по всему Калимдору и Восточным королевствам.",al={"what is earthen","earthen lore","who are earthen","что такое земельник","земельники предание","кто такие земельники"}},{q="Почему Мор'рогал хочет смерти Гоггерока?",a="Мор'рогал опасается, что несравненная сила пробужденного земельника принесет катастрофу Когтистым горам и всему Калимдору. Поскольку такие первозданные существа непредсказуемы и невероятно могущественны, он считает, что уничтожить ослабленного сном Гоггерока — единственный способ защитить землю.",al={"why kill goggeroc","is goggeroc evil","why slay earthen","зачем убивать гоггерока","зол ли гоггерок","зачем убивать земельника"}},{q="Где находится Гоггерок?",a="Гоггерок заточен в резонитовой бочке глубоко в пещерах Ущелья Камнепадов на юго-востоке Когтистых гор, в окружении кобольдов, роющих в этих пещерах.",al={"where is cask","goggeroc location","find resonite cask","где бочка","гоггерок местонахождение","найти резонитовую бочку"}},{q="Как пробудить Гоггерока?",a="Нужно применить Колдовской кристалл резонита, полученный от Мор'рогала, прямо на резонитовую бочку в пещере. Магически измененный кристалл раскалывает сосуд и выталкивает дремлющего земельника наружу.",al={"how to summon goggeroc","use enchanted resonite crystal","open cask","как призвать гоггерока","использовать колдовской кристалл резонита","открыть бочку"}},{q="Что происходит после гибели Гоггерока?",a="Когда вы возвращаетесь к Мор'рогалу с вестью о гибели Гоггерока, шаман избавляется от глубокого страха. Он провозглашает вас героем, чей поступок предотвратил огромную беду, и вы получаете великую честь и уважение среди тауренов Громового Утеса.",al={"quest reward story","morrogal reaction","turn in earthen arise","награда за задание история","реакция мор'рогала","сдать пробуждение земельника"}}},fp="13,335,18.513.0,20.491.1,17.221.0,19.254.0,38.305.0,26.203.0,27.210.0,37.227.1"}
P.entries["quest:6482"] = {n="Свободу Руулу!",s="Глубоко в Крепости Колючего Меха на севере Ясеневого леса в клетке ждет спасения медведь по имени Руул, плененный испорченными фурболгами Колючего Меха. Искатели приключений из Орды могут помочь пленнику пробиться из логова фурболгов на свободу.",h="Глубоко в Крепости Колючего Меха на севере Ясеневого леса в клетке ждет спасения медведь по имени Руул...",kw={"ashenvale","druid escort","furbolg","ruul snowhoof","splintertree post","thistlefur hold","yama snowhoof","ясеневый лес","сопровождение друида","фурболг","руул снежное копыто","застава расщепленного дерева","крепость колючего меха","ями снежное копыто"},ang={["class:Druid"]="Плен Руула — скромное напоминание об опасности скитаний по диким землям в облике зверя, где оскверненные местные жители не отличают друга от добычи.",["faction:Horde"]="Каждая душа, спасенная из оскверненных логовищ севера Ясеневого леса, укрепляет шаткий аванпост Орды — Заставу Расщепленного Дерева.",["race:Tauren"]="Спасение заблудившегося брата по Кругу Кенария и избавление от тревоги его родичей на Заставе Расщепленного Дерева чтят узы Матери-Земли и Орды."},sec={{t="Друид в цепях",b="Странствуя по оскверненным лесам севера Ясеневого леса, друид Руул Снежное Копыто в облике медведя подошел слишком близко к Крепости Колючего Меха. Оскверненные фурболги, лишенные мудрости предков и охваченные диким безумием, приняли обернувшегося таурена за обычного зверя. Вместо почтения они посадили его в клетку и морили голодом, истощив его магические силы, так что он не смог освободиться сам."},{t="Побег из Логова",b="Ослабленный голодом и неволей, Руул не может ни сменить облик, ни пробиться через пещерное поселение фурболгов без помощи. После освобождения союзником Орды он рассчитывает на своего спасителя, который расчистит путь сквозь толпы враждебных воинов Колючего Меха. Благополучно добравшись до окрестностей Заставы Расщепленного Дерева, он ненадолго принимает истинный облик таурена, чтобы сердечно поблагодарить спасителя, а затем возвращается в дикую природу отсыпаться."}},faq={{q="Почему фурболги заперли Руула Снежного Копыта?",a="Руул исследовал леса в облике медведя. Оскверненные фурболги Колючего Меха не узнали в нем друида, приняли его за дикого зверя и заперли в клетке, где морили голодом, пока у него не осталось сил на побег.",al={"why is ruul trapped","how did ruul get captured","why caged","почему руул в плену","как руул попал в плен","почему в клетке"}},{q="Кто такая Ями Снежное Копыто?",a="Ями Снежное Копыто — сестра Руула, служащая на Заставе Расщепленного Дерева в Ясеневом лесу. Она сильно встревожилась, когда Руул несколько дней назад ушел в лес и не вернулся.",al={"ruul sister","yama splintertree","who is yama","сестра руула","ями снежное копыто","кто такая ями"}},{q="Почему Руул не мог просто сменить облик медведя и сбежать?",a="Долгий плен и намеренное голодание у фурболгов Колючего Меха сильно ослабили Руула. Без пищи и сил его запас природной энергии полностью иссяк, и он оставался беспомощным до спасения.",al={"why didnt ruul shapeshift","druid bear trap","почему руул не сменил облик","друид медведь клетка"}},{q="Что происходит после того, как Руул оказывается в безопасности?",a="Когда его выводят из враждебного логова к границам Заставы Расщепленного Дерева, Руул ненадолго принимает свой природный облик таурена, чтобы выразить благодарность, а затем снова обращается медведем и уходит искать тихое место, чтобы поспать и восстановить силы.",al={"where does ruul go","ruul ending","куда идет руул","концовка руула"}},{q="Все ли фурболги Ясеневого леса враждебны, как племя Колючего Меха?",a="Нет. Хотя многие племена фурболгов обладают благородным наследием и тесно связаны с природой, фурболги Колючего Меха на севере Ясеневого леса поддались темному, оскверняющему влиянию, которое сделало их агрессивными и непредсказуемыми.",al={"are furbolgs evil","thistlefur corruption","фурболги злые","порча колючего меха"}},{q="Где происходит спасение?",a="Руул заточен в Крепости Колючего Меха — логове фурболгов в холмах к северо-западу от Заставы Расщепленного Дерева и к северу от Астранаара в Ясеневом лесу.",al={"where is ruul","ruul snowhoof location","где руул","местонахождение руула снежное копыто"}}},fp="15,223,17.433.0,19.421.1,48.238.1,21.176.0,56.235.1,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="Братство Справедливости",s="Это поручение — первый шаг к раскрытию тайного синдиката, терроризирующего Западный Край. По указанию Гриана Камнегрива из Сторожевого холма путники направляются на восток, в Красногорье, к сомнительному знакомому, который может знать, где прячутся воры.",h="Это поручение — первый шаг к раскрытию тайного синдиката, терроризирующего Западный Край.",kw={"defias","gryan stoutmantle","lakeshire","redridge","sentinel hill","westfall","wiley the black","братство справедливости","гриан камнегрив","приозерье","красногорье","сторожевой холм","западный край","вилли черный"},ang={["class:Rogue"]="Камнегрив понимает, что регулярными военными методами преступный синдикат не сокрушить: нужен тот, кто знает тени и уличные услуги, — и это ведет прямо к Вилли Черному.",["faction:Alliance"]="Долгий путь из Западного Края в Красногорье показывает, насколько сильно внешним землям Штормграда приходится полагаться друг на друга, пока столица остается равнодушной."},sec={{t="Угроза в пыли",b="Западный Край пришел в упадок: урожаи отняты, а землю наводнили бандиты в красных банданах. Гриан Камнегрив и Народное ополчение удерживают Сторожевой холм под почти непрерывными налетами, но действуют вслепую. Камнегрив понимает, что, отбиваясь от одиночных грабителей, край не спасти, пока не найдены главари картеля и тот, кто ими командует."},{t="Знакомый за пределами города",b="Вместо официальных военных каналов и штормградских знатных господ, не заботящихся о крае, Камнегрив обращается к личным долгам. Он посылает доверенных приключенцев через Элвиннский лес в Красногорье. В тихом озерном селении Приозерье, на верхнем этаже местной таверны, засел плут по имени Вилли Черный. Он знает преступный мир куда лучше любого капитана ополчения, и Вилли — первая нить к убежищам Братства."}},faq={{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — предводитель Народного ополчения, разношерстных сил обороны, расквартированных в Сторожевом холме в Западном Крае. Поскольку Штормград пренебрегает пограничными землями, он руководит защитой немногих оставшихся местных фермеров и беженцев.",al={"gryan stoutmantle","who gives this quest","quest giver westfall","гриан камнегрив","кто выдает это задание","персонаж, выдающий задания западный край"}},{q="Почему Камнегрив посылает вас в Приозерье?",a="У Народного ополчения нет подпольных осведомителей в самом Западном Крае. Камнегрив призывает старую личную услугу от Вилли Черного, плута, живущего в таверне Приозерья, в надежде, что связи в преступном мире помогут выяснить, кто возглавляет воров.",al={"why lakeshire","why go to redridge","why wiley","почему приозерье","почему идти в красногорье","почему вилли"}},{q="Кто такой Вилли Черный?",a="Вилли Черный — плут, остановившийся на втором этаже Таверны Приозерья в Красногорье. Он должен услугу Гриану Камнегриву, поэтому служит полезным источником слухов преступного мира и связей с преступниками.",al={"who is wiley","wiley lakeshire","wiley the black","кто такой вилли","вилли приозерье","вилли черный"}},{q="Что такое Братство Справедливости?",a="Братство Справедливости — безжалостный преступный картель в красных масках, захвативший фермы, дороги и заброшенные шахты Западного Края, изгоняющий поселенцев и бросающий вызов власти Штормграда.",al={"defias brotherhood","what is defias","red bandana bandits","братство справедливости","что такое дефиасы","бандиты в красных банданах"}},{q="Где найти Вилли в Приозерье?",a="Вилли Черный находится наверху, на втором этаже Таверны Приозерья, которая стоит возле моста в городке Приозерье в Красногорье.",al={"where is wiley","find wiley","wiley location","где вилли","найти вилли","местонахождение вилли"}},{q="Нужно ли в этом задании сражаться?",a="Нет. Этот начальный шаг чисто информационный. Вы просто отправляетесь из Сторожевого холма в Западном Крае через Элвиннский лес к таверне в Приозерье, чтобы встретиться с Вилли.",al={"is this quest hard","combat in defias brotherhood quest","enemies","сложно ли задание","бой в задании братства справедливости","враги"}}},fp="22,253,22.387.0,22.453.0,25.238.0,43.236.0,23.210.0,31.221.0,36.149.0,35.171.0"}
P.entries["quest:6503"] = {n="Вестницы Ясеневого леса",s="«Вестницы Ясеневого леса» — задание Орды по перехвату патрулей, выдаваемое Курай'бином в Ясеневом лесу. Разведчики ночных эльфов рассредоточились от Аванпоста Среброкрылых, собирая сведения о ближайших лагерях Орды, что требует упреждающего удара, чтобы скрыть оборону аванпоста. Выслеживая этих неуловимых разведчиков, Орда лишает местные силы Альянса зрения и отбивает охоту к новым вторжениям.",h="«Вестницы Ясеневого леса» — задание Орды по перехвату патрулей, выдаваемое Курай'бином в Ясеневом лесу.",kw={"alliance","ashenvale","ashenvale outrunners","horde","kuray'bin","night elf scouts","silverwing outpost","альянс","ясеневый лес","вестницы ясеневого леса","орда","курай'бин","разведчики ночных эльфов","аванпост среброкрылых"},ang={["class:Hunter"]="Выслеживание скрытых вестниц в глухих лесах требует острого чутья, обостренного чувства следа и меткой стрельбы.",["class:Rogue"]="Уничтожение вражеских вестниц оборачивает скрытность ночных эльфов против них самих, и лазутчики Орды остаются хозяевами лесных теней.",["faction:Horde"]="Каждая сраженная в Ясеневом лесу разведчица ночных эльфов защищает местные лагеря и лесозаготовки от согласованных контрударов Альянса."},sec={{t="Глаза в кронах",b="Чащи Ясеневого леса остаются спорным рубежом, где за каждой тропой и хребтом пристально следят. Разведка смертельна, как топор, и донесения, поступающие к Курай'бину, подтверждают: разведчицы ночных эльфов, известные как Вестницы Ясеневого леса, выскользнули из оплота Альянса — Аванпоста Среброкрылых. Действуя в густых дебрях к востоку от своей базы и к югу от владений Орды, эти разведчицы крадутся по лесным тропам, нанося на карту укрепления и отслеживая передвижения войск."},{t="Ослепить Альянс",b="Чтобы предотвратить организованное нападение, Орда стремится уничтожать вражескую разведку до ее возвращения. Выслеживая вестниц, воины Орды лишают командиров Аванпоста Среброкрылых важных сведений о численности войск и обороне периметра аванпоста. Лишившись передовых глаз, ночные эльфы теряют ориентацию и гораздо менее охотно рискуют проводить наступательные маневры в спорных лесах."}},faq={{q="Кто выдает задание «Вестницы Ясеневого леса»?",a="Задание выдает Курай'бин, координатор разведчиков Орды, расквартированный в Ясеневом лесу, который следит за передвижениями ночных эльфов в лесу и противодействует им.",al={"quest giver","who gives quest","kuray'bin quest","персонаж, выдающий задания","кто выдает задание","задание курай'бина"}},{q="Где находятся Вестницы Ясеневого леса?",a="Вестницы рыщут по лесам к востоку от Аванпоста Среброкрылых и к югу от лагеря Курай'бина, патрулируя подлесок и собирая сведения.",al={"outrunners location","where are outrunners","where to find outrunners","где вестницы","где находятся вестницы","где найти вестниц"}},{q="Чем вестницы опасны для Орды?",a="Вестницы — передовые разведчицы, действующие из Аванпоста Среброкрылых. Если им удастся нанести на карту лагеря Орды и подсчитать войска, Альянс сможет скоординировать точные налеты на уязвимые позиции.",al={"why kill outrunners","threat of outrunners","outrunner purpose","зачем убивать вестниц","угроза вестниц","цель вестниц"}},{q="Что такое Аванпост Среброкрылых?",a="Аванпост Среброкрылых — крупное военное укрепление ночных эльфов в Ясеневом лесу, передовая база сил Альянса, защищающих лес и противостоящих расширению Орды.",al={"silverwing outpost lore","what is silverwing outpost","silverwing alliance","аванпост среброкрылых","что такое аванпост среброкрылых","среброкрылые альянс"}},{q="Входит ли это задание в более длинную цепочку?",a="Это задание — прежде всего самостоятельная тактическая задача по сокращению разведки Альянса в этом районе, награждающая бойцов, которые помогают Курай'бину охранять периметр.",al={"quest chain","follow up quest","outrunner chain","цепочка заданий","следующее задание","цепочка вестниц"}},{q="Могут ли игроки Альянса выполнить это задание?",a="Нет, это задание доступно только Орде. Курай'бин действует строго в интересах передовых сил Орды в Ясеневом лесу.",al={"is this horde only","alliance version","can alliance do this","только для орды","версия для альянса","может ли альянс выполнить это"}}},fp="20,388,20.476.0,21.423.0,41.151.0,43.148.0,45.204.0,27.180.0,41.179.0,41.119.0"}
P.entries["quest:6504"] = {n="Утраченные страницы",s="Когда орчиха Гурда Печать Гнева везла только что купленную гоблинский крошшер из Кабестана на Лесозаготовки Песни Войны, внезапный порыв ветра унес руководство по эксплуатации машины. Застряв возле Заставы Расщепленного Дерева, она не может управлять этим сложным инженерным чудом, пока не соберет разлетевшиеся страницы.",h="Когда орчиха Гурда Печать Гнева везла только что купленную гоблинский крошшер из Кабестана на Лесозаготовки...",kw={"ashenvale","gurda ragescar","ratchet","shredder","shredder operating manual","splintertree post","the lost pages","warsong lumber camp","ясеневый лес","гурда печать гнева","кабестан","крошшер","руководство по эксплуатации крошшера","застава расщепленного дерева","утраченные страницы","лесозаготовки песни войны"},ang={["faction:Horde"]="Каждый крошшер, добравшийся до Лесозаготовок Песни Войны, ускоряет заготовку драгоценной древесины, необходимой для строительства стен, хижин и боевых кораблей в Дуротаре.",["profession:Engineering"]="Механики прекрасно поймут затруднение Гурды: управлять гоблинским крошшером без инструкции изготовителя — верный путь к катастрофическому взрыву котла.",["race:Orc"]="Тяжелый физический труд и воинские традиции оставляют мало терпения для подробных гоблинских бумаг, поэтому раздражение Гурды из-за потерянных технических листов вполне понятно."},sec={{t="Порыв неудачи",b="Клан Песни Войны сильно зависит от паровых крошшеров, купленных у гоблинов порта Кабестан, для вырубки леса в Ясеневом лесу. Управлять этими хрупкими шумными механизмами обычному орку-воину совсем не просто. Когда Гурда Печать Гнева отправилась на север с только что купленным крошшером, внезапный порыв ветра вырвал у нее из рук инструкцию и разбросал двенадцать хрупких пергаментных листов по лесной земле."},{t="Страницы в дебрях",b="Поскольку дикие ветры пронесли руководство над кронами, отдельные страницы оказались в руках бродячих существ, культистов и лесных обитателей по всему региону. Пока не собраны все три главы, сложный механизм остается неподвижной глыбой стали с жужжащими пилами, а Гурда застряла на дороге к Заставе Расщепленного Дерева и не может явиться на лесозаготовки."}},faq={{q="Кто такая Гурда Печать Гнева?",a="Гурда Печать Гнева — работница Орды, которой поручено доставить гоблинский крошшер из торгового порта Кабестан в Ясеневый лес для участия в вырубке на Лесозаготовках Песни Войны.",al={"gurda","ragescar","who is the quest giver","гурда","печать гнева","кто выдает задание"}},{q="Зачем Гурде нужно руководство, чтобы управлять крошшером?",a="Гоблинская инженерия славится капризностью и нелогичностью: она полагается на взрывоопасные котлы, хитрые клапаны давления и сложные рычаги. Даже усердный орк не может безопасно управлять механизмом, не прочитав руководство изготовителя.",al={"why manual","why cant she drive it","shredder operating manual","зачем руководство","почему она не может управлять","руководство по эксплуатации крошшера"}},{q="Как страницы руководства оказались разбросаны по всему Ясеневому лесу?",a="Когда Гурда ехала на север по лесной дороге, сильный порыв ветра вырвал книгу у нее из рук. Рассыпавшиеся страницы разлетелись по лесу, и у нее осталась лишь пустая обложка.",al={"how did pages get lost","wind blew pages","как потерялись страницы","ветер унес страницы"}},{q="Куда в итоге предназначен крошшер?",a="Машина предназначена для Лесозаготовок Песни Войны, где Орда ведет усиленную сплошную вырубку, чтобы снабжать древесиной Оргриммар и Дуротар.",al={"where is the shredder going","warsong shredder destination","куда направляется крошшер","назначение крошшера песни войны"}},{q="Где найти пропавшие страницы?",a="Ветры разнесли страницы далеко и широко, и их подобрали разные гуманоиды и враждебные лесные обитатели, бродящие по Ясеневому лесу.",al={"where to find pages","who drops the pages","где найти страницы","у кого страницы"}},{q="Почему Орда покупает механизмы в Кабестане?",a="Кабестан — ближайший нейтральный порт с действующими торговыми связями с гоблинскими картелями. Орда регулярно закупает специализированную технику, подрывные инструменты и паровые машины для усиления своей военной логистики.",al={"horde goblin machinery","ratchet trade horde","гоблинские механизмы орды","торговля кабестана с ордой"}}},fp="14,296,18.449.0,23.388.0,22.180.0,64.235.0,61.195.0,42.159.0,37.143.0,51.225.0"}
P.entries["quest:6523"] = {n="Защита Кайи",s="«Защита Кайи» — задание Орды с сопровождением в Когтистых горах. Обнаружив Кайю Плоское Копыто в плену у враждебных тауренов из племени Зловещего Тотема, искатели приключений проводят ее по опасным горным тропам до Лагеря Апарахе. Весть о ее спасении приносит огромное облегчение ее встревоженному отцу, Макабе Плоскому Копыту.",h="«Защита Кайи» — задание Орды с сопровождением в Когтистых горах.",kw={"camp aparaje","escort","grimtotem","kaya flathoof","makaba flathoof","protect kaya","stonetalon","tauren","лагерь апарахе","сопровождение","зловещий тотем","кайя плоское копыто","макаба плоское копыто","защита кайи","когтистые горы","таурен"},ang={["faction:Horde"]="Забота о безопасности путешествующих семей укрепляет с трудом завоеванные Ордой плацдармы и маршруты снабжения в Когтистых горах.",["race:Tauren"]="Спасение Кайи напрямую помогает сородичам, страдающим от агрессии клана Зловещего Тотема."},sec={{t="Пленница в скалах",b="В Когтистых горах среди тауренов бушуют острые распри, и нигде напряжение не сильнее, чем вокруг вероломного клана Зловещего Тотема. Глубоко на вражеской земле Кайя Плоское Копыто была схвачена и заточена. Бежать пешком означает пробираться по извилистым тропам, где поджидают хищники и бдительные враги, поэтому вооруженный эскорт — ее единственная реальная надежда добраться до дружественных земель."},{t="Бегство в Лагерь Апарахе",b="Лагерь Апарахе находится в восточной части Когтистых гор, и оттуда Кайя знает дорогу домой. Она стремится к лагерю, уверенная, что, добравшись до него, найдет путь сама. Если провести ее по тропам, полным засад, она избежит повторного плена, пока похитители не поняли, что она ускользнула."},{t="Облегчение отца",b="В ожидании вестей у юго-восточной границы Когтистых гор Макаба Плоское Копыто опасается худшего за пропавшую дочь. Когда гонцы приносят подтверждение, что Кайя благополучно добралась до Лагеря Апарахе, отчаяние Макабы сменяется безмерной благодарностью героям, вставшим между его дитя и ее похитителями."}},faq={{q="Кто такая Кайя Плоское Копыто?",a="Кайя Плоское Копыто — молодая таурен, захваченная враждебными силами Зловещего Тотема в Когтистых горах. Она надеется на проходящих мимо искателей приключений Орды, которые помогут ей бежать и проводят в безопасное место.",al={"who is kaya","kaya flathoof lore","kaya","кто такая кайя","кайя плоское копыто предания","кайя"}},{q="Куда нужно сопроводить Кайю?",a="Кайю нужно благополучно проводить по тропам до Лагеря Апарахе в восточных Когтистых горах, откуда она сама знает дорогу домой.",al={"kaya escort destination","where to take kaya","where does kaya go","куда сопровождать кайю","куда вести кайю","куда идет кайя"}},{q="Кто такой Макаба Плоское Копыто?",a="Макаба Плоское Копыто — отец Кайи, тревожно ждущий у юго-восточного входа в Когтистые горы. Он отчаивается из-за пропавшего ребенка, пока искатели приключений не приносят весть о ее спасении.",al={"who is makaba","makaba flathoof lore","kaya's father","кто такой макаба","макаба плоское копыто предания","отец кайи"}},{q="Кто похитил Кайю?",a="Кайю взяли в плен враждебные таурены из племени Зловещего Тотема, устроившие лагеря и засады среди скал Когтистых гор.",al={"who took kaya","who kidnapped kaya","kaya kidnappers","кто похитил кайю","кто взял кайю в плен","похитители кайи"}},{q="Что происходит после того, как Кайя добирается до Лагеря Апарахе?",a="Когда Кайя добирается до Лагеря Апарахе, она может найти дорогу сама, а игроку поручено вернуться к Макабе Плоскому Копыту и принести радостную весть о ее спасении.",al={"after protect kaya","what next after escort","protect kaya follow up","после защиты кайи","что дальше после сопровождения","защита кайи продолжение"}},{q="Доступно ли это задание игрокам Альянса?",a="Нет. Семья Плоское Копыто принадлежит к мирным тауренам, союзным Орде, поэтому это спасение доступно только искателям приключений Орды.",al={"can alliance do protect kaya","is kaya horde only","может ли альянс защита кайи","только ли орда кайя"}}},fp="12,311,22.400.0,22.295.0,17.322.1,21.195.0,36.131.0,23.190.0,18.115.0,45.162.0,44.137.0"}
P.entries["quest:6541"] = {n="Донесение Кадраку",s="Торк на Перекрестке направляет способных бойцов Орды на север, к сторожевой башне Кадрака у границы Ясеневого леса. Кадрак координирует расширение Орды в древний лес и готовит прибывающих новобранцев к предстоящим стычкам.",h="Торк на Перекрестке направляет способных бойцов Орды на север, к сторожевой башне Кадрака у границы Ясеневого...",kw={"ashenvale","barrens","crossroads","kadrak","splintertree","thork","watch tower","zoram strand","ясеневый лес","степи","перекресток","кадрак","застава расщепленного дерева","торк","сторожевая башня","зорамское взморье"},ang={["faction:Horde"]="Это поручение знаменует переход от обороны обжитых земель в Степях к защите жизненно важных ресурсных путей в спорных лесах на севере.",["race:Orc"]="Ясеневый лес — важное испытание для орков: древесина нужна, чтобы укрепить Оргриммар и создать прочный дом в Калимдоре."},sec={{t="Дорога на север",b="Пока Перекресток отбивается от свинобразов, кентавров и местных разбойников, более широкие территориальные интересы Орды обращены на север, к густым чащам Ясеневого леса. Торк выступает посредником, направляя опытных бойцов, проявивших себя в центральных Степях, к северной пограничной башне, которой командует Кадрак."},{t="Стратегия на границе",b="Кадрак руководит южными подступами к Ясеневому лесу, организуя подкрепление для плацдарма Орды за границей. С новыми лагерями, такими как Застава Расщепленного Дерева и форт на Зорамском взморье, Орда активно укрепляет свое присутствие в богатых древесиной лесах, несмотря на ожесточенное сопротивление местных ночных эльфов."}},faq={{q="Кто такой Торк?",a="Торк — офицер-орк, расквартированный на Перекрестке в Степях. Он помогает координировать местную оборону и направляет перспективных искателей приключений на региональные военные кампании, такие как война в Ясеневом лесу.",al={"thork crossroads","who gives report to kadrak","thork barrens","торк перекресток","кто дает донесение кадраку","торк степи"}},{q="Где находится Кадрак?",a="Кадрак стоит на северной сторожевой башне в Степях, прямо у главной дороги, ведущей в Ясеневый лес.",al={"kadrak location","where is kadrak","kadrak watch tower","где кадрак","расположение кадрака","сторожевая башня кадрака"}},{q="Почему Орда продвигается в Ясеневый лес?",a="Орде нужны древесина и ресурсы для строительства новых городов в Дуротаре и Степях. Расширение в Ясеневый лес дает жизненно важный лес, но ставит Орду в прямой конфликт с ночными эльфами.",al={"why ashenvale","horde in ashenvale","ashenvale invasion","почему ясеневый лес","орда в ясеневом лесу","вторжение в ясеневый лес"}},{q="Какие форпосты Орда основала в Ясеневом лесу?",a="Кадрак сообщает, что Орда основала Заставу Расщепленного Дерева на центральной дороге в лес и еще один форпост западнее, на Зорамском взморье.",al={"horde bases ashenvale","zoram strand base","splintertree","базы орды ясеневый лес","база зорамское взморье","застава расщепленного дерева"}},{q="Что будет после донесения Кадраку?",a="Когда вы доложите Кадраку, он расскажет вам о местной военной обстановке и поручит собрать отчеты на разных заставах клана Песни Войны в Ясеневом лесу.",al={"after kadrak","next quest after kadrak","what does kadrak give","после кадрака","следующее задание после кадрака","что дает кадрак"}},{q="Можно ли получить это задание не в Степях?",a="Да. Почти такой же приказ явиться к Кадраку получают бойцы Орды в Малака'джине в Когтистых горах.",al={"alternate kadrak quest","stonetalon kadrak quest","другое задание кадрака","задание кадрака когтистые горы"}}},fp="16,238,14.323.0,17.338.0,13.204.0,24.127.0,40.204.0,53.157.0,37.158.0,69.136.0"}
P.entries["quest:6542"] = {n="Донесение Кадраку",s="Этот военный приказ направляет воинов Орды из Малака'джина в Когтистых горах к сторожевому посту Кадрака на границе северных Степей. Он знаменует переход от обороны скал к усилению спорной военной кампании Орды в Ясеневом лесу. Доложив Кадраку, солдаты отправляются поддерживать передовые лагеря, такие как Застава Расщепленного Дерева и Зорамское взморье.",h="Этот военный приказ направляет воинов Орды из Малака'джина в Когтистых горах к сторожевому посту Кадрака на...",kw={"ashenvale","barrens","darn talongrip","kadrak","splintertree","stonetalon mountains","warsong reports","zoram strand","ясеневый лес","степи","дарн цепкохват","кадрак","застава расщепленного дерева","когтистые горы","отчет песни войны","зорамское взморье"},ang={["faction:Horde"]="Этот приказ включает вас в более широкие военные усилия Вождя, направляя бывалых бойцов границы в борьбу за ресурсы Ясеневого леса.",["race:Orc"]="Кампания в Ясеневом лесу крайне важна для клана Песни Войны и выживания Дуротара, поэтому пост Кадрака — испытательная площадка для молодых орков-воинов.",["race:Tauren"]="Дозорные Орды, такие как орк Дарн Цепкохват, безопасно проводят путников через горные границы, сохраняя связь между землями Кровавого Копыта и северным фронтом Вождя."},sec={{t="Призыв на северный фронт",b="В скалистом проходе Малака'джин орк Дарн Цепкохват следит за южными и горными рубежами Орды. Но главное военное давление приходится на север, в древние чащи Ясеневого леса, где часовые ночных эльфов беспрестанно сражаются с лесорубами клана Песни Войны. Видя бывалых бойцов, проходящих через Когтистые горы, Дарн направляет способных новобранцев к северной сторожевой башне в Степях, чтобы помочь в идущих кампаниях."},{t="Дозор Кадрака",b="Орк Кадрак стоит на северном рубеже, где засушливая саванна встречается с зеленым пологом Ясеневого леса, и руководит передвижением войск Орды на спорную территорию. Орда напористо укрепляет свои позиции, держа форпосты на западном Зорамском взморье и на Заставе Расщепленного Дерева на севере. Кадрак служит важным узлом для координации снабжения, войск и срочных донесений на этих осажденных лесных рубежах."}},faq={{q="Кто посылает вас к Кадраку из Когтистых гор?",a="Дарн Цепкохват, орк, расквартированный на форпосте Орды Малака'джин в Когтистых горах, дает этот приказ способным искателям приключений, направляющимся к границе леса.",al={"quest giver report to kadrak","who starts report to kadrak stonetalon","darn talongrip quest","персонаж, выдающий задания донесение кадраку","кто начинает донесение кадраку когтистые горы","задание дарна цепкохвата"}},{q="Где находится Кадрак?",a="Кадрак стоит на северной сторожевой башне в Степях и охраняет главную дорогу, ведущую на север, в Ясеневый лес.",al={"kadrak location","where is kadrak","find kadrak","где кадрак","расположение кадрака","найти кадрака"}},{q="Почему Орда набирает воинов для Ясеневого леса?",a="Орде нужна древесина для Оргриммара, и она создала укрепленные позиции, такие как Зорамское взморье и Застава Расщепленного Дерева. Поскольку им противостоят местные ночные эльфы, командирам постоянно нужно подкрепление, чтобы удержать территорию.",al={"why go to ashenvale","horde ashenvale campaign","why fight in ashenvale","зачем идти в ясеневый лес","кампания орды в ясеневом лесу","зачем воевать в ясеневом лесу"}},{q="Что происходит после донесения Кадраку?",a="Кадрак расскажет вам о стратегической обстановке в Ясеневом лесу и поручит доставлять и собирать военные донесения на спорных форпостах леса в задании «Отчет Песни Войны».",al={"what next after kadrak","the warsong reports","kadrak follow up quest","что дальше после кадрака","отчет песни войны","продолжение задания кадрака"}},{q="Отличается ли это задание от версии в Степях?",a="Оба задания — вводные и ведут к Кадраку на границе Ясеневого леса. Одно выдается в Степях (на Перекрестке), другое — в Когтистых горах; выполнение любого из них направляет вас в сюжетную линию Ясеневого леса.",al={"barrens vs stonetalon kadrak","two report to kadrak quests","kadrak breadcrumb duplicate","кадрак степи или когтистые горы","два задания донесение кадраку","дубликат вводного задания кадрака"}},{q="Что такое Зорамское взморье, упомянутое в инструктаже?",a="Зорамское взморье — прибрежная область на северо-западе Ясеневого леса у Сокрытого Моря. Орда основала там укрепленный пляжный форпост для тактических передвижений и обеспечения морского доступа.",al={"what is zoram strand","zoram strand outpost","ashenvale beach base","что такое зорамское взморье","форпост зорамское взморье","пляжная база ясеневый лес"}}},fp="16,398,28.440.0,14.447.0,40.174.0,24.128.0,51.274.0,39.186.0,49.221.0,51.197.0"}
P.entries["quest:6543"] = {n="Отчет Песни Войны",s="Это задание, выдаваемое Кадраком на пограничной башне между северными Степями и Ясеневым лесом, поручает гонцам координировать разведданные по всему спорному лесу. Искатели приключений должны доставить действующие приказы и собрать сведения с передовой у всадников близ Азшары, Заставы Расщепленного Дерева и Зорамского взморья.",h="Это задание, выдаваемое Кадраком на пограничной башне между северными Степями и Ясеневым лесом, поручает...",kw={"ashenvale","barrens","kadrak","splintertree post","warsong outrider","warsong reports","warsong runner","warsong scout","zoram strand","zoram'gar outpost","ясеневый лес","степи","кадрак","застава расщепленного дерева","всадник из клана песни войны","отчет песни войны","гонец клана песни войны","разведчик клана песни войны","зорамское взморье","форт зорам'гар"},ang={["class:Hunter"]="Выслеживание на коварных дорогах Ясеневого леса проверяет навыки ориентирования и выживания в дикой местности — как среди диких хищников, так и среди скрытых эльфийских лучников.",["faction:Horde"]="Доставка этих отчетов — один из первых настоящих шагов молодого воина Орды в борьбе за территории против ночных эльфов на севере Калимдора.",["race:Orc"]="Для орков поддержка клана Песни Войны — дело клановой чести и практической необходимости: она обеспечивает бесперебойные поставки древесины для строительства Оргриммара."},sec={{t="Снабжение границы",b="Стоя на укрепленной сторожевой башне на северном краю Степей, Кадрак следит за передвижением через узкий горный каньон, ведущий в Ясеневый лес. Для Орды важно удерживать этот проход: засушливые степи не дают огромного количества древесины, нужной Оргриммару, и клан Песни Войны вынужден углубляться в древние эльфийские леса. Чтобы снабжать и согласовывать разрозненные передовые дозоры, нужны надежные гонцы, способные уходить от засад ночных эльфов на коварных лесных тропах Ясеневого леса."},{t="Глаза над Ясеневым лесом",b="Задание прочерчивает дугу через весь древний лес. На дальнем западе, на туманном берегу Зорамского взморья, гонец клана Песни Войны следит за активностью наг и угрозами с моря близ Форта Зорам'гар. Глубже в лесу, на Заставе Расщепленного Дерева, разведчик координирует оборону от постоянных набегов Часовых. Дальше на восток, по извилистой дороге к разрушенным руинам Азшары, всадник наблюдает за восточными подступами. Сведения со всех трех постов дают Кадраку целостную картину передвижений войск ночных эльфов и уязвимых мест границы."}},faq={{q="Где начинается это задание?",a="Задание начинается у Кадрака, офицера-орка в деревянной сторожевой башне, охраняющей горный проход на границе северных Степей и южного Ясеневого леса.",al={"quest giver","kadrak location","who gives the warsong reports","where to start","персонаж, выдающий задания","где кадрак","кто дает отчет песни войны","где начать"}},{q="Почему Орда шпионит в Ясеневом лесу?",a="Орда сильно зависит от густых чащ Ясеневого леса для строительства и укрепления поселений, таких как Оргриммар. Местные ночные эльфы яростно защищают свои священные рощи, превращая весь край в действующую зону боевых действий, где нужна постоянная разведка, чтобы удерживать форпосты и линии снабжения.",al={"why ashenvale","warsong lumber","ashenvale conflict","почему ясеневый лес","лес песни войны","конфликт в ясеневом лесу"}},{q="Где найти трех разведчиков клана Песни Войны?",a="Гонец клана Песни Войны находится в Форте Зорам'гар на Зорамском взморье, на дальнем северо-западе. Разведчик клана Песни Войны расквартирован на Заставе Расщепленного Дерева у главной дороги. Всадник из клана Песни Войны патрулирует восточную дорогу к границе Азшары.",al={"scout locations","where are the scouts","outrider runner scout location","где разведчики","где найти разведчиков","расположение всадника гонца разведчика"}},{q="Кто такие всадники клана Песни Войны?",a="Всадники клана Песни Войны — разведчики и налетчики орочьего клана Песни Войны. Известные яростной кавалерией и тактикой стычек, они возглавляют расширение Орды, заготовку древесины и защиту территорий в чащах Ясеневого леса.",al={"warsong clan","who are warsong outriders","warsong clan ashenvale","клан песни войны","кто такие всадники песни войны","клан песни войны ясеневый лес"}},{q="Что происходит после возвращения с отчетами?",a="Получив собранные сведения, Кадрак использует тактические данные, чтобы планировать будущие передвижения войск, усиливать уязвимые форпосты, такие как Зорам'гар и Застава Расщепленного Дерева, и закреплять присутствие Орды глубже в лесу.",al={"reports turn in","next move","what does kadrak do","сдать отчеты","следующий шаг","что делает кадрак"}},{q="Безопасна ли дорога через Ясеневый лес для гонцов низкого уровня?",a="Нет. На главной дороге через Ясеневый лес часто устраивают засады скрытные Часовые ночных эльфов, враждебные животные, такие как кошки-охотники и медведи, и патрули Альянса из таких поселений, как Астранаар.",al={"ashenvale danger","is the road safe","night elf ganks","опасность ясеневого леса","безопасна ли дорога","убийства ночных эльфов"}}},fp="19,333,18.542.0,21.568.0,30.175.0,37.290.0,44.255.0,30.242.0,41.226.0,58.210.0"}
P.entries["quest:6544"] = {n="Налет Торека",s="Налет Торека — прямой рейд Орды из глуши Ясеневого леса против близлежащего гарнизона ночных эльфов на Аванпосте Среброкрылых. Под командованием орка-налетчика Торека по приказу Заставы Расщепленного Дерева отряд стремится сломить сопротивление местных Часовых и убить их командира, Дариэль Лунное Пламя. Это одна из самых дерзких и кровавых стычек в продолжающейся войне за границы Ясеневого леса.",h="Налет Торека — прямой рейд Орды из глуши Ясеневого леса против близлежащего гарнизона ночных эльфов на...",kw={"ashenvale","duriel moonfire","ertog ragetusk","raiders","sentinels","silverwing outpost","splintertree post","torek","ясеневый лес","дариэль лунное пламя","эртог лютоклык","налетчики","часовые","аванпост среброкрылых","застава расщепленного дерева","торек"},ang={["class:Warrior"]="Жестокая лобовая рукопашная схватка, проверяющая физическую выносливость в бою с опытными лучницами-Часовыми и мастерами клинка.",["faction:Alliance"]="Гибель Дариэль Лунное Пламя обнажает Аванпост Среброкрылых и угрожает исконным лесным владениям ночных эльфов.",["faction:Horde"]="Для Орды прорыв мимо Аванпоста Среброкрылых — важное испытание силы, ослабляющее блокаду ночных эльфов вокруг Заставы Расщепленного Дерева.",["race:NightElf"]="Рейд бьет по сердцу фронтового командования Часовых, проливая эльфийскую кровь под сенью Ясеневого леса."},sec={{t="Удар из тени",b="В Ясеневом лесу идет нарастающая приграничная война между лесозаготовительными лагерями Орды и коренными ночными эльфами. Стремясь прорвать оборонительный периметр Альянса, Торек собирает отряд налетчиков с Расщепленного Дерева неподалеку от Аванпоста Среброкрылых. Не дожидаясь ответного удара, Торек организует лобовую атаку, чтобы разрушить оборону аванпоста, пока ночные эльфы не подготовили усиленную кампанию против Заставы Расщепленного Дерева."},{t="Захват Среброкрылых",b="Аванпост Среброкрылых — укрепленный лесной оплот, который охраняют бдительные Среброкрылые Часовые и свирепые эльфийские воины. Главная цель Торека — их предводительница Дариэль Лунное Пламя. Ее гибель обезглавит военную иерархию ночных эльфов в этом районе, и налетчики смогут доложить о кровавой победе командиру Эртогу Лютоклыку у Реки Фалфаррен."}},faq={{q="Кто такой Торек?",a="Торек — агрессивный орк-налетчик с Заставы Расщепленного Дерева в Ясеневом лесу. Свирепый и жаждущий битвы, он командует отрядом налетчиков, которым поручено напрямую атаковать силы ночных эльфов, окопавшиеся в лесу.",al={"torek npc","who is torek","torek orc","торек","кто такой торек","орк торек"}},{q="Что такое Аванпост Среброкрылых?",a="Аванпост Среброкрылых — укрепленное поселение ночных эльфов в Ясеневом лесу. Его охраняют элитные Часовые и воины, а сам он служит военным оплотом, следящим за передвижениями войск Орды по лесным тропам.",al={"silverwing outpost","what is silverwing","аванпост среброкрылых","что такое среброкрылые"}},{q="Кто такая Дариэль Лунное Пламя?",a="Дариэль Лунное Пламя — командир ночных эльфов, защищающая Аванпост Среброкрылых. Как глава гарнизона, она направляет местных Часовых против вторжений Орды, пока отряд Торека не прорывается в лагерь, чтобы сразить ее.",al={"duriel moonfire","duriel","дариэль лунное пламя","дариэль"}},{q="Кто такой Эртог Лютоклык?",a="Эртог Лютоклык — офицер Орды на Заставе Расщепленного Дерева. Он является начальником Торека, руководит военными операциями в регионе и принимает донесения о победах над Альянсом.",al={"ertog ragetusk","ertog","эртог лютоклык","эртог"}},{q="Почему Орда нападает на Аванпост Среброкрылых?",a="Орда и ночные эльфы ведут активную борьбу за территории по всему Ясеневому лесу. Удар по Аванпосту Среброкрылых ослабляет давление на линии снабжения Орды и напрямую подрывает сеть обороны Часовых, охраняющих глубь леса.",al={"why attack silverwing","ashenvale conflict silverwing","зачем нападать на среброкрылых","конфликт в ясеневом лесу среброкрылые"}},{q="Где происходит это нападение?",a="Налет начинается неподалеку от Аванпоста Среброкрылых, к западу от Реки Фалфаррен в Ясеневом лесу, и завершается в самом лагере ночных эльфов.",al={"torek assault location","where is torek","где налет торека","где торек"}}},fp="15,390,25.430.0,17.377.0,13.236.0,27.204.0,23.224.1,22.206.0,45.234.0,34.153.0"}
P.entries["quest:6545"] = {n="Сведения гонца клана Песни Войны",s="Сведения гонца клана Песни Войны — задание Орды по передаче сообщений, связывающее передовые рубежи Ясеневого леса с командирами на границе. Донесение, доверенное гонцам и новобранцам, описывает растущее военное давление на разведчиков Песни Войны, в частности агрессию наступающих нага.",h="Сведения гонца клана Песни Войны — задание Орды по передаче сообщений, связывающее передовые рубежи Ясеневого...",kw={"ashenvale","kadrak","mor'shan","naga","rampart","report","runner","scout","warsong","ясеневый лес","кадрак","мор'шан","нага","застава","донесение","гонец","разведчик","песнь войны"},ang={["faction:Horde"]="На лесной границе важен каждый воин: поддержание связи между Степями и передовыми аванпостами критично для выживания.",["race:Orc"]="Клан Песни Войны полагается на стойкость и бдительность своих гонцов, чтобы удерживать земли, захваченные под командованием вождя Тралла."},sec={{t="Донесения с передовой",b="Клан Песни Войны держит по всему Ясеневому лесу цепочку разведчиков и гонцов, чтобы следить за враждебными силами и поддерживать линии снабжения. Из-за стычек с Часовыми ночных эльфов и суровой местности быстрые сведения жизненно важны. Гонцы с донесениями с передовой обеспечивают согласованность действий дальних гарнизонов с командирами, такими как Кадрак на Заставе Мор'шан."},{t="Угроза нага",b="Пока Орда ждет ожесточенного сопротивления ночных эльфов среди деревьев, часовые аванпоста сообщают о все более дерзких нападениях нага. Эти змеевидные захватчики бьют из водоемов и древних руин, испытывая на прочность баррикады аванпоста и заставляя защитников отвлекаться от лесозаготовок и пограничных дозоров. Сведения, доставленные на Заставу Мор'шан, бьют тревогу из-за этих согласованных амфибийных атак."}},faq={{q="Кому отправляется донесение?",a="Донесение доставляется прямо Кадраку, надзирателю на Заставе Мор'шан на границе Ясеневого леса и северных Степей.",al={"who receives update","kadrak report","where does report go","кто получает донесение","донесение кадраку","куда идет донесение"}},{q="Какие угрозы упомянуты в сведениях?",a="Разведчик сообщает, что местный аванпост выдержал неоднократные нападения, и указывает на растущую угрозу со стороны враждебных нага, действующих в ближних водах.",al={"what is in report","runner update content","naga attacks","что в донесении","содержание сведений гонца","нападения нага"}},{q="Почему Орда полагается здесь на пеших гонцов?",a="Густая листва, меткие стрелки ночных эльфов и изолированные аванпосты делают воздушные перелеты затруднительными или опасными в некоторых частях Ясеневого леса. Наземные посыльные позволяют быстро и незаметно передавать вести по охраняемым тропам.",al={"why runners","warsong runners lore","why not wyverns","почему гонцы","гонцы песни войны","почему не наездники на виверне"}},{q="Кто такие гонцы Песни Войны?",a="Это разведчики, посыльные и бойцы авангарда клана Песни Войны, которым поручено охранять линии снабжения и следить за передвижениями врага на спорных границах леса.",al={"warsong clan ashenvale","who are warsong runners","клан песни войны ясеневый лес","кто такие гонцы песни войны"}},{q="Где нападают нага в Ясеневом лесу?",a="Нага обосновались в укрепленных руинах на берегах и озерах Ясеневого леса, часто устраивая засады на путников и нападая на соседние лагеря.",al={"where are naga","ashenvale naga","где нага","нага ясеневого леса"}},{q="Для чего нужен аванпост в этой местности?",a="Застава служит пунктом раннего оповещения и опорой обороны, не давая врагам разорвать связь между лесозаготовками в глубине леса и Степями.",al={"why is the outpost here","horde camp purpose","зачем здесь аванпост","цель лагеря орды"}}},fp="21,288,20.419.0,15.446.0,32.153.0,41.157.0,45.206.0,31.170.0,42.139.0,43.172.0"}
P.entries["quest:6546"] = {n="Сведения всадника из клана Песни Войны",s="Сведения всадника из клана Песни Войны — задание Орды на доставку, начинающееся на опасных тропах восточного Ясеневого леса. Одинокий разведчик Песни Войны доверяет искателю приключений важные сведения об угрозах со стороны Альянса, засевших рядом сатиров и наступающих нага в соседнем Азшаре.",h="Сведения всадника из клана Песни Войны — задание Орды на доставку, начинающееся на опасных тропах восточного...",kw={"ashenvale","azshara","kadrak","mor'shan rampart","naga","satyr","warsong outrider","warsong report","ясеневый лес","азшара","кадрак","застава мор'шан","нага","сатиры","всадник песни войны","отчет песни войны"},ang={["faction:Horde"]="Каждое донесение, доставленное по линии Мор'шан, укрепляет хрупкий плацдарм Орды в густых чащах Ясеневого леса.",["race:Orc"]="Клан Песни Войны гордится тем, что держит авангард, но его разведчики знают: одной храбростью не остановить врагов, окружающих со всех сторон."},sec={{t="Глаза на краю леса",b="Восточный Ясеневый лес — спорная пограничная зона, где линии снабжения Орды постоянно подвергаются нападениям. Всадники Песни Войны бдительно следят за лесом, выявляя передвижения врага задолго до того, как налетчики ударят по таким аванпостам, как Застава Мор'шан или Застава Расщепленного Дерева. Встреча со всадником в дозоре означает оказаться в гуще разведывательной деятельности, где сведения решают, удержать укрепление или потерять его в засаде."},{t="Угрозы на каждом горизонте",b="Отчет, составленный всадником, рисует мрачную тактическую картину для Орды в центральных лесах Калимдора. Помимо постоянных стычек с ночными эльфами и Альянсом в целом, восточный Ясеневый лес кишит хитрыми демоническими сатирами. Опасность усугубляется тем, что разведчики обнаружили массовое присутствие нага в разрушенных прибрежных землях соседнего Азшара: командиры предупреждены, что Орда окружена враждебными силами почти со всех сторон."}},faq={{q="Что такое Отчет Песни Войны?",a="Это разведывательное донесение, написанное всадником Песни Войны, с описанием расположения вражеских войск и опасностей региона. В нем говорится об угрозах со стороны ближайших сил Альянса, действующих шабашей сатиров в восточном Ясеневом лесу и недавно обнаруженных передвижениях нага в Азшаре.",al={"warsong report quest item","what does the report say","scout report","отчет песни войны","что сказано в отчете","донесение разведчика"}},{q="Кто такой Кадрак?",a="Кадрак — командир Орды на Заставе Мор'шан, оборонительном рубеже, охраняющем северную границу между Степями и Ясеневым лесом. Он принимает прибывающих разведчиков и координирует передовые операции в лесу.",al={"who is kadrak","where is kadrak","kadrak turn in","кто такой кадрак","где кадрак","сдать задание кадраку"}},{q="Почему упомянуты нага в Азшаре?",a="Азшара непосредственно граничит с восточным Ясеневым лесом. Всадники следят за передвижениями чужаков в соседних землях, чтобы фланги Орды не были застигнуты врасплох крупным вторжением, пока она сражается с ночными эльфами.",al={"naga azshara connection","why mention azshara","azshara naga threat","нага азшара","зачем упоминать азшару","угроза нага азшара"}},{q="Чем так опасен восточный Ясеневый лес для Орды?",a="Регион зажат между действующими отрядами Альянса, древними руинами сатиров, пропитанными демонической скверной, и дикими лесными зверями, поэтому гонцы и патрули Орды уязвимы для засад со всех сторон.",al={"why is eastern ashenvale dangerous","ashenvale threats","satyr threat","чем опасен восточный ясеневый лес","угрозы ясеневого леса","угроза сатиров"}},{q="Кто такие Всадники Песни Войны?",a="Это передовой авангард и разведывательная конница клана Песни Войны в Ясеневом лесу, отвечающие за слежку за передвижениями ночных эльфов, прикрытие лесозаготовительных лагерей и охрану торговых дорог.",al={"what are outriders","warsong scouts","outriders lore","кто такие всадники","разведчики песни войны","всадники предания"}},{q="Почему всадник не может сам доставить отчет?",a="Всаднику поручено нести дозор на тропе и отслеживать вражеские передвижения в реальном времени. Если он покинет свой наблюдательный пост, передовая не заметит внезапного наступления Альянса или сатиров.",al={"why do i deliver report","why not deliver himself","почему я доставляю отчет","почему не доставит сам"}}},fp="23,283,26.482.0,24.477.0,27.264.0,14.230.0,38.209.0,56.218.0,30.187.0,50.208.0"}
P.entries["quest:6547"] = {n="Сведения разведчика клана Песни Войны",s="Сведения разведчика клана Песни Войны — задание Орды по передаче сообщений, связывающее командиров аванпостов на границах Ясеневого леса с передовыми разведчиками, наблюдающими за спорным лесом. Доставляя стратегические приказы Кадрака, гонцы помогают клану Песни Войны вести плотное наблюдение за ночными эльфами, устраивающими засады. Оно показывает шаткую, враждебную хватку, которую Орда стремится удержать над недавно занятыми землями.",h="Сведения разведчика клана Песни Войны — задание Орды по передаче сообщений, связывающее командиров аванпостов...",kw={"ashenvale","barrens","kadrak","night elves","report","scout","sentinels","warsong","ясеневый лес","степи","кадрак","ночные эльфы","донесение","разведчик","часовые","песнь войны"},ang={["faction:Horde"]="Каждый гонец, несущий приказы между Кадраком и дальними разведчиками, помогает удержать плацдарм Орды в Ясеневом лесу против неослабевающих засад ночных эльфов.",["race:NightElf"]="Присутствие разведчиков Песни Войны на границах — это постоянное осквернение священных лесов Элуны, от которого Часовые стремятся очистить землю.",["race:Orc"]="Наследие клана Песни Войны определяется его упорством в Ясеневом лесу: он добывает ценную древесину, несмотря на враждебность земли и ее древних защитников."},sec={{t="Глаза в тени",b="Пограничье Ясеневого леса остается пороховой бочкой, где никто не уступает ни пяди. Силы Орды под началом Кадрака сильно зависят от рассредоточенных разведчиков Песни Войны на опасных аванпостах: они следят за передвижениями ночных эльфов и защищают спорные линии снабжения. Поскольку сам лес дает естественное укрытие скрытным Часовым Альянса, регулярные донесения и письменные сведения необходимы, чтобы изолированные разведчики не оказались отрезаны и разгромлены."},{t="Удержать позиции",b="Для клана Песни Войны каждый расчищенный или занятый участок леса оплачен кровью. Разведчики постоянно высматривают ответные рейды ночных эльфов, стремящихся вернуть леса. Доставка приказов Кадрака убеждает авангард, что подкрепления и координация действуют, и разведчики могут доложить, что их оборонительные меры успешны, несмотря на непрерывное сопротивление эльфов."}},faq={{q="Кто такой Кадрак?",a="Кадрак — командир Орды на границе Степей и Ясеневого леса. Он координирует разведывательные вылазки, оборону границ и тыловое обеспечение операций Песни Войны, продвигающихся в древний лес.",al={"kadrak","who is kadrak","kadrak role","кадрак","кто такой кадрак","роль кадрака"}},{q="Почему разведчики Песни Войны так опасаются ночных эльфов?",a="Ночные эльфы естественно сливаются с тенями своих исконных лесов и внезапно устраивают засады на патрули Орды. Поскольку клан Песни Войны вырубает лес и заселяет землю, которую эльфы считают священной, разведчикам постоянно грозят смертельные внезапные нападения.",al={"why fear night elves","night elves in shadows","warsong scout elven danger","почему бояться ночных эльфов","ночные эльфы в тени","опасность эльфов для разведчиков"}},{q="Почему идет борьба за Ясеневый лес?",a="Орде нужны древесина и ресурсы Ясеневого леса для строительства Оргриммара и снабжения поселений в засушливых Степях и Дуротаре. Коренные ночные эльфы считают лес священной землей и яростно борются, чтобы изгнать орочьих лесорубов и гарнизоны.",al={"why fight over ashenvale","ashenvale war","horde ashenvale conflict","почему сражаются за ясеневый лес","война за ясеневый лес","конфликт орды в ясеневом лесу"}},{q="Какова роль клана Песни Войны здесь?",a="Клан Песни Войны возглавляет расширение Орды и добычу ресурсов в Ясеневом лесу. Приведенный в лес Громом Адским Криком еще во время Третьей войны, он прочно закрепился, держит лесозаготовительные лагеря и ведет постоянные стычки с Часовыми.",al={"warsong clan ashenvale","warsong role","клан песни войны ясеневый лес","роль песни войны"}},{q="Куда идут сведения после того, как дойдут до разведчика?",a="Когда разведчик получает обновленные указания Кадрака, он посылает весть об успехах против ответных ударов эльфов, чтобы руководство Орды знало об устойчивости передовой.",al={"who gets report","kadrak report","scout update result","кто получает отчет","донесение кадраку","итог сведений разведчика"}},{q="Успешны ли на данный момент планы Орды в Ясеневом лесу?",a="Передовые разведчики считают свои оборонительные усилия успешными: им удается удерживать укрепленные позиции и отражать удары эльфов, хотя регион остается ожесточенно оспариваемым полем боя, где ни одна сторона не добилась полного господства.",al={"is horde winning ashenvale","warsong progress","побеждает ли орда в ясеневом лесу","успехи песни войны"}}},fp="20,404,19.450.0,18.405.0,14.224.0,57.279.0,35.261.0,37.283.0,51.212.0,60.242.0"}
P.entries["quest:6548"] = {n="Отомсти за мою деревню",s="Макаб Плоское Копыто едва пережил жестокое нападение, когда налетчики из клана Зловещего Тотема обрушились на его деревню на юго-востоке Когтистых гор. Отрезанный от сородичей и окруженный мертвыми, он просит путников из Орды ударить по лагерю головорезов Зловещего Тотема и наемников, чтобы отомстить за павших соплеменников.",h="Макаб Плоское Копыто едва пережил жестокое нападение, когда налетчики из клана Зловещего Тотема обрушились на...",kw={"avenge my village","grimtotem","grimtotem mercenary","grimtotem ruffian","grundig darkcloud","makaba flathoof","stonetalon mountains","отомсти за мою деревню","зловещий тотем","наемник зловещего тотема","головорез зловещего тотема","грундиг темное облако","макаба плоское копыто","когтистые горы"},ang={["faction:Horde"]="Орда зависит от открытых и безопасных проходов между Степями и Когтистыми горами. Банда Зловещего Тотема, убивающая путников и союзные деревни, угрожает линиям снабжения Вождя в горах.",["race:Tauren"]="Предательство клана Зловещего Тотема сильнее всего бьет по путникам-тауренам. Видя, как своих же собратьев шу'хало режут их сородичи, остро ощущаешь мрачную реальность раскола кланов и опасность, которую Зловещий Тотем представляет для объединенного народа Кэрна."},sec={{t="Кровь в ущельях",b="У границы между Степями и красными каменными перевалами Когтистых гор Макаба Плоское Копыто остался единственным выжившим после жестокой резни. Налетчики под темными знаменами клана Зловещего Тотема напали без предупреждения и перебили почти всех в его поселении. Макаба яростно сражался и сразил нескольких нападавших, но в конце концов был вынужден скрыться, сохранив лишь жизнь и гнев."},{t="Угроза Зловещего Тотема",b="Клан Зловещего Тотема давно стал непокорной, агрессивной занозой для племен таурен, объединенных под началом верховного вождя Кэрна Кровавого Копыта. В отличие от мирных кочевников Мулгора, отряды Зловещего Тотема часто нанимают безжалостных головорезов и жадных до наживы наемников, чтобы захватывать земли и нападать на отдаленные поселения. Для Макабы дипломатия и родство племен теперь ничего не значат: лишь кровь, отплаченная кровью, может унять его горе."}},faq={{q="Кто выдал это задание?",a="Макаба Плоское Копыто — выживший таурен, разбивший лагерь у юго-восточного прохода в Когтистые горы. Он пережил жестокое разорение своей соседней деревни кланом Зловещего Тотема и жаждет возмездия налетчикам.",al={"quest giver","makaba flathoof","who is makaba","персонаж, выдающий задания","макаба плоское копыто","кто такой макаба"}},{q="Почему Зловещий Тотем нападает на других таурен?",a="Клан Зловещего Тотема так и не принял единство Орды и мирные замыслы Кэрна Кровавого Копыта. Яростные, враждебные к чужакам и агрессивные, они открыто нападают на поселения соперников, убивают чужаков и используют вооруженных громил и наемников, чтобы утвердить власть над такими землями, как Когтистые горы.",al={"why grimtotem hostile","tauren attacking tauren","grimtotem clan lore","почему зловещий тотем враждебен","таурены нападают на таурен","предания клана зловещего тотема"}},{q="Где находятся нападавшие из клана Зловещего Тотема?",a="Головорезы и наемники Зловещего Тотема расположились в лагере к западу от Макабы Плоского Копыта на юго-востоке Когтистых гор, среди скалистых холмов над проходом.",al={"where are the mobs","grimtotem camp location","where to find ruffians","где мобы","где лагерь зловещего тотема","где найти головорезов"}},{q="Кто такие наемники Зловещего Тотема?",a="Клан Зловещего Тотема часто пополняет ряды своих воинов, нанимая безжалостных бойцов и наемников для усиления отрядов, чтобы иметь достаточно силы для устрашения и разгрома отдаленных поселений.",al={"mercenaries","grimtotem sellswords","who are the mercs","наемники","наемники зловещего тотема","кто такие наемники"}},{q="Что происходит после этого задания?",a="Расправившись с головорезами и наемниками на передовой, Макаба просит вас нанести удар по предводителю резни, Грундигу Темное Облако, в следующем задании «Убить Грундига Темное Облако».",al={"next quest","what follows avenge my village","kill grundig darkcloud","следующее задание","что после отомсти за мою деревню","убить грундига темное облако"}},{q="Где находилась деревня Макабы?",a="Поселение Макабы было уединенным лагерем таурен у пограничных проходов на юго-востоке Когтистых гор. Налет Зловещего Тотема полностью уничтожил его, и Макаба остался одним из немногих известных выживших.",al={"flathoof village","where was the village","what village was destroyed","деревня плоское копыто","где была деревня","какая деревня уничтожена"}}},fp="17,328,18.429.0,20.448.0,20.222.0,45.297.0,42.185.0,34.212.0,30.187.1,35.214.0"}
P.entries["quest:6561"] = {n="Жестокость Черных Глубин",s="«Жестокость Черных Глубин» — срочная мольба умирающего воина Серебряного Рассвета, оказавшегося в ловушке в Непроглядной Пучине. Авантюристам Орды поручено покончить с Повелителем сумрака Келрисом, предводителем культа, который устраивает жуткие кровавые жертвоприношения древнему чудовищу в руинах внизу.",h="«Жестокость Черных Глубин» — срочная мольба умирающего воина Серебряного Рассвета, оказавшегося в ловушке в...",kw={"aku'mai","argent dawn","bashana runetotem","blackfathom deeps","blackfathom villainy","kelris","moon well","thaelrid","twilight lord kelris","twilight's hammer","аку'май","серебряный рассвет","башана рунический тотем","непроглядная пучина","жестокость черных глубин","келрис","лунный колодец","талрид","повелитель сумрака келрис","сумеречный молот"},ang={["class:Druid"]="Осквернение древнего лунного колодца ночных эльфов культистами, поклоняющимися Бездне, и нагами — мучительная рана на природном и духовном убежище Калимдора.",["class:Shaman"]="Смута, посеянная Келрисом и Аку'май, оскорбляет равновесие стихий, превращая чистые подземные воды в гниющее ложе тьмы и жертвоприношений.",["faction:Horde"]="Для Орды союз с разведчиком Серебряного Рассвета — редкий миг общих интересов против космической скверны, позволяющий заслужить ранее расположение Рассвета.",["race:Tauren"]="Башана Рунический Тотем видит в поражении Келриса важную защиту Матери-Земли, очищение от мерзости, пытавшейся ввергнуть природный порядок мира в изначальный хаос."},sec={{t="Отчаянный последний бой",b="Привлеченный подземным храмом на побережье Ясеневого леса, разведчик Серебряного Рассвета Талрид обнаружил ужасы куда страшнее обычных набегов наг. Раненый и лишенный сил в пещерах, ночной эльф понимает, что не сможет завершить задачу один. Чтобы его разведданные не погибли вместе с ним, он обращается к любым проходящим героям Орды, готовым ударить по темным предводителям затопленных залов."},{t="Жертвы Глубине",b="Цель задания — Повелитель сумрака Келрис, глава культистов Сумеречного Молота, укрепившихся в разрушенном Храме Луны. В союзе с местными нагами Келрис проводит темные ритуалы над оскверненным лунным колодцем, скармливая живых пленников Аку'май — ненасытной гидре и зверю Древних богов — в безумной погоне за космической силой и изначальным хаосом."},{t="Весть в Громовой Утес",b="Серебряный Рассвет считал Келриса погибшим или пропавшим, поэтому подтверждение его смерти крайне важно. Вместо того чтобы отправлять героев обратно в земли людей, Талрид велит доставить доказательство смерти предводителя культа Башане Рунический Тотем на Вершину Старейшин в Громовом Утесе. Башана, глубоко связанная с равновесием Матери-Земли, чтит победу, уничтожившую скверну, что стремилась ввергнуть Калимдор в первобытную гибель."}},faq={{q="Кто такой Повелитель сумрака Келрис?",a="Келрис — предводитель культистов Сумеречного Молота, занявших Непроглядную Пучину. Серебряный Рассвет считал его мертвым или пропавшим, но он тайно копил силу, принося живые жертвы древней гидре Аку'май у оскверненного лунного колодца.",al={"kelris","who is kelris","twilight lord kelris","келрис","кто такой келрис","повелитель сумрака келрис"}},{q="Почему член Серебряного Рассвета оказался в Непроглядной Пучине?",a="Страж Талрид из ордена Серебряного Рассвета пришел расследовать растущую угрозу в разрушенном храме ночных эльфов. Одолеваемый обитателями пещер и смертельно ослабленный, он остался в ловушке и вынужден полагаться на заглянувших искателей приключений, чтобы завершить свой долг и устранить Келриса.",al={"argent guard thaelrid","why is thaelrid here","argent dawn in bfd","страж талрид","почему талрид здесь","серебряный рассвет в непроглядной пучине"}},{q="Кто такой Аку'май?",a="Аку'май — чудовищная древняя многоглавая гидра, считающаяся изначальным слугой Древних богов. Дремавшая под затопленными руинами, она пробудилась, когда глубинная подземная скверна осквернила священные воды храма, и теперь пожирает пленников, которых приводит Сумеречный Молот.",al={"akumai","who is akumai","aku'mai lore","аку'май","кто такой аку'май","предания об аку'май"}},{q="Почему задание нужно сдать Башане Рунический Тотем?",a="Талрид направляет героев Орды к Башане Рунический Тотем на Вершине Старейшин в Громовом Утесе. Как хранительница равновесия Матери-Земли, Башана поддерживает связь с защитниками от древнего зла и считает поклонение Келриса Древним богам омерзительной язвой на теле Калимдора.",al={"bashana runetotem","why thunder bluff","where to turn in blackfathom villainy","башана рунический тотем","почему громовой утес","где сдать жестокость черных глубин"}},{q="Что случилось с руинами Непроглядной Пучины?",a="Давным-давно подземный комплекс был священным храмом богини луны Элуны. Катастрофические потрясения и древние темные течи из недр осквернили великий лунный колодец, и наги с культистами конца света захватили затопленные святилища для своей темной владычицы Аку'май.",al={"history of blackfathom deeps","temple of elune ruins","why is bfd corrupted","история непроглядной пучины","храм элуны руины","почему непроглядная пучина осквернена"}},{q="Какова цель культа Сумеречного Молота здесь?",a="Сумеречный Молот стремится вернуть мир в эпоху изначального хаоса, поклоняясь Древним богам. Келрис ищет личной силы через темное общение, скармливая невинных глубинам ради благосклонности древних сущностей.",al={"twilight's hammer motives","why cult in bfd","kelris goals","мотивы сумеречного молота","почему культ в непроглядной пучине","цели келриса"}}},fp="20,291,22.427.0,22.381.0,21.422.1,28.273.0,54.252.0,16.279.0,43.278.0,48.281.0,52.231.0"}
P.entries["quest:6562"] = {n="Угроза из Глубин",s="«Угроза из Глубин» — призыв о помощи, отправленный из Когтистых гор к далеким берегам Ясеневого леса. Цунаман направляет искателей приключений из Орды к тролльскому ученому Дже'неу Санкри в форт Зорам'гар, предупреждая об опасных силах на побережье.",h="«Угроза из Глубин» — призыв о помощи, отправленный из Когтистых гор к далеким берегам Ясеневого леса.",kw={"ashenvale","blackfathom deeps","je'neu sancrea","stonetalon mountains","tsunaman","windshear crag","zoram strand","zoram'gar outpost","ясеневый лес","непроглядная пучина","дже'неу санкри","когтистые горы","цунаман","утес ветрорезов","зорамское взморье","форт зорам'гар"},ang={["class:Shaman"]="Смута под волнами Зорамского взморья угрожает равновесию местных духов воды и требует духовного прозрения, чтобы очистить гниль.",["faction:Horde"]="Удержание форта Зорам'гар критически важно для защиты западного фланга Калимдора как от сил ночных эльфов, так и от прибрежных ужасов.",["race:Troll"]="Отклик на зов Дже'неу Санкри дает сородичам из племени Черного Копья важную возможность помочь одному из своих выдающихся ученых в раскрытии древних тайн Калимдора."},sec={{t="Зов к побережью",b="В засушливых ущельях Когтистых гор Цунаман понимает, что темные раскаты на севере требуют внимания. Он поручает способным путникам из Орды отправиться в Ясеневый лес — исконные леса ночных эльфов — и связаться с Дже'неу Санкри. Тот несет службу в форте Зорам'гар на дальнем западном краю, известном как Зорамское взморье, и столкнулся с растущей опасностью, требующей помощи извне."},{t="Дорога к Зорамскому взморью",b="Добраться до западного берега Ясеневого леса для путников из Орды непросто. Пробираясь через проходы Утеса Ветрорезов, потревоженные гоблинами, или двигаясь на север из Степей, они должны войти во враждебный лес, который яростно охраняют стражи ночных эльфов. Далеко за густыми кронами, на омываемом штормами побережье Зорамского взморья, одинокий форт борется за выживание, вглядываясь в темные воды рядом."},{t="Шепот под волнами",b="Когда путники прибывают на берег, Дже'неу Санкри рассказывает, что беда зреет в подземном храме Непроглядной Пучины. Древняя скверна, мерзкие водные элементали и культисты Сумеречного Молота собрались под приливами, маня древнее зло обратно в мир. Дже'неу рассчитывает, что герои спустятся под воду и сразятся с изначальным ужасом, пробужденным в затопленных залах."}},faq={{q="Кто выдает задание «Угроза из Глубин»?",a="Задание выдает Цунаман, находящийся в Когтистых горах. Он понимает, что союзникам на побережье Ясеневого леса нужно подкрепление, и направляет путешествующих искателей приключений из Орды к морю.",al={"quest giver","who starts trouble in the deeps","tsunaman","персонаж, выдающий задания","кто начинает угрозу из глубин","цунаман"}},{q="Где находится Дже'неу Санкри?",a="Дже'неу Санкри несет службу в форте Зорам'гар на Зорамском взморье, на дальнем западном побережье Ясеневого леса.",al={"where is je'neu","jeneu sancrea location","zoram'gar outpost","где дже'неу","дже'неу санкри местонахождение","форт зорам'гар"}},{q="Как добраться до форта Зорам'гар из Когтистых гор?",a="Путники могут отправиться на северо-восток через Утес Ветрорезов в Ясеневый лес или обойти с востока через Степи и войти в лес с юга. Из центра Ясеневого леса идите строго на запад до открытых вод Зорамского взморья.",al={"path to ashenvale","how to get to zoram strand","stonetalon to ashenvale route","путь в ясеневый лес","как добраться до зорамского взморья","маршрут из когтистых гор в ясеневый лес"}},{q="Какую беду расследует Дже'неу?",a="Дже'неу Санкри наблюдает за соседними руинами Непроглядной Пучины, где культисты и оскверненные водные существа пробуждают древние ужасы под поверхностью.",al={"what is happening at zoram strand","why does jeneu need help","что происходит на зорамском взморье","зачем дже'неу нужна помощь"}},{q="Какое задание следует за «Угрозой из Глубин»?",a="Разговор с Дже'неу Санкри ведет прямо к заданию «Сущность Аку'май», которое отправляет искателей приключений в Непроглядную Пучину за сапфировой сущностью элементаля.",al={"next quest","trouble in the deeps follow up","следующее задание","продолжение угрозы из глубин"}},{q="Почему путь через Ясеневый лес считается опасным?",a="Ясеневый лес — суверенные владения ночных эльфов, яростно сопротивляющихся любому вторжению Орды. Путники в лесу рискуют наткнуться на враждебных стражей и неуловимых нападающих из засады.",al={"ashenvale danger","night elf threat","опасность ясеневого леса","угроза ночных эльфов"}}},fp="20,265,22.435.0,24.425.0,24.420.1,41.195.0,32.121.0,51.230.0,37.161.0,40.162.0,57.194.0"}
P.entries["quest:6563"] = {n="Сущность Аку'май",s="Дже'неу Санкри из форта Зорам'гар заметил, что наги из Непроглядной Пучины добывают в пещерах мощные скопления сапфиров. Встревоженный их магическими свойствами и энергией стихии воды, шаман поручает авантюристам Орды забрать самоцветы, пока их не использовали во зло.",h="Дже'неу Санкри из форта Зорам'гар заметил, что наги из Непроглядной Пучины добывают в пещерах мощные...",kw={"ashenvale","blackfathom deeps","je'neu sancrea","naga","sapphire of aku'mai","trouble in the deeps","water spirits","zoram strand","ясеневый лес","непроглядная пучина","дже'неу санкри","наги","сапфиры аку'май","угроза из глубин","духи воды","зорамское взморье"},ang={["class:Shaman"]="Прочтение кристаллов Дже'неу Санкри выявляет беспокойных духов воды, заключенных в них, — тонкое предупреждение о том, что стихийные силы под храмом извращаются.",["faction:Horde"]="Плацдарм Орды в форте Зорам'гар опасен; не давая местным нагам получить сырую магическую силу, вы помогаете защитить прибрежный лагерь.",["race:Troll"]="Дже'неу Санкри — наблюдательный мистик из племени Черного Копья, который полагается на общение с духами и мудрость предков, чтобы справляться со странными угрозами Калимдора."},sec={{t="Угроза в глубинах",b="На окутанных туманом берегах Зорамского взморья шаман из племени Черного Копья Дже'неу Санкри наблюдает за древними руинами кальдораев, захваченными зловещими силами. В затопленных залах Непроглядной Пучины наги начали добывать яркие сапфировые образования, растущие на отсыревших стенах пещер. Чувствуя, что змеевидные захватчики стремятся подчинить эту непостоянную силу, Санкри хочет перехватить добычу, пока их замыслы не осуществились."},{t="Духи воды и тайная сила",b="Сапфиры Аку'май — гораздо больше, чем обычные самоцветы: они вибрируют стихийным резонансом и хранят в себе духов воды. В руках опытных чародеев такие проводники могли бы питать опасные тайные ритуалы или усиливать влияние теневой гидры Аку'май, чье темное присутствие пронизывает подземный храм. Забрав эти скопления, вы лишите нагов ценнейшего реагента и убережете побережье от неукротимой стихийной магии."}},faq={{q="Кто выдает это задание?",a="Задание выдает Дже'неу Санкри, шаман-тролль из племени Черного Копья, находящийся в форте Зорам'гар на Зорамском взморье на северо-западе Ясеневого леса.",al={"quest giver","who starts essence of akumai","jeneu sancrea location","персонаж, выдающий задание","кто начинает сущность аку'май","где дже'неу санкри"}},{q="Зачем нагам сапфиры Аку'май?",a="Их замысел до конца неясен, но сапфиры обладают мощной энергией стихии воды и сырой магической силой, что делает их крайне опасными реагентами для заклинаний нагов.",al={"why do naga want sapphires","what are the crystals for","sapphire purpose","зачем нагам сапфиры","для чего кристаллы","назначение сапфиров"}},{q="Где находятся скопления сапфиров?",a="Они покрывают стены и пол пещер во внешних туннелях и затопленных проходах Непроглядной Пучины, сразу за разрушенным подземным входом на Зорамском взморье.",al={"where to find sapphires","sapphire of akumai location","crystal spawns","где найти сапфиры","сапфир аку'май где","кристаллы где брать"}},{q="Кто такой Аку'май?",a="Аку'май — чудовищная трехглавая гидра, обитающая в глубине затопленных руин храма. Ее почитают культисты Сумеречного Молота, и ее боятся как излюбленной питомицы Древних богов.",al={"who is akumai","what is akumai","aku'mai","кто такой аку'май","что такое аку'май","аку'май"}},{q="Нужно ли для этого задания убивать боссов подземелья?",a="Нет. Скопления сапфиров растут на стенах пещер в первых затопленных туннелях, до встречи с главными боссами Непроглядной Пучины.",al={"do i need a full group","can i solo sapphires","boss requirement","нужна ли полная группа","можно ли в одиночку","требования к боссам"}},{q="Связано ли это задание с другими сюжетными линиями?",a="Да. Оно следует за заданием «Угроза из Глубин» и входит в расследование Дже'неу Санкри о растущей тьме и деятельности культистов в Непроглядной Пучине.",al={"quest chain","prerequisites","trouble in the deeps","цепочка заданий","предыдущие задания","угроза из глубин"}}},fp="22,287,22.461.0,30.455.0,21.143.0,46.181.0,38.169.0,16.183.0,52.144.0,47.168.0"}
P.entries["quest:6564"] = {n="Верность Древним богам",s="«Верность Древним богам» — задание Орды, которое начинается с находки отсыревшего послания у нагов в Непроглядной Пучине. Доставка записки Дже'неу Санкри в форт Зорам'гар раскрывает зловещий замысел ритуала в затопленных руинах Непроглядной Пучины.",h="«Верность Древним богам» — задание Орды, которое начинается с находки отсыревшего послания у нагов в...",kw={"aku'mai","allegiance","ashenvale","blackfathom deeps","damp note","je'neu sancrea","lorgus jett","old gods","wrathscale","zoram'gar outpost","аку'май","верность","ясеневый лес","непроглядная пучина","отсыревшая записка","дже'неу санкри","лоргус джетт","древние боги","наги","форт зорам'гар"},ang={["class:Shaman"]="Порабощение нагами духов воды в ритуальных кристаллах — тяжкое извращение естественного равновесия, требующее скорейшего исправления.",["faction:Horde"]="Найденная записка Лоргуса Джетта помогает защитить форт Зорам'гар от Сумеречного Молота и его союзников-нагов, угрожающих плацдарму Орды на западном побережье Ясеневого леса.",["race:Troll"]="Помогая сородичу из племени Черного Копья Дже'неу Санкри, вы разоблачаете древние космические сущности, возвращение которых грозило бы всем племенам Азерота."},sec={{t="Наспех нацарапанное заявление",b="Сражаясь с нагами Непроглядной Пучины, разведчики Орды находят отсыревшую смятую записку, написанную торопливым почерком. В ней содержатся указания жрицам нагов собирать кристаллы стихии воды. Это не просто грабеж: кристаллы собирают для призыва наг-аквамантов, чтобы собрать стихийные силы ради куда более мрачной цели."},{t="Шепот глубин",b="Найденные приказы раскрывают, что наги намерены использовать энергию стихий в кристаллах, чтобы умилостивить и полностью призвать Аку'май, чудовищную гидру, любимую древними космическими владыками. В записке дерзко провозглашается, что это возвестит возвращение «величайшей эпохи» мира — доисторического владычества Древних богов. Получив пергамент в форте Зорам'гар, мистик из племени Черного Копья Дже'неу Санкри называет автора заговора: культиста Сумеречного Молота Лоргуса Джетта."}},faq={{q="Что такое «Отсыревшая записка»?",a="«Отсыревшая записка» — найденные приказы, написанные культистом Сумеречного Молота Лоргусом Джеттом. В них жрицам нагов велено собирать кристаллы, наполненные стихиями, чтобы усилить их аквамантов и призвать чудовищного слугу Аку'май.",al={"damp note","what does the note say","note lore","отсыревшая записка","что сказано в записке","предыстория записки"}},{q="Кто такой Дже'неу Санкри?",a="Дже'неу Санкри — тролль из племени Черного Копья, провидец и ученый, находящийся в форте Зорам'гар в Ясеневом лесу. Представляя Служителей Земли, он исследует стихийные нарушения и древние угрозы, поднимающиеся из соседних руин Непроглядной Пучины.",al={"jeneu sancrea","who is jeneu","zoram outpost questgiver","дже'неу санкри","кто такой дже'неу","выдающий задания в зорам'гар"}},{q="Кто такой Лоргус Джетт?",a="Лоргус Джетт — человек-шаман из культа Сумеречного Молота, действующий в Непроглядной Пучине, где культисты заключили союз с нагами. Он руководит добычей стихийных кристаллов, чтобы усилить ритуалы нагов и пробудить темные древние ужасы.",al={"lorgus jett","who wrote the note","naga leader zoram","лоргус джетт","кто написал записку","предводитель нагов зорам"}},{q="Что такое Аку'май?",a="Аку'май — колоссальная трехглавая гидра, обитающая в затопленных глубинах Непроглядной Пучины. Тесно связанное с первозданной тьмой Древних богов, это существо почитают и культ Сумеречного Молота, и наги Непроглядной Пучины.",al={"akumai","who is akumai","aku'mai lore","аку'май","кто такой аку'май","аку'май предыстория"}},{q="Зачем наги собирают кристаллы воды?",a="Духи стихии воды, заточенные в кристаллах, дают нагам-аквамантам сырую силу. Высасывая эту стихийную магию, наги надеются умилостивить Аку'май и накопить достаточно силы, чтобы возвестить возвращение Древних богов.",al={"why naga crystals","elemental crystals naga","aquamancer crystals","зачем нагам кристаллы","стихийные кристаллы нагов","кристаллы аквамантов"}},{q="Куда ведет эта цепочка заданий?",a="Доставка записки Дже'неу Санкри ведет прямо к следующему поручению: выследить и убить Лоргуса Джетта, чтобы сорвать ритуальные планы культа в Непроглядной Пучине.",al={"what comes after allegiance to the old gods","allegiance to the old gods part 2","next quest","что после верности древним богам","верность древним богам часть 2","следующее задание"}}},fp="26,282,23.413.0,20.494.1,22.235.0,22.236.0,19.248.0,16.251.0,43.226.0,33.186.1"}
P.entries["quest:6565"] = {n="Верность Древним богам",s="«Верность Древним богам» — задание Орды: нужно уничтожить Лоргуса Джетта в глубинах Непроглядной Пучины. По поручению провидца из племени Черного Копья Дже'неу Санкри в форте Зорам'гар вам предстоит сорвать планы культистов Сумеречного Молота, стремящихся пробудить древние силы разрушения. Убийство Лоргуса наносит прямой удар по подрывной деятельности культа под побережьем Ясеневого леса.",h="«Верность Древним богам» — задание Орды: нужно уничтожить Лоргуса Джетта в глубинах Непроглядной Пучины.",kw={"allegiance to the old gods","ashenvale","blackfathom deeps","je'neu sancrea","lorgus jett","old gods","twilight's hammer","zoram'gar","верность древним богам","ясеневый лес","непроглядная пучина","дже'неу санкри","лоргус джетт","древние боги","сумеречный молот","зорам'гар"},ang={["class:Shaman"]="Сумеречный Молот стремится выпустить стихийную ярость на службе хаотичных Древних богов, поэтому для тех, кто поклялся хранить стихийное равновесие вместе со Служителями Земли, их истребление — первоочередная задача.",["faction:Horde"]="Убийство Лоргуса Джетта обезопасит окрестности форта Зорам'гар и защитит уединенный прибрежный лагерь Орды в Ясеневом лесу от коварных замыслов культистов.",["race:Troll"]="Помощь Дже'неу Санкри — дань мудрости уважаемого провидца из племени Черного Копья, который далеко от Островов Эха трудится ради защиты изначальных духов Азерота."},sec={{t="Угроза под фортом Зорам'гар",b="На взморье Ясеневого леса застава Орды в Зорам'гар настороженно следит за Непроглядной Пучиной. Затопленный храмовый комплекс стал рассадником темного колдовства, захваченным нагами, оскверненными тварями и фанатиками Сумеречного Молота в плащах. Дже'неу Санкри, провидец Служителей Земли на побережье, понимает, что культисты не чтят ни равновесие природы, ни духов земли. Они клянутся в верности Древним богам — чудовищным владыкам хаоса, побежденным в давние эпохи, чье злое касание все еще ощущается в забытых местах Азерота."},{t="Конец Лоргуса Джетта",b="Дже'неу поручает защитникам Орды проникнуть в подземные руины и выследить Лоргуса Джетта, важного предводителя культистов. Лоргус действует в глубине каменных коридоров между залами гигантской черепахи Гхаму-ра и водного элементаля барона Акваниса. Сам Дже'неу слишком слаб, чтобы идти в сырую тьму, поэтому убийство Лоргуса необходимо, чтобы прервать темные ритуалы, которые культист замышлял под волнами Ясеневого леса."},{t="Сдерживание хаоса",b="После смерти Лоргуса Джетта непосредственная ритуальная угроза побережью устранена, но Дже'неу признает, что Сумеречный Молот далеко не истреблен. Тихое проникновение культа в древние святыни говорит о более широкой, подкрадывающейся угрозе, цель которой — не меньше чем полное возвращение Древних богов. Для Орды в Зорам'гар смерть Лоргуса выигрывает ценное время в борьбе с врагом, скрывающимся в тенях мира."}},faq={{q="Кто такой Лоргус Джетт?",a="Лоргус Джетт — видный предводитель культистов Сумеречного Молота в Непроглядной Пучине. Он направляет ритуалы культа, призванные возвестить возвращение и владычество Древних богов.",al={"lorgus jett","who is lorgus","lorgus jett lore","лоргус джетт","кто такой лоргус","лоргус джетт предыстория"}},{q="Где в Непроглядной Пучине можно найти Лоргуса Джетта?",a="Лоргус Джетт обходит затопленные коридоры Непроглядной Пучины, в частности соединяющие залы между покоями Гхаму-ра и местом алтаря барона Акваниса.",al={"lorgus jett location","where is lorgus","find lorgus jett","где лоргус джетт","где лоргус","найти лоргуса джетта"}},{q="Кто такой Дже'неу Санкри?",a="Дже'неу Санкри — тролль-провидец из племени Черного Копья, связанный со Служителями Земли. Он находится в форте Зорам'гар на Зорамском взморье в Ясеневом лесу и следит за стихийными возмущениями и скверной в Непроглядной Пучине.",al={"je'neu sancrea","who gives allegiance to the old gods","jeneu","дже'неу санкри","кто выдает верность древним богам","дже'неу"}},{q="Почему Дже'неу заботит Сумеречный Молот?",a="Как провидец, стремящийся понять природу и стихийное равновесие, Дже'неу видит в Сумеречном Молоте смертельную угрозу. Культ служит Древним богам, хаотичным древним сущностям, чье возвращение разрушило бы гармонию мира.",al={"why fight twilight hammer","earthen ring old gods","зачем бороться с сумеречным молотом","служители земли древние боги"}},{q="Кто такие Древние боги?",a="Древние боги — первозданные существа хаоса и разрушения, правившие Азеротом в глубокой древности, пока не были побеждены и погребены. Культ Сумеречного Молота поклоняется им и замышляет разрушить их печати и вернуть их разрушительное владычество.",al={"old gods lore","who are old gods","creatures of chaos","предания о древних богах","кто такие древние боги","существа хаоса"}},{q="Почему Дже'неу Санкри не может сам убить Лоргуса Джетта?",a="Дже'неу признает, что слишком слаб, чтобы в одиночку встретить опасности Непроглядной Пучины, и полагается на способных защитников Орды, а сам следит за духовными и стихийными возмущениями из форта.",al={"why jeneu doesnt go","is jeneu weak","почему дже'неу не идет","слаб ли дже'неу"}}},fp="26,413,28.592.0,18.482.0,17.443.1,19.195.0,52.170.0,22.217.0,49.232.0,22.254.0,50.224.0"}
P.entries["quest:6571"] = {n="Поставка для Песни Войны",s="Поставка для Песни Войны — масштабное снабженческое задание Орды, которое выдает Локе Окарр на Заставе Расщепленного Дерева. Чтобы Лесозаготовки Песни Войны продолжали работу, нужно вернуть важное лесозаготовительное снаряжение, разбросанное по враждебным землям фурболгов и сатиров, а также получить грузы, прибывающие из далеких гоблинских портов.",h="Поставка для Песни Войны — масштабное снабженческое задание Орды, которое выдает Локе Окарр на Заставе...",kw={"ashenvale","booty bay","locke okarr","logging rope","pixel","saw blades","splintertree post","warsong lumber camp","warsong oil","warsong supplies","ясеневый лес","пиратская бухта","локе окарр","погрузочная веревка","пиксель","пилы","застава расщепленного дерева","лесозаготовки песни войны","масло песни войны","поставка для песни войны"},ang={["faction:Horde"]="Расширение Орды в Дуротаре целиком зависит от древесины, добываемой кланом Песни Войны. Возвращение этих инструментов напрямую укрепляет основу Оргриммара.",["profession:Engineering"]="Гоблинские детали этой поставки показывают, какая важная механическая цепочка снабжения нужна для вырубки древних лесов — от пил Пиксель до смазки для паровых двигателей.",["race:Orc"]="Чтить наследие клана Песни Войны в Ясеневом лесу — значит держать их топоры острыми, а лагеря снабженными, несмотря на постоянные нападения лесных обитателей."},sec={{t="Пилы должны вращаться",b="Кампания клана Песни Войны по заготовке древней древесины Ясеневого леса требует нескончаемого потока тяжелых инструментов. На своем аванпосту — Заставе Расщепленного Дерева — интенданты Орды постоянно сталкиваются с перебоями в снабжении. Локе Окарр отвечает за полное оснащение лесозаготовок, но местные поставки сорваны из-за набегов местных зверей и демонических культистов, и работа осталась без жизненно важного снаряжения."},{t="Разрозненная цепочка снабжения",b="Securing the needed equipment is an ordeal spanning much of Kalimdor and extending even across the sea. While circular saw blades await collection from the goblin courier Pixel right in Splintertree Post, the crate of heavy axes requires picking up a delivery from Wharfmaster Lozgil down in Booty Bay. The remaining essential goods must be ripped directly from enemy hands: sturdy logging ropes seized by hostile Foulweald and Thistlefur furbolgs, and barrels of Warsong machinery oil stolen by the satyrs of Night Run, Satyrnaar, and Xavian to fuel their profane rituals."}},faq={{q="Какие предметы входят в поставку для Песни Войны?",a="Locke Okarr needs four essential items: a shipment of Warsong Saw Blades held by the goblin Pixel, a crate of Warsong Axes shipped to Booty Bay, heavy Logging Rope looted by local furbolgs, and barrels of Warsong Oil stolen by Ashenvale's satyrs.",al={"warsong supplies list","what items needed","supplies needed","поставка для песни войны список","какие предметы нужны","что нужно собрать"}},{q="Кто такой Локе Окарр?",a="Локе Окарр — орк, находящийся на Заставе Расщепленного Дерева и отвечающий за координацию поставок материалов для Лесозаготовок Песни Войны. Под сильным давлением из-за необходимости избежать задержек он нанимает странствующих искателей приключений из Орды, чтобы вернуть разбросанные грузы.",al={"locke okarr lore","who gives warsong supplies","splintertree quest giver","локе окарр предания","кто выдает поставку для песни войны","персонаж на заставе расщепленного дерева"}},{q="Почему Орда получает снаряжение из Пиратской бухты?",a="Орда полагается на нейтральные торговые сети, такие как Картель Хитрая Шестеренка, чтобы ввозить специальные изделия, которые Дуротар и Степи не могут легко выпускать в больших количествах. Прочные лесорубные топоры, заказанные через гоблинов, проходят через морские торговые центры вроде Пиратской бухты, прежде чем попасть в Ясеневый лес.",al={"why booty bay","booty bay axe shipment","steamwheedle tools","почему пиратская бухта","топоры из пиратской бухты","инструменты хитрой шестеренки"}},{q="Зачем сатирам масло Песни Войны?",a="Сатиры, обитающие в таких руинах, как Сатирнаар, Ночная поляна и Ксавиан, используют украденное промышленное масло не для механизмов, а для темных, оскверненных обрядов, посвященных Пылающему Легиону и распространяющейся порче Оскверненного леса.",al={"satyr oil lore","why do satyrs have oil","warsong oil rituals","масло сатиров","зачем сатирам масло","ритуалы с маслом песни войны"}},{q="Какие фурболги украли погрузочную веревку?",a="Погрузочную веревку захватили из засады племена фурболгов Гиблой Чащи и Колючего Меха. Оба племени питают яростную враждебность к вырубке леса Ордой в Ясеневом лесу, считая эти земли своей территорией.",al={"who stole the rope","furbolg rope lore","foulweald thistlefur rope","кто украл веревку","веревка фурболгов","гиблая чаща колючий мех веревка"}},{q="Почему Лесозаготовки Песни Войны так важны для Орды?",a="Засушливые земли Дуротара почти не дают пригодной для строительства древесины. Клан Песни Войны был направлен в цветущие пограничные земли Ясеневого леса именно для заготовки огромных деревьев, необходимых для строительства Оргриммара и развития растущей военной инфраструктуры Орды.",al={"why harvest ashenvale","warsong lumber importance","orcs cutting trees","зачем рубить ясеневый лес","важность лесозаготовок песни войны","орки рубят деревья"}}},fp="16,290,25.415.0,27.573.0,39.246.0,19.252.0,51.303.0,35.229.0,38.197.0,53.269.0"}
P.entries["quest:6581"] = {n="Пилы Песни Войны",s="Пилы Песни Войны — поручение Орды, выполняемое на Заставе Расщепленного Дерева для лесозаготовительной кампании клана Песни Войны. Чтобы получить тяжелые пилы, привезенные из Кабестана, искателям приключений нужно заключить тайную сделку с курьером Пиксель, которая требует личной защиты, прежде чем отдать груз. Выполнив ее условие, вы получите важное оборудование, необходимое, чтобы лесопилки Орды в Ясеневом лесу продолжали работать.",h="Пилы Песни Войны — поручение Орды, выполняемое на Заставе Расщепленного Дерева для лесозаготовительной...",kw={"ashenvale","deadly blunderbuss","pixel","ratchet","splintertree post","warsong outriders","warsong saw blades","warsong supplies","ясеневый лес","смертоносный мушкетон","пиксель","кабестан","застава расщепленного дерева","пилы песни войны","поставка для песни войны"},ang={["faction:Horde"]="Лесозаготовки в Ясеневом лесу составляют жизненно важный каркас для расширения Оргриммара, поэтому каждая поставка оборудования необходима для выживания Орды в Калимдоре.",["profession:Engineering"]="Смертоносный мушкетон, который требует Пиксель, — обычное изделие умелых мастеров, показывающее, как гоблинская и людская инженерия обеспечивает снабжение на передовой.",["race:Orc"]="Клан Песни Войны поставил свою гордость на лесозаготовки в Ясеневом лесу под началом Громмаша Адского Крика; поддержание работы промышленных пил чтит неизменное присутствие клана в лесу."},sec={{t="Хитрая сделка курьера",b="Лесорубы Песни Войны в Ясеневом лесу целиком зависят от привозного тяжелого оборудования, чтобы справляться с древней древесиной глубокого леса. Пиксель благополучно доставила на Заставу Расщепленного Дерева партию специальных пил прямо из гоблинского порта Кабестан, но отдавать их просто так не собирается. В опасных глухих местах Ясеневого леса монеты стоят не так уж много, а личная безопасность — гораздо больше. Вместо золота Пиксель требует обменять тяжелые пилы на надежный Смертоносный мушкетон, чтобы защитить себя в опасных поездках по вражеской территории."},{t="Снабжение для военных усилий",b="Густые кроны Ясеневого леса высоко ценятся Ордой, которая страдает от острой нехватки древесины на засушливых равнинах Дуротара и в Степях. Однако рубка древних рощ-стражей быстро тупит обычные топоры, поэтому гоблинские промышленные лезвия необходимы. Груз Пиксель напрямую питает работу лесозаготовок Песни Войны, позволяя Орде и дальше строить аванпосты и боевые машины, несмотря на ожесточенное сопротивление ночных эльфов."}},faq={{q="Кто такая Пиксель и почему у нее пилы?",a="Пиксель — курьер, находящаяся сейчас на Заставе Расщепленного Дерева, которая привезла партию промышленных пил прямо из гоблинского порта Кабестан. Она удерживает груз, пока не получит надежное оружие для собственной защиты.",al={"who is pixel","pixie splintertree","saw blade courier","кто такая пиксель","пиксель застава расщепленного дерева","курьер с пилами"}},{q="Почему Пиксель хочет Смертоносный мушкетон вместо золота?",a="Путь через Степи и вглубь земель ночных эльфов в Ясеневом лесу крайне опасен. Зная об опасностях дороги, Пиксель ставит личную защиту выше денег и требует огнестрельное оружие инженерной работы, чтобы обезопасить свои поездки.",al={"why deadly blunderbuss","pixel gun trade","why want a gun","зачем смертоносный мушкетон","обмен пиксель на оружие","зачем ей ружье"}},{q="Почему эти пилы так важны для Орды?",a="Орде нужны огромные объемы древесины для строительства укреплений и боевых машин по всему Калимдору. Обычные режущие инструменты быстро изнашиваются о древние железные деревья Ясеневого леса, поэтому привозные механические пилы жизненно важны для лесозаготовительной техники клана Песни Войны.",al={"why are saw blades needed","warsong lumber importance","why warsong supplies","зачем нужны пилы","важность лесозаготовок песни войны","зачем поставка для песни войны"}},{q="Откуда изначально взялись пилы?",a="Пилы изготовили в Кабестане — нейтральном гоблинском порту на восточном побережье Степей — и оттуда отправили, а затем довезли по суше до Заставы Расщепленного Дерева.",al={"origin of saw blades","ratchet blades","where did saw blades come from","происхождение пил","пилы кабестан","откуда пилы"}},{q="Какое место это задание занимает в лесозаготовках Песни Войны?",a="Это задание — часть более широких усилий по сбору поставки для Песни Войны для лесозаготовок в Ясеневом лесу. Получение пил от Пиксель закрывает одно из ключевых требований снабжения, необходимых для поддержания лесозаготовок Орды.",al={"warsong supplies chain","warsong saw blades prerequisite","цепочка поставки для песни войны","пилы песни войны предыдущее задание"}},{q="Может ли кто-нибудь сделать оружие, которое хочет Пиксель?",a="Смертоносный мушкетон создают умелые инженеры из медных трубок, медных болтов, деревянного ложа и кожи, хотя курьеры и воины часто выменивают их на местных рынках или у других искателей приключений.",al={"how to get deadly blunderbuss","blunderbuss source","engineering gun","как получить смертоносный мушкетон","где взять мушкетон","инженерное ружье"}}},fp="18,421,25.614.0,24.461.0,50.244.0,57.244.0,51.275.0,46.173.0,58.237.0,39.210.0"}
P.entries["quest:66"] = {n="Легенда о Сталване",s="Легенда о Сталване начинается в Темнолесье с мрачного видения городской предсказательницы, Мадам Евы. Встревоженная предзнаменованием смерти своей внучки Алиссы, Ева обращается к картам и видениям в трансе и угадывает лишь одно оставшееся имя: Сталван. Чтобы распутать эту нить ужаса, она посылает путников изучить городские записи в Ратуше Темнолесья.",h="Легенда о Сталване начинается в Темнолесье с мрачного видения городской предсказательницы, Мадам Евы.",kw={"alyssa","clerk daltry","darkshire","death card","duskwood","madame eva","stalvan","town hall","алисса","клерк далтри","темнолесье","карта смерти","сумеречный лес","мадам ева","сталван","ратуша"},ang={["class:Priest"]="Жрецы, идущие по темным дорогам Темнолесья, часто прислушиваются к духовным предостережениям, поэтому жуткие предзнаменования смерти Мадам Евы становятся для них неотложным делом пастырского долга.",["faction:Alliance"]="Пока Сумеречный лес справляется без регулярной поддержки армии Штормграда, искатели приключений Альянса часто приходят на помощь городским старейшинам и защищают уязвимые семьи, такие как семья Мадам Евы."},sec={{t="Видение смерти",b="В вечном сумраке Сумеречного леса Мадам Ева служит провидицей Темнолесья: толкует знамения и гадает на картах встревоженным местным жителям. Резко проснувшись от ужасного потрясения, Ева обратилась к колоде для гадания и вытянула карту Смерти, связанную с ее юной внучкой Алиссой. Погрузившись в глубокий мрачный транс, чтобы пронзить мрак, она получила лишь одну подсказку: имя Сталван. Испуганная тем, что это знамение значит для ее семьи и города, она обращается к способным искателям приключений, чтобы они пошли по следу, пока не случилась беда."},{t="Расспросы в Ратуше",b="Ева знает, что для раскрытия правды о Сталване нужно изучить письменную историю Темнолесья. Она отправляет искателей приключений через площадь в Ратушу Темнолесья к Клерку Далтри, городскому хранителю книг учета и общественных архивов. Далтри ведает пыльными документами поселения, и только он может определить, был ли Сталван бывшим жителем, проезжим путником или чем-то гораздо более зловещим, похороненным в прошлом Сумеречного леса."}},faq={{q="Кто такая Мадам Ева?",a="Мадам Ева — гадалка и предсказательница, живущая в Темнолесье. Она использует карты и обряды транса, чтобы заглянуть в знамения будущего, и чувствует магические возмущения, перемещающиеся по Сумеречному лесу.",al={"madame eva","who is eva","darkshire fortune teller","мадам ева","кто такая ева","гадалка темнолесья"}},{q="Почему Мадам Еве нужна помощь?",a="Мадам Ева пережила ужасающее видение, указывающее, что ее внучке Алиссе грозит смертельная опасность. Карты выдали карту Смерти, а в трансе она узнала лишь имя «Сталван», поэтому она ищет помощи со стороны, чтобы разобраться с угрозой.",al={"why start stalvan","eva vision","why help eva","зачем начинать легенду о сталване","видение евы","почему помочь еве"}},{q="Кто такой Клерк Далтри?",a="Клерк Далтри — городской хранитель записей, находящийся в Ратуше Темнолесья. Он ведет городские книги учета, реестры и исторические документы, поэтому лучше всех подходит для вопросов о незнакомых именах.",al={"clerk daltry","daltry","who is town clerk","клерк далтри","далтри","кто городской клерк"}},{q="Что такое Ратуша Темнолесья?",a="Ратуша Темнолесья — административный центр города, в котором располагаются чиновники местной власти, исторические записи и командный состав Ночного Дозора.",al={"darkshire town hall","town hall duskwood","ратуша темнолесья","ратуша сумеречного леса"}},{q="Кто такая Алисса?",a="Алисса — юная внучка Мадам Евы, живущая в Темнолесье. Гадание Евы показало, что Алиссе грозит смертельное предзнаменование, связанное с неким Сталваном.",al={"alyssa","madame eva granddaughter","алисса","внучка мадам евы"}},{q="Куда ведет это расследование дальше?",a="Разговор с Клерком Далтри открывает городские записи и прошлые расследования и начинает обширное расследование в Сумеречном лесу и соседних землях, чтобы выяснить историю и судьбу Сталвана.",al={"stalvan next step","what does daltry say","сталван следующий шаг","что говорит далтри"}}},fp="21,363,17.562.0,22.470.0,18.192.0,30.244.0,20.208.0,28.162.0,14.163.0,40.181.0"}
P.entries["quest:6608"] = {s="«Больше учить нечему» — задание Орды, которое выдает наставник по рыбной ловле Оргриммара Лумак, когда рыболов перерос обычное обучение. Лумак отправляет своего искусного ученика к своему другу-человеку Нату Пэглу, который разбил лагерь на уединенном берегу Пылевых топей. Это переход от обычного обучения к непростому искусству рыбной ловли ранга искусника.",h="«Больше учить нечему» — задание Орды, которое выдает наставник по рыбной ловле Оргриммара Лумак, когда...",kw={"artisan fishing","dustwallow marsh","lumak","nat pagle","orgrimmar","theramore","you too good","рыбная ловля искусника","пылевые топи","лумак","нат пэгл","оргриммар","терамор","больше учить нечему"},ang={["faction:Horde"]="Это задание показывает, что за войной фракций отдельные личности порой завязывают дружбу между сторонами на почве безобидного ремесла и общих увлечений.",["race:Orc"]="Даже в воинственной твердыне Оргриммара Лумак доказывает, что терпение, хороший юмор и глубокое уважение к природе помогают оркам заводить друзей по ту сторону фронта."},sec={{t="Пределы Лумака",b="Лумак — главный наставник по рыбной ловле в Оргриммаре, в Аллее Чести, но даже терпеливый орк понимает, когда ученик сравнялся с ним в знании удочки и катушки. Не притворяясь, что ему есть чему еще научить, Лумак честно признает, что рыболов стал «слишком хорош» для обычных уроков. Чтобы достичь звания мастера, нужно выйти за городские стены и за пределы расовых границ."},{t="Неожиданная дружба",b="Несмотря на тлеющую вражду Орды и Альянса в Калимдоре, рыбалка часто сближает там, где пасует дипломатия. Лумак направляет путников к своему личному знакомому, Нату Пэглу, настойчиво подчеркивая, что человека нельзя ни обижать, ни есть. Нат разбил лагерь на островке к югу от острова Терамор в Пылевых топях и охотно игнорирует политику, пока рыба клюет."}},faq={{q="Кто посылает меня на это задание?",a="Лумак, наставник по рыбной ловле, живущий у воды в Аллее Чести в Оргриммаре, выдает вам это задание, когда ваше умение рыбной ловли достаточно высоко, чтобы продвинуться дальше уровня эксперта.",al={"who starts you too good","lumak quest giver","where to get you too good","кто дает больше учить нечему","лумак выдает задание","где взять больше учить нечему"}},{q="Где находится Нат Пэгл?",a="Нат Пэгл обосновался на островке у побережья Пылевых топей, к югу от человеческого поселения на острове Терамор.",al={"where is nat pagle","nat pagle location","find nat pagle","где нат пэгл","нат пэгл местонахождение","найти ната пэгла"}},{q="Почему у орка есть друг-человек?",a="Рыболовов по всему Азероту часто объединяет взаимное уважение, выходящее за рамки войны фракций. Лумак и Нат Пэгл сблизились исключительно на почве рыбалки, признав страсть друг друга вопреки жестокой вражде орков и людей.",al={"lumak and nat pagle friendship","why is nat pagle friends with an orc","дружба лумака и ната пэгла","почему нат пэгл дружит с орком"}},{q="Что будет, если я поговорю с Натом Пэглом?",a="Разговор с Натом Пэглом знакомит вас с его трудным испытанием для мастеров: вам придется пройти по всему Азероту, ловя редкую рыбу, прежде чем он лично продолжит ваше обучение.",al={"what does nat pagle teach","artisan fishing quest","чему учит нат пэгл","задание рыбная ловля искусника"}},{q="Безопасно ли Орде проходить через Терамор?",a="Нет, Терамор — город-крепость, строго охраняемый Альянсом. Искателям приключений из Орды приходится обходить город или идти вдоль берега, чтобы добраться до острова Ната и не навлечь гнев стражей Терамора.",al={"can horde go through theramore","getting to nat pagle as horde","может ли орда пройти через терамор","как добраться до ната пэгла за орду"}},{q="Почему Лумак сам не может учить меня дальше?",a="Лумак передал вам все, что знал. Истинное мастерство в рыбной ловле требует знаний Ната Пэгла, которого считают самым легендарным рыболовом известного мира.",al={"why lumak stops training","expert to artisan fishing horde","почему лумак перестает учить","рыбная ловля умелец искусник орда"}}},fp="13,350,14.413.0,22.406.0,27.165.0,27.118.0,36.227.0,39.176.0,44.197.0,41.164.0"}
P.entries["quest:6611"] = {n="Ступай в Прибамбасск!",s="«Ступай в Прибамбасск!» — путь поваров Орды, которые хотят выйти за пределы возможностей наставников своей столицы. По указанию Замджи в Оргриммаре начинающие повара отправляются на юг Калимдора, в Танарис, на поиски эксцентричного гоблина-мясника Могиля Быстроруба. Это задание знаменует переход к настоящему мастерству в кулинарном искусстве.",h="«Ступай в Прибамбасск!» — путь поваров Орды, которые хотят выйти за пределы возможностей наставников своей...",kw={"artisan cooking","cooking","dirge quikcleave","gadgetzan","orgrimmar","tanaris","valley of strength","zamja","кулинария искусника","кулинария","могиль быстроруб","прибамбасск","оргриммар","танарис","аллея силы","замджа"},ang={["faction:Horde"]="Оргриммар полагается на сторонних специалистов, например нейтральных гоблинов-поваров, чтобы поднять своих мастеров выше обычных племенных блюд.",["profession:Cooking"]="Это задание отмечает рубеж, когда повар перерастает обучение в столице и должен отправиться в опасные дикие земли, чтобы учиться у мастера."},sec={{t="Повар перерастает Оргриммар",b="В Тракте тролльша-повар Замджа кормит бесчисленных воинов и путников, идущих через красные каньоны Дуротара. Но когда усердный повар усваивает все рецепты и приемы Замджи, мастер признает свое поражение. Передав всю свою кулинарную магию, она отправляет опытного ученика на юг, в пески Танариса, признавая, что лишь настоящий знаток странного и экзотического мяса способен продвинуть талантливого повара дальше."},{t="Мясник в пустыне",b="Цель — Прибамбасск, паровой торговый центр, которым управляет Картель Хитрая Шестеренка. Там, в шумной городской таверне, трудится Могиль Быстроруб. Гоблин с необычным вкусом и полным отсутствием кулинарной брезгливости, Могиль известен по всему Калимдору тем, что готовит из чудовищной пустынной фауны — а порой и из обрезков кожи — сытные блюда, способные поддержать закаленных искателей приключений."}},faq={{q="Кто посылает вас в Прибамбасск?",a="Замджа, тролльша — наставник по кулинарии уровня эксперта, стоящая у костров для готовки в Тракте в Оргриммаре, дает это задание поварам, освоившим все, что она знает.",al={"quest giver","who starts this","zamja quest","персонаж, выдающий задания","кто дает это задание","задание замджи"}},{q="Почему Замджа отправляет вас прочь?",a="Замджа исчерпала все рецепты и кулинарные приемы, которым могла научить. Чтобы достичь ранга искусника в кулинарии, она направляет перспективных поваров к Могилю Быстрорубу в Танарисе — эксцентричному знатоку, известному умением готовить съедобные блюда из самых скудных пустынных ингредиентов.",al={"why gadgetzan","why dirge quikcleave","cooking master","почему прибамбасск","почему могиль быстроруб","мастер кулинарии"}},{q="Кто такой Могиль Быстроруб?",a="Могиль Быстроруб — гоблин-мясник и наставник по кулинарии ранга искусника, которого можно найти в таверне Прибамбасска. Он славится крутым нравом, странными теориями о питании — например, будто белок есть в старых кожаных сапогах, — и мастерством в изысканной экзотической кухне дикой природы.",al={"who is dirge","dirge gadgetzan","кто такой могиль","могиль прибамбасск"}},{q="Обязательно ли это задание для изучения кулинарии ранга искусника?",a="Нет. Это задание лишь направляет игроков Орды в Танарис. Повар с достаточным умением может сразу отправиться в Прибамбасск и поговорить с Могилем Быстрорубом, не получая направления от Замджи.",al={"do i need this quest","breadcrumb cooking","is it mandatory","нужно ли это задание","кулинария направление","обязательно ли"}},{q="Где находится Прибамбасск?",a="Прибамбасск — обнесенный стеной пустынный поселок Картеля Хитрая Шестеренка в северных песках Танариса, далеко на юге континента Калимдор, ниже Тысячи Игл.",al={"gadgetzan location","where is dirge","прибамбасск местонахождение","где могиль"}},{q="Учится ли Замджа чему-нибудь, когда вы возвращаетесь?",a="Хотя Замджа дерзко требует, чтобы вы вернулись и научили ее, когда станете главным поваром на районе, она остается наставником-экспертом в Оргриммаре и следит за своими кострами для следующих поколений путников.",al={"does zamja learn cooking","teach zamja","учится ли замджа кулинарии","научить замджу"}}},fp="20,356,25.422.0,25.395.0,27.158.0,29.269.0,24.267.0,48.224.0,27.179.0,51.206.0"}
P.entries["quest:6621"] = {n="Король Гиблой Чащи",s="«Король Гиблой Чащи» — военная операция Орды по поручению Каранга Амаккара из форта Зорам'гар. Чтобы усмирить порченых фурболгов Гиблой Чащи к юго-востоку от Астранаара, чемпионы Орды водружают боевое знамя прямо на священном тотемном кургане племени, вызывая и убивая его вождя, вождя Мургута.",h="«Король Гиблой Чащи» — военная операция Орды по поручению Каранга Амаккара из форта Зорам'гар.",kw={"ashenvale","foulweald","furbolg","greenpaw village","karang amakkar","murgut","totem mound","zoram'gar","ясеневый лес","гиблая чаща","фурболг","деревня зеленой лапы","каранг амаккар","мургут","тотемный курган","зорам'гар"},ang={["class:Shaman"]="Искаженные тотемы и агрессия племени Гиблой Чащи отражают сохраняющийся духовный разлад, терзавший местные племена Ясеневого леса после вторжения Пылающего Легиона.",["faction:Horde"]="Каранг Амаккар демонстрацией военного превосходства запугивает враждебные племена Ясеневого леса, обеспечивая безопасный проход для караванов снабжения Орды по центральным тропам.",["race:Orc"]="Водрузить знамя, чтобы вызвать вражеского вождя на поединок, — классическая орочья война: упор на силу и решительное столкновение, а не на долгие стычки."},sec={{t="Демонстрация силы",b="Пока ночные эльфы пытаются сдержать порченые местные племена Ясеневого леса, Орда подходит к угрозе с расчетливой агрессией. Каранг Амаккар из форта Зорам'гар понимает, что племя Гиблой Чащи, возможно, и не равно по численности северному племени Колючего Меха, но его необузданная свирепость — скрытая опасность для южной дороги. Не дожидаясь засад на патрули Орды, Каранг приказывает упреждающе продемонстрировать военное превосходство, чтобы сломить волю племени."},{t="Осквернение и вызов",b="Удар нацелен на Деревню Зеленой Лапы к северо-востоку от Озера Мистраль. Каранг изготавливает племенное боевое знамя, которое нужно вбить прямо в центр тотемного кургана Гиблой Чащи, — непростительное оскорбление предков-духов и гордости племени. Защитники-фурболги в отчаянии бросаются на курган, чтобы сорвать оскорбительное знамя, и вынуждают вождя Мургута выйти и защищать свою честь в открытом бою. Захват личного тотема Мургута разрушает их руководство и утверждает превосходство Орды в этих землях."}},faq={{q="Кто приказывает убить вождя Мургута?",a="Каранг Амаккар, орк из форта Зорам'гар на западном побережье Ясеневого леса, отдает это задание после изучения соседних фурболгов племени Колючего Меха.",al={"quest giver king of the foulweald","who gives king of the foulweald","karang amakkar quest","персонаж, выдающий задание король гиблой чащи","кто дает король гиблой чащи","задание каранга амаккара"}},{q="Где находится Деревня Зеленой Лапы?",a="Деревня Зеленой Лапы лежит к юго-востоку от поселения ночных эльфов Астранаар, к северо-востоку от Озера Мистраль, чуть южнее главной восточной дороги Ясеневого леса.",al={"where is greenpaw village","foulweald location","where to plant karang banner","где деревня зеленой лапы","гиблая чаща местонахождение","где установить знамя каранга"}},{q="Зачем Орда водружает знамя на тотемном кургане?",a="Водружение Знамени Каранга прямо на священном тотемном кургане племени — намеренная провокация. Осквернение священной земли заставляет племя Гиблой Чащи яростно напасть и вынуждает вождя Мургута открыто сражаться, защищая свое положение.",al={"why place banner","totem mound banner purpose","why challenge murgut","зачем ставить знамя","назначение знамени на кургане","зачем вызывать мургута"}},{q="Кто такие фурболги Гиблой Чащи?",a="Племя Гиблой Чащи — одно из нескольких племен фурболгов Ясеневого леса, впавших в безумие и порчу после Третьей войны. Хотя оно малочисленнее племени Колючего Меха, оно остается свирепым и враждебным к чужакам.",al={"what are the foulweald","foulweald tribe lore","who is chief murgut","что такое гиблая чаща","предания племени гиблой чащи","кто такой вождь мургут"}},{q="Что дает возвращение Тотема Мургута?",a="Доставка тотема вождя Мургута в форт Зорам'гар доказывает поражение вождя. Лишившись предводителя и с оскверненным священным курганом, уцелевшие фурболги Гиблой Чащи устрашены и избегают дальнейших столкновений с Ордой.",al={"murgut totem purpose","what happens after murgut dies","назначение тотема мургута","что будет после смерти мургута"}},{q="Как это задание связано с прежними расследованиями о фурболгах?",a="Это задание непосредственно продолжает задание «Между молотом и Колючим Мехом». Разобравшись с северным племенем Колючего Меха, Каранг обращает внимание на юг, чтобы упредить удар и сокрушить племя Гиблой Чащи, пока оно не начало согласованные набеги.",al={"between a rock and a thistlefur connection","prerequisite king of the foulweald","связь с between a rock and a thistlefur","предыдущее задание король гиблой чащи"}}},fp="21,312,15.490.0,25.511.0,37.180.0,34.158.0,53.240.0,31.222.0,47.227.0,64.229.0"}
P.entries["quest:6625"] = {n="Травматологи Альянса",s="«Травматологи Альянса» — вызов, направляющий опытных полевых медиков на Остров Терамор в Пылевых топях. Инструкторы первой помощи в столицах Альянса приглашают умелых целителей учиться у доктора Густава ван Склиффа, главного врача элитного медицинского корпуса Альянса.",h="«Травматологи Альянса» — вызов, направляющий опытных полевых медиков на Остров Терамор в Пылевых топях.",kw={"alliance trauma","dustwallow marsh","first aid","ironforge","nissa firestone","theramore","triage","vanhowzen","травматологи альянса","пылевые топи","первая помощь","стальгорн","нисса огневик","терамор","сортировка","ван склифф"},ang={["faction:Alliance"]="Травматологи Альянса обеспечивают бойцов на передовой по всему Калимдору и Восточным королевствам умелыми полевыми медиками, способными стабилизировать тяжелые ранения под огнем.",["race:Dwarf"]="Наставники вроде Ниссы Огневик в Стальгорне охотно отбирают перспективных целителей из Великой кузни, чтобы те представляли лучшие медицинские таланты Альянса в Тераморе."},sec={{t="Зов на передовую",b="Когда медик осваивает основные приемы, которым учат в великих городах Альянса, местные наставники уже мало что могут ему дать. Об тех, кто проявил исключительные способности в обращении с иглой, тканью и сортировкой, сообщают непосредственно доктору Густаву ван Склиффу. Из пограничной крепости на Острове Терамор он руководит Травматологами Альянса — организацией, призванной спасать жизни в самых жестоких зонах боевых действий Калимдора и за его пределами."},{t="Дорога в Терамор",b="Наставники вроде Ниссы Огневик в Стальгорне считают личный вызов от ван Склиффа исключительной привилегией. Остров Терамор постоянно страдает от региональных угроз, стычек и суровой природы, поэтому туда стабильно поступают тяжелораненые солдаты. Чтобы добраться до клиники ван Склиффа, нужно долгое морское путешествие в Пылевые топи, где лишь самые хладнокровные полевые хирурги могут надеяться выдержать его строгие требования к сортировке."}},faq={{q="Что такое Травматологи Альянса?",a="Травматологи Альянса — элитное медицинское подразделение, отвечающее за передовую полевую медицину и экстренную сортировку во всем Альянсе. Корпус возглавляет главный врач Густав ван Склифф и занимается тяжелыми ранениями, которые не под силу обычной полевой перевязке.",al={"alliance trauma lore","who are alliance trauma","травматологи альянса предания","кто такие травматологи альянса"}},{q="Кто посылает вас на это задание?",a="Инструкторы первой помощи Альянса, например Нисса Огневик в Великой кузне Стальгорна, направляют перспективных целителей, как только те достигают вершины обычной гражданской подготовки.",al={"who gives alliance trauma","ironforge first aid quest giver","кто дает травматологов альянса","персонаж, выдающий задание первой помощи в стальгорне"}},{q="Куда нужно отправиться?",a="Вам нужно отправиться в портовую крепость людей на Острове Терамор, расположенную у восточного побережья Пылевых топей на континенте Калимдор.",al={"where is vanhowzen","alliance trauma destination","где ван склифф","цель травматологов альянса"}},{q="Кто такой доктор Густав ван Склифф?",a="Доктор Густав ван Склифф — главный врач Травматологов Альянса. Он работает в военной клинике Терамора и считается одним из ведущих специалистов Альянса по неотложной медицине и хирургической сортировке.",al={"gustaf vanhowzen","chief physician vanhowzen","густав ван склифф","главный врач ван склифф"}},{q="Что происходит после встречи с доктором ван Склиффом?",a="По прибытии в Терамор ван Склифф подвергает кандидатов напряженной практической проверке сортировки: нужно спасти волны умирающих солдат, прежде чем их допустят в высшие ряды полевой медицины.",al={"what comes after alliance trauma","triage quest next","что после травматологов альянса","следующее задание сортировка"}},{q="Почему клиника находится в Тераморе, а не в Штормграде или Стальгорне?",a="Терамор — действующий пограничный гарнизон, окруженный враждебными болотами, опасными зверями и спорными территориями. Постоянный приток тяжелораненых делает его идеальной площадкой для интенсивного обучения травматологии.",al={"why theramore clinic","why dustwallow for trauma","почему клиника в тераморе","почему пылевые топи для травматологии"}}},fp="15,307,19.448.0,21.468.0,24.252.0,28.178.0,28.143.0,31.221.0,49.217.0,71.240.0"}
P.entries["quest:6627"] = {n="Испытание знаний",s="«Испытание знаний» — проверка ума и исторической памяти, которую устраивает отшельник Брауг Тусклый Дух в Когтистых горах. Добыв древний том «Наследие Аспектов», путники должны показать знание древней истории, ответив на вопрос Брауга. Тех, кто не усвоил текст, внезапно изгоняют в другую часть Калимдора.",h="«Испытание знаний» — проверка ума и исторической памяти, которую устраивает отшельник Брауг Тусклый Дух в...",kw={"aspects","braug dimspirit","earth warder","neltharion","stonetalon","taurajo","test of faith","weathered nook","аспекты","брауг тусклый дух","хранитель земли","нелтарион","когтистые горы","таурахо","испытание веры","угол семи ветров"},ang={["class:Mage"]="Маги сочтут защитное заклинание телепортации Брауга одновременно впечатляющим и карающим: оно показывает, что отшельники Когтистых гор владеют древней магией и наказывают небрежных ученых.",["faction:Horde"]="Испытания Орды в Калимдоре требуют не только грубой силы: от воинов и шаманов ждут понимания древних шрамов и мощи драконов, сформировавших континент.",["race:Tauren"]="Это испытание воплощает уважение таурен к мудрости предков и древней истории: молодые защитники не должны слепо идти вперед, не зная равновесия мира."},sec={{t="Испытание мудрости",b="Испытание знаний — часть более широкой цепочки испытаний, начатой Дорном Вольным Ловчим в Углу Семи Ветров. Оно переносит акцент с боевого выживания и слепого доверия на понимание древнего прошлого мира. Брауг Тусклый Дух, живущий среди скал Когтистых гор, требует, чтобы искатели добыли древние тексты и по-настоящему усвоили заключенные в них знания."},{t="Наследие Аспектов",b="Урок посвящен созданию и разделению Аспектов драконов, в частности роковому союзу, заключенному задолго до Великого Раскола. Брауг проверяет, что искатель помнит о Хранителе Земли Нелтарионе, чье погружение в безумие и предательство изменило облик Азерота. Тем, кто не чтит историю, путь мудрости закрыт."},{t="Цена догадок",b="Брауг не терпит праздных догадок. Искателя, давшего неверный ответ, мистическим образом изгоняют, и он оказывается за много миль оттуда, в Лагере Таурахо на юге Степей. Чтобы вернуть себе положение, нужно проделать долгий путь обратно в Когтистые горы и во второй раз предстать перед пристальным взором отшельника."}},faq={{q="Каков ответ на вопрос Брауга Тусклого Духа?",a="Брауг спрашивает о личности Хранителя Земли, описанного в томе «Наследие Аспектов». Правильный ответ — Нелтарион, Черный Аспект, который позже обратился против собратьев-драконов.",al={"braug question answer","test of lore answer","legacy of the aspects question","ответ на вопрос брауга","ответ испытание знаний","вопрос наследие аспектов"}},{q="Что будет, если ответить неверно?",a="Если назвать Браугу неверное имя, вас немедленно изгонят магией и перенесут прямо в Лагерь Таурахо в Степях. Чтобы повторить испытание, придется пройти весь путь обратно к его жилищу в Когтистых горах.",al={"wrong answer test of lore","failed test of lore","teleported to taurajo","неверный ответ испытание знаний","провал испытания знаний","телепорт в таурахо"}},{q="Кто такой Брауг Тусклый Дух?",a="Брауг Тусклый Дух — старый отшельник, живущий в Когтистых горах. Он проводит для Орды проверки знаний и преданий, продолжая цепочку духовных испытаний, начатую в Тысяче Игл.",al={"braug dimspirit","who gives test of lore","брауг тусклый дух","кто дает испытание знаний"}},{q="Как это связано с испытаниями в Тысяче Игл?",a="Цепочка началась с Дорна Вольного Ловчего в Углу Семи Ветров в Тысяче Игл с «Испытания веры». Дорн проверяет физическое и духовное доверие, а затем отправляет достойных посвященных по Калимдору, чтобы другие мудрые старейшины проверили их ум, решимость и силу.",al={"dorn plainstalker connection","test of faith chain","дорн вольный ловчий","цепочка испытание веры"}},{q="О какой книге Брауг задает вопросы?",a="Вопросы проверяют понимание «Наследия Аспектов» — древнего трактата о благословении титанами пяти великих Аспектов драконов, призванных охранять Азерот.",al={"what book braug","legacy of the aspects","какая книга у брауга","наследие аспектов"}},{q="Куда ведет эта цепочка заданий дальше?",a="Успешный ответ на вопросы Брауга об Аспектах драконов ведет к дальнейшим исследовательским испытаниям по древней истории, где искателям нужно обшаривать дальние земли в поисках утраченных записей и знаний предков.",al={"what is after test of lore","next quest in test of lore","что после испытания знаний","следующее задание испытания знаний"}}},fp="12,361,17.381.0,21.371.0,22.317.1,49.193.0,39.226.0,23.203.0,56.265.0,38.171.0,38.192.0"}
P.entries["quest:6628"] = {n="Испытание знаний",s="Это испытание — интеллектуальная проверка в более широкой череде духовных испытаний, начинающихся в Тысяче Игл. Обыскав мир в поисках исторических текстов, посвященные являются к Парквелу Финталласу в Подгороде, чтобы доказать, что понимают мрачные страницы истории, сформировавшие Азерот.",h="Это испытание — интеллектуальная проверка в более широкой череде духовных испытаний, начинающихся в Тысяче...",kw={"dorn plainstalker","lich king","mark of shame","nerzhul","parqual fintallas","test of lore","thousand needles","undercity","weathered nook","дорн вольный ловчий","король-лич","метка позора","нер'зул","парквел финталлас","испытание знаний","тысяча игл","подгород","угол семи ветров"},ang={["faction:Horde"]="Испытание укрепляет связи между племенами Калимдора и королевством под Лордероном, напоминая героям, что мудрость для выживания Орды так же важна, как и грубая сила.",["race:Tauren"]="Это испытание, идущее от традиций старейшин, побуждает путешественников-тауренов узнать мрачную историю их северных союзников, Отрекшихся, и мира за пределами Калимдора.",["race:Undead"]="Тема испытания затрагивает самую суть самосознания Отрекшихся: трагедию создания Нер'зула и возникновение проклятия, что сковывало их, пока Сильвана не разорвала хватку Короля-лича."},sec={{t="Испытание знаний",b="Хотя многие испытания Орды проверяют воинскую силу или выносливость, Испытание знаний требует усердия ученого. Путь начинается с духовных упражнений Дорна Вольного Ловчего в Углу Семи Ветров и уводит кандидатов далеко от изрезанных ветрами каньонов Тысячи Игл в сумрачные залы Подгорода. Экзаменатором выступает Парквел Финталлас, строго проверяющий знание истории."},{t="Происхождение Плети",b="Чтобы удовлетворить Парквела, посвященный должен изучить «Истоки угрозы нежити» — текст о проклятом происхождении Плети в Лордероне. Главный вопрос экзамена касается происхождения существа, правящего на Ледяном Троне: бывшего старейшины-шамана Нер'зула, чью сущность Пылающий Легион превратил в Короля-лича. Знание этой мрачной родословной считается необходимым для понимания существования Отрекшихся и опасностей, грозящих Калимдору и Восточным королевствам."}},faq={{q="Каков ответ на вопрос Парквела?",a="Парквел Финталлас спрашивает, как звали Короля-лича изначально. Правильный ответ — Нер'зул, древний орк-шаман, чей дух был прикован к Ледяному Трону.",al={"lich king answer","parqual question","test of lore answer","ответ король-лич","вопрос парквела","ответ испытание знаний"}},{q="Что будет, если ответить неправильно?",a="Неверный ответ накладывает на вас ослабляющий эффект «Метка позора», и придется дождаться окончания штрафа, прежде чем Парквел позволит вам пройти экзамен снова.",al={"mark of shame","wrong answer test of lore","метка позора","неверный ответ испытание знаний"}},{q="Где начинается эта цепочка заданий?",a="Все испытание начинается с Дорна Вольного Ловчего в Углу Семи Ветров, среди высоких скал Тысячи Игл.",al={"where does test of lore start","dorn plainstalker questline","где начинается испытание знаний","цепочка заданий дорна вольного ловчего"}},{q="Где находится Парквел Финталлас?",a="Парквел Финталлас обитает в Подгороде, среди подземных библиотек и коридоров Отрекшихся, где проверяет будущих учеников.",al={"find parqual","parqual fintallas location","найти парквела","где парквел финталлас"}},{q="На каком тексте основано это испытание?",a="Испытание основано на томе «Истоки угрозы нежити», где рассказывается о происхождении Чумы нежизни и создании Короля-лича.",al={"which book for test of lore","beginnings book","какая книга для испытания знаний","книга истоки"}},{q="Почему задание из Тысячи Игл отправляет игроков в Подгород?",a="Испытания тауренов призваны проверить все стороны искателя приключений. Чтобы проверить знания, кандидатов отправляют за море на поиски ученых записей, сохранившихся в руинах Лордерона.",al={"why go to undercity","thousand needles undercity","зачем идти в подгород","тысяча игл подгород"}}},fp="12,297,20.430.0,21.495.1,41.162.0,46.165.0,34.130.0,35.155.0,33.152.0,60.208.0"}
P.entries["quest:6629"] = {n="Убить Грундига Темное Облако",s="Убить Грундига Темное Облако — задание Орды, которое выдает Макаба Плоское Копыто на юго-восточной тропе в Когтистых горах. После расправы над разбойниками и наемниками Зловещего Тотема Макаба велит вам сразить предводителя, разорившего его дом, — Грундига Темное Облако. Гибель Грундига и его головорезов приносит справедливое возмездие за разоренное поселение.",h="Убить Грундига Темное Облако — задание Орды, которое выдает Макаба Плоское Копыто на юго-восточной тропе в...",kw={"brute","darkcloud","flathoof","grimtotem","grundig","makaba","post","stonetalon","головорез","темное облако","плоское копыто","зловещий тотем","грундиг","макаба","застава","когтистые горы"},ang={["faction:Horde"]="Когтистые горы — ключевая территория для расширения Орды в Калимдоре, а агрессивные вожди Зловещего Тотема вроде Грундига угрожают путям снабжения, соединяющим Степи с Приютом у Солнечного Камня.",["race:Tauren"]="Клан Зловещего Тотема продолжает сеять раздор среди тауренов, и резня Грундига показывает, что единству под знаменем Орды всегда будет противостоять их беспощадный экстремизм."},sec={{t="Мясник тропы",b="Макабе Плоскому Копыту удалось пережить внезапное жестокое нападение на его поселение на тропе в Когтистых горах, но его горе все еще свежо. Испытав вашу силу на пехотинцах Зловещего Тотема, он указывает вам на зачинщика кровопролития — Грундига Темное Облако. В отличие от простых налетчиков, Грундиг командует преданным отрядом головорезов и возглавил резню, сровнявшую деревню с землей."},{t="Удар по Заставе Зловещего Тотема",b="Грундиг разбил лагерь на Заставе Зловещего Тотема, дальше по горной дороге на западе. Чтобы отомстить за сородичей Макабы и защитить перевал от нового насилия, путникам нужно подняться в крепость, прорубиться через ближний круг головорезов Темного Облака и покончить с самим Грундигом, пока его отряд не обрушился на другие беззащитные лагеря."}},faq={{q="Кто такой Грундиг Темное Облако?",a="Грундиг Темное Облако — свирепый командир Зловещего Тотема, обосновавшийся на Заставе Зловещего Тотема на юго-востоке Когтистых гор. Он лично спланировал и возглавил жестокое нападение, уничтожившее деревню Макабы Плоского Копыта.",al={"grundig darkcloud","who is grundig","grimtotem leader","грундиг темное облако","кто такой грундиг","вождь зловещего тотема"}},{q="Где найти Грундига Темное Облако?",a="Грундиг Темное Облако находится на Заставе Зловещего Тотема, расположенной на горной тропе к западу от лагеря Макабы Плоского Копыта, неподалеку от границы Степей.",al={"grundig location","where is grundig","grimtotem post location","где грундиг","где найти грундига","застава зловещего тотема"}},{q="Почему Макаба Плоское Копыто дает это задание?",a="Макаба видел, как Зловещий Тотем перебил его сородичей и разорил дом. Уже отомстив их разбойникам и наемникам, он просит голову главаря, Грундига Темное Облако, чтобы обрести истинное завершение и возмездие.",al={"why kill grundig","makaba story","makaba revenge","зачем убивать грундига","история макабы","месть макабы"}},{q="Почему Зловещий Тотем нападает на мирные поселения здесь?",a="Клан Зловещего Тотема яростно презирает остальные племена тауренов, особенно тех, кто стал союзником Орды или выбрал более мягкие пути. Засады, набеги и грубая жестокость — их обычные средства, чтобы изгнать соперничающие кланы с земель, которыми они хотят владеть.",al={"why grimtotem attack","grimtotem hostility","почему нападает зловещий тотем","враждебность зловещего тотема"}},{q="Что будет после убийства Грундига Темное Облако?",a="Убийство Грундига Темное Облако и его головорезов завершает короткую цепочку мести Макабы Плоского Копыта. Со смертью мясника Макаба наконец может оплакать свою деревню, зная, что справедливость восторжествовала.",al={"what next after grundig","flathoof chain continuation","что дальше после грундига","продолжение цепочки макабы"}},{q="Какое задание нужно выполнить перед этим?",a="Сначала нужно выполнить задание «Отомсти за мою деревню», в котором Макаба Плоское Копыто проверяет вашу решимость, веля сразить разбойников и наемников Зловещего Тотема, расположившихся неподалеку к западу.",al={"prereq kill grundig","quest before grundig","предыдущее задание грундиг","задание перед грундигом"}}},fp="22,363,23.418.0,24.351.0,25.209.0,37.160.0,47.245.0,58.260.0,43.191.0,45.178.0"}
P.entries["quest:6641"] = {n="Ворша Хлестунья",s="Ворша Хлестунья — свирепая гидра, терроризирующая оплот Орды, Форт Зорам'гар, на побережье Ясеневого леса. Почитая ярость этого существа, местные наги держат на прибрежном острове жертвенную жаровню в ее честь. Погасив это священное пламя, герои Орды разъярят Воршу и выманят ее на берег, чтобы положить конец ее хищным нападениям.",h="Ворша Хлестунья — свирепая гидра, терроризирующая оплот Орды, Форт Зорам'гар, на побережье Ясеневого леса.",kw={"ashenvale","brazier","hydra","muglash","naga","vorsha","zoram strand","zoram'gar","ясеневый лес","жаровня","гидра","муглаш","нага","ворша","зорамское взморье","зорам'гар"},ang={["faction:Horde"]="Оборона Форта Зорам'гар необходима, чтобы удерживать северный логистический плацдарм в Ясеневом лесу, где пути снабжения постоянно подвергаются нападениям.",["race:Orc"]="Орки вроде Муглаша не прячутся за наспех сколоченными частоколами, а предпочитают выходить в прибой и встречать хищных чудовищ лицом к лицу."},sec={{t="Ужас из глубин",b="Форт Зорам'гар стоит на узкой полосе побережья на северо-западе Ясеневого леса, постоянно подвергаясь осаде враждебных зверей, ночных эльфов и змеевидных захватчиков. Среди самых разрушительных угроз Зорамского взморья — Ворша Хлестунья, гигантская гидра, известная жестокими нападениями на форт без всякого повода. Чудовище выходит из прибоя, сокрушает укрепления, убивает воинов и скрывается в глубоких водах."},{t="Жаровня нага",b="Местные наги не просто терпят прожорливую гидру — они почитают ее хищную злобу. На скалистом выступе у берега змеевидные порождения зла постоянно поддерживают огонь в жертвенной жаровне в дар Ворше. Муглаш, орк, решивший прекратить постоянные нападения на форт, понял, что осквернение этого ритуального пламени заставит чудовище в ярости подняться на поверхность, и защитники смогут заманить его в засаду, а не ждать очередной внезапной бойни."}},faq={{q="Кто такая Ворша Хлестунья?",a="Ворша Хлестунья — свирепая огромная гидра, обитающая в водах у Зорамского взморья. Она часто нападает на Форт Зорам'гар без повода, разрушая защитные сооружения и убивая людей Орды.",al={"vorsha","what is vorsha","vorsha hydra","ворша","кто такая ворша","гидра ворша"}},{q="Почему наги почитают Воршу?",a="Наги Зорамского взморья уважают Воршу за ее неукротимую свирепость и разрушительный аппетит. Они держат на острове у берега жаровню, горящую в честь ее злобной натуры, и видят в чудовище воплощение дикой ярости побережья.",al={"why naga like hydra","vorsha naga brazier","why worship vorsha","почему наги любят гидру","ворша наги жаровня","почему поклоняться ворше"}},{q="Как выманить Воршу на бой?",a="Муглаш ведет штурм острова, где наги поддерживают огонь в жаровне Ворши. Погасив священное пламя, вы глубоко разъярите и стражей-нагов, и саму гидру, и Ворша поднимется из моря, чтобы отомстить.",al={"how to summon vorsha","how do you call vorsha","brazier island vorsha","как призвать воршу","как вызвать воршу","остров жаровни ворша"}},{q="Кто такой Муглаш?",a="Муглаш — орк, служащий в Форте Зорам'гар. Устав жить в страхе перед беспричинными набегами Ворши на побережье, он придумал план погасить ритуальную жаровню нагов и сразиться с чудовищем вместе с надежными союзниками.",al={"who is muglash","muglash orc","zoramgar muglash","кто такой муглаш","орк муглаш","зорам'гар муглаш"}},{q="Почему Форт Зорам'гар уязвим для прибрежных чудовищ?",a="Форт Зорам'гар — изолированный и открытый пограничный лагерь прямо на берегу Ясеневого леса. Наги господствуют в руинах в море, а дикие гидры патрулируют прибой, поэтому близость воды делает его уязвимым для нападений со всех сторон.",al={"why is zoramgar attacked","zoram strand danger","почему нападают на зорам'гар","опасность зорамского взморья"}},{q="Что происходит после гибели Ворши?",a="После гибели гидры о победе сообщают гонцам Песни Войны, удерживающим рубежи у Форта Зорам'гар. Это облегчает бремя стражей границы и защищает ближайшее побережье от внезапных нападений.",al={"vorsha quest turn in","who to report vorsha to","сдать задание ворша","кому сообщить о ворше"}}},fp="17,352,22.436.0,23.501.0,25.213.0,29.228.0,33.236.0,15.226.0,54.269.0,35.221.1"}
P.entries["quest:67"] = {n="Легенда о Сталване",s="Это поручение начинает бумажный след судьбы Сталвана Мистмантла; его дает клерк Далтри из ратуши Темнолесья. Самые старые записи указывают на запад, к заброшенной Школе Луноречья в Западном Крае, и запускают классическое расследование о крушении жизни обычного человека.",h="Это поручение начинает бумажный след судьбы Сталвана Мистмантла; его дает клерк Далтри из ратуши Темнолесья.",kw={"daltry","duskwood","footlocker","forlorn spirit","mistmantle","moonbrook","schoolhouse","stalvan","westfall","далтри","сумеречный лес","сундук","неприкаянный дух","мистмантл","луноречье","школа","сталван","западный край"},ang={["class:Mage"]="Неприкаянный дух, охраняющий сундук, применяет превращение и изнуряющие проклятия, устраивая жутковатую встречу с магией, рожденной скорбью, в самой обыденной школьной обстановке.",["faction:Alliance"]="Этот этап расследования показывает, насколько сильно распались сельские города королевства: герои вынуждены пробираться через Западный Край, занятый Братством Справедливости, лишь ради запроса в реестр Темнолесья."},sec={{t="Просьба городского клерка",b="После первых расспросов в Темнолесье Клерк Далтри достает городской реестр, чтобы найти Сталвана Мистмантла. К его удивлению, книга не обновлялась годами и указывает последним известным местом жительства Сталвана школу в Луноречье далеко на западе. Не подозревая о зловещем характере расследования, Далтри считает это рутинным канцелярским делом и просит путников проверить адрес и собрать любые записи, которые помогут обновить пыльные архивы Темнолесья."},{t="Руины Луноречья",b="Идти по следу значит покинуть мрак Сумеречного леса и отправиться в беззаконную пыль Западного Края. Луноречье, некогда процветавшее земледельческое поселение, теперь кишит разбойниками из Братства Справедливости. Почти в центре опустевшего городка стоит заброшенная школа, безмолвная среди бандитской оккупации. Внутри старый сундук хранит первые осязаемые улики о прошлой жизни Сталвана как учителя, а также неутихающую, беспокойную скорбь, связанную с этим сундуком."},{t="Трагическое привидение",b="Если потревожить старый сундук, обнаружатся не только забытые страницы: он призывает Неприкаянного духа, который нападает на всякого, кто раскапывает прошлое Сталвана. Скорбная магия призрака проклинает незваных гостей и намекает на неразрешенную трагедию, связанную с уходом учителя из Западного Края; простое историческое расследование превращается в настоящее преследование призраком."}},faq={{q="Кто такой Клерк Далтри?",a="Клерк Далтри — хранитель городских записей в Ратуше Темнолесья в Сумеречном лесу. Он помогает, просматривая местный реестр в поисках упоминаний о Сталване Мистмантле, но находит лишь древние, устаревшие записи.",al={"daltry","darkshire clerk","who starts legend of stalvan 2","далтри","клерк темнолесья","кто начинает легенду о сталване 2"}},{q="Где находится Школа Луноречья?",a="Школа находится в Луноречье на юго-западе Западного Края. По архитектуре она напоминает ратушу Темнолесья и стоит посреди городка в окружении враждебных бандитов из Братства Справедливости.",al={"moonbrook schoolhouse location","where is the schoolhouse","where is stalvan footlocker","где школа луноречья","где находится школа","где сундук сталвана"}},{q="Что внутри старого сундука?",a="В сундуке лежат старые записи и личные вещи со времен, когда Сталван Мистмантл был учителем в Луноречье; они дают следующую зацепку в поисках его местонахождения.",al={"stalvan footlocker","what is in the footlocker","сундук сталвана","что в сундуке"}},{q="Почему при открытии сундука нападает призрак?",a="Открытие сундука призывает Неприкаянного духа, который нападает с превращением и проклятиями. Беспокойный призрак связан с мрачной трагедией прошлого Сталвана и его уходом из Луноречья.",al={"forlorn spirit","why does a ghost spawn","curse of stalvan ghost","неприкаянный дух","почему появляется призрак","проклятие сталвана призрак"}},{q="Почему Сталван покинул Западный Край?",a="Сталван был учителем в Луноречье, а затем отправился искать работу частным репетитором в другом уголке королевства, оставив свои школьные вещи запертыми в заброшенном городке.",al={"why did stalvan leave moonbrook","stalvan moonbrook history","почему сталван покинул луноречье","история сталвана в луноречье"}},{q="Безопасно ли входить в Луноречье?",a="Нет. Луноречье полностью перешло под власть Братства Справедливости, поэтому каждому, кто ищет школу, придется прорываться через вооруженных воров и разбойников.",al={"is moonbrook dangerous","mobs in moonbrook","опасно ли луноречье","монстры в луноречье"}}},fp="21,278,24.479.0,22.465.0,17.359.1,20.206.0,35.190.0,34.179.0,52.201.1,31.198.0,27.163.0"}
P.entries["quest:676"] = {n="Да падет молот",kw={"arathi highlands","boulderfist enforcer","boulderfist ogre","drum fel","hammerfall","hillsbrad foothills","stromgarde","tallow","tarren mill","the hammer may fall","нагорье арати","надсмотрщик тяжелого кулака","огр тяжелого кулака","драм желчный","павший молот","предгорья хилсбрада","стромгард","сальный","мельница таррен","да падет молот"},ang={["class:Warrior"]="Схватка с огромными надсмотрщиками Тяжелого Кулака — классическое испытание для бойцов первой линии, желающих заслужить уважение опытных орков-командиров вроде Драма Желчного.",["faction:Horde"]="Это задание знаменует главный переход от местных споров в Хилсбраде к более широкой обороне Нагорья Арати, укрепляя важный оплот Павшего Молота в регионе.",["race:Orc"]="Павший Молот имеет для орков глубокое сентиментальное и историческое значение: он основан там, где вождь Оргрим Молот Рока отдал жизнь во время кампаний по освобождению."},sec={{t="Грубый вызов",b="In Tarren Mill, Tallow harbors little patience for untested adventurers wandering through the Foothills. Seeing undisciplined recruits standing idle while distant allies bleed, he directs capable fighters east through Thoradin's Wall into the Arathi Highlands. The Horde outpost of Hammerfall stands besieged on multiple fronts, but Tallow refuses to send warm bodies unless they have proven their worth against substantial opposition first."},{t="Испытание Тяжелым Кулаком",b="Rather than allowing recruits to stumble blindly into Hammerfall, Tallow demands a demonstration of martial strength at the ogre mound northeast of Stromgarde. The Boulderfist tribe maintains a heavy presence in Arathi, their hulking ogres and enforcers posing an immediate threat to anyone traveling the highland trails. Slaying these brutes serves both to thin the hostile forces flanking the road and to ensure that only capable warriors arrive at the outpost."},{t="Доклад в Павшем Молоте",b="Upon clearing out the Boulderfist encampment, the path leads northeast to Hammerfall, an outpost named in memory of Warchief Orgrim Doomhammer. There, commander Drum Fel accepts fresh arrivals with weary skepticism. Whether Tallow intended to bolster the garrison or simply send fools to their deaths, Drum Fel wastes no time turning proven fighters toward the endless skirmishes threatening the outpost's survival."}},faq={{q="Где это задание начинается и заканчивается?",a="The quest is offered by Tallow in Tarren Mill, located in the Hillsbrad Foothills. After completing the required kills in Arathi Highlands, it is turned in to Drum Fel inside the Horde outpost of Hammerfall.",al={"where do i start the hammer may fall","quest turn in location","who gives the hammer may fall","где начать да падет молот","где сдать задание","кто выдает да падет молот"}},{q="Где находятся огры Тяжелого Кулака?",a="Огры Тяжелого Кулака обитают на заметном земляном кургане и в окружающем лагере к северо-востоку от руин Стромгарда в Нагорье Арати.",al={"boulderfist ogre location","where are the ogres in arathi","boulderfist mound","где огры тяжелого кулака","где огры в арати","курган тяжелого кулака"}},{q="Что такое застава Павший Молот?",a="Павший Молот — укрепленное поселение Орды на северо-востоке Нагорья Арати. Он назван в честь бывшего вождя Оргрима Молота Рока, павшего в бою неподалеку во время освобождения лагерей для интернированных орков.",al={"what is hammerfall","hammerfall lore","who founded hammerfall","что такое павший молот","предания павшего молота","кто основал павший молот"}},{q="Why does Tallow make you fight ogres before reporting to Hammerfall?",a="Павший Молот находится под постоянными атаками и отчаянно нуждается в способных бойцах. Сальный посылает новобранцев против огров Тяжелого Кулака как на суровое испытание, чтобы все, кто придет на подмогу Драму Желчному, действительно умели сражаться, а не становились лишним бременем.",al={"why kill ogres first","tallow motive","why test me","почему сначала убить огров","мотив сального","зачем меня проверяют"}},{q="Кто такой Драм Желчный?",a="Драм Желчный — опытный воин-орк и командир в Павшем Молоте в Нагорье Арати; ему поручено организовать оборону от враждебных животных, огров, троллей и остатков Альянса.",al={"drum fel identity","hammerfall commander","who is drum fel","кто такой драм желчный","командир павшего молота","драм желчный"}},{q="Что идет после этого задания?",a="Доклад Драму Желчному ведет прямо к кампании «Призыв к оружию» — череде военных операций по устранению окрестных угроз, включая племена троллей Сухокожих, угрожающие нагорью.",al={"next quest","hammer may fall followup","what comes after","следующее задание","продолжение да падет молот","что дальше"}}},fp="19,317,15.441.0,20.463.0,23.415.1,36.207.0,40.143.0,34.212.0,68.259.0,16.198.0,29.206.0"}
P.entries["quest:68"] = {n="Легенда о Сталване",s="Это расследование раскрывает забытую главу мрачной истории Сталвана Мистмантла. Пыльное неотправленное письмо из заброшенного сундука в Луноречье дает осязаемое доказательство того, где он жил, прежде чем его след исчез, и возвращает к записям Темнолесья.",h="Это расследование раскрывает забытую главу мрачной истории Сталвана Мистмантла.",kw={"clerk daltry","curse of stalvan","darkshire","duskwood","dusty unsent letter","footlocker","forlorn spirit","mistmantle","moonbrook","stalvan","клерк далтри","проклятие сталвана","темнолесье","сумеречный лес","пыльное неотправленное письмо","сундук","неприкаянный дух","мистмантл","луноречье","сталван"},ang={["class:Mage"]="Враждебная тень, охраняющая сундук, владеет коварными тайными искусствами вроде превращения, а также калечащим проклятием, что намекает на неестественные силы, сопровождающие Сталвана.",["class:Priest"]="Появление Неприкаянного духа, привязанного к простому сундуку с памятными вещами, говорит о мучительном душевном грузе, не позволившем упокоиться и после смерти.",["faction:Alliance"]="Раскрытие тайны Сталвана Мистмантла помогает осажденному Темнолесью учесть зловещих личностей, проходивших через границы региона."},sec={{t="Забытый след в Луноречье",b="Пока идут поиски истории Сталвана Мистмантла, старый сундук, спрятанный в Луноречье, выдает важную часть головоломки: пыльное неотправленное письмо. Луноречье, некогда процветавшее земледельческое поселение, пришло в упадок и теперь кишит разбойниками и неупокоенными призраками. Пребывание Сталвана здесь было достаточно недолгим, чтобы ускользнуть из общей памяти, но это забытое послание точно помещает его в деревушку."},{t="Привидение у сундука",b="Возня с вещами Сталвана не остается незамеченной. Потревоженный сундук пробуждает из теней Неприкаянного духа, готового охранять оставленные тайны. Призрак обрушивает чарующую магию и изнуряющее проклятие Сталвана, что говорит: какая бы судьба ни постигла этого человека, скорбь и темные чары прочно цепляются за его оставшиеся вещи."},{t="Обновление городского реестра",b="Доставив письмо через границу обратно в Темнолесье, вы дадите Клерку Далтри недостающий документ. Хотя Далтри находит странным, что письмо так и не отправили, доказательство неоспоримо. Теперь, когда связь с Луноречьем подтверждена, бумажный след наконец сможет направить расследование туда, куда Сталван бежал дальше."}},faq={{q="Что внутри старого сундука в Луноречье?",a="Внутри сундука лежит пыльное неотправленное письмо, написанное во время пребывания Сталвана Мистмантла в Луноречье. Оно служит осязаемым доказательством того, что он жил в городке до исчезновения.",al={"what did i find","footlocker contents","stalvan letter","что я нашел","содержимое сундука","письмо сталвана"}},{q="Почему при открытии сундука нападает дух?",a="Неприкаянный дух задерживается возле забытых вещей Сталвана и поднимается, чтобы напасть на всякого, кто потревожит сундук. Он владеет жуткой магией, включая страх, превращение и неотступное проклятие Сталвана.",al={"forlorn spirit","why am i attacked","footlocker ghost","неприкаянный дух","почему на меня напали","призрак сундука"}},{q="Зачем нести письмо Клерку Далтри?",a="Клерк Далтри ведает городскими записями и реестром в ратуше Темнолесья. Ему нужны веские документы, подтверждающие прошлое местонахождение Сталвана, прежде чем он сможет помочь в дальнейших поисках.",al={"who is clerk daltry","why daltry","darkshire town hall","кто такой клерк далтри","зачем далтри","ратуша темнолесья"}},{q="Почему важно, что письмо не было отправлено?",a="То, что письмо осталось спрятанным и брошенным в заброшенном сундуке, намекает на внезапный отъезд или растущую паранойю и усиливает жутковатую скрытность вокруг передвижений Сталвана.",al={"unsent letter mystery","why wasn't it mailed","тайна неотправленного письма","почему не отправили"}},{q="Что делает проклятие Сталвана?",a="Проклятие Сталвана, накладываемое Неприкаянным духом, который охраняет сундук, — изнуряющая порча, ослабляющая все основные характеристики жертвы на десять минут.",al={"curse of stalvan debuff","spirit curse","проклятие сталвана ослабление","проклятие духа"}},{q="Куда ведет след после передачи письма Далтри?",a="Когда Клерк Далтри обновит городской реестр по этому доказательству из Луноречья, он сможет направить ваши поиски к следующему известному месту пребывания Сталвана.",al={"what next","where after daltry","next clue","что дальше","куда после далтри","следующая улика"}}},fp="21,277,30.406.0,28.360.1,26.344.0,47.192.0,50.210.0,36.196.0,53.199.0,34.169.0,60.163.0"}
P.entries["quest:683"] = {n="Просьба Сары Балу",s="Просьба Сары Балу — печальное поручение, которое выполняется по просьбе скорбящей вдовы-дворфийки из Стальгорна. Не в силах предстать перед своим монархом в таком горе, Сара поручает передать личное обращение королю Магни Бронзобороду о ее погибшем муже, Салли Балу.",h="Просьба Сары Балу — печальное поручение, которое выполняется по просьбе скорбящей вдовы-дворфийки из...",kw={"a king's tribute","dun morogh","ironforge","magni bronzebeard","sara balloo","sully balloo","thandol span","королевские почести","дун морог","стальгорн","магни бронзобород","сара балу","салли балу","мост тандола"},ang={["faction:Alliance"]="Передача вестей между скорбящими жителями и руководством Альянса показывает, какую личную цену платят простые люди в конфликтах, защищающих королевство.",["race:Dwarf"]="Доставка просьбы скорбящей вдовы прямо вашему королю затрагивает глубокое значение, которое дворфы придают работе с камнем, родословной и почитанию жертв предков."},sec={{t="Просьба вдовы",b="Получив трагическое последнее письмо, поднятое из вод под мостом Тандола, Сара Балу оказалась парализована горем. Не желая, чтобы жертва ее мужа Салли была забыта, она написала просьбу, адресованную самому трону Стальгорна. Слишком убитая горем, чтобы явиться ко двору, она вручает запечатанный свиток надежному защитнику Альянса, чтобы тот ходатайствовал перед королем Магни Бронзобородом от ее имени."},{t="Прием у короля",b="Доставка личного прошения к Высокому трону Стальгорна — не рядовое дело, но Магни Бронзобород лично отмечает храбрых защитников Каз Модана. Получив послание, король откладывает государственные дела, чтобы прочесть скромную просьбу солдатской вдовы, и тем показывает свою связь с простыми дворфами, построившими и защищающими его горное королевство."}},faq={{q="Кто такая Сара Балу?",a="Сара Балу — дворфийка из Стальгорна, чей муж, солдат Салли Балу, погиб в трагедии на мосту Тандола. Она живет в городе, свято храня память о нем.",al={"sara balloo","who is sara","сара балу","кто такая сара"}},{q="Почему Сара хочет, чтобы к королю пошел я, а не она сама?",a="Сару сломило горе после того, как она наконец узнала о судьбе мужа. Она чувствует, что не сможет сохранить самообладание, подобающее при обращении к королю Магни Бронзобороду на Высоком троне.",al={"why cant sara go","sara grief","почему сара не может пойти","горе сары"}},{q="Кем был Салли Балу?",a="Салли Балу был дворфом-солдатом, защищавшим мост Тандола. Он погиб в бою на мосту, оставив жене намокшее письмо.",al={"sully balloo","saras husband","салли балу","муж сары"}},{q="Куда доставить Просьбу Сары Балу?",a="Просьбу нужно доставить лично королю Магни Бронзобороду на Высокий трон в центре Стальгорна.",al={"where is magni","king magni location","turn in location","где магни","где король магни","где сдать задание"}},{q="Что будет после того, как король Магни прочтет просьбу?",a="Прочитав просьбу Сары, король Магни решает достойно почтить павшего солдата, и это ведет прямо к заданию «Королевские почести», цель которого — воздвигнуть вечный памятник.",al={"quest continuation","next quest","продолжение задания","следующее задание"}},{q="Какая фракция может взять это задание?",a="Это поручение доступно только членам Альянса, так как касается внутренних дел дворфов и приема у короля Магни Бронзоборода.",al={"can horde do this","faction requirement","может ли орда","требования к фракции"}}},fp="18,262,17.468.0,22.359.1,19.156.0,63.195.0,21.158.0,38.100.0,45.158.1,37.137.0"}
P.entries["quest:686"] = {n="Королевские почести",s="Королевские почести — задание Альянса, которое дает король Магни Бронзобород на Высоком троне Стальгорна. Глубоко тронутый горем Сары Балу, чей муж Салли пал при защите моста Тандола, король решает почтить павшего солдата вечным памятником. Он посылает искателя приключений передать его королевский заказ Главному камнетесу Мраморщику.",h="Королевские почести — задание Альянса, которое дает король Магни Бронзобород на Высоком троне Стальгорна.",kw={"ironforge","magni bronzebeard","marblesten","memorial","sara balloo","sully balloo","thandol span","стальгорн","магни бронзобород","мраморщик","памятник","сара балу","салли балу","мост тандола"},ang={["faction:Alliance"]="Павшие на мосту Тандола отдали жизни, охраняя для Альянса важнейшие линии снабжения между Каз Моданом и северными королевствами.",["race:Dwarf"]="Это задание показывает преданность короля Магни своему народу: даже о самом простом дворфе-пехотинце помнит трон."},sec={{t="Бремя государя",b="Когда король Магни Бронзобород получает просьбу Сары Балу, он не отмахивается от скорбящей вдовы. Хотя он признает, что простым людям трудно понять жестокую необходимость войны, потеря каждого солдата под знаменем Альянса тяжко ложится на его совесть. Не в силах отменить мрачную неизбежность смерти на передовой, Магни решает сделать так, чтобы жертва Салли Балу не была забыта."},{t="Резец камнетеса",b="Вместо пустых утешений король решает воздвигнуть памятник в честь Салли. Он назначает искателя приключений хранителем своей королевской воли и отправляет его через весь Стальгорн к Главному камнетесу Мраморщику. Получив личный заказ короля, мастер-камнетес готовится высечь в камне память о павшем защитнике."}},faq={{q="Кем был Салли Балу?",a="Салли Балу был солдатом-дворфом, погибшим в боях за Альянс при обороне моста Тандола. Его вдова, Сара Балу, обратилась к королю Магни Бронзобороду, узнав о его смерти.",al={"who is sully","sully balloo lore","who died","кто такой салли","предания о салли балу","кто погиб"}},{q="Почему король Магни заказывает памятник?",a="Король Магни несет груз каждой дворфийской жизни, потерянной в непрекращающейся борьбе Альянса. Хотя он не может вернуть Салли вдове, он намерен почтить мужество солдата долговечным королевским памятником.",al={"why build memorial","magni motive","kings tribute purpose","зачем строить памятник","мотив магни","цель королевских почестей"}},{q="Кто такой Главный камнетес Мраморщик?",a="Главный камнетес Мраморщик — мастер-каменотес Стальгорна, которому поручено исполнение крупных городских и королевских архитектурных проектов. Король Магни рассчитывает, что он создаст памятник Салли Балу.",al={"who is marblesten","grand mason role","кто такой мраморщик","роль главного камнетеса"}},{q="Где происходит это задание?",a="Задание целиком проходит в Стальгорне: оно начинается на Высоком троне у короля Магни Бронзоборода и ведет к Главному камнетесу Мраморщику в другой части столицы.",al={"where is this quest","quest location","где это задание","место задания"}},{q="Что предшествует этому заданию?",a="Чтобы получить это задание, искатель приключений должен выполнить «Просьба Сары Балу» — доставить искреннее письмо вдовы лично королю Магни Бронзобороду.",al={"prerequisites","previous quest","требования","предыдущее задание"}},{q="Этот памятник только для Салли Балу?",a="Хотя памятник заказан именно во имя Салли Балу, чтобы утешить его вдову Сару, он символизирует почтение короля ко всем дворфийским воинам, погибшим на службе Альянсу.",al={"who does it honor","is it just for sully","кого он почитает","только ли для салли"}}},fp="16,352,20.431.0,18.361.0,21.205.0,42.213.0,30.205.0,33.167.0,29.154.0,39.193.0"}
P.entries["quest:69"] = {n="Легенда о Сталване",s="Это поручение — поворотный момент в поисках неуловимого Сталвана Мистмантла: оно уводит следователей из мрака Сумеречного леса обратно к сердцу королевства. Поспешная, полустертая запись в городской книге учета Темнолесья указывает через реку на Златоземье. Следовать бумажному следу к оживленной таверне Гордость Льва — следующий шаг к выяснению, куда отправился загадочный наставник.",h="Это поручение — поворотный момент в поисках неуловимого Сталвана Мистмантла: оно уводит следователей из мрака...",kw={"clerk daltry","darkshire","duskwood","elwynn forest","goldshire","innkeeper farley","lion's pride inn","stalvan","клерк далтри","темнолесье","сумеречный лес","элвиннский лес","златоземье","хозяин таверны фарли","таверна гордость льва","сталван"},ang={["faction:Alliance"]="Распутывание местных историй и остывших следов на южных землях Альянса требует перемещения между пограничными постами вроде Темнолесья и центральными поселениями вроде Златоземья.",["race:Human"]="Повторяя путь Сталвана, вы проходите через сердце Королевства Штормград, связывая мрачные рубежи Сумеречного леса с привычным уютом Элвиннского леса."},sec={{t="Подсказка в книге",b="Просматривая записи Темнолесья, Клерк Далтри замечает упущение в городской книге учета. Под более ранней записью о Сталване Мистмантле обнаруживается второй пункт назначения, наспех написанный и частично зачеркнутый, словно кто-то передумал или хотел скрыть свой путь. В записке сказано, что Сталван собирался отправиться на северо-запад, в Элвиннский лес, а именно в таверну Гордость Льва."},{t="Переход в Элвинн",b="Путь из тенистых рощ Сумеречного леса на солнечные дороги Златоземья дает резкий контраст, но тень прошлого Сталвана достигает и этих мест. Таверна Гордость Льва — оживленный перекресток Элвиннского леса, принимающий путников, торговцев и солдат. Хозяин таверны Фарли заправляет шумным залом, и потому лучше всех подойдет, чтобы расспросить об образованном страннике, искавшем ночлег."}},faq={{q="Почему след ведет в Златоземье?",a="Клерк Далтри обнаружил в книге учета Темнолесья под первой записью о Сталване второй, частично зачеркнутый адрес. Он ясно указывал, что тот направлялся в таверну Гордость Льва в Златоземье.",al={"why goldshire","why go to goldshire","stalvan in goldshire","почему златоземье","зачем идти в златоземье","сталван в златоземье"}},{q="Кто такой Клерк Далтри?",a="Клерк Далтри — хранитель записей, работающий в ратуше Темнолесья. Он ведет местные книги учета и помогает находить исторические документы о прежних жителях.",al={"daltry","who is daltry","далтри","кто такой далтри"}},{q="С кем говорить в таверне Гордость Льва?",a="Нужно поговорить непосредственно с Хозяином таверны Фарли, который управляет таверной Гордость Льва и следит за путниками и посетителями, проходящими через Златоземье.",al={"who to talk to","lion's pride contact","innkeeper goldshire","с кем поговорить","контакт в гордости льва","хозяин таверны златоземья"}},{q="Почему запись в книге зачеркнута?",a="Запись в книге была стерта лишь частично, что говорит о поспешной или намеренной попытке скрыть путь Сталвана в Элвиннский лес, когда он покинул Сумеречный лес.",al={"scratched out note","why scratched out","зачеркнутая запись","почему зачеркнуто"}},{q="Есть ли в этом задании сражения?",a="Нет. Этот этап расследования — лишь путешествие и расспросы, которые безопасно приведут вас из ратуши Темнолесья в таверну Златоземья.",al={"is there fighting","do i fight anything","есть ли бой","нужно ли сражаться"}},{q="Что такое таверна Гордость Льва?",a="Таверна Гордость Льва — центр Златоземья в Элвиннском лесу. Это известное место отдыха для путников, идущих между Штормградом, Западным Краем и Сумеречным лесом.",al={"lions pride inn","goldshire inn","таверна гордость льва","таверна златоземья"}}},fp="21,405,20.410.0,20.404.0,37.199.0,20.172.0,42.150.0,48.160.0,35.150.0,29.176.0"}
P.entries["quest:690"] = {n="Просьба Малина",s="Просьба Малина — задание Альянса, которое выдает верховный маг Малин в Квартале магов Штормграда. Малин просит опытных искателей приключений отправиться далеко на север, в Опорный пункт на Нагорье Арати, где экспедиция пытается вернуть ценные магические реликвии, оставленные при падении Стромгарда.",h="Просьба Малина — задание Альянса, которое выдает верховный маг Малин в Квартале магов Штормграда.",kw={"arathi highlands","malin","refuge pointe","skuerto","stormwind","stromgarde","tower of arathor","trelane","wizard's sanctum","нагорье арати","малин","опорный пункт","скуэрто","штормград","стромгард","башня аратора","трелан","святилище волшебника"},ang={["class:Mage"]="Для магов, посещающих Святилище волшебника, помощь Малину напрямую сохраняет драгоценные магические исследования и реликвии, связанные с наследием магов Аратора.",["faction:Alliance"]="Опорный пункт — хрупкий оставшийся плацдарм Альянса на Нагорье Арати, поэтому любое подкрепление из Штормграда крайне важно для удержания региона.",["race:Human"]="Стромгард был колыбелью человеческой цивилизации; помощь в возвращении его сокровищ — дело чести и исторического выживания для сынов и дочерей Аратора."},sec={{t="Потерянные вещи учителя",b="Верховный маг Малин, живущий в Святилище волшебника в Штормграде, действует от имени своего прежнего наставника, верховного мага Трелана. Когда воинственное королевство Стромгард погрузилось в хаос и разрушение, Трелан отчаянно оборонял Башню Аратора. Вынужденный покинуть пост, когда город пал под натиском врагов, Трелан оставил могущественные зачарованные вещи. Малин хочет вернуть эти артефакты, пока их не захватили враждебные руки, и направляет способных наемников на север, чтобы усилить его людей на месте."},{t="Осажденный Опорный пункт",b="Путь к реликвиям Трелана лежит через Опорный пункт — осажденный оплот сторонников Стромгарда в центре Нагорья Арати. Главный помощник Малина среди защитников — дворф Скуэрто. Однако Опорный пункт сильно теснят разбойники Синдиката, тролли Сухокожие и огры Тяжелого Кулака. Прибывшие путники быстро понимают, что Скуэрто и гарнизон слишком перегружены, чтобы радушно встретить гостей без немедленной помощи."}},faq={{q="Кто такой верховный маг Малин?",a="Верховный маг Малин — старший маг-человек, живущий в Святилище волшебника в Штормграде. Когда-то он был учеником верховного мага Трелана из Стромгарда, а теперь из Штормграда координирует усилия по возвращению магических исследований своего прежнего учителя.",al={"archmage malin","who is malin","malin stormwind","верховный маг малин","кто такой малин","малин штормград"}},{q="Почему Малину нужна помощь на Нагорье Арати?",a="Стромгард недавно пал в осаде, и верховный маг Трелан был вынужден бежать из Башни Аратора. Агенты Малина в этом районе пытаются вернуть брошенные магические реликвии Трелана, но им не справиться, и они нуждаются в подкреплении.",al={"why go to arathi","malin mission purpose","why arathi highlands","зачем идти на нагорье арати","цель задания малина","почему нагорье арати"}},{q="Где находится Скуэрто?",a="Скуэрто — дворф-разведчик, расквартированный в Опорном пункте, укрепленном лагере Альянса на главной торговой дороге через центр Нагорья Арати.",al={"find skuerto","skuerto location","where is refuge pointe","найти скуэрто","где скуэрто","где опорный пункт"}},{q="Что случилось с Башней Аратора?",a="Башня Аратора была магическим оплотом в Стромгарде. Во время падения королевства верховный маг Трелан пытался удержать укрепление от вторгшихся разбойников Синдиката и огров Тяжелого Кулака, но оборона не выдержала, и ему пришлось бежать.",al={"tower of arathor fall","what happened to stromgarde","trelane tower","падение башни аратора","что случилось со стромгардом","башня трелана"}},{q="Что будет после разговора со Скуэрто?",a="Скуэрто перегружен делами и встречает вас холодно, сразу направляя к своим товарищам в Опорном пункте, чтобы вы начали собирать разбросанные вещи Трелана.",al={"malin request follow up","next quest after malin","skuerto next quest","продолжение просьбы малина","следующее задание после малина","следующее задание скуэрто"}},{q="Кто такой верховный маг Трелан?",a="Верховный маг Трелан — выдающийся маг Стромгарда и наставник верховного мага Малина. Он был одним из главных защитников столицы Арати до падения королевства.",al={"archmage trelane","who is trelane","trelane stromgarde","верховный маг трелан","кто такой трелан","трелан стромгард"}}},fp="15,296,26.512.0,37.492.0,22.238.0,35.238.0,25.161.0,38.253.0,40.168.0,24.163.0"}
P.entries["quest:6921"] = {n="Среди руин",s="По поручению Дже'неу Санкри из Форта Зорам'гар авантюристы Орды отправляются в затопленный храм Непроглядной Пучины за глубинным ядром. Служители Земли ищут эту реликвию, чтобы раскрыть темные стихийные замыслы вторгшегося культа Сумеречного Молота.",h="По поручению Дже'неу Санкри из Форта Зорам'гар авантюристы Орды отправляются в затопленный храм Непроглядной...",kw={"amongst the ruins","ashenvale","blackfathom deeps","earthen ring","fathom core","fathom stone","je'neu sancrea","moonshrine ruins","twilight's hammer","zoram'gar outpost","среди руин","ясеневый лес","непроглядная пучина","служители земли","глубинное ядро","глубинный камень","дже'неу санкри","руины лунного святилища","сумеречный молот","форт зорам'гар"},ang={["class:Shaman"]="Добыча глубинного ядра напрямую служит миссии Служителей Земли — защитить духов воды и земли от принуждения со стороны Сумеречного Молота.",["faction:Horde"]="Уничтожая угрозы в Непроглядной Пучине, вы защищаете Форт Зорам'гар и укрепляете спорный плацдарм Орды на побережье Ясеневого леса.",["race:Troll"]="Помощь Дже'неу Санкри — это помощь собрату из племени Черного Копья, который связывает Орду со стражами стихий из Служителей Земли."},sec={{t="Угроза в глубинах",b="Древний храм ночных эльфов в Непроглядной Пучине, некогда священный для Элуны, попал под власть зловещих сил. В глубине его затопленных ходов культисты Сумеречного Молота устроили свой оплот. Шаман Черного Копья Дже'неу Санкри, находящийся на продуваемом ветрами берегу у Форта Зорам'гар в Ясеневом лесу, с растущей тревогой наблюдает за распространением порчи: он понимает, что культ намерен подчинить местные стихии и обратить их против земли и ее защитников."},{t="Глубинный камень",b="Чтобы расстроить планы культа, Дже'неу поручает защитникам Орды добыть глубинное ядро из подводного глубинного камня в Руинах Лунного святилища. Если умелые шаманы правильно расшифруют ядро, оно раскроет подробную летопись стихийных потоков и возмущений. С этим артефактом Служители Земли надеются проникнуть за завесу действий Сумеречного Молота и защитить край от стихийной катастрофы."}},faq={{q="Кто выдает задание «Среди руин»?",a="Задание выдает Дже'неу Санкри, тролль, представитель Служителей Земли в Форте Зорам'гар на Зорамском взморье в западной части Ясеневого леса.",al={"quest giver","where to get quest","who starts amongst the ruins","персонаж, выдающий задание","где взять задание","кто дает среди руин"}},{q="Что такое глубинное ядро?",a="Глубинное ядро — особый артефакт, хранящийся в затопленном глубинном камне среди руин. Когда шаманы читают его, оно дает подробную историю стихийной активности и показывает, как местные стихии принуждают и подчиняют.",al={"what is the fathom core","fathom stone purpose","what does the core do","что такое глубинное ядро","зачем нужен глубинный камень","что делает ядро"}},{q="Почему Служителей Земли беспокоит Непроглядная Пучина?",a="Служители Земли стремятся к равновесию между природными стихиями. Культисты Сумеречного Молота, захватившие затопленные руины, активно портят и принуждают стихии служить их темным целям, угрожая стабильности всего края.",al={"earthen ring motive","why does the earthen ring care","blackfathom deeps cultists","мотив служителей земли","почему служителей земли это волнует","культисты непроглядной пучины"}},{q="Где находится глубинный камень?",a="Глубинный камень лежит под водой в Руинах Лунного святилища внутри Непроглядной Пучины, поэтому исследователям нужно нырнуть, чтобы добыть ядро.",al={"where is the stone","fathom core location","moonshrine ruins fathom core","где камень","где глубинное ядро","глубинное ядро руины лунного святилища"}},{q="Могут ли игроки Альянса взять это задание?",a="Нет. Задание доступно только Орде, так как Дже'неу Санкри действует из форта Орды Зорам'гар и наряду с обязанностями Служителя Земли помогает стратегическому присутствию Орды в Ясеневом лесу.",al={"is this horde only","alliance version","can alliance do amongst the ruins","только для орды","версия для альянса","может ли альянс выполнить среди руин"}},{q="Какая группа заняла Непроглядную Пучину?",a="Пещерный храмовый комплекс захвачен Сумеречным Молотом — культом конца света, служащим зловещим Древним богам и обращающим стихии к катастрофическим целям.",al={"who is in blackfathom","enemies in bfd","twilight's hammer blackfathom","кто в непроглядной пучине","враги в непроглядной пучине","сумеречный молот непроглядная пучина"}}},fp="17,251,20.481.0,16.434.0,38.159.0,22.241.0,58.254.0,34.166.0,37.193.0,42.189.0"}
P.entries["quest:6922"] = {n="Барон Акванис",s="Победив водного элементаля барона Акваниса в Непроглядной Пучине, искатели приключений получают Странную водяную сферу с испорченной, зловонной жидкостью. Доставленный Дже'неу Санкри из Служителей Земли, артефакт становится важным свидетельством стихийной порчи, расползающейся под Ясеневым лесом. Дже'неу полагает, что сфера докажет, что испортило барона, и не удивился бы, окажись это культисты Сумеречного Молота, засевшие в затопленных руинах.",h="Победив водного элементаля барона Акваниса в Непроглядной Пучине, искатели приключений получают Странную...",kw={"ashenvale","baron aquanis","blackfathom deeps","earthen ring","elemental corruption","je'neu sancrea","strange water globe","twilight's hammer","zoram strand","ясеневый лес","барон акванис","непроглядная пучина","служители земли","стихийная порча","дже'неу санкри","странная водяная сфера","сумеречный молот","зорамское взморье"},ang={["class:Shaman"]="Служители Земли считают порчу стихийных духов тяжким нарушением природного порядка. Расследование осквернения барона Акваниса — ключ к восстановлению стихийного равновесия.",["faction:Horde"]="Дже'неу Санкри взаимодействует с разведчиками Орды в Форте Зорам'гар и ищет отважных защитников, чтобы очистить оскверненные воды под побережьем Ясеневого леса."},sec={{t="Испорченное сердце",b="Барон Акванис был не обычным духом воды, а могущественным элементалем, испорченным мерзкой магией в затопленных гротах Непроглядной Пучины. После его уничтожения остается Странная водяная сфера — несокрушимый шар с плещущейся зловонной жидкостью, которая, судя по всему, питала и искажала природную сущность существа. Предмет не поддается физическому урону и хранит энергии, глубоко тревожащие тех, кто чувствует равновесие стихий."},{t="Исследования Служителей Земли",b="Дже'неу Санкри, шаман Служителей Земли на Зорамском взморье, сразу узнает в артефакте свидетельство неестественного вмешательства. Он и его орден давно подозревали, что барон Акванис стал жертвой темных сил, и прямо указывали на культистов Сумеречного Молота, занявших затонувший храм. Изучая сферу, Дже'неу надеется не только подтвердить вину культа, но и выяснить, какими именно темными методами тот подчиняет и искажает стихийных духов Азерота."}},faq={{q="Кто такой барон Акванис?",a="Барон Акванис — могущественный элементаль воды, обитающий в подземных водах Непроглядной Пучины. Он не бродит свободно: его испортили и подчинили темные практики, обитающие в руинах храмового комплекса.",al={"who is aquanis","aquanis boss","baron aquanis lore","кто такой акванис","босс акванис","предания барон акванис"}},{q="Что такое Странная водяная сфера?",a="Странная водяная сфера — несокрушимый шар, остающийся после победы над бароном Акванисом. Внутри плещется мерзкая зловонная жидкость, источник оскверненной энергии, питавшей порчу элементаля.",al={"water globe","strange water globe","aquanis quest item","водяная сфера","странная водяная сфера","предмет задания акваниса"}},{q="Зачем Дже'неу Санкри нужна сфера?",a="Как член Служителей Земли, Дже'неу Санкри следит за стихийными возмущениями по всему Ясеневому лесу. Он изучает сферу, чтобы подтвердить, стоит ли за порчей Сумеречный Молот, и раскрыть ритуалы, искажающие духов.",al={"why bring to jeneu","jeneu sancrea purpose","зачем нести дже'неу","дже'неу санкри цель"}},{q="Кто стоит за порчей барона Акваниса?",a="Главные подозреваемые — культисты Сумеречного Молота, угнездившиеся в глубине Непроглядной Пучины. Их присутствие в храме согласуется с кампанией осквернения и темного общения с неестественными существами.",al={"who corrupted aquanis","aquanis twilight hammer","cultists blackfathom","кто испортил акваниса","акванис сумеречный молот","культисты непроглядной пучины"}},{q="Где находится Дже'неу Санкри?",a="Дже'неу Санкри — шаман Служителей Земли, разбивший лагерь на Зорамском взморье на северо-западном побережье Ясеневого леса, близ входа в пещерную систему Непроглядной Пучины.",al={"where is jeneu","turn in aquanis quest","where to turn in water globe","где дже'неу","сдать задание акваниса","куда сдать водяную сферу"}},{q="Что происходит после сдачи этого задания?",a="Передача сферы ведет к дальнейшему расследованию стихийного бедствия в крае, и искатели приключений продолжают помогать Служителям Земли против растущей скверны.",al={"next quest","elemental distress","следующее задание","стихийное бедствие"}}},fp="13,454,17.461.0,27.500.1,22.235.0,32.221.0,39.238.0,46.203.0,32.170.0,39.192.0"}
P.entries["quest:6962"] = {n="Угощение для Дедушки Зимы",s="Угощение для Дедушки Зимы — праздничное задание, которое предлагают во время Зимнего Покрова в Оргриммаре. Веселый персонаж, сидящий у лавки Пастбищ Дымного Леса, устал выслушивать праздничные пожелания и просит отзывчивого искателя приключений принести свежее имбирное печенье и молоко.",h="Угощение для Дедушки Зимы — праздничное задание, которое предлагают во время Зимнего Покрова в Оргриммаре.",kw={"gingerbread cookie","greatfather winter","holiday spices","ice cold milk","orgrimmar","smokywood pastures","treats for great-father winter","winter veil","имбирное печенье","дедушка зима","праздничные пряности","ледяное молоко","оргриммар","пастбища дымного леса","угощение для дедушки зимы","зимний покров"},ang={["faction:Horde"]="Праздник, привезенный в Оргриммар предприимчивыми гоблинами Пастбищ Дымного Леса, приносит в суровый город воинов редкую минуту беззаботного домашнего уюта.",["profession:Cooking"]="Эта праздничная традиция дает начинающим поварам простую возможность попрактиковаться в выпечке, превращая дикие яйца и сезонные пряности в праздничное имбирное печенье."},sec={{t="Усталый покровитель зимы",b="Хотя Дедушка Зима воплощает легендарный дух зимы и изобилия по всему Азероту, тот, кто встречает гостей в Аллее Силы, — трудолюбивый артист, нанятый Пастбищами Дымного Леса. Долгие смены, проведенные за выслушиванием жителей, мечтающих о праздничных лакомствах, пробуждают аппетит. Устав говорить о сезонных угощениях, Дедушка охотно просит проходящих путников утолить его тягу к теплой выпечке и холодному напитку."},{t="Кулинарный праздничный дух",b="Чтобы выполнить просьбу Дедушки, нужно немного домашней стряпни. Искателям приключений придется купить праздничные пряности у гоблинов-торговцев Пастбищ Дымного Леса, собрать мелкие яйца диких птиц и испечь классическое имбирное печенье. Вместе с кувшином ледяного молока из местной таверны это скромное угощение приносит пекарю праздничное настроение и небольшой знак благодарности от устроителей праздника."}},faq={{q="Кто такой Дедушка Зима в Оргриммаре?",a="Это актер, нанятый Пастбищами Дымного Леса, чтобы изображать легендарного Дедушку Зиму во время Зимнего Покрова. Он сидит у праздничной торговой лавки в Аллее Силы, приветствует жителей Орды, выслушивает праздничные просьбы и поддерживает веселье.",al={"who is great father winter","orgrimmar greatfather winter","is he the real winter father","кто такой дедушка зима","дедушка зима оргриммар","настоящий ли дедушка зима"}},{q="Какое угощение просит Дедушка Зима?",a="Дедушка Зима просит пять свежеиспеченных имбирных пряников и одну порцию ледяного молока, чтобы пережить долгий утомительный день встречи праздничных гостей.",al={"what does he want","treats requested","what cookies does he need","чего он хочет","какое угощение просит","какое печенье ему нужно"}},{q="Как приготовить имбирное печенье?",a="Рецепт и праздничные пряности продают торговцы Пастбищ Дымного Леса у праздничной лавки. Пекари соединяют праздничные пряности с мелкими яйцами диких птиц, а затем готовят печенье на огне.",al={"how to get gingerbread cookies","gingerbread cookie recipe","cookie ingredients","как получить имбирное печенье","рецепт имбирного печенья","ингредиенты печенья"}},{q="Где найти ледяное молоко?",a="Ледяное молоко можно купить почти у любого торговца едой и питьем, трактирщика или бармена в Оргриммаре и других крупных поселениях.",al={"where to get ice cold milk","buy milk","milk vendor","где взять ледяное молоко","купить молоко","торговец молоком"}},{q="Почему Дедушка Зима сам просит еду?",a="Целый день слушать болтовню детей и горожан о еде, подарках и праздниках — от этого артист сильно проголодался. Он не может просто так покинуть свой пост в Аллее Силы, поэтому просит проходящих искателей приключений принести ему перекус.",al={"why does he want treats","is greatfather winter hungry","почему он просит угощение","голоден ли дедушка зима"}},{q="Есть ли у этого задания аналог для Альянса?",a="Да. Такую же просьбу выдвигает Дедушка Зима в Стальгорне: он так же просит защитников Альянса принести имбирное печенье и холодное молоко во время праздника.",al={"alliance version","ironforge treats","версия для альянса","угощение стальгорн"}}},fp="30,298,24.478.0,23.452.0,39.285.0,44.177.0,36.224.0,33.144.0,50.248.0,45.180.0"}
P.entries["quest:6981"] = {n="Светящийся осколок",s="Светящийся осколок — загадочный самоцвет изумрудного цвета, добытый в темных глубинах Пещер Стенаний. Под его гладкой поверхностью клубится дымная сущность, и эта тревожная реликвия побуждает искателей приключений искать ответы в Кабестане и за его пределами.",h="Светящийся осколок — загадочный самоцвет изумрудного цвета, добытый в темных глубинах Пещер Стенаний.",kw={"barrens","druids of the fang","emerald nightmare","falla sagewind","glowing shard","ratchet","sputtervalve","wailing caverns","степи","друиды клыка","изумрудный кошмар","фолла ветер мудрости","светящийся осколок","кабестан","пароклапан","пещеры стенаний"},ang={["class:Druid"]="Для друидов изумрудный блеск и дымное ядро осколка — мрачное свидетельство того, что Изумрудный Кошмар просачивается в явный мир через павших собратьев в Пещерах Стенаний.",["faction:Alliance"]="Даже вдали от дома, в Калимдоре, исследователи Альянса понимают, какую угрозу всему миру несет темная сила, оскверняющая природу под Степями.",["faction:Horde"]="Разгадка тайны осколка помогает защитить важные перекрестки и торговые пути Степей от неестественных угроз, зарождающихся в подземных источниках.",["race:Tauren"]="Равновесие Степей дорого Шу'хало, и доставка этой противоестественной реликвии Фолле Ветер Мудрости помогает понять порчу, отравляющую их исконные земли."},sec={{t="Тревожная находка",b="Светящийся осколок, извлеченный из глубин Пещер Стенаний, сразу тревожит всякого, кто берет его в руки. Ярко-зеленый и на вид твердый, под кристаллической гранью он хранит клубящиеся туманные тени. Кристалл слегка притягивает, требуя внимания и излучая жуткую ауру, намекающую на порчу спящих друидов и их оскверненного кошмарами убежища."},{t="Поиск ответов в Кабестане",b="Не зная происхождения и природы камня, искатели приключений приносят артефакт в гоблинский порт Кабестан. Местный инженер Пароклапан осматривает диковину и понимает, что ее происхождение лежит за пределами гоблинской техники и обычной геологии. Он отправляет искателей вверх, на скалистые гребни над пещерами, где таурен-мистик Фолла Ветер Мудрости оберегает неспокойные души Степей."}},faq={{q="Что такое Светящийся осколок?",a="Это оскверненный светящийся зеленый кристалл, найденный в глубине Пещер Стенаний. Внутри его стеклянной оболочки клубится слабый дым, тревожа каждого, кто рассматривает его вблизи.",al={"glowing shard item","what is this green gem","shard from wailing caverns","светящийся осколок","что это за зеленый камень","осколок из пещер стенаний"}},{q="Кто может осмотреть осколок в Кабестане?",a="Осколок осматривает Пароклапан, инженер, живущий рядом с распорядителем полетов в Кабестане. Хотя он инженер, а не друид, он узнает странную энергию осколка и направляет вас к тому, кто разбирается в духовных вопросах.",al={"who in ratchet looks at shard","ratchet npc for shard","sputtervalve shard","кто в кабестане смотрит осколок","персонаж в кабестане для осколка","пароклапан осколок"}},{q="Где находится Фолла Ветер Мудрости?",a="Фолла Ветер Мудрости разбила лагерь на горных вершинах прямо над входом в Пещеры Стенаний в центральных Степях.",al={"falla sagewind location","where is falla","mountain above wailing caverns","где фолла ветер мудрости","где найти фоллу","гора над пещерами стенаний"}},{q="Есть ли над головой Пароклапана значок задания?",a="Нет. У Пароклапана нет активного значка задания. Нужно поговорить с ним напрямую и выбрать пункт диалога о странном светящемся осколке, чтобы продолжить.",al={"sputtervalve no question mark","cant turn in to sputtervalve","sputtervalve bugged","пароклапан нет вопросительного знака","не могу сдать пароклапану","пароклапан ошибка"}},{q="Почему кажется, что внутри осколка дым?",a="Дымный вихрь внутри кристалла отражает всепроникающую порчу, искажающую Пещеры Стенаний, и напрямую связан с Изумрудным Кошмаром, проникающим в мысли спящих Друидов Клыка.",al={"why does shard smoke","green smoke in gem","corruption in shard","почему осколок дымится","зеленый дым в камне","порча в осколке"}},{q="Кто может выполнить цепочку заданий после Фоллы Ветер Мудрости?",a="Эту историю могут пройти искатели приключений и Орды, и Альянса. Выводы Фоллы Ветер Мудрости напрямую ведут к заданию «Кошмары», отправляющему героев за советом к их вождям и старейшинам.",al={"is this quest horde only","alliance glowing shard","who gets in nightmares","только ли для орды это задание","светящийся осколок альянс","кто получает кошмары"}}},fp="17,241,22.398.0,26.419.1,26.170.0,37.225.0,32.126.0,52.167.0,47.196.0,54.208.1"}
P.entries["quest:6984"] = {n="Благодарность от \"Пастбищ Дымного Леса\"!",s="Это праздничное задание завершает усилия Пастбищ Дымного Леса по спасению зимних припасов в Оргриммаре. После возвращения похищенных угощений у Омерзительного Гринча торговец-гоблин Каймард Меднокноп направляет искателей приключений получить официальный праздничный знак признательности прямо от Дедушки Зимы.",h="Это праздничное задание завершает усилия Пастбищ Дымного Леса по спасению зимних припасов в Оргриммаре.",kw={"feast of winter veil","great-father winter","greench","kaymard copperpinch","orgrimmar","smokywood pastures","valley of strength","winter veil","зимний покров","дедушка зима","гринч","каймард меднокноп","оргриммар","пастбища дымного леса","аллея силы"},ang={["faction:Horde"]="Празднование Зимнего Покрова Ордой в Оргриммаре сочетает древнее шаманское почитание смены времен года с шумной гоблинской коммерцией.",["profession:Cooking"]="Сезонные припасы Пастбищ Дымного Леса — основа праздничной кухни: экзотические рецепты и праздничные ингредиенты, которых повара с нетерпением ждут каждый год."},sec={{t="Корпоративный праздник",b="Пастбища Дымного Леса стремятся извлечь выгоду из духа Зимнего Покрова, продавая угощения, рецепты и праздничное настроение в столицах Азерота. Когда их партию праздничных товаров похитили в заснеженных холмах Альтеракских гор, дела встали. Теперь, когда угощения возвращены, а Гринч-вор усмирен, торговец Каймард Меднокноп спешит выразить помощникам полную корпоративную благодарность — и устроить подобающе торжественную церемонию."},{t="Встреча с Дедушкой Зимой",b="Вместо того чтобы вручить обычный кошелек через прилавок, гоблины устраивают так, чтобы награду вручил сам Дедушка Зима. Восседая у праздничной елки в Аллее Силы, этот праздничный персонаж служит и покровителем традиций, и почетным символом торжеств. Он благодарит спасителей праздничных припасов сезонным благословением и Особым даром Пастбищ Дымного Леса."}},faq={{q="Кто отправляет меня поговорить с Дедушкой Зимой?",a="Каймард Меднокноп, представитель Пастбищ Дымного Леса в Аллее Силы в Оргриммаре, отправляет вас к Дедушке Зиме, когда вы успешно вернете похищенные праздничные угощения компании.",al={"who starts this quest","quest giver","kaymard role","кто начинает это задание","персонаж, выдающий задания","кто такой каймард"}},{q="Чем я заслужил благодарность Пастбищ Дымного Леса?",a="You tracked down the Abominable Greench in the Alterac Mountains and recovered the stolen holiday treats, saving the Feast of Winter Veil supply chain for the goblins.",al={"why do they thank me","what treats were stolen","greench background","почему меня благодарят","какие угощения украли","кто такой гринч"}},{q="Где в Оргриммаре находится Дедушка Зима?",a="Он сидит под большой украшенной елкой Зимнего Покрова в Аллее Силы, рядом с торговыми палатками Пастбищ Дымного Леса.",al={"great-father winter location","where is santa in org","winter veil tree org","где дедушка зима","где санта в оргриммаре","елка зимнего покрова оргриммар"}},{q="Кто такой Дедушка Зима?",a="В древних преданиях Дедушка Зима — элементаль или мифический вестник смены времен года, одевающий землю в зимний снег. На Зимний Покров смертные исполнители надевают его традиционное красное одеяние, чтобы нести добрую волю и раздавать угощения детям и искателям приключений.",al={"who is great-father winter","is great-father winter real","winter veil lore","кто такой дедушка зима","настоящий ли дедушка зима","предания зимнего покрова"}},{q="Что такое Пастбища Дымного Леса?",a="Пастбища Дымного Леса — кулинарное и сельскохозяйственное предприятие под управлением гоблинов. Во время Зимнего Покрова они поставляют праздничную еду, сезонные ингредиенты и декоративные безделушки и Орде, и Альянсу.",al={"smokywood pastures lore","who are smokywood pastures","goblin holiday vendor","предания пастбища дымного леса","кто такие пастбища дымного леса","гоблин праздничный торговец"}},{q="Получу ли я что-нибудь еще после разговора с ним?",a="Да. Дедушка Зима вручает вам Особый дар Пастбищ Дымного Леса от имени компании, а ваши усилия повышают репутацию у Картеля Хитрая Шестеренка.",al={"quest reward","disguise kit","mail gift","награда за задание","набор для маскировки","подарок по почте"}}},fp="32,308,19.481.0,33.410.0,47.210.0,52.167.0,50.128.0,27.272.0,27.214.0,51.154.0"}
P.entries["quest:7"] = {n="Нападение на лагерь кобольдов",s="«Нападение на лагерь кобольдов» — одно из первых военных поручений, которое маршал Макбрайд дает новоприбывшим рекрутам в Долине Североземья. Добровольцам предстоит истребить кобольдов-паразитов, засевших в северных лесах, чтобы агрессивные подземные мародеры не заполонили земли аббатства. Это первое настоящее испытание новобранца в защите границ Королевства Штормград.",h="«Нападение на лагерь кобольдов» — одно из первых военных поручений, которое маршал Макбрайд дает...",kw={"echo ridge","elwynn forest","kobold","marshal mcbride","northshire","northshire abbey","vermin","рудник горного эха","элвиннский лес","кобольд","маршал макбрайд","североземье","аббатство североземья","паразиты"},ang={["faction:Alliance"]="Беспорядки в Североземье показывают, насколько напряжены внутренние земли Штормграда: даже нашествия мелких мародеров требуют срочного созыва ополчения из добровольцев.",["race:Human"]="Для людей Североземья отражать кобольдов-паразитов — основной гражданский долг: нужно уберечь аббатство и фермерские земли от разорения."},sec={{t="Долина под давлением",b="Долина Североземья когда-то была тихим местом молитв, земледелия и обучения новичков, но в последние годы войска Штормграда оказались растянуты до предела. Король пропал, королевские гарнизоны рассеяны, и дикие твари вместе с лихими людьми смело наступают на границы цивилизации. Маршал Макбрайд организует местную оборону у самого Аббатства Североземья и рассчитывает на свежих добровольцев, чтобы подавить угрозы прежде, чем они нарушат жизнь аббатства или затронут окрестные виноградники."},{t="Паразиты в лесу",b="Кобольды по природе трусливые пещерные жители, помешанные на свечах; обычно они довольствуются тем, что ковыряют подземные жилы вдали от солнечного света. Однако целый клан вышел к северной кромке леса в Североземье. Если их не остановить, их многочисленность превратит мародерство в открытые набеги. Приказ Макбрайда истребить кобольдов-паразитов служит двойной цели: он ослабляет их авангард и показывает, хватит ли новобранцу решимости защищать королевство."}},faq={{q="Кто отдает приказ уничтожить лагерь кобольдов?",a="Приказ отдает маршал Макбрайд. Он стоит прямо у Аббатства Североземья и от имени Штормграда ведает приемом рекрутов и охраной долины.",al={"who gives this quest","quest giver","marshal mcbride role","кто дает это задание","персонаж, выдающий задание","роль маршала макбрайда"}},{q="Почему кобольды живут в северном лесу, а не в руднике?",a="Хотя кобольды обычно живут в норах и рудниках, в Североземье их стало так много, что они выплеснулись в открытый лес. Они устроили примитивные лагеря среди северных деревьев и бродят у края обжитых земель.",al={"why are kobolds outside","kobolds above ground","why woods","почему кобольды снаружи","кобольды на поверхности","почему в лесу"}},{q="Почему эти кобольды считаются угрозой для Штормграда?",a="Поодиночке кобольды-паразиты робки и слабы. Но стаей это наглые воры, способные устраивать засады на путников, грабить припасы и захватывать незащищенные форпосты, а Штормград не может этого допустить, пока его армия и так перегружена.",al={"are kobolds dangerous","why kill vermin","опасны ли кобольды","зачем убивать паразитов"}},{q="Куда ведет это задание дальше?",a="Когда поверхностные паразиты будут повыбиты, маршал Макбрайд просит рекрутов исследовать Рудник Горного Эха, где находится сердце нашествия кобольдов.",al={"what quest is next","next step","after camp cleanup","какое задание следующее","следующий шаг","после нападения на лагерь"}},{q="Получает ли Североземье регулярную поддержку королевской армии?",a="Нет. Из-за политической напряженности и нехватки войск по всему королевству после исчезновения короля Вариана местным командирам, таким как Макбрайд, приходится полагаться на добровольцев из числа гражданских, искателей приключений и новобранцев для охраны границ.",al={"where are stormwind guards","why volunteers","где стражи штормграда","почему добровольцы"}},{q="Почему кобольды так привязаны к своим свечам?",a="Кобольды почитают свечи как главную защиту от удушающей тьмы подземных туннелей. Пламя для них означает безопасность, зрение и собственность, поэтому они крайне враждебны к тем, кто пытается его отнять.",al={"why candles","candle obsession","почему свечи","помешанность на свечах"}}},fp="19,401,23.483.0,23.457.0,42.162.0,56.240.0,55.252.0,34.160.1,50.223.0,48.225.0"}
P.entries["quest:70"] = {n="Легенда о Сталване",s="Этот этап расследования направляет искателей к забытому письму, оставленному много лет назад в гостинице Златоземья. След Сталвана Мистмантла ведет из Элвиннского леса в Торговый квартал Штормграда.",h="Этот этап расследования направляет искателей к забытому письму, оставленному много лет назад в гостинице...",kw={"canals","caretaker folsom","goldshire","innkeeper farley","lion's pride inn","mistmantle","stalvan","stormwind","undelivered letter","каналы","управляющий фольсом","златоземье","хозяин таверны фарли","таверна гордость льва","мистмантл","сталван","штормград","недоставленное письмо"},ang={["faction:Alliance"]="Чтобы раскрыть тайну Сталвана, нужно пройти по сердцу земель Альянса и повторить старый путь от сонной деревушки Златоземье до величественных каналов столицы.",["race:Human"]="Это расследование обнажает темные течения Королевства Штормград: зло, преследующее Сумеречный лес, уходит корнями к самому порогу столицы."},sec={{t="Полуночный ужас",b="Когда Хозяина таверны Фарли из таверны Гордость Льва спрашивают о Сталване Мистмантле, он вспоминает грозовую ночь много лет назад. Странствующий курьер искал укрытия от ливня, но около полуночи в полной панике сбежал вниз. В одной ночной одежде он выскочил прямо в темную бурю, и больше его никто не видел."},{t="Оставленная посылка",b="В паническом бегстве курьер бросил сумку и личный сундук в комнате наверху. Среди забытого груза лежало неотправленное письмо с именем Сталвана, адресованное жителю Канального квартала Штормграда. Сундук так и стоял нетронутым в изножье кровати, пока Фарли не разрешил его открыть."},{t="Холодный прием",b="Доставив давно просроченное письмо в Штормград, вы попадаете к Управляющему Фольсому, который присматривает за домами вдоль каналов рядом с Парком. Вместо благодарности за доставку упомянутое имя Сталвана и вид его почерка вызывают у него немедленное отвращение и враждебность, намекая на давние скандалы, связанные с отправителем."}},faq={{q="Где хранится недоставленное письмо?",a="Письмо лежит в сундуке на верхнем этаже таверны Гордость Льва в Златоземье. Поднимитесь по лестнице, поверните направо и войдите в спальню с кроватью; сундук стоит в изножье кровати.",al={"find letter","stalvan chest location","where is the chest","найти письмо","где сундук сталвана","где сундук"}},{q="Почему письмо изначально не было доставлено?",a="Много лет назад курьер укрылся от ливня в таверне Гордость Льва. Около полуночи что-то так сильно напугало его, что он бежал в бурю в одной ночной одежде, бросив сундук и посылки.",al={"why abandoned letter","what scared the courier","why did messenger run","почему письмо брошено","что напугало курьера","почему посыльный убежал"}},{q="Где найти Управляющего Фольсома в Штормграде?",a="Управляющий Фольсом стоит у каналов в Штормграде, неподалеку от края квартала Парка.",al={"folsom location","where is caretaker folsom","canal district turn in","где фольсом","где управляющий фольсом","сдача в канальном квартале"}},{q="Почему Управляющий Фольсом сердится, получив письмо?",a="Фольсом сразу узнает почерк и имя Сталвана и реагирует с возмущением. Сталван Мистмантл оставил горькие воспоминания и негодование среди людей, связанных с его прошлым в Штормграде.",al={"why is folsom mad","folsom reaction","you have some nerve","почему фольсом зол","реакция фольсома","у вас хватает наглости"}},{q="Как это связано с бедой в Сумеречном лесу?",a="Городской совет Темнолесья расследует затянувшееся зло, связанное с именем Сталвана Мистмантла. Чтобы выяснить, кем Сталван был при жизни, нужно проследить его прежние путешествия и связи через Элвиннский лес и Штормград.",al={"why duskwood quest in goldshire","how does this relate to duskwood","почему задание сумеречного леса в златоземье","как это связано с сумеречным лесом"}},{q="Что происходит после передачи письма Управляющему Фольсому?",a="Резкий ответ Управляющего Фольсома открывает штормградскую главу расследования и подталкивает вас выяснить, где раньше служил Сталван и какие мрачные события произошли со знатным семейством, которому он служил.",al={"next step","what follows this quest","следующий шаг","что после этого задания"}}},fp="21,218,17.344.0,19.334.0,16.348.1,37.203.0,46.226.0,46.99.0,57.200.0,49.228.0,57.204.1"}
P.entries["quest:700"] = {n="Королевские почести",s="«Королевские почести» — заключительный шаг в чествовании жертвы павшего дворфийского солдата Салли Балу. После того как мелкозернистый гранит собран среди руин Лордерона, Главный камнетес Мраморщик по приказу короля Магни Бронзоборода создает в Стальгорне торжественный памятник.",h="«Королевские почести» — заключительный шаг в чествовании жертвы павшего дворфийского солдата Салли Балу.",kw={"a king's tribute","granite","ironforge","lordaeron","magni bronzebeard","marblesten","memorial","sully balloo","королевские почести","гранит","стальгорн","лордерон","магни бронзобород","мраморщик","памятник","салли балу"},ang={["class:Warrior"]="Слова Магни прямо чтят самоотверженную доблесть бойцов первой линии, таких как Салли Балу, отдавших в бою все.",["faction:Alliance"]="Памятник служит трогательным напоминанием о тяжелой цене, которую заплатили Каз Модан и северные королевства в недавних войнах.",["race:Dwarf"]="Для дворфов почитать павших предков-воинов в прочном камне — одна из самых священных культурных традиций."},sec={{t="Памятник, высеченный из скорби",b="Король Магни Бронзобород заказал постоянный памятник в честь Салли Балу, отважного дворфа, отдавшего жизнь за свой народ. Памятник создан Главным камнетесом Мраморщиком из качественного гранита, привезенного из истерзанных войной земель Лордерона, и стоит в Стальгорне как вечное свидетельство подвига павших солдат, чьи жертвы хранят королевство дворфов."},{t="Раздумья государя",b="Услышав о завершении памятника, Магни мрачно размышляет о пределах камня и смертности. Признавая, что высеченный камень никогда не сравнится с жизнью отважного дворфа, он надеется, что памятник устоит и грядущие поколения, живущие на Азероте, никогда не забудут героев, проливших кровь ради их завтрашнего дня."}},faq={{q="Кого почитает этот памятник?",a="Памятник воздвигнут в память о Салли Балу, отважном дворфийском солдате, отдавшем жизнь в доблестной борьбе за свой народ и Альянс.",al={"who is this memorial for","sully balloo monument","who died","кому памятник","памятник салли балу","кто погиб"}},{q="Почему камень добывали в Лордероне?",a="Главному камнетесу Мраморщику требовался лучший гранит, пригодный для долговечных королевских почестей. В Лордероне добывают превосходный камень, хотя сам край лежит в руинах после Плети.",al={"why lordaeron stone","lordaeron granite","marblesten stone","почему камень лордерона","гранит лордерона","камень мраморщика"}},{q="Где происходит это задание?",a="Задание начинается у Главного камнетеса Мраморщика и завершается у короля Магни Бронзоборода в Высоком троне Стальгорна.",al={"where to turn in","who completes quest","где сдать","кто завершает задание"}},{q="Почему король Магни лично заказывает эти почести?",a="Магни считает, что правители должны чтить простых солдат, защищающих их владения. Памятный камень, по его мнению, — важное напоминание будущим поколениям о высокой цене, которую рядовые солдаты платят за их безопасность.",al={"why does magni care","magni bronzebeard sully balloo","почему магни заботится","магни бронзобород салли балу"}},{q="Что происходит после завершения памятника?",a="Доклад королю Магни завершает цепочку заданий о памятнике. Готовая статуя остается в Стальгорне как торжественная, вечная веха в память о Салли Балу.",al={"what comes next","kings tribute follow up","что дальше","продолжение королевских почестей"}},{q="В чем значение статуи с точки зрения каменного мастерства?",a="Главный камнетес Мраморщик — один из самых искусных дворфийских мастеров Стальгорна. Работая с привезенным гранитом Лордерона, он превратил грубый камень в достойное общенародное произведение искусства от имени монарха.",al={"marblesten role","grand mason craft","роль мраморщика","ремесло главного камнетеса"}}},fp="16,279,26.381.0,24.333.0,38.142.0,42.209.0,33.116.0,55.206.0,44.143.0,47.209.0"}
P.entries["quest:7025"] = {n="Угощение для Дедушки Зимы",s="Во время Зимнего Покрова артист, изображающий Дедушку Зиму в Стальгорне, устает и просит прохожих о праздничном угощении. Если принести ему свежие пряничные печенья и ледяное молоко, он вручит праздничную награду и тепло поблагодарит.",h="Во время Зимнего Покрова артист, изображающий Дедушку Зиму в Стальгорне, устает и просит прохожих о...",kw={"feast of winter veil","gingerbread cookie","greatfather winter","ice cold milk","ironforge","smokywood pastures","treats for greatfather winter","зимний покров","пряничное печенье","дедушка зима","ледяное молоко","стальгорн","пастбища дымного леса","угощение для дедушки зимы"},ang={["faction:Alliance"]="Стальгорн — главный центр празднования Зимнего Покрова для Альянса: к праздничной ели в Общинном квартале съезжаются путники со всех Восточных королевств.",["profession:Cooking"]="Для задания нужны простые кулинарные навыки: смешать мелкие яйца и праздничные специи в праздничные пряничные печенья.",["race:Dwarf"]="Для дворфов Дедушка Зима — древняя легенда о титанах и зимних дарах, но вид такого дедушки, жующего печенье в Общинном квартале, возвращает миф на землю."},sec={{t="Долгий день на троне",b="Хотя Зимний Покров уходит корнями в древние предания титанов и мифы дворфов о бессмертном существе в зимней стуже, современные празднества во многом держатся на коммерческом спонсорстве Пастбищ Дымного Леса. У праздничной ели в Общинном квартале Стальгорна простой дворф долгие утомительные часы проводит в костюме Дедушки Зимы, выслушивая праздничные пожелания горожан и нетерпеливых детей."},{t="Выпечка праздничного настроения",b="Выслушав за день множество просьб о подарках, здешний Дедушка Зима неизбежно нагуливает собственный аппетит. Он просит не чего-то роскошного, а простой радости: пять свежеиспеченных пряничных печений с праздничными специями и ледяное молоко, чтобы их запить. Обмен дает передышку уставшему работнику праздника и разносит добрую волю по заснеженной столице."}},faq={{q="Где найти Дедушку Зиму в Стальгорне?",a="Дедушка Зима сидит возле большой праздничной ели и витрины Пастбищ Дымного Леса в Общинном квартале Стальгорна среди праздничных украшений.",al={"where is greatfather winter","greatfather winter location ironforge","ironforge santa location","где дедушка зима","дедушка зима стальгорн","санта в стальгорне"}},{q="Как испечь пряничные печенья?",a="Рецепт продают торговцы Пастбищ Дымного Леса рядом с Дедушкой Зимой. Для выпечки нужны навык кулинарии, праздничные специи, купленные у торговца на празднике, и мелкие яйца, собранные у диких птиц.",al={"where to get gingerbread cookies","gingerbread recipe","how to bake cookies","где взять пряничные печенья","рецепт пряников","как испечь печенье"}},{q="Где взять ледяное молоко?",a="Ледяное молоко можно купить почти у любого хозяина таверны, торговца едой или напитками в крупных городах Альянса, в том числе в тавернах Стальгорна.",al={"ice cold milk vendor","where to buy milk","milk ironforge","продавец ледяного молока","где купить молоко","молоко стальгорн"}},{q="Это тот самый легендарный Дедушка Зима?",a="Нет, это дворфийский артист, нанятый Пастбищами Дымного Леса, чтобы изображать легендарную, связанную с титанами фигуру на празднике Зимнего Покрова.",al={"is greatfather winter real","who is the guy in ironforge","is he really greatfather winter","настоящий ли дедушка зима","кто это в стальгорне","правда ли он дедушка зима"}},{q="Что присылает Дедушка Зима после выполнения задания?",a="Получив печенья и молоко, Дедушка Зима вручает вам Подарочный набор Пастбищ Дымного Леса в благодарность за старания.",al={"treats for greatfather winter reward","mail from greatfather winter","smokywood pastures sampler","награда угощение для дедушки зимы","почта от дедушки зимы","набор пастбищ дымного леса"}},{q="Могут ли игроки Орды выполнить это задание?",a="Это задание в Стальгорне дают игрокам Альянса. У Орды есть собственное подобное задание у Дедушки Зимы в Оргриммаре.",al={"can horde do this quest","horde treats for greatfather winter","может ли орда выполнить задание","угощение для дедушки зимы орда"}}},fp="29,254,22.401.0,20.427.0,48.152.0,36.212.0,29.152.0,50.150.0,64.134.1,47.154.0"}
P.entries["quest:7162"] = {n="Испытательные земли",s="«Испытательные земли» — обряд посвящения, который лейтенант Хаггердин дает новобранцам Альянса, вступающим в Стражу Грозовой Вершины в Альтераке. Чтобы получить официальный знак Грозовой Вершины, претенденты должны отправиться в кишащие гарпиями Пещеры Ледяного Крыла и вернуть установленное боевое знамя. Проявленное в пещере мужество — первый шаг к продвижению по военным рангам экспедиции.",h="«Испытательные земли» — обряд посвящения, который лейтенант Хаггердин дает новобранцам Альянса, вступающим в...",kw={"dun baldar","haggerdin","harpies","icewing caverns","insignia","proving grounds","stormpike","stormpike banner","дун болдар","хаггердин","гарпии","пещеры ледяного крыла","знак отличия","испытательные земли","грозовая вершина","знамя грозовой вершины"},ang={["faction:Alliance"]="Экспедиция Грозовой Вершины — главное военное предприятие Альянса в Альтераке, сочетающее археологические замыслы дворфов с обороной территории от Орды.",["race:Dwarf"]="Стражей Грозовой Вершины в основном возглавляют дворфы Стальгорна, ищущие древние реликвии и тайны титанов, так что это испытание — вход в одно из самых гордых военных подразделений вашей расы."},sec={{t="Мера мужества",b="Стража Грозовой Вершины ведет неустанную кампанию в Альтеракской долине против Клана Северного Волка. Лейтенант Хаггердин, координирующий силы из лагеря Альянса в Альтеракских горах, не отправляет зеленых новобранцев на поле боя без проверки. Прежде чем дать солдату официальное место в страже, Хаггердин требует доказать умение и выдержку, отправляя его в коварные Пещеры Ледяного Крыла к юго-западу от Дун Болдара."},{t="Пещеры Ледяного Крыла",b="Испытание просто по замыслу, но смертельно по исполнению: глубоко в подземных ледяных туннелях установлено знамя Грозовой Вершины. Пещеры не пусты: свирепые ледяные гарпии гнездятся в промерзших углублениях и охотно разрывают неосторожных чужаков. Возвращение со знаменем в целости показывает, что новобранец способен пройти по опасной местности, выстоять против жестоких хищников и сохранить дисциплину под давлением."},{t="Знак Грозовой Вершины",b="Тот, кто переживет пещеру и вернет знамя, получает знак отличия новичка Грозовой Вершины, официально принимающий его в экспедиционные силы. Как обещает Хаггердин, знак — не просто безделушка, а знак ранга, который можно улучшать по мере того, как солдат зарабатывает больше чести на поле боя, стремясь к легендарным наградам, таким как Око командования."}},faq={{q="Кто такой лейтенант Хаггердин?",a="Лейтенант Хаггердин — офицер Альянса, находящийся в Альтеракских горах, отвечающий за набор и поощрение бойцов Стражи Грозовой Вершины. Он проверяет будущих бойцов и награждает их за службу воинскими знаками отличия.",al={"lieutenant haggerdin","haggerdin","who gives proving grounds","лейтенант хаггердин","хаггердин","кто дает испытательные земли"}},{q="Где находятся Пещеры Ледяного Крыла?",a="Пещеры Ледяного Крыла лежат к юго-западу от оплота Альянса Дун Болдар, в ледяных просторах Альтеракской долины. Это запутанные подземные туннели, прорубленные во льду и камне.",al={"icewing caverns location","where is icewing caverns","banner location","где пещеры ледяного крыла","пещеры ледяного крыла расположение","где знамя"}},{q="Какие опасности таятся в Пещерах Ледяного Крыла?",a="Пещеры населяют свирепые ледяные гарпии. Лейтенант Хаггердин предупреждает новобранцев, что эти дикие создания без колебаний устроят засаду на чужаков и перегрызут им глотки.",al={"harpies","what is in icewing caverns","icewing harpies","гарпии","что в пещерах ледяного крыла","гарпии ледяного крыла"}},{q="Почему Стража Грозовой Вершины требует это испытание?",a="Битва с орками Северного Волка жестока и беспощадна. Хаггердин настаивает на отсеве неопытных новобранцев до того, как они попадут на основные линии, чтобы каждый солдат под их знаменем мог сражаться в суровых условиях.",al={"why proving grounds","why do the banner trial","stormpike initiation","почему испытательные земли","зачем испытание знамени","посвящение грозовой вершины"}},{q="Какова награда за прохождение «Испытательных земель»?",a="За прохождение испытания новобранец получает знак отличия новичка Грозовой Вершины. Хаггердин улучшает его до более мощных версий по мере того, как солдат накапливает честь в Альтеракской долине.",al={"stormpike insignia","eye of command","proving grounds reward","знак грозовой вершины","око командования","награда испытательные земли"}},{q="Кто такие Северные Волки, о которых говорит Хаггердин?",a="Клан Северного Волка — клан орков, живущий в Альтеракской долине со времен изгнания десятилетия назад. Стража Грозовой Вершины считает их враждебными дикарями, мешающими интересам Альянса и раскопкам в долине.",al={"frostwolf savages","who are the frostwolves","frostwolf clan","дикари северного волка","кто такие северные волки","клан северного волка"}}},fp="15,389,20.439.0,19.426.0,22.372.0,28.231.0,30.191.0,46.183.0,47.226.0,53.189.0,47.224.0"}
P.entries["quest:729"] = {n="Рассеянный геолог",ang={["faction:Alliance"]="Это задание показывает совместное присутствие исследователей из Стальгорна, изучающих незнакомые древние земли своих союзников ночных эльфов в Калимдоре."},sec={{t="Опасные раскопки",b="Dispatched across the sea by the Explorers' League under orders from Master Greywhisker, Archaeologist Hollee was thrilled to apprentice under Prospector Remtravel. Renowned among Ironforge's academic circles for his groundbreaking discoveries, Remtravel was sent to investigate ancient ruins along the untamed coast of Darkshore. However, during an excavation into what appeared to be the remnants of an ancient, great civilization, violent stone golems burst forth from the earth, rapidly overrunning the dig site."},{t="Не замечая гибели",b="While Hollee fled in panic to seek help in the night elven port of Auberdine, Remtravel barely batted an eye. Wholly consumed by the relics he uncovered, the elderly prospector remained knee-deep in rubble, completely unbothered by the lumbering constructs surrounding his camp. Anyone who reaches him south of Auberdine finds him not cowering in fear, but grumbling about missing stone brushes and misplaced fossils."}},faq={{q="Who is Prospector Remtravel?",a="Prospector Remtravel is a celebrated dwarven researcher belonging to the Explorers' League of Ironforge. Famous in the dwarven academies for his monumental discoveries, he is equally infamous for an extreme lack of situational awareness whenever valuable relics are nearby.",al={"remtravel","prospector remtravel lore","who is the prospector"}},{q="Why is Archaeologist Hollee in Auberdine?",a="Hollee was assigned as an assistant to Remtravel by Master Greywhisker. When dangerous golems emerged from the ground at their dig site, she fled northward to Auberdine seeking reinforcements to mount a rescue.",al={"archaeologist hollee","hollee auberdine","why did hollee run"}},{q="Что раскапывали дворфы на Темных берегах?",a="The expedition had uncovered evidence of an ancient, advanced society buried beneath Darkshore. Remtravel discovered a mysterious fossil and various stone artifacts before the site was overtaken by subterranean constructs.",al={"what was remtravel digging","darkshore dig site","remtravel fossil"}},{q="Where can Prospector Remtravel be found?",a="Remtravel is located in southern Darkshore, perched among ancient ruins south of Auberdine, surrounded by dangerous golems while obsessively looking for his stone brush and fossil.",al={"where is remtravel","remtravel location","find prospector remtravel"}},{q="Кто отправил эту экспедицию на Темные берега?",a="The expedition was organized by the Explorers' League in Ironforge and directly assigned by Master Greywhisker, who tasked Hollee with assisting Remtravel in cataloging the region's ancient wonders.",al={"who sent hollee","master greywhisker","explorers league darkshore"}},{q="Is Remtravel in actual danger?",a="Yes. Hostile golems prowl the ruins directly around him. Remtravel is oblivious to the imminent threat, focusing entirely on cataloging his findings and wondering where his tools and assistant have wandered off to.",al={"is remtravel dead","remtravel alive","help remtravel"}}},fp="28,330,14.516.0,17.417.0,28.273.0,41.210.0,46.222.0,40.180.0,38.198.0,30.214.0"}
P.entries["quest:730"] = {n="Неприятности на Темных берегах?",ang={["faction:Alliance"]="Это задание показывает растущее сотрудничество Стальгорна и Дарнасса, связывающее путников между Тельдрассилом и материковым Калимдором.",["race:Dwarf"]="Для дворфов это задание связано с традицией Лиги исследователей раскапывать наследие титанов и древнюю историю на новых континентах.",["race:NightElf"]="Ночные эльфы могут смотреть на появление дворфов-раскопщиков с кирками в их древних прибрежных руинах с осторожным весельем или тихой тревогой."},sec={{t="Молчащая экспедиция",b="In the grand night elven capital of Darnassus, dwarven researchers from Ironforge pursue the ancient mysteries of Kalimdor. Chief Archaeologist Greywhisker sent an excavation party across the water to Darkshore to unearth artifacts of antiquity. When weeks go by without a single missive or progress report, Greywhisker grows anxious, fearing that his field crew has encountered perils they were ill-equipped to survive alone."},{t="Неотрытые угрозы",b="Greywhisker laments that many in the Alliance dismiss dwarven archaeology as little more than an eccentric hobby. However, findings in Khaz Modan have convinced his colleagues that an ancient, terrifying force threatens Azeroth spanning from Lordaeron to Kalimdor. Digging into Darkshore's ruins is not merely an academic endeavor—it is an effort to understand historic cataclysms and the deep-seated menaces buried beneath ancient soil."},{t="Встреча в Аубердине",b="Переплыв пролив от Тельдрассила к прибрежной гавани Аубердин, путники находят в городе Археолога Холли. Обрадованная, что Главный археолог прислал помощь, Холли сообщает, что экспедиция действительно в тяжелом положении: она попала в беду дальше по побережью в поисках древних реликвий."}},faq={{q="Who starts the quest Trouble in Darkshore?",a="Chief Archaeologist Greywhisker offers the quest in the night elven capital of Darnassus, seeking brave adventurers willing to check on his missing crew.",al={"who gives trouble in darkshore","quest giver trouble in darkshore","where to get trouble in darkshore","кто дает неприятности на темных берегах","персонаж, выдающий задание неприятности на темных берегах","где взять неприятности на темных берегах"}},{q="Куда нужно отправиться, чтобы выполнить это задание?",a="Вам нужно отправиться из Дарнасса через море в портовый городок Аубердин на Темных берегах, где вы найдете Археолога Холли.",al={"where do i go","turn in location","who do i turn this in to","куда идти","где сдать задание","кому сдавать задание"}},{q="Почему дворфийские археологи находятся в Дарнассе и на Темных берегах?",a="После недавних открытий в Каз Модане дворфийские исследователи начали изучать древние места по всему Калимдору, чтобы найти ключи к древним силам, угрожающим Азероту.",al={"why are dwarves in darnassus","dwarves in darkshore","dwarven archaeology kalimdor","почему дворфы в дарнассе","дворфы на темных берегах","дворфийская археология калимдор"}},{q="Что происходит после встречи с Археологом Холли?",a="Speaking with Archaeologist Hollee in Auberdine leads directly into 'The Absent Minded Prospector', asking you to venture into Darkshore's wilderness to locate Prospector Remtravel.",al={"what comes next","follow up quest","next quest","что дальше","продолжение задания","следующее задание"}},{q="Почему группа раскопок не сообщила о себе?",a="Группа столкнулась с неожиданными опасностями и неудачами в полевых условиях на Темных берегах, и ее члены оказались разделены и лишены возможности связаться с Дарнассом.",al={"what happened to the dig","why did they disappear","crew missing","что случилось с раскопками","почему они пропали","пропала группа"}},{q="What looming threat is Greywhisker referring to?",a="Greywhisker references discoveries unearthed in Khaz Modan that suggest an ancient, pervasive danger slumbering deep within Azeroth's historic ruins.",al={"what ancient threat","greywhisker warning","khaz modan threat"}}},fp="21,355,19.426.0,16.439.0,20.335.1,42.153.0,45.134.0,58.172.0,48.181.0,45.167.0,48.149.0"}
P.entries["quest:7321"] = {n="Нежный черепаховый суп",ang={["faction:Horde"]="Поддержка гарнизона Мельницы Таррен — это не только защита границ: запасы и боевой дух помогают Орде удержаться в спорном Хилсбраде.",["profession:Cooking"]="Это задание позволяет поварам освоить нежный черепаховый суп, превращая агрессивных рептилий озера Лордамер и рек Хилсбрада в восстанавливающее блюдо."},sec={{t="Гастрономия Отрекшихся",b="It is widely assumed that the Forsaken have entirely abandoned the comforts of life, including the art of fine dining. Christoph Jeffcoat, stationed in Tarren Mill, vigorously rejects that assumption. Boasting that his rich, soothing turtle bisque is good enough to tempt souls back from beyond the grave, Jeffcoat seeks to prove that undead hands are capable of delicate, heartwarming craft even in a land tainted by plague and war."},{t="Охота на кусачих черепах",b="Ordinarily, Jeffcoat gathered his own ingredients from the waterways of Hillsbrad Foothills and the eastern shores of Lordamere Lake in neighboring Alterac. However, duties in Tarren Mill and the encroaching presence of Alliance forces have pinned him down. He relies on passing Horde cooks to hunt the snapjaws, harvest their meat, and bring it back so the culinary tradition can endure."}},faq={{q="Зачем повару из Отрекшихся готовить горячий суп?",a="While the Forsaken do not require sustenance in the same manner as living mortals, individuals like Christoph Jeffcoat take great pride in their trade. Jeffcoat aims to disprove the prejudice that undead lack refined skill, joking that his signature broth is good enough to bring the deceased back to life.",al={"undead cooking","why make bisque","undead eat food","готовка нежити","зачем варить суп","нежить ест еду"}},{q="Где найти черепашье мясо для этого рецепта?",a="Черепашье мясо добывают у агрессивных кусачих черепах, живущих вдоль рек Предгорий Хилсбрада и Альтерака, а также на берегах озера Лордамер.",al={"where are turtles","turtle locations","snapjaw locations","где черепахи","места черепах","где кусачие черепахи"}},{q="Why can't Christoph Jeffcoat gather his own ingredients?",a="Jeffcoat claims he is tied down with responsibilities in Tarren Mill. He also expresses irritation at the encroaching Alliance forces nearby, which make personal hunting excursions far more hazardous.",al={"why doesn't christoph go","jeffcoat stuck in town"}},{q="Нужны ли знания кулинарии для этого задания?",a="Yes. Christoph Jeffcoat will only share his craft and recipe with fellow practitioners of the cooking profession, though it does not demand any advanced mastery to begin.",al={"do i need cooking","cooking profession requirement","нужна ли кулинария","требование профессии кулинария"}},{q="Какое значение имеет Мельница Таррен для Орды в Хилсбраде?",a="Мельница Таррен — главный оплот Орды в Предгорьях Хилсбрада. Прежде человеческая деревня, теперь она служит укрепленной базой Отрекшихся и их союзников и часто сталкивается с Южнобережьем и силами Альянса в регионе.",al={"what is tarren mill","tarren mill lore","что такое мельница таррен","предания мельницы таррен"}},{q="Бывает ли черепаший суп только у Орды?",a="Alliance cooks can acquire the recipe from local human chefs in Southshore who also make use of the local turtle population, but Christoph Jeffcoat's personal quest and perspective are exclusive to the Horde.",al={"alliance version","can alliance get turtle bisque","версия альянса","может ли альянс получить черепаховый суп"}}},fp="22,366,19.433.0,20.388.0,54.306.0,47.175.0,56.200.0,49.170.0,59.255.0,37.208.0"}
P.entries["quest:74"] = {n="Легенда о Сталване",s="Этот этап расследования ведет к старому ящику с семейными реликвиями Флинтриджей, оставленному у каналов Штормграда. В пыльных вещах находится обрывок страницы дневника — важная рукописная улика о прошлой жизни Сталвана Мистмантла, ведущая к маршалу Хаггарду в Элвиннском лесу.",h="Этот этап расследования ведет к старому ящику с семейными реликвиями Флинтриджей, оставленному у каналов...",kw={"duskwood","elwynn forest","forlorn spirit","marshal haggard","mistmantle","sealed crate","stalvan","torn journal page","сумеречный лес","элвиннский лес","неприкаянный дух","маршал хаггард","мистмантл","запечатанный ящик","сталван","обрывок страницы дневника"},ang={["faction:Alliance"]="Расследование давних нераскрытых дел в сердце Элвиннского леса показывает, как глубоко личные ужасы могут ускользнуть от взгляда маршалов Штормграда.",["race:Human"]="Маршал Хаггард олицетворяет стареющее поколение ветеранов Штормграда, хранящее важные воспоминания о королевстве до того, как Первая и Вторая войны разорвали семьи."},sec={{t="Вскрывая прошлое",b="Роясь в запечатанном ящике с затхлыми реликвиями, старыми охотничьими трофеями и семейными портретами, следователи находят под керамической вазой одинокий обрывок страницы дневника. Написанный рукой самого Сталвана Мистмантла, он дает личное представление о мыслях замкнутого ученого до наступления трагедии."},{t="Слабеющее зрение маршала",b="Маршал Хаггард, теперь старый и страдающий от слабого зрения, с трудом разбирает письмо на потрепанном пергаменте. И все же характерный почерк тревожно отзывается в его памяти, напоминая о документах и событиях минувших лет, до того как тьма отняла у него зрение."}},faq={{q="Где находится запечатанный ящик?",a="Запечатанный ящик стоит у Каналов Штормграда, прямо за управляющим Фольсомом, среди упакованных вещей семьи Флинтридж. Найденную там страницу затем относят маршалу Хаггарду на юго-востоке Элвиннского леса.",al={"crate location","where is crate","haggard crate","где ящик","расположение ящика","ящик хаггарда"}},{q="Что внутри запечатанного ящика?",a="В ящике лежат пыльные реликвии, семейный портрет, старые книги, охотничьи трофеи и керамическая ваза, под которой находится обрывок страницы из дневника Сталвана.",al={"crate contents","what is in the crate","torn page crate","содержимое ящика","что в ящике","обрывок страницы в ящике"}},{q="Кто такой маршал Хаггард?",a="Маршал Хаггард — пожилой офицер Штормграда в отставке, живущий один на юге Элвиннского леса. Несмотря на слабое зрение и дряхлость, его воспоминания о старых записях и путниках делают его важным свидетелем прошлых событий.",al={"who is haggard","marshal haggard lore","old marshal elwynn","кто такой хаггард","предания маршала хаггарда","старый маршал элвинн"}},{q="Почему эта страница дневника важна?",a="Обрывок страницы — прямое свидетельство, написанное самим Сталваном Мистмантлом. Его характерный почерк и оставшиеся мысли помогают связать разрозненные рассказы из Сумеречного леса и Элвиннского леса с его личным падением.",al={"why torn page matters","journal page clue","stalvan journal","почему важна страница","улика дневник","дневник сталвана"}},{q="Что происходит, когда ящик открывают?",a="Потревоженные останки прошлого Сталвана пробуждают беспокойных мертвецов: появляется мстительный неприкаянный дух и нападает на тех, кто пытается раскрыть эту трагедию.",al={"forlorn spirit spawn","ghost after crate","why did a ghost attack me","появление неприкаянного духа","призрак после ящика","почему напал призрак"}},{q="Куда ведет расследование дальше?",a="После того как обрывок страницы показан маршалу Хаггарду, его воспоминание о почерке направляет расследование дальше — к поискам других уцелевших фрагментов истории Сталвана.",al={"next step","after torn page","where do I go next","следующий шаг","после обрывка страницы","куда идти дальше"}}},fp="21,309,19.331.0,24.276.1,34.227.0,32.158.0,23.226.0,35.215.0,38.163.0,39.173.0"}
P.entries["quest:741"] = {n="Рассеянный геолог",s="В этом поручении странный окаменелый образец, найденный на диких берегах Темных берегов, нужно доставить в аванпост Лиги исследователей в Дарнассе. Археолог Холли не хочет бросать рассеянного коллегу в поле и поручает перевозку образца проходящему мимо искателю приключений. Прибытие окаменелости в столицу ночных эльфов тут же вызывает живой интерес Главного археолога Седоуса.",h="В этом поручении странный окаменелый образец, найденный на диких берегах Темных берегов, нужно доставить в...",kw={"archaeologist","darkshore","darnassus","explorers league","fossil","greywhisker","hollee","remtravel","археолог","темные берега","дарнасс","лига исследователей","окаменелость","седоус","холли","сомнамбулер"},ang={["faction:Alliance"]="Это задание показывает, как члены Альянса зависят друг от друга: дворфийские исследователи полагаются на странствующих искателей приключений, которые безопасно связывают дальние берега Темных берегов и высоты Дарнасса.",["race:Dwarf"]="Доставка окаменелости Сомнамбулера исполняет главную миссию Лиги исследователей: раскрыть глубочайшее прошлое мира и доказать безмерную ценность дворфийского упорства.",["race:NightElf"]="Смотреть, как дворфийские землекопы выносят древние останки из священной земли Темных берегов, может быть тяжело, но сотрудничество с Лигой сохраняет связи внутри Альянса."},sec={{t="Курьер в столицу",b="Раскопки Геолога Сомнамбулера на туманном побережье Темных берегов обнаружили любопытную окаменелость, но копать глубже для него важнее, чем соблюдать порядок. Археолог Холли не хочет оставлять блуждающего геолога одного среди опасных зверей и враждебных культистов побережья и остается присматривать за ним. Чтобы находка была задокументирована, ей нужен путник из Альянса, который доставит образец в Дарнасс, где у дворфийской гильдии есть ученое представительство."},{t="Интерес дворфов в Калимдоре",b="Дворфы из Стальгорна большими силами пересекли Великое море под знаменем Лиги исследователей, желая раскопать древние реликвии и утраченную историю под землей Калимдора. Приняв артефакт в эльфийской столице, Главный археолог Седоус тут же начинает восхищаться талантом Сомнамбулера находить древние сокровища. Если ночные эльфы считают свои леса живыми святилищами, то Лига видит в древних землях обширные раскопки, ждущие расшифровки."}},faq={{q="Что это за загадочная окаменелость?",a="Это неопознанный окаменелый образец, найденный на побережье Темных берегов Геологом Сомнамбулером. Его древность и необычная природа делают его ценной находкой для ученых Лиги исследователей в Дарнассе.",al={"mysterious fossil","what fossil is this","remtravel fossil","загадочная окаменелость","что это за окаменелость","окаменелость сомнамбулера"}},{q="Почему Холли остается на Темных берегах?",a="Археолог Холли считает своим долгом присматривать за Геологом Сомнамбулером. Он привык уходить в сторону и не замечать опасности во время раскопок, поэтому она не хочет оставлять его одного в глуши, пока его находки доставляют в Дарнасс.",al={"why doesn't hollee go","hollee staying","why hollee stays","почему холли не идет","холли остается","почему холли остается"}},{q="Кто такой Главный археолог Седоус?",a="Седоус — старший представитель Лиги исследователей Стальгорна, руководящий археологическими предприятиями на севере Калимдора. Он работает в Дарнассе и изучает реликвии, которые привозят с места работ дворфийские землекопы.",al={"greywhisker","who is greywhisker","chief greywhisker","седоус","кто такой седоус","главный археолог седоус"}},{q="Почему Лига исследователей работает в Дарнассе?",a="Король Магни Бронзобород учредил Лигу исследователей, чтобы раскрыть происхождение дворфов и древнюю историю всего Азерота. Дружественные дипломатические связи с ночными эльфами позволяют дворфийским ученым отправлять экспедиции из Дарнасса для изучения забытых земель Калимдора.",al={"dwarves in darnassus","explorers league darnassus","why are dwarves here","дворфы в дарнассе","лига исследователей дарнасс","почему здесь дворфы"}},{q="Куда попадет окаменелость после Дарнасса?",a="Главный археолог Седоус осматривает находку в Дарнассе, но открытия такого масштаба должны быть внесены в каталог или направлены дальше по каналам Лиги и обратно в великий музей Стальгорна.",al={"where does fossil go","fossil next step","куда попадет окаменелость","дальнейший путь окаменелости"}},{q="Где Сомнамбулер нашел образец?",a="Сомнамбулер обнаружил образец на диком побережье Темных берегов, где полно кораблекрушений, древних руин и окаменелых морских существ, живших еще до Великого Раскола.",al={"where was fossil found","remtravel dig site","где нашли окаменелость","место раскопок сомнамбулера"}}},fp="28,412,24.493.0,29.498.0,30.220.0,41.236.0,39.222.0,52.284.0,46.205.0,38.177.0"}
P.entries["quest:742"] = {n="Большая охота",s="Большая охота — это призыв, отправленный молодым героям Орды в Громовом Утесе: он зовет их на север, в густые кроны Ясеневого леса. Через глашатаев города путникам велят явиться к Сенани Громовое Сердце на Заставе Расщепленного Дерева и принять участие в испытательной охоте.",h="Большая охота — это призыв, отправленный молодым героям Орды в Громовом Утесе: он зовет их на север, в густые...",kw={"ashenvale","hunt","senani","splintertree","thunder bluff","thunderheart","windstrider","zoram strand","ясеневый лес","охота","сенани","расщепленное дерево","громовой утес","громовое сердце","быстрое копыто","зорамское взморье"},ang={["class:Hunter"]="Дикие хищники Ясеневого леса дают охотникам возможность освоить выслеживание в густом лесу, совсем не похожем на сухие открытые саванны юга.",["faction:Horde"]="Застава Расщепленного Дерева и Зорамское взморье — важнейшие плацдармы северных линий снабжения Орды, и им нужны свежие новобранцы, чтобы сдерживать диких зверей и враждебных местных жителей.",["race:Tauren"]="Для таурен, проходивших испытания на открытых равнинах Мулгора, густой и тенистый полог Ясеневого леса — непривычное священное испытание под бдительными взглядами сородичей, таких как Сенани."},sec={{t="Призыв с Высокой вершины",b="На безмятежных высотах Громового Утеса гонцы сообщают растущей Орде о возможностях за пределами Мулгора. Вестник Утеса Быстрое Копыто несет открытое приглашение для проверенных искателей приключений, ищущих более серьезных испытаний. Поскольку Орда закрепляется в глубине древнего леса к северу от Степей, молодых воинов призывают усилить эти аванпосты и испытать навыки выживания в куда более суровой среде."},{t="Северный рубеж",b="Ясеневый лес для Орды — это и богатые ресурсы, и серьезная опасность. Присутствие фракции в этих землях держится на двух крупных лагерях: Заставе Расщепленного Дерева у главной дороги и отдаленном аванпосте на западном побережье, на Зорамском взморье. Прибыв на Заставу Расщепленного Дерева, новобранцы оказываются под началом Сенани Громовое Сердце, опытной охотницы, которая организует масштабную охоту, чтобы укротить дикие земли и добыть славу для Орды."}},faq={{q="Кто дает это задание в Громовом Утесе?",a="Это поручение предлагает проходящим искателям приключений в Громовом Утесе Вестник Утеса Быстрое Копыто. Его долг — сообщать способным бойцам о стремлении Орды к расширению и направлять их в отдаленные аванпосты, нуждающиеся в помощи.",al={"who starts ashenvale hunt","quest giver ashenvale hunt","bluff runner windstrider","кто начинает большую охоту","персонаж, выдающий задание большая охота","вестник утеса быстрое копыто"}},{q="Где находится Застава Расщепленного Дерева?",a="Застава Расщепленного Дерева — укрепленное поселение Орды в восточной части Ясеневого леса. Чтобы добраться до нее, идите прямо на север через границу Степей в Ясеневый лес, а затем по восточной лесной тропе вглубь чащи.",al={"splintertree post location","how to get to splintertree post","where is splintertree","где застава расщепленного дерева","как добраться до заставы расщепленного дерева","где расщепленное дерево"}},{q="Кто такая Сенани Громовое Сердце?",a="Сенани Громовое Сердце — опытная охотница-таурен, расквартированная на Заставе Расщепленного Дерева. Она координирует охоту в Ясеневом лесу и проверяет силу и терпение новобранцев Орды в схватках с местными хищниками.",al={"senani thunderheart","who is senani","thunderheart npc","сенани громовое сердце","кто такая сенани","громовое сердце"}},{q="Почему Орда охотится в Ясеневом лесу?",a="Орда активно расширяет присутствие в Ясеневом лесу, чтобы добывать древесину и занять стратегически важные земли. Сама охота помогает сократить число опасных диких зверей, угрожающих лагерям, и позволяет молодым искателям приключений проявить себя на незнакомой местности.",al={"why hunt in ashenvale","ashenvale hunt purpose","horde ashenvale goals","зачем охотиться в ясеневом лесу","цель большой охоты","цели орды в ясеневом лесу"}},{q="Что такое Зорамское взморье, упомянутое в брифинге?",a="Зорамское взморье — прибрежный лагерь Орды на дальнем западном берегу Ясеневого леса, обращенный к морю. Он служит вторичным морским плацдармом и оплотом против наг и враждебных лесных обитателей.",al={"what is zoram strand","zoram strand outpost","zoram outpost","что такое зорамское взморье","аванпост зорамского взморья","аванпост зорам"}},{q="Что происходит после доклада Сенани?",a="Когда вы доложите Сенани Громовое Сердце, она поприветствует вас на аванпосте и сразу вовлечет в более широкие охотничьи задачи, направив вас выслеживать и побеждать самых свирепых зверей Ясеневого леса.",al={"what follows ashenvale hunt","next quest after senani","hunt continuation","что после большой охоты","следующее задание после сенани","продолжение охоты"}}},fp="18,291,28.451.0,21.468.0,39.213.0,35.220.0,27.211.0,38.261.0,51.196.0,39.197.0"}
P.entries["quest:743"] = {n="Опасности Ярости Ветра",s="Опасности Ярости Ветра — обряд боевой готовности, который предлагает Руул Орлиный Коготь в Деревне Кровавого Копыта. Молодым таурен и искателям приключений Орды поручено сразиться с дикими гарпиями Ярости Ветра, гнездящимися в юго-восточных утесах Мулгора. Охота на этих свирепых хищников — важная проверка мастерства и выживания перед выходом за пределы родины племен.",h="Опасности Ярости Ветра — обряд боевой готовности, который предлагает Руул Орлиный Коготь в Деревне Кровавого...",kw={"bloodhoof village","dangers of the windfury","harpies","mulgore","ruul eagletalon","tauren trial","windfury","windfury talons","деревня кровавого копыта","опасности ярости ветра","гарпии","мулгор","руул орлиный коготь","испытание таурен","ярость ветра","когти ярости ветра"},ang={["class:Warrior"]="Испытание Руула Орлиного Когтя особенно важно для будущих воинов, которым предстоит учиться отражать быстрые пикирующие удары и одолевать свирепых воздушных налетчиков твердой выучкой.",["faction:Horde"]="Союзники таурен, проходящие испытание Руула, показывают преданность делу защиты сердца земель Орды и завоевывают неизменное уважение Деревни Кровавого Копыта.",["race:Tauren"]="Для молодых таурен очистка гнезд Ярости Ветра — это и защита равнин, и священный переход во взрослую жизнь под бдительными взглядами старейшин деревни."},sec={{t="Оценка наставника",b="В Деревне Кровавого Копыта опытный воин Руул Орлиный Коготь наблюдает за всеми путниками, проходящими через сердце Мулгора. От тех, кто достиг зрелости или хочет доказать готовность к дальним странствиям, Руул требует вещественных доказательств боевых навыков. Выжить за пределами защищенных долин Мулгора можно лишь хладнокровно встречая агрессивных и хитрых врагов, и Руул оценивает стойкость юнцов на свирепейших местных хищниках."},{t="Угроза Ярости Ветра",b="Гарпии Ярости Ветра гнездятся на горном юго-восточном краю Мулгора, вдали от проторенных троп, но постоянно угрожают бродячим животным и одиноким путникам. Жестокие и вечно голодные до свежей плоти, эти крылатые чудовища полагаются на стремительные налеты и острейшие когти. Победа над ними и добыча их когтей показывают не только силу, нужную для устранения закрепившейся угрозы, но и скорость, необходимую против воздушных налетчиков."}},faq={{q="Кто такой Руул Орлиный Коготь?",a="Руул Орлиный Коготь — опытный воин и наставник из таурен, живущий в Деревне Кровавого Копыта. Он обучает молодых искателей приключений и устраивает испытания, чтобы убедиться, что у них хватает силы, реакции и стойкости, прежде чем они отправятся в более опасные уголки Калимдора.",al={"ruul eagletalon","who gives dangers of the windfury","ruul","руул орлиный коготь","кто дает опасности ярости ветра","руул"}},{q="Где в Мулгоре обитают гарпии Ярости Ветра?",a="Гарпии Ярости Ветра гнездятся в юго-восточных горах Мулгора. Свои грубые гнезда они строят высоко на скалах и склонах предгорий, вдали от главной дороги, пересекающей долину.",al={"windfury harpy location","where are windfury harpies","windfury nest location","где гарпии ярости ветра","расположение гарпий ярости ветра","гнезда ярости ветра"}},{q="Почему гарпии Ярости Ветра считаются природными врагами таурен?",a="Гарпии — известные своей агрессивностью хищные падальщики, защищающие свои территории и нападающие на всех, кто приближается к их гнездам. В Мулгоре стая Ярости Ветра славится ненасытной тягой к свежему мясу и неослабной злобой к путникам и пасущимся животным, из-за чего постоянно угрожает равнинам.",al={"why do tauren fight harpies","harpy threat mulgore","windfury lore","почему таурены сражаются с гарпиями","угроза гарпий мулгор","предания ярости ветра"}},{q="Какое доказательство требует Руул Орлиный Коготь после охоты?",a="Руул просит искателей приключений добыть восемь когтей Ярости Ветра прямо с убитых гарпий. Отсечь и принести эти когти — значит показать мастерство против основного природного оружия гарпий.",al={"dangers of the windfury proof","what to collect for ruul","windfury quest objective","доказательство опасности ярости ветра","что собрать для руула","цель задания ярости ветра"}},{q="Почему искатели приключений должны пройти это испытание перед уходом из Мулгора?",a="Руул считает свирепых гарпий Ярости Ветра идеальной мерой боевой готовности. Если искатель приключений не справляется со скоростью, яростью и когтями гарпии, у него мало шансов против более смертельных опасностей за оборонительными утесами Мулгора.",al={"purpose of the trial","why do dangers of the windfury","ruul's test","цель испытания","зачем опасности ярости ветра","испытание руула"}},{q="Где находится Деревня Кровавого Копыта?",a="Деревня Кровавого Копыта расположена в центральной части Мулгора у Озера Каменного Быка, к югу от Великих врат и Громового Утеса. Это главный центр культуры, торговли и обучения для таурен, путешествующих по равнинам.",al={"bloodhoof village location","where is bloodhoof","ruul location","где деревня кровавого копыта","где кровавое копыто","где руул"}}},fp="23,364,22.435.0,19.451.0,23.275.0,48.204.0,70.299.0,53.188.0,63.257.0,35.220.0"}
P.entries["quest:745"] = {n="Недобрые соседи",s="Это задание выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта. Оно посылает юных искателей приключений из Орды сдержать разрушительное браконьерство местных гноллов Бледногривов. Истребляя их кожевников, свежевателей и браконьеров, вы защищаете дикую природу Мулгора и постигаете философию тауренов — жить в равновесии с Матерью-Землей.",h="Это задание выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта.",kw={"baine bloodhoof","bloodhoof village","gnolls","mulgore","palemane","poachers","sharing the land","skinners","tanners","бейн кровавое копыто","деревня кровавого копыта","гноллы","мулгор","бледногривы","браконьеры","недобрые соседи","свежеватели","кожевники"},ang={["class:Druid"]="Друиды понимают, что безнаказанное браконьерство нарушает дух равнин и требует немедленного вмешательства, чтобы исцелить гармонию этой земли.",["class:Hunter"]="Свежеватели и браконьеры Бледногривов — противоположность настоящего охотника: они жестоко и расточительно убивают диких существ вместо того, чтобы уважать их.",["faction:Horde"]="Помощь Бейну Кровавому Копыту укрепляет связь между новыми искателями приключений из Орды и руководством юного народа тауренов.",["race:Tauren"]="Для молодых тауренов отклик на призыв Бейна — важный шаг к пониманию священного долга защищать Мулгор и чтить равновесие Матери-Земли."},sec={{t="Земля вне равновесия",b="Таурены глубоко почитают природу, берут от нее лишь необходимое для выживания и чтят Мать-Землю во всем. Гноллы Бледногривы, поселившиеся к югу от Деревни Кровавого Копыта и в пещере на западе, не питают такого уважения. Вместо умеренной охоты они жестоко истребляют зверей по всей равнине, оставляя за собой освежеванные туши и нарушенное равновесие природы. Для народа, стремящегося построить мирный дом в Мулгоре, эта бездумная бойня недопустима."},{t="Когда слова бессильны",b="Бейн Кровавое Копыто сначала надеялся решить дело миром и пытался начать переговоры с наступающими гноллами. Бледногривы отвергли все попытки, ответив на дипломатию враждебностью и продолжением разорения. Видя, что переговоры бесполезны, Бейн прибегает к силе. Юных воинов отправляют прямо в охотничьи лагеря, чтобы покончить с браконьерами, кожевниками и свежевателями, пока степи не получили непоправимый урон."},{t="Круг жизни и смерти",b="Это поручение — обряд посвящения и нравственный урок для растущих защитников. Когда искатель приключений возвращается с истребления, Бейн напоминает ему, что отнимать жизнь нужно не из злобы, а по необходимости, ради сохранения гармонии. Жизнь и смерть образуют единый круг, где одно не может существовать без другого, — это основополагающая истина, которую должен нести каждый защитник Мулгора."}},faq={{q="Кто выдает это задание?",a="Бейн Кровавое Копыто, сын верховного вождя Кэрна Кровавого Копыта, выдает это задание в Деревне Кровавого Копыта в центре Мулгора.",al={"quest giver","who starts sharing the land","baine quest","персонаж, выдающий задания","кто начинает недобрые соседи","задание бейна"}},{q="Почему таурены нацелились на гноллов Бледногривов?",a="Гноллы Бледногривы безрассудно охотятся на животных Мулгора и истощают стада, не чтя природное равновесие. Они также отвергли все попытки тауренов наладить мирный диалог.",al={"why kill gnolls","palemane problem","what did gnolls do","зачем убивать гноллов","проблема бледногривов","что сделали гноллы"}},{q="Где находятся эти гноллы?",a="Бледногривы устроили лагеря к югу от Деревни Кровавого Копыта и обитают в системе пещер Утеса Бледногривов на западе.",al={"gnoll locations","palemane camp","where to find palemanes","где гноллы","лагерь бледногривов","где найти бледногривов"}},{q="Пытались ли таурены сначала договориться о мире?",a="Да. Бейн отмечает, что таурены не раз пытались наладить общение и поделить землю, но гноллы с презрением отвергли все мирные предложения.",al={"did tauren talk to gnolls","palemane diplomacy","говорили ли таурены с гноллами","дипломатия бледногривов"}},{q="Какому уроку Бейн пытается научить?",a="Бейн хочет, чтобы юные защитники поняли: смерть и жизнь образуют нерушимый круг. Хотя порой приходится отнимать жизнь ради защиты равновесия, делать это нужно всегда с глубоким уважением к Матери-Земле.",al={"baine lesson","meaning of sharing the land","урок бейна","смысл недобрые соседи"}},{q="Кто такие гноллы Бледногривы?",a="Это примитивное гиеноподобное племя, обитающее в Мулгоре. Оно известно бледным мехом, территориальной агрессией и полным пренебрежением к гармонии равнин.",al={"who are palemanes","palemane tribe","кто такие бледногривы","племя бледногривов"}}},fp="16,309,21.523.0,15.429.0,28.396.0,21.114.0,49.178.0,31.122.0,39.155.0,42.222.0,28.160.0"}
P.entries["quest:746"] = {n="Дворфийские делишки",s="«Дворфийские делишки» — задание в Мулгоре, которое выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта. Опасаясь, что раскопки дворфов разъярят местных зверей и осквернят священную землю, Бейн поручает юным защитникам Орды сорвать их работу: отобрать и разбить их кирки.",h="«Дворфийские делишки» — задание в Мулгоре, которое выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта.",kw={"baine bloodhoof","bloodhoof village","dwarf","forge","kodo","mulgore","picks","prospector","бейн кровавое копыто","деревня кровавого копыта","дворф","горн","кодо","мулгор","кирки","старатель"},ang={["class:Shaman"]="Шаманы понимают: тревожить недра неосторожными раскопками — значит нарушать равновесие стихий и вызывать беспокойство среди духов и существ земли.",["faction:Horde"]="Вторжение лояльных Альянсу дворфов в сердце земель Орды подрывает хрупкий мир, установленный после Третьей войны, и демонстрирует явное пренебрежение границами племен.",["profession:Mining"]="Шахтеры почитают богатства, скрытые в камне, но методы дворфов в Мулгоре лишены уважения и гармонии и ведут к бездумному разрушению.",["race:Tauren"]="Тело Матери-Земли священно, и вид чужаков, буравящих холмистые степи Мулгора, — оскорбление, требующее немедленного и твердого ответа."},sec={{t="Незваные гости в холмах",b="К северо-западу от Деревни Кровавого Копыта дворфы-старатели начали обустраивать место раскопок среди холмов Мулгора. Лига исследователей и ее землекопы ищут по всему Калимдору реликвии титанов и тайны земли, но их работа редко уважает земли и обычаи коренных жителей. Для тауренов земля — живая мать, которую следует почитать, а не истощать и выдалбливать ради камня и металла."},{t="Защита священной земли",b="Бейн Кровавое Копыто понимает, что дворфийские машины и беспрестанные взрывы угрожают хрупкой гармонии равнин. Помимо разрушений, шум тревожит местных зверей и приводит кодо равнин в ярость. Разбив инструменты старателей у их же горнов, таурены надеются послать недвусмысленное предупреждение и остановить вторжение, пока не нанесен непоправимый вред."}},faq={{q="Зачем дворфы копают в Мулгоре?",a="Дворфы-старатели считают, что в недрах центрального Калимдора скрыты тайны и артефакты. Однако пренебрежение к землям племен и разрушительные методы добычи привели их к прямому конфликту с тауренами.",al={"dwarves in mulgore","why are prospectors here","dwarven excavation mulgore","дворфы в мулгоре","зачем здесь старатели","дворфийские раскопки мулгор"}},{q="Кто выдает задание «Дворфийские делишки»?",a="Задание выдает Бейн Кровавое Копыто, юный сын верховного вождя Кэрна Кровавого Копыта, в Деревне Кровавого Копыта в центре Мулгора.",al={"quest giver dwarven digging","who starts dwarven digging","кто выдает задание дворфийские делишки","кто начинает дворфийские делишки"}},{q="Почему Бейн хочет разбить инструменты, а не просто украсть?",a="Бейн хочет сделать снаряжение совершенно бесполезным, чтобы немедленно остановить раскопки. Уничтожение инструментов в горнах — ясное символическое и практическое послание: земля не раскроет свои тайны грубой силе и осквернению.",al={"why break the picks","smashing dwarven tools","зачем ломать кирки","разбить дворфийские инструменты"}},{q="Как раскопки влияют на животных Мулгора?",a="Громкий стук и глубокие раны на земле сильно тревожат местных существ, особенно огромных кодо, бродящих по холмам, и мирные стада становятся раздражительными и агрессивными.",al={"angry kodos","why are beasts mad","злые кодо","почему звери злятся"}},{q="Где можно разбить кирки?",a="Кирки можно перековать в обломки в любом действующем горне. Можно воспользоваться горном прямо в лагере дворфов-раскопщиков или отнести кирки кузнецам в Громовом Утесе.",al={"where is the forge","smash prospector picks forge","где горн","разбить кирки старателей в горне"}},{q="Связано ли это задание с общим присутствием Лиги исследователей в Калимдоре?",a="Да. Дворфийские экспедиции из Стальгорна основали форпосты по всему Калимдору, включая Мулгор, Степи и южный Калимдор, и нередко затевают стычки с расами Орды из-за власти над землями и священными местами.",al={"explorers league mulgore","ironforge in kalimdor","лига исследователей мулгор","стальгорн в калимдоре"}}},fp="15,289,24.392.0,26.388.0,35.232.0,36.137.0,63.245.0,52.187.0,31.201.0,75.232.0"}
P.entries["quest:747"] = {n="Охота начинается",s="«Охота начинается» — основополагающий обряд посвящения для юных искателей приключений в Лагере Нараче на Плато Красного Облака. По поручению Грулла Соколиного Ветра новички отправляются охотиться на местных степных ходоков, чтобы добыть мясо и перья для поселения. Это задание — первый шаг к уважению вождя Соколиного Ветра и будущему доступу в Громовой Утес.",h="«Охота начинается» — основополагающий обряд посвящения для юных искателей приключений в Лагере Нараче на...",kw={"camp narache","chief hawkwind","feathers","grull hawkwind","hunt begins","mulgore","plainstrider","red cloud mesa","лагерь нараче","вождь соколиный ветер","перья","грулл соколиный ветер","охота начинается","мулгор","степной ходок","плато красного облака"},ang={["class:Hunter"]="Выслеживание быстрых степных ходоков Плато Красного Облака — первое практическое упражнение в меткости, выслеживании и уважении к зверям, которые вас кормят.",["race:Tauren"]="Для юных шу'хало первая добыча — степной ходок плато — важный обряд посвящения: он подтверждает вашу связь с землей и долг кормить Лагерь Нараче."},sec={{t="Пропитание племени",b="На высотах Плато Красного Облака выживание и традиции неразделимы. Таурены охотятся по необходимости, чтобы кормить и одевать свой народ, а выслеживание и погоню считают также важным испытанием дисциплины и спортом. Когда запасы Лагеря Нараче оскудевают, община рассчитывает на молодежь, которая добудет свежее мясо ходоков для готовки и прочные перья для одежды племени."},{t="Заслужить признание",b="Ни один будущий герой не уйдет с Плато Красного Облака в просторы Мулгора, не доказав своей ценности. Грулл Соколиный Ветер — главный судья характера новичков, и он настаивает, что нужно доказать свои способности, прежде чем предстать перед его отцом, вождем Соколиным Ветром. Удачная охота показывает не только самостоятельность, но и преданность делу племени."}},faq={{q="Кто выдает это задание?",a="Это задание выдает Грулл Соколиный Ветер в Лагере Нараче. Он сын предводителя поселения, вождя Соколиного Ветра, и наставник молодых охотников и искателей приключений на Плато Красного Облака.",al={"quest giver","who starts the hunt begins","grull hawkwind","персонаж, выдающий задания","кто начинает охота начинается","грулл соколиный ветер"}},{q="Почему охотятся именно на степных ходоков, а не на других зверей?",a="Степных ходоков на плато много, и они дают питательное мясо, чтобы пополнить скудеющие запасы, и прочные перья для традиционной одежды и украшений тауренов.",al={"why plainstriders","plainstrider meat and feathers","hunting plainstriders","почему степные ходоки","мясо и перья ходоков","охота на ходоков"}},{q="Почему я должен доказывать свою ценность, прежде чем увижу вождя Соколиного Ветра?",a="Общество тауренов высоко ценит практическую пользу и охотничье мастерство. Грулл Соколиный Ветер требует от новичков показать навыки выживания и верность поселению, прежде чем вождь примет их и доверит им более важные дела.",al={"why prove to chief hawkwind","chief hawkwind approval","why hunt first","зачем доказывать вождю соколиному ветру","одобрение вождя соколиного ветра","почему сначала охота"}},{q="Какова общая цель этих испытаний на Плато Красного Облака?",a="Плато служит испытательной площадкой. Когда молодой таурен докажет свои способности вождю Соколиному Ветру и старейшинам Лагеря Нараче, он считается готовым спуститься в просторы Мулгора и войти в столицу — Громовой Утес.",al={"mesa trials purpose","why am i on red cloud mesa","leaving red cloud mesa","цель испытаний плато","почему я на плато красного облака","покинуть плато красного облака"}},{q="Что будет после этой охоты?",a="Если принести мясо и перья, Грулл одобрит это, и начнется задание «Охота продолжается», в котором новички выслеживают более крупную и неуловимую дичь на плато.",al={"next quest","followup","what is after the hunt begins","следующее задание","продолжение","что после охота начинается"}},{q="Охотятся ли таурены только ради выживания?",a="Хотя пропитание и ресурсы вроде кожи, кости и перьев необходимы, таурены также охотятся ради спорта и духовного единения, оттачивая чутье, которое делает племена бдительными и сильными.",al={"tauren hunting philosophy","hunt for sport","why do tauren hunt","философия охоты тауренов","охота ради спорта","зачем таурены охотятся"}}},fp="15,361,20.383.0,19.382.0,21.181.0,53.182.0,59.252.0,59.239.0,27.181.0,33.203.0"}
P.entries["quest:748"] = {n="Отравленная вода",s="Задание «Отравленная вода» открывает усилия таурен по очищению священных колодцев Мулгора от загрязнения. Муллу Громовому Рогу в Деревне Кровавого Копыта помогают молодые защитники Орды: они собирают в степях природные компоненты, чтобы создать целительный ритуальный тотем.",h="Задание «Отравленная вода» открывает усилия таурен по очищению священных колодцев Мулгора от загрязнения.",kw={"bloodhoof village","cleansing totem","mulgore","mull thunderhorn","plainstrider","poison water","prairie wolf","winterhoof water well","деревня кровавого копыта","тотем очищения","мулгор","мулл громовой рог","бегун по равнинам","отравленная вода","луговой волк","колодец заиндевевшего копыта"},ang={["class:Druid"]="Отравление чистых источников гоблинами — прямое нападение на природное равновесие, требующее немедленного ответа ради защиты хрупкой флоры и фауны Мулгора.",["class:Shaman"]="Очищение отравленных вод с помощью тотемов, наделенных силой зверей, показывает основы шаманства таурен: работать вместе с местной природой, чтобы исправлять нарушения стихий.",["race:Tauren"]="Осквернение чистой воды бьет в самую суть даров Матери-Земли, поэтому обряд очищения — основной долг любого тауренна, достигшего зрелости в Мулгоре."},sec={{t="Оскверненная земля",b="Травянистые равнины Мулгора — священная земля для таурен, но коварные силы начали угрожать их жизненно важному источнику. Мулл Громовой Рог, старейшина Деревни Кровавого Копыта, обнаруживает, что гоблины-чужаки и их прихвостни отравили драгоценные колодцы, которые поддерживают жизнь племен и местных животных. Загрязнение бьет прямо в духовное сердце кочевого народа, недавно поселившегося здесь."},{t="Сбор природной сущности",b="Чтобы противостоять промышленным загрязнениям, Мулл полагается на традиционное шаманство таурен, а не на грубые средства. Для очищения Колодца Заиндевевшего Копыта нужно создать мощный ритуальный тотем, наполненный жизненной силой коренных хищников Мулгора. Он посылает охотников добыть лапы луговых волков и когти взрослых бегунов по равнинам на юго-западных равнинах, призывая силу земли исцелить собственные раны."}},faq={{q="Кто отравил колодцы в Мулгоре?",a="За осквернение священных водопоев по всему Мулгору отвечают гоблины-захватчики и их наемники. Их разрушительная промышленная деятельность и пренебрежение природным равновесием угрожают и племенам таурен, и местным животным.",al={"who tainted the wells","who poisoned mulgore","who polluted the water","кто осквернил колодцы","кто отравил мулгор","кто загрязнил воду"}},{q="Зачем Муллу Громовому Рогу нужны волчьи лапы и когти бегунов по равнинам?",a="Мулл создает традиционные очищающие тотемы из частей местных зверей Мулгора. Используя природных духов и силу хищников равнин, он создает фокус, достаточно мощный для ритуала очищения воды.",al={"why wolf paws","why plainstrider talons","totem materials","зачем волчьи лапы","зачем когти бегуна по равнинам","материалы для тотема"}},{q="Какой колодец готовится очистить это задание?",a="В этом задании собирают материалы специально для создания очищающего тотема для Колодца Заиндевевшего Копыта — первого в череде загрязненных колодцев, которым требуется ритуальное очищение.",al={"what well is this for","which water well","для какого колодца это","какой колодец"}},{q="Где находится Мулл Громовой Рог?",a="Мулл Громовой Рог живет в Деревне Кровавого Копыта — главном поселении таурен в центральной части Мулгора, у вод Озера Каменного Быка.",al={"mull thunderhorn location","where is mull","where to turn in poison water","где мулл громовой рог","где мулл","куда сдать отравленная вода"}},{q="Где найти нужных волков и бегунов по равнинам?",a="Луговые волки и взрослые бегуны по равнинам бродят по холмистым равнинам к юго-западу от Деревни Кровавого Копыта.",al={"where to find prairie wolves","plainstrider location","hunting grounds","где найти луговых волков","где бегуны по равнинам","места охоты"}},{q="Что произойдет после того, как Мулл получит лапы и когти?",a="Мулл соединяет собранные компоненты в Тотем очищения колодца Заиндевевшего Копыта и поручает вам отнести его прямо к Колодцу Заиндевевшего Копыта, чтобы провести обряд очищения.",al={"next quest after poison water","what do i do next","следующее задание после отравленная вода","что делать дальше"}}},fp="12,238,17.428.0,26.435.0,40.234.0,65.236.0,46.172.0,34.141.0,58.96.0,53.172.0"}
P.entries["quest:749"] = {n="Разграбленный караван",s="Морин Ловец Облаков направляет путников осмотреть обломки разгромленного каравана Торговой Компании у северного берега Озера Каменного Быка. Хотя таурены сожгли обоз в отместку за павших товарищей, гоблины-старатели вернулись за уцелевшим грузом. Осмотр уцелевших ящиков с припасами показывает истинный промышленный размах деятельности Торговой Компании в Мулгоре.",h="Морин Ловец Облаков направляет путников осмотреть обломки разгромленного каравана Торговой Компании у...",kw={"morin cloudstalker","mulgore","ravaged caravan","stonebull lake","supply crate","venture co","venture company","морин ловец облаков","мулгор","разграбленный караван","озеро каменного быка","ящик с припасами","торговая компания"},ang={["faction:Horde"]="Бесконтрольная корпоративная экспансия в Мулгор угрожает стабильности Громового Утеса, и разведчикам Орды необходимо нарушать снабжение Торговой Компании.",["profession:Mining"]="Прочные ящики и заметки о снабжении показывают, что Торговая Компания ведет по всему Мулгору активную разведку и добычу полезных ископаемых.",["race:Tauren"]="Осквернение равнин машинами Торговой Компании и вырубка леса бьют прямо по земле ваших предков, поэтому возврат и уничтожение их припасов жизненно важны для защиты Мулгора."},sec={{t="Возмездие у озера",b="Обугленные остатки на северном берегу Озера Каменного Быка — результат быстрого удара таурен. Скорбя о двух товарищах, погибших в недавней стычке, Морин Ловец Облаков и его воины устроили засаду на вооруженный обоз Торговой Компании. Желая уничтожить плоды трудов чужаков, таурены сожгли повозки и оставили дымящиеся руины, полагая, что огонь поглотит все, что гоблины хотели увезти."},{t="Незаконченное дело",b="Вскоре таурены заметили, что старатели Торговой Компании роются в почерневших обломках, а значит, огонь не уничтожил самый важный груз. Не желая слепо рисковать жизнями, Морин посылает разведчиков осмотреть место. Среди закопченных обломков лежат целые ящики с эмблемой горного отдела Торговой Компании, упакованные и предназначенные для центральных перерабатывающих мощностей."}},faq={{q="Почему караван был уничтожен?",a="Морин Ловец Облаков и его воины-таурены напали на караван из засады и сожгли его в отместку за двух разведчиков, погибших в прежней стычке с Торговой Компанией.",al={"who destroyed the caravan","why is the caravan burned","caravan attack","кто уничтожил караван","почему караван сожжен","нападение на караван"}},{q="Где находится Разграбленный караван?",a="Сожженные повозки стоят на северном берегу Озера Каменного Быка, к востоку от Деревни Кровавого Копыта в Мулгоре.",al={"caravan location","where is the caravan","ravaged caravan spot","где караван","расположение каравана","разграбленный караван"}},{q="Почему гоблины возвращаются к обломкам?",a="Торговая Компания отправила старателей, потому что огонь уничтожил не весь груз. Они пытаются забрать прочные ящики с припасами, помеченные для отправки на их центральные перерабатывающие предприятия.",al={"why are salvagers here","venture co salvagers","what do the goblins want","зачем здесь старатели","старатели торговой компании","что нужно гоблинам"}},{q="Что лежит в ящиках с припасами?",a="На ящиках стоит эмблема горного отдела Торговой Компании; внутри — минеральные ресурсы, предназначенные для очистки и переработки на их главных промышленных предприятиях.",al={"crate contents","what is in the crate","sealed supply crate","содержимое ящика","что в ящике","запечатанный ящик с припасами"}},{q="Кто такой Морин Ловец Облаков?",a="Морин Ловец Облаков — таурен-разведчик и следопыт, находящийся к востоку от Деревни Кровавого Копыта. Он следит за вражескими вторжениями в центральный Мулгор, в особенности со стороны Торговой Компании.",al={"who is morin","morin cloudstalker role","кто такой морин","морин ловец облаков роль"}},{q="Что этот караван говорит о Торговой Компании?",a="Он показывает, что присутствие Торговой Компании в Мулгоре — не просто разведывательный отряд, а организованная промышленная добыча с вооруженными линиями снабжения и централизованной сетью переработки.",al={"venture co mulgore presence","why are goblins in mulgore","торговая компания в мулгоре","почему гоблины в мулгоре"}}},fp="19,390,23.438.0,19.408.0,30.169.0,37.102.0,46.197.0,33.171.0,26.190.0,56.201.0"}
P.entries["quest:7493"] = {n="Все еще только начинается!",s="«Все еще только начинается!» — задание Орды, которое выдают в Оргриммаре опытным кожевникам после победы над Ониксией. Властитель Рунтак признает мастерство героя и обучает редкому способу изготовления защитных плащей из чешуи матери драконов. Это важное ремесло готовит Орду к смертоносному пламени Вершины Черной горы.",h="«Все еще только начинается!» — задание Орды, которое выдают в Оргриммаре опытным кожевникам после победы над...",kw={"blackrock","broodmother","cloak","leatherworking","natoj","nefarian","onyxia","scale","черная гора","мать драконов","плащ","кожевничество","нефариан","ониксия","чешуя"},ang={["faction:Horde"]="Для Орды защитное снаряжение, выкованное из павших врагов, жизненно важно для защиты войск от новых драконьих разрушений."},sec={{t="Наследие матери драконов",b="Падение Ониксии — триумф Орды, но не конец угрозы со стороны черного драконьего рода. Чешуйчатая шкура матери драконов обладает замечательной стойкостью к драконьему пламени. Чтобы такие материалы не пропали зря, руководство Орды ищет мастеров, способных превратить останки дракона в защитные доспехи."},{t="Щит от пламени Тени",b="Властитель Рунтак учит одаренных кожевников сшивать Плащ из чешуи Ониксии. Эти знания нужны не для показа или престижа. В глубине Черной горы брат Ониксии, Нефариан, обладает разрушительным пламенным дыханием. Без зачарованной защиты из чешуи собственной матери любой авангард, выступивший против Владыки Черной горы, обратился бы в пепел."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Властитель Рунтак в Оргриммаре. Он признает защитников Орды, владеющих мастерством кожевника высшего уровня и помогавших в низвержении Ониксии.",al={"natoj quest giver","where is overlord natoj","quest start","кто выдает задание","где властитель рунтак","начало задания"}},{q="Что нужно для получения этого задания?",a="Это задание предлагают только опытным кожевникам, которые выполнили одно из заданий, следующих за победой над Ониксией, например «Победа Орды» или «Весьма загадочное обстоятельство».",al={"leatherworking requirement","how to get quest","prerequisites","требование кожевничества","как получить задание","необходимые условия"}},{q="Чему учит Властитель Рунтак?",a="Властитель Рунтак обучает кожевника способу изготовления Плаща из чешуи Ониксии из чешуи, собранной с павшей матери драконов.",al={"quest reward recipe","onyxia cloak pattern","what do i learn","рецепт награды","выкройка плаща ониксии","что я изучу"}},{q="Почему важен Плащ из чешуи Ониксии?",a="Плащ защищает владельца от смертоносного пламенного дыхания Нефариана, Владыки Черной горы. Без его особых защитных свойств встреча с повелителем рода была бы смертельной.",al={"why make cloak","cloak purpose","nefarian cloak","зачем делать плащ","назначение плаща","плащ от нефариана"}},{q="Кто такой Владыка Черной горы?",a="Владыка Черной горы — Нефариан, могучий черный дракон и брат Ониксии, который строит планы с высот Черной горы, чтобы подчинить смертные расы.",al={"who is lord of blackrock","nefarian identity","blackrock lord","кто такой владыка черной горы","кто такой нефариан","владыка черной горы"}},{q="Почему в названии задания сказано, что все только начинается?",a="Хотя Ониксия убита, более широкая война против черного драконьего рода и замыслы Нефариана внутри Черной горы лишь обострились.",al={"meaning of title","journey just begun why","значение названия","почему все только начинается"}}},fp="26,347,22.359.0,27.396.1,49.178.0,49.183.0,33.152.0,40.186.0,29.159.0,57.145.0"}
P.entries["quest:7497"] = {n="Все еще только начинается!",s="Это задание — заслуженное признание опытного мастера после победы над Ониксией. Майор Маттингли передает важный способ изготовления Плаща из чешуи Ониксии, превращая останки павшей матери драконов в необходимую защиту от ее брата.",h="Это задание — заслуженное признание опытного мастера после победы над Ониксией.",kw={"black dragonflight","blackrock","leatherworking","major mattingly","nefarian","onyxia","onyxia scale cloak","stormwind","черный драконий род","черная гора","кожевничество","майор маттингли","нефариан","ониксия","плащ из чешуи ониксии","штормград"},ang={["faction:Alliance"]="Это задание связывает нелегкую победу Штормграда над Ониксией с грядущим наступлением на ее брата Нефариана в Черной горе."},sec={{t="Редкое мастерство",b="Многие герои могут претендовать на победу над матерью драконов Ониксией, но лишь немногие сочетают боевую доблесть и мастерство кожевника высшего уровня, необходимое для работы с ее прочной шкурой. Когда герой с такими талантами докладывает Майору Маттингли в Штормграде, офицер признает, как важны эти ремесленные навыки для грядущих сражений."},{t="Защита от черного драконьего рода",b="Смерть Ониксии не отменяет угрозы черного драконьего рода. Маттингли учит мастера обрабатывать и сшивать чешую матери драконов в Плащ из чешуи Ониксии. Эта уникальная вещь дает особую защиту от разрушительного пламенного дыхания брата Ониксии, Нефариана, Владыки Черной горы."}},faq={{q="Кто выдает задание «Все еще только начинается!»?",a="Майор Маттингли в Штормграде выдает это задание героям Альянса, проявившим себя в походе против Ониксии и владеющим кожевничеством высшего уровня.",al={"who gives the journey has just begun","where to get journey has just begun","journey has just begun quest giver","кто дает все еще только начинается","где взять все еще только начинается","выдающий задание все еще только начинается"}},{q="Чему учит это задание?",a="Выполнение задания обучает мастеров-кожевников рецепту Плаща из чешуи Ониксии — вещи, созданной специально из чешуи Ониксии.",al={"what recipe do i get","onyxia cloak recipe","reward for journey has just begun","какой рецепт я получу","рецепт плаща ониксии","награда за все еще только начинается"}},{q="Почему нужен Плащ из чешуи Ониксии?",a="Плащ особо обработан, чтобы защищать владельца от смертоносного пламенного дыхания Нефариана, Владыки Черной горы, и потому незаменим в борьбе с оставшимися предводителями черного драконьего рода.",al={"why do i need onyxia cloak","what is onyxia scale cloak for","shadow flame protection","зачем нужен плащ ониксии","для чего плащ из чешуи ониксии","защита от пламени тени"}},{q="Кто такой Владыка Черной горы, упомянутый Майором Маттингли?",a="Владыка Черной горы — Нефариан, могучий черный дракон и брат Ониксии. Он правит Вершиной Черной горы и продолжает замыслы черного драконьего рода.",al={"who is lord of blackrock","who is nefarian","mattingly dragon warning","кто такой владыка черной горы","кто такой нефариан","предупреждение маттингли о драконе"}},{q="Почему герой должен быть кожевником, чтобы получить эти знания?",a="Способы добычи, закалки и сшивания драконьей чешуи без потери ее природной магической защиты требуют высокого мастерства опытного кожевника.",al={"why leatherworking only","can anyone get this quest","leatherworker requirement","почему только кожевничество","кто может получить задание","требование кожевника"}},{q="Покончила ли смерть Ониксии с угрозой черных драконов для Штормграда?",a="Нет. Хотя сама Ониксия убита, ее брат Нефариан по-прежнему повелевает Черной горой и продолжает плести заговоры против Альянса и смертных рас.",al={"is stormwind safe now","onyxia dead what next","black dragonflight after onyxia","безопасен ли штормград","ониксия мертва что дальше","черный драконий род после ониксии"}}},fp="26,276,14.360.0,41.323.1,48.169.0,27.153.0,40.206.0,58.168.0,63.179.0,65.161.1"}
P.entries["quest:751"] = {n="Разграбленный караван",s="Осмотр разбитого каравана в Мулгоре показывает, что гоблины-промышленники незаконно закрепились на землях тауренов. Разведчики достали документы из запертого ящика и подтвердили, что Торговая Компания планомерно вычерпывает минеральные богатства края. Это открытие побуждает Бегунов Кровавого Копыта встать на активную оборону родных равнин.",h="Осмотр разбитого каравана в Мулгоре показывает, что гоблины-промышленники незаконно закрепились на землях...",kw={"bloodhoof village","morin cloudstalker","mulgore","outrunners","ravaged caravan","supply crate","venture co","venture co documents","деревня кровавого копыта","морин ловец облаков","мулгор","бегуны","разграбленный караван","ящик с припасами","торговая компания","документы торговой компании"},ang={["class:Druid"]="Для друидов равновесие земли священно, поэтому разрушительная, задымленная открытая добыча Торговой Компании — осквернение, которое необходимо очистить.",["faction:Horde"]="Орда полагается на верность и устойчивость Мулгора; если позволить чужеземным торговым картелям разорять его холмы, под угрозой окажется безопасность самого Громового Утеса.",["profession:Mining"]="Высокосортная руда в ящике доказывает, что восточные холмы Мулгора скрывают богатые подземные жилы, которые чужаки спешат захватить.",["race:Tauren"]="Для тауренов вид грубых промышленных машин, вгрызающихся в родные равнины Мулгора, — оскорбление Матери-Земли и акт войны против их недавно обретенного мира."},sec={{t="Свидетельства эксплуатации",b="Обломки разграбленного каравана к востоку от Деревни Кровавого Копыта рассказывают тревожную историю. В запертом ящике с припасами лежит плотный запас добытой руды и минералов, а также связка документов Торговой Компании. Эти бумаги — неопровержимое доказательство того, что алчная Торговая Компания начала самовольную добычу в безмятежных долинах Мулгора."},{t="Дозор Бегунов",b="Морин Ловец Облаков и другие Бегуны осторожно следят за границами Мулгора, остерегаясь чужаков, желающих поживиться за счет их мирной родины. Доставленные документы подтверждают худшие опасения Морина: дым над восточными предгорьями — знак растущего коммерческого вторжения. У тауренов нет выбора, кроме как дать отпор осквернителям, пока их холмы не выпотрошили целиком."}},faq={{q="Что лежит в запертом ящике с припасами?",a="Вскрыв ящик, вы найдете плотный набор добытой руды, сырых минералов и связку документов Торговой Компании с описанием ее деятельности.",al={"supply crate loot","what is in the crate","crate contents","добыча из ящика","что в ящике","содержимое ящика"}},{q="Кто такой Морин Ловец Облаков?",a="Морин Ловец Облаков — таурен-Бегун, стоящий на дороге к востоку от Деревни Кровавого Копыта в сторону границы Степей. Он патрулирует Мулгор и выслеживает внешние угрозы.",al={"who is morin","morin cloudstalker role","outrunner morin","кто такой морин","морин ловец облаков","бегун морин"}},{q="Почему Торговая Компания в Мулгоре?",a="Торговая Компания стремится безжалостно использовать богатые природные ресурсы и рудные жилы Мулгора, вгрызаясь в холмы без оглядки на землю и ее коренной народ.",al={"why are goblins here","venture co goal mulgore","what do goblins want","почему здесь гоблины","цель торговой компании мулгор","чего хотят гоблины"}},{q="Откуда шел караван?",a="Караван принадлежал Торговой Компании и вез добытую руду и рабочие бумаги из ее предгорных рудников, пока не был уничтожен на дороге.",al={"whose caravan was it","caravan origin","who attacked the caravan","чей это караван","происхождение каравана","кто напал на караван"}},{q="Куда ведет расследование дальше?",a="Получив документы, Морин Ловец Облаков направляет воинов прямо к руководству Торговой Компании, чтобы свернуть ее добычу в восточных предгорьях.",al={"what comes next","next quest after ravaged caravan","following up on the caravan","что дальше","следующее задание после разграбленного каравана","продолжение истории каравана"}},{q="Почему это угрожает тауренам?",a="Таурены считают землю священной и почитают Мать-Землю. Безрассудная открытая добыча и промышленные отходы Торговой Компании оскверняют нетронутые пейзажи Мулгора.",al={"why do tauren care","venture co threat","threat to mulgore","почему тауренам не все равно","угроза торговой компании","угроза мулгору"}}},fp="19,373,24.371.0,21.434.0,39.146.0,26.176.0,38.180.0,32.169.0,40.178.1,34.178.0"}
P.entries["quest:752"] = {n="Скромная просьба",s="Скромная просьба — один из первых обрядов долга, который дает вождь Соколиный Ветер в Лагере Нараче. Пока вождь занят неотложными делами племени на Плато Красного Облака, он просит молодого искателя приключений отправиться на юго-восток и проведать его престарелую мать у местного колодца. Просьба подчеркивает общинную ответственность, почтение к старшим и повседневную гармонию, важную для жизни тауренов.",h="Скромная просьба — один из первых обрядов долга, который дает вождь Соколиный Ветер в Лагере Нараче.",kw={"a humble task","camp narache","chief hawkwind","greatmother hawkwind","mulgore","red cloud mesa","water well","скромная просьба","лагерь нараче","вождь соколиный ветер","великая мать соколиный ветер","мулгор","плато красного облака","колодец"},ang={["faction:Horde"]="Тихий, пасторальный характер заданий Нараче показывает, как мирная общинная философия тауренов контрастирует с более суровой, выживальческой жесткостью остальной молодой Орды.",["race:Tauren"]="Для юных тауренов-воинов отклик на призыв вождя воплощает главные основы учения Матери-Земли: уважение к старшим и безоговорочную преданность общему благополучию племени."},sec={{t="Общинная гармония и долг",b="В тени Лагеря Нараче от каждого члена племени ждут, что он внесет свой вклад в гармонию жизни. Для молодых тауренов, вступающих во взрослую жизнь, долг перед племенем измеряется не только боевой доблестью в схватках со свинобразами и хищниками: он начинается с простой социальной ответственности. Вождь Соколиный Ветер показывает это на деле: прикованный к посту управлением и обороной, он доверяет начинающим искателям приключений присмотр за уязвимыми старейшинами общины."},{t="Колодец к юго-востоку от Нараче",b="Плато Красного Облака в Мулгоре полагается на природные колодцы, разбросанные за пределами лагеря. Рано утром Великая Мать Соколиный Ветер ушла из деревни, чтобы набрать свежей воды из юго-восточного источника. В краю, где бродят территориальные звери и подступают свинобразы-Дыбогривы, отсутствие старейшины в течение нескольких часов вызывает тихую тревогу, и Соколиный Ветер посылает помощь, чтобы убедиться, что она невредима."}},faq={{q="Кто дает это задание и где его найти?",a="Задание дает вождь Соколиный Ветер, предводитель Лагеря Нараче на Плато Красного Облака в Мулгоре. Он стоит в центральном шатре лагеря и руководит местными делами.",al={"who gives a humble task","where to pick up quest","chief hawkwind location","кто дает скромную просьбу","где взять задание","где вождь соколиный ветер"}},{q="Где находится Великая Мать Соколиный Ветер?",a="Великая Мать Соколиный Ветер находится к юго-востоку от Лагеря Нараче: она хлопочет у колодца на нижнем уступе плато.",al={"greatmother hawkwind location","where is the mother","water well location","где великая мать соколиный ветер","где мать вождя","где колодец"}},{q="Почему вождь Соколиный Ветер не проведает мать сам?",a="Вождь Соколиный Ветер должен оставаться в Лагере Нараче, чтобы заниматься неотложными делами племени и наставлять молодых воинов. Как вождь, он опирается на общую ответственность племени и доверяет подающим надежды искателям приключений заботу о делах деревни.",al={"why cant chief go","why doesn't hawkwind check","chief hawkwind busy","почему вождь не может пойти","почему соколиный ветер не проверит","вождь соколиный ветер занят"}},{q="Грозит ли Великой Матери Соколиному Ветру опасность у колодца?",a="Хотя на окрестных равнинах водятся агрессивные горные пумы и долгоножки, Великая Мать Соколиный Ветер цела и невредима у колодца и приятно удивлена, что кто-то потрудился проведать старейшину.",al={"is she safe","is greatmother attacked","danger at water well","она в безопасности","напали ли на великую мать","опасность у колодца"}},{q="Какое культурное значение это задание имеет для тауренов?",a="Культура тауренов высоко ценит семью, сплоченность общины и почтение к старшим. Задание учит юных героев, что истинная сила — в скромном служении и защите своих близких, а не в погоне за личной славой.",al={"tauren culture humble task","why is this a humble task","tauren elders","культура тауренов скромная просьба","почему просьба скромная","старейшины тауренов"}},{q="Что будет после того, как вы найдете Великую Мать Соколиного Ветра?",a="Когда вы поговорите с Великой Матерью Соколиным Ветром, она завершает дело и просит о дальнейшей помощи: отнести наполненный кувшин с водой обратно в лагерь.",al={"next quest","a humble task follow up","what to do after finding mother","следующее задание","продолжение скромной просьбы","что делать после встречи с матерью"}}},fp="13,384,25.487.0,29.432.0,47.166.0,38.125.0,55.242.0,46.215.0,64.231.0,48.151.0"}
P.entries["quest:753"] = {n="Скромная просьба",s="«Скромная просьба» — вводный обряд служения на Плато Красного Облака, где старейшина проверяет смирение и усердие начинающего искателя приключений. Принося свежую колодезную воду через равнины вождю Лагеря Нараче, юные таурены узнают, что служение своему народу начинается с простейших обязанностей.",h="«Скромная просьба» — вводный обряд служения на Плато Красного Облака, где старейшина проверяет смирение и...",kw={"camp narache","chief hawkwind","greatmother hawkwind","humble task","mulgore","red cloud mesa","rites of the earthmother","water pitcher","лагерь нараче","вождь соколиный ветер","великая мать соколиный ветер","скромная просьба","мулгор","плато красного облака","обряды матери-земли","кувшин с водой"},ang={["faction:Horde"]="Уроки рода Соколиного Ветра показывают, как таурены сохраняют сплоченность и выживают в Мулгоре, образуя мирную, но непреклонную опору Орды Тралла.",["race:Tauren"]="Приносить воду старейшинам — основа тауренской добродетели заботы об общине, и это показывает, что вы готовы пойти путем Матери-Земли."},sec={{t="Жизненная сила молодости",b="Великая Мать Соколиный Ветер прошла много троп за свою долгую жизнь, и хотя ее дух остается твердым, ноги уже не несут ее по равнинам так быстро, как в молодости. Она находится у колодца на южных окраинах Плато Красного Облака и терпеливо исполняет свои обязанности. Когда на ее пути оказываются будущие защитники племени, она направляет их юную энергию на практические нужды общины, давая возможность доказать свою ценность службой, а не насилием."},{t="Служение племени",b="Посвящаемому нужно принести наполненный кувшин с водой на северо-запад, в Лагерь Нараче, и вручить его лично вождю поселения, вождю Соколиному Ветру, который приходится сыном Великой Матери. В обществе тауренов выживание на засушливых равнинах Мулгора требует общего труда и надежных запасов свежей воды. Уважение к старейшинам общины и готовность взять на себя их заботы считаются основой того, чтобы стать настоящим защитником племени."},{t="Путь к Громовому Утесу",b="Вождь Соколиный Ветер видит в пришедшем молодом страннике, принесшем воду от его матери, не просто выполненную работу. По обычаю тауренов, готовность отстаивать свой народ на дальних землях начинается со смирения и неподсказанного желания помочь. Проявив эту тихую дисциплину, посвящаемый привлекает внимание вождя и получает рекомендацию для древних Обрядов Матери-Земли — настоящих духовных испытаний, открывающих врата Громового Утеса."}},faq={{q="Кто такая Великая Мать Соколиный Ветер?",a="Великая Мать Соколиный Ветер — старейшина рода Соколиного Ветра, находящаяся у колодца на Плато Красного Облака. Она мать вождя Лагеря Нараче, вождя Соколиного Ветра, и наставляет молодых тауренов в смирении и племенных ценностях.",al={"greatmother hawkwind","who gives a humble task","hawkwind elder","великая мать соколиный ветер","кто выдает скромную просьбу","старейшина соколиный ветер"}},{q="Где находится колодец?",a="Колодец расположен к юго-востоку от Лагеря Нараче на травянистых равнинах Плато Красного Облака. Рядом с ним стоят кувшины со свежей колодезной водой, которые путники и смотрители лагеря могут отнести обратно.",al={"water well location","where is the well","find water pitcher","расположение колодца","где колодец","найти кувшин с водой"}},{q="Кто такой вождь Соколиный Ветер?",a="Вождь Соколиный Ветер — предводитель, управляющий Лагерем Нараче на Плато Красного Облака. Он руководит обучением и духовными обрядами молодых тауренов, готовя их к тому, чтобы отправиться в путь и служить всему племени в Мулгоре.",al={"chief hawkwind","who is the chief","camp narache leader","вождь соколиный ветер","кто такой вождь","глава лагеря нараче"}},{q="Почему это поручение считается важным испытанием?",a="Культура тауренов высоко ценит смирение, поддержку общины и уважение к старейшинам. Выполнение неприметных повседневных обязанностей показывает, что искатель приключений заботится о существовании своего народа, а не только о личной славе в бою.",al={"why carry water","why humble task","is this quest important","зачем нести воду","зачем скромная просьба","важно ли это задание"}},{q="Что следует после выполнения задания «Скромная просьба»?",a="Выполнив это задание, вы докажете свою дисциплину вождю Соколиному Ветру, и он направит вас пройти Обряды Матери-Земли — череду традиционных испытаний, обязательных для всех тауренов, достигших совершеннолетия.",al={"what comes next","next quest","after humble task","что дальше","следующее задание","после скромной просьбы"}},{q="Куда в итоге ведет этот путь?",a="Уважение старейшин Лагеря Нараче готовит вас к тому, чтобы покинуть уединенное плато и отправиться на просторы равнин Мулгора, а в конечном счете — к высоким плато столицы, Громовому Утесу.",al={"future destination","where are we going","thunder bluff goal","дальнейший путь","куда идти","цель громовой утес"}}},fp="13,288,21.500.0,20.469.0,27.468.0,28.220.0,32.178.0,22.203.0,47.236.0,42.202.0,37.209.0"}
P.entries["quest:754"] = {n="Очищение колодца Заиндевевшего Копыта",s="«Очищение колодца Заиндевевшего Копыта» — обряд, который Мулл Громовой Рог в Деревне Кровавого Копыта поручает искателям приключений из Орды. После того как гоблины загрязнили местные источники, освященный тотем нужно доставить на территорию Торговой Компании, чтобы очистить Колодец Заиндевевшего Копыта. Восстановление этого источника — первый важный шаг к исцелению отравленных вод центрального Мулгора.",h="«Очищение колодца Заиндевевшего Копыта» — обряд, который Мулл Громовой Рог в Деревне Кровавого Копыта...",kw={"bloodhoof village","cleansing","mulgore","mull thunderhorn","poison","totem","venture company","water well","winterhoof","деревня кровавого копыта","очищение","мулгор","мулл громовой рог","яд","тотем","торговая компания","колодец","заиндевевшее копыто"},ang={["class:Druid"]="Немедленное возвращение жаждущих зверей к очищенному источнику доказывает, как необходимо исцелять природу везде, где цивилизация грозит ее опустошить.",["class:Shaman"]="Направлять духов через тотемы, чтобы обратить вспять неестественную промышленную скверну, — главная цель связи шамана со стихией воды.",["faction:Horde"]="Обеспечение Мулгора свежей водой укрепляет сердце земель недавно поселившихся тауренов и южную опору молодой Орды.",["race:Tauren"]="Колодцы Мулгора — священные дарители жизни, ниспосланные Матерью-Землей; защищать их от гоблинской жадности — и гражданский долг, и священная обязанность каждого таурена."},sec={{t="Опустошенная земля",b="Травянистые равнины Мулгора зависят от хрупкой сети древних колодцев, которые поддерживают и дичь, и разрозненные племена тауренов. Недавно безжалостные промышленные наемники Торговой Компании обосновались в холмах к юго-востоку от Деревни Кровавого Копыта. Их работы загрязнили местные водоносные слои, и Колодец Заиндевевшего Копыта стал затхлым и ядовитым. Дикие звери избегают испорченной воды, а соседним лагерям грозит беда, если порча распространится дальше в земле."},{t="Обряд очищения вод",b="Чтобы противостоять промышленной грязи, Мулл Громовой Рог вырезает и зачаровывает ритуальный тотем очищения, наполненный благословением Матери-Земли. Но доставить это средство можно, лишь одолев вооруженных громил Торговой Компании, захвативших источник. Установив тотем прямо у колодца, искатель приключений рассеивает зловонные стоки, и из глубин земли снова поднимается чистая, дарующая жизнь вода."}},faq={{q="Где находится Колодец Заиндевевшего Копыта?",a="Колодец Заиндевевшего Копыта находится в холмах к юго-востоку от Деревни Кровавого Копыта в Мулгоре. Его усиленно охраняют гоблины-рабочие и наемники, служащие Торговой Компании.",al={"winterhoof well location","where is winterhoof well","how to find winterhoof well","расположение колодца заиндевевшего копыта","где колодец заиндевевшего копыта","как найти колодец заиндевевшего копыта"}},{q="Почему колодец был отравлен?",a="Торговая Компания устроила поблизости горные и земляные работы, позволив токсичным промышленным стокам и отходам просачиваться прямо в водоносный слой, из-за чего природный источник стал непригоден для питья местным зверям и тауренам.",al={"who poisoned the water","why is the well dirty","venture company well","кто отравил воду","почему колодец грязный","торговая компания колодец"}},{q="Кто такой Мулл Громовой Рог?",a="Мулл Громовой Рог — духовный старейшина в Деревне Кровавого Копыта. Он глубоко чувствует состояние земли и создает обрядовые тотемы, чтобы исправить разрушения природы, причиненные чужаками.",al={"who is mull","mull thunderhorn role","кто такой мулл","мулл громовой рог роль"}},{q="Что происходит после очищения колодца?",a="Когда вода в Колодце Заиндевевшего Копыта становится чистой и звери снова безопасно пьют из него, Мулл Громовой Рог обращает ваше внимание на другие загрязненные колодцы Мулгора, начиная с Тотема Громового Рога.",al={"what comes next","after winterhoof cleansing","what does mull do next","что дальше","после очищения колодца заиндевевшего копыта","что мулл делает дальше"}},{q="Кто охраняет колодец?",a="Колодец занимают рабочие и наемники Торговой Компании — беспринципного синдиката под началом гоблинов, который истощает земли ради природных ресурсов, не заботясь о местной экосистеме.",al={"who guards winterhoof well","what enemies are at the well","кто охраняет колодец заиндевевшего копыта","какие враги у колодца"}},{q="Как действует тотем очищения?",a="Тотем, вырезанный с помощью священных обрядов тауренов и защитных ритуалов, черпает силу природных духов и благословение Матери-Земли, чтобы изгнать неестественные химические загрязнения из истока источника.",al={"cleansing totem lore","how does mull totem work","предание о тотеме очищения","как действует тотем мулла"}}},fp="20,358,16.505.0,30.432.0,43.191.0,32.227.0,24.205.0,40.212.1,31.195.0,34.192.0"}
P.entries["quest:756"] = {n="Тотем Громового Рога",s="«Тотем Громового Рога» — задание, которое Мулл Громовой Рог в Деревне Кровавого Копыта дает для создания священного тотема очищения. Чтобы бороться с гоблинским загрязнением колодцев Мулгора, юным защитникам Орды нужно собрать природные когти хищников равнин и связать первобытную силу земли с ритуальным деревом.",h="«Тотем Громового Рога» — задание, которое Мулл Громовой Рог в Деревне Кровавого Копыта дает для создания...",kw={"bloodhoof village","cleansing","cougar claws","flatland cougar","mulgore","mull thunderhorn","prairie stalker","stalker claws","thunderhorn totem","water well","деревня кровавого копыта","очищение","когти пумы","пума плоскогорья","мулгор","мулл громовой рог","луговой скрад","когти скрада","тотем громового рога","колодец"},ang={["class:Hunter"]="Чтобы собрать когти, нужно понимать местных подкрадывающихся зверей равнин и чтить добычу, сохраняя экосистему.",["class:Shaman"]="Восстановление с помощью тотемов основано на призыве живых духов земли, чтобы очистить воду, оскверненную неестественным, небрежным предпринимательством.",["race:Tauren"]="Защита водоносных слоев Мулгора от чужой эксплуатации — священный долг племени, отражающий завет Матери-Земли жить в равновесии, а не грабить."},sec={{t="Охота на хищников равнин",b="Пока промышленная эксплуатация Торговой Компании отравляет драгоценные источники воды Мулгора, Мулл Громовой Рог спешно трудится над средствами исцеления. Для создания Тотема очищения колодца Громового Рога нужны природные сущности самых целеустремленных охотников равнин: луговых скрадов и пум плоскогорья. Забирая когти этих хищников, бродящих к востоку и западу от Деревни Кровавого Копыта, обряд направляет необузданную, неиспорченную хищную мощь животных прямо в тотем."},{t="Природа охоты",b="Традиция тауренов проводит глубокое различие между охотой ради пропитания или духовного равновесия и повальным грабежом гоблинов. Мулл подчеркивает, что чистота, с которой охотятся местные хищники, жизненно важна для очищения оскверненной земли. Там, где гоблинские машины оскверняют источники маслом и промышленными отходами, природная сила зверей, борющихся с землей, дает духовный катализатор, нужный для восстановления Колодца Громового Рога."}},faq={{q="Зачем Муллу Громовому Рогу когти хищников?",a="Мулл использует когти луговых скрадов и пум плоскогорья, чтобы направить чистый первобытный дух хищников равнин в тотем очищения. Он верит, что чистый дух природных охотников противостоит искусственной промышленной порче.",al={"why claws","purpose of stalker claws","cougar claws purpose","зачем когти","для чего когти скрада","для чего когти пумы"}},{q="Кто портит воду в Мулгоре?",a="Гоблины Торговой Компании, работающие в Мулгоре, загрязняют землю и воду. Их безрассудная добыча ресурсов и буровые установки сбрасывают токсичную жижу в водоносные слои, питающие колодцы племен.",al={"who tainted the well","why is the well poisoned","what poisoned mulgore","кто испортил колодец","почему колодец отравлен","что отравило мулгор"}},{q="Где обитают луговые скрады и пумы плоскогорья?",a="Оба зверя бродят по открытым равнинам центрального Мулгора, в основном по холмистым саваннам к востоку и западу от Деревни Кровавого Копыта.",al={"stalker location","where to find cougars","cougar claw locations","где скрады","где найти пум","где взять когти пумы"}},{q="Что происходит после создания Тотема Громового Рога?",a="Когда Мулл вырезает и зачаровывает тотем с помощью когтей, он отправляет вас прямо к оскверненному Колодцу Громового Рога, чтобы провести обряд очищения и изгнать яд.",al={"what next","after thunderhorn totem","totem follow up","что дальше","после тотема громового рога","продолжение тотема"}},{q="Как это связано с предыдущим очищением колодца Заиндевевшего Копыта?",a="Это часть продолжающихся усилий племени по сохранению священных вод Мулгора. Колодец Заиндевевшего Копыта был очищен первым, а теперь загрязнение угрожает колодцу Громового Рога дальше на севере.",al={"winterhoof connection","previous totem quest","связь с колодцем заиндевевшего копыта","предыдущее задание с тотемом"}},{q="Почему таурены не используют просто травяные средства вместо звериных когтей?",a="Ритуальное мастерство тауренов опирается на различные стихийные и физические стороны природы. Острая чистота верховных хищников дает деятельную, борющуюся духовную силу, необходимую, чтобы пробиться сквозь агрессивные гоблинские промышленные яды.",al={"why not herbs","shamanic totem materials","почему не травы","материалы шаманских тотемов"}}},fp="17,307,28.469.0,22.465.0,46.237.0,39.200.0,58.146.0,50.174.1,66.195.0,72.236.0"}
P.entries["quest:757"] = {n="Обряд Силы",s="Обряд Силы — первое испытание в традиционных Обрядах Матери-Земли, которые проходят молодые таурены в Лагере Нараче. Чтобы доказать свою храбрость и готовность защищать племя, испытуемые должны истребить вторгшихся в Ежевичную лощину свинобразов-Дыбогривов и принести их пояса вождю Соколиному Ветру.",h="Обряд Силы — первое испытание в традиционных Обрядах Матери-Земли, которые проходят молодые таурены в Лагере...",kw={"brambleblade ravine","bristleback","camp narache","chief hawkwind","earthmother","mulgore","quilboar","rite of strength","seer graytongue","ежевичная лощина","дыбогрив","лагерь нараче","вождь соколиный ветер","мать-земля","мулгор","свинобраз","обряд силы","провидец серая пасть"},ang={["faction:Horde"]="Защита плато обеспечивает один из главных источников пополнения Орды: молодые воины и шаманы смогут безопасно возмужать и помочь новому союзу.",["race:Tauren"]="Каждый молодой таурен начинает свой путь с этих древних обрядов и показывает, что готов защитить свой народ от угрозы свинобразов, прежде чем покинуть Плато Красного Облака."},sec={{t="Первое испытание",b="Для молодого таурена, который ищет признания старейшин племени и в будущем — принятия в Громовом Утесе, прохождение Обрядов Матери-Земли — обязательный долг. Обряд Силы, который назначает Провидец Серая Пасть, служит первым испытанием. Он требует физической отваги и решительных действий в защиту Плато Красного Облака и проверяет, способен ли испытуемый без страха встретить смертельных врагов племени."},{t="Угроза Дыбогривов",b="Местом испытания выбрана Ежевичная лощина — поросший колючками овраг к востоку от Лагеря Нараче, где обосновались свинобразы-Дыбогривы. Эти агрессивные чужаки постоянно вторгаются на земли предков, устраивают засады на охотничьи отряды и под покровом темноты грабят припасы лагеря. Убить их и забрать их пояса — это и доказательство доблести, и необходимая мера для безопасности поселения."}},faq={{q="Для чего нужен Обряд Силы?",a="Это основополагающий этап Обрядов Матери-Земли, призванный проверить храбрость молодого таурена в бою. Устранив врагов, угрожающих лагерю, испытуемый получает право на путь к настоящему уважению в Громовом Утесе.",al={"why do rite of strength","rite of strength lore","purpose of rite of strength","зачем нужен обряд силы","обряд силы предания","цель обряда силы"}},{q="Кто дает и оценивает это испытание?",a="Провидец Серая Пасть возлагает поручение на испытуемого и объясняет духовные и практические требования испытания. Когда будет собрано двенадцать поясов Дыбогривов, доказательство доблести нужно предъявить прямо вождю Соколиному Ветру в Лагере Нараче.",al={"who gives rite of strength","who turns in rite of strength","кто дает обряд силы","кому сдавать обряд силы"}},{q="Где находится Ежевичная лощина?",a="Ежевичная лощина лежит прямо к востоку от Лагеря Нараче на Плато Красного Облака. Это колючий каньон, кишащий враждебными свинобразами-Дыбогривами.",al={"where is brambleblade ravine","brambleblade location","где ежевичная лощина","расположение ежевичной лощины"}},{q="Почему целью выбраны Дыбогривы?",a="Дыбогривы вторгаются на исконные охотничьи угодья племени. Они то и дело устраивают засады на охотников-тауренов и по ночам крадут провизию из Лагеря Нараче, поэтому они — прямые враги племени.",al={"why kill bristlebacks","what did the quilboar do","зачем убивать дыбогривов","что сделали свинобразы"}},{q="Почему собирают пояса, а не другие трофеи?",a="Пояса — вещественный знак побежденных воинов: они доказывают, что испытуемый сразился со свинобразами лицом к лицу и одолел взрослых бойцов, а не просто подбирал добычу издали.",al={"why bristleback belts","why belts","пояса дыбогривов","зачем пояса"}},{q="Что происходит после Обряда Силы?",a="Прохождение Обряда Силы подтверждает доблесть посвящаемого и дает ему право на последующие испытания Матери-Земли, продолжая формальный путь к взрослой жизни и духовному положению в племени.",al={"what is after rite of strength","next earthmother rite","что после обряда силы","следующий обряд матери-земли"}}},fp="16,303,15.399.0,22.404.0,44.234.0,34.237.0,37.150.0,40.223.0,44.196.0,49.201.0"}
P.entries["quest:758"] = {n="Очищение колодца Громового Рога",s="Очищение колодца Громового Рога — важный духовный обряд в Мулгоре: путникам поручено очистить загрязненный Колодец Громового Рога. Вооружившись ритуальным тотемом, подготовленным Муллом Громовым Рогом, герои очищают оскверненный источник, жизненно важный для местного племени. Успешное очищение приносит искреннее одобрение предков Громового Рога.",h="Очищение колодца Громового Рога — важный духовный обряд в Мулгоре: путникам поручено очистить загрязненный...",kw={"ancestral spirits","bloodhoof village","cleansing totem","earth mother","mulgore","mull thunderhorn","thunderhorn cleansing","thunderhorn water well","духи предков","деревня кровавого копыта","тотем очищения","мать-земля","мулгор","мулл громовой рог","очищение колодца громового рога","колодец громового рога"},ang={["class:Druid"]="Очищение отравленной воды останавливает распространение порчи по экосистеме Мулгора и сохраняет природную гармонию равнин.",["class:Shaman"]="Направлять энергию предков через тотемы, чтобы исцелять оскверненные родники, — сама основа призвания шамана.",["faction:Horde"]="Помощь тауренам с их священными источниками укрепляет связь между молодой Ордой и ее гордыми союзниками из Шу'хало.",["race:Tauren"]="Восстановление священных источников чтит Мать-Землю и защищает ваших сородичей, которые обустраивают постоянный мирный дом в Мулгоре."},sec={{t="Отравленная жила жизни",b="Колодцы на просторных равнинах Мулгора — жизненно важные источники для кочевых племен тауренов, недавно поселившихся в этих степях. Когда подземные источники отравляет скверна, страдают и звери, и ближние поселения. Колодец Громового Рога к северу от Деревни Кровавого Копыта стал жертвой порчи, и исцелить израненную землю можно лишь духовным обрядом."},{t="Очищение предков",b="Чтобы одолеть порчу, Мулл Громовой Рог изготавливает освященный Тотем очищения, наполненный духовной силой. Принеся эту реликвию к отравленной воде, герои направляют силу предков в источник, рассеивают яды и возвращают природе чистое равновесие. Мулл получает прямое подтверждение успеха, когда духи предков Громового Рога являются ему во сне, чтобы выразить неизменную благодарность."}},faq={{q="Где находится Колодец Громового Рога?",a="Колодец Громового Рога лежит на равнинах к северу от Деревни Кровавого Копыта в Мулгоре. Это один из нескольких жизненно важных водопоев для местных кланов тауренов.",al={"thunderhorn well location","where is well","where do i use totem","где колодец громового рога","где колодец","где использовать тотем"}},{q="Кто начинает этот обряд очищения?",a="Обряд начинает Мулл Громовой Рог. Его можно найти в Деревне Кровавого Копыта, где он мастерит особые тотемы, чтобы исцелить пострадавшую природу Мулгора.",al={"who gives quest","mull thunderhorn location","quest giver","кто дает задание","где мулл громовой рог","персонаж, выдающий задание"}},{q="Почему нужно очищать колодцы Мулгора?",a="Колодцы по всему Мулгору стали жертвой неестественного отравления и порчи, что угрожает хрупкому равновесию равнин и выживанию племен тауренов, зависящих от чистой воды.",al={"why cleanse wells","what happened to the water","why is well poisoned","зачем очищать колодцы","что случилось с водой","почему колодец отравлен"}},{q="Как Мулл узнает, что обряд удался?",a="Когда обряд у колодца завершен, духи предков клана Громового Рога являются Муллу во сне, хваля деяния героя и принося благодарность предков.",al={"ancestor dream","how mull knows","well cleansed result","сон о предках","как мулл узнает","результат очищения колодца"}},{q="Что происходит после очищения колодца Громового Рога?",a="Очищение Колодца Громового Рога — часть более широких усилий по защите источников Мулгора. Затем Мулл отправляет путников помочь в другом неспокойном месте — создать Тотем Буйногривых.",al={"what next","next quest after thunderhorn","wildmane totem next","что дальше","следующее задание после громового рога","тотем буйногривых дальше"}},{q="Что такое Тотем очищения колодца Громового Рога?",a="Тотем очищения колодца Громового Рога — ритуально вырезанное духовное средоточие, которое подготовил Мулл Громовой Рог специально для очищения оскверненных вод родового колодца своего клана.",al={"cleansing totem","what is the totem item","mull totem","тотем очищения","что за тотем","тотем мулла"}}},fp="21,345,18.422.0,19.447.0,44.167.0,36.161.0,48.196.0,45.184.0,51.191.0,40.180.0"}
P.entries["quest:759"] = {n="Тотем Буйногривых",s="Тотем Буйногривых — третий и последний этап усилий Мулла Громового Рога по созданию очищающих тотемов для отравленных колодцев Мулгора. Чтобы очистить Колодец Буйногривых, обряд требует даров от самых свирепых хищников края — вожаков луговых волков.",h="Тотем Буйногривых — третий и последний этап усилий Мулла Громового Рога по созданию очищающих тотемов для...",kw={"bloodhoof village","mulgore","mull thunderhorn","prairie wolf alpha","thunder bluff","totem","water well","wildmane","деревня кровавого копыта","мулгор","мулл громовой рог","вожак лугового волка","громовой утес","тотем","колодец","буйногривые"},ang={["class:Hunter"]="Выслеживание хитрых волков-вожаков у высоких утесов проверяет уважение охотника к дикой природе и ее самым опасным хищникам.",["class:Shaman"]="Шаманы ценят тонкие обряды, в которых тотемы хищников сочетаются со стихией воды, чтобы изгнать ядовитую порчу.",["race:Tauren"]="Очищение родовых колодцев подчеркивает долг тауренов исправлять нарушенное равновесие природы и чтить жертвы, которых требует Мать-Земля."},sec={{t="Последний колодец",b="Добыв материалы для освящения тотемов для колодцев Заиндевевшего Копыта и Громового Рога, остается лишь один пораженный источник в центре Мулгора — Колодец Буйногривых. Отравленная вода на равнинах угрожает и кочующим зверям, и поселениям, и для восстановления равновесия земли нужны сильные первозданные ингредиенты."},{t="Сила хищника",b="Чтобы одолеть сильную порчу в северных водах, Мулл Громовой Рог требует жертвы свирепости. Вожаки луговых волков бродят по степям, особенно у высоких утесов под Громовым Утесом. Добытые зубы вкладывают неутомимый напор и стойкость верховных хищников Мулгора прямо в создание очищающего тотема."},{t="Жертва и равновесие",b="В духовной традиции тауренов обращение к существам земли имеет эмоциональный и стихийный вес. Мулл видит в сборе зубов вожаков не завоевание, а мрачную необходимость: жертва хищников Мулгора помогает исцелить израненные воды Матери-Земли."}},faq={{q="Для чего нужен Тотем Буйногривых?",a="Мулл Громовой Рог изготавливает тотем, чтобы очистить Колодец Буйногривых — последний загрязненный источник воды, угрожающий тауренам Мулгора.",al={"why make wildmane totem","wildmane totem purpose","зачем делать тотем буйногривых","назначение тотема буйногривых"}},{q="Почему нужны именно зубы вожаков луговых волков?",a="Чтобы очистить глубокую порчу в Колодце Буйногривых, нужно направить свирепую, непреклонную силу верховного хищника. Зубы вожаков стай дают необходимую первозданную мощь.",al={"why wolf teeth","prairie alpha teeth purpose","зачем волчьи зубы","назначение зубов вожаков"}},{q="Где в Мулгоре найти вожаков луговых волков?",a="Вожаки луговых волков бродят по северным равнинам Мулгора, обычно в степях у подножия Громового Утеса.",al={"prairie wolf alpha location","where to find prairie alphas","где вожак лугового волка","где найти вожаков луговых волков"}},{q="Кто изготавливает тотем?",a="Мулл Громовой Рог, духовный старейшина из Деревни Кровавого Копыта, изготавливает каждый очищающий тотем, когда испытуемый соберет нужные дары.",al={"who makes the totem","totem quest giver","кто делает тотем","кто выдает задание на тотем"}},{q="Что происходит после создания Тотема Буйногривых?",a="Когда Мулл Громовой Рог соберет тотем из зубов вожаков, вас отправят с ним на север, чтобы провести само очищение у Колодца Буйногривых.",al={"what comes next","wildmane totem next quest","что дальше","следующее задание тотема буйногривых"}},{q="Как этот обряд отражает верования тауренов?",a="Таурены считают лишение животного жизни торжественным обменом с природой. Мулл признает жертву волков с печалью об их смерти и с гордостью за их роль в исцелении земли.",al={"tauren philosophy totem","mull thunderhorn beliefs","философия тауренов тотем","верования мулла громового рога"}}},fp="14,272,14.339.0,23.367.0,21.277.0,38.141.0,55.192.0,47.130.0,21.146.0,48.147.0,44.199.0"}
P.entries["quest:76"] = {n="Яшмовая шахта",s="После того как выяснилось, что кобольды захватили Рудник Подземных Глубин, маршал Дугхан поручает разведчикам осмотреть Яшмовую шахту дальше на восток. Прибыв на место, они убеждаются в худшем: нашествие распространилось по важным рудным жилам Элвиннского леса, и оставшиеся защитники Штормграда оказались на пределе сил.",h="После того как выяснилось, что кобольды захватили Рудник Подземных Глубин, маршал Дугхан поручает разведчикам...",kw={"azora","dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","mine","scout","азора","дугхан","элвиннский лес","подземные глубины","златоземье","яшмовая шахта","кобольд","шахта","разведчик"},ang={["faction:Alliance"]="Одновременная потеря Рудника Подземных Глубин и Яшмовой шахты показывает, насколько хрупкими стали внутренние земли Штормграда без централизованной королевской поддержки.",["profession:Mining"]="Для шахтера зрелище богатых подземных жил, захваченных вредителями, горько. В туннелях Яшмовой шахты немало ценных залежей, но чтобы добыть их, придется пробиваться через полчища кобольдов, защищающих свою территорию.",["race:Human"]="Разведчики-люди воочию видят, как постепенно рушится сельская инфраструктура Элвиннского леса: ресурсы окраин гибнут у самых порогов столицы."},sec={{t="Второе вторжение",b="Получив доказательства того, что кобольды наводнили туннели Рудника Подземных Глубин к югу от Златоземья, маршал Дугхан опасался, что нашествие — не единичный случай. Яшмовая шахта, расположенная в скалистых предгорьях к северо-востоку от Башни Азоры, — еще один важный источник камня и металла для королевства. Не имея возможности снять обычных стражей Штормграда с патрулирования города, Дугхан полагается на вольных искателей приключений: они должны отправиться на восток и выяснить, не захвачено ли и это место подземными вредителями со свечами."},{t="Растянутая оборона",b="Разведка в глубине залов Яшмовой шахты показывает, что кобольды полностью вытеснили шахтеров-людей и закрепились в темных проходах, укрепив их. Для маршала Дугхана этот мрачный доклад — очередной удар в нарастающем кризисе. Король Вариан Ринн пропал, а королевские войска не отправляют в отдаленные земли, поэтому местному гарнизону не хватает людей, чтобы очистить шахты. Сердце королевства страдает экономически и оказывается зажато в тисках."}},faq={{q="Где находится Яшмовая шахта?",a="Шахта находится в северных предгорьях восточной части Элвиннского леса. Чтобы добраться до нее, следуйте на восток по главной дороге мимо Златоземья до Башни Азоры, а затем поверните на север, в холмы.",al={"where is jasperlode","jasperlode mine location","how to find jasperlode","где яшмовая шахта","расположение яшмовой шахты","как найти яшмовую шахту"}},{q="Почему маршалу Дугхану нужен разведчик, а не стражи?",a="Стража Штормграда в Элвиннском лесу остро нуждается в людях из-за политического тупика в столице и исчезновения короля Вариана Ринна. Местные силы растянуты на защиту ферм и городов от бандитов и гноллов, поэтому маршалу Дугхану приходится полагаться на разведчиков из числа гражданских.",al={"why send adventurers","why no stormwind guard","where are the guards","почему искатели приключений","почему не стража штормграда","где стражи"}},{q="Почему кобольды захватывают шахты Элвиннского леса?",a="Кобольды — прирожденные проходчики, их привлекают подземные рудные жилы и сырые пещеры. Когда военное присутствие Штормграда ослабло, твари осмелели и стали наступать на разработки людей, такие как Рудник Подземных Глубин и Яшмовая шахта, чтобы завладеть золотом, рудой и землей.",al={"why kobolds in jasperlode","what do kobolds want","kobold infestation reason","почему кобольды в яшмовой шахте","чего хотят кобольды","причина нашествия кобольдов"}},{q="Что происходит после разведки Яшмовой шахты?",a="Когда вы сообщаете маршалу Дугхану о падении Яшмовой шахты, он признает мрачную реальность: Элвиннский лес осажден сразу с нескольких сторон. Раз восточные шахты потеряны, его внимание переключается на запад леса, где Гарнизон у Западного ручья испытывает сильное давление гноллов из племени Речной Лапы.",al={"what next after jasperlode","jasperlode follow up","что дальше после яшмовой шахты","продолжение яшмовой шахты"}},{q="Чем потеря Яшмовой шахты важна для Штормграда?",a="Шахты Элвиннского леса поставляют руду и камень, необходимые для экономики Штормграда и для ковки оружия и доспехов. Потеря и Рудника Подземных Глубин, и Яшмовой шахты останавливает добычу и серьезно подрывает усилия по восстановлению королевства.",al={"why jasperlode matters","jasperlode importance","почему важна яшмовая шахта","значение яшмовой шахты"}},{q="Кому принадлежит соседняя Башня Азоры?",a="Башня Азоры — небольшая башня магов у восточной дороги в Элвиннском лесу. Ею управляет Теокрит, верховный маг Азоры, а служат в ней слуги Азоры. Она служит ориентиром для путников, идущих к восточным предгорьям.",al={"what is tower of azora","who lives in azora tower","что такое башня азоры","кто живет в башне азоры"}}},fp="19,314,18.518.0,21.456.0,37.191.0,63.268.0,43.266.0,48.280.0,60.230.0,35.246.0"}
P.entries["quest:760"] = {n="Очищение колодца Буйногривых",s="Очищение колодца Буйногривых завершает усилия тауренов по ритуальной очистке важных водопоев Мулгора. По поручению Мулла Громового Рога из Деревни Кровавого Копыта герои несут готовый Тотем Буйногривых на север, чтобы очистить последний отравленный колодец. Изгнание гоблинских загрязнений восстанавливает равновесие равнин и обеспечивает пастушеский уклад племен тауренов.",h="Очищение колодца Буйногривых завершает усилия тауренов по ритуальной очистке важных водопоев Мулгора.",kw={"bloodhoof village","cleansing","earth mother","mulgore","mull thunderhorn","totem","venture company","water well","wildmane","деревня кровавого копыта","очищение","мать-земля","мулгор","мулл громовой рог","тотем","торговая компания","колодец","буйногривые"},ang={["class:Druid"]="Устранение вреда, причиненного гоблинами природе, прямо отражает завет Кенария — исцелять оскверненные экосистемы и охранять зеленые пастбища.",["class:Shaman"]="Использование ритуальных тотемов для устранения механического загрязнения служит примером долга шаманов — поддерживать гармонию между стихиями природы и живыми общинами.",["race:Tauren"]="Восстановление трех древних колодцев Мулгора — основополагающий обряд посвящения, доказывающий преданность молодого воина сохранению даров Матери-Земли."},sec={{t="Очищение дара Матери-Земли",b="Вода — священный источник жизни на залитых солнцем равнинах Мулгора: она поддерживает стада, почву и кочевые племена, недавно собравшиеся вокруг Громового Утеса. Когда Торговая Компания и наступающие гоблины начали загрязнять эти водоносные слои токсичными промышленными стоками, старейшины тауренов осознали смертельную угрозу. После очищения колодцев Заиндевевшего Копыта и Громового Рога Колодец Буйногривых остается третьим и последним оскверненным местом, где требуется духовное вмешательство."},{t="Тотем Буйногривых",b="Тотем очищения колодца Буйногривых, созданный из особых элементов, собранных по всей области, направляет исцеляющую силу духов предков и стихии земли. Установленный возле оскверненных вод к северу от Громового Утеса, он рассеивает грязные химикаты, вытягивает токсины и возрождает естественный ток воды. Завершив ритуал, таурены защищают свой народ от болезней и ясно дают понять, что осквернение их священной земли терпеть не будут."}},faq={{q="Почему отравили Колодец Буйногривых?",a="Гоблинские предприятия, движимые промышленной жадностью и лесозаготовками, привнесли гнусные яды и химические отходы в подземные воды Мулгора, угрожая как местным животным, так и поселениям племен.",al={"who poisoned the well","why is the well dirty","goblin poison","кто отравил колодец","почему колодец грязный","гоблинский яд"}},{q="Где находится Колодец Буйногривых?",a="Колодец Буйногривых расположен на равнинах прямо к северу от высоких плато Громового Утеса.",al={"wildmane well location","where is wildmane well","finding wildmane well","где колодец буйногривых","расположение колодца буйногривых","найти колодец буйногривых"}},{q="Кто начинает этот ритуал очищения?",a="Мулл Громовой Рог, старейшина из Деревни Кровавого Копыта, проводит вас через создание тотемов и отправляет очищать колодцы.",al={"who gives wildmane cleansing","quest giver","mull thunderhorn location","кто дает очищение колодца буйногривых","персонаж, выдающий задания","где мулл громовой рог"}},{q="Какие еще колодцы входят в эти усилия по очищению?",a="Колодец Буйногривых — третий из трех важных источников воды. Ему предшествуют Колодец Заиндевевшего Копыта и Колодец Громового Рога, оба к югу.",al={"other wells","mulgore wells","winterhoof thunderhorn wells","другие колодцы","колодцы мулгора","колодцы заиндевевшего копыта и громового рога"}},{q="Как действует тотем очищения?",a="Тотем наполнен магией предков и очищенными природными стихиями: он направляет исцеляющую духовную энергию в подземные воды и нейтрализует гоблинские загрязнения.",al={"cleansing totem mechanic","how does totem clean water","как работает тотем очищения","как тотем очищает воду"}},{q="Что значит завершение этого ритуала для Деревни Кровавого Копыта?",a="Очищение трех колодцев гарантирует безопасную питьевую воду всем племенам центрального Мулгора и почитает священный долг тауренов исцелять Мать-Землю от промышленной эксплуатации.",al={"outcome of quest","why cleanse the wells","tauren lore importance","итог задания","зачем очищать колодцы","значение для предания тауренов"}}},fp="18,371,33.509.0,18.481.0,41.206.0,41.104.0,36.139.0,54.153.0,34.166.0,60.179.0"}
P.entries["quest:761"] = {n="Охота на перепелятников",s="Охота на перепелятников — обряд выслеживания и меткой стрельбы, который предлагает Харкен Тотем Ветра в Деревне Кровавого Копыта. Чтобы доказать свою смекалку и терпение, охотникам и путникам предлагается выследить неуловимых птиц на холмистых равнинах Мулгора. Возвращение с нетронутыми трофейными перьями свидетельствует о преданности охоте и уважении к природным испытаниям Матери-Земли.",h="Охота на перепелятников — обряд выслеживания и меткой стрельбы, который предлагает Харкен Тотем Ветра в...",kw={"bloodhoof village","harken windtotem","mulgore","swoop","swoop hunting","tauren trial","trophy swoop quill","деревня кровавого копыта","харкен тотем ветра","мулгор","перепелятник","охота на перепелятников","испытание тауренов","трофейное перо перепелятника"},ang={["class:Druid"]="Выслеживание перепелятников на продуваемых ветрами плато сближает друидов с хищными птицами, которые поддерживают равновесие в небесах Мулгора.",["class:Hunter"]="Эта охота — первый урок в стрельбе по воздушной цели с упреждением, оценке повадок и точных ударах по бдительным хищникам.",["race:Tauren"]="Для молодых тауренов и странников охота на быстрых перепелятников Мулгора — древний обряд посвящения, оттачивающий навыки выслеживания и поддерживающий охотничьи обычаи предков."},sec={{t="Испытание зоркого глаза",b="Травянистые степи Мулгора кишат зверями, но немногие проверяют чутье преследователя так, как местные перепелятники. Эти крупные хищные птицы сливаются с небом и равниной, кружа над головой или скользя низко над высокой травой. В отличие от неповоротливых виверн равнин или пасущихся кодо, перепелятники требуют острого внимания и быстрых ног, чтобы их догнать, поэтому охота на них — традиционное испытание для молодых охотников, стремящихся заслужить место среди племен."},{t="Знаки охоты",b="Для Харкена Тотема Ветра сбор трофейных перьев — не столько истребление дичи, сколько воспитание дисциплины. В культуре тауренов трофеи тяжелой охоты означают смекалку и стойкость. Предъявив эти безупречные перья старейшинам Деревни Кровавого Копыта, искатель приключений показывает, что способен кормить и защищать общину, что его копыта быстры, а чувства достаточно остры, чтобы покорить широкий мир."}},faq={{q="Какова цель охоты на перепелятников для Харкена Тотема Ветра?",a="Харкен Тотем Ветра поручает охотникам выслеживать перепелятников по всему Мулгору, чтобы проверить их смекалку, скорость и преданность. Целые трофейные перья служат признанным доказательством мастерства охотника и приносят почет среди тауренов Деревни Кровавого Копыта.",al={"why hunt swoops","harken windtotem quest purpose","swoop hunting purpose","зачем охотиться на перепелятников","цель задания харкена тотема ветра","цель охоты на перепелятников"}},{q="Где обычно встречаются перепелятники?",a="Перепелятники встречаются по всем открытым равнинам Мулгора: они парят над прериями или высматривают добычу в траве за пределами поселений вроде Деревни Кровавого Копыта.",al={"where are swoops","swoop locations mulgore","find swoops","где перепелятники","где найти перепелятников в мулгоре","найти перепелятников"}},{q="Почему на перепелятников сложно охотиться?",a="В отличие от стадных животных, которые движутся вместе по равнинам, перепелятники — быстрые и настороженные хищные птицы, рассеянные по округе и внимательные. Чтобы выследить их, нужно острое зрение, чтобы заметить пути полета, и быстрый шаг, чтобы сбить их до того, как они уйдут.",al={"why are swoops hard to catch","swoop behavior","почему трудно поймать перепелятников","повадки перепелятников"}},{q="Что означают трофейные перья для тауренов?",a="В традициях тауренов трофейные перья перепелятника означают терпение, острое зрение и успешную охоту. Их ношение показывает, что у охотника есть чутье, необходимое, чтобы кормить и защищать племя.",al={"trophy swoop quill meaning","significance of quills","значение трофейного пера перепелятника","значение перьев"}},{q="Кто такой Харкен Тотем Ветра?",a="Харкен Тотем Ветра — уважаемый таурен, живущий в Деревне Кровавого Копыта. Он наблюдает за новичками и начинающими охотниками и оценивает их находчивость в традиционных испытаниях на равнинах.",al={"who gives swoop hunting","harken windtotem lore","кто дает охоту на перепелятников","предания о харкене тотеме ветра"}},{q="Влияет ли эта охота на равновесие природы в Мулгоре?",a="Таурены относятся к охоте как к священному диалогу с Матерью-Землей, а не как к бессмысленной бойне. Сбор перьев — взвешенное испытание дисциплины, которое чтит смекалку добычи и сохраняет равновесие племени.",al={"is swoop hunting overhunting","swoop balance mulgore","не чрезмерна ли охота на перепелятников","равновесие перепелятников в мулгоре"}}},fp="13,385,19.466.0,18.451.0,59.252.0,39.172.0,41.246.0,48.215.0,24.192.0,55.222.0"}
P.entries["quest:763"] = {n="Обряды Матери-Земли",ang={["faction:Horde"]="Традиционные обряды укрепляют единство племен по всему Мулгору и гарантируют, что новые защитники Орды обладают и воинским мастерством, и глубокой духовной основой.",["race:Tauren"]="Каждый молодой таурен должен пройти путь Матери-Земли, чтобы доказать свою ценность старейшинам и найти свое место среди объединенных племен."},sec={{t="Прощание с плато",b="Из поколения в поколение молодые таурены испытывали свою силу в безопасном Лагере Нараче на Плато Красного Облака. Прохождение первых испытаний доказывает, что у человека хватает дисциплины и решимости, чтобы выжить, но священные Обряды Матери-Земли требуют гораздо большего, чем борьба с местными зверями. Вождь Соколиный Ветер понимает, когда посвящаемый перерос защищенные охотничьи угодья плато и должен шагнуть в более широкую общину."},{t="Знак для Бейна",b="Чтобы облегчить путь между Нараче и главными поселениями, вождь Соколиный Ветер вручает вам вырезанный вручную тотем как знак представления. Неся этот символ по извилистой тропе в Деревню Кровавого Копыта, вы являетесь к Бейну Кровавому Копыту, молодому вождю деревни и сыну верховного вождя Кэрна Кровавого Копыта. Тотем свидетельствует о вашей готовности к обрядам духа и мудрости, которые ждут впереди."}},faq={{q="Для чего нужно это задание?",a="Это обряд перехода, который выводит вас из начальной области Лагеря Нараче и направляет в Деревню Кровавого Копыта, связывая вас со следующей главой церемониальных испытаний тауренов.",al={"why do rites of the earthmother","what does this quest do","purpose of quest","зачем обряды матери-земли","что дает это задание","цель задания"}},{q="Кто такой Бейн Кровавое Копыто?",a="Бейн Кровавое Копыто — сын верховного вождя Кэрна Кровавого Копыта. Он управляет Деревней Кровавого Копыта и является уважаемым местным вождем, наблюдающим за продолжающимися духовными и боевыми испытаниями молодых тауренов.",al={"who is baine","baine lore","son of cairne","кто такой бейн","бейн предания","сын кэрна"}},{q="What is the Totem of Hawkwind?",a="Это деревянный тотем, вырезанный вручную вождем Соколиным Ветром из Лагеря Нараче. Он служит официальной грамотой и знаком одобрения и доказывает Бейну Кровавому Копыту, что вы заслужили благословение Соколиного Ветра на дальнейшие обряды.",al={"totem of hawkwind","hawkwinds totem","carved totem"}},{q="Какие обряды идут после этого?",a="Когда вы прибудете в Деревню Кровавого Копыта и встретитесь с Бейном, вам поручат Обряд прозрения, который проверяет вашу духовную связь с помощью священных видений предков.",al={"next rites","what comes after","next quest","следующие обряды","что дальше","следующее задание"}},{q="Где находится Деревня Кровавого Копыта?",a="Деревня Кровавого Копыта лежит к северу от Лагеря Нараче, на берегах Озера Каменного Быка в центральном Мулгоре. Путникам достаточно спуститься по главной дороге с плато и идти на север.",al={"where is bloodhoof village","how to find bloodhoof village","path to bloodhoof","где деревня кровавого копыта","как найти деревню кровавого копыта","путь в деревню кровавого копыта"}},{q="Почему нужно пройти обряды Матери-Земли?",a="Обряды Матери-Земли — глубоко священные традиции тауренов. Прохождение всех их этапов демонстрирует физическую стойкость, духовную связь и мудрость и приносит посвящаемому истинное признание старейшин Громового Утеса.",al={"why earthmother rites","tauren trials purpose","rites of earthmother lore","зачем обряды матери-земли","цель испытаний тауренов","предания обрядов матери-земли"}}},fp="24,305,16.421.0,17.420.0,34.199.0,23.201.0,30.219.0,27.170.0,35.185.0,44.246.0"}
P.entries["quest:764"] = {n="Торговая Компания",s="Расследование судьбы разграбленного каравана Торговой Компании в Мулгоре выявляет агрессивное скопление гоблинов Торговой Компании, зарывшихся в восточные холмы. Получив категорический отказ на официальные просьбы о разрешении на добычу, компания все равно начала разработку земли Матери-Земли, и Морин Ловец Облаков заказал смертельный ответ.",h="Расследование судьбы разграбленного каравана Торговой Компании в Мулгоре выявляет агрессивное скопление...",kw={"goblin","mining rights","morin cloudstalker","mulgore","ravaged caravan","venture co","venture co mine","venture company","гоблин","право на добычу","морин ловец облаков","мулгор","разграбленный караван","торговая компания","шахта торговой компании"},ang={["faction:Horde"]="Защита Мулгора от коммерческой эксплуатации подтверждает вашу решимость оберегать народ Кэрна Кровавого Копыта, пока он стремится обезопасить свою новую родину.",["profession:Mining"]="Торговая Компания действует исключительно грубой силой: халтурит и расшатывает землю, не заботясь ни о естественном равновесии, ни о безопасности горного дела.",["race:Tauren"]="Для тауренов Мать-Земля священна. Открытые разработки Торговой Компании — не просто вторжение, а насильственное осквернение родного дома предков, заслуживающее немедленного и решительного изгнания."},sec={{t="Промышленное вторжение",b="Таурены Мулгора чтят землю как продолжение Матери-Земли и берегут ее нетронутые равнины и сбалансированный животный мир. Когда Торговая Компания обратилась к племенам за правом взрывать и вскрывать холмы ради сырой руды, ей категорически отказали. Не смутившись ни племенными решениями, ни территориальным суверенитетом, неумолимый картель тайно провел тяжелую технику, рабочих и надсмотрщиков прямо в восточные гряды Мулгора для незаконной добычи."},{t="Недвусмысленное послание",b="Таурены-разведчики вроде Морина Ловца Облаков понимают, что с корпоративной жадностью нельзя договориться дипломатическими призывами, когда кирки уже бьют по камню. Документы, найденные в разграбленном караване Торговой Компании, подтверждают наличие горных работ, и Морин посылает защитников Орды перебить и надсмотрщиков, щелкающих кнутами, и рабочих у буров. Кровавое возмездие должно заставить Торговую Компанию счесть цену вторжения слишком высокой."}},faq={{q="Почему Торговая Компания находится в Мулгоре?",a="Торговая Компания устроила на восточных холмах Мулгора незаконный лагерь и шахту для добычи минералов и природных ресурсов. После того как таурены официально отказали ей в праве на добычу, картель проигнорировал власть племен и все равно начал работы.",al={"why are goblins in mulgore","venture co mulgore motive","what does venture co want","почему гоблины в мулгоре","мотивы торговой компании в мулгоре","чего хочет торговая компания"}},{q="Кто отдал приказ напасть на шахтеров?",a="Приказ отдает Морин Ловец Облаков, таурен, несущий дозор возле Деревни Кровавого Копыта. Он считает, что отказ картеля принять отказ племени — прямое нарушение, требующее силы, а не новых разговоров.",al={"who gives this quest","morin cloudstalker role","quest giver","кто выдает это задание","роль морина ловца облаков","персонаж, выдающий задания"}},{q="Где находится шахта Торговой Компании?",a="Главная шахта Торговой Компании расположена в предгорьях к востоку от Разграбленного каравана и Деревни Кровавого Копыта. Небольшую группу служащих компании можно также встретить в лагере среди утесов к северо-востоку от северных подъемников Громового Утеса.",al={"venture co mine location","where are the supervisors","where to find venture co","расположение шахты торговой компании","где бригадиры","где найти торговую компанию"}},{q="Пытались ли таурены вести переговоры с гоблинами?",a="Да. Торговая Компания просила у тауренов официального права на добычу в Мулгоре. Вожди племен отказались позволить разорять их родовые земли открытыми разработками, но гоблины попросту решили копать без разрешения.",al={"did tauren permit mining","mining rights mulgore","did goblins ask permission","разрешили ли таурены добычу","право на добычу мулгор","просили ли гоблины разрешения"}},{q="Относятся ли эти гоблины к Картелю Хитрая Шестеренка?",a="Нет. Торговая Компания — независимый, пользующийся дурной славой хищнический промышленный картель, отличный от нейтральных торговых объединений вроде Картеля Хитрая Шестеренка. Где бы она ни добывала ресурсы, она поддерживает враждебные отношения с местным населением.",al={"are these ratchet goblins","is venture co friendly","venture company faction","это гоблины кабестана","дружелюбна ли торговая компания","фракция торговая компания"}},{q="Как это связано с разграбленными караванами?",a="Разграбленный караван был обозом Торговой Компании, уничтоженным тауренами. Ящики горного отдела и документы, найденные среди обломков, раскрыли планы компании в Мулгоре и вызвали этот удар по ее шахте.",al={"caravan connection","did venture co attack caravans","the ravaged caravan connection","связь с караваном","нападала ли торговая компания на караваны","разграбленный караван"}}},fp="15,339,20.472.0,23.485.0,38.269.0,40.215.0,42.253.0,54.219.0,50.237.0,46.224.0"}
P.entries["quest:765"] = {n="Бригадир Шумовик",s="Бригадир Шумовик — высокопоставленный надсмотрщик Торговой Компании, расположившийся в горных туннелях Мулгора. По поручению Морина Ловца Облаков положить конец расчетливому грабежу гоблинского предприятия, искатели приключений Орды входят в шахту, чтобы убить его и забрать его подробную планшетку.",h="Бригадир Шумовик — высокопоставленный надсмотрщик Торговой Компании, расположившийся в горных туннелях...",kw={"clipboard","fizsprocket","mine","morin cloudstalker","mulgore","supervisor","venture co","планшетка","шумовик","шахта","морин ловец облаков","мулгор","бригадир","торговая компания"},ang={["faction:Horde"]="Помощь тауренам против наступающих корпоративных грабителей укрепляет защиту Ордой недавно занятых земель Калимдора.",["race:Tauren"]="Открытый замысел Торговой Компании вытеснить ваше племя и разграбить священную землю делает убийство Шумовика актом жизненно важной защиты территории."},sec={{t="Заговор против равнин",b="Документы из уничтоженного каравана Торговой Компании показали, что компания не просто добывала руду — она намеренно строила планы полностью изгнать тауренов из Мулгора. Выселив местных, алчная корпорация рассчитывала получить свободу вычерпать из холмов и глубоких подземных жил все природные ресурсы."},{t="Удар по десятнику",b="Морин Ловец Облаков, разгневанный корпоративными злодеяниями, замышляемыми против его народа, направляет героев в шахту Торговой Компании к востоку от разоренных торговых фургонов. В глубине правых туннелей, в окружении рабочих и младших начальников, делами заправляет Бригадир Шумовик. Если убить Бригадира Шумовика и забрать его планшет, местная координация будет нарушена, а вы получите важные сведения о будущих замыслах компании."}},faq={{q="Кто такой Бригадир Шумовик?",a="Бригадир Шумовик — начальник Торговой Компании, руководящий работами в горных туннелях восточного Мулгора. Он надзирает за рабочими, вгрызающимися в землю, и осуществляет корпоративные стратегии расширения их деятельности по всему региону.",al={"fizsprocket","who is fizsprocket","fizsprocket lore","шумовик","кто такой шумовик","шумовик предания"}},{q="Почему Морин Ловец Облаков хочет смерти Шумовика?",a="Морин нашел в разграбленном караване документы, доказывающие, что Торговая Компания замышляла ради прибыли изгнать тауренов с родовых земель. Шумовик — непосредственный начальник, осуществляющий эти расчетливые планы эксплуатации.",al={"why kill fizsprocket","morin cloudstalker motivation","зачем убивать шумовика","мотивы морина ловца облаков"}},{q="Где находится Бригадир Шумовик?",a="Он находится внутри шахты Торговой Компании, прямо к востоку от Разграбленного каравана в Мулгоре. В шахте идите по крайнему правому туннелю до зала, где он стоит в окружении рабочих и надсмотрщиков.",al={"where is fizsprocket","fizsprocket mine location","fizsprocket map","где шумовик","шахта шумовика","карта шумовика"}},{q="Какое доказательство победы над Шумовиком требует Морин?",a="Морин Ловец Облаков требует личную планшетку Шумовика, где хранятся учетные книги и записи, способные раскрыть дальнейшие замыслы Торговой Компании в Мулгоре.",al={"proof of death","fizsprocket clipboard","доказательство смерти","планшетка шумовика"}},{q="Почему Торговая Компания находится в Мулгоре?",a="Торговая Компания — беспринципный коммерческий картель, стремящийся ободрать нетронутые земли ради древесины, минералов и ценных подземных богатств, совершенно не считаясь с коренными жителями и природным равновесием.",al={"venture co mulgore","why are goblins in mulgore","торговая компания мулгор","почему гоблины в мулгоре"}},{q="Прогонит ли убийство Шумовика Торговую Компанию окончательно?",a="Нет. Хотя гибель Шумовика нарушает местное руководство и дает Морину Ловцу Облаков важные записи об их планах, Торговая Компания остается постоянной угрозой, укоренившейся в холмах Мулгора.",al={"is venture co gone","after fizsprocket dies","ушла ли торговая компания","после смерти шумовика"}}},fp="22,298,25.371.0,21.456.1,30.251.0,50.232.0,40.207.0,54.160.0,38.219.0,67.204.0"}
P.entries["quest:766"] = {n="Маззранач",s="Маур Заклинатель Дождя из Деревни Кровавого Копыта стал жертвой ядовитого укуса Маззранача — легендарного бегуна по равнинам, который за поколение до этого терроризировал его деда. Таурен мечется в лихорадке и бредовых кошмарах, и ему нужно сильное лекарство из местных животных Мулгора, пока инфекция не отняла у него жизнь.",h="Маур Заклинатель Дождя из Деревни Кровавого Копыта стал жертвой ядовитого укуса Маззранача — легендарного...",kw={"bloodhoof village","flatland cougar","maur raincaller","mazzranache","mulgore","plainstrider","prairie wolf","swoop","деревня кровавого копыта","равнинный кугуар","маур заклинатель дождя","маззранач","мулгор","луговой бегун","луговой волк","налетчик"},ang={["class:Hunter"]="Выслеживание луговых волков, кугуаров, луговых бегунов и налетчиков по всему Мулгору — практический урок чтения равнин и понимания особенностей местной дикой природы саванны.",["faction:Horde"]="Защита Деревни Кровавого Копыта от суровых опасностей Мулгора жизненно важна для мира и стабильности на родине тауренов.",["race:Tauren"]="Снадобье, которое готовит Маур, отражает древнюю практику тауренов — черпать лекарства прямо из растительного и животного мира Матери-Земли."},sec={{t="Наследие равнин",b="Долгие годы Маур Заклинатель Дождя считал Маззранача не более чем жуткой семейной историей, которую рассказывал его дед. Старый таурен говорил о необычайно свирепом бегуне по равнинам со светящимися красными глазами, острыми как бритва когтями и ядовитым укусом, не свойственным мирным животным Мулгора. Когда Маур встретил зверя на открытой равнине, легенда оказалась слишком реальной: он был тяжело ранен и с трудом добрался до безопасного места."},{t="Борьба с заражением",b="The creature's venom works swiftly, inducing high fevers and nightmarish delirium. To purge the venom before it turns fatal, traditional tauren medicine relies on the vitality of the local beasts. Maur requires a prairie wolf heart, a flatland cougar femur, a plainstrider scale, and a swoop gizzard. By combining the essences of these varied hunters and scavengers, he can brew a concoction capable of halting the necrotic spread and nursing him back to health."}},faq={{q="Кто такой Маззранач?",a="Mazzranache is an infamous plainstrider roaming the grasslands of Mulgore. Unlike common striders, it is known for vivid plumage, demonic red eyes, fierce talons, and an unusually venomous bite. It has terrorized travelers across multiple generations.",al={"who is mazzranache","what kind of beast is mazzranache","mazzranache lore","кто такой маззранач","что за зверь маззранач","маззранач предания"}},{q="Кто такой Маур Заклинатель Дождя?",a="Маур Заклинатель Дождя — таурен, живущий в Деревне Кровавого Копыта. Когда он пересекал Мулгор, на него напал Маззранач и укусил в плечо, и теперь Маур прикован к постели смертельно опасной ядовитой инфекцией.",al={"maur raincaller","who gave me this quest","who is the sick tauren","маур заклинатель дождя","кто дал это задание","кто больной таурен"}},{q="Почему Мауру нужны части четырех разных зверей?",a="Traditional tauren remedies draw upon the natural strengths and spiritual essences of plains animals to neutralize potent toxins. The heart of a wolf, the dense marrow of a cougar femur, a plainstrider scale, and a swoop gizzard together form an antidote strong enough to counteract Mazzranache's venom.",al={"why wolf heart cougar femur","why animal ingredients","mazzranache remedy ingredients"}},{q="Убил ли дед Маура Маззранача?",a="Нет. Дед Маура сражался со свирепым луговым бегуном много лет назад, но не смог его одолеть и выжил лишь для того, чтобы передать потомкам предостережения о его яркой окраске и жестоких нападениях.",al={"did grandfather defeat mazzranache","maur grandfather mazzranache","who fought mazzranache before"}},{q="Нужно ли в этом задании охотиться на самого Маззранача?",a="Нет. Главное для Маура сейчас — пережить лихорадку. Задание целиком посвящено сбору составляющих для его лекарства, а не охоте на легендарную птицу.",al={"do i kill mazzranache","where is mazzranache","hunt mazzranache"}},{q="Где находится Деревня Кровавого Копыта?",a="Деревня Кровавого Копыта лежит в центральной части Мулгора, к югу от Громового Утеса и чуть восточнее Озера Каменного Быка. Это главное поселение, откуда молодые тауренские воины отправляются в широкие равнины.",al={"where is bloodhoof village","bloodhoof village location","где деревня кровавого копыта","расположение деревни кровавого копыта"}}},fp="11,313,22.471.0,20.462.0,20.251.0,23.208.0,52.303.0,40.198.0,55.180.0,35.193.0"}
P.entries["quest:767"] = {n="Обряд прозрения",s="Обряд прозрения — важнейшее испытание на пороге зрелости в Обрядах Матери-Земли, проверяющее духовную зрелость юного искателя приключений. По поручению Бейна Кровавого Копыта соискателям предстоит обратиться за советом к провидцу деревни Зарельману Две Луны. Это путешествие необходимо всем, кто ищет благословения и уважения старейшин на холмах Громового Утеса.",h="Обряд прозрения — важнейшее испытание на пороге зрелости в Обрядах Матери-Земли, проверяющее духовную...",kw={"baine bloodhoof","bloodhoof village","mulgore","rite of vision","rites of the earthmother","tauren trial","thunder bluff","zarlman two-moons","бейн кровавое копыто","деревня кровавого копыта","мулгор","обряд прозрения","обряды матери-земли","испытание тауренов","громовой утес","зарельман две луны"},ang={["class:Druid"]="Прямое общение с видениями Матери-Земли укрепляет призвание друидов внимательно прислушиваться к мудрости и шепоту живого мира.",["class:Shaman"]="Поиски Зарельмана Две Луны и путь видений глубоко созвучны долгу шамана — сохранять равновесие между мирскими делами и волей предков.",["faction:Horde"]="Прохождение этих традиционных священных обрядов доказывает вашу преданность и уважение к культуре старейшин тауренов, помогающих направлять Орду.",["race:Tauren"]="Обряд прозрения — важная культурная веха для каждого молодого таурена, знаменующая ваш переход в ряды доверенных защитников и ходоков по духам племен."},sec={{t="Священная ступень",b="Поколениями кочевые таурены обращались к Матери-Земле, чтобы она вела их народ по равнинам Калимдора. Теперь, собравшись в безопасных границах Мулгора, они сохраняют духовные традиции как основу своего общества. Обряд прозрения — одно из древних испытаний, известных как Обряды Матери-Земли. Если прежние испытания проверяют физическую силу посвященного и его связь с охотой, то Обряд прозрения требует путешествия вглубь себя и призывает юных тауренов и почетных союзников напрямую общаться с духами."},{t="Наставление провидца",b="Прежде чем искать духовное видение, посвященного должен подготовить человек, умудренный древней мудростью. В Деревне Кровавого Копыта это поручено почитаемому шаману Зарельману Две Луны. Бейн Кровавое Копыто доверил ему готовить путников; Зарельман обладает острым зрением, позволяющим распознать идущих путем предков, и проводит предварительные обряды и священные приготовления, необходимые, чтобы проникнуть сквозь завесу физического мира."}},faq={{q="Что такое Обряд прозрения?",a="Обряд прозрения — священный ритуал в рамках Обрядов Матери-Земли. Он призван расширить духовное зрение искателя приключений, позволяя ему общаться с духами предков и показать старейшинам Громового Утеса свою духовную готовность.",al={"rite of vision quest","what is rite of vision","rite of vision lore","задание обряд прозрения","что такое обряд прозрения","обряд прозрения предания"}},{q="Кто дает это задание?",a="Задание дает Бейн Кровавое Копыто, сын верховного вождя Кэрна Кровавого Копыта. Бейн присматривает за Деревней Кровавого Копыта и направляет достойных путников к духовным старейшинам деревни.",al={"who gives rite of vision","rite of vision quest giver","кто дает обряд прозрения","обряд прозрения персонаж, выдающий задания"}},{q="Кто такой Зарельман Две Луны?",a="Зарельман Две Луны — опытный тауренский шаман и духовный лидер Деревни Кровавого Копыта. Он готовит путников и посвященных, желающих пройти священные испытания, такие как Обряд прозрения.",al={"who is zarlman","zarlman two moons lore","кто такой зарельман","зарельман две луны предания"}},{q="Почему Обряды Матери-Земли важны для тауренов?",a="Обряды Матери-Земли — традиционный обряд перехода во взрослую жизнь для тауренов. Успешное прохождение доказывает физическую силу, духовную гармонию и неизменное уважение к земле и приносит честь в глазах высших старейшин.",al={"earthmother rites meaning","why do rites of earthmother","значение обрядов матери-земли","зачем обряды матери-земли"}},{q="Can non-tauren undertake the Rite of Vision?",a="Да. Союзникам из Орды, которые путешествуют по Мулгору и заслужили доверие племени Кровавого Копыта, позволено идти путем Матери-Земли, проявляя уважение к традициям тауренов в обмен на благосклонность старейшин.",al={"can orcs do rite of vision","non tauren earthmother","могут ли орки пройти обряд прозрения","не таурены мать-земля"}},{q="Где проходит это испытание?",a="Испытание начинается в Деревне Кровавого Копыта, значительном тауренском поселении у берегов Озера Каменного Быка в центральном Мулгоре, к югу от Громового Утеса.",al={"where is rite of vision","rite of vision location","где обряд прозрения","место обряда прозрения"}}},fp="14,381,23.535.0,19.443.0,27.255.0,22.205.0,25.190.0,61.255.0,44.208.0,33.154.0"}
P.entries["quest:768"] = {n="Добывание шкур",s="«Добывание шкур» — простое торговое задание, которое выдает Верен Долгоног на возвышенностях Громового Утеса. Чтобы обеспечивать столицу и испытывать молодых охотников, Верен обменивает связку выделанных шкур тонкой кожи на изготовленные изделия. Это показывает глубоко укоренившуюся традицию тауренов превращать плоды охоты на равнинах в необходимую одежду и доспехи.",h="«Добывание шкур» — простое торговое задание, которое выдает Верен Долгоног на возвышенностях Громового Утеса.",kw={"gathering leather","leatherworking","light leather","mulgore","tauren hunt","thunder bluff","veren tallstrider","добывание шкур","кожевничество","тонкая кожа","мулгор","охота тауренов","громовой утес","верен долгоног"},ang={["class:Hunter"]="Охотники, выходящие на равнины Мулгора, от природы мастерски выслеживают добычу и собирают тонкие шкуры, которые нужны Верену.",["faction:Horde"]="Снабжение мастеров Громового Утеса сырьем укрепляет молодую столицу, пока она усиливает оборону и торговые связи.",["race:Tauren"]="Для охотников-тауренов почтить убитого зверя, превратив его шкуру в полезные вещи, — важнейшая культурная традиция, передающаяся из поколения в поколение."},sec={{t="Забота о Громовом Утесе",b="В недавно основанной столице на высоких плато Мулгора ремесло и выживание идут рука об руку. Верен Долгоног обрабатывает шкуры, делая одежду и защитные доспехи для растущего населения Громового Утеса. Вместо того чтобы добывать все самому, он призывает молодых искателей приключений, отправляющихся на равнины, приносить свою добычу, превращая обычную охоту в почетную службу обществу."},{t="Путь охоты",b="Для тауренов охота на зверей в степях — не забава, а почетное дело, которое кормит, одевает и укрывает племя. Верен Долгоног ищет охотников, стремящихся принести честь своему клану, и просит именно тонкую кожу, снятую с местных животных. За двенадцать хорошо сохраненных шкур он расплачивается с охотником крепкими изделиями, укрепляя взаимную поддержку, на которой держится общество тауренов."}},faq={{q="Кто такой Верен Долгоног?",a="Верен Долгоног — кожевник, живущий в Громовом Утесе. Он изготавливает одежду и защитные доспехи для народа тауренов и обменивает готовые изделия у охотников, которые приносят ему свежие шкуры с равнин.",al={"veren tallstrider","who gives gathering leather","leather questgiver thunder bluff","верен долгоног","кто выдает задание добывание шкур","кожа персонаж, выдающий задания громовой утес"}},{q="Что нужно Верену Долгоногу?",a="Верен просит двенадцать кусков тонкой кожи, добытой со зверей, бродящих по Мулгору и соседним землям, чтобы изготовить изделия для Громового Утеса.",al={"gathering leather requirements","what to bring veren","gathering leather materials","добывание шкур требования","что принести верену","добывание шкур материалы"}},{q="Где происходит это задание?",a="Задание начинается и заканчивается у Верена Долгонога на вершине Громового Утеса, хотя для его выполнения нужно охотиться на диких зверей в степях внизу.",al={"where is veren tallstrider","gathering leather location","где верен долгоног","добывание шкур местоположение"}},{q="Почему тауренам так важна охота на зверей?",a="В культуре тауренов охота — священное равновесие с Матерью-Землей. Каждая часть убитого зверя находит применение: мясо кормит племя, а кости и выделанные шкуры идут на орудия, шатры и прочные доспехи.",al={"tauren hunting culture","why hunt leather","tauren leather lore","охота тауренов","зачем охотиться на кожу","предания тауренов о коже"}},{q="Может ли любой искатель приключений из Орды взяться за это задание?",a="Да, любой путник, верный Орде, в ком Верен видит желание испытать себя на равнинах, может помочь ему с добыванием шкур.",al={"who can do gathering leather","is gathering leather horde only","кто может выполнить добывание шкур","добывание шкур только для орды"}},{q="Что происходит после доставки кожи?",a="Верен проверяет качество шкур, хвалит охотника за работу и в честный обмен выдает изготовленный предмет снаряжения.",al={"gathering leather turn in","veren tallstrider reward","добывание шкур сдать","верен долгоног награда"}}},fp="17,360,24.407.0,19.436.0,25.210.0,33.153.0,33.147.0,61.219.0,45.137.0,43.128.0"}
P.entries["quest:769"] = {n="Сумка из шкуры кодо",s="«Сумка из шкуры кодо» — торговое задание, которое выдает Верен Долгоног, искусный кожевник-таурен на высоких плато Громового Утеса. В обмен на основные материалы для ремесла он передает традиционный равнинный способ шитья прочных дорожных сумок из крепкой звериной шкуры. Это ранний обряд посвящения для учеников кожевников в Мулгоре.",h="«Сумка из шкуры кодо» — торговое задание, которое выдает Верен Долгоног, искусный кожевник-таурен на высоких...",kw={"coarse thread","kodo","kodo hide bag","leatherworking","light leather","mulgore","thunder bluff","veren tallstrider","грубая нить","кодо","сумка из шкуры кодо","кожевничество","тонкая кожа","мулгор","громовой утес","верен долгоног"},ang={["faction:Horde"]="Мастера Громового Утеса поставляют необходимые материальные товары, которые поддерживают снаряжение охотников, разведчиков и воинов Орды по всему центральному Калимдору.",["race:Tauren"]="Для Шу'хало умение делать надежное снаряжение из шкур могучих кодо — важный шаг к почитанию даров Матери-Земли и сохранению заветов предков."},sec={{t="Урок на плато",b="На ремесленных возвышенностях Громового Утеса Верен Долгоног чтит давнюю кочевую традицию ничего не тратить впустую после охоты. Чтобы заслужить его наставления, начинающий кожевник должен принести ему выделанную тонкую кожу и прочную нить. Показав умение обращаться с основными материалами, ученики доказывают, что готовы создавать вещи, достойные того, чтобы носить в них снаряжение для выживания по суровым просторам Калимдора."},{t="Дух кодо",b="Для тауренов кодо — символ выносливости, силы и твердой решимости. Его толстая шкура защищает от колючих зарослей, пронизывающего ветра и звериных когтей. Изготовление сумок и одежды из шкуры кодо — не просто практичное дело, а выражение почтения к животному, которое кормило и носило Шу'хало на протяжении бесчисленных поколений на равнинах Мулгора."}},faq={{q="Кто выдает задание «Сумка из шкуры кодо»?",a="Задание выдает Верен Долгоног, таурен — учитель кожевничества и торговец из Громового Утеса.",al={"quest giver","where to get kodo hide bag quest","veren tallstrider location","персонаж, выдающий задания","где взять задание сумка из шкуры кодо","где верен долгоног"}},{q="Кто может взяться за это задание?",a="Это учебное задание от Верена Долгонога могут получить только искатели приключений, обученные кожевничеству и достигшие уровня навыка ученика не ниже 10.",al={"who can take this quest","quest requirements","profession requirement","кто может взять задание","требования задания","требования к профессии"}},{q="Какие материалы нужны Верену Долгоногу?",a="Ему нужны четыре куска тонкой кожи и четыре мотка грубой нити, чтобы пополнить торговые запасы, прежде чем поделиться выкройкой.",al={"what items are needed","kodo hide bag materials","quest turn-in items","какие предметы нужны","сумка из шкуры кодо материалы","предметы для сдачи задания"}},{q="Почему шкура кодо так важна для ремесленников-тауренов?",a="Кодо воплощают стойкость и физическую мощь — качества, глубоко ценимые тауренами. Изготовление прочного снаряжения из их шкур чтит дух животного и дает надежные вещи путникам, пересекающим равнины.",al={"why kodo hide","tauren kodo meaning","kodo importance","зачем шкура кодо","значение кодо для тауренов","важность кодо"}},{q="Чему учит Верен Долгоног после выполнения задания?",a="Получив материалы, Верен обучает ремесленника особым знаниям, необходимым для пошива сумки из шкуры кодо.",al={"quest reward","what do i get","bag pattern","награда за задание","что я получу","выкройка сумки"}},{q="Где можно достать нужные материалы?",a="Тонкую кожу добывают, снимая шкуры с низкоуровневых зверей по всему Мулгору и соседним землям, а грубую нить можно купить у торговцев и торговцев портняжными товарами.",al={"where to get light leather","where to get coarse thread","где взять тонкую кожу","где взять грубую нить"}}},fp="13,362,20.426.0,18.388.0,35.113.0,39.149.0,46.133.0,59.224.0,50.125.0,46.176.0"}
P.entries["quest:770"] = {n="Поцарапанный демоном плащ",s="«Поцарапанный демоном плащ» — рваная шкура, снятая с легендарного белого волка Призрачного Воя, бродящего по травянистым равнинам Мулгора. Отмеченная неизлечимой раной, нанесенной в прошлых схватках с Пылающим Легионом, шкура служит доказательством освобождения зверя от мучений. Доставка ее старейшинам Деревни Кровавого Копыта завершает историю одной трагической местной легенды.",h="«Поцарапанный демоном плащ» — рваная шкура, снятая с легендарного белого волка Призрачного Воя, бродящего по...",kw={"burning legion","camp sungraze","demon scarred cloak","ghost howl","mulgore","skorn whitecloud","white wolf","пылающий легион","поцарапанный демоном плащ","призрачный вой","мулгор","скорн белое облако","белый волк"},ang={["class:Druid"]="Друиды видят в шкуре со следами демонов мрачное напоминание о том, что земля и ее дикие обитатели до сих пор несут незажившие раны после демонического вторжения в Калимдор.",["class:Hunter"]="Для охотника выследить одинокого израненного вожака вроде Призрачного Воя — важнейшее испытание, которое приносит высокую похвалу и дар мастера-охотника от старейшины Скорна Белого Облака.",["race:Tauren"]="Для Шу'хало охота на Призрачного Воя — не жестокость и не завоевание, а мрачный обряд, дарующий измученному существу покой от остаточной скверны Пылающего Легиона."},sec={{t="Память о скверных ранах",b="Призрачный Вой — неуловимый белый волк, известный по всему Мулгору как своей свирепостью, так и скорбным воем. Когда его убивают, он оставляет шкуру, на которой заметны шрамы от гнусной демонической порчи. Эти следы остались после отчаянных сражений волка с вторгшимися демонами Пылающего Легиона — столкновения, которое ранило Призрачного Воя телом и духом задолго после окончания Третьей войны."},{t="Покой для измученного духа",b="Таурены Мулгора глубоко уважают диких зверей своей родины, почитая их как детей Матери-Земли. Передав израненный плащ Скорну Белому Облаку в Деревне Кровавого Копыта, вы подтверждаете гибель измученного хищника. Скорн понимает, какое огромное мастерство требуется, чтобы выследить и одолеть Призрачного Воя, и с грустью надеется, что после смерти истерзанный дух волка наконец обрел покой."}},faq={{q="Что такое «Поцарапанный демоном плащ»?",a="Это рваная шкура, снятая с Призрачного Воя, легендарного белого волка Мулгора. На шкуре видны шрамы от энергии Скверны, оставшиеся после старой битвы с Пылающим Легионом.",al={"what is demon scarred cloak","demon scarred cloak item","ghost howl pelt","что такое поцарапанный демоном плащ","предмет поцарапанный демоном плащ","шкура призрачного воя"}},{q="Откуда на плаще демонические шрамы?",a="Призрачный Вой получил раны в схватках с Пылающим Легионом, когда демонические захватчики двинулись по Калимдору во время Третьей войны.",al={"why is ghost howl scarred","how did ghost howl get scarred","ghost howl legion","почему у призрачного воя шрамы","как призрачный вой получил шрамы","призрачный вой легион"}},{q="Кому отнести плащ?",a="Отнесите плащ Скорну Белому Облаку, старому охотнику-таурену, живущему в Деревне Кровавого Копыта в Мулгоре.",al={"where do i turn in demon scarred cloak","who wants demon scarred cloak","skorn whitecloud turn in","где сдать поцарапанный демоном плащ","кому нужен поцарапанный демоном плащ","скорн белое облако сдать"}},{q="Почему Скорна Белого Облака волнует Призрачный Вой?",a="Скорн Белое Облако — отошедший от дел охотник, который считает Призрачного Воя грозным зверем, сильно пострадавшим от демонической порчи. Он уважает мастерство, нужное для победы над таким существом, и надеется, что его дух наконец обретет покой.",al={"skorn whitecloud lore","why does skorn want ghost howl","скорн белое облако предания","зачем скорну призрачный вой"}},{q="Где найти Призрачного Воя?",a="Призрачный Вой — редкий белый волк, бродящий по холмистым равнинам Мулгора. Обычно его замечают на северных или центральных открытых полях между Плато Красного Облака и Громовым Утесом.",al={"where to find ghost howl","ghost howl location","ghost howl spawn","где найти призрачного воя","местоположение призрачного воя","появление призрачного воя"}},{q="Почему тауренам хочется, чтобы дух волка обрел покой?",a="Культура тауренов подчеркивает гармонию с природой и почтение к диким духам. Поскольку демоническая порча принесла Призрачному Вою бесконечные мучения, его гибель считается милосердным возвращением к Матери-Земле.",al={"tauren belief ghost howl","ghost howl spirit","вера тауренов призрачный вой","дух призрачного воя"}}},fp="23,378,21.424.0,27.421.0,32.174.0,49.141.0,28.104.0,48.224.0,26.172.0,53.220.0"}
P.entries["quest:771"] = {n="Обряд прозрения",s="Обряд прозрения — основополагающее духовное испытание молодых тауренов, покидающих Плато Красного Облака ради остального Мулгора. Чтобы прозреть и получить наставление духов предков, неофиты должны собрать природные реагенты и сварить Воду Провидцев под присмотром Зарельмана Две Луны в Деревне Кровавого Копыта.",h="Обряд прозрения — основополагающее духовное испытание молодых тауренов, покидающих Плато Красного Облака ради...",kw={"ambercorn","bloodhoof village","earth mother","mulgore","rite of vision","water of the seers","well stones","zarlman two-moons","янтарные зерна","деревня кровавого копыта","мать-земля","мулгор","обряд прозрения","вода провидцев","камни колодцев","зарельман две луны"},ang={["class:Druid"]="Друиды глубоко чтят янтарные зерна и камни колодцев, видя в них прямое воплощение растений и живительных вод, которые поддерживают равновесие Мулгора.",["class:Shaman"]="Шаманы узнают в приготовлении Воды Провидцев традиционный ритуал единения с землей, настраивающий дух на незримые стихии перед прямой беседой с духами.",["race:Tauren"]="Для тауренов Обряд прозрения — важная веха в жизни племени, связывающая будущего воина, охотника или мистика с духовным наследием Матери-Земли и предков."},sec={{t="Дары земли",b="Прежде чем будет дано видение, неофит должен показать глубокое понимание природных даров Мулгора. Зарельман Две Луны велит искателю собрать камни колодцев, лежащие возле священных общинных колодцев, и янтарные зерна, упавшие под корни древних деревьев Мулгора. Эти природные элементы — не просто предметы: для тауренов в них заключены скрытая магия и жизненная сила Матери-Земли, готовые к использованию в обряде."},{t="Приготовление Воды Провидцев",b="Собрав все необходимое, Зарельман смешивает камни и янтарные зерна в могучую Воду Провидцев. Если выпить этот обрядовый напиток у племенного огня деревни, разум проясняется и появляется призрачный проводник. Путь за этим видением по равнинам — истинная суть обряда: он проверяет, способен ли неофит ходить между физическим миром и духовным шепотом земли."}},faq={{q="Для чего нужен Обряд прозрения?",a="Обряд прозрения — духовное испытание для тауренов, достигших зрелости и ищущих свой путь. Приготовив и выпив Воду Провидцев, неофит учится общаться с духами и следовать знамениям предков по равнинам Мулгора.",al={"what is rite of vision","why do rite of vision","purpose of rite of vision","что такое обряд прозрения","зачем нужен обряд прозрения","цель обряда прозрения"}},{q="Кто такой Зарельман Две Луны?",a="Зарельман Две Луны — таурен-шаман и провидец из Деревни Кровавого Копыта. Он руководит духовными испытаниями молодых искателей приключений, готовит обрядовые напитки, такие как Вода Провидцев, и толкует знамения Матери-Земли.",al={"who is zarlman","zarlman two moons role","questgiver zarlman","кто такой зарельман","зарельман две луны","персонаж, выдающий задания зарельман"}},{q="Где найти камни колодцев и янтарные зерна?",a="Камни колодцев собирают с земли возле колодцев с пресной водой, разбросанных по Мулгору. Янтарные зерна можно найти у корней больших раскидистых деревьев, растущих на окрестных травянистых равнинах.",al={"where to find ambercorn","well stones location","reagents for rite of vision","где найти янтарные зерна","камни колодцев где","реагенты для обряда прозрения"}},{q="Что происходит после того, как выпьешь Воду Провидцев?",a="Напиток, выпитый у племенного огня, открывает духовное зрение, и появляется призрачный зверь-проводник. Искатель должен следовать за этим духом по равнинам, чтобы узнать следующий этап священного пути.",al={"what happens next rite of vision","water of the seers effect","vision quest follow-up","что дальше обряд прозрения","действие воды провидцев","продолжение задания прозрения"}},{q="Почему тауренам так священны колодцы?",a="Вода — источник жизни Мулгора и драгоценный дар Матери-Земли. Колодцы — священные общинные места, питающие и землю, и стада, поэтому камни, собранные рядом с ними, наполнены духовной силой.",al={"tauren water wells","why are wells sacred","mulgore water","колодцы тауренов","почему колодцы священны","вода мулгора"}},{q="Ведет ли это задание к другим обрядам?",a="Да. Это задание — часть многоэтапной церемонии. Когда Зарельман приготовит Воду Провидцев, неофиты должны выпить ее, проследовать за появившимся видением и предстать перед старейшинами Мулгора.",al={"next quest in rite of vision","is rite of vision a chain","tauren rites chain","следующее задание обряда прозрения","цепочка обряда прозрения","цепочка обрядов тауренов"}}},fp="14,335,24.476.0,30.397.0,42.238.0,25.234.0,42.210.0,51.214.1,47.219.0,38.207.1"}
P.entries["quest:772"] = {n="Обряд прозрения",s="Обряд прозрения — духовная кульминация древнего испытания молодых тауренов в Деревне Кровавого Копыта. Выпив священную Воду Провидцев у племенного костра, неофиты призывают призрачного проводника, который ведет их к предначертанной судьбе.",h="Обряд прозрения — духовная кульминация древнего испытания молодых тауренов в Деревне Кровавого Копыта.",kw={"bloodhoof village","ghost wolf","mulgore","rite of vision","seer wiserunner","tribal fire","water of the seers","zarlman two-moons","деревня кровавого копыта","призрачный волк","мулгор","обряд прозрения","провидец хранитель мудрости","племенной огонь","вода провидцев","зарельман две луны"},ang={["class:Druid"]="Обряд укрепляет почтение к миру природы и духовное смирение перед наставлением звериных обличий.",["class:Shaman"]="Следование за призрачным волком предков — ранний урок хождения между мирами, укрепляющий связь шамана с духами, ведущими Орду.",["race:Tauren"]="Для юных тауренов Обряд прозрения — глубоко священный переход во взрослую жизнь, выражающий единение с предками и послушание духовному наставлению."},sec={{t="Вода Провидцев",b="Собрав необходимые обрядовые травы и пройдя первые испытания веры, неофит получает Воду Провидцев от деревенского шамана Зарельмана Две Луны. Этот могучий напиток нужно выпить перед ревущим племенным огнем в сердце Деревни Кровавого Копыта. Если пить его со сосредоточенным и почтительным умом, священная вода расширяет восприятие за пределы физического зрения, стирая завесу между материальным миром и миром духов."},{t="Вслед за призрачным волком",b="Когда неофит выпивает отвар, в пламени возникает призрачное видение — волк-дух предков. Он не говорит и не сражается, а молча бежит на северо-запад по холмистым равнинам Мулгора. Истинный неофит должен последовать его тихим путем — прочь от деревни, вглубь скалистых холмов, где в уединенном размышлении ждет отшельник Провидец Хранитель Мудрости."},{t="Путь к мудрости",b="Встреча с Провидцем Хранителем Мудрости у входа в его горную пещеру означает успешное завершение видения. Этот путь по травянистым холмам проверяет терпение неофита, доверие к наставлению предков и связь с Матерью-Землей. Пройдя этот обряд, юный искатель приключений получает право на высшее испытание зрелости — Обряд мудрости."}},faq={{q="Что произойдет, если я выпью Воду Провидцев?",a="Если выпить воду у племенного огня в Деревне Кровавого Копыта, она открывает ваши духовные чувства. Вскоре после этого перед пламенем появляется призрачный волк-дух, чтобы указать вам путь.",al={"how does water of seers work","drinking water of the seers","what does the water do","как действует вода провидцев","выпить воду провидцев","что делает вода"}},{q="Куда ведет меня дух-проводник?",a="Призрачный волк бежит на северо-запад от Деревни Кровавого Копыта по холмам Мулгора и ведет прямо к скалистой пещере, где обитает Провидец Хранитель Мудрости.",al={"where does ghost wolf go","who does the wolf lead to","wolf destination","куда идет призрачный волк","к кому ведет волк","цель волка"}},{q="Кто такой Зарельман Две Луны?",a="Зарельман Две Луны — известный таурен-шаман в Деревне Кровавого Копыта, который готовит неофитов к духовной зрелости с помощью обрядов предков и священных отваров.",al={"who gives the rite of vision","zarlman two moons role","кто дает обряд прозрения","зарельман две луны"}},{q="Кто такой Провидец Хранитель Мудрости?",a="Провидец Хранитель Мудрости — старый таурен-мистик, живущий в размышлениях среди скал к северо-западу от Деревни Кровавого Копыта. Неофиты, следующие за своим духовным видением, находят его, чтобы завершить испытание.",al={"who is wiserunner","seer in cave mulgore","кто такой хранитель мудрости","провидец в пещере мулгор"}},{q="Почему воду нужно пить у племенного огня?",a="Племенной костер служит священным якорем для духов предков Деревни Кровавого Копыта. Освященное пламя и священная вода позволяют видению проникнуть в мир яви.",al={"why tribal fire","bonfire rite of vision","почему племенной огонь","костер обряд прозрения"}},{q="Какой обряд следует за Обрядом прозрения?",a="Завершив Обряд прозрения у Провидца Хранителя Мудрости, неофиты направляются на Обряд мудрости — последнее духовное испытание их раннего пути в Мулгоре.",al={"next quest after rite of vision","what comes next","следующее задание после обряда прозрения","что дальше"}}},fp="14,249,22.467.0,24.371.0,16.362.0,49.192.0,36.150.0,25.171.0,23.189.0,49.197.0,41.173.0"}
P.entries["quest:773"] = {n="Обряд мудрости",s="Обряд мудрости — завершающее испытание в традиционных Обрядах Матери-Земли, которые проходят юные искатели приключений в Мулгоре. Очистив зрение Обрядом прозрения, просители отправляются на священное кладбище Красных скал, чтобы пообщаться с Духом предков и получить благословение мертвых.",h="Обряд мудрости — завершающее испытание в традиционных Обрядах Матери-Земли, которые проходят юные искатели...",kw={"ancestral spirit","mulgore","red rocks","rite of wisdom","rites of the earthmother","seer wiserunner","thunder bluff","water of the seers","дух предков","мулгор","красные скалы","обряд мудрости","обряды матери-земли","провидец хранитель мудрости","громовой утес","вода провидцев"},ang={["class:Druid"]="Обряд показывает равновесие между миром живых и вечным круговоротом, за которым присматривает Мать-Земля, и укореняет юных друидов в долге перед землей.",["class:Shaman"]="Прямое общение с Духом предков укрепляет основной долг шамана — чтить мертвых и хранить верность духам, оберегающим Мулгор.",["race:Tauren"]="Для шу'хало получение покрова от предков у Красных скал — высшая веха перехода во взрослую жизнь и принятия среди старейшин племени."},sec={{t="Испытание Красных скал",b="Очистив восприятие Обрядом прозрения, юные защитники направляются к востоку от Громового Утеса, к Красным скалам. На этом древнем кладбище покоятся останки и неупокоенные духи тех, кто сражался и погиб ради мирной жизни в Мулгоре. Чтобы пройти испытание, нужно подойти к месту упокоения с должным почтением, преодолеть все угрозы, бродящие по холмам, и обратиться за советом к почитаемым мертвым."},{t="Передача покрова",b="На вершине Красных скал общение с Духом предков — это испытание не боевой силы, а духовной готовности и преемственности. Покоящиеся там духи представляют поколение, которое сражалось бок о бок с Кэрном Кровавым Копытом, чтобы основать Громовой Утес и защитить племена. Получив их благословение, проситель официально наследует торжественный долг защищать город и занимает свое место признанного взрослого и защитника, достойного с гордостью войти в Громовой Утес."}},faq={{q="Для чего нужен Обряд мудрости?",a="Обряд мудрости завершает Обряды Матери-Земли, соединяя видения юности с серьезной ответственностью взрослой жизни. Получив благословение духов предков, просители доказывают, что чтят жертвы предшественников и готовы защищать Громовой Утес.",al={"why do rite of wisdom","what does rite of wisdom do","rite of wisdom purpose","зачем нужен обряд мудрости","что дает обряд мудрости","цель обряда мудрости"}},{q="Кто посылает на Обряд мудрости?",a="Провидец Хранитель Мудрости в своей пещере к северо-западу от Деревни Кровавого Копыта посылает неофитов на это испытание, когда они успешно завершили Обряд прозрения и выпили Воду Провидцев.",al={"who gives rite of wisdom","where do i start rite of wisdom","кто дает обряд мудрости","где начать обряд мудрости"}},{q="Где найти Дух предков?",a="Дух предков находится у Красных скал — древнего кладбища тауренов среди скалистых утесов к востоку от Громового Утеса.",al={"ancestral spirit location","where is the spirit","where to find ancestral spirit","где дух предков","где находится дух","как найти дух предков"}},{q="Почему сначала нужен Обряд прозрения?",a="Только те, кто выпил Воду Провидцев и очистил свое духовное зрение, способны воспринять и получить благословение древних духов у Красных скал.",al={"why do vision first","rite of vision prerequisite","water of seers requirement","почему сначала прозрение","требование обряда прозрения","вода провидцев требование"}},{q="Что происходит после завершения Обряда мудрости?",a="Заслужив одобрение предков, неофиты получают указание совершить свое официальное путешествие на высокие уступы Громового Утеса.",al={"what next after rite of wisdom","next quest after rite of wisdom","что дальше после обряда мудрости","следующее задание после обряда мудрости"}},{q="Какие существа угрожают землям Красных скал?",a="На священное кладбище у Красных скал вторглись агрессивные гноллы Бледногривы, которые таятся на каменистых тропах, ведущих к древнему месту погребения.",al={"enemies at red rocks","what guards red rocks","gnolls at red rocks","враги у красных скал","кто охраняет красные скалы","гноллы у красных скал"}}},fp="14,321,22.468.0,18.492.0,42.310.0,36.186.0,39.137.0,41.175.0,49.138.0,49.160.0"}
P.entries["quest:775"] = {n="Путешествие в Громовой Утес",s="Путешествие в Громовой Утес — заключительное паломничество, завершающее испытания юного героя в Мулгоре. Пройдя священные Обряды Матери-Земли под руководством духов, искатель приключений удостаивается встречи с верховным вождем тауренов Кэрном Кровавым Копытом.",h="Путешествие в Громовой Утес — заключительное паломничество, завершающее испытания юного героя в Мулгоре.",kw={"ancestral spirit","cairne bloodhoof","high rise","journey into thunder bluff","mulgore","rites of the earthmother","thunder bluff","дух предков","кэрн кровавое копыто","высокая вершина","путешествие в громовой утес","мулгор","обряды матери-земли","громовой утес"},ang={["faction:Horde"]="Готовность тауренов принять любую союзную расу, прошедшую их священные традиции, говорит о взаимном уважении, на котором держится молодая Орда.",["race:Tauren"]="Для молодого таурена встреча с Кэрном Кровавым Копытом после завершения обрядов Матери-Земли — окончательный порог взрослости и племенной чести."},sec={{t="Завершенный обряд посвящения",b="Прежде чем любой путник или молодой воин сможет по-настоящему считать, что проявил себя в Мулгоре, он должен пройти древние Обряды Матери-Земли. Эти испытания проверяют силу, зоркость и мудрость на холмистых равнинах и в местах предков этой земли. Когда Дух предков признает последний обряд, посвящаемый считается достойным войти в город Громовой Утес не как простой гость, а как почетный защитник народа тауренов."},{t="Подъем на Высокую вершину",b="Задание направляет путника от священной земли, где бродят духи, прямо на головокружительные высоты Громового Утеса. Город, расположенный на вершинах плоскогорий, — маяк мира, высеченный из красного камня и поддерживаемый длинными веревочными мостами и огромными деревянными подъемниками. Там, на Высокой вершине, верховный вождь Кэрн Кровавое Копыто ждет, чтобы лично поприветствовать тех, кто прошел путем предков."}},faq={{q="Кто отправляет вас в это путешествие?",a="Задание выдает Дух предков после того, как вы завершите Обряд мудрости — последний этап традиционных Обрядов Матери-Земли.",al={"who gives quest","ancestral spirit quest","quest giver","кто дает задание","задание духа предков","дух предков","персонаж, выдающий задания"}},{q="Где найти Кэрна Кровавого Копыта?",a="Кэрн Кровавое Копыто обитает на Высокой вершине — центральном возвышенном плато Громового Утеса, с которого открывается вид на окружающие красные плато и равнины.",al={"cairne location","where is cairne","thunder bluff leader","где кэрн","местонахождение кэрна","предводитель громового утеса"}},{q="В чем значение выполнения этого задания?",a="Оно служит официальным выпуском из начальных приключений Мулгора. Явившись к Кэрну, вы будете признаны руководством тауренов и готовы выполнять обязанности по всей Орде.",al={"why visit cairne","rites meaning","significance of thunder bluff journey","зачем идти к кэрну","смысл обрядов","значение путешествия в громовой утес"}},{q="Только ли таурены проходят это путешествие?",a="Хотя это глубоко традиционный обряд посвящения тауренов, любой представитель Орды, доказавший свою преданность через Обряды Матери-Земли, удостаивается той же чести и отправляется на встречу с верховным вождем.",al={"can orcs do this","who can do journey to thunder bluff","races","могут ли орки","кто может пройти путешествие в громовой утес","расы"}},{q="Что происходит после разговора с Кэрном?",a="Кэрн приветствует вас в своем доме, признает ваши деяния и направляет вас к более масштабным конфликтам, с которыми Орда сталкивается по всему Калимдору.",al={"next quest","what after cairne","after journey into thunder bluff","следующее задание","что после кэрна","после путешествия в громовой утес"}},{q="Как добраться до Высокой вершины в Громовом Утесе?",a="Поднимитесь на огромных механических подъемниках с равнин на плато, затем пересеките веревочные и деревянные мосты, ведущие к центральной площадке Высокой вершины, где стоит жилище вождя.",al={"getting to high rise","how to get to cairne","thunder bluff elevators","как добраться до высокой вершины","как попасть к кэрну","подъемники громового утеса"}}},fp="26,296,27.451.0,26.407.0,30.141.0,34.138.0,50.216.0,37.208.0,38.141.0,48.197.0"}
P.entries["quest:776"] = {n="Обряды Матери-Земли",s="Это испытание, назначенное лично верховным вождем Кэрном Кровавым Копытом, поручает восходящим героям выследить великого кодо Арра'чею на равнинах Мулгора. Даже если посвящаемый прошел традиционные обряды, Кэрн ждет, что его народ будет постоянно подтверждать свою силу, умение выслеживать и преданность племени. Рог Арра'чеи доказывает, что искатель приключений готов служить всей Орде за пределами плоскогорий.",h="Это испытание, назначенное лично верховным вождем Кэрном Кровавым Копытом, поручает восходящим героям...",kw={"arra'chea","arrachea","bloodhoof","cairne","earthmother","horn","hunt","kodo","mulgore","thunder bluff","арра'чея","кровавое копыто","кэрн","мать-земля","рог","охота","кодо","мулгор","громовой утес"},ang={["class:Hunter"]="Выслеживание одинокого бродячего исполина вроде Арра'чеи на золотистых равнинах воплощает древние охотничьи философии, которые следопыты-таурены передают из поколения в поколение.",["faction:Horde"]="Победа над Арра'чеей дает Громовому Утесу необходимые пищу, кожу и материалы и показывает дух общего выживания, на котором держится молодая Орда.",["race:Tauren"]="Предстать перед Кэрном Кровавым Копытом с рогом Арра'чеи — высший обряд посвящения для молодого шу'хало, доказывающий, что ваше мастерство чтит и ваших предков, и стада Мулгора."},sec={{t="Мерило вождя",b="Прибытие в Громовой Утес означает конец простой юности для тауренов, но верховный вождь Кэрн Кровавое Копыто не позволяет молодым охотникам почивать на лаврах. Для Кэрна место среди высоких утесов — лишь начало ответственности перед Объединенными племенами тауренов. Вместо того чтобы посылать посвящаемых против мелких вредителей, он требует доказательства настоящего охотничьего мастерства: выследить и чисто добыть одного из самых известных странствующих зверей Мулгора."},{t="Охота на Арра'чею",b="Цель — Арра'чея, огромный легендарный кодо, чей кольцевой путь пролегает по золотистым травам к северо-востоку от Громового Утеса. Чтобы сразить такое создание, нужна не только грубая сила: нужно терпеливо подкрадываться по открытой саванне и уважать титана равнин. Рог Арра'чеи, доставленный на Высокую вершину, приносит не только личную славу, но и припасы для города: Кэрн тут же отправляет свежевальщиков и собирателей, чтобы ничто от священного зверя не пропало."}},faq={{q="Кто выдает это задание?",a="Верховный вождь Кэрн Кровавое Копыто лично поручает это дело со своего места на вершине Громового Утеса.",al={"quest giver","who gives rites of the earthmother","cairne quest","персонаж, выдающий задания","кто дает обряды матери-земли","задание кэрна"}},{q="Кто такой Арра'чея?",a="Арра'чея — грозный, известный кодо, бродящий по равнинам Мулгора. Его огромный рог служит доказательством умения охотника выслеживать добычу и его боевой доблести.",al={"who is arrachea","what is arrachea","arrachea lore","кто такой арра'чея","что такое арра'чея","предания об арра'чее"}},{q="Где найти Арра'чею?",a="Арра'чея обычно бродит по широкой круговой тропе к северо-востоку от утесов Громового Утеса, медленно обходя открытые холмистые равнины по часовой стрелке.",al={"where is arrachea","arrachea location","arrachea path","где арра'чея","местонахождение арра'чеи","путь арра'чеи"}},{q="Почему Кэрн просит об этой охоте, если я уже прошел прежние обряды?",a="В культуре тауренов получение первого места — не конец долга. Кэрн учит, что силу, смирение и охотничье мастерство нужно постоянно доказывать ради блага племени.",al={"why do this quest","why kill arrachea","point of rites","зачем это задание","зачем убивать арра'чею","смысл обрядов"}},{q="Что происходит с телом Арра'чеи после того, как рог взят?",a="Следуя тауренским традициям почитания добычи, Кэрн посылает отряд собирателей забрать мясо и шкуру павшего зверя, чтобы добыча накормила и одела Громовой Утес.",al={"arrachea meat","what happens to the kodo","carcass lore","мясо арра'чеи","что будет с кодо","туша"}},{q="Это то же самое задание, что и начальные обряды?",a="Нет. Пока ранние испытания в Лагере Нараче обучают посвящаемого основам Обрядов Матери-Земли, это заключительное испытание в Громовом Утесе — личная проверка Кэрна, достойны ли вы по-прежнему называться охотником.",al={"rites of the earthmother differences","which rites quest","camp narache rites","различия обрядов матери-земли","какое задание обрядов","обряды лагеря нараче"}}},fp="24,439,21.449.0,22.491.0,21.108.0,18.161.0,27.154.0,78.183.0,57.183.0,50.204.0"}
P.entries["quest:7781"] = {n="Владыка Черной горы",s="Владыка Черной горы — задание Альянса, которое начинается, когда вы забираете отсеченную голову черного дракона Нефариана в Логове Крыла Тьмы. Доставка этого чудовищного трофея верховному лорду Болвару Фордрагону в Крепость Штормграда возвещает падение хозяина Черной горы. Это одна из величайших военных побед, которые Альянс праздновал в недавней истории.",h="Владыка Черной горы — задание Альянса, которое начинается, когда вы забираете отсеченную голову черного...",kw={"blackrock mountain","blackwing lair","highlord bolvar fordragon","head of nefarian","lord of blackrock","nefarian","stormwind keep","черная гора","логово крыла тьмы","верховный лорд болвар фордрагон","голова нефариана","владыка черной горы","нефариан","крепость штормграда"},ang={["faction:Alliance"]="Преподнесение головы черного дракона Нефариана — одно из высших военных достижений Альянса, решительно сокрушившее замыслы драконьего рода против земель людей.",["race:Human"]="Штормград пережил бесчисленные вторжения и заговоры, устроенные из Черной горы; поражение ее владыки приносит королевству долгожданное возмездие и облегчение."},sec={{t="Памятник победе",b="Нефариан, коварный повелитель черного драконьего рода и владыка Верхней Вершины Черной горы, давно отбрасывал жуткую тень на окрестные человеческие королевства. Его убийство — не просто акт выживания, оно означает полный крах его извращенных опытов и интриг. Доставка его огромной, покрытой боевыми шрамами головы в Штормград служит неопровержимым доказательством того, что Владыка Черной горы пал от рук величайших героев Альянса."},{t="Прием в Крепости Штормграда",b="Жуткий трофей приносят прямо верховному лорду Болвару Фордрагону, который правит королевством из тронного зала Крепости Штормграда. Внезапное появление отсеченной головы дракона в королевском дворе потрясает присутствующих и вызывает мгновенное благоговение. Для королевства, и без того измученного внутренними политическими распрями и внешними угрозами, эта победа становится мощным подъемом боевого духа и незабываемой страницей в летописи Альянса."}},faq={{q="О чем задание «Владыка Черной горы»?",a="Это задание начинается, когда искатели приключений забирают отсеченную Голову Нефариана в Логове Крыла Тьмы. Победителю предлагается доставить грандиозный трофей в Штормград и вручить его верховному лорду Болвару Фордрагону от имени королевства.",al={"lord of blackrock quest","nefarian head quest alliance","head of nefarian stormwind","задание владыка черной горы","задание голова нефариана альянс","голова нефариана штормград"}},{q="Кто такой Нефариан?",a="Нефариан — великий черный дракон, сын Смертокрыла. Правя с высот Логова Крыла Тьмы в Черной горе, он командовал орками Черной горы и проводил зловещие опыты по созданию разноцветного драконьего рода.",al={"who is nefarian","lord of blackrock","nefarian lore","кто такой нефариан","владыка черной горы","предания о нефариане"}},{q="Кто такой верховный лорд Болвар Фордрагон?",a="Верховный лорд Болвар Фордрагон — паладин, правящий Штормградом в качестве регента в отсутствие короля Вариана Ринна. Он вершит суд в тронном зале Крепости Штормграда и присматривает за юным принцем Андуином Ринном.",al={"bolvar fordragon","who is bolvar","highlord bolvar","болвар фордрагон","кто такой болвар","верховный лорд болвар"}},{q="Почему трофей приносят в Крепость Штормграда?",a="Владычество Нефариана в Черной горе было смертельной угрозой для королевства Штормград и всего южного континента. Доставка трофея прямо военному руководству королевства подтверждает гибель дракона и позволяет королевству сплотиться вокруг героического подвига.",al={"why stormwind","why bring head to keep","why bolvar","почему штормград","зачем нести голову в крепость","почему болвар"}},{q="Что происходит после передачи головы Болвару?",a="Верховный лорд Болвар Фордрагон потрясен подвигом и объявляет, что эта победа навсегда останется в истории. Это ведет к следующему этапу события, когда голову публично выставляют на обозрение всему Штормграду.",al={"what happens next","lord of blackrock part 2","nefarian head turn in","что дальше","владыка черной горы часть 2","сдача головы нефариана"}},{q="Влияет ли сдача этой головы на весь город?",a="Да. Когда голову Нефариана доставляют в столицу и поднимают над городскими воротами, это возвещает о гибели дракона всем горожанам и солдатам и наполняет защитников Штормграда торжествующей решимостью.",al={"city buff","rallying cry","head of nefarian buff","бонус города","боевой клич","бонус головы нефариана"}}},fp="21,369,21.471.0,26.462.0,42.234.0,16.232.0,33.202.0,45.280.0,45.243.0,48.221.0"}
P.entries["quest:7782"] = {n="Владыка Черной горы",s="Это задание — заключительный итог кампании против сил Черной горы. Доложив верховному адмиралу Джес-Терет в Крепости Штормграда, герои направляются на Аллею Героев, где Фельдмаршал Стоунбридж организует у городских ворот публичное чествование на глазах у всего Альянса.",h="Это задание — заключительный итог кампании против сил Черной горы.",kw={"blackrock","dragonslayer","jes-tereth","nefarian","rallying cry","stonebridge","stormwind","valley of heroes","черная гора","убийца драконов","джес-терет","нефариан","боевой клич","стоунбридж","штормград","аллея героев"},ang={["class:Warrior"]="Огромное воодушевление, которое дает Боевой клич убийцы драконов, придает сил воинам, отправляющимся на защиту королевства.",["faction:Alliance"]="Демонстрация головы Нефариана на Аллее Героев объединяет все расы Альянса и напоминает жителям Стальгорна, Дарнасса и Гномрегана, что темные силы, терзающие Восточные королевства, можно сокрушить.",["race:Human"]="Для королевства Штормград победа над повелителем Черной горы устраняет смертельную угрозу со стороны драконов, притаившихся прямо на северной границе."},sec={{t="Триумф города",b="Кампания против клана Черной горы и отродий черного драконьего рода завершается публичной демонстрацией победы. После того как отрубленную голову Нефариана представили в Крепости Штормграда, верховный лорд Болвар Фордрагон направляет героев через весь город на Аллею Героев. Там их ожидает Фельдмаршал Стоунбридж, чтобы принять жуткий трофей и начать празднования по всему городу."},{t="Сплочение Альянса",b="Когда Фельдмаршал Стоунбридж вздергивает отрубленную голову Нефариана на большие арки главного входа в Штормград, весь город ощущает это потрясение. Зрелище сопровождается Боевым кличем убийцы драконов, который вдохновляет защитников города, приезжих сановников и простых горожан: отродье Смертокрыла получило сокрушительный удар."}},faq={{q="Что произойдет, когда вы выполните это задание?",a="Фельдмаршал Стоунбридж вешает отрубленную голову Нефариана высоко на каменной арке ворот на Аллее Героев. Это накладывает на весь Штормград эффект Боевого клича убийцы драконов, повышающий боевую мощь всех дружественных игроков и стражей.",al={"nefarian head quest turn in","what does stonebridge do","rallying cry trigger","сдать голову нефариана","что делает стоунбридж","боевой клич убийцы драконов"}},{q="Кто такой Фельдмаршал Стоунбридж?",a="Фельдмаршал Стоунбридж — высокопоставленный офицер армии Штормграда, расквартированный на Аллее Героев возле входа в Штормград. Он организует публичное чествование крупных военных побед, в том числе вывешивание голов поверженных драконьих угроз.",al={"stonebridge","field marshal stonebridge","стоунбридж","фельдмаршал стоунбридж"}},{q="Почему верховный лорд Болвар Фордрагон посылает вас сюда?",a="Получив в тронном зале подтверждение поражения Нефариана, Болвар приказывает вам принести весть к городским воротам, чтобы военные Альянса открыто явили победу и подняли боевой дух по всей столице.",al={"bolvar","why go to valley of heroes","болвар","зачем идти на аллею героев"}},{q="Влияет ли эта сдача задания на весь город?",a="Да. Когда Стоунбридж принимает трофей, по Штормграду разносится торжественное объявление, и Боевой клич убийцы драконов накладывается на всех в пределах города.",al={"world buff nefarian","does stormwind get buff","бонус нефариана","дает ли штормград бонус"}},{q="Где находится Аллея Героев?",a="Аллея Героев — величественная въездная дорога в Штормград, обрамленная высокими статуями героев Второй войны, прошедших через Темный портал.",al={"valley of heroes location","where is stonebridge","где аллея героев","где стоунбридж"}},{q="Кто такой «Владыка Черной горы»?",a="Владыка Черной горы — черный дракон Нефариан, старший сын Смертокрыла и правитель верхних шпилей Черной горы.",al={"who is lord of blackrock","nefarian identity","кто владыка черной горы","кто такой нефариан"}}},fp="21,326,16.395.1,21.375.0,42.263.1,33.273.0,49.210.1,40.173.1,38.167.0,32.128.2"}
P.entries["quest:7783"] = {n="Владыка Черной горы",s="Это задание завершает штурм Логова Крыла Тьмы: героям поручено доставить отрубленную голову Нефариана в Оргриммар. Принеся чудовищный трофей вождю Траллу, они получают доказательство того, что отродья черного драконьего рода сломлены. Это момент великого триумфа Орды над одним из ее самых коварных врагов.",h="Это задание завершает штурм Логова Крыла Тьмы: героям поручено доставить отрубленную голову Нефариана в...",ang={["class:Warrior"]="Принести самому Вождю огромный отрубленный череп повелителя драконов — одно из высших свидетельств воинской славы.",["faction:Horde"]="Гибель Нефариана восстанавливает честь Орды и освобождает земли Черной горы от власти дракона, поработившего отступническую Темную Орду.",["race:Orc"]="Для орков вручение головы Нефариана Траллу — возмездие чудовищу, которое дергало за ниточки Ренда Чернорука и порабощало кланы орков ради своих опытов."},sec={{t="Трофей разрушения",b="Нефариан, вдохновитель Логова Крыла Тьмы и предводитель черных драконов в Восточных королевствах, наконец пал. Его огромная голова со следами битв — неопровержимое доказательство его гибели. Для воинов Орды вынести такой великий трофей из пылающих высот Черной горы и доставить его через Великое море в Дуротар — деяние непревзойденной славы."},{t="Суд Вождя",b="Трофей вручают прямо вождю Траллу. Тралл знает порчу Черной горы лучше почти всех: он освободил свой народ из лагерей для военнопленных и увел его от демонической жажды крови Старой Орды. Гибель сына Смертокрыла оправдывает годы борьбы и разрушает жестокую власть темного дракона над орками клана Черной горы."},{t="Тени отца",b="Хотя смерть Нефариана прекращает извращенные генетические опыты черного драконьего рода, его падение не устраняет всех опасностей. Увидев обезглавленного дракона, Тралл замечает, что сам Смертокрыл наверняка пробуждается, узнав о гибели сына. Победа настоящая, но она служит суровым напоминанием о более страшных ужасах, дремлющих под поверхностью мира."}},faq={{q="Кто такой Нефариан?",a="Нефариан — огромный черный дракон, сын Смертокрыла. Со своего насеста высоко в Логове Крыла Тьмы на Черной горе он проводил извращенные опыты по созданию радужного драконьего рода и манипулировал смертными расами, особенно Темной Ордой, заставляя их исполнять его волю.",al={"nefarian backstory","who is nefarian","black dragon lord","история нефариана","кто такой нефариан","повелитель черных драконов"}},{q="Почему трофей доставляют Траллу?",a="Тралл — Вождь Орды. Он вывел орков из лагерей для военнопленных и увел от демонической жажды крови Старой Орды, поэтому доказательство гибели дракона, поработившего орков Черной горы и Темную Орду, должно быть в его руках.",al={"why thrall","who receives the head","почему тралл","кто получает голову"}},{q="Что происходит в Оргриммаре, когда сдают голову?",a="Когда голову Нефариана возвращают и водружают в Оргриммаре, в городе начинается празднование. Вся столица получает Боевой клич убийцы драконов, повышающий боевую мощь всех находящихся рядом представителей Орды.",al={"head buff","orgrimmar world buff","rallying cry buff","бонус головы","бонус оргриммара","боевой клич убийцы драконов"}},{q="Есть ли у этого задания аналог для Альянса?",a="Да, герои Альянса выполняют такое же задание с названием «Владыка Черной горы», доставляя голову Нефариана верховному лорду Болвару Фордрагону в Крепости Штормграда, чтобы даровать своему городу то же благословение.",al={"alliance version","alliance counterpart","версия альянса","аналог альянса"}},{q="Why is Deathwing a concern?",a="Deathwing is Nefarian's father and the patriarch of the black dragonflight. Defeating his son does not remove the danger posed by the dragonfather.",al={"evil one stirs","who is the evil one","злой пробуждается","кто злой"}},{q="Откуда берется голова?",a="Задание начинается с добычи Головы Нефариана прямо с трупа Нефариана после победы над ним на вершине Логова Крыла Тьмы.",al={"how to get head of nefarian","quest starter item","как получить голову нефариана","предмет начала задания"}}},fp="21,364,16.380.0,23.395.0,21.372.1,16.273.0,38.243.0,53.225.0,44.200.0,27.147.0,30.135.0"}
P.entries["quest:7784"] = {n="Владыка Черной горы",s="Это задание — последняя доставка отрубленной головы Нефариана руководителям Оргриммара. Доказав Траллу гибель черного дракона, герои направляются к верховному правителю Саурфангу в Аллее Силы, чтобы выставить трофей перед всей Ордой.",h="Это задание — последняя доставка отрубленной головы Нефариана руководителям Оргриммара.",kw={"blackwing lair","eitrigg","head of nefarian","natoj","orgrimmar","nefarian","valley of strength","логово крыла тьмы","эйтригг","голова нефариана","натож","оргриммар","нефариан","аллея силы"},ang={["faction:Horde"]="Публичный показ головы Нефариана укрепляет новый порядок Тралла и доказывает мощь обновленной Орды перед черным драконом, который манипулировал орками Черной горы.",["race:Orc"]="Для орков падение дракона, державшего клан Черной горы в рабстве, — глубокое очищение, смывающее бесчестную тень с их народа."},sec={{t="Трофей для Орды",b="После того как черный дракон Нефариан убит на вершине Логова Крыла Тьмы, его голову приносят в Оргриммар как доказательство победы. Вождь Тралл подтверждает гибель сына Смертокрыла и отправляет победителя к верховному правителю Саурфангу в Аллее Силы. Там жуткие останки готовят к публичному показу — как предостережение врагам и боевой клич для истинной Орды."},{t="Наследие завоевано",b="Нефариан властвовал на высотах Черной горы, подчиняя своей воле орков Черной горы и Темную Орду. Сразив его и высоко подняв его голову в Аллее Силы, Орда вождя Тралла наносит мощный удар по черному драконьему роду, а Саурфанг призывает весь Оргриммар насладиться Боевым кличем убийцы драконов."}},faq={{q="Для чего нужно это задание?",a="Это заключительная сдача за убийство Нефариана. Показав доказательство Траллу, вы докладываете верховному правителю Саурфангу в Аллее Силы Оргриммара, чтобы получить почести и выставить отрубленную голову на всеобщее обозрение.",al={"what does this quest do","lord of blackrock turn in","why go to saurfang","что дает это задание","сдача владыки черной горы","зачем идти к саурфангу"}},{q="Кто такой верховный правитель Саурфанг?",a="Верховный правитель Саурфанг — опытный орк-воин и один из величайших героев Орды. Он находится в Аллее Силы в Оргриммаре, где принимает голову и велит водрузить ее на всеобщее обозрение.",al={"who is saurfang","high overlord saurfang role","кто такой саурфанг","верховный правитель саурфанг","роль саурфанга"}},{q="Почему голову Нефариана выставляют на показ?",a="Водружение головы черного дракона бесспорно доказывает, что повелитель Черной горы пал. Это укрепляет боевой дух защитников Оргриммара, а на всех в городе накладывается Боевой клич убийцы драконов.",al={"why mount nefarians head","nefarian head display orgrimmar","зачем вешать голову нефариана","голова нефариана в оргриммаре"}},{q="Кем был Нефариан?",a="Нефариан был огромным черным драконом и сыном Смертокрыла. Из Логова Крыла Тьмы на Черной горе он командовал орками Черной горы и Темной Ордой и вывел радужный драконий род.",al={"who was nefarian","nefarian lore","кто такой нефариан","предыстория нефариана"}},{q="Где находится верховный правитель Саурфанг?",a="Саурфанг несет стражу в Аллее Силы — центральном входном районе Оргриммара.",al={"where is saurfang","saurfang location","где саурфанг","местонахождение саурфанга"}},{q="Какую роль в этом играет Тралл?",a="Вождь Тралл принимает голову первым. Подтвердив смерть Нефариана, он отправляет вас к Саурфангу, чтобы трофей официально водрузили.",al={"why thrall","thrall involvement","почему тралл","роль тралла"}}},fp="21,264,22.393.0,19.348.1,34.226.0,30.206.0,38.233.0,17.190.0,40.95.0,35.139.0"}
P.entries["quest:780"] = {n="Боевые вепри",s="«Боевые вепри» — охотничье задание-посвящение, которое выдает Грулл Соколиный Ветер в Лагере Нараче. Молодым тауренам поручено истреблять свирепых обученных для боя вепрей Ежевичной лощины, чтобы защитить земли племени и накормить молодежь поселения.",h="«Боевые вепри» — охотничье задание-посвящение, которое выдает Грулл Соколиный Ветер в Лагере Нараче.",kw={"battleboar","brambleblade ravine","bristleback","camp narache","grull hawkwind","mulgore","quilboar","red cloud mesa","боевой вепрь","ежевичная лощина","дыбогрив","лагерь нараче","грулл соколиный ветер","мулгор","свинобраз","плато красного облака"},ang={["class:Hunter"]="Столкновение со зверями, которых Дыбогривы обучили злобе, учит молодых охотников резкому различию между дикой природой и животными, превращенными в орудия войны.",["profession:Cooking"]="Просьба принести бока и рыла подчеркивает основу тауренской кулинарии: даже жесткое, грубое мясо всегда можно превратить в сытное, питательное рагу.",["race:Tauren"]="Это задание воплощает тауренский баланс: защищать земли Матери-Земли и при этом не терять ничего из добытого в бою, превращая боевых зверей врагов в пищу для телят лагеря."},sec={{t="Угроза на границе",b="К востоку от Плато Красного Облака лежит Ежевичная лощина — поросший колючками шрам, который удерживают свинобразы из племени Дыбогривов. По мере того как напряженность между Шу'хало и свинобразами перерастает в открытую войну, Дыбогривы обучили свирепых боевых вепрей, чтобы прощупывать границы тауренов и терроризировать их исконные охотничьи угодья. Если их не остановить, эти агрессивные звери будут угрожать не только охотничьим тропам, но и безопасности самого Лагеря Нараче."},{t="Прокормить племя",b="Для тауренов охота — одновременно оборона и общая пища. Грулл Соколиный Ветер велит посвящаемым приносить рыла и бока убитых боевых вепрей. Даже звери, обученные свинобразами, не пропадают зря: их мясо и хрящи идут на сытное рагу для молодежи племени, и оружие свинобразов становится пищей для следующего поколения защитников-тауренов."}},faq={{q="Почему боевые вепри нападают на плато?",a="Боевых вепрей намеренно вырастили и обучили свинобразы Дыбогривы, обитающие в Ежевичной лощине. Свинобразы используют их как ударных животных, чтобы донимать тауренов и вторгаться в охотничьи угодья племени на Плато Красного Облака.",al={"battleboar aggression","why battleboars hostile","battleboars attacking","агрессия боевых вепрей","почему вепри враждебны","боевые вепри нападают"}},{q="Кто посылает игроков на эту охоту?",a="Грулл Соколиный Ветер, выдающийся охотник и старейшина в Лагере Нараче, направляет молодых тауренов через заключительные испытания их начального обучения.",al={"quest giver battleboars","who gives the battleboars quest","grull hawkwind role","кто выдает задание боевые вепри","роль грулла соколиного ветра"}},{q="Где можно найти боевых вепрей?",a="Они бродят рядом с Ежевичной лощиной и внутри нее — суровым каньоном к востоку от Лагеря Нараче, на восточном краю Плато Красного Облака.",al={"battleboar location","where are battleboars","brambleblade ravine boars","где боевые вепри","расположение боевых вепрей","вепри ежевичной лощины"}},{q="Что делают с мясом, добытым у вепрей?",a="Бока и рыла боевых вепрей приносят в Лагерь Нараче, где из них варят рагу для детей и старейшин поселения, следуя тауренской традиции использовать все, что добыто на охоте.",al={"battleboar flanks use","what is boar meat for","boar stew","бока боевых вепрей","для чего мясо вепря","рагу из вепря"}},{q="Как это задание вписывается в конфликт со свинобразами?",a="Оно служит ранним введением в открытую вражду между тауренами и племенем Дыбогривов. Истребление их боевых животных — прямое послание свинобразам до начала открытых столкновений с самими Дыбогривами.",al={"tauren quilboar war","bristleback conflict","quilboar lore","война тауренов и свинобразов","конфликт с дыбогривами","предания о свинобразах"}},{q="Какое задание предшествует «Боевым вепрям»?",a="Ему предшествует «Охота продолжается» — прежнее задание Грулла Соколиного Ветра, посвященное знакомству с охотничьими угодьями Плато Красного Облака.",al={"battleboars prerequisite","previous quest battleboars","hunt continues chain","предыдущее задание боевые вепри","охота продолжается","цепочка боевых вепрей"}}},fp="15,237,22.418.0,17.402.0,43.234.0,31.147.0,32.137.0,50.191.0,57.232.0,36.132.0"}
P.entries["quest:781"] = {n="Нападение на Лагерь Нараче",s="«Нападение на Лагерь Нараче» — важная находка в логове свинобразов в Ежевичной лощине. Карта с пятнами грязи показывает, что агрессивное племя Дыбогривов замышляет организованную осаду Лагеря Нараче. Передав эти планы вождю Соколиному Ветру, вы предупреждаете Лагерь Нараче вовремя, чтобы призвать помощь из Деревни Кровавого Копыта.",h="«Нападение на Лагерь Нараче» — важная находка в логове свинобразов в Ежевичной лощине.",kw={"attack plans","bloodhoof village","brambleblade ravine","bristleback","camp narache","chief hawkwind","dirt-stained map","quilboar","red cloud mesa","планы нападения","деревня кровавого копыта","ежевичная лощина","дыбогрив","лагерь нараче","вождь соколиный ветер","карта с пятнами грязи","свинобраз","плато красного облака"},ang={["faction:Horde"]="Сохранение позиций тауренов в Мулгоре обеспечивает Орде жизненно важный южный оплот в центральном Калимдоре.",["race:Tauren"]="Для юных тауренов-воинов, совершающих первые обряды на плато, перехват этой карты доказывает вашу верность племени и защищает ваших сородичей от внезапной резни."},sec={{t="Заговор в зарослях",b="Разведывая глубины пещер Ежевичной лощины, юные таурены-искатели приключений находят на каменном полу грубую карту с пятнами грязи. При внимательном осмотре на пергаменте обнаруживаются продуманные тактические отметки свинобразов Дыбогривов. Свинобразы не просто устраивают случайные стычки, а готовят полномасштабную длительную осаду Лагеря Нараче."},{t="Предупредить вождя",b="Доставив планы нападения в Лагерь Нараче, вы даете вождю Соколиному Ветру важнейшие сведения. Понимая, какая грозная опасность нависла над почти незащищенным лагерем и его юными посвящаемыми, Соколиный Ветер готовится послать весть в Деревню Кровавого Копыта за подкреплением. Перехваченная карта превращает возможную катастрофическую засаду в подготовленную оборону."}},faq={{q="Где найти планы нападения Дыбогривов?",a="Планы лежат на карте с пятнами грязи в пещере Ежевичной лощины, чуть выше по тропе справа от хижины вождя Острого Бивня.",al={"map location","where is dirt-stained map","find the plans","где карта","где карта с пятнами грязи","найти планы"}},{q="Кому передают планы нападения Дыбогривов?",a="Планы нужно доставить напрямую вождю Соколиному Ветру в центр Лагеря Нараче.",al={"who to turn in to","who gets the map","quest ender","кому сдавать задание","кто получает карту","завершение задания"}},{q="Почему свинобразы Дыбогривы нацелились на Лагерь Нараче?",a="Племя Дыбогривов стремится изгнать тауренов с Плато Красного Облака и вернуть охотничьи угодья и священные равнины Мулгора своему народу.",al={"why attack camp narache","quilboar motives mulgore","bristleback siege","зачем нападать на лагерь нараче","мотивы свинобразов мулгор","осада дыбогривов"}},{q="Как вождь Соколиный Ветер планирует противостоять осаде?",a="Благодаря раннему предупреждению от перехваченной карты вождь Соколиный Ветер намерен призвать собратьев из Деревни Кровавого Копыта, чтобы усилить плато и отразить нападение.",al={"hawkwind plan","reinforcements camp narache","план соколиного ветра","подкрепление лагеря нараче"}},{q="Нужно ли с кем-то говорить, прежде чем взять карту?",a="Нет. Задание начинается прямо с Карты с пятнами грязи, лежащей на полу пещеры в Ежевичной лощине, и после подбора карта превращается в планы сражения.",al={"quest starter","dirt stained map starter","how to start attack on camp narache","начало задания","карта с пятнами грязи начало","как начать нападение на лагерь нараче"}},{q="Что будет, если Лагерь Нараче падет?",a="Лагерь Нараче — главное убежище для молодых тауренов-воинов и обрядов посвящения; его потеря подорвет безопасность Плато Красного Облака и лишит Мулгор духовных тренировочных земель.",al={"stakes of camp narache","why defend narache","что на кону в лагере нараче","зачем защищать нараче"}}},fp="22,330,22.393.0,21.361.0,45.143.0,42.85.0,56.152.0,50.168.0,69.149.0,35.185.0"}
P.entries["quest:783"] = {n="Внутренняя угроза",s="Задание «Внутренняя угроза» знаменует начало службы для защитников, откликнувшихся на призыв Штормграда в Долине Североземья. Новобранцев направляют в Аббатство Североземья к маршалу Макбрайду, и они узнают, что войска королевства разбросаны по дальним землям, а местные гарнизоны не справляются с внутренними бедами без помощи гражданских.",h="Задание «Внутренняя угроза» знаменует начало службы для защитников, откликнувшихся на призыв Штормграда в...",kw={"a threat within","abbey","elwynn forest","marshal mcbride","northshire","recruitment","stormwind guard","volunteers","внутренняя угроза","аббатство","элвиннский лес","маршал макбрайд","североземье","набор","стража штормграда","добровольцы"},ang={["faction:Alliance"]="Задание подчеркивает напряжение, с которым сталкивается Великий Альянс: военные обязательства в дальних землях оставляют даже самые надежные коренные области уязвимыми перед внутренним развалом.",["race:Human"]="Поскольку Долина Североземья — стартовая долина для защитников-людей, отклик на призыв маршала Макбрайда становится вашей первой официальной клятвой защищать родину и Королевство Штормград."},sec={{t="Королевство на пределе сил",b="Долина Североземья когда-то была тихим уголком, посвященным молитве, земледелию и монашеским наукам. Сегодня это первая линия обороны от внутренних беспорядков в Элвиннском лесу. Регулярные войска Штормграда разосланы по дальним фронтам, и коренные земли столицы остались опасно малолюдными. Из-за нехватки солдат в этих краях Страже Штормграда приходится принимать любого добровольца, пришедшего к воротам аббатства."},{t="Призыв маршала",b="В Аббатстве Североземья маршал Макбрайд руководит обороной долины в условиях растущей напряженности в регионе. Пока иноземные опасности угрожают Альянсу издалека, разбойники, расплодившиеся вредители и подземные твари пользуются безвластием прямо у порога королевства. Откликнувшись на этот призыв, новобранцы сразу вступают в боевую службу: сначала очищают окрестности аббатства, а затем сталкиваются с более глубокой гнилью, пускающей корни по всему Элвиннскому лесу."}},faq={{q="В чем смысл этого задания?",a="Это вводный призыв для только что прибывших новобранцев в Долине Североземья. Вам предписано войти в Аббатство Североземья и доложить маршалу Макбрайду, чтобы присоединиться к местной обороне.",al={"threat within quest","what is this quest","northshire intro quest","внутренняя угроза задание","что это за задание","вводное задание североземья"}},{q="Кто такой маршал Макбрайд?",a="Маршал Макбрайд — старший офицер Стражи Штормграда, расквартированный в Аббатстве Североземья. Он руководит обороной долины, направляет новобранцев и раздает поручения, чтобы сдерживать угрозы в ближайшей округе.",al={"marshal mcbride","who is mcbride","abbey commander","маршал макбрайд","кто такой макбрайд","командир аббатства"}},{q="Почему Штормград набирает добровольцев вместо того, чтобы прислать регулярные войска?",a="Постоянные армии Штормграда отправлены за границу в дальние походы защищать интересы Альянса. Из-за такой нагрузки гарнизоны коренных земель критически малочисленны, и местным командирам приходится полагаться на недавно прибывших искателей приключений и добровольцев, чтобы защищать собственные дома.",al={"why volunteers","where are the guards","why is stormwind understaffed","почему добровольцы","где стража","почему в штормграде не хватает солдат"}},{q="Какие угрозы сейчас донимают Долину Североземья?",a="Долина сталкивается сразу с несколькими бедами: агрессивные кобольды заселили соседние шахты и холмы, больные или хищные вредители досаждают окрестным виноградникам, а организованные шайки разбойников и бандитов пользуются ослабленным местным гарнизоном.",al={"valley threats","what is attacking northshire","northshire problems","угрозы долины","кто нападает на североземье","проблемы североземья"}},{q="Куда ведет это задание дальше?",a="Доклад маршалу Макбрайду открывает несколько срочных поручений в Североземье: новобранцев отправляют уничтожать вторжения кобольдов на холмах, помогать местным фермерам и рабочим и выяснять, откуда взялось столько организованных бандитов.",al={"next quest","what comes after threat within","mcbride follow up","следующее задание","что после внутренней угрозы","продолжение макбрайда"}},{q="Почему Аббатство Североземья используется как военный командный пункт?",a="Хотя Аббатство Североземья — священное место учения и веры, его укрепленные каменные стены и расположение в центре делают его единственной подходящей базой в долине. Когда местная власть оказалась перегружена, Стража Штормграда разместила командование прямо в его залах.",al={"why military in abbey","northshire church military","holy abbey soldiers","почему военные в аббатстве","церковь североземья военные","солдаты в аббатстве"}}},fp="15,323,24.457.0,18.466.0,34.210.0,23.230.0,75.292.0,54.256.0,37.227.0,62.272.0"}
P.entries["quest:784"] = {n="Бей предателей!",s="«Бей предателей!» — военный удар Орды по приказу Га'Тока из Колючего Холма: нужно отбить Крепость Тирагард у человеческих захватчиков. Силы Кул Тираса под командованием лейтенанта Бенедикта вновь заняли твердыню, прямо нарушив хрупкий мир между Дуротаром и Терамором. Уничтожение гарнизона крайне важно для безопасности восточного побережья родины орков.",h="«Бей предателей!» — военный удар Орды по приказу Га'Тока из Колючего Холма: нужно отбить Крепость Тирагард у...",kw={"daelin proudmoore","durotar","gar'thok","kul tiras","lieutenant benedict","marines","razor hill","sailors","tiragarde keep","vanquish the betrayers","даэлин праудмур","дуротар","га'ток","кул тирас","лейтенант бенедикт","морпехи","колючий холм","моряки","крепость тирагард","бей предателей"},ang={["faction:Horde"]="Захват Крепости Тирагард силами Кул Тираса — продолжающийся акт войны прямо на пороге Дуротара. Уничтожение отряда Бенедикта показывает, что Орда способна защитить свой новый дом от чужеземных флотов.",["race:Orc"]="Орки чтут перемирие, заключенное с Джайной на Горе Хиджал, но Кул Тирас пробуждает горькие воспоминания о Второй войне. Отразить морпехов Бенедикта — вопрос выживания и гордости предков.",["race:Troll"]="Крепость Тирагард находится неприятно близко к поселению Черного Копья — Деревне Сен'джин. Расправа с этими враждебными моряками напрямую защищает уязвимый новый дом троллей."},sec={{t="Разрушенное перемирие",b="Когда Тралл привел Орду через Великое море в Калимдор, он заключил непрочный союз с леди Джайной Праудмур, чтобы победить Пылающий Легион на Горе Хиджал. Этот мир был нарушен, когда отец Джайны, с которым она была в разладе, верховный адмирал Даэлин Праудмур, прибыл с мощным флотом Кул Тираса. Виня всех орков в зверствах Старой Орды, адмирал вторгся в Дуротар и захватил опорные пункты на побережье, включая Крепость Тирагард. Хотя Даэлин в итоге был убит в Тераморе, остатки его флота отказываются чтить любые договоры и отступиться от своей ненависти."},{t="Возрождение Бенедикта",b="После гибели Верховного адмирала Крепость Тирагард ненадолго пала, но резервы Кул Тираса под командованием лейтенанта Бенедикта с тех пор вновь отбили твердыню. Из этого укрепленного оплота между Колючим Холмом и Деревней Сен'джин моряки и морпехи донимают путников и угрожают восточным морским подступам. Га'Ток видит в их укрепившейся позиции непосредственную опасность для безопасности Дуротара и призывает воинов Орды ударить прямо по штабу Бенедикта."}},faq={{q="Почему люди из Кул Тираса нападают на Дуротар?",a="Это остатки экспедиционного флота под командованием верховного адмирала Даэлина Праудмура. Адмирал не желал мирного сосуществования людей и орков и стремился полностью истребить Дуротар. Даже после его смерти его приверженцы продолжают занимать прибрежные редуты вроде Крепости Тирагард, бросая вызов Орде.",al={"why are humans in durotar","kul tiras attacking","tiragarde keep humans lore","почему люди в дуротаре","кул тирас нападает","люди крепость тирагард"}},{q="Кто такой лейтенант Бенедикт?",a="Лейтенант Бенедикт — командир резервов Кул Тираса, которые сейчас удерживают Крепость Тирагард. После поражения верховного адмирала Праудмура Бенедикт собрал уцелевших морпехов и моряков, чтобы отбить прибрежное укрепление и вести постоянные операции против орков.",al={"who is benedict","lieutenant benedict lore","leader tiragarde keep","кто такой бенедикт","лейтенант бенедикт","командир крепости тирагард"}},{q="Поддерживает ли Джайна Праудмур этих людей?",a="Нет. Джайна заключила с вождем Траллом договор о взаимном выживании и открыто выступила против агрессивного похода отца ради сохранения мира. Войска, удерживающие Крепость Тирагард, — отколовшиеся остатки Кул Тираса, отвергающие дипломатию Терамора и считающие перемирие Джайны изменой.",al={"does jaina support them","theramore kul tiras alliance","jaina proudmoore tiragarde","поддерживает ли джайна","терамор кул тирас союз","джайна праудмур тирагард"}},{q="Почему их называют «предателями»?",a="Га'Ток считает их предателями, потому что их вторжение прямо нарушило дипломатическое согласие между Траллом и Джайной Праудмур, достигнутое для победы над Архимондом в Третьей войне. Их постоянное военное присутствие на суверенной земле Орды нарушает послевоенные границы, установленные в Калимдоре.",al={"why betrayers","who betrayed who","betrayers meaning","почему предатели","кто кого предал","значение предателей"}},{q="Где находится Крепость Тирагард?",a="Крепость Тирагард расположена на восточном побережье Дуротара, к югу от Колючего Холма и чуть северо-восточнее Деревни Сен'джин. Ее высокие каменные стены возвышаются над прибрежными водами, давая захватчикам стратегическую базу рядом с поселениями Орды.",al={"tiragarde keep location","where is tiragarde keep","where to find benedict","где крепость тирагард","расположение крепости тирагард","где найти бенедикта"}}},fp="22,366,17.559.0,21.469.0,43.323.0,27.292.0,43.277.0,32.304.0,32.240.0"}
P.entries["quest:786"] = {n="Предотвращение агрессии племени Колкар",s="«Предотвращение агрессии племени Колкар» — важное оборонительное задание Орды, которое дает разведчик Лар Ночной Клык близ Деревни Сен'джин. Игроки должны проникнуть в Утес Колкара и уничтожить три комплекта согласованных планов вторжения, пока племя кентавров не нанесло удар по молодым поселениям Дуротара.",h="«Предотвращение агрессии племени Колкар» — важное оборонительное задание Орды, которое дает разведчик Лар...",kw={"durotar","kolkar","kolkar crag","lar prowltusk","orgrimmar","sen'jin village","thwarting kolkar aggression","valley of trials","дуротар","колкар","утес колкара","лар ночной клык","оргриммар","деревня сен'джин","предотвращение агрессии племени колкар","долина испытаний"},ang={["faction:Horde"]="Остановив наступление Колкара, молодая Орда избегает изнурительной территориальной войны на несколько фронтов прямо на пороге своего нового дома.",["race:Orc"]="В Долине Испытаний юные орки проходят обряды взросления, поэтому агрессия кентавров там — оскорбление самих основ воинской культуры орков.",["race:Troll"]="Уже потеряв свой древний островной дом, тролли Черного Копья не могут допустить, чтобы Деревню Сен'джин захлестнули грабители-кентавры."},sec={{t="Надвигающееся вторжение",b="Разведывая запад Дуротара, тролль-следопыт Лар Ночной Клык под покровом ночи проник в Утес Колкара. Увиденное встревожило его: кентавры Колкара не просто устраивали разрозненные набеги на побережье, а готовили масштабное вторжение по трем направлениям, нацеленное прямо на земли орков и Черного Копья. Военачальники кентавров разделили боевые планы между тремя предводителями, намереваясь ударить по Долине Испытаний, Деревне Сен'джин и самим вратам Оргриммара."},{t="Удар по каньонам",b="Чтобы предотвратить катастрофические бои в сухих красных каньонах Дуротара, новобранцев посылают в глубь Утеса Колкара, чтобы отсечь змее голову. Проникновение в пыльный лагерь и сожжение трех свитков с планами нападения нарушает цепь командования кентавров. Хотя Лар Ночной Клык уверен, что Орда неизбежно сокрушит любое полномасштабное вторжение, уничтожение этих документов избавит защитников Дуротара от дорогостоящего кровопролития, пока молодое государство еще только встает на ноги."}},faq={{q="Кто дает задание «Предотвращение агрессии племени Колкар»?",a="Задание дает Лар Ночной Клык, разведчик-тролль из племени Черного Копья, находящийся недалеко от Деревни Сен'джин на южных обрывах Дуротара.",al={"quest giver","who gives quest","lar prowltusk location","персонаж, выдающий задание","кто дает задание","где лар ночной клык"}},{q="Какие цели планируют атаковать кентавры Колкара?",a="Боевые планы Колкара описывают согласованное наступление в три удара по Долине Испытаний, Деревне Сен'джин и столице Орды — Оргриммару.",al={"centaur targets","what are attack plans","three targets","цели кентавров","какие планы нападения","три цели"}},{q="Где находится Утес Колкара?",a="Утес Колкара — выжженный солнцем комплекс каньонов, спрятанный к западу за скалистыми хребтами от Деревни Сен'джин на юге Дуротара.",al={"kolkar crag location","where is the crag","centaur village durotar","где утес колкара","расположение утеса колкара","деревня кентавров дуротар"}},{q="Где в утесе найти планы нападения?",a="Три свитка с чертежами вторжения хранятся у трех разных предводителей Колкара, охраняющих разные лагеря по всему утесу.",al={"attack plan locations","where are scrolls","centaur leaders","где планы нападения","где свитки","предводители кентавров"}},{q="Почему Колкар хотят вторгнуться в Дуротар?",a="Колкар — агрессивное, экспансионистское племя кентавров, коренных жителей засушливых земель Калимдора. Они считают прибывших орков и троллей Черного Копья чужаками, посягающими на их территорию и охотничьи угодья.",al={"why are centaur attacking","centaur motive","kolkar lore","почему нападают кентавры","мотив кентавров","колкар предания"}},{q="Что происходит после уничтожения планов?",a="Уничтожение документов предотвращает согласованную осаду, расстраивает тактическое наступление Колкара и защищает хрупкие поселения Дуротара от внезапного разорения.",al={"quest aftermath","does centaur attack stop","последствия задания","прекратится ли нападение кентавров"}}},fp="27,294,18.498.0,20.475.0,49.137.0,55.154.0,29.121.0,49.157.0,41.207.0,43.179.0"}
P.entries["quest:787"] = {n="Новая Орда",s="«Новая Орда» — вводное задание в Долине Испытаний, которое выдает ветеран-воин Эйтригг. Он велит новобранцам явиться к Горнеку в Логово, чтобы начать обучение. В этом кратком поручении Эйтригг рассказывает о своем пути и о замысле Тралла — возрожденной Орде.",h="«Новая Орда» — вводное задание в Долине Испытаний, которое выдает ветеран-воин Эйтригг.",kw={"burning legion","durotar","eitrigg","gornek","new horde","the den","thrall","valley of trials","пылающий легион","дуротар","эйтригг","горнек","новая орда","логово","тралл","долина испытаний"},ang={["faction:Horde"]="Это задание воплощает основополагающий дух правления Тралла: полный разрыв с демоническим рабством во имя чести, выживания и наследия предков.",["race:Orc"]="Для молодых орков, вступающих в Долину Испытаний, Эйтригг — живая память о трагическом прошлом их народа и об искуплении под началом Тралла.",["race:Troll"]="Тролли Черного Копья проходят обучение вместе с орками в Долине Испытаний: они приняли замысел Тралла о совместном выживании и чести."},sec={{t="Возвращение ветерана",b="Эйтригг находится в Долине Испытаний по приказу вождя Тралла: он должен оценивать и наставлять новейших кандидатов в Орду. Он покинул Старую Орду после Второй войны, разочаровавшись из-за ее порабощения Пылающим Легионом, и жил в тихом изгнании, пока его не захватили люди. Спасенный Траллом, он решил вернуться, узнав о мечте молодого Вождя: честной Орде, основанной на шаманизме предков и полностью свободной от демонических владык."},{t="Явиться в Логово",b="Прежде чем новобранец сможет покинуть суровые каньоны Долины Испытаний, он должен доказать свою доблесть. Эйтригг отправляет новичков в затененную пещеру, известную как Логово, к Горнеку. Хотя Горнек редко выбирает слова, говоря о неприглядном состоянии новых кандидатов, его надзор гарантирует, что в дальние земли Дуротара попадут лишь те, кто овладел дисциплиной и умением выживать."}},faq={{q="Кто такой Эйтригг?",a="Эйтригг — немолодой орк-ветеран, на собственном опыте видевший, как Пылающий Легион развратил Старую Орду. Разочаровавшись, он удалился в добровольное изгнание в Лордерон. После того как его захватили люди, а затем освободил Тралл, он присягнул на верность вновь созданной Орде Тралла и теперь помогает руководить обучением новобранцев в Долине Испытаний.",al={"who is eitrigg","eitrigg backstory","eitrigg lore","кто такой эйтригг","эйтригг история","эйтригг предыстория"}},{q="Почему Эйтригг говорит о «Новой Орде»?",a="Первоначальная Орда была обманута и порабощена демонической жаждой крови под властью Пылающего Легиона. Новая Орда Тралла была создана, чтобы отбросить демонический контроль, возродить традиционный шаманизм и построить честное, независимое будущее для орков и их союзников в Калимдоре.",al={"what is the new horde","difference between old and new horde","new horde meaning","что такое новая орда","разница между старой и новой ордой","новая орда значение"}},{q="Где находится Горнек?",a="Горнек стоит сразу у входа в Логово — приметную пещеру в северной скальной стене Долины Испытаний.",al={"where is gornek","find gornek","gornek location","где горнек","найти горнека","горнек местонахождение"}},{q="Что происходит после доклада Горнеку?",a="Горнек принимает вас в число учеников Эйтригга и дает первые полевые поручения: вы защищаете долину, а он проверяет, готовы ли вы служить Орде.",al={"next quest after the new horde","what does gornek do","gornek quest","следующее задание после новой орды","что делает горнек","задание горнека"}},{q="Почему Эйтригг был изгнан?",a="Эйтригг покинул Орду, потому что ему были отвратительны демоническая порча и бессмысленная резня, устроенные чернокнижниками на службе Пылающего Легиона во время прежних войн.",al={"why did eitrigg leave","eitrigg exile reason","eitrigg demon corruption","почему эйтригг ушел","причина изгнания эйтригга","эйтригг демоны"}},{q="Почему новобранцев обучают в Долине Испытаний?",a="Долина Испытаний — уединенное суровое место в Дуротаре, где молодые орки и союзные новички могут сразиться с опасными зверями и скорпидами под присмотром опытных наставников, прежде чем отправиться в большой мир.",al={"why valley of trials","purpose of the valley of trials","valley of trials training","почему долина испытаний","назначение долины испытаний","обучение в долине испытаний"}}},fp="13,299,18.465.0,20.397.0,15.378.0,44.288.0,24.139.0,39.181.0,23.179.0,49.232.0"}
P.entries["quest:79"] = {n="Легенда о Сталване",s="Это задание — момент, когда разрозненные слухи о Сталване Мистмантле превращаются в неоспоримое доказательство жестокого преступления. Хозяин таверны Смиттс передает давно скрытые грязные страницы дневника и направляет следователя прямо к командиру Ночного Дозора Алтее Чернодрев.",h="Это задание — момент, когда разрозненные слухи о Сталване Мистмантле превращаются в неоспоримое...",kw={"darkshire","duskwood","ebonlocke","investigation","mistmantle","muddy journal","night watch","smitts","stalvan","темнолесье","сумеречный лес","чернодрев","расследование","мистмантл","грязный дневник","ночной дозор","смиттс","сталван"},ang={["class:Paladin"]="Раскрытие давно похороненных убийств отвечает призванию паладина: он требует ответа за невинные жизни, насильно отнятые во мраке Сумеречного леса.",["class:Rogue"]="Сопоставление образцов почерка в тавернах и пыльных сундуках отражает терпеливую работу сыщика, нередко нужную, чтобы выследить неуловимую добычу.",["faction:Alliance"]="Расследование показывает, что южным землям приходится полагаться на странствующих героев Альянса, чтобы вершить правосудие, когда официальной поддержки Штормграда нет совсем."},sec={{t="Прорыв в Темнолесье",b="Годами мрачная судьба знатной семьи, приезжавшей в Сумеречный лес, оставалась нераскрытой трагедией. Хозяин таверны Смиттс и маршал Хаггард, тогда один из командиров Стражи Штормграда, осмотрели место убийства и нашли несколько рваных грязных страниц дневника. Без образцов почерка и подтверждающих бумаг записи лежали без движения и не могли официально уличить затворника, который, по слухам, жил в глуши. Улики, собранные в Элвиннском лесу, Западном Крае и Сумеречном лесу, наконец связывают почерк со Сталваном Мистмантлом и превращают городские сплетни в бесспорное дело об убийстве."},{t="Передать дело Дозору",b="Темнолесье живет в постоянной осаде нежити, диких зверей и еще худших ужасов, бродящих во мраке леса. У командира Алтеи Чернодрев мало терпения для небылиц и необоснованных подозрений, когда выживание города висит на волоске. Доставка этих грязных страниц соединяет давнюю историю с немедленным военным правосудием. Получив веское доказательство резни на земле Сумеречного леса, Ночной Дозор наконец вынужден признать Сталвана Мистмантла не просто чудаковатым отшельником или героем страшных историй, а опасным беглецом, которого необходимо покарать."}},faq={{q="Какие улики все это время были у хозяина таверны Смиттса?",a="Много лет назад Смиттс вместе с Хаггардом расследовал убийство приезжих дворян. На месте они нашли рваные грязные страницы дневника, но у них не было образцов почерка, чтобы доказать, что их автор — Сталван Мистмантл. До сих пор.",al={"smitts journal pages","muddy journal pages","what did smitts find","страницы дневника смиттса","грязные страницы дневника","что нашел смиттс"}},{q="Почему Смиттс не сообщил об этом командиру Чернодрев раньше?",a="Без доказательств, связывающих почерк на грязных страницах с отшельником-учителем, у Смиттса и Хаггарда были лишь косвенные обрывки. Если бы они принесли командиру Чернодрев непроверенные слухи, их сочли бы бесполезной тратой и без того ограниченного времени Ночного Дозора.",al={"why wait so long","why keep the pages secret","why didn't smitts tell the guard","почему так долго ждали","почему скрывали страницы","почему смиттс не сказал страже"}},{q="Кто такая командир Алтея Чернодрев?",a="Командир Алтея Чернодрев — глава Ночного Дозора, измученного городского ополчения, которое охраняет Темнолесье и патрулирует дороги Сумеречного леса, защищая их от Плети и лесных хищников.",al={"who is ebonlocke","althea ebonlocke role","commander of darkshire","кто такая чернодрев","алтея чернодрев должность","командир темнолесья"}},{q="Какая резня произошла в Сумеречном лесу?",a="Несколько лет назад в Сумеречном лесу была убита приезжая знатная семья. Слухи указывали на их бывшего учителя, Сталвана Мистмантла, но у местных следователей сначала не было неопровержимых улик для обвинения.",al={"what massacre","slaughter of nobles","who was murdered","какая резня","убийство дворян","кого убили"}},{q="Какое место этот этап занимает во всем расследовании?",a="Этот этап — переход от частного расследования к официальному правосудию. Изучив реестры, школьные записи и семейные сундуки в трех землях, вы передаете собранные улики местным властям, чтобы они приняли меры против Сталвана.",al={"stalvan quest chain step","how far in is this","is this the end of the quest","этап цепочки сталвана","как далеко это","это конец задания"}},{q="Почему Ночной Дозор так неохотно расследует старые преступления?",a="Темнолесью ежедневно грозит немедленное уничтожение от бродячих чудовищ, стай воргенов и пауков. Командир Чернодрев должна направить всех стражников на выживание, поэтому для старых дел нужны неопровержимые доказательства, прежде чем она выделит людей.",al={"why is ebonlocke busy","darkshire defense priority","night watch priorities","почему чернодрев занята","оборона темнолесья","приоритеты ночного дозора"}}},fp="21,266,27.595.0,22.573.1,51.232.0,61.273.0,34.200.0,37.217.0,56.266.0,62.245.0"}
P.entries["quest:79008"] = {n="... и записка, которую ты нашел",s="Эта обожженная записка, найденная среди углей догорающего костра в Западном Крае, оставляет загадочную единственную подсказку. Ее опаленное послание намекает на место где-то в мире и призывает нашедшего отыскать «землю-близнеца».",h="Эта обожженная записка, найденная среди углей догорающего костра в Западном Крае, оставляет загадочную...",kw={"blistered note","campfire","charred note","embers","note","twin land","westfall","обожженная записка","костер","обугленная записка","угли","записка","земля-близнец","западный край"},ang={["class:Rogue"]="Расшифровывать загадочные подсказки в потайных лагерях — вторая натура для тех, кто живет шепотом, тайнами и скрытыми посланиями.",["faction:Alliance"]="Для искателей приключений, пытающихся навести порядок в Западном Крае, неопознанный лагерь и загадочный шифр — еще одна тайна на границе королевства."},sec={{t="Догорающий костер",b="Среди заброшенных полей, разграбленных ферм и продуваемых ветрами равнин Западного Края путники часто натыкаются на лагеря бродяг, разбойников и отчаявшихся скитальцев. Но этот небольшой лагерь покинули в спешке или тайком: припасы брошены, а угли еще слабо тлеют. Среди разбросанного мусора лежит опаленный клочок пергамента, переживший огонь."},{t="Загадочное послание",b="На обожженной записке всего два коротких предложения: «Не все, что горит, потеряно. Найди землю-близнеца, найди место». Окутанные тайной слова служат и загадкой, и приглашением, указывая прочь от пустынных полей Западного Края к другой земле, связанной именем, географией или судьбой."}},faq={{q="Что говорится в записке?",a="В обожженной записке сказано: «Не все, что горит, потеряно. Найди землю-близнеца, найди место». Это единственная подсказка, оставленная на заброшенной стоянке.",al={"note text","what is written on the note","blistered note words","текст записки","что написано в записке","слова обожженной записки"}},{q="Где найдена эта записка?",a="Записку находят среди остатков недавнего костра и разбросанных припасов в глуши Западного Края.",al={"note location","where is the note","campfire location","место записки","где записка","где костер"}},{q="Кто оставил костер?",a="Автор неизвестен. Тот, кто разжег костер, ушел недавно, оставив разбросанные припасы и опаленное послание в углях.",al={"who left the note","campfire owner","note author","кто оставил записку","хозяин костра","автор записки"}},{q="Что означает «земля-близнец»?",a="Эта фраза — загадка, указывающая на другой край мира, который отражает землю, где найдена записка, или связан с ней, хотя обугленная записка ничего больше не поясняет.",al={"twin land meaning","what is twin land","where is twin land","значение земли-близнеца","что такое земля-близнец","где земля-близнец"}},{q="Почему записка обгорела?",a="Записка обгорела и обуглилась в углях костра, что говорит о том, что кто-то либо пытался уничтожить ее в спешке, либо небрежно бросил, когда пламя угасало.",al={"why was it burned","did someone try to burn the note","charred note","почему сожжена","пытались ли сжечь записку","обугленная записка"}},{q="Связано ли это с Братством Справедливости?",a="Хотя Западный Край заполонили Братство Справедливости и нищие бродяги, загадочный характер послания говорит о чем-то более темном, чем обычная переписка разбойников.",al={"defias note","is it defias","brotherhood campfire","записка братства справедливости","это справедливость","костер братства"}}},fp="27,250,12.383.0,19.311.0,23.150.0,25.118.0,22.142.0,35.187.0,24.172.0,44.179.0"}
P.entries["quest:791"] = {n="Больше сумок – больше добычи!",s="«Больше сумок – больше добычи!» — вводное задание, которое дает Фурл Хмурый Лоб на сторожевой башне над Колючим Холмом. Старый шрамированный ветеран больше не может сражаться на передовой и просит молодых авантюристов Орды добыть парусину у местных враждебных людей и кентавров, чтобы сшить припасы для их путешествия.",h="«Больше сумок – больше добычи!» — вводное задание, которое дает Фурл Хмурый Лоб на сторожевой башне над...",kw={"canvas scraps","carry your weight","durotar","furl scornbrow","kolkar","razor hill","razor hill watchtower","tiragarde","обрывки парусины","больше сумок – больше добычи","дуротар","фурл хмурый лоб","колкар","колючий холм","сторожевая башня колючего холма","тирагард"},ang={["faction:Horde"]="Каждый молодой солдат в Дуротаре полагается на закаленных ветеранов вроде Фурла Хмурого Лба, которые напоминают новичкам: служить Орде — значит исполнять любой долг, которого требует родина, будь то охрана заставы или шитье из парусины.",["profession:Tailoring"]="Фурл показывает практичное, грубое портняжное дело пограничья: он превращает брошенную плотную парусину людей-захватчиков и кентавров-налетчиков в прочное снаряжение для выживания в глуши.",["race:Orc"]="Фурл воплощает старшее поколение орков, освободившихся от демонической порчи, пересекших море с Траллом и теперь посвящающих последние годы заботе о будущем своей молодой нации."},sec={{t="Призвание ветерана",b="Фурл Хмурый Лоб — ветеран Третьей войны, шедший рядом с вождем Траллом при освоении Дуротара и в отчаянной обороне на горе Хиджал. Теперь годы и старые раны замедлили его, и он больше не берется за топор в бою. Вместо этого он несет бессменную стражу на сторожевой башне Колючего Холма, подает сигнал тревоги при набегах и поддерживает следующее поколение защитников."},{t="Добытая парусина",b="Сигналы рога звучат все реже, по мере того как Орда укрепляет власть в регионе, и Фурл проводит часы за изготовлением полезного снаряжения. Прочную парусину трудно найти в засушливых каньонах Дуротара, но ее в изобилии носят и култирасцы-захватчики на восточном берегу, и кочевые кентавры Колкар, бродящие по равнинам. Обрывки, добытые у этих врагов, дают Фурлу ткань, нужную, чтобы сшить походные сумки для разведчиков."}},faq={{q="Кто такой Фурл Хмурый Лоб?",a="Фурл Хмурый Лоб — стареющий орк-ветеран, несущий службу на сторожевой башне над Колючим Холмом. Он сражался рядом с Траллом при основании Дуротара и стоял в объединенных рядах, победивших Архимонда на горе Хиджал. Не имея возможности биться на передовой, он служит наблюдателем, а в свободное время мастерит походное снаряжение для молодых воинов Орды.",al={"who is furl","furl scornbrow lore","who gives carry your weight","кто такой фурл","фурл хмурый лоб предания","кто дает задание больше сумок – больше добычи"}},{q="Где в Дуротаре найти обрывки парусины?",a="Обрывки парусины можно собрать у култирасцев, занимающих Крепость Тирагард на побережье Дуротара, и у кентавров Колкар, разбивших лагеря на равнинах. И те, и другие носят плотные тканые материалы, которые можно забрать из их лагерей и вещей.",al={"where to get canvas scraps","who drops canvas scraps","canvas scrap locations","где взять обрывки парусины","с кого падают обрывки парусины","места обрывков парусины"}},{q="Где находится сторожевая башня, на которой стоит Фурл?",a="Башня Фурла стоит на высоких скалистых утесах прямо к северо-западу от Колючего Холма. Извилистая тропа за поселением ведет на вершину, где возвышается деревянная смотровая постройка.",al={"where is furl scornbrow","razor hill watchtower location","find razor hill watchtower","где фурл хмурый лоб","сторожевая башня колючего холма","найти башню колючего холма"}},{q="Что Фурл мастерит из обрывков парусины?",a="Фурл сшивает собранные обрывки парусины в прочную походную сумку. Молодым авантюристам, странствующим по Дуротару, дополнительная вместимость для провизии, пайков и трофейного оружия необходима, чтобы выжить в суровой глуши.",al={"what does furl make","what is the canvas used for","canvas scraps reward","что делает фурл","для чего нужна парусина","награда за обрывки парусины"}},{q="Почему старый воин шьет сумки, а не сражается?",a="Десятилетия непрерывных боев сказались на теле Фурла, и он не может соответствовать скорости и силе, которых требует поле боя. Вместо того чтобы сетовать на отставку, он находит честь в охране Колючего Холма и изготовлении снаряжения, которое помогает молодым бойцам защищать родину.",al={"why is furl crafting","why does furl stay in the tower","why isn't furl fighting","почему фурл шьет","почему фурл остается в башне","почему фурл не сражается"}},{q="В какой войне сражался Фурл?",a="Фурл сражался под началом вождя Тралла в Третьей войне, участвовал в заселении Дуротара и в решающей битве на горе Хиджал против Пылающего Легиона. Он с гордостью вспоминает, как откликнулся на боевой клич во время вынужденного временного перемирия между Ордой, ночными эльфами и Альянсом ради победы над Архимондом.",al={"furl battle history","what did furl do before","archimonde furl","боевой путь фурла","что фурл делал раньше","архимонд фурл"}}},fp="17,302,19.390.0,16.458.0,22.359.0,44.251.0,46.190.0,44.239.0,56.310.0,27.327.0"}
P.entries["quest:79192"] = {n="Ступени",s="«Ступени» — расследование, начинающееся с потрепанной записки, оставленной в суровых глубинах Степей. В небрежно исписанном пергаменте сказано, что двое курьеров доставляли грузы для Новой чумы, а то, что с ними случилось, названо простыми несчастными случаями аптекарей. Таинственный автор призывает нашедшего отыскать укромное горное убежище на границе Пустошей.",h="«Ступени» — расследование, начинающееся с потрепанной записки, оставленной в суровых глубинах Степей.",kw={"desolace","mercenaries","mountains","new plague","note","royal apothecary society","stepping stones","the barrens","пустоши","наемники","горы","новая чума","записка","королевское фармацевтическое общество","ступени","степи"},ang={["class:Rogue"]="Выслеживать анонимных осведомителей и проверять тайные тайники в глубинке между Пустошами и Степями — вторая натура для тех, кто имеет дело с кинжалами и разведкой.",["faction:Horde"]="Странникам Орды в Степях предстоит решить, угрожают ли их землям и союзам слухи о доставках смертоносной чумы на землю Калимдора.",["race:Undead"]="Для путешествующих Отрекшихся любое упоминание Королевского фармацевтического общества и его исследований заразы — срочный вопрос безопасности или опасный заговор изнутри."},sec={{t="Записка в глуши",b="Сообщение кое-как прикреплено к деревянной доске в лагере в глубинке и выделяется на фоне суровой природы Степей. В таких лагерях часто тихо сменяются наемники, головорезы и бродяги, ищущие временный приют вдали от чужих глаз Перекрестка или Кабестана. Рваная записка сразу выделяется среди обыденных разговоров в глуши и приглашает к встрече, полной интриги и мрачных намеков."},{t="Шепотки о Новой чуме",b="Автор записки сообщает, что двое агентов доставляли грузы для Новой чумы, а то, что с ними случилось, называет простыми несчастными случаями аптекарей. Курьеры, перевозящие по Калимдору нестабильную заразу, сильно рискуют, и автор предлагает уютное местечко в горах между Степями и Пустошами как безопасное место для разговора."}},faq={{q="О чем говорится в записке, найденной у «Ступеней»?",a="Записка раскрывает, что курьеры, перевозившие материалы для Новой чумы Отрекшихся, внезапно погибли. Автор называет это простыми несчастными случаями аптекарей, но предлагает место встречи в горах, чтобы спокойно обсудить дело.",al={"stepping stones note","what is the note about","stepping stones quest text","записка ступени","о чем записка","текст задания ступени"}},{q="Куда велит идти записка?",a="Автор приглашает читателя в тайный лагерь высоко в горах, разделяющих Степи и Пустоши, вдали от обычных патрульных маршрутов и торговых путей.",al={"where to go stepping stones","cozy spot mountains","stepping stones location","куда идти ступени","уютное местечко в горах","ступени местоположение"}},{q="Что такое Новая чума, упомянутая в письме?",a="Новая чума — смертоносное варево, которое разрабатывает в Подгороде Королевское фармацевтическое общество Отрекшихся. Она предназначена для уничтожения и Плети, и живых врагов, а ее испытания и доставки курьерами по континентам окружены тайной и смертельной опасностью.",al={"what is new plague","royal apothecary plague","apothecary deliveries","что такое новая чума","чума фармацевтического общества","поставки аптекарей"}},{q="Кто написал записку, прикрепленную к доске?",a="Сообщение оставлено анонимно на грубой деревянной доске в лагере в глубинке. Автор не назван и лишь предлагает уютное местечко в горах между Степями и Пустошами как безопасное место для разговора.",al={"who wrote the note","stepping stones author","who is waiting in the mountains","кто написал записку","автор ступеней","кто ждет в горах"}},{q="Почему курьеры Отрекшихся оказались в Калимдоре?",a="Аптекари Отрекшихся часто собирают экзотические яды, споры и реагенты из суровой флоры и фауны Калимдора, организуя поставки через аванпосты Орды и маршруты в глуши.",al={"forsaken in barrens","why new plague in kalimdor","apothecaries in the barrens","отрекшиеся в степях","почему новая чума в калимдоре","аптекари в степях"}},{q="Почему для таких записок используют лагеря в глубинке?",a="Степи обширны и слабо управляются за пределами крупных поселений. Нейтральные станции, места отдыха наемников и лагеря изгоев позволяют путникам, контрабандистам и осведомителям незаметно оставлять вести, не привлекая внимания Орды или местных застав.",al={"backcountry camp lore","mercenary camps barrens","лагерь в глубинке","лагеря наемников степи"}}},fp="15,374,19.427.0,26.331.1,56.229.0,35.175.0,47.261.0,39.206.0,51.192.0,51.273.0"}
P.entries["quest:792"] = {n="Злобные фамильяры",s="«Злобные фамильяры» — раннее задание, которое Зурита Востроглазая дает новоприбывшим бойцам в Долине Испытаний. Наблюдая за испытаниями в долине, Зурита обнаружила коварный грот Пылающего Клинка в соседней пещере. Чтобы сдержать его стремительное распространение, новобранцев отправляют охотиться на демонических фамильяров, выбирающихся на красную землю Дуротара.",h="«Злобные фамильяры» — раннее задание, которое Зурита Востроглазая дает новоприбывшим бойцам в Долине...",kw={"burning blade","burning blade coven","durotar","imps","the den","valley of trials","vile familiars","zureetha fargaze","пылающий клинок","грот пылающего клинка","дуротар","бесы","логово","долина испытаний","злобные фамильяры","зурита востроглазая"},ang={["class:Warlock"]="Орки и тролли-чернокнижники должны считаться с реальностью отступников-заклинателей тьмы, которые используют демонические договоры для разрушения, а не направляют энергию Скверны на выживание Орды.",["faction:Horde"]="Пылающий Клинок — одна из самых непосредственных внутренних угроз Дуротару: он стремится изгнить молодую Орду изнутри, пока она не утвердила свою власть.",["race:Orc"]="Для орков, стремящихся чтить отказ Тралла от демонического рабства, встреча со скверной Пылающего Легиона на священных тренировочных землях — горькое напоминание о том, что наследие Совета Теней все еще гноится."},sec={{t="Тень в долине",b="Долина Испытаний должна быть местом, где молодые орки и тролли Черного Копья доказывают силу, дисциплину и преданность Орде Тралла. Она предназначена для проверки новобранцев на местных хищниках вроде скорпидов и кабанов, а не на демонической порче. Однако в пещере на северо-востоке агенты, называющие себя Пылающим Клинком, устроили тайный грот прямо под бдительным взором надзирателей долины."},{t="Истребление бесов",b="Зурита Востроглазая, инструктор, направленный наставлять новичков возле Логова, заметила тонкую скверну прежде, чем она захлестнула каньон. Мелкие демонические существа, известные как злобные фамильяры, начали выползать из устья пещеры, метая огонь и угрожая любому, кто подойдет слишком близко. Пока Орда не вырвала с корнем хозяев, скрывающихся во тьме, молодым новобранцам поручено истреблять этих младших слуг, чтобы сохранить безопасность долины."}},faq={{q="Кто дает задание «Злобные фамильяры»?",a="Задание дает Зурита Востроглазая. Она стоит у входа в Логово в центре Долины Испытаний.",al={"vile familiars quest giver","who gives vile familiars","where to pick up vile familiars","злобные фамильяры кто дает задание","кто дает злобных фамильяров","где взять злобных фамильяров"}},{q="Кто такие злобные фамильяры?",a="Злобные фамильяры — небольшие демонические существа, похожие на бесов, которых призывают и подчиняют культисты Пылающего Клинка. Они служат мелкими приспешниками и питомцами и жгут нарушителей огнем.",al={"what are vile familiars","vile familiar lore","vile familiars mob type","кто такие злобные фамильяры","предания злобные фамильяры","тип существ злобные фамильяры"}},{q="Где находится Грот Пылающего Клинка?",a="Грот скрыт в пещере на северо-востоке Долины Испытаний, за бродящими пестрыми кабанами и скорпидами-рабочими.",al={"burning blade coven location","where is burning blade coven","cave in valley of trials","грот пылающего клинка местоположение","где грот пылающего клинка","пещера в долине испытаний"}},{q="Почему Пылающий Клинок оказался в Долине Испытаний?",a="Пылающий Клинок — тайный культ, стремящийся подорвать новую Орду Тралла и распространить демоническую порчу. Проникнув в Долину Испытаний, культисты могут скрытно затаиться и угрожать новейшему поколению бойцов Орды.",al={"why is burning blade here","burning blade motives","what does burning blade want","почему здесь пылающий клинок","цели пылающего клинка","чего хочет пылающий клинок"}},{q="Что происходит после выполнения задания «Злобные фамильяры»?",a="Когда фамильяров у пещеры станет меньше, Зурита Востроглазая велит вам спуститься в пещеру, сразиться с предводителем культистов и забрать Медальон Пылающего Клинка.",al={"vile familiars follow up","what comes after vile familiars","burning blade medallion quest","злобные фамильяры продолжение","что после злобных фамильяров","задание медальон пылающего клинка"}},{q="Нужно ли идти вглубь пещеры, чтобы найти фамильяров?",a="Нет. Хотя они обитают в пещере, множество злобных фамильяров кружит у входа и на дне каньона прямо перед устьем пещеры.",al={"are vile familiars inside cave","where to kill vile familiars","farm vile familiars","злобные фамильяры в пещере","где убивать злобных фамильяров","фарм злобных фамильяров"}}},fp="14,360,22.441.0,16.434.0,35.126.0,24.175.0,41.139.0,49.232.0,45.174.1,57.140.0"}
P.entries["quest:794"] = {n="Медальон Пылающего Клинка",s="Это задание выдает чернокнижница Зурита Востроглазая. Оно отправляет молодых новобранцев Орды в глубь пещеры Грот Пылающего Клинка в Долине Испытаний. Там игрокам предстоит схватиться с затаившимся сектантом и вернуть артефакт темной магии — Медальон Пылающего Клинка. Задание показывает, что демоническая скверна активно пускает корни прямо под носом у Орды.",h="Это задание выдает чернокнижница Зурита Востроглазая.",kw={"burning blade","coven","durotar","medallion","the den","valley of trials","warlock","yarrog baneshadow","zureetha fargaze","пылающий клинок","грот","дуротар","медальон","логово","долина испытаний","чернокнижник","йоррог тень проклятия","зурита востроглазая"},ang={["class:Shaman"]="Возвращение оскверненной реликвии помогает Зурите Востроглазой разоблачить демоническую скверну, оскверняющую землю Дуротара.",["class:Warlock"]="Схватка с Йоррогом напоминает об опасностях самовольного поклонения демонам вне дозволенных, тщательно скрываемых договоров, заключенных при власти Тралла.",["faction:Horde"]="Задание становится для молодых новобранцев последним испытанием и показывает их готовность отправиться в дикие земли Дуротара на защиту молодого государства.",["race:Orc"]="Охота на Йоррога Тень Проклятия показывает внутреннюю борьбу новой Орды за искоренение остатков демонической скверны старых порядков прямо в своих учебных лагерях."},sec={{t="Скрытая угроза в долине",b="Пока молодые орки и тролли проходят в Долине Испытаний начальные испытания боем и выживанием, в тени таится коварная опасность. С помощью гаданий чернокнижница Зурита Востроглазая чувствует, что мерзкие прислужники, наводнившие северные утесы, — лишь авангард более темной силы. Глубоко в соседней пещере культ Пылающего Клинка устроил тайный грот, где практикует темные искусства и хранит опасные реликвии демонической силы."},{t="Схватка с Йоррогом Тень Проклятия",b="Сам медальон находится в руках Йоррога Тень Проклятия — орка-чернокнижника, действующего как агент Пылающего Клинка. Йоррог скрывается на возвышенном уступе в глубине подземного логова и повелевает демоническими тварями и темной магией вдали от бдительных глаз надзирателей Долины. Если убить его и забрать медальон, местное руководство культа будет ослаблено, прежде чем его ритуалы проникнут глубже в сердце Дуротара."},{t="Затянувшаяся тень",b="Обретение талисмана подтверждает худшие опасения Зуриты Востроглазой. Хотя грот в Долине Испытаний разгромлен, медальон доказывает, что Пылающий Клинок действует организованно и целенаправленно. Влияние культа простирается далеко за пределы мест посвящения, и это значит, что молодой Орде предстоит столкнуться с куда более обширными демоническими заговорами по всему Дуротару."}},faq={{q="Где найти Грот Пылающего Клинка?",a="Грот Пылающего Клинка находится внутри пещеры в утесах к северу и западу от Логова в Долине Испытаний, среди бесоподобных мерзких прислужников.",al={"coven cave location","where is the cave","burning blade cave valley of trials","где пещера грота","где находится пещера","пещера пылающего клинка долина испытаний"}},{q="У кого находится Медальон Пылающего Клинка?",a="Медальон носит Йоррог Тень Проклятия, орк-сектант-отступник, которого можно найти глубоко в пещере, на возвышенном каменном уступе за неглубоким прудом.",al={"who drops the medallion","yarrog baneshadow","medallion mob","кто носит медальон","йоррог тень проклятия","моб с медальоном"}},{q="Что такое Пылающий Клинок?",a="Пылающий Клинок — коварный культ орков и чернокнижников, оскверненных скверной и преданных демоническим силам. Из тайных логовищ и лагерей они активно плетут интриги против новой Орды Тралла.",al={"who are burning blade","burning blade cult","what is burning blade","кто такие пылающий клинок","культ пылающего клинка","что такое пылающий клинок"}},{q="Почему медальон так важен для Зуриты Востроглазой?",a="Зурита увидела медальон в своих гаданиях. Это предмет силы, питающий темные ритуалы культа, и неоспоримое доказательство того, что демонические агенты проникают в Долину Испытаний.",al={"why does zureetha want it","what is the medallion","zureetha fargaze medallion","зачем он нужен зурите","что за медальон","зурита востроглазая медальон"}},{q="Означает ли победа над Йоррогом конец культа в Дуротаре?",a="Нет. Хотя гибель Йоррога очищает пещеру в Долине Испытаний, Зурита предупреждает, что этот ковен — лишь небольшая ячейка, а у Пылающего Клинка гораздо более масштабные замыслы по всему Дуротару.",al={"is the burning blade destroyed","are they gone","after burning blade medallion","уничтожен ли пылающий клинок","они исчезли","после медальона пылающего клинка"}},{q="Что происходит после сдачи медальона?",a="Доказав свою доблесть, убив Йоррога и вернув реликвию, вы считаетесь готовым покинуть Долину Испытаний и получаете приказ явиться в Деревню Сен'джин на южном побережье Дуротара.",al={"next quest","what comes next","after this quest","следующее задание","что дальше","после этого задания"}}},fp="23,363,29.453.0,29.434.1,20.361.1,40.168.0,44.165.0,26.180.0,54.208.0,53.189.0,44.190.0"}
P.entries["quest:8"] = {n="Выгодная сделка",s="Казалось бы, обычная услуга Кальвину Монтеччи в Могильнике отправляет путника в таверну «Петля висельника» в Брилле. Поручение — доставить Хозяйке таверны Ренни загадочное письмо без адреса под видом обычной курьерской работы.",h="Казалось бы, обычная услуга Кальвину Монтеччи в Могильнике отправляет путника в таверну «Петля висельника» в...",kw={"brill","calvin montague","deathknell","gallows end","innkeeper renee","nondescript letter","rogue","tirisfal glades","брилл","кальвин монтеччи","могильник","петля висельника","хозяйка таверны ренни","ненадписанное письмо","разбойник","тирисфальские леса"},ang={["class:Rogue"]="Частное поручение курьера Кальвина Монтеччи дает представление о неформальных делах, которые ведутся в Могильнике и Брилле.",["faction:Horde"]="Доставка прямо ведет в Брилл и знакомит недавно прибывших союзников с региональным центром управления и отдыха Отрекшихся в Тирисфале.",["race:Undead"]="Для недавно восставших Отрекшихся это поручение — первое путешествие прочь от безопасного кладбища Могильника к шумному Бриллу."},sec={{t="Дружеский курьер",b="Расположившись среди мрачных могил и разрушенных часовен Могильника, Кальвин Монтеччи выдает себя за измученного бойца, которому досаждают зомби Плети и ползучие пауки. Заявив, что ему просто нужна помощь с доставкой послания в Брилл, он вручает проходящим искателям приключений ненадписанное письмо. Его беспечный вид и обещание щедрой платы делают поручение безобидной услугой, призванной направить недавно пробудившихся Отрекшихся в главный город региона."},{t="Таверна «Петля висельника»",b="Дорога ведет на восток через погибающие деревья Тирисфальских лесов, мимо поместья «Остывший Очаг», к поселению Брилл. За стойкой местной таверны хозяйка таверны Ренни поначалу встречает новичков пугающе солнечным настроем и заботится об удобстве посетителей. Однако получив письмо Монтеччи, она тут же теряет радушие. Отбросив напускную любезность, она притворяется, что получила весть от любимой матери, затем отчитывает посыльного за любопытство и требует что-нибудь купить или уйти. Возвращение к Кальвину приводит к новому сюрпризу: вместо мирной выплаты обещанной награды он вызывает посыльного на дуэль."}},faq={{q="Кто такой Кальвин Монтеччи?",a="Кальвин Монтеччи — разбойник из Могильника, который просит только что пробудившихся путников отнести письмо хозяйке таверны Ренни в Брилле. Он представляет это как простую услугу и обещает хорошо заплатить.",al={"calvin montague","who gives a rogues deal","quest giver","кальвин монтеччи","кто дает задание выгодная сделка","персонаж, выдающий задания"}},{q="Что внутри Ненадписанного письма?",a="The letter's exact contents are not recorded. Calvin gives the courier an unmarked message to deliver to Innkeeper Renee in Brill.",al={"nondescript letter contents","what is in the letter","calvins letter","содержание ненадписанного письма","что в письме","письмо кальвина"}},{q="Почему Хозяйка таверны Ренни ведет себя так странно?",a="Ренни держит таверну в Брилле и настаивает, что ее переписка личная. Узнать ее реакцию на доставку можно, принеся ей письмо Монтеччи.",al={"innkeeper renee attitude","why is renee fake","renee mother excuse","отношение хозяйки таверны ренни","почему ренни притворяется","отговорка про мать ренни"}},{q="Платит ли Кальвин Монтеччи за доставку на самом деле?",a="Монтеччи обещает хорошо заплатить за доставку. Когда письмо попадает к Ренни, она предлагает еду или воду; после этого вернитесь к Кальвину, чтобы продолжить дела, связанные с обещанной платой.",al={"did calvin scam me","where is my money","montague reward","кальвин обманул","где мои деньги","награда монтеччи"}},{q="Где находится Брилл?",a="Брилл расположен к северо-востоку от Могильника. Путники идут по главной дороге на восток из начальной долины, поворачивают направо у поместья «Остывший Очаг» и по крытому мосту попадают в поселение.",al={"how to get to brill","road to brill","brill directions","как добраться до брилла","дорога в брилл","как пройти в брилл"}},{q="Что происходит после передачи письма Ренни?",a="Продолжение — еще одно задание под названием «Выгодная сделка». Вернитесь к Кальвину Монтеччи в Могильнике, чтобы продолжить дела с ним.",al={"next quest","a rogues deal follow up","what to do after renee","следующее задание","продолжение выгодной сделки","что делать после ренни"}}},fp="14,250,18.483.0,23.691.1,23.180.0,38.130.0,40.160.0,51.182.0,23.181.0,46.130.1"}
P.entries["quest:804"] = {n="Саркот",s="Отомстив за раненого тролля Хана'зуа и убив чудовищного скорпида Саркота, искатель приключений должен доставить весть о его беде в Логово. Горнека необходимо предупредить, чтобы помощь успела дойти до пострадавшего разведчика, пока ядовитые раны не отняли у него жизнь.",h="Отомстив за раненого тролля Хана'зуа и убив чудовищного скорпида Саркота, искатель приключений должен...",kw={"darkspear","durotar","gornek","hana'zua","sarkoth","scorpid","the den","valley of trials","черное копье","дуротар","горнек","хана'зуа","саркот","скорпид","логово","долина испытаний"},ang={["faction:Horde"]="Новая Орда строится на взаимной выручке в суровой, безжалостной земле; не бросать товарища — основополагающий принцип, который прививают с первых шагов новобранца.",["race:Orc"]="Культура орков ценит личную силу, но защита чести беспомощного союзника доказывает сердце настоящего воина.",["race:Troll"]="Зарождающийся союз племени Черного Копья и орков Тралла крепнет благодаря поступкам братства, таким как спасение Хана'зуа от медленной, мучительной смерти от яда."},sec={{t="Беда разведчика",b="Разведчик племени Черного Копья Хана'зуа застрял на высоких утесах Долины Испытаний: отравленный ядом, он не мог без помощи спуститься по опасным тропам. Хотя Саркот — грозный скорпид, сразивший его, — был наказан, одной гордостью не пронести отравленного воина по сухим камням. Прикованный к своей скале, он надеется, что проходящий мимо новобранец передаст весть вниз, в лагерь обучения."},{t="Честь в Логове",b="Возвращение к Горнеку в Логове завершает испытание. Горнек сразу понимает, какую угрозу представляет Саркот, и быстро организует помощь Хана'зуа. По мнению командиров Орды, готовность отложить собственное обучение, чтобы отомстить за павшего незнакомца и спасти его, воплощает истинную честь и доказывает ценность новобранца задолго до того, как он выйдет в Дуротар."}},faq={{q="Кто такой Хана'зуа и почему он застрял?",a="Хана'зуа — молодой разведчик-тролль из племени Черного Копья. Он забрался высоко в Долину Испытаний, где на него напал и отравил чудовищный скорпид Саркот. Он слишком слаб, чтобы спуститься сам, и ему нужно спасение.",al={"hanazua","who is hanazua","why is the troll hurt","хана'зуа","кто такой хана'зуа","почему тролль ранен"}},{q="Кто такой Горнек?",a="Горнек — орк-надзиратель, расквартированный в Логове в Долине Испытаний. Он оценивает новобранцев, дает задания на выживание и организует помощь, когда новички сталкиваются со смертельной опасностью в ущелье.",al={"gornek","where is gornek","den leader","горнек","где горнек","глава логова"}},{q="Что такое Саркот?",a="Саркот — известный огромный скорпид, обитающий на скалистых утесах над Долиной Испытаний. Его яд и свирепость делают его легендарной опасностью среди испытаний молодых орков и троллей.",al={"sarkoth beast","what kind of monster is sarkoth","саркот","что за чудовище саркот","скорпид саркот"}},{q="Выживет ли Хана'зуа после ран?",a="Да. Выслушав ваш доклад, Горнек сразу посылает на утесы спасательный отряд, чтобы вылечить его от яда и благополучно вернуть в лагерь.",al={"does the troll live","is hanazua okay","hanazua saved","выживет ли тролль","в порядке ли хана'зуа","хана'зуа спасен"}},{q="Почему Горнек так высоко ценит этот поступок?",a="Выжить в испытаниях — это ожидаемо, но отложить свои дела, чтобы отстоять честь незнакомца и спасти ему жизнь, — пример основных ценностей, которые новая Орда стремится воспитать в своих воинах.",al={"why does gornek care","gornek honor speech","почему горнека это волнует","речь горнека о чести"}},{q="Где находится Логово?",a="Логово — главная учебная пещера и сборный пункт в самом сердце Долины Испытаний на юго-западе Дуротара.",al={"where is the den","den location durotar","где логово","логово дуротар"}}},fp="7,254,16.425.0,16.363.0,39.228.0,14.201.0,16.197.0,33.141.1,43.198.0,25.125.0"}
P.entries["quest:805"] = {n="Деревня Сен'джин",s="Задание «Деревня Сен'джин» отмечает момент, когда молодые новобранцы Орды покидают уединенную Долину Испытаний, чтобы предупредить троллей Черного Копья о деятельности демонического культа. По поручению Зуриты Востроглазой гонцы несут весть о Пылающем Клинке Мастеру Гадрину и узнают, что магия тени уже угрожает ближним берегам.",h="Задание «Деревня Сен'джин» отмечает момент, когда молодые новобранцы Орды покидают уединенную Долину...",kw={"burning blade","darkspear","durotar","echo isles","master gadrin","sen'jin village","valley of trials","zureetha fargaze","пылающий клинок","черное копье","дуротар","острова эха","мастер гадрин","деревня сен'джин","долина испытаний","зурита востроглазая"},ang={["faction:Horde"]="Это задание показывает важное сотрудничество основных рас Орды Тралла, обменивающихся сведениями для защиты молодых поселений друг друга.",["race:Orc"]="Для молодых орков уход из Долины Испытаний на помощь племени Черного Копья — ранняя проверка чести и солидарности с союзниками, стоявшими рядом с Траллом за Великим морем.",["race:Troll"]="Возвращение в Деревню Сен'джин лицом к лицу сводит героев Черного Копья с изгнанием их народа и продолжающейся борьбой за возвращение Островов Эха."},sec={{t="Уход из Логова",b="Доказав боевую доблесть и добыв темные медальоны в Гроте Пылающего Клинка в Долине Испытаний, новички считаются готовыми к большому миру. Зурита Востроглазая понимает, что демоническое присутствие на священной земле испытаний — не случайная досада, а признак подкрадывающейся порчи по всему Дуротару. Она направляет молодых героев на восток за выход из ущелья, а затем на юг к побережью, чтобы предупредить племя Черного Копья."},{t="Тени над побережьем",b="Прибыв в прибрежное поселение Деревня Сен'джин, путники передают предупреждение Мастеру Гадрину, старейшему знахарю, ведущему племя Черного Копья в изгнании. Гадрин подтверждает, что сам Пылающий Клинок на пески деревни не наступал, но сообщает, что темная магия пустила корни неподалеку, на Островах Эха. Донесение показывает, насколько хрупок оплот молодой Орды: пока союзники спешат на помощь друг другу, древнее племенное предательство и скверна Скверны бьют по их флангам одновременно."}},faq={{q="Почему Зурита Востроглазая отправляет людей из Долины Испытаний?",a="Обнаружив демоническую деятельность в Долине Испытаний, Зурита Востроглазая опасается, что культ Пылающего Клинка представляет организованную угрозу для всего Дуротара. Она посылает проверенных новобранцев за пределы долины, чтобы предупредить союзные поселения и выяснить, как далеко распространилось влияние культа.",al={"why leave valley","why go to senjin","zureetha fargaze orders","почему покинуть долину","почему идти в сен'джин","приказ зуриты востроглазой"}},{q="Кто такой Мастер Гадрин?",a="Мастер Гадрин — старейший знахарь и духовный лидер троллей Черного Копья, живущих в Деревне Сен'джин. Он советник вождя Вол'джина и руководит делами племени, пока над их временным прибрежным убежищем нависают угрозы.",al={"master gadrin lore","who is gadrin","мастер гадрин","кто такой гадрин"}},{q="Нападал ли Пылающий Клинок на Деревню Сен'джин?",a="Нет, Пылающий Клинок напрямую на Деревню Сен'джин не нападал. Однако Мастер Гадрин отмечает, что родственная темная магия и предательство пустили корни неподалеку, на Островах Эха, а значит, троллям самим грозит неминуемая опасность.",al={"is burning blade in senjin","cult in senjin","пылающий клинок в сен'джин","культ в сен'джин"}},{q="Где находится Деревня Сен'джин?",a="Деревня Сен'джин лежит на восток от главного выхода из каньона Долины Испытаний, а затем на развилке дороги нужно повернуть на юг, к юго-восточному побережью Дуротара.",al={"how to get to senjin","senjin village direction","как добраться до сен'джин","где деревня сен'джин"}},{q="Какую угрозу на Островах Эха упоминает Мастер Гадрин?",a="Мастера Гадрина тревожит черное предательство Залазана, такого же тролля-знахаря, который коварными порчами поработил соплеменников и захватил власть над Островами Эха, вытеснив уцелевших троллей Черного Копья на материк.",al={"echo isles trouble","what happened at echo isles","беда на островах эха","что случилось на островах эха"}},{q="Что происходит после доклада Мастеру Гадрину?",a="Выслушав ваш доклад и рассказ о беде троллей, Гадрин просит вас помочь против опасностей, угрожающих побережью, а дальнейшие указания отправляют вас на северо-запад к Оргнилу Душегрызу в Колючий Холм.",al={"next quest after report to senjin","what to do after gadrin","следующее задание после деревни сен'джин","что делать после гадрина"}}},fp="25,322,15.449.0,22.510.1,70.285.0,21.259.0,47.227.0,33.168.0,57.234.0,46.216.0"}
P.entries["quest:806"] = {n="Сгущаются черные тучи",s="«Сгущаются черные тучи» — важное задание Оргнила Душегрыза из Колючего Холма: уничтожить мятежного чернокнижника, оскверняющего землю. Гоблин по имени Пшикс Черношквал закрепился в Громовом хребте от имени коварного культа Пылающего Клинка. Его устранение жизненно важно, чтобы защитить Дуротар от демонического возрождения, пока культисты не распространились дальше.",h="«Сгущаются черные тучи» — важное задание Оргнила Душегрыза из Колючего Холма: уничтожить мятежного...",kw={"burning blade","dark storms","durotar","fizzle darkstorm","fizzle's claw","orgnil soulscar","razor hill","thunder ridge","пылающий клинок","сгущаются черные тучи","дуротар","пшикс черношквал","клешня пшикса","оргнил душегрыз","колючий холм","громовой хребет"},ang={["class:Shaman"]="Темные обряды Пшикса и его приспешников нарушают природных духов Громового хребта, тревожат его зверей и требуют восстановления баланса стихий.",["class:Warlock"]="Пшикс Черношквал показывает безрассудную опасность неконтролируемой преданности Скверне: он позор и угроза, которую дисциплинированные чернокнижники Орды терпеть не могут.",["faction:Horde"]="Защита сердца Дуротара от демонического подрыва позволяет зарождающейся Орде направлять оборону вовне, а не рушиться изнутри.",["race:Orc"]="Пылающий Клинок олицетворяет темное прошлое, которое орки каждый день стремятся преодолеть. Устранение культистов-лазутчиков вроде Пшикса необходимо для сохранения свободного народа Тралла."},sec={{t="Угроза в хребте",b="Пока молодые защитники Орды патрулируют границы Дуротара, у них под носом зреет внутренняя порча. Оргнил Душегрыз, ведя расследование из Колючего Холма, обнаружил, что Громовой хребет на северо-западе подпал под власть темной магии. Ущелье кишит культистами Пылающего Клинка, несущими разорение и хаос местным животным и земле."},{t="Пшикс Черношквал",b="Деятельностью культистов в хребте руководит Пшикс Черношквал, расчетливый гоблин-чернокнижник, союзник Пылающего Клинка. Он не служит торговле или интересам картелей, а напрямую использует силу Скверны ради подрывных целей культа. Убийство Пшикса и добыча его искореженной клешни докажет Оргнилу, что ближайшее руководство культа в ущелье сломлено."},{t="Искоренение культа",b="Пылающий Клинок воплощает все, что новая Орда Тралла стремится оставить позади: демоническое рабство, безрассудную порчу и кровожадное безумие. Убийство Пшикса устраняет действующего заговорщика из глубины Дуротара, но также говорит о том, что тень над родиной орков простирается гораздо глубже отдельных лагерей."}},faq={{q="Кто такой Пшикс Черношквал?",a="Пшикс Черношквал — гоблин-чернокнижник, действующий от имени культа Пылающего Клинка. Он с последователями-культистами укрылся в Громовом хребте и сеет демонический хаос в ущелье, пока Оргнил Душегрыз не требует его казни.",al={"who is fizzle","fizzle darkstorm lore","fizzle goblin","кто такой пшикс","пшикс черношквал","гоблин пшикс"}},{q="Где находится Громовой хребет?",a="Громовой хребет — суровый каньон на северо-западе Дуротара, к северу от Колючего Холма и чуть юго-западнее Оргриммара. Он известен тем, что кишит зверями, напитанными молниями, и лагерями культистов Пылающего Клинка.",al={"where is thunder ridge","thunder ridge location","how to find thunder ridge","где громовой хребет","расположение громового хребта","как найти громовой хребет"}},{q="Почему Пылающий Клинок находится в Дуротаре?",a="Пылающий Клинок стремится подорвать Орду Тралла и вернуть демоническое господство над орками. Культисты тайно действуют из скрытых ущелий, пещер и каньонов по всему Дуротару, сея порчу изнутри.",al={"burning blade in durotar","why are cultists in durotar","burning blade motives","пылающий клинок в дуротаре","почему культисты в дуротаре","мотивы пылающего клинка"}},{q="Почему Оргнилу Душегрызу нужна именно клешня Пшикса?",a="Оргнилу нужно неоспоримое доказательство, что чернокнижник уничтожен. Клешня Пшикса подтверждает, что глава культистов в Громовом хребте больше не может руководить действиями.",al={"why fizzle claw","fizzle's claw meaning","proof of death fizzle","зачем клешня пшикса","клешня пшикса значение","доказательство смерти пшикса"}},{q="Что происходит после убийства Пшикса?",a="Победа над Пшиксом устраняет непосредственную угрозу в Громовом хребте, и Оргнил Душегрыз отправляет вас к шаману Маргозу, который больше знает о порче Пылающего Клинка, чтобы вы искоренили дальнейшие заговоры Пылающего Клинка.",al={"what comes after dark storms","dark storms follow up","next quest after dark storms","что после сгущаются черные тучи","продолжение сгущаются черные тучи","следующее задание после сгущаются черные тучи"}},{q="Почему гоблин служит Пылающему Клинку?",a="Хотя многие гоблины ищут золото через торговые картели, некоторых соблазняют грубая сила, влияние и темные искусства магии тени. Пшикс принял колдовство Скверны и отдал свою безжалостную хитрость на службу культистам.",al={"goblin in burning blade","why is fizzle with the cult","fizzle warlock","гоблин в пылающем клинке","почему пшикс с культом","пшикс чернокнижник"}}},fp="11,352,21.362.0,16.385.0,20.328.1,24.237.0,31.216.0,36.211.0,57.194.0,35.221.1,46.223.0"}
P.entries["quest:809"] = {n="Ак'Зелот",s="«Ак'Зелот» — одно из первых заданий Орды, которое дает чернокнижник Нииру Огненный Клинок из глубин Расселины Теней в Оргриммаре. Получив свидетельства сохраняющейся демонической порчи, Нииру отправляет искателей приключений в Степи на встречу с его осведомителем у границы.",h="«Ак'Зелот» — одно из первых заданий Орды, которое дает чернокнижник Нииру Огненный Клинок из глубин Расселины...",kw={"ak'zeloth","barrens","burning blade","cleft of shadow","demon seed","dreadmist peak","far watch post","neeru fireblade","ак'зелот","степи","пылающий клинок","расселина теней","демоново семя","вершина багрового тумана","дальняя застава","нииру огненный клинок"},ang={["class:Warlock"]="Чернокнижники, знакомые с учением Нииру Огненного Клинка, могут распознать тонкое двуличие своего наставника, когда его помощник ставит под сомнение призыв уничтожить демоническую реликвию.",["faction:Horde"]="Защита Дальней заставы и очистка Вершины Багрового Тумана крайне важны для безопасности зарождающихся торговых и транспортных путей между Дуротаром и Степями.",["race:Orc"]="Орки отчаянно боролись, чтобы вырваться из хватки Пылающего Легиона, поэтому любой признак культа Пылающего Клинка и демонических реликвий у их порога — неотложная угроза."},sec={{t="Теневой след",b="После находки ошейника с символикой Пылающего Клинка в Дуротаре Нииру Огненный Клинок заявляет, что выслеживает остатки демонов, угрожающие недавно обосновавшейся Орде. Выставляя себя стражем от порчи Скверны, Нииру направляет искателей приключений в сухие равнины Степей, предупреждая, что вокруг артефакта мерзкой силы, известного как Демоново семя, собирается темный культ."},{t="Контакт на заставе",b="Чтобы согласовать удар по культу, искатели приключений должны найти Ак'Зелота, помощника Нииру, находящегося у Дальней заставы на границе Дуротара и Степей. Однако по прибытии Ак'Зелот встречает задание с тихим скепсисом и вслух гадает, зачем его хозяину всерьез понадобилось уничтожить артефакт, прежде чем объяснить, как поступить с Демоновым семенем на Вершине Багрового Тумана."}},faq={{q="Кто дает это задание?",a="Задание дает Нииру Огненный Клинок, чернокнижник, обитающий в сумрачной пещере Расселины Теней под Оргриммаром, сразу после того как вы покажете ему ошейник Пылающего Клинка.",al={"quest starter","where to get ak'zeloth","neeru fireblade quest","начало задания","где взять ак'зелота","задание нииру огненный клинок"}},{q="Где находится Ак'Зелот?",a="Ак'Зелот находится сразу за Дальней заставой, у восточной границы Степей, где мост ведет из Дуротара.",al={"ak'zeloth location","where is ak'zeloth","find ak'zeloth","где ак'зелот","местонахождение ак'зелота","найти ак'зелота"}},{q="Что такое Демоново семя?",a="Демоново семя — мерзкий артефакт демонической силы, которым владеет культ Пылающего Клинка на Вершине Багрового Тумана, зловещей горе на севере Степей.",al={"demon seed lore","what is the seed","демоново семя","что за семя"}},{q="Почему Ак'Зелот считает приказы Нииру странными?",a="Ак'Зелот ничего не объясняет. Он лишь замечает, что странно, что Нииру хочет уничтожить Демоново семя, а затем соглашается рассказать вам, как его убрать.",al={"why is ak'zeloth surprised","strange reaction ak'zeloth","почему ак'зелот удивлен","странная реакция ак'зелота"}},{q="Какое задание идет следом?",a="Разговор с Ак'Зелотом сразу ведет к заданию «Демоново семя», в котором вам предстоит подняться на Вершину Багрового Тумана и обезвредить оскверняющую реликвию.",al={"next quest after ak'zeloth","ak'zeloth followup","следующее задание после ак'зелота","продолжение ак'зелота"}},{q="Входит ли это задание в сюжетную линию Пылающего Клинка?",a="Да. Оно служит важным звеном, связывающим местные заговоры культистов в Дуротаре с более широкой организованной деятельностью культа, обосновавшегося в Степях.",al={"burning blade questline","orgrimmar cult quest","цепочка пылающего клинка","задание культа оргриммар"}}},fp="9,278,17.373.0,19.390.1,21.184.0,27.143.0,23.156.0,47.152.1,28.158.0,50.161.0"}
P.entries["quest:812"] = {n="Нужда в исцелении",s="Тролль из племени Черного Копья Ринаг лежит отравленный ядохвостым скорпидом на суровых утесах северо-западного Дуротара. У него почти не остается времени до гибели от яда, и он надеется, что гонец домчится до Оргриммара и принесет лекарство от Кор'гхана.",h="Тролль из племени Черного Копья Ринаг лежит отравленный ядохвостым скорпидом на суровых утесах...",kw={"antidote","cleft of shadow","durotar","kor'ghan","need for a cure","orgrimmar","rhinag","scorpid","venomtail","противоядие","расселина теней","дуротар","кор'гхан","нужда в исцелении","оргриммар","ринаг","скорпид","ядохвост"},ang={["faction:Horde"]="Скалистая местность Дуротара сурова и беспощадна и становится непрестанным огненным испытанием для новоприбывших защитников молодого государства Тралла.",["race:Troll"]="Страх Ринага вернуться в Деревню Сен'джин подчеркивает суровую гордость племени Черного Копья, где небрежность в простом выживании в глуши навлекает жестокие насмешки сородичей."},sec={{t="Укус скорпида",b="Сухие каньоны Дуротара кишат ядохвостыми скорпидами — агрессивными хищниками, чье жало несет быстрый, изнуряющий нейротоксин. Ринаг допустил ошибку, ослабив бдительность в бою с тварями у границы. Зная, что яд в его венах убьет его меньше чем за час, он не может сам дойти до городских врат и вверяет свою жизнь тому, кто пройдет мимо его уединенного лагеря."},{t="Тайны во мраке",b="Вместо того чтобы довериться обычному аптекарю или шаману, Ринаг направляет путников глубоко под Оргриммар, в сумрачные подземные пещеры Расселины Теней. Там обитает Кор'гхан, загадочный знаток, знакомый с жестокими ядами пустошей Дуротара. Кор'гхан обладает знаниями, нужными для приготовления действенного противоядия, но редко помогает безвозмездно тем, кто не доказал свою доблесть."}},faq={{q="Кто такой Ринаг?",a="Ринаг — тролль-искатель приключений из племени Черного Копья, цепляющийся за жизнь на северо-западных утесах Дуротара. Ужаленный ядохвостым скорпидом, он боится не только скорой смерти, но и насмешек сородичей из Деревни Сен'джин, если вернется туда в таком униженном виде.",al={"rhinag lore","who is rhinag","rhinag the troll","история ринага","кто такой ринаг","тролль ринаг"}},{q="Почему Кор'гхан находится в Расселине Теней?",a="Кор'гхан живет в Расселине Теней, сумрачной пещере под Оргриммаром, где чернокнижники, разбойники и другие знатоки темных искусств занимаются своим ремеслом вдали от глаз почетных воинов Тралла. Его знание ядовитых зелий и суровых испытаний подходит подземной обстановке Расселины.",al={"where is korgan","who is korghan","kor'ghan location","где кор'гхан","кто такой кор'гхан","местонахождение кор'гхана"}},{q="Почему Ринаг не обратится к шаману или целителю в Деревне Сен'джин?",a="Ринаг признает, что его удерживает собственная гордость. Он боится, что возвращение в Деревню Сен'джин в таком небрежном, отравленном состоянии вызовет лишь насмешки сородичей-троллей, и предпочитает тайно получить средство у Кор'гхана.",al={"why not go to senjin","why rhinag avoids senjin","почему не в сен'джин","почему ринаг избегает сен'джин"}},{q="Что происходит после того, как Ринаг получает противоядие?",a="Ринаг выпивает противоядие и выздоравливает, но его беды на этом не кончаются. Зная Кор'гхана, целитель потребует от Ринага доказать себя новыми суровыми испытаниями — убивать кабанов и собирать хвосты скорпидов, — прежде чем он вернет расположение знатока.",al={"does rhinag survive","rhinag aftermath","выживет ли ринаг","что стало с ринагом"}},{q="Где можно найти Ринага?",a="Он находится на суровых утесах северо-западного Дуротара, у пограничных проходов, ведущих на запад к Степям.",al={"rhinag location","where is rhinag","где ринаг","местонахождение ринага"}},{q="Почему с этим лекарством так спешат?",a="Яд ядохвостого скорпида исключительно силен: у нелеченого пострадавшего остается меньше часа, прежде чем яд поразит жизненно важные органы.",al={"why is it timed","rhinag poison timer","почему на время","таймер яда ринага"}}},fp="15,260,17.452.0,22.425.0,14.270.0,39.310.0,67.251.0,48.282.1,26.127.0,47.148.0"}
P.entries["quest:813"] = {n="Поиски противоядия",s="«Поиски противоядия» — срочное задание Кор'гхана в Оргриммаре: нужно сварить лекарство для отравленного охотника Ринага. Времени мало, пока яд не оказался смертельным, и искателю приключений нужно собрать ядовитые мешочки скорпидов-ядохвостов за городскими стенами. Задание показывает суровость животного мира Дуротара и необходимость подготовки к жизни в глуши.",h="«Поиски противоядия» — срочное задание Кор'гхана в Оргриммаре: нужно сварить лекарство для отравленного...",kw={"antidote","durotar","kor'ghan","orgrimmar","poison","rhinag","scorpid","venomtail","противоядие","дуротар","кор'гхан","оргриммар","яд","ринаг","скорпид","ядохвост"},ang={["class:Hunter"]="Кор'гхан — строгое напоминание всем охотникам: знание яда зверя и наличие подходящих лекарств так же важны, как ваш лук и умение выслеживать.",["faction:Horde"]="Орда в Дуротаре заботится о своих: одинокие следопыты и разведчики на границах могут рассчитывать на помощь оплота — Оргриммара.",["race:Orc"]="Выживание в Дуротаре испытывает выносливость недавно поселившихся орков и показывает: даже опытный разведчик может погибнуть от местных опасностей, если будет небрежен."},sec={{t="Гонка с ядом",b="Охотясь по всему Дуротару, тролль из племени Черного Копья по имени Ринаг совершил опасную ошибку: напал на местных скорпидов-ядохвостов, не взяв с собой противоядия. Ужаленный, он быстро слабел от их сильного яда и был вынужден послать за срочной помощью. Кор'гхан, опытный охотник из Оргриммара, должен приготовить исцеляющее снадобье, пока яд не закончил свое дело."},{t="Создание лекарства",b="Чтобы создать противоядие, нужно добыть источник самой отравы: ядовитые мешочки взрослых ядохвостов, обитающих у ворот Оргриммара. Кор'гхан замечает, что упреки Ринагу за недостаток подготовки подождут, ведь дорога каждая минута. Когда мешочки быстро добыты и доставлены в город, Кор'гхан готовит снадобье, чтобы его немедленно отнесли умирающему охотнику."}},faq={{q="Кто такой Ринаг?",a="Ринаг — охотник из племени троллей Черного Копья в Дуротаре. Выслеживая зверей, он был сильно ужален местными ядохвостами. Без противоядия в пути он оказался беспомощен и зависел от гонцов, которым предстояло доставить лекарство из Оргриммара, пока яд не убил его.",al={"rhinag lore","who is poisoned","who needs the antidote","ринаг","кто отравлен","кому нужно противоядие"}},{q="Кто такой Кор'гхан?",a="Кор'гхан — опытный охотник-тролль из племени Черного Копья, живущий в Расселине Теней в Оргриммаре. Он прекрасно знает диких зверей Дуротара и обладает алхимическими знаниями, нужными, чтобы сварить действенное противоядие из сырых ядовитых мешочков ядохвостов.",al={"kor'ghan","who is korphan","korgan orgrimmar","кор'гхан","кто такой коргхан","кор'гхан оргриммар"}},{q="Откуда берутся нужные ядовитые мешочки?",a="Ядовитые мешочки добывают прямо из скорпидов-ядохвостов, которые бродят по каменистым сухим равнинам недалеко от главных южных и восточных входов в Оргриммар.",al={"where are venomtails","poison sac location","venomtail scorpid sacs","где ядохвосты","где взять ядовитые мешочки","мешочки скорпидов-ядохвостов"}},{q="Почему у этого задания есть ограничение по времени?",a="Срочность вызвана ухудшающимся здоровьем Ринага. Яд ядохвостов исключительно губителен и действует быстро, поэтому Кор'гхан должен получить ингредиенты и приготовить лекарство, пока охотник не погиб от отравления.",al={"why is there a timer","need for a cure timer","timed quest","почему таймер","нужда в исцелении таймер","задание на время"}},{q="Какой урок подчеркивает Кор'гхан во время этой охоты?",a="Кор'гхан предупреждает, что каждый охотник должен тщательно изучить повадки и смертельные опасности своей добычи, прежде чем нападать. Отправляться в глушь без должной подготовки и средств защиты — недосмотр, который легко может стоить воину жизни.",al={"kor'ghan lesson","hunting lesson","kor'ghan advice","урок кор'гхана","урок охоты","совет кор'гхана"}},{q="Как это задание связано с заданием «Нужда в исцелении»?",a="«Нужда в исцелении» — первое поручение, которое запускает чрезвычайную ситуацию и отсчет времени. «Поиски противоядия» — промежуточный шаг, на котором игрок собирает сырье, чтобы Кор'гхан сварил готовое снадобье.",al={"need for a cure connection","prerequisite quest","how does it connect","нужда в исцелении связь","предыдущее задание","как связано"}}},fp="20,368,24.397.0,17.405.0,14.266.0,16.259.0,43.165.0,47.242.0,53.250.0,46.238.0"}
P.entries["quest:816"] = {n="Пропавший, но не забытый",s="«Пропавший, но не забытый» — печальное задание, которое дает Майша Тор'крен на своей ферме к северо-западу от Колючего Холма. Отчаянно желая узнать правду, она просит путников поискать на опасных берегах Реки Строптивой хоть какие-то следы ее упрямого сына Крона.",h="«Пропавший, но не забытый» — печальное задание, которое дает Майша Тор'крен на своей ферме к северо-западу от...",kw={"amulet","crocolisk","dreadmaw","kron","misha","razor hill","southfury","tor'kren","амулет","кроколиск","крупнозубый кроколиск","крон","майша","колючий холм","строптивая","тор'крен"},ang={["class:Hunter"]="Для охотников Крон — предостерегающий пример следопыта, не оценившего свирепость добычи и ставшего ее обедом.",["faction:Horde"]="Жизнь в раннем Дуротаре сурова и беспощадна: обычные семьи борются с неумолимой землей и смертоносными хищниками, бродящими у ее границ.",["race:Orc"]="Судьба Крона — печальное напоминание: хотя гордость и воинская слава лежат в основе культуры орков, безрассудная самонадеянность и неуважение к опасным зверям ведут к негероической смерти."},sec={{t="Страх матери",b="К северо-западу от Колючего Холма, среди засушливых красных пустошей Дуротара, стоит скромная ферма Тор'крен. Здесь живет Майша Тор'крен, мать-орчиха, скованная горем и тревогой. Несколько дней назад ее сын Крон объявил, что идет на запад, к Реке Строптивой на границе Степей, охотиться на свирепых кроколисков. Несмотря на ее предостережения об опасных тварях, упрямая гордость погнала Крона прочь, чтобы доказать свою доблесть. С тех пор его никто не видел."},{t="Мрачное подтверждение",b="Майша просит проходящих мимо искателей приключений обыскать берега Реки Строптивой в поисках любых следов судьбы Крона и даже советует заглянуть в желудки кроколисков. К несчастью, худшие ее предчувствия оправдываются. Убив свирепых крупнозубых кроколисков у воды, можно найти проглоченный амулет Крона. Возвращение памятной вещи Майше лишает ее последней надежды, что сын жив, но наконец дает скорбящей матери покой, нужный, чтобы начать оплакивать его."}},faq={{q="Кто такая Майша Тор'крен?",a="Майша Тор'крен — мать-орчиха, живущая на уединенной ферме к северо-западу от Колючего Холма в Дуротаре. Измученная горем и тревогой, она просит странников найти любые следы ее пропавшего сына Крона.",al={"misha torkren","who gives lost but not forgotten","kron mother","майша тор'крен","кто дает пропавший, но не забытый","мать крона"}},{q="Кто такой Крон?",a="Крон был упрямым сыном Майши Тор'крен. Желая доказать свою силу, он проигнорировал предостережения матери и ушел охотиться на опасных кроколисков у Реки Строптивой, где и встретил безвременную смерть.",al={"who is kron","what happened to kron","misha son","кто такой крон","что случилось с кроном","сын майши"}},{q="Где пропал Крон?",a="Крон отправился на запад через Дуротар к границе Степей, чтобы охотиться на берегах Реки Строптивой.",al={"where is kron","where to look for kron","kron location","где крон","где искать крона","местонахождение крона"}},{q="Как доказать Майше судьбу Крона?",a="Вы находите проглоченный амулет Крона среди останков крупнозубых кроколисков, бродящих в водах Реки Строптивой. Возвращение этой семейной реликвии Майше подтверждает его гибель.",al={"krons amulet","sign of krons fate","crocolisk stomach","амулет крона","знак судьбы крона","желудок кроколиска"}},{q="Какую награду дает Майша?",a="Майша дает вам подарок, который изначально приготовила для Крона, чтобы отпраздновать его триумфальное возвращение с охоты. Не в силах смотреть на него после известия о смерти сына, она отдает его искателю приключений, подарившему ей покой.",al={"lost but not forgotten reward","misha gift","пропавший, но не забытый награда","подарок майши"}},{q="Почему Крон вообще ушел?",a="Крона вела упрямая гордость и желание доказать свое охотничье мастерство. Когда мать предупредила, что кроколиски слишком свирепы и опасны, он пришел в ярость и все равно ушел охотиться на них.",al={"why did kron hunt","kron pride","почему крон пошел на охоту","гордость крона"}}},fp="22,244,16.475.0,19.465.1,22.201.0,13.202.1,26.114.0,38.184.1,28.224.1,38.212.0"}
P.entries["quest:817"] = {n="Полезная добыча",s="«Полезная добыча» — охотничье задание, которое дает кожевник Вель'рин Клык в Деревне Сен'джин. Население растет, запасы тают, и племени Черного Копья нужно добывать прочные тигровые шкуры на соседних Островах Эха, чтобы делать жилища, одежду и снаряжение.",h="«Полезная добыча» — охотничье задание, которое дает кожевник Вель'рин Клык в Деревне Сен'джин.",kw={"darkspear","durotar tiger","echo isles","hunting","leatherworking","practical prey","sen'jin village","tiger fur","vel'rin fang","черное копье","тигр дуротара","острова эха","охота","кожевничество","полезная добыча","деревня сен'джин","тигровая шкура","вель'рин клык"},ang={["class:Hunter"]="Рассказ Вель'рина о целом дне молчаливого выслеживания перед тем, как захлопнуть ловушку, напрямую говорит о главных добродетелях — терпении и точности, которым учат всех молодых охотников.",["faction:Horde"]="Поддержка молодого поселения племени Черного Копья необходимыми товарами помогает укрепить южный фланг Орды вдоль Великого моря.",["race:Troll"]="Для изгнанного племени Черного Копья охота на Островах Эха — горькое напоминание об утраченном доме: чтобы кормить род, приходится ступать по земле, захваченной Залазаном."},sec={{t="Вопрос выживания",b="Жизнь на засушливом побережье Дуротара сурова, и тролли Черного Копья, изгнанные в Деревню Сен'джин, должны использовать каждый ресурс. Тигровые шкуры — один из самых универсальных материалов: из них шьют палатки, плотные одеяла и усиленные доспехи. Поселение растет за счет беженцев и вернувшихся разведчиков, запасы истощились, и ремесленники вроде Вель'рина Клыка вынуждены заказывать новые охоты."},{t="Равновесие и охота",b="Племя Черного Копья осознанно относится к хищникам своих земель. Вместо чрезмерной охоты на местных тигров Дуротара тролли обычно оставляют их в покое и бьют их, лишь когда нужно пополнить запасы племени. Переправа через воду на Острова Эха для охоты на этих хищников — и практическая необходимость, и традиционное испытание терпения, дисциплины и умения жить в глуши."}},faq={{q="Кто такой Вель'рин Клык?",a="Вель'рин Клык — тролль-ремесленник из племени Черного Копья в Деревне Сен'джин, работающий со шкурами и кожей. Он направляет охотников добывать необходимые шкуры, чтобы племя было одето, укрыто и снаряжено.",al={"vel'rin fang","who gives practical prey","velrin fang","вель'рин клык","кто дает полезная добыча","велрин клык"}},{q="Зачем Деревне Сен'джин тигровые шкуры?",a="Растущее население Деревни Сен'джин истощило прежние запасы. Тигровые шкуры дают прочный материал для теплых одеял, крепких палаток и кожаных доспехов, защищающих жителей от суровой погоды.",al={"why tiger pelts","practical prey purpose","what are furs used for","зачем тигровые шкуры","для чего полезная добыча","для чего нужны шкуры"}},{q="Где водятся тигры Дуротара?",a="Тигры бродят по дикой местности Островов Эха — архипелага у юго-восточного побережья Дуротара.",al={"where are the tigers","tiger location","echo isles tigers","где тигры","где найти тигров","тигры острова эха"}},{q="Почему тролли не истребляют всех тигров поблизости?",a="Вель'рин объясняет, что племя Черного Копья намеренно соразмеряет свои нужды с местной экологией. Тролли дают хищникам процветать, чтобы популяция оставалась устойчивой, и вмешиваются, лишь когда потребности деревни превышают запасы.",al={"why let tigers thrive","culling the flock","почему не трогать тигров","сокращение стаи"}},{q="Важна ли охота на тигров для культуры племени Черного Копья?",a="Да. Выслеживание тигра считается обрядом терпения и хитрости. Вель'рин с теплотой вспоминает, как почти целый день неподвижно ждал в листве на Островах Эха, прежде чем одержал свою первую крупную охотничью победу.",al={"tiger hunt tradition","first tiger hunt","традиция охоты на тигров","первая охота на тигра"}},{q="Почему охотникам нужно плыть на Острова Эха, если там хозяйничает Залазан?",a="Хотя предатель-знахарь Залазан и его одурманенные приспешники занимают большую часть архипелага, диких зверей на островах по-прежнему много. Добывать пищу и охотиться на внешних берегах остается необходимым риском для племени Черного Копья.",al={"tigers on echo isles","why go to echo isles","тигры на островах эха","зачем плыть на острова эха"}}},fp="14,280,20.430.0,20.432.0,20.197.0,41.219.0,35.127.0,48.256.0,51.212.0,65.231.0"}
P.entries["quest:818"] = {n="Растворитель",kw={"alchemy","crawler mucus","darkspear strand","durotar","intact makrura eye","makrura","master vornal","sen'jin village","алхимия","слизь краулера","побережье черного копья","дуротар","целый глаз макрура","макруры","мастер ворнал","деревня сен'джин"},ang={["faction:Horde"]="Прибрежный Дуротар остается опасным для молодой Орды: уничтожение агрессивных макруров и прибрежных краулеров делает безопаснее рыбацкие берега возле деревни Сен'джин.",["race:Orc"]="Ворнал открыто сомневается, что оркам хватит тихой дисциплины для алхимии, и потому задание — шанс доказать, что единство Орды включает и ученое терпение.",["race:Troll"]="Для Черного Копья, возрождающегося в деревне Сен'джин, важно проявить себя перед старейшинами вроде Мастера Ворнала, чтобы продолжить мистические и алхимические традиции племени."},sec={{t="Угасающее зрение мастера",b="Мастер Ворнал живет в деревне Сен'джин, обремененный возрастом и ослабевающим зрением. Если раньше первобытная магия сама собой текла к его пальцам, то теперь он сильно полагается на алхимию, чтобы обострять восприятие и творить свои искусства. Несмотря на растущую немощь, упрямый тролль отказывается брать ученика, утверждая, что ни среди Черного Копья, ни среди орков Дуротара не нашлось никого, достойного его наставничества."},{t="Испытание неопытных",b="Вместо прямого обучения Ворнал требует сырье с сурового побережья: целые глаза макруров и пузырьки со слизью краулеров. Добыть неповрежденные глаза у панцирных щелкающих макруров можно только точными ударами, а сбор достаточного количества слизи проверяет готовность авантюриста терпеть нудную черную работу. Для Ворнала охота на этих прибрежных тварей нужна не ради реагентов, а чтобы отсеять тех, кому не хватает сосредоточенности."},{t="Мера воли",b="Для мастера Ворнала время и терпение — высшая мера силы. Он ждет, что дерзкая молодежь поддастся раздражению или вовсе бросит поручение. Возвращение в деревню Сен'джин с безупречными ингредиентами показывает не только умение выживать среди опасных рифов пролива у Островов Эха, но и дисциплину, необходимую для овладения тонким искусством алхимии."}},faq={{q="Кто такой Мастер Ворнал?",a="Мастер Ворнал — пожилой тролль-алхимик и заклинатель, живущий в деревне Сен'джин. С возрастом его зрение слабеет, и он вынужден прибегать к алхимическим растворам и зельям, чтобы творить магию, которая раньше давалась ему легко.",al={"master vornal","who is vornal","vornal lore","мастер ворнал","кто такой ворнал","ворнал предания"}},{q="Зачем Ворналу глаза макруров и слизь краулеров?",a="Ворнал полагается на алхимические составы, чтобы поддерживать магию и возмещать слабеющее зрение. Слизь и целые глаза макруров служат реагентами для его смесей, а также вступительным испытанием для возможных учеников.",al={"why crawler mucus","why makrura eyes","what does vornal make","зачем слизь краулеров","зачем глаза макруров","что варит ворнал"}},{q="Почему Ворнал так неохотно берет ученика?",a="Ворнал предъявляет высокие требования и не терпит высокомерия. Он считает, что ни один тролль или орк не проявил подлинного усердия и терпения, нужных для обучения у него, и видит в большинстве желающих чересчур гордых и легко падающих духом учеников.",al={"vornal apprentice","why no apprentice","is vornal looking for a student","ученик ворнала","почему нет ученика","ищет ли ворнал ученика"}},{q="Где обитают эти существа возле деревни Сен'джин?",a="Краулеры и макруры бродят на мелководье вдоль Побережья Черного Копья и населяют протоки, отделяющие материк от Островов Эха неподалеку от берега.",al={"where are makrura","where are crawlers","darkspear strand beasts","где макруры","где краулеры","звери побережья черного копья"}},{q="Почему глаза макруров должны быть целыми?",a="Алхимические зелья, обостряющие восприятие, требуют неповрежденных органов чувств. Грубые удары в бою могут раздавить нежные глаза макрура, поэтому охотнику нужны точность и сдержанность.",al={"intact eye","makrura intact eyes","why intact eyes","целый глаз","целые глаза макруров","почему целые глаза"}},{q="Какому уроку хочет научить Ворнал?",a="Ворнал считает, что терпение — истинное испытание характера. Поручая однообразную и грязную работу у прибоя, он хочет увидеть, поддастся ли новичок слабости и спешке или сохранит спокойную сосредоточенность алхимика.",al={"vornal lesson","meaning of the quest","patience test","урок ворнала","смысл задания","испытание терпения"}}},fp="16,336,23.409.0,20.445.0,17.369.0,21.225.0,52.240.0,50.245.0,55.146.0,42.197.0,38.240.0"}
P.entries["quest:819"] = {n="Пустой бочонок Чэня",s="Среди глуши Степей лежит пустой бочонок с надписью Чэня Буйного Портера. Его находка начинает путь в прошлое знаменитого странствующего пивовара, который когда-то помог своим боевым мастерством основанию Дуротара.",h="Среди глуши Степей лежит пустой бочонок с надписью Чэня Буйного Портера.",kw={"barrens","brewing","brewmaster drohn","chen stormstout","empty keg","pandaren","ratchet","rexxar","степи","пивоварение","пивовар дрон","чэнь буйный портер","пустой бочонок","пандарен","кабестан","рексар"},ang={["faction:Horde"]="Чэня Буйного Портера помнят как почетного союзника, сражавшегося бок о бок с Рексаром и Рохана ради основания Дуротара и защиты Орды в первые дни.",["profession:Cooking"]="Бочонок олицетворяет наследие мастера-пивовара, чье легендарное чутье и поиски редких ингредиентов вдохновили ремесленников по всему Калимдору."},sec={{t="Странствующая реликвия",b="Среди засушливых просторов Степей путники порой натыкаются на брошенную деревянную бочку. В отличие от обычных бочонков, оставленных свинобразами Иглогривыми или кентаврами Колкар, эта сделана тщательно и несет памятную табличку: «Чэнь Буйный Портер — пусть твой дух будет поднят, а твой дух всегда поднимает». Эта необычная реликвия, томящаяся под солнцем Калимдора, заставляет любопытных искать знатока пивоварения, чтобы выяснить, как она здесь оказалась."},{t="Отголоски основания Дуротара",b="Если отнести бочонок Пивовару Дрону в Кабестан, станет ясно его происхождение. Дрон сразу узнает работу: бочонок принадлежал Чэню Буйному Портеру, легендарному страннику-пандарену, который вместе с Рексаром участвовал в решающих битвах, обеспечивших Дуротар для Орды Тралла. Хотя с тех пор, как Чэнь ступал по красной земле Калимдора, прошли годы, его легендарные рецепты и странствующий дух живы в памяти опытных пивоваров этих мест."}},faq={{q="Что такое Пустой бочонок Чэня?",a="Это брошенная пивоваренная бочка, найденная в Степях. На ней надпись, посвящающая ее странствующему пандарену-пивовару Чэню Буйному Портеру.",al={"empty keg","chens keg","what is this barrel","пустой бочонок","бочонок чэня","что за бочка"}},{q="Кто такой Чэнь Буйный Портер?",a="Чэнь Буйный Портер — неуловимый пандарен-пивовар, много путешествовавший по Калимдору. Он больше всего известен тем, что помогал могу'нату-повелителю зверей Рексару в обороне и раннем основании Дуротара.",al={"who is chen","chen lore","pandaren brewmaster","кто такой чэнь","чэнь предания","пандарен пивовар"}},{q="Кому нужно отнести бочонок?",a="Бочонок можно отнести Пивовару Дрону, орку-пивовару, стоящему на дороге возле Кабестана: он узнает клеймо Чэня и умеет воссоздавать его рецепты.",al={"where to turn in keg","who wants chens keg","keg turn in","куда сдать бочонок","кому нужен бочонок чэня","сдать бочонок"}},{q="Почему бочонок Чэня валяется в Степях?",a="Много лет назад Чэнь бродил по Калимдору в поисках необычных ингредиентов для своих напитков, особенно во время путешествий, когда помогал юной Орде отстоять новую родину от войск адмирала Праудмура.",al={"why is keg in barrens","how did keg get here","почему бочонок в степях","как бочонок сюда попал"}},{q="Появляется ли Чэнь Буйный Портер лично?",a="Нет. Чэнь покинул эти края и давно не появлялся в Калимдоре. Остались лишь его старые бочки, рецепты и теплые воспоминания таких союзников, как Дрон и Рексар.",al={"can i find chen","where is chen stormstout","is chen in classic","можно ли найти чэня","где чэнь буйный портер","есть ли чэнь в классике"}},{q="Что Пивовар Дрон делает с бочонком?",a="Дрон в восторге от реликвии и пользуется случаем, предлагая отважным странникам собрать ингредиенты из местных зверей, чтобы воссоздать мощные легендарные напитки Чэня.",al={"drohn quest line","what happens next with keg","цепочка заданий дрона","что дальше с бочонком"}}},fp="16,243,17.517.0,28.455.0,25.151.0,23.204.0,29.159.0,43.205.0,38.176.0,43.185.0"}
P.entries["quest:821"] = {n="Пустой бочонок Чэня",s="Это задание продолжает легендарную линию пандаренского пивоварения в Степях. Пивовар Дрон в Кабестане предлагает воссоздать знаменитый крепкий напиток Чэня Буйного Портера, если вы соберете дикие ингредиенты у местных зверей, бродящих по саванне.",h="Это задание продолжает легендарную линию пандаренского пивоварения в Степях.",kw={"brewmaster drohn","chen stormstout","keg","plainstrider kidney","ratchet","savannah lion tusk","the barrens","thunder lizard horn","trogg brew","пивовар дрон","чэнь буйный портер","бочонок","почки кочевника равнин","кабестан","бивень саванного льва","степи","рог громового ящера","троггская брага"},ang={["faction:Horde"]="Чэнь Буйный Портер сражался плечом к плечу с Рексаром, помогая основать Дуротар, поэтому любая память о его странствиях имеет для Орды особое культурное значение.",["profession:Cooking"]="Кулинарные авантюристы оценят смелое, хотя и тревожащее сочетание пограничного мясницкого дела и тонкого пивоварения, из которого рождаются легендарные напитки Калимдора.",["race:Orc"]="Дрон показывает, как орки приняли древние традиции пивоваров, переданные напрямую странниками, ходившими по этой земле бок о бок с ранней Ордой."},sec={{t="Наследие в бочонке",b="Когда брошенный бочонок с пандаренской надписью попадает к Пивовару Дрону в Кабестане, он вызывает теплые воспоминания о легендарном страннике Чэне Буйном Портере. Чэнь передал секреты своего именного напитка наставнику Дрона, а тот — самому Дрону. Хотя для далеких от пивоварения людей это необычно, рецепт требует сырых, мощных компонентов прямо от свирепых зверей Степей."},{t="Сбор урожая саванны",b="Для крепкого напитка Чэня нужен необычный набор компонентов: почки кочевников равнин, бивни саванных львов и рог громового ящера. Добыча требует охоты на пыльных равнинах и доказывает, что лишь самые выносливые звери дают тот самый градус для настоящего пандаренского пивоварения. Когда все собрано, Дрон исполняется ностальгии и замечает, что возрождение старой формулы греет желудок почти так же, как его прежние партии троггской браги."}},faq={{q="Кто такой Пивовар Дрон?",a="Пивовар Дрон — орк-пивовар, живущий в портовом городе Кабестан. Он освоил искусство пивоварения у наставника, лично получившего рецепты от легендарного странника Чэня Буйного Портера.",al={"brewmaster drohn","who is drohn","drohn ratchet","пивовар дрон","кто такой дрон","дрон кабестан"}},{q="Почему для рецепта пива нужны звериные почки и рога?",a="Пандаренские традиции пивоварения — и приспособления грубых пограничных пивоваров — часто опираются на мощные, особые ингредиенты из местной фауны, придающие крепким напиткам бодрость, градус и особый природный вкус.",al={"why animal parts","plainstrider kidneys brew","lion tusks beer","зачем части животных","почки кочевников равнин пиво","бивни львов пиво"}},{q="Где найти нужные ингредиенты?",a="Все три компонента добываются из коренной фауны Степей. Кочевники равнин и саванные львы бродят по открытым степям, а громовых ящеров обычно можно найти пасущимися на более сухих или каменистых участках равнин.",al={"where to find tusks","where are thunder lizards","finding brew ingredients","где найти бивни","где громовые ящеры","поиск ингредиентов для пива"}},{q="Кем был Чэнь Буйный Портер?",a="Чэнь Буйный Портер — странствующий пандарен-пивовар, путешествовавший по Калимдору во время основания Дуротара. Он помогал Орде, разыскивая экзотические редкие ингредиенты, чтобы довести до совершенства свои крепкие сорта пива.",al={"who is chen","chen stormstout lore","chen","кто такой чэнь","чэнь буйный портер предания","чэнь"}},{q="Что происходит после того, как принести ингредиенты Дрону?",a="Бивни львов, почки кочевников равнин и рог громового ящера радуют Дрона, напоминают ему о прежних днях пивоварения и ведут прямо к заключительному этапу воссоздания легендарного напитка.",al={"next quest after chens empty keg","drohn reward","whats next","следующее задание после пустого бочонка чэня","награда дрона","что дальше"}},{q="Что за троггская брага, о которой говорит Дрон?",a="Увидев дикие ингредиенты, Дрон с теплотой вспоминает прежний напиток — троггскую брагу, что говорит о его эксцентричном прошлом: он выбраживал на границе резкие и необычные составы.",al={"trogg brew","drohn trogg brew","trogg beer","троггская брага","дрон троггская брага","троггское пиво"}}},fp="16,247,17.400.0,23.473.1,24.197.0,56.232.0,44.237.0,24.202.0,53.205.0,38.191.0"}
P.entries["quest:822"] = {n="Пустой бочонок Чэня",s="После создания мощного напитка «Буйный эль» Пивовар Дрон в Кабестане предлагает сварить еще один необычный рецепт, которому его научил неуловимый странствующий пандарен Чэнь Буйный Портер. Для этого крепкого варева, известного как троггово пиво, нужны редкие органы и железы местных зверей Степей.",h="После создания мощного напитка «Буйный эль» Пивовар Дрон в Кабестане предлагает сварить еще один необычный...",kw={"barrens","brewmaster drohn","chen stormstout","chen's empty keg","kodo liver","ratchet","stormhide","thunderhawk","trogg ale","степи","пивовар дрон","чэнь буйный портер","пустой бочонок чэня","печень кодо","кабестан","бурошкурый","громовой ястреб","троггово пиво"},ang={["faction:Horde"]="Чэнь Буйный Портер сражался бок о бок с Ордой при обороне Дуротара и произвел неизгладимое впечатление на орков вроде Дрона, встретивших его в те первые дни.",["profession:Cooking"]="Кулинарные пуристы могут морщиться при виде троггова пива, но использование жирных субпродуктов и сильнодействующих желез отражает походную кулинарную традицию: ничто в добыче не должно пропадать.",["race:Orc"]="Пивовар Дрон выбрал для орка необычное занятие: он предпочел экзотические методы варки Чэня традиционному пути воина, не покидая своего дела в Кабестане."},sec={{t="Вторая формула пандарена",b="После того как вы помогли Пивовару Дрону воспроизвести первый напиток легендарного Чэня Буйного Портера, орк-пивовар рассказывает, что странствующий пандарен поделился не одним секретом. Дрон знает рецепт необычного напитка — троггова пива. В отличие от обычных спиртных напитков, перегнанных из зерна, это своеобразное варево целиком основано на мощных органических реагентах, добытых у самых свирепых зверей центрального Калимдора."},{t="Ингредиенты троггова пива",b="Чтобы сварить этот резкий и бодрящий напиток, Дрону нужны громовые компоненты: молниевые железы бурошкурых кабанов, слюнная железа большого громового ястреба и крепкая печень кодо, бродящих по равнинам. После перегонки смесь дает сильнодействующий тонизирующий напиток, созданный для выживания в дикой природе."},{t="Прочное партнерство",b="Работа Дрона не ограничивается одной партией. Зная о спросе среди странствующих искателей приключений и наемников, проходящих через нейтральный порт Кабестан, Дрон не ставит срока: он готов варить свежее троггово пиво всякий раз, когда путешественник приносит новую партию звериных органов."}},faq={{q="Кто такой Чэнь Буйный Портер?",a="Чэнь Буйный Портер — неуловимый странствующий пандарен-пивовар, который путешествовал по Калимдору во время основания Дуротара. По пути он поделился несколькими своими мощными приемами варки с Дроном в Кабестане и отправился дальше в странствия.",al={"who is chen","chen lore","pandaren chen","кто такой чэнь","предания о чэне","пандарен чэнь"}},{q="Где находится Пивовар Дрон?",a="Пивовар Дрон живет в нейтральном портовом городе Кабестан на восточном побережье Степей. Он проводит дни, совершенствуя необычные напитки, рецепты которых узнал при встрече с Чэнем.",al={"drohn location","where is brewmaster drohn","drohn npc","где дрон","местонахождение дрона","где пивовар дрон","дрон персонаж"}},{q="Что такое троггово пиво?",a="Троггово пиво — необычный и крепкий напиток, рецепту которого Чэнь научил Дрона. Вместо обычного хмеля в него добавляют звериные железы и субпродукты, отчего он славится своей убойной силой и подходит выносливым искателям приключений.",al={"trogg ale","what is this drink","what does drohn brew","троггово пиво","что это за напиток","что варит дрон"}},{q="Где добыть молниевые железы?",a="Молниевые железы добывают у бурошкурых зверей, бродящих по засушливым просторам Степей: в их телах накапливаются природные электрические заряды.",al={"lightning gland source","stormhide location","where to get lightning gland","источник молниевых желез","где бурошкурые","где добыть молниевую железу"}},{q="С каких зверей падают слюнные железы громового ястреба?",a="Эти железы добывают только у больших громовых ястребов — величественных пернатых хищников, владеющих молниями и охотящихся в открытом небе над Степями.",al={"thunderhawk saliva gland","where are greater thunderhawks","thunderhawk location","слюнная железа громового ястреба","где большие громовые ястребы","где громовые ястребы"}},{q="Можно ли сварить троггово пиво более одного раза?",a="Да. Пивовар Дрон по-прежнему готов варить новые партии напитка, когда искатели приключений приносят ему свежие железы и печень кодо.",al={"is this repeatable","can i do this again","repeat trogg ale","можно ли повторить","можно сделать снова","повторить троггово пиво"}}},fp="16,301,25.422.0,28.339.0,23.303.1,23.246.0,34.193.0,18.215.0,37.154.0,43.158.0,36.146.0"}
P.entries["quest:823"] = {n="Явиться к Оргнилу",s="«Явиться к Оргнилу» — одно из первых заданий Орды, которое выдает Мастер Гадрин из Деревни Сен'джин. Оно отправляет начинающих искателей приключений на север, в Колючий Холм, чтобы предупредить Оргнила Душегрыза о коварном влиянии культа Пылающего Клинка. Это донесение помогает согласовать разрозненную оборону Дуротара от демонической скверны, зреющей прямо на родине орков.",h="«Явиться к Оргнилу» — одно из первых заданий Орды, которое выдает Мастер Гадрин из Деревни Сен'джин.",kw={"burning blade","durotar","master gadrin","orgnil soulscar","razor hill","report to orgnil","sen'jin village","пылающий клинок","дуротар","мастер гадрин","оргнил душегрыз","колючий холм","явиться к оргнилу","деревня сен'джин"},ang={["faction:Horde"]="Это задание отмечает важную связь и сотрудничество между недавно объединившимися троллями Черного Копья и орками Дуротара перед лицом общих угроз.",["race:Orc"]="Оргнил Душегрыз олицетворяет передовую оборону вашей новой родины, не давая демонической скверне укорениться в границах Дуротара.",["race:Troll"]="Хотя Черное Копье поглощено борьбой с Залазаном, Мастер Гадрин показывает преданность троллей Орде, предупреждая орочьих вождей об опасностях региона."},sec={{t="Согласованная оборона",b="Пока Деревня Сен'джин борется со своими бедами — прежде всего с предательством Залазана на Островах Эха, — Мастер Гадрин понимает, что сведения о культе Пылающего Клинка говорят о гораздо более широкой угрозе. В Долине Испытаний обнаружили слухи о демонической скверне, и знахарь Черного Копья знает, что с такими угрозами нельзя справляться поодиночке. Он отправляет странствующих героев на север по пыльной дороге в Колючий Холм, где местные орочьи власти наблюдают за Дуротаром шире."},{t="Оргнил Душегрыз",b="Оргнил Душегрыз, расквартированный в военном лагере Колючего Холма, — орк, которому поручено искоренять внутреннее зло и охранять центральные земли. Когда искатели приключений передают предупреждение Гадрина, Оргнил без промедления сопоставляет сведения из Долины Испытаний и Деревни Сен'джин. Понимая, что тень Пылающего Клинка нависла опасно близко, он быстро собирает силы, чтобы разгромить культистов, пока их темные ритуалы не погубили молодое государство."}},faq={{q="Кто выдает задание «Явиться к Оргнилу»?",a="Мастер Гадрин, знахарь Черного Копья и духовный лидер, живущий в Деревне Сен'джин, дает вам это поручение после того, как вы помогли троллям с их первыми местными бедами.",al={"who gives report to orgnil","where to get report to orgnil","quest giver report to orgnil","кто выдает явиться к оргнилу","где взять явиться к оргнилу","персонаж, выдающий задание явиться к оргнилу"}},{q="Где находится Оргнил Душегрыз?",a="Оргнил Душегрыз находится в Колючем Холме — укрепленном поселении к северу от Деревни Сен'джин в центральной части Дуротара.",al={"where is orgnil soulscar","orgnil soulscar location","find orgnil soulscar","где оргнил душегрыз","местонахождение оргнила душегрыза","найти оргнила душегрыза"}},{q="Почему Мастер Гадрин отправляет вас в Колючий Холм?",a="Мастер Гадрин понимает, что деятельность демонического культа, обнаруженная в Долине Испытаний и вокруг Дуротара, угрожает всем, а не только троллям. Он направляет вас к Оргнилу Душегрызу, орку, отвечающему за охрану региона от Пылающего Клинка.",al={"why report to orgnil","why go to razor hill","purpose of report to orgnil","зачем являться к оргнилу","зачем идти в колючий холм","цель задания явиться к оргнилу"}},{q="Что такое Пылающий Клинок, упомянутый в задании?",a="Пылающий Клинок — коварный культ поклонников демонов, действующий в тени Дуротара и за его пределами. Его скрытое присутствие в ближайших каньонах и пещерах угрожает безопасности и стабильности молодой Орды.",al={"who are the burning blade","burning blade cult","what is burning blade","кто такие пылающий клинок","культ пылающего клинка","что такое пылающий клинок"}},{q="Какое задание идет после «Явиться к Оргнилу»?",a="Когда вы сообщаете о донесении Оргнилу Душегрызу в Колючем Холме, он сразу выдает вам задание «Сгущаются черные тучи», чтобы расследовать растущую угрозу культистов и бороться с ней.",al={"next quest after report to orgnil","report to orgnil followup","what comes after report to orgnil","следующее задание после явиться к оргнилу","продолжение явиться к оргнилу","что после явиться к оргнилу"}},{q="Что нужно выполнить до получения этого задания?",a="Оно естественно следует за вашим прибытием в Деревню Сен'джин по заданию «Деревня Сен'джин», связывая первые открытия в Долине Испытаний с более широкой кампанией в Дуротаре.",al={"prereq report to orgnil","how to unlock report to orgnil","previous quest report to orgnil","предыдущее задание явиться к оргнилу","как открыть явиться к оргнилу","требования явиться к оргнилу"}}},fp="16,347,21.502.0,15.482.0,37.175.0,33.120.0,46.258.0,49.215.0,36.165.0,64.169.0"}
